window.SOP_DATA=[{"c":"SOP-PRO-001","g":"Program Kerja dan Kegiatan","t":"Penyusunan Rencana Kerja Tahunan","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Sekretaris Jenderal dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[6,9],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengumpulan usulan, penyusunan, pembahasan pada Rapat Kerja, persetujuan, dan sosialisasi rencana kerja tahunan kabinet, sehingga seluruh program memiliki tujuan, penanggung jawab, waktu, anggaran, dan indikator capaian yang jelas serta selaras dengan AD/ART dan peraturan kampus."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk BPH, Eksekutif (Menteri dan Kabiro), Inspektur Jenderal, dan seluruh pengurus BEM Kabinet Samasta dalam penyusunan program kerja tahunan pada awal periode. SOP ini tidak mengatur program baru di luar rencana kerja (lihat SOP-PRO-003), penyusunan kalender (lihat SOP-PRO-002), dan rincian anggaran per kegiatan (lihat SOP-KEU-002)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 9 ayat (1) sampai (6) (Rapat Kerja: pelaksana, agenda, pengambilan keputusan, dan persetujuan Pembina).","ART Bab III (Tugas) Pasal 3 huruf b dan e (merancang program kerja; menyusun anggaran dan program kerja tahunan dengan persetujuan BPM).","ART Pasal 4 (Wewenang BEM) huruf a (kebijakan pelaksanaan kegiatan kemahasiswaan).","AD Pasal 5 dan Pasal 6 (fungsi dan tujuan BEM).","AD Pasal 15 ayat (4) (penyusunan anggaran mengikuti waktu pengumpulan anggaran kampus dengan persetujuan KAUR ORMAWA)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rencana Kerja Tahunan (RKT)","Dokumen daftar program kerja satu periode beserta tujuan, sasaran, penanggung jawab, jadwal, perkiraan anggaran, dan indikator capaian."],["Rapat Kerja (RAKER)","Forum perencanaan program kerja tahunan yang dilaksanakan BPH dan Eksekutif pada awal periode (ART Pasal 9)."],["Indikator capaian","Ukuran yang dapat diperiksa untuk menilai keberhasilan sebuah program."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["RAKER dilaksanakan BPH dan Eksekutif pada awal periode; agendanya mencakup penyusunan dan pengesahan program kerja tahunan, pembagian tugas, timeline, anggaran biaya, dan target capaian (ART Pasal 9 ayat 2 dan 3).","Keputusan RAKER diambil secara mufakat atau pemungutan suara bila diperlukan; hasilnya menjadi pedoman satu periode (ART Pasal 9 ayat 4 dan 5).","Setiap program dalam RKT memuat: nama, tujuan, sasaran, penanggung jawab, kategori awal (lihat SOP-PRO-004), waktu, perkiraan anggaran, dan indikator capaian.","Seluruh program harus sesuai fungsi dan tujuan BEM serta manhaj Ahlusunah wal Jamaah (AD Pasal 5 ayat 3).","RKT belum berlaku sebelum disetujui BPM (anggaran dan program kerja tahunan) dan Pembina (ART Pasal 9 ayat 6); anggaran mengikuti jadwal kampus dengan persetujuan KAUR ORMAWA.","Program yang tidak tercantum dalam RKT hanya dapat dijalankan melalui SOP-PRO-003."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Bertanggung jawab akhir atas RKT dan menetapkannya melalui Keputusan Presiden."],["Wakil Presiden","R","Memimpin konsolidasi usulan, menghapus tumpang tindih, dan menyiapkan RAKER."],["Sekretaris Jenderal","R","Mengumpulkan bahan, menyusun draf RKT, mencatat RAKER, dan mengarsipkan."],["Menteri / Kabiro","R","Mengusulkan program unit beserta tujuan, jadwal, biaya, dan indikator."],["Biro Keuangan","C","Memberi masukan kelayakan anggaran dan menyusun draf anggaran gabungan."],["Inspektur Jenderal","C","Memeriksa keselarasan draf dengan AD/ART dan peraturan kampus."],["BPM, KAUR ORMAWA, Pembina","C","Memberi persetujuan sesuai kewenangan masing-masing."],["Seluruh pengurus","I","Memahami dan menjalankan RKT yang berlaku."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["AD/ART dan peraturan kampus.","Visi dan misi kabinet serta kalender akademik kampus.","Laporan akhir dan daftar program belum selesai dari kabinet sebelumnya.","Lembar Usulan Program Tahunan dari setiap unit.","Informasi plafon dan jadwal pengumpulan anggaran kampus."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengumpulan bahan: Mengumpulkan AD/ART, kalender akademik, arsip kabinet sebelumnya, dan jadwal anggaran kampus.","Sekjen","AD/ART, arsip, kalender kampus","Paket bahan RAKER","3 hari kerja setelah struktur ditetapkan"],["2","Usulan program unit: Mengisi Lembar Usulan Program Tahunan: tujuan, sasaran, jadwal, perkiraan biaya, penanggung jawab, indikator.","Menteri / Kabiro","Paket bahan","Usulan tertulis tiap unit","5 hari kerja"],["3","Konsolidasi draf: Menggabungkan usulan, menghapus tumpang tindih, menyusun draf RKT dan draf anggaran gabungan.","Wapres, Sekjen, Biro Keuangan","Usulan unit","Draf RKT dan anggaran","3 hari kerja"],["4","Pemeriksaan keselarasan: Memeriksa draf dengan Checklist Keselarasan; memberi catatan tertulis bila bertentangan dengan AD/ART atau aturan kampus.","Irjen","Draf, checklist","Catatan pemeriksaan","2 hari kerja"],["5","Pelaksanaan RAKER: Membahas lima agenda RAKER; keputusan secara mufakat atau pemungutan suara (SOP-GOV-002); membuat notulen.","BPH dan Eksekutif","Draf, catatan Irjen","Keputusan RAKER dan notulen","1 kali rapat; notulen 2 hari kerja"],["6","Finalisasi: Merevisi draf sesuai hasil RAKER dan menyiapkan berkas permohonan persetujuan.","Sekjen, Wapres","Hasil RAKER","RKT final dan berkas persetujuan","3 hari kerja"],["7","Persetujuan eksternal: Menyampaikan anggaran dan program kepada BPM; anggaran kepada KAUR ORMAWA sesuai jadwal kampus; program kepada Pembina; merevisi bila ada catatan.","Presiden, Sekjen","RKT final","Bukti persetujuan","Sesuai jadwal kampus; target 10 hari kerja"],["8","Penetapan dan sosialisasi: Menetapkan RKT melalui Keputusan Presiden, mensosialisasikan, memasukkan ke kalender (SOP-PRO- 002) dan Register Dokumen.","Presiden, Sekjen","Bukti persetujuan","Keputusan Presiden dan RKT tersosialisasi","3 hari kerja setelah persetujuan"],["9","Peninjauan berkala: Meninjau RKT pada evaluasi tengah periode atau saat ada perubahan aturan, struktur, atau anggaran.","Wapres, Irjen","Hasil evaluasi","RKT revisi atau penegasan","Setiap ada pemicu"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"RKT ditargetkan disetujui dan ditetapkan paling lambat 30 hari kerja sejak struktur kabinet ditetapkan, dengan menyesuaikan jadwal pengumpulan anggaran kampus. Hasil akhir: Keputusan Presiden tentang RKT beserta lampiran anggaran."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Tumpang tindih program antarunit diputuskan Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","RAKER tidak memenuhi kuorum: dijadwalkan ulang sesuai SOP-GOV-006.","BPM, KAUR ORMAWA, atau Pembina memberi catatan atau menolak: draf direvisi dan diajukan kembali; program yang belum disetujui tidak dilaksanakan.","Anggaran melebihi plafon kampus: Biro Keuangan menyusun prioritas dan opsi pengurangan untuk diputuskan pimpinan.","Kebutuhan mengubah AD/ART tidak diputuskan melalui SOP ini; ikuti AD Bab XI dan ART Bab VII."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% program dalam RKT memiliki penanggung jawab, jadwal, anggaran, dan indikator.","RKT disetujui sebelum kegiatan pertama dilaksanakan.","Tidak ada temuan pertentangan dengan AD/ART pada pemeriksaan Irjen.","RKT tersosialisasi paling lambat 3 hari kerja setelah penetapan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Keputusan Presiden tentang Rencana Kerja Tahunan.","RKT beserta lampiran anggaran.","Notulen dan keputusan RAKER.","Catatan pemeriksaan Irjen.","Bukti persetujuan BPM, KAUR ORMAWA, dan Pembina.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kesesuaian RKT dengan kalender setiap bulan; Irjen menilai kepatuhan pelaksanaan RKT pada evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengumpulan bahan → Usulan unit → Konsolidasi draf → Periksa Irjen → RAKER → Persetujuan BPM, KAUR, Pembina → Penetapan Presiden → Sosialisasi dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Usulan Program Tahunan","Nama program; unit; tujuan; sasaran; waktu; perkiraan biaya; penanggung jawab; indikator capaian."],["Templat Rencana Kerja Tahunan","Daftar program; kategori awal; jadwal; anggaran; penanggung jawab; indikator."],["Lembar Persetujuan RKT","Pihak penyetuju; tanggal; keputusan; catatan; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh unit telah menyampaikan Lembar Usulan Program Tahunan.","☐ Ya ☐ Tidak"],["2","Setiap program memiliki penanggung jawab, jadwal, anggaran, dan indikator.","☐ Ya ☐ Tidak"],["3","Tidak ada program yang bertentangan dengan AD/ART, ART Pasal 11, dan aturan kampus.","☐ Ya ☐ Tidak"],["4","RKT telah dibahas pada RAKER dan dicatat dalam notulen.","☐ Ya ☐ Tidak"],["5","Persetujuan BPM, KAUR ORMAWA, dan Pembina telah diperoleh.","☐ Ya ☐ Tidak"],["6","RKT tercatat pada Register Dokumen dan kalender.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-002","g":"Program Kerja dan Kegiatan","t":"Penyusunan Kalender Program Kerja Kabinet","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[10,13],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan, pengesahan, dan pembaruan kalender program kerja kabinet agar jadwal seluruh unit selaras dengan kalender akademik, tidak berbenturan, dan dapat dipantau pimpinan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh Menteri, Kabiro, dan panitia yang memiliki jadwal kegiatan dalam RKT. SOP ini mengatur kalender program kerja; pengelolaan kalender organisasi secara umum diatur pada SOP-ADM-018 dan perubahan jadwal kegiatan diatur pada SOP-PRO-015."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Bab III (Tugas) Pasal 3 huruf f (mengoordinasikan seluruh kegiatan kemahasiswaan).","ART Pasal 9 ayat (3) huruf c (penetapan timeline kegiatan pada RAKER).","ART Pasal 10 ayat (4) huruf a (koordinasi kegiatan mendatang pada Rapat Koordinasi).","SOP-PRO-001 (Rencana Kerja Tahunan) dan kalender akademik kampus."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kalender program kerja","Daftar jadwal seluruh program dan kegiatan kabinet dalam satu periode."],["Benturan jadwal","Dua kegiatan atau lebih yang memakai waktu, tempat, atau sumber daya yang sama, atau bertabrakan dengan agenda akademik dan agenda kampus."],["Penguncian jadwal","Penetapan tanggal kegiatan yang hanya dapat diubah melalui SOP-PRO-015."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kalender disusun dari RKT yang telah disetujui, kalender akademik, agenda kampus, hari besar Islam, dan agenda HIMA serta UKM yang diketahui.","Jadwal kegiatan menghormati waktu salat fardu dan salat Jumat serta tidak ditempatkan pada masa ujian kecuali dengan persetujuan Wakil Presiden.","Kegiatan Kategori B dan C dimasukkan ke kalender paling lambat 30 hari sebelum pelaksanaan (usulan).","Dua kegiatan Kategori B atau C pada hari yang sama hanya dengan persetujuan Wakil Presiden.","Kalender resmi hanya satu versi yang disimpan di repositori BEM dan disebarkan melalui kanal resmi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Mengesahkan kalender program kerja kabinet."],["Wakil Presiden","R","Menyelesaikan benturan jadwal dan menyetujui pengecualian."],["Sekretaris Jenderal","R","Menyusun, memperbarui, menyebarkan, dan mengarsipkan kalender."],["Menteri / Kabiro","R","Menyampaikan jadwal unit dan pembaruannya tepat waktu."],["Kementerian Harmonisasi Kampus","C","Memberi data agenda kampus, HIMA, UKM, dan pihak internal lainnya."],["Seluruh pengurus","I","Mengikuti kalender yang berlaku."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["RKT yang telah ditetapkan.","Kalender akademik dan agenda kampus.","Jadwal usulan dari tiap unit.","Data agenda HIMA dan UKM."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengumpulan jadwal: Meminta jadwal rinci dari tiap unit dan data agenda kampus, HIMA, serta UKM.","Sekjen","RKT, kalender kampus","Daftar jadwal unit","3 hari kerja setelah RKT ditetapkan"],["2","Penyusunan draf: Memetakan seluruh kegiatan pada kalender bulanan dan menandai benturan.","Sekjen","Daftar jadwal","Draf kalender dan daftar benturan","3 hari kerja"],["3","Penyelesaian benturan: Membahas benturan pada Rapat Koordinasi dan memutuskan penyesuaian jadwal.","Wapres dan Eksekutif","Draf, daftar benturan","Jadwal tanpa benturan","1 kali rapat"],["4","Pengesahan: Menetapkan kalender program kerja kabinet.","Presiden","Draf final","Kalender sah","2 hari kerja"],["5","Penyebaran: Mengunggah kalender ke repositori dan menyebarkannya melalui kanal resmi.","Sekjen","Kalender sah","Kalender tersebar","1 hari kerja"],["6","Pembaruan: Memperbarui kalender hanya berdasarkan keputusan perubahan yang sah (SOP-PRO-015, SOP-PRO- 022) dan mencatat versi.","Sekjen","Keputusan perubahan","Kalender versi terbaru","1 hari kerja setelah keputusan"],["7","Pemantauan bulanan: Memeriksa kalender terhadap realisasi dan melaporkan penyimpangan.","Sekjen","Kalender, laporan unit","Catatan pemantauan","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Kalender ditargetkan disahkan paling lambat 10 hari kerja setelah RKT ditetapkan. Hasil akhir: kalender program kerja kabinet yang sah dan dapat diakses seluruh pengurus."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Benturan yang tidak selesai pada Rapat Koordinasi diputuskan Wakil Presiden; bila perlu dibawa ke Rapat Pimpinan (SOP-GOV-005).","Unit terlambat menyampaikan jadwal: dicatat dan ditindaklanjuti sesuai SOP-MONEV-008.","Perubahan jadwal setelah penguncian: ikuti SOP-PRO-015.","Agenda kampus mendadak yang membatalkan kegiatan: ikuti SOP-PRO-022."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Tidak ada benturan jadwal yang tidak terselesaikan pada kegiatan Kategori B dan C.","Kalender tersedia hanya dalam satu versi resmi.","100% kegiatan Kategori B dan C masuk kalender sebelum 30 hari pelaksanaan.","Pembaruan kalender dilakukan paling lambat 1 hari kerja setelah keputusan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Kalender program kerja kabinet.","Daftar benturan dan hasil penyelesaiannya.","Riwayat versi kalender.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kesesuaian kalender dengan realisasi kegiatan setiap bulan; Wakil Presiden meninjau benturan berulang pada Rapat Koordinasi."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kumpulkan jadwal → Susun draf → Selesaikan benturan → Pengesahan Presiden → Sebarkan → Perbarui dan pantau → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Kalender Program Kerja","Bulan; tanggal; program; unit; tempat; kategori; penanggung jawab; status."],["Daftar Benturan Jadwal","Kegiatan terkait; jenis benturan; usulan penyelesaian; keputusan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh program RKT telah masuk kalender.","☐ Ya ☐ Tidak"],["2","Tidak ada benturan dengan kalender akademik dan agenda kampus.","☐ Ya ☐ Tidak"],["3","Waktu salat dan masa ujian telah dipertimbangkan.","☐ Ya ☐ Tidak"],["4","Kalender disahkan Presiden dan hanya satu versi beredar.","☐ Ya ☐ Tidak"],["5","Pembaruan dicatat pada riwayat versi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-003","g":"Program Kerja dan Kegiatan","t":"Pengajuan Program Kerja Baru","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Sekretaris Jenderal dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[14,17],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengajuan program kerja di luar RKT agar program tambahan memiliki alasan, sumber dana, dan penanggung jawab yang jelas serta tidak mengganggu program yang telah disetujui."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pengurus BEM yang mengusulkan program kerja baru, termasuk kegiatan insidental, respons atas kebutuhan mendesak, dan tawaran kolaborasi. Program yang sudah ada dalam RKT tidak memerlukan SOP ini. Pembatalan atau penundaan diatur pada SOP-PRO-022."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 (Wewenang BEM) huruf a dan c (kebijakan pelaksanaan kegiatan; pembentukan panitia).","ART Pasal 9 ayat (5) dan (6) (RKT sebagai pedoman; persetujuan Pembina).","AD Pasal 5 (fungsi dan tujuan) dan AD Pasal 15 (keuangan).","SOP-PRO-001, SOP-PRO-004, dan SOP-PRO-005."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Program kerja baru","Program yang tidak tercantum dalam RKT yang telah ditetapkan."],["Lembar Usulan Program","Formulir yang memuat alasan, tujuan, sasaran, sumber dana, jadwal, dan penanggung jawab usulan."],["Pengusul","Menteri, Kabiro, atau pengurus yang mengajukan program dengan rekomendasi pimpinan unit."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pengusul adalah Menteri atau Kabiro; pengurus lain mengajukan melalui pimpinan unitnya.","Usulan wajib menyebut kesesuaiannya dengan AD/ART, fungsi BEM, dan RKT, serta alasan program tidak masuk RKT.","Sumber dana wajib jelas dan halal (AD Pasal 15 ayat 2); program tanpa sumber dana tidak diproses.","Program baru tidak boleh menggeser program RKT tanpa persetujuan Presiden; bila mengubah anggaran atau program kerja yang telah disetujui BPM atau Pembina, perubahan dilaporkan kepada pihak tersebut.","Usulan kolaborasi dengan HIMA, UKM, atau pihak eksternal diajukan melalui Kementerian Harmonisasi Kampus atau Kementerian Hubungan Eksternal."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pengusul (Menteri / Kabiro)","R","Mengisi Lembar Usulan Program secara lengkap dan jujur."],["Sekretaris Jenderal","R","Meregistrasi usulan dan memeriksa kelengkapan administrasi."],["Wakil Presiden","R","Mengoordinasikan telaah kelayakan dan menyampaikan hasilnya kepada Presiden."],["Presiden","A","Memutuskan usulan sesuai SOP-PRO-005."],["Biro Keuangan","C","Memberi masukan ketersediaan dana."],["Inspektur Jenderal","C","Memeriksa kesesuaian usulan dengan AD/ART bila ada indikasi pertentangan."],["Seluruh pengurus","I","Mengetahui keputusan atas usulan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["RKT dan kalender yang berlaku.","Lembar Usulan Program.","Rekomendasi pimpinan unit.","Informasi ketersediaan dana."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan usulan: Mengisi Lembar Usulan Program: alasan, tujuan, sasaran, kesesuaian RKT, kategori awal, perkiraan biaya dan sumber dana, jadwal, penanggung jawab.","Pengusul","Kebutuhan program","Lembar Usulan Program","Sesuai kebutuhan; minimal 30 hari sebelum pelaksanaan"],["2","Registrasi dan pemeriksaan awal: Mencatat usulan dan memeriksa kelengkapan; mengembalikan bila kurang.","Sekjen","Lembar Usulan","Usulan tercatat atau dikembalikan","1 hari kerja"],["3","Konfirmasi dana: Memberi masukan ketersediaan dan sumber dana.","Biro Keuangan","Usulan tercatat","Catatan dana","2 hari kerja"],["4","Telaah kelayakan: Melaksanakan telaah sesuai SOP- PRO-004.","Wapres, Irjen","Usulan, catatan dana","Lembar Telaah Kelayakan","Sesuai SOP-PRO- 004"],["5","Keputusan: Memutuskan usulan sesuai SOP-PRO- 005: disetujui, disetujui bersyarat, ditunda, atau ditolak dengan alasan.","Presiden","Hasil telaah","Keputusan atas usulan","Sesuai SOP-PRO- 005"],["6","Pemberitahuan dan pencatatan: Memberi tahu pengusul, memperbarui RKT dan kalender, serta mencatat pada Register Program.","Sekjen","Keputusan","Pengusul diberi tahu; register dan kalender diperbarui","2 hari kerja setelah keputusan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari pengajuan hingga keputusan ditargetkan paling lambat 10 hari kerja sejak usulan lengkap. Hasil akhir: keputusan tertulis atas usulan program baru."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Usulan mendesak yang tidak dapat menunggu: ikuti SOP-GOV-012 (keputusan mendesak) dan ratifikasi pada rapat terdekat.","Perbedaan pendapat atas kelayakan: diputuskan Presiden melalui SOP-GOV-002.","Program mengubah program atau anggaran yang telah disetujui BPM atau Pembina: ajukan perubahan kepada pihak tersebut sebelum pelaksanaan.","Pengusul merasa keberatan atas penolakan: dapat mengajukan ulang dengan perbaikan pada Rapat Koordinasi."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% program baru memiliki keputusan tertulis sebelum dilaksanakan.","Tidak ada program baru berjalan tanpa sumber dana yang jelas.","Waktu keputusan tidak melebihi 10 hari kerja pada 90% usulan.","RKT, kalender, dan Register Program diperbarui paling lambat 2 hari kerja setelah keputusan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Usulan Program.","Lembar Telaah Kelayakan.","Keputusan atas usulan.","Register Program yang diperbarui.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan Register Program setiap bulan; Irjen menilai kepatuhan prosedur pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengajuan usulan → Registrasi → Konfirmasi dana → Telaah kelayakan → Keputusan Presiden → Pemberitahuan dan pencatatan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Usulan Program","Nama program; pengusul; alasan; tujuan; sasaran; kesesuaian RKT dan AD/ART; kategori awal; biaya dan sumber dana; jadwal; penanggung jawab; tanggal."],["Register Program","Nomor; nama program; pengusul; status; keputusan; tanggal; penanggung jawab."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Usulan memuat alasan program tidak masuk RKT.","☐ Ya ☐ Tidak"],["2","Kesesuaian dengan AD/ART dan fungsi BEM dinyatakan.","☐ Ya ☐ Tidak"],["3","Sumber dana jelas dan halal.","☐ Ya ☐ Tidak"],["4","Tidak ada program RKT yang tergeser tanpa persetujuan Presiden.","☐ Ya ☐ Tidak"],["5","Keputusan tertulis telah diterbitkan dan pengusul diberi tahu.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-004","g":"Program Kerja dan Kegiatan","t":"Pemeriksaan Kelayakan dan Kesesuaian Program","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[18,21],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur telaah kelayakan dan kesesuaian program terhadap AD/ART, peraturan kampus, ketentuan syariat, anggaran, jadwal, kapasitas, dan risiko, serta menetapkan kategori kegiatan sebagai dasar tingkat persetujuan dan pengendalian."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk setiap program dan kegiatan yang akan dijalankan, baik dari RKT maupun usulan baru (SOP- PRO-003). SOP ini tidak memutuskan program (lihat SOP-PRO-005) dan tidak menggantikan penilaian risiko rinci (lihat SOP-RSK-002)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 5 dan Pasal 6 (fungsi, tujuan, dan manhaj Ahlusunah wal Jamaah).","AD Pasal 15 ayat (2) (sumber dana terhindar dari riba, gharar, dan maysir).","ART Pasal 11 (larangan), khususnya huruf a, c, e, f, h, dan k.","ART Pasal 2 huruf e dan j (kerja sama eksternal dan kegiatan di luar kampus memerlukan persetujuan atau izin kampus).","ART Pasal 3 (Kewajiban) huruf a, d, dan h."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Telaah kelayakan","Pemeriksaan tertulis atas tujuh aspek untuk menilai layak atau tidaknya program dijalankan."],["Kategori kegiatan","Pengelompokan A, B, atau C berdasarkan lingkup, pihak yang terlibat, tempat, dan risiko."],["Layak bersyarat","Program dapat dijalankan setelah syarat tertulis dipenuhi pada batas waktu yang ditetapkan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Tujuh aspek telaah: (1) kesesuaian dengan AD/ART dan fungsi BEM serta manhaj; (2) kesesuaian dengan RKT dan prioritas; (3) tidak melanggar larangan ART Pasal 11; (4) kelayakan anggaran dan sumber dana halal; (5) kelayakan jadwal terhadap kalender; (6) kapasitas sumber daya manusia dan perlengkapan; (7) risiko dan perizinan.","Kategori A: kegiatan internal pengurus BEM di dalam kampus, tanpa pihak eksternal, dengan biaya kecil di bawah batas yang ditetapkan Presiden bersama Biro Keuangan.","Kategori B: kegiatan di dalam kampus yang melibatkan mahasiswa atau ormawa lain, narasumber atau mitra dari luar BEM, atau biaya menengah.","Kategori C: kegiatan di luar kampus, menginap, melibatkan publik atau instansi eksternal, kerja sama atau sponsor, atau berisiko tinggi.","Tingkat persetujuan: Kategori A disetujui Presiden; Kategori B disetujui Presiden dengan pemberitahuan kepada KAUR ORMAWA; Kategori C disetujui Presiden dengan persetujuan atau izin KAUR ORMAWA, Pembina, atau Ketua STDIIS sesuai ketentuan kampus.","Batas nilai biaya tiap kategori adalah usulan dan ditetapkan final setelah uji coba."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Wakil Presiden","A","Bertanggung jawab akhir atas telaah; memimpin telaah, menetapkan kategori, dan menyampaikan rekomendasi kepada Presiden."],["Sekretaris Jenderal","R","Menyiapkan Lembar Telaah Kelayakan dan memeriksa aspek administrasi serta jadwal."],["Biro Keuangan","R","Menelaah aspek anggaran dan sumber dana."],["Inspektur Jenderal","R","Memeriksa kesesuaian program terhadap AD/ART dan aturan kampus serta mencatat temuan."],["Penanggung jawab program","C","Memberi penjelasan dan melengkapi data."],["Presiden","I","Menerima hasil telaah sebagai dasar keputusan (SOP-PRO-005)."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Lembar Usulan Program atau entri RKT.","Catatan ketersediaan dana.","Kalender program kerja.","AD/ART dan peraturan kampus."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan berkas: Menerima dan memeriksa kelengkapan berkas telaah.","Sekjen","Usulan, catatan dana","Berkas lengkap","1 hari kerja"],["2","Telaah administrasi dan jadwal: Memeriksa kesesuaian RKT, kalender, dan beban unit.","Sekjen","Berkas, kalender","Catatan jadwal dan administrasi","1 hari kerja"],["3","Telaah anggaran: Memeriksa kewajaran biaya, sumber dana halal, dan pemisahan fungsi.","Biro Keuangan","Berkas","Catatan anggaran","2 hari kerja"],["4","Pemeriksaan kesesuaian aturan: Memeriksa kesesuaian dengan AD/ART, ART Pasal 11, manhaj, dan aturan kampus; menandai syarat izin eksternal.","Irjen","Berkas, checklist","Catatan keselarasan","2 hari kerja"],["5","Penetapan kategori dan simpulan: Menetapkan kategori A, B, atau C dan simpulan: layak, layak bersyarat, atau tidak layak.","Wapres","Seluruh catatan","Lembar Telaah Kelayakan","1 hari kerja"],["6","Penyampaian hasil: Menyampaikan hasil kepada Presiden dan penanggung jawab program.","Sekjen","Lembar Telaah","Hasil tersampaikan dan tercatat","1 hari kerja"],["7","Pemantauan syarat: Memantau pemenuhan syarat pada program layak bersyarat.","Sekjen, Irjen","Lembar Telaah","Syarat terpenuhi atau dilaporkan","Sesuai batas syarat"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Telaah ditargetkan selesai paling lambat 5 hari kerja sejak berkas lengkap; telaah gabungan tidak melebihi 7 hari kerja. Hasil akhir: Lembar Telaah Kelayakan beserta kategori kegiatan."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Perbedaan penilaian antaraspek: diputuskan Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Temuan pertentangan dengan AD/ART atau aturan kampus: program wajib diubah atau tidak dilanjutkan; bila perlu penafsiran, dikonsultasikan kepada KAUR ORMAWA atau Pembina.","Program berisiko tinggi: dilengkapi penilaian risiko sesuai SOP-RSK-002.","Dugaan pelanggaran larangan ART Pasal 11: ikuti ART Pasal 12 dan 13."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% program memiliki Lembar Telaah Kelayakan sebelum persetujuan.","Tidak ada program Kategori C berjalan tanpa izin kampus yang disyaratkan.","Telaah selesai dalam batas waktu pada 90% program.","Jumlah program dikembalikan karena telaah tidak lengkap menurun tiap triwulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Telaah Kelayakan.","Penetapan kategori kegiatan.","Catatan pemeriksaan Irjen.","Daftar syarat dan status pemenuhannya.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan Lembar Telaah setiap bulan; Irjen menilai ketepatan kategori pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima berkas → Telaah jadwal dan administrasi → Telaah anggaran → Periksa aturan Irjen → Tetapkan kategori dan simpulan → Sampaikan hasil → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Telaah Kelayakan","Nama program; tujuh aspek telaah dan hasilnya; kategori kegiatan; simpulan; syarat; pemeriksa; tanggal."],["Checklist Keselarasan AD/ART","Butir kesesuaian AD/ART, ART Pasal 11, aturan kampus, dan manhaj; temuan; tindak lanjut."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Tujuh aspek telaah telah diperiksa dan dicatat.","☐ Ya ☐ Tidak"],["2","Kategori kegiatan telah ditetapkan.","☐ Ya ☐ Tidak"],["3","Tidak ada pertentangan dengan AD/ART, ART Pasal 11, dan aturan kampus.","☐ Ya ☐ Tidak"],["4","Sumber dana halal dan bebas riba, gharar, dan maysir.","☐ Ya ☐ Tidak"],["5","Izin atau persetujuan kampus yang disyaratkan telah ditandai.","☐ Ya ☐ Tidak"],["6","Hasil telaah telah disampaikan kepada Presiden dan penanggung jawab.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-005","g":"Program Kerja dan Kegiatan","t":"Persetujuan Program dan Penunjukan Penanggung Jawab","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[22,25],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur persetujuan program, penetapan kategori dan syarat pelaksanaan, serta penunjukan penanggung jawab program agar setiap program berjalan dengan kewenangan dan tanggung jawab yang jelas."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk program dari RKT yang akan diaktifkan dan program baru yang telah ditelaah pada SOP-PRO- 004. SOP ini tidak mengatur pembentukan panitia (lihat SOP-PRO-006) dan tidak mengatur penundaan atau pembatalan (lihat SOP-PRO-022)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 (Wewenang BEM) huruf a, b, dan f (kebijakan, pengangkatan pengurus internal, penandatanganan dokumen).","AD Pasal 11 ayat (2) huruf b (kewenangan prerogatif Presiden atas Menteri dan Kabiro).","ART Pasal 9 ayat (6) (persetujuan Pembina atas program kerja).","SOP-GOV-002 (Pengambilan Keputusan) dan SOP-GOV-008 (Pendelegasian Wewenang)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Penanggung jawab program","Menteri atau Kabiro yang bertanggung jawab atas keberhasilan, anggaran, dan pelaporan program."],["Persetujuan bersyarat","Persetujuan yang berlaku setelah syarat tertulis dipenuhi."],["Keputusan Presiden","Dokumen resmi penetapan program, kategori, syarat, dan penanggung jawab."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Presiden memutuskan berdasarkan Lembar Telaah Kelayakan; keputusan diambil sesuai SOP-GOV- 002.","Program RKT yang telah disetujui Pembina diaktifkan oleh Presiden; Kategori B dan C tetap mengikuti tingkat persetujuan pada SOP-PRO-004.","Penanggung jawab program adalah Menteri atau Kabiro unit pemilik program; penunjukan lain hanya dengan alasan tertulis.","Satu penanggung jawab tidak memegang lebih dari dua program Kategori B atau C yang berjalan bersamaan (usulan).","Program belum boleh dijalankan, dipublikasikan, atau dibiayai sebelum Keputusan Presiden terbit dan persetujuan pihak luar yang disyaratkan diperoleh."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Memutuskan program, kategori, syarat, dan penanggung jawab; menandatangani keputusan."],["Wakil Presiden","R","Menyampaikan hasil telaah dan rekomendasi serta memantau pemenuhan syarat."],["Sekretaris Jenderal","R","Menyiapkan draf keputusan, mencatat, dan mengarsipkan."],["Penanggung jawab program","R","Menerima penunjukan dan memenuhi syarat yang ditetapkan."],["Inspektur Jenderal","C","Memastikan keputusan tidak bertentangan dengan AD/ART."],["KAUR ORMAWA / Pembina","C","Memberi persetujuan atau izin untuk Kategori B dan C sesuai ketentuan kampus."],["Seluruh pengurus","I","Mengetahui program yang telah disetujui."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Lembar Telaah Kelayakan.","Lembar Usulan Program atau entri RKT.","Bukti persetujuan atau izin kampus bila disyaratkan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyampaian hasil telaah: Menyampaikan Lembar Telaah beserta rekomendasi kepada Presiden.","Wapres","Lembar Telaah","Bahan keputusan","1 hari kerja"],["2","Permohonan persetujuan kampus: Untuk Kategori B dan C, mengajukan pemberitahuan atau permohonan persetujuan kepada KAUR ORMAWA, Pembina, atau Ketua STDIIS.","Presiden, Sekjen","Lembar Telaah, surat","Persetujuan atau izin kampus","Sesuai jadwal kampus"],["3","Pembahasan keputusan: Membahas hasil telaah pada rapat pimpinan atau kabinet bila perlu (SOP-GOV-002).","Presiden, Wapres","Bahan keputusan","Keputusan atas program","2 hari kerja"],["4","Penyusunan draf keputusan: Menyusun draf Keputusan Presiden: program, kategori, syarat, penanggung jawab, dan batas waktu persiapan.","Sekjen","Keputusan rapat","Draf Keputusan Presiden","1 hari kerja"],["5","Pengesahan: Menetapkan dan menandatangani Keputusan Presiden.","Presiden","Draf keputusan","Keputusan Presiden","1 hari kerja"],["6","Pemberitahuan dan pencatatan: Menyampaikan keputusan kepada penanggung jawab dan unit terkait; memperbarui Register Program dan kalender.","Sekjen","Keputusan Presiden","Keputusan tersosialisasi","1 hari kerja"],["7","Pemantauan syarat: Memantau pemenuhan syarat pada persetujuan bersyarat.","Wapres","Keputusan, laporan","Status syarat","Sesuai batas syarat"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Keputusan ditargetkan terbit paling lambat 7 hari kerja setelah hasil telaah diterima, di luar waktu persetujuan pihak kampus. Hasil akhir: Keputusan Presiden tentang program dan penanggung jawab."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Persetujuan kampus belum diperoleh: program tidak dilaksanakan; jadwal disesuaikan melalui SOP- PRO-015.","Keputusan mendesak yang tidak dapat menunggu rapat: ikuti SOP-GOV-012.","Presiden berhalangan: ikuti SOP-GOV-008 dan SOP-GOV-009.","Penanggung jawab tidak sanggup menjalankan: Presiden menunjuk pengganti dengan alasan tertulis."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% program berjalan dengan Keputusan Presiden yang sah.","Tidak ada program Kategori B atau C berjalan tanpa persetujuan atau izin kampus yang disyaratkan.","Keputusan terbit dalam batas waktu pada 90% program.","Register Program dan kalender diperbarui paling lambat 1 hari kerja setelah keputusan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Keputusan Presiden tentang program dan penanggung jawab.","Bukti persetujuan atau izin kampus.","Register Program yang diperbarui.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kesesuaian keputusan dengan Register Program setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Hasil telaah → Permohonan persetujuan kampus → Pembahasan → Draf keputusan → Pengesahan Presiden → Pemberitahuan dan pencatatan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Keputusan Presiden tentang Program","Nomor; dasar; program; kategori; syarat; penanggung jawab; batas persiapan; tanggal; tanda tangan."],["Surat Permohonan Persetujuan Kegiatan","Tujuan; waktu; tempat; peserta; anggaran; penanggung jawab; lampiran telaah."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Lembar Telaah Kelayakan tersedia dan simpulannya layak atau layak bersyarat.","☐ Ya ☐ Tidak"],["2","Kategori dan tingkat persetujuan telah ditetapkan.","☐ Ya ☐ Tidak"],["3","Persetujuan atau izin kampus yang disyaratkan telah diperoleh.","☐ Ya ☐ Tidak"],["4","Penanggung jawab telah ditunjuk dan beban programnya wajar.","☐ Ya ☐ Tidak"],["5","Keputusan Presiden ditandatangani dan tersosialisasi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-006","g":"Program Kerja dan Kegiatan","t":"Pembentukan Panitia Kegiatan","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[26,29],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pembentukan panitia kegiatan agar struktur, tugas, wewenang, dan pemisahan fungsi panitia jelas serta panitia bekerja dengan pengawasan pimpinan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk panitia setiap kegiatan Kategori A, B, dan C yang diselenggarakan BEM. SOP ini tidak mengatur seleksi pengurus BEM (lihat SOP-SDM-001) dan pembubaran panitia (lihat SOP-PRO-019)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 (Wewenang BEM) huruf b, c, dan f (pengangkatan pengurus internal, pembentukan panitia dan tim kerja, penandatanganan dokumen).","ART Pasal 6 ayat (1) dan (2) (syarat umum kepengurusan).","ART Pasal 11 huruf h, i, dan l (larangan perundungan, penyelewengan dana, dan meninggalkan tanggung jawab).","SOP-PRO-005 (Keputusan Presiden atas program)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Panitia kegiatan","Tim kerja sementara yang menjalankan satu kegiatan berdasarkan Surat Keputusan."],["Ketua pelaksana","Pimpinan panitia yang bertanggung jawab atas pelaksanaan kegiatan kepada penanggung jawab program."],["Pemisahan fungsi","Pemisahan peran pengaju, pemberi persetujuan, pemegang dana, dan pemeriksa agar tidak dipegang satu orang."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Panitia dibentuk setelah Keputusan Presiden atas program terbit (SOP-PRO-005); BEM mengusulkan dan Presiden menetapkan melalui Surat Keputusan Kepanitiaan.","Struktur minimal: penanggung jawab, ketua pelaksana, sekretaris, bendahara, serta seksi acara, publikasi dan dokumentasi, perlengkapan dan konsumsi, dan keamanan dan kesehatan; Kategori A dapat menggabungkan seksi.","Anggota panitia adalah mahasiswa aktif, tidak sedang menjalani sanksi akademik atau kemahasiswaan, dan menyatakan kesediaan tertulis; anggota dari pengurus BEM tetap tunduk pada ART Pasal 6.","Ketua pelaksana tidak merangkap bendahara; bendahara tidak merangkap pemeriksa atau pemberi persetujuan.","Panitia bertanggung jawab kepada penanggung jawab program dan Presiden; seluruh tindakan panitia tunduk pada ART Pasal 11 dan sanksi ART Pasal 12.","Panitia tidak boleh bertindak atas nama BEM di luar mandat Surat Keputusan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan Surat Keputusan Kepanitiaan."],["Wakil Presiden","R","Memeriksa struktur, beban, dan pemisahan fungsi panitia."],["Sekretaris Jenderal","R","Menyiapkan draf Surat Keputusan, mencatat, menomori, dan mengarsipkan."],["Penanggung jawab program","R","Mengusulkan susunan panitia dan membina panitia."],["Biro Keuangan","C","Memastikan bendahara memenuhi syarat dan memberi arahan pengelolaan dana."],["Inspektur Jenderal","C","Memeriksa kesesuaian susunan panitia dengan ketentuan."],["Anggota panitia","I","Menerima tugas dan menjalankannya sesuai Surat Keputusan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Keputusan Presiden atas program.","Usulan susunan panitia.","Surat Pernyataan Kesediaan Panitia.","Data keaktifan dan sanksi mahasiswa bila perlu."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Usulan susunan panitia: Menyusun usulan struktur, nama, dan tugas pokok panitia beserta Surat Pernyataan Kesediaan.","Penanggung jawab","Keputusan Presiden","Usulan susunan panitia","3 hari kerja setelah keputusan program"],["2","Pemeriksaan susunan: Memeriksa syarat anggota, beban rangkap jabatan, dan pemisahan fungsi.","Wapres, Sekjen","Usulan susunan","Catatan pemeriksaan","2 hari kerja"],["3","Penelaahan: Memeriksa kesesuaian dengan ketentuan; memberi catatan bila ada pertentangan.","Irjen","Usulan susunan","Catatan keselarasan","1 hari kerja"],["4","Penyusunan draf SK: Menyusun draf Surat Keputusan Kepanitiaan: dasar, susunan, tugas, masa kerja, dan batas wewenang.","Sekjen","Usulan yang diperbaiki","Draf SK Kepanitiaan","1 hari kerja"],["5","Pengesahan: Menetapkan dan menandatangani SK Kepanitiaan.","Presiden","Draf SK","SK Kepanitiaan","2 hari kerja"],["6","Pengarahan panitia: Menyampaikan SK, tugas, jadwal persiapan, dan aturan kerja kepada panitia.","Penanggung jawab","SK Kepanitiaan","Panitia memahami tugas","2 hari kerja setelah SK"],["7","Pencatatan: Mencatat panitia pada Register Program dan mengarsipkan SK.","Sekjen","SK Kepanitiaan","Arsip dan register diperbarui","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pembentukan panitia ditargetkan selesai paling lambat 7 hari kerja setelah Keputusan Presiden atas program terbit. Hasil akhir: Surat Keputusan Kepanitiaan yang sah."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Anggota panitia mengundurkan diri atau tidak aktif: penanggung jawab mengusulkan pengganti dan Presiden mengubah SK.","Dugaan pelanggaran oleh panitia: ikuti ART Pasal 12 dan 13 serta SOP-SDM-013.","Perselisihan antaranggota panitia: diputuskan penanggung jawab; bila belum selesai dibawa ke SOP- GOV-010.","Kegiatan mendesak tanpa waktu penuh: ikuti SOP-GOV-012 dengan pencatatan SK menyusul."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kegiatan memiliki SK Kepanitiaan sebelum persiapan dimulai.","Tidak ada ketua pelaksana yang merangkap bendahara.","Seluruh anggota panitia memiliki Surat Pernyataan Kesediaan.","SK Kepanitiaan terbit dalam batas waktu pada 90% kegiatan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Surat Keputusan Kepanitiaan.","Surat Pernyataan Kesediaan Panitia.","Catatan pemeriksaan susunan panitia.","Register Program yang diperbarui.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan SK dan pernyataan kesediaan setiap bulan; Irjen menilai kepatuhan pemisahan fungsi pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Usulan susunan → Periksa susunan → Telaah Irjen → Draf SK → Pengesahan Presiden → Pengarahan panitia → Pencatatan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat SK Kepanitiaan","Nomor; dasar; nama kegiatan; susunan panitia; tugas pokok; masa kerja; batas wewenang; tanggal; tanda tangan."],["Surat Pernyataan Kesediaan Panitia","Nama; jabatan; kesanggupan; kepatuhan pada aturan; tanggal; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Keputusan Presiden atas program telah terbit.","☐ Ya ☐ Tidak"],["2","Struktur minimal panitia terpenuhi.","☐ Ya ☐ Tidak"],["3","Ketua pelaksana dan bendahara dijabat orang berbeda.","☐ Ya ☐ Tidak"],["4","Seluruh anggota memenuhi syarat dan memiliki pernyataan kesediaan.","☐ Ya ☐ Tidak"],["5","SK Kepanitiaan ditandatangani, disampaikan, dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-007","g":"Program Kerja dan Kegiatan","t":"Penyusunan TOR atau Kerangka Acuan Kegiatan","o":"Menteri / Kabiro Penanggung Jawab Program","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri / Kabiro penanggung jawab program","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[30,33],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan Kerangka Acuan Kegiatan (TOR) agar tujuan, sasaran, bentuk, jadwal, kebutuhan, dan indikator keberhasilan kegiatan jelas sebelum proposal dan anggaran disusun."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kegiatan Kategori A, B, dan C. Untuk Kategori A, TOR dapat berupa satu halaman ringkas. SOP ini tidak mengatur penyusunan proposal dan RAB (lihat SOP-PRO-008)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Bab III (Tugas) Pasal 3 huruf b dan c (merancang program dan mewadahi kegiatan pengembangan diri, dakwah, sosial, keilmuan, dan minat bakat).","AD Pasal 5 ayat (3) dan ART Pasal 3 (Kewajiban) huruf a (kegiatan sesuai manhaj Ahlusunah wal Jamaah).","ART Pasal 11 (larangan).","SOP-PRO-005 (Keputusan Presiden atas program) dan SOP-PRO-006 (SK Kepanitiaan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["TOR","Kerangka Acuan Kegiatan: dokumen ringkas yang menjelaskan apa, mengapa, siapa, kapan, di mana, dan bagaimana kegiatan dijalankan."],["Sasaran","Kelompok peserta atau penerima manfaat beserta perkiraan jumlahnya."],["Indikator keberhasilan","Ukuran yang dapat diperiksa untuk menilai kegiatan berhasil."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["TOR disusun ketua pelaksana setelah SK Kepanitiaan terbit dan disetujui penanggung jawab program; Kategori B dan C diketahui Wakil Presiden.","Isi minimal: latar belakang, tujuan, sasaran dan perkiraan jumlah peserta, bentuk dan susunan acara garis besar, waktu dan tempat, panitia, narasumber atau mitra, kebutuhan sumber daya, indikator keberhasilan, dan risiko utama.","Materi keilmuan dan dakwah serta calon narasumber ditelaah kesesuaiannya dengan manhaj Ahlusunah wal Jamaah dan peraturan kampus; bila melibatkan ustadz, komunikasi melalui Kementerian Harmonisasi Kampus.","TOR yang telah disetujui menjadi dasar proposal, RAB, publikasi, dan pelaksanaan; perubahan pokok mengikuti SOP-PRO-015."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Ketua pelaksana","R","Menyusun TOR dan melengkapinya dengan data pendukung."],["Penanggung jawab program","A","Menyetujui TOR dan bertanggung jawab atas kesesuaiannya dengan keputusan program."],["Sekretaris panitia","R","Memeriksa format, mencatat versi, dan menyimpan TOR."],["Wakil Presiden","C","Memberi masukan untuk Kategori B dan C serta kesesuaian dengan RKT dan kalender."],["Kementerian Harmonisasi Kampus","C","Memberi masukan komunikasi dengan ustadz dan pihak internal bila diperlukan."],["Sekretaris Jenderal","I","Menerima salinan TOR untuk arsip."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Keputusan Presiden atas program.","SK Kepanitiaan.","Kalender program kerja.","Data kegiatan serupa sebelumnya dan hasil evaluasinya."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengumpulan data: Mengumpulkan keputusan program, kalender, data peserta, dan evaluasi kegiatan serupa.","Ketua pelaksana","Keputusan program, kalender","Bahan TOR","2 hari kerja setelah SK"],["2","Penyusunan draf: Menyusun draf TOR dengan isi minimal sesuai ketentuan pokok.","Ketua pelaksana, sekretaris panitia","Bahan TOR","Draf TOR","3 hari kerja"],["3","Konsultasi materi dan narasumber: Untuk kegiatan keilmuan dan dakwah, meminta masukan kesesuaian materi dan calon narasumber.","Ketua pelaksana, Kementerian Harmonisasi Kampus","Draf TOR","Catatan kesesuaian","2 hari kerja"],["4","Pemeriksaan: Memeriksa kesesuaian TOR dengan keputusan program, RKT, dan kalender.","Penanggung jawab, Wapres","Draf TOR","Catatan pemeriksaan","2 hari kerja"],["5","Persetujuan: Menyetujui TOR dan memberi nomor versi.","Penanggung jawab","Draf TOR final","TOR disetujui","1 hari kerja"],["6","Distribusi dan arsip: Membagikan TOR kepada seluruh seksi dan menyerahkan salinan kepada Sekjen.","Sekretaris panitia","TOR disetujui","TOR tersebar dan terarsip","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"TOR ditargetkan disetujui paling lambat 7 hari kerja setelah SK Kepanitiaan terbit. Hasil akhir: TOR yang disetujui penanggung jawab program."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Perbedaan pandangan atas konsep kegiatan: diputuskan penanggung jawab; bila belum selesai dibawa ke Wakil Presiden.","Materi atau narasumber dinilai tidak sesuai manhaj atau aturan kampus: diganti atau dikonsultasikan kepada pihak kampus sebelum dilanjutkan.","Konsep berubah setelah TOR disetujui: ikuti SOP-PRO-015.","Kegiatan mendesak: TOR ringkas disetujui lebih dahulu dan dilengkapi kemudian."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kegiatan memiliki TOR yang disetujui sebelum proposal disusun.","TOR memuat seluruh isi minimal.","Tidak ada perubahan pokok kegiatan tanpa catatan perubahan.","TOR disetujui dalam batas waktu pada 90% kegiatan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["TOR yang disetujui.","Catatan kesesuaian materi dan narasumber.","Riwayat versi TOR.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris panitia memeriksa versi TOR yang berlaku; Wakil Presiden meninjau kualitas TOR Kategori B dan C pada Rapat Koordinasi."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kumpulkan data → Susun draf TOR → Konsultasi materi → Pemeriksaan → Persetujuan → Distribusi dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat TOR Kegiatan","Latar belakang; tujuan; sasaran; bentuk dan susunan acara; waktu dan tempat; panitia; narasumber atau mitra; kebutuhan; indikator; risiko; versi."],["Catatan Kesesuaian Materi","Judul materi; narasumber; hasil telaah; catatan; pemeriksa; tanggal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh isi minimal TOR terisi.","☐ Ya ☐ Tidak"],["2","TOR sesuai keputusan program, RKT, dan kalender.","☐ Ya ☐ Tidak"],["3","Materi dan narasumber telah ditelaah kesesuaiannya.","☐ Ya ☐ Tidak"],["4","TOR disetujui penanggung jawab dan diberi nomor versi.","☐ Ya ☐ Tidak"],["5","TOR tersebar kepada seluruh seksi dan terarsip.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-008","g":"Program Kerja dan Kegiatan","t":"Penyusunan Proposal dan RAB","o":"Menteri / Kabiro Penanggung Jawab Program","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri / Kabiro penanggung jawab program","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[34,37],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan, pemeriksaan, persetujuan, dan pengajuan proposal kegiatan beserta Rencana Anggaran Biaya (RAB) agar kegiatan didukung dana yang wajar, sah, transparan, dan dapat dipertanggungjawabkan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kegiatan yang memerlukan dana atau dukungan kampus. Format surat dan proposal mengikuti SOP-ADM-007 dan SOP-ADM-008; pencairan dana mengikuti SOP-KEU-004. SOP ini tidak mengatur sponsorship (lihat SOP-HKE-007 dan SOP-KEU-012)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) sampai (4) (sumber keuangan; terhindar dari riba, gharar, dan maysir; bukti resmi; penyusunan anggaran dengan persetujuan KAUR ORMAWA).","ART Pasal 4 (Wewenang BEM) huruf d dan f (mengajukan dana kemahasiswaan; menandatangani dokumen).","ART Bab III (Tugas) Pasal 3 huruf e (penyusunan anggaran).","ART Pasal 3 (Kewajiban) huruf e (pengelolaan keuangan amanah, transparan, akuntabel).","SOP-PRO-007 (TOR) dan SOP-KEU-002 sampai SOP-KEU-004."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Proposal kegiatan","Dokumen permohonan persetujuan dan dukungan kegiatan yang memuat TOR, RAB, dan lampiran."],["RAB","Rencana Anggaran Biaya: daftar pos biaya, volume, harga satuan, jumlah, dan sumber dana."],["Dana tak terduga","Cadangan biaya kecil untuk kebutuhan di luar perkiraan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Proposal disusun berdasarkan TOR yang telah disetujui dan memuat RAB dengan sumber dana yang jelas.","Sumber dana hanya dari sumber yang sah dan halal sesuai AD Pasal 15; dana bersyarat yang mengikat organisasi melampaui satu periode tidak diterima.","Harga satuan didasarkan pada harga pasar atau penawaran; pembelian bernilai besar menyertakan pembanding sesuai SOP-KEU-011.","Dana tak terduga tidak melebihi 5% dari total RAB dan penggunaannya wajib dicatat (usulan).","Proposal Kategori B dan C diajukan kepada pihak kampus melalui KAUR ORMAWA sesuai jadwal pengajuan dana kemahasiswaan.","Pemisahan fungsi: penyusun RAB, pemeriksa RAB, pemberi persetujuan, dan pemegang dana tidak boleh orang yang sama."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Ketua pelaksana","R","Menyusun proposal dan memastikan kesesuaian dengan TOR."],["Bendahara panitia","R","Menyusun RAB dan menghimpun penawaran harga."],["Penanggung jawab program","R","Memeriksa proposal dan RAB sebelum diajukan."],["Biro Keuangan","C","Memverifikasi RAB dan kewajaran biaya (SOP-KEU-003)."],["Sekretaris Jenderal","R","Memeriksa kelengkapan proposal, menomori, dan mengarsipkan."],["Presiden","A","Menyetujui dan menandatangani proposal atas nama BEM."],["KAUR ORMAWA","I","Menerima proposal dan memberi persetujuan sesuai kewenangan kampus."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["TOR yang disetujui.","Daftar kebutuhan dan penawaran harga.","Keputusan Presiden dan SK Kepanitiaan.","Ketentuan dan jadwal dana kemahasiswaan kampus."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan RAB: Menyusun RAB per pos: volume, harga satuan, jumlah, dan sumber dana; menambahkan dana tak terduga.","Bendahara panitia","TOR, penawaran","Draf RAB","3 hari kerja"],["2","Penyusunan proposal: Menyusun proposal: latar belakang, tujuan, bentuk kegiatan, panitia, RAB, penutup, dan lampiran.","Ketua pelaksana","TOR, draf RAB","Draf proposal","3 hari kerja"],["3","Pemeriksaan penanggung jawab: Memeriksa isi dan kesesuaian dengan TOR dan keputusan program.","Penanggung jawab","Draf proposal","Catatan dan persetujuan awal","2 hari kerja"],["4","Verifikasi anggaran: Memverifikasi kewajaran biaya, sumber dana, dan pemisahan fungsi.","Biro Keuangan","Draf RAB","Catatan verifikasi","2 hari kerja"],["5","Pemeriksaan kelengkapan: Memeriksa kelengkapan proposal dengan Checklist Proposal (SOP- ADM-008).","Sekjen","Proposal, checklist","Lengkap atau perlu revisi","1 hari kerja"],["6","Pengesahan: Menyetujui dan menandatangani proposal.","Presiden","Proposal lengkap","Proposal sah bertanda tangan","2 hari kerja"],["7","Pengajuan dukungan dana: Untuk dana kemahasiswaan, mengajukan proposal kepada KAUR ORMAWA; melacak persetujuan.","Sekjen, Presiden","Proposal sah","Bukti pengajuan dan persetujuan","Sesuai jadwal kampus"],["8","Pencatatan: Mencatat proposal pada Register Dokumen dan menyerahkan salinan kepada Biro Keuangan untuk pencairan.","Sekjen","Proposal sah","Arsip dan register","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Proposal beserta RAB ditargetkan siap diajukan paling lambat 12 hari kerja setelah TOR disetujui, dan diajukan sesuai jadwal kampus. Hasil akhir: proposal sah yang dapat diajukan."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["RAB melebihi plafon atau dana yang tersedia: panitia menyusun ulang prioritas bersama Biro Keuangan (SOP-KEU-003).","Sumber dana diragukan kehalalannya atau mengikat organisasi: ditolak dan diteruskan kepada Presiden.","Proposal ditolak atau diberi catatan oleh kampus: direvisi dan diajukan kembali atau kegiatan disesuaikan melalui SOP-PRO-015.","Dugaan penggelembungan biaya: ikuti SOP-RSK-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% proposal dilengkapi RAB yang telah diverifikasi Biro Keuangan.","Tidak ada proposal diajukan tanpa tanda tangan yang berwenang.","Dana tak terduga tidak melebihi batas pada seluruh RAB.","Proposal siap diajukan dalam batas waktu pada 90% kegiatan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Proposal kegiatan dan RAB yang sah.","Catatan verifikasi Biro Keuangan.","Bukti pengajuan dan persetujuan kampus.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan arsip proposal setiap bulan; Irjen menilai kepatuhan prosedur dan pemisahan fungsi pada pemeriksaan berkala (SOP-MONEV-007)."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Susun RAB → Susun proposal → Periksa penanggung jawab → Verifikasi Biro Keuangan → Periksa kelengkapan → Pengesahan Presiden → Ajukan dana → Catat dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Proposal Kegiatan","Latar belakang; tujuan; bentuk kegiatan; waktu dan tempat; panitia; RAB; penutup; lampiran."],["Templat RAB","Pos biaya; volume; satuan; harga satuan; jumlah; sumber dana; dana tak terduga; total."],["Checklist Proposal","Butir kelengkapan, tanda tangan, nomor surat, lampiran, dan verifikasi anggaran."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","RAB memuat volume, harga satuan, jumlah, dan sumber dana.","☐ Ya ☐ Tidak"],["2","Sumber dana sah dan halal.","☐ Ya ☐ Tidak"],["3","Dana tak terduga tidak melebihi batas.","☐ Ya ☐ Tidak"],["4","RAB telah diverifikasi Biro Keuangan.","☐ Ya ☐ Tidak"],["5","Proposal ditandatangani Presiden dan diberi nomor.","☐ Ya ☐ Tidak"],["6","Pengajuan kepada kampus tercatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-009","g":"Program Kerja dan Kegiatan","t":"Pengajuan Izin dan Peminjaman Tempat","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[38,41],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengajuan izin kegiatan dan peminjaman tempat agar kegiatan memiliki tempat yang sah, tidak berbenturan, dan digunakan sesuai syarat pengelola."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kegiatan BEM yang memerlukan ruang atau lokasi di dalam maupun di luar kampus. Penggunaan ruang sekretariat mengikuti SOP-AST-005; peminjaman aset non-tempat mengikuti SOP-AST- 003."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 (Hak BEM) huruf i dan j (fasilitas dan dukungan kampus; kegiatan tingkat regional, nasional, atau internasional dengan seizin kampus).","ART Pasal 3 (Kewajiban) huruf d dan h (menjaga nama baik dan ketertiban; mematuhi peraturan kampus).","ART Pasal 4 (Wewenang BEM) huruf f (penandatanganan surat resmi).","SOP-PRO-002 (Kalender), SOP-ADM-002 dan SOP-ADM-006 (surat keluar dan surat izin)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Peminjaman tempat","Permohonan penggunaan ruang atau lokasi milik kampus atau pihak lain untuk kegiatan."],["Pengelola tempat","Pihak kampus atau pihak luar yang berwenang memberi izin penggunaan tempat."],["Syarat penggunaan","Ketentuan tertulis pengelola tentang waktu, kapasitas, kebersihan, kerusakan, dan larangan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Tempat diajukan setelah jadwal kegiatan terdaftar pada kalender (SOP-PRO-002) dan TOR disetujui.","Tempat kampus diajukan melalui KAUR ORMAWA atau pihak sarana kampus; tempat di luar kampus memerlukan izin pengelola dan persetujuan atau izin kampus sesuai ketentuan.","Batas pengajuan (usulan): Kategori A paling lambat H-3, Kategori B paling lambat H-10, Kategori C paling lambat H-21.","Tempat dan tata penggunaannya harus sesuai nilai Islam, tata tertib kampus, serta ketentuan keselamatan.","Kegiatan belum boleh dipublikasikan sebagai pasti sebelum izin tempat tertulis diperoleh.","Tempat dikembalikan dalam kondisi semula dan bersih; kerusakan dilaporkan segera."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Ketua pelaksana","R","Menyampaikan kebutuhan tempat dan memenuhi syarat penggunaan."],["Sekretaris Jenderal","A","Bertanggung jawab atas pengajuan, pencatatan izin, dan pengarsipan."],["Admin kesekretariatan","R","Menyiapkan surat permohonan dan melacak jawaban."],["Presiden","R","Menandatangani surat permohonan atas nama BEM."],["KAUR ORMAWA / pengelola tempat","C","Memberi izin dan syarat penggunaan tempat."],["Seksi perlengkapan","R","Memeriksa kondisi tempat sebelum dan sesudah penggunaan."],["Wakil Presiden","I","Menerima laporan izin untuk pemantauan kesiapan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["TOR dan kalender kegiatan.","Perkiraan jumlah peserta dan kebutuhan tata ruang.","Surat permohonan.","Syarat penggunaan dari pengelola."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyampaian kebutuhan: Menyampaikan kebutuhan tempat: tanggal, jam, kapasitas, tata ruang, dan fasilitas.","Ketua pelaksana","TOR, kalender","Permintaan tempat","Sesuai batas pengajuan"],["2","Pemeriksaan ketersediaan: Memeriksa ketersediaan tempat dan benturan jadwal.","Admin kesekretariatan","Permintaan, kalender","Tempat tersedia atau alternatif","1 hari kerja"],["3","Penyusunan surat: Menyusun surat permohonan izin dan peminjaman tempat.","Admin kesekretariatan","Permintaan","Draf surat","1 hari kerja"],["4","Penandatanganan dan pengiriman: Menandatangani dan mengirim surat melalui kanal resmi.","Presiden, Sekjen","Draf surat","Surat terkirim dan bukti kirim","1 hari kerja"],["5","Pelacakan jawaban: Menanyakan jawaban dan mencatat izin beserta syarat penggunaan.","Admin kesekretariatan","Bukti kirim","Izin tertulis dan syarat","Sesuai jawaban pengelola"],["6","Penyampaian izin kepada panitia: Menyampaikan izin dan syarat kepada panitia dan Wapres.","Sekjen","Izin tertulis","Panitia memahami syarat","1 hari kerja"],["7","Pemeriksaan sebelum dan sesudah pakai: Memeriksa kondisi tempat dengan Checklist Serah Terima Tempat; mengembalikan tempat sesuai syarat.","Seksi perlengkapan","Izin, checklist","Berita acara kondisi tempat","H-1 dan sesudah kegiatan"],["8","Pencatatan: Mengarsipkan izin dan berita acara.","Admin kesekretariatan","Izin, berita acara","Arsip lengkap","2 hari kerja setelah kegiatan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Izin tempat ditargetkan diperoleh paling lambat H-2 untuk Kategori A, H-7 untuk Kategori B, dan H-14 untuk Kategori C. Hasil akhir: izin tertulis dan berita acara kondisi tempat."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Tempat tidak tersedia atau izin ditolak: panitia menyiapkan alternatif; perubahan jadwal atau tempat mengikuti SOP-PRO-015.","Benturan dengan agenda kampus: diselesaikan Wakil Presiden melalui kalender (SOP-PRO-002).","Kerusakan atau kehilangan di tempat: ikuti SOP-AST-007 dan laporkan kepada pengelola.","Izin belum terbit mendekati hari pelaksanaan: Presiden memutuskan penundaan (SOP-PRO-022)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kegiatan memiliki izin tempat tertulis sebelum dipublikasikan sebagai pasti.","Tidak ada kegiatan berjalan tanpa izin tempat.","Berita acara kondisi tempat tersedia untuk 100% kegiatan Kategori B dan C.","Izin diperoleh dalam batas waktu pada 90% kegiatan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Surat permohonan dan izin tertulis.","Syarat penggunaan tempat.","Berita acara kondisi tempat.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan izin dan berita acara setiap bulan; Wakil Presiden memantau kesiapan tempat pada Rapat Koordinasi."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kebutuhan tempat → Cek ketersediaan → Surat permohonan → Tanda tangan dan kirim → Terima izin dan syarat → Periksa tempat → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Surat Permohonan Tempat","Nomor; tujuan; kegiatan; tanggal dan jam; kapasitas; fasilitas; penanggung jawab; tanda tangan."],["Checklist Serah Terima Tempat","Kondisi ruang; perlengkapan; kebersihan; kerusakan; pemeriksa; tanggal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kegiatan telah terdaftar pada kalender dan TOR disetujui.","☐ Ya ☐ Tidak"],["2","Surat permohonan ditandatangani dan terkirim sesuai batas pengajuan.","☐ Ya ☐ Tidak"],["3","Izin tertulis dan syarat penggunaan diterima.","☐ Ya ☐ Tidak"],["4","Tempat sesuai nilai Islam, tata tertib kampus, dan ketentuan keselamatan.","☐ Ya ☐ Tidak"],["5","Berita acara kondisi tempat dibuat sebelum dan sesudah kegiatan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-010","g":"Program Kerja dan Kegiatan","t":"Pengajuan Narasumber, Pemateri, atau Mitra","o":"Menteri / Kabiro Penanggung Jawab Program","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri / Kabiro penanggung jawab program","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[42,45],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pemilihan, verifikasi, pengundangan, dan pengelolaan narasumber, pemateri, atau mitra kegiatan agar kualitas materi terjaga, sesuai manhaj dan aturan kampus, serta hak dan kewajiban kedua pihak jelas."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kegiatan yang melibatkan narasumber, pemateri, moderator undangan, atau mitra pelaksana. Kerja sama kelembagaan formal mengikuti SOP-HKE-005; protokoler tamu mengikuti SOP-HKE- 010; surat undangan mengikuti SOP-ADM-006."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 5 ayat (3) dan ART Pasal 3 (Kewajiban) huruf a (kegiatan sesuai manhaj Ahlusunah wal Jamaah).","ART Pasal 2 (Hak BEM) huruf e (kerja sama dengan pihak eksternal dengan persetujuan Ketua STDIIS).","ART Pasal 11 huruf a, b, d, dan e (larangan SARA, penistaan agama, paham bertentangan, dan politik praktis).","SOP-PRO-007 (TOR) dan SOP-PRO-008 (RAB)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Narasumber atau pemateri","Pihak yang diundang menyampaikan materi pada kegiatan."],["Mitra","Lembaga atau organisasi yang membantu pelaksanaan kegiatan."],["Verifikasi narasumber","Pemeriksaan latar belakang, kompetensi, dan kesesuaian materi dengan manhaj dan aturan kampus."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Calon narasumber diusulkan panitia dalam TOR dan wajib diverifikasi sebelum diundang.","Narasumber dan materi tidak boleh bertentangan dengan manhaj Ahlusunah wal Jamaah, ART Pasal 11, atau peraturan kampus.","Komunikasi dengan ustadz dan pihak internal kampus melalui Kementerian Harmonisasi Kampus; narasumber eksternal Kategori C dikonsultasikan kepada KAUR ORMAWA atau Pembina.","Undangan resmi diterbitkan setelah verifikasi dan persetujuan penanggung jawab; honorarium dan fasilitas sesuai RAB.","Kerja sama kelembagaan dengan mitra baru memerlukan persetujuan Ketua STDIIS (ART Pasal 2 huruf e) melalui SOP-HKE-005; undangan perorangan tidak dianggap kerja sama tetapi tetap diverifikasi.","Tersedia narasumber cadangan untuk kegiatan Kategori B dan C."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Ketua pelaksana","R","Mengusulkan calon narasumber dan mengelola komunikasi dengan narasumber."],["Seksi acara","R","Mengonfirmasi kehadiran, kebutuhan, dan materi narasumber."],["Penanggung jawab program","A","Menyetujui calon narasumber atau mitra dan bertanggung jawab atas kesesuaiannya."],["Kementerian Harmonisasi Kampus","C","Membantu komunikasi dengan ustadz dan pihak internal serta memberi masukan kesesuaian."],["Wakil Presiden","C","Memberi masukan untuk Kategori B dan C."],["Bendahara panitia","R","Menyiapkan honorarium dan fasilitas sesuai RAB."],["Sekretaris Jenderal","I","Menerbitkan surat undangan dan mengarsipkan korespondensi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["TOR dan RAB.","Daftar calon narasumber beserta profil dan rekam jejak.","Rencana judul dan garis besar materi.","Jadwal kegiatan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengusulan calon: Menyusun daftar calon narasumber atau mitra beserta profil, topik, dan alasan pemilihan.","Ketua pelaksana","TOR, RAB","Daftar calon","3 hari kerja"],["2","Verifikasi: Memeriksa latar belakang, kompetensi, dan kesesuaian dengan manhaj dan aturan kampus; mengisi Lembar Verifikasi.","Seksi acara, Kementerian Harmonisasi Kampus","Daftar calon","Lembar Verifikasi Narasumber","3 hari kerja"],["3","Persetujuan: Menyetujui calon utama dan cadangan; untuk Kategori C berkonsultasi dengan KAUR ORMAWA atau Pembina.","Penanggung jawab, Wapres","Lembar Verifikasi","Narasumber disetujui","2 hari kerja"],["4","Pengundangan: Menerbitkan dan mengirim surat undangan resmi beserta rincian kegiatan.","Sekjen","Persetujuan, TOR","Undangan terkirim","1 hari kerja"],["5","Konfirmasi: Mengonfirmasi kesediaan, jadwal, materi, kebutuhan teknis, dan hak narasumber.","Seksi acara","Jawaban undangan","Konfirmasi tertulis","Paling lambat H-7"],["6","Penyiapan fasilitas: Menyiapkan honorarium, transportasi, konsumsi, dan akomodasi sesuai RAB.","Bendahara panitia","Konfirmasi, RAB","Fasilitas siap","Paling lambat H-2"],["7","Pendampingan hari-H: Menyambut, mendampingi, dan memberi pengarahan tata tertib kepada narasumber.","Seksi acara","Rundown","Narasumber hadir dan terlayani","Hari pelaksanaan"],["8","Penutupan: Mengirim ucapan terima kasih, menyelesaikan hak narasumber, dan mengarsipkan korespondensi.","Seksi acara, Sekjen","Laporan kegiatan","Arsip lengkap","5 hari kerja setelah kegiatan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Narasumber utama ditargetkan terkonfirmasi paling lambat H-7 untuk Kategori B dan H-14 untuk Kategori C. Hasil akhir: narasumber terverifikasi, terundang, dan terkonfirmasi secara tertulis."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Narasumber berhalangan: aktifkan narasumber cadangan dan sampaikan perubahan melalui SOP-PRO- 015.","Materi atau pernyataan narasumber diduga bertentangan dengan aturan: ikuti SOP-RSK-004 dan laporkan kepada Wakil Presiden.","Kerja sama kelembagaan dengan mitra baru: ikuti SOP-HKE-005.","Perbedaan pendapat atas kelayakan narasumber: diputuskan penanggung jawab; bila belum selesai, Wakil Presiden berkonsultasi dengan KAUR ORMAWA atau Pembina."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% narasumber memiliki Lembar Verifikasi sebelum diundang.","Tidak ada narasumber tampil tanpa persetujuan tertulis penanggung jawab.","Narasumber cadangan tersedia pada 100% kegiatan Kategori B dan C.","Konfirmasi tertulis diperoleh dalam batas waktu pada 90% kegiatan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Verifikasi Narasumber.","Surat undangan dan konfirmasi.","Bukti penyelesaian hak narasumber.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden memeriksa kesiapan narasumber pada Rapat Koordinasi menjelang kegiatan; Irjen menilai kepatuhan prosedur verifikasi pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Usulan calon → Verifikasi → Persetujuan → Undangan → Konfirmasi → Fasilitas → Pendampingan hari-H → Penutupan dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Verifikasi Narasumber","Nama; lembaga; topik; rekam jejak; hasil telaah kesesuaian; pemeriksa; keputusan; tanggal."],["Templat Surat Undangan Narasumber","Nomor; tujuan; kegiatan; waktu dan tempat; topik; fasilitas; kontak; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Calon narasumber telah diverifikasi dan disetujui tertulis.","☐ Ya ☐ Tidak"],["2","Narasumber cadangan tersedia untuk Kategori B dan C.","☐ Ya ☐ Tidak"],["3","Undangan resmi terkirim dan kesediaan terkonfirmasi.","☐ Ya ☐ Tidak"],["4","Honorarium dan fasilitas sesuai RAB.","☐ Ya ☐ Tidak"],["5","Korespondensi dan hak narasumber terarsip.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-011","g":"Program Kerja dan Kegiatan","t":"Persiapan Teknis dan Logistik","o":"Menteri / Kabiro Penanggung Jawab Program","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri / Kabiro penanggung jawab program","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[46,49],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur persiapan teknis dan logistik kegiatan agar seluruh kebutuhan siap, diuji, dan dikendalikan sebelum hari pelaksanaan melalui keputusan kesiapan yang jelas."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kegiatan Kategori A, B, dan C setelah proposal disetujui. SOP ini mengatur kesiapan teknis, rundown, dan logistik; pengadaan barang mengikuti SOP-PRO-012 dan peminjaman aset mengikuti SOP-AST-003."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 10 ayat (1) dan (4) (Rapat Koordinasi: koordinasi kegiatan mendatang dan monitoring anggaran).","ART Pasal 3 (Kewajiban) huruf d (menjaga ketertiban dan kedamaian).","SOP-PRO-007, SOP-PRO-008, SOP-PRO-009, dan SOP-PRO-010.","SOP-RSK-002 (Penilaian Risiko Sebelum Kegiatan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rundown","Susunan acara terperinci per menit beserta penanggung jawab tiap sesi."],["Gladi","Uji coba teknis atau alur acara sebelum hari pelaksanaan."],["Keputusan kesiapan (go/no- go)","Keputusan pimpinan bahwa kegiatan layak dilanjutkan atau perlu diubah berdasarkan laporan kesiapan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Seluruh seksi menyusun daftar kebutuhan dan penanggung jawab berdasarkan TOR dan RAB yang disetujui.","Rundown menghormati waktu salat fardu dan salat Jumat serta menyediakan waktu dan fasilitas ibadah.","Fasilitas dasar yang wajib dicek: tempat dan tata ruang, listrik dan suara, perlengkapan acara, daftar hadir, tanda pengenal, perlengkapan P3K, jalur evakuasi, dan fasilitas bersuci.","Kegiatan Kategori B dan C wajib melakukan gladi; Kategori A cukup pengecekan.","Laporan kesiapan disampaikan pada H-3 dan keputusan kesiapan diambil Wakil Presiden paling lambat H-2 (usulan).","Kegiatan tanpa keputusan kesiapan tidak dilanjutkan ke hari pelaksanaan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Ketua pelaksana","R","Memimpin persiapan, rapat panitia, dan menyampaikan laporan kesiapan."],["Seksi acara, perlengkapan, dan keamanan dan kesehatan","R","Menyiapkan rundown, perlengkapan, tata ruang, jalur evakuasi, dan P3K."],["Penanggung jawab program","A","Bertanggung jawab atas kesiapan dan menandatangani laporan kesiapan."],["Wakil Presiden","R","Memeriksa laporan dan mengambil keputusan kesiapan."],["Tim Acara","C","Memberi masukan rundown, protokoler, dan pengendalian teknis acara."],["Sekretaris Jenderal","I","Menerima rundown dan laporan kesiapan untuk arsip."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["TOR, proposal, dan RAB yang disetujui.","Izin tempat dan konfirmasi narasumber.","Daftar peserta atau perkiraan jumlah.","Hasil penilaian risiko kegiatan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan daftar kebutuhan: Setiap seksi menyusun daftar kebutuhan teknis dan logistik beserta penanggung jawab.","Seluruh seksi","TOR, RAB","Daftar kebutuhan per seksi","3 hari kerja"],["2","Penyusunan rundown: Menyusun rundown terperinci dengan waktu ibadah dan penanggung jawab tiap sesi.","Seksi acara, Tim Acara","TOR, konfirmasi narasumber","Rundown","3 hari kerja"],["3","Rapat persiapan: Mengadakan rapat koordinasi panitia; mencatat tindak lanjut.","Ketua pelaksana","Daftar kebutuhan, rundown","Notulen dan tindak lanjut","Minimal 2 kali sebelum kegiatan"],["4","Pemenuhan kebutuhan: Menyiapkan atau meminjam perlengkapan dan mengatur tata ruang.","Seksi perlengkapan","Daftar kebutuhan","Perlengkapan tersedia","Paling lambat H-3"],["5","Gladi dan pengecekan: Melakukan gladi (Kategori B dan C) atau pengecekan (Kategori A) terhadap suara, alur, dan tata ruang.","Panitia, Tim Acara","Rundown, perlengkapan","Catatan kekurangan dan perbaikannya","H-2 sampai H-1"],["6","Laporan kesiapan: Mengisi Checklist Kesiapan dan menyampaikan laporan kesiapan.","Ketua pelaksana, penanggung jawab","Checklist","Laporan kesiapan","Paling lambat H-3"],["7","Keputusan kesiapan: Memeriksa laporan dan memutuskan: lanjut, lanjut bersyarat, atau ubah jadwal (SOP-PRO-015).","Wapres","Laporan kesiapan","Keputusan kesiapan","Paling lambat H-2"],["8","Pengarahan akhir: Menyampaikan pengarahan akhir, pembagian tugas hari-H, dan kontak darurat kepada panitia.","Ketua pelaksana","Rundown, keputusan","Panitia siap","H-1"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Persiapan teknis dan logistik ditargetkan lengkap pada H-3 dan keputusan kesiapan diambil paling lambat H- 2. Hasil akhir: laporan kesiapan dan keputusan kesiapan tertulis."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kebutuhan kritis belum terpenuhi pada H-3: panitia melapor kepada Wakil Presiden untuk pemenuhan darurat atau perubahan jadwal (SOP-PRO-015).","Hasil gladi menunjukkan risiko keselamatan: kegiatan ditahan sampai risiko dikendalikan (SOP-PRO- 017).","Kekurangan dana perlengkapan: ikuti SOP-KEU-014.","Penolakan keputusan kesiapan oleh panitia: diputuskan Wakil Presiden; bila perlu dibawa ke Presiden."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kegiatan memiliki laporan dan keputusan kesiapan tertulis.","Seluruh kebutuhan kritis terpenuhi pada H-3.","Gladi dilakukan pada 100% kegiatan Kategori B dan C.","Jumlah kendala teknis hari-H menurun dari kegiatan ke kegiatan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar kebutuhan per seksi.","Rundown final.","Notulen rapat persiapan.","Checklist Kesiapan dan laporan kesiapan.","Keputusan kesiapan.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden memantau kesiapan seluruh kegiatan pada Rapat Koordinasi; Sekretaris Jenderal mengarsipkan dokumen persiapan setiap kegiatan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Daftar kebutuhan → Rundown → Rapat persiapan → Penuhi kebutuhan → Gladi → Laporan kesiapan → Keputusan kesiapan → Pengarahan akhir → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Rundown","Waktu; sesi; durasi; penanggung jawab; keterangan; waktu ibadah."],["Checklist Kesiapan Teknis dan Logistik","Tempat; suara; perlengkapan; peserta; P3K; jalur evakuasi; fasilitas bersuci; status; penanggung jawab."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Daftar kebutuhan seluruh seksi telah terpenuhi.","☐ Ya ☐ Tidak"],["2","Rundown memuat waktu ibadah dan penanggung jawab tiap sesi.","☐ Ya ☐ Tidak"],["3","Gladi atau pengecekan telah dilaksanakan dan kekurangan diperbaiki.","☐ Ya ☐ Tidak"],["4","Perlengkapan P3K dan jalur evakuasi tersedia.","☐ Ya ☐ Tidak"],["5","Keputusan kesiapan telah diterbitkan Wakil Presiden.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-012","g":"Program Kerja dan Kegiatan","t":"Pengadaan Perlengkapan dan Konsumsi","o":"Menteri / Kabiro Penanggung Jawab Program","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri / Kabiro penanggung jawab program","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[50,53],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengadaan perlengkapan dan konsumsi kegiatan agar kebutuhan terpenuhi secara wajar, halal, sesuai RAB, dan dapat dipertanggungjawabkan dengan bukti yang sah."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pengadaan barang, jasa kecil, dan konsumsi oleh panitia. Aturan pembelian barang dan jasa mengikuti SOP-KEU-010, perbandingan penawaran mengikuti SOP-KEU-011, dan pencairan dana mengikuti SOP-KEU-004."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (2) dan (3) (terhindar dari riba, gharar, dan maysir; dokumentasi bukti resmi).","ART Pasal 3 (Kewajiban) huruf e (pengelolaan keuangan amanah, transparan, dan akuntabel).","ART Pasal 11 huruf i dan k (larangan penyelewengan dana dan penggunaan fasilitas untuk kepentingan pribadi).","SOP-PRO-008 (RAB), SOP-KEU-010, SOP-KEU-011, dan SOP-KEU-016."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pengadaan","Proses memperoleh barang, jasa, atau konsumsi yang dibutuhkan kegiatan."],["Konsumsi halal dan layak","Makanan dan minuman yang halal, higienis, dan memperhatikan kebutuhan peserta yang diketahui."],["Bukti pengadaan","Nota, kuitansi, atau bukti pembayaran resmi beserta dokumentasi barang yang diterima."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pengadaan hanya untuk kebutuhan yang tercantum dalam RAB; pengadaan di luar RAB memerlukan persetujuan tertulis penanggung jawab dan Biro Keuangan (SOP-KEU-014).","Konsumsi wajib halal dan higienis; panitia mencatat kebutuhan khusus peserta dari data pendaftaran sejauh diketahui.","Pembelian bernilai di atas batas yang ditetapkan menyertakan minimal tiga penawaran (usulan) sesuai SOP-KEU-011.","Pemisahan fungsi: yang mengajukan kebutuhan, menyetujui, membayar, dan menerima barang tidak boleh orang yang sama.","Seluruh pembelian disertai bukti sah; tidak ada pembelian tanpa bukti.","Barang yang menjadi aset dicatat sebagai inventaris (SOP-AST-001 dan SOP-AST-002); sisa konsumsi dimanfaatkan secara baik dan tidak dibuang sia-sia."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Seksi perlengkapan dan konsumsi","R","Mengajukan daftar kebutuhan, mencari penawaran, dan menerima barang."],["Bendahara panitia","R","Membayar sesuai persetujuan, menyimpan bukti, dan mencatat transaksi."],["Penanggung jawab program","A","Menyetujui daftar pengadaan dan bertanggung jawab atas kesesuaiannya dengan RAB."],["Biro Keuangan","C","Memeriksa kewajaran harga, kesesuaian RAB, dan bukti transaksi."],["Ketua pelaksana","R","Menyetujui penerimaan barang dan mengawasi pelaksanaan pengadaan."],["Wakil Presiden","I","Menerima laporan pengadaan bernilai besar atau di luar RAB."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["RAB yang disetujui.","Daftar kebutuhan per seksi.","Dana yang telah dicairkan.","Data kebutuhan khusus peserta."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Daftar pengadaan: Menyusun Daftar Kebutuhan Pengadaan berdasarkan RAB: jenis, jumlah, spesifikasi, dan jadwal.","Seksi perlengkapan dan konsumsi","RAB, daftar kebutuhan","Daftar pengadaan","2 hari kerja"],["2","Pencarian penawaran: Mengumpulkan penawaran harga dan memastikan kehalalan konsumsi.","Seksi perlengkapan dan konsumsi","Daftar pengadaan","Penawaran dan pembanding","3 hari kerja"],["3","Persetujuan: Menyetujui daftar pengadaan dan pilihan penyedia.","Penanggung jawab, Biro Keuangan","Penawaran","Persetujuan tertulis","2 hari kerja"],["4","Pembayaran: Membayar penyedia dengan bukti sah sesuai SOP-KEU-006.","Bendahara panitia","Persetujuan, dana","Bukti pembayaran","Sesuai jadwal pengadaan"],["5","Penerimaan dan pemeriksaan: Memeriksa jumlah dan kualitas barang atau konsumsi terhadap pesanan; mencatat penerimaan.","Seksi perlengkapan, ketua pelaksana","Pesanan, barang","Berita acara penerimaan","Saat barang diterima"],["6","Pencatatan inventaris: Mencatat barang aset sebagai inventaris dan menyerahkan pengelolaannya.","Seksi perlengkapan, BPH dan Eksekutif","Berita acara penerimaan","Barang tercatat","3 hari kerja"],["7","Rekap bukti: Menyusun rekap pengeluaran dan bukti untuk LPJ.","Bendahara panitia","Bukti pengadaan","Rekap pengeluaran","3 hari kerja setelah kegiatan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pengadaan ditargetkan selesai paling lambat H-3. Hasil akhir: barang dan konsumsi diterima sesuai RAB beserta bukti pengadaan yang lengkap."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Harga melebihi RAB: ikuti SOP-KEU-014 dan minta persetujuan tertulis sebelum membeli.","Barang tidak sesuai pesanan atau rusak: ditolak atau ditukar dan dicatat dalam berita acara.","Bukti pembelian tidak lengkap: bendahara melapor kepada Biro Keuangan; ikuti SOP-KEU-016.","Dugaan penyalahgunaan atau penggelembungan dana: ikuti SOP-RSK-007.","Keraguan kehalalan konsumsi: tidak dipakai sampai dipastikan."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pengadaan memiliki persetujuan dan bukti sah.","Seluruh konsumsi halal dan higienis.","Realisasi tidak melebihi RAB tanpa persetujuan tertulis.","Seluruh aset hasil pengadaan tercatat sebagai inventaris."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Kebutuhan Pengadaan.","Penawaran dan persetujuan.","Bukti pembayaran dan berita acara penerimaan.","Rekap pengeluaran.","Entri inventaris.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Biro Keuangan memeriksa bukti pengadaan sebelum LPJ; Irjen menilai kepatuhan prosedur dan pemisahan fungsi pada pemeriksaan berkala (SOP-MONEV-007)."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Daftar pengadaan → Cari penawaran → Persetujuan → Pembayaran → Terima dan periksa → Catat inventaris → Rekap bukti → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Kebutuhan Pengadaan","Jenis; jumlah; spesifikasi; perkiraan harga; penyedia; pos RAB; jadwal; penanggung jawab."],["Berita Acara Penerimaan Barang","Barang; jumlah; kondisi; penyedia; penerima; tanggal; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh pengadaan tercantum dalam RAB atau disetujui tertulis.","☐ Ya ☐ Tidak"],["2","Penawaran pembanding tersedia sesuai ketentuan.","☐ Ya ☐ Tidak"],["3","Konsumsi halal dan higienis.","☐ Ya ☐ Tidak"],["4","Bukti pembayaran dan berita acara penerimaan lengkap.","☐ Ya ☐ Tidak"],["5","Barang aset telah dicatat sebagai inventaris.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-013","g":"Program Kerja dan Kegiatan","t":"Publikasi dan Pendaftaran Peserta","o":"Kepala Biro Desain Komunikasi Visual","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Desain Komunikasi Visual","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Sekretaris Jenderal dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[54,57],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pembuatan publikasi kegiatan dan pengelolaan pendaftaran peserta agar informasi akurat, bersumber dari izin yang sah, sesuai nilai Islam dan aturan kampus, serta data peserta terlindungi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk publikasi dan pendaftaran seluruh kegiatan BEM. Pembuatan dan persetujuan konten umum mengikuti SOP-KOM-007, pengelolaan media sosial mengikuti SOP-KOM-008, dan penggunaan logo mengikuti SOP-KOM-014."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 18 ayat (1) dan (2) (lambang yang sah dan larangan lambang yang tidak disahkan).","ART Pasal 11 huruf a, b, d, e, dan g (larangan SARA, penistaan agama, paham bertentangan, politik praktis, dan pencemaran nama baik).","ART Pasal 3 (Kewajiban) huruf d (menjaga nama baik kampus).","SOP-KOM-007, SOP-KOM-009, SOP-RSK-010, dan SOP-SDM-018."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Brief publikasi","Permintaan tertulis panitia kepada Biro Desain Komunikasi Visual yang memuat isi, ukuran, kanal, dan tenggat desain."],["Pendaftaran peserta","Pengumpulan data peserta melalui formulir resmi untuk mendata, memverifikasi, dan mengatur kuota."],["Data peserta","Informasi pribadi peserta yang dikumpulkan hanya untuk keperluan kegiatan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Publikasi baru dilakukan setelah keputusan program, izin tempat, dan konfirmasi narasumber terbit; informasi yang belum pasti tidak dipublikasikan.","Setiap konten wajib menggunakan lambang dan identitas BEM yang sah serta bahasa yang santun, tidak memuat SARA, politik praktis, atau ucapan yang melanggar ART Pasal 11.","Konten disetujui penanggung jawab program dan diperiksa Sekretaris Jenderal untuk ketepatan data; Kategori B dan C juga diketahui Wakil Presiden.","Waktu publikasi (usulan): Kategori A paling lambat H-3, Kategori B paling lambat H-10, Kategori C paling lambat H-14.","Formulir pendaftaran hanya meminta data yang diperlukan; data peserta hanya diakses panitia yang berwenang dan tidak dibagikan tanpa izin peserta.","Kuota dan batas pendaftaran ditetapkan sesuai kapasitas tempat dan keselamatan; pendaftaran ditutup bila kuota penuh."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Seksi publikasi dan dokumentasi","R","Menyusun brief, isi publikasi, dan mengelola formulir pendaftaran."],["Biro Desain Komunikasi Visual","A","Bertanggung jawab atas kualitas desain dan penerbitan publikasi sesuai aturan identitas."],["Penanggung jawab program","R","Menyetujui isi publikasi dan syarat pendaftaran."],["Sekretaris Jenderal","R","Memeriksa ketepatan data, nomor surat, dan lampiran publikasi."],["Wakil Presiden","C","Memberi persetujuan untuk Kategori B dan C."],["Peserta","I","Mengisi data dengan benar dan mengikuti tata tertib."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["TOR, izin tempat, dan konfirmasi narasumber.","Brief publikasi.","Logo dan templat desain resmi.","Kuota dan syarat peserta."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyampaian brief: Menyampaikan brief publikasi: judul, waktu, tempat, narasumber, kuota, kanal, tenggat, dan kontak.","Seksi publikasi dan dokumentasi","TOR, izin, konfirmasi","Brief publikasi","Sesuai batas publikasi"],["2","Pembuatan desain: Mengerjakan desain dengan templat dan lambang resmi; mencatat antrean pekerjaan.","Biro Desain Komunikasi Visual","Brief, templat","Draf desain","3 hari kerja"],["3","Pembuatan formulir pendaftaran: Menyiapkan formulir dengan data seperlunya, kuota, dan pernyataan penggunaan data.","Seksi publikasi dan dokumentasi","Syarat peserta","Formulir pendaftaran","2 hari kerja"],["4","Pemeriksaan dan persetujuan: Memeriksa ketepatan data dan kesesuaian aturan; menyetujui konten.","Sekjen, penanggung jawab, Wapres","Draf desain, formulir","Konten disetujui","2 hari kerja"],["5","Penerbitan: Menerbitkan publikasi melalui kanal resmi dan membuka pendaftaran.","Biro Desain Komunikasi Visual","Konten disetujui","Publikasi terbit","Sesuai batas publikasi"],["6","Pengelolaan pendaftaran: Memantau pendaftar, memverifikasi, mengirim konfirmasi, dan menutup pendaftaran saat kuota penuh.","Seksi publikasi dan dokumentasi","Data pendaftar","Daftar peserta terkonfirmasi","Sampai batas pendaftaran"],["7","Koreksi bila ada kesalahan: Mengoreksi atau menarik publikasi yang keliru sesuai SOP-KOM-009 dan memberi tahu peserta.","Biro Desain Komunikasi Visual","Temuan kesalahan","Publikasi terkoreksi","1 hari kerja setelah temuan"],["8","Penyerahan data: Menyerahkan daftar peserta ke seksi acara dan menyimpan data secara aman.","Seksi publikasi dan dokumentasi","Daftar peserta","Daftar peserta final","Paling lambat H-2"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Publikasi terbit sesuai batas masing-masing kategori dan pendaftaran ditutup paling lambat H-2 atau saat kuota penuh. Hasil akhir: publikasi sah dan daftar peserta terkonfirmasi."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Informasi kegiatan berubah: ikuti SOP-PRO-015 dan terbitkan koreksi sesuai SOP-KOM-009.","Konten menimbulkan keberatan atau polemik: ikuti SOP-KOM-012 dan laporkan kepada Wakil Presiden.","Kebocoran data peserta: ikuti SOP-RSK-009.","Kuota melebihi kapasitas tempat: batasi pendaftaran; konsultasikan dengan panitia keselamatan (SOP- PRO-017)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% publikasi disetujui sebelum terbit.","Tidak ada publikasi menggunakan lambang yang tidak sah.","Tidak ada kebocoran data peserta.","Koreksi kesalahan dilakukan dalam 1 hari kerja pada 100% temuan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Brief publikasi.","Desain dan konten yang disetujui.","Formulir pendaftaran dan daftar peserta.","Catatan koreksi publikasi.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa arsip publikasi dan persetujuan setiap bulan; Irjen menilai kepatuhan identitas dan perlindungan data pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Brief publikasi → Desain dan formulir → Periksa dan setujui → Terbit → Kelola pendaftaran → Koreksi bila perlu → Serahkan daftar peserta → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Brief Publikasi Kegiatan","Judul; waktu; tempat; narasumber; kuota; kanal; tenggat; kontak; penanggung jawab."],["Formulir Pendaftaran Peserta","Data seperlunya; kontak; pernyataan penggunaan data; persetujuan tata tertib."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Konten menggunakan lambang dan templat resmi.","☐ Ya ☐ Tidak"],["2","Informasi telah sesuai izin dan konfirmasi yang ada.","☐ Ya ☐ Tidak"],["3","Konten disetujui penanggung jawab dan diperiksa Sekjen.","☐ Ya ☐ Tidak"],["4","Formulir hanya meminta data yang diperlukan.","☐ Ya ☐ Tidak"],["5","Kuota sesuai kapasitas tempat dan keselamatan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-014","g":"Program Kerja dan Kegiatan","t":"Pelaksanaan Kegiatan","o":"Menteri / Kabiro Penanggung Jawab Program","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri / Kabiro penanggung jawab program","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[58,61],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pelaksanaan kegiatan pada hari-H agar kegiatan berjalan sesuai rundown, tertib, aman, sesuai syariat Islam dan tata tertib kampus, serta tercatat dengan baik."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh panitia dan peserta pada hari pelaksanaan kegiatan Kategori A, B, dan C. Perubahan konsep atau jadwal mengikuti SOP-PRO-015, kendala lapangan mengikuti SOP-PRO-016, dan keadaan darurat mengikuti SOP-PRO-017."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Kewajiban) huruf a, b, c, dan d (program sesuai tujuan dan prinsip Ahlus Sunnah wal Jama'ah; persatuan dan ukhuwah; manfaat bagi civitas; ketertiban).","ART Pasal 11 (larangan).","AD Pasal 5 (fungsi BEM).","SOP-PRO-011 (Persiapan Teknis dan Logistik)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Koordinator lapangan","Panitia yang mengendalikan kelancaran alur acara dan menjadi penghubung antarseksi pada hari-H."],["Lembar Kendali Hari-H","Lembar pemantauan waktu, kehadiran, dan kejadian penting selama kegiatan."],["Tata tertib kegiatan","Aturan perilaku peserta dan panitia sesuai syariat Islam dan peraturan kampus."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kegiatan hanya dimulai bila keputusan kesiapan (SOP-PRO-011) telah terbit.","Rundown dijalankan dengan menghormati waktu salat fardu dan salat Jumat.","Seluruh panitia mengenakan tanda pengenal dan menjalankan tugas sesuai SK Kepanitiaan.","Tata tertib kegiatan disampaikan kepada peserta di awal acara; pelanggaran ditangani sesuai ART Pasal 11 sampai 13 dan peraturan kampus.","Kegiatan Kategori B dan C dihadiri minimal satu pimpinan BEM atau pejabat yang ditunjuk; Irjen atau pengawas yang ditunjuk dapat memantau.","Pernyataan resmi atas nama BEM hanya disampaikan penanggung jawab atau juru bicara yang ditunjuk (SOP-KOM-010)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Ketua pelaksana","R","Memimpin pelaksanaan, memutuskan penyesuaian kecil, dan melapor kepada penanggung jawab."],["Koordinator lapangan","R","Mengendalikan alur, waktu, dan koordinasi antarseksi."],["Seksi acara, perlengkapan, publikasi dan dokumentasi, keamanan dan kesehatan","R","Menjalankan tugas masing-masing sesuai rundown."],["Penanggung jawab program","A","Bertanggung jawab akhir atas jalannya kegiatan."],["Wakil Presiden","C","Memantau kegiatan Kategori B dan C dan memberi arahan bila diperlukan."],["Inspektur Jenderal","C","Memantau kepatuhan prosedur bila ditugaskan."],["Peserta dan narasumber","I","Mengikuti tata tertib dan arahan panitia."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Rundown final dan keputusan kesiapan.","Daftar peserta dan daftar panitia.","Checklist kesiapan dan kontak darurat.","Perlengkapan dan konsumsi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengarahan panitia: Mengumpulkan panitia, menyampaikan rundown, pembagian tugas, dan kontak darurat.","Ketua pelaksana","Rundown, SK","Panitia siap","1 jam sebelum acara"],["2","Pemeriksaan akhir: Memeriksa tempat, suara, perlengkapan, dan jalur evakuasi.","Koordinator lapangan","Checklist kesiapan","Pemeriksaan akhir tercatat","30 menit sebelum acara"],["3","Registrasi peserta: Mencatat kehadiran peserta dan mengarahkan ke tempat.","Seksi acara","Daftar peserta","Daftar hadir","Sesuai rundown"],["4","Pembukaan dan tata tertib: Membuka acara dan menyampaikan tata tertib sesuai syariat dan aturan kampus.","Seksi acara, ketua pelaksana","Rundown","Acara dimulai","Sesuai rundown"],["5","Pengendalian jalannya acara: Mengendalikan waktu, mencatat kejadian pada Lembar Kendali, dan memastikan waktu ibadah terlaksana.","Koordinator lapangan","Rundown, Lembar Kendali","Acara berjalan sesuai rencana","Selama acara"],["6","Penanganan penyimpangan: Menangani kendala kecil sesuai SOP- PRO-016 dan melapor bila melebihi batas.","Ketua pelaksana","Kendala lapangan","Kendala tertangani atau dieskalasi","Segera"],["7","Penutupan dan pemeriksaan tempat: Menutup acara, merapikan tempat, memeriksa kondisi tempat dan aset.","Seksi perlengkapan, koordinator lapangan","Checklist serah terima tempat","Tempat dan aset terkendali","Segera setelah acara"],["8","Rapat singkat dan laporan awal: Mengadakan rapat singkat panitia dan menyampaikan laporan awal kegiatan.","Ketua pelaksana","Lembar Kendali","Laporan awal","H+1"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Seluruh tahapan hari-H mengikuti rundown. Laporan awal disampaikan paling lambat H+1. Hasil akhir: kegiatan terlaksana sesuai rundown, Lembar Kendali Hari-H, dan laporan awal."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Keterlambatan atau kendala lapangan: ikuti SOP-PRO-016.","Keadaan darurat atau ancaman keselamatan: ikuti SOP-PRO-017 dan hentikan kegiatan bila diperlukan.","Perubahan konsep atau jadwal mendadak: ikuti SOP-PRO-015.","Pelanggaran tata tertib oleh peserta atau panitia: ditangani ketua pelaksana; pelanggaran berat dilaporkan kepada Wakil Presiden dan ditangani sesuai ART Pasal 12 dan 13.","Pertanyaan atau liputan dari pihak luar: dialihkan kepada juru bicara yang ditunjuk (SOP-KOM-010)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kegiatan dimulai setelah keputusan kesiapan terbit.","Waktu salat tidak terlewat pada seluruh kegiatan.","Kegiatan dimulai dengan keterlambatan tidak lebih dari 30 menit pada 90% kegiatan.","Lembar Kendali Hari-H tersedia untuk 100% kegiatan Kategori B dan C."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar hadir peserta dan panitia.","Lembar Kendali Hari-H.","Berita acara kondisi tempat.","Laporan awal kegiatan.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden meninjau laporan awal kegiatan pada Rapat Koordinasi; Irjen menilai kepatuhan prosedur pelaksanaan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengarahan panitia → Pemeriksaan akhir → Registrasi → Pembukaan dan tata tertib → Kendali acara → Tangani penyimpangan → Penutupan dan periksa tempat → Laporan awal → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Kendali Hari-H","Waktu rencana dan realisasi; sesi; kejadian; kendala; tindakan; pencatat."],["Daftar Hadir Peserta dan Panitia","Nama; asal; tanda tangan atau tanda hadir; waktu hadir."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Keputusan kesiapan telah terbit sebelum kegiatan dimulai.","☐ Ya ☐ Tidak"],["2","Panitia diberi pengarahan dan mengenakan tanda pengenal.","☐ Ya ☐ Tidak"],["3","Rundown dijalankan dengan menghormati waktu ibadah.","☐ Ya ☐ Tidak"],["4","Tata tertib disampaikan dan penyimpangan dicatat.","☐ Ya ☐ Tidak"],["5","Tempat dan aset diperiksa dan laporan awal disampaikan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-015","g":"Program Kerja dan Kegiatan","t":"Pengendalian Perubahan Jadwal atau Konsep","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Sekretaris Jenderal dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[62,65],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengajuan, penilaian, persetujuan, dan pemberitahuan perubahan jadwal atau konsep kegiatan agar setiap perubahan tercatat, disetujui pihak berwenang, dan tidak menimbulkan kekacauan administrasi, anggaran, maupun komunikasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk perubahan tanggal, waktu, tempat, konsep, narasumber utama, peserta sasaran, dan anggaran kegiatan setelah TOR atau proposal disetujui. Pembatalan atau penundaan seluruh program diatur pada SOP- PRO-022."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 (Wewenang BEM) huruf a (kebijakan pelaksanaan kegiatan).","ART Pasal 10 ayat (1) (Rapat Koordinasi untuk mengevaluasi pelaksanaan program kerja dan koordinasi).","ART Pasal 3 (Kewajiban) huruf e (pengelolaan keuangan amanah, transparan, akuntabel).","SOP-PRO-002, SOP-PRO-007, SOP-PRO-008, dan SOP-GOV-012."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Permintaan perubahan","Pengajuan tertulis untuk mengubah jadwal, konsep, atau komponen kegiatan yang telah disetujui."],["Perubahan minor","Perubahan kecil yang tidak mengubah tanggal, tempat, konsep inti, narasumber utama, atau anggaran secara berarti."],["Perubahan mayor","Perubahan tanggal, tempat, konsep inti, narasumber utama, sasaran peserta, atau anggaran melebihi batas toleransi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap perubahan diajukan tertulis melalui Formulir Permintaan Perubahan; perubahan lisan tidak berlaku.","Perubahan minor disetujui penanggung jawab program dan dicatat; perubahan mayor disetujui Wakil Presiden, dan untuk Kategori C atau perubahan yang menyentuh persetujuan kampus disetujui Presiden.","Perubahan anggaran melebihi 10% dari RAB disetujui Biro Keuangan dan Presiden (usulan) dan dilaporkan kepada KAUR ORMAWA bila dana berasal dari dana kemahasiswaan.","Perubahan yang memengaruhi izin tempat, izin kampus, atau persetujuan Pembina wajib diajukan ulang kepada pihak tersebut sebelum berlaku.","Perubahan mayor dalam 3 hari terakhir sebelum kegiatan hanya untuk alasan mendesak dan mengikuti SOP-GOV-012 (usulan).","Seluruh pihak terdampak (peserta, narasumber, pengelola tempat, kampus) diberi tahu tertulis secepatnya."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pengaju (ketua pelaksana atau penanggung jawab)","R","Mengisi Formulir Permintaan Perubahan dan menjelaskan alasan serta dampak."],["Wakil Presiden","A","Menilai dan menyetujui perubahan mayor serta bertanggung jawab atas pengendalian perubahan."],["Presiden","R","Menyetujui perubahan Kategori C dan perubahan yang menyentuh persetujuan kampus."],["Sekretaris Jenderal","R","Mencatat perubahan, memperbarui kalender dan dokumen, dan menyebarkan versi terbaru."],["Biro Keuangan","C","Menilai dampak anggaran."],["Biro Desain Komunikasi Visual","R","Mengoreksi publikasi dan memberi tahu peserta sesuai SOP-KOM-009."],["Seluruh panitia","I","Menjalankan versi terbaru."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["TOR, proposal, RAB, rundown, dan kalender yang berlaku.","Formulir Permintaan Perubahan.","Izin dan persetujuan yang telah diterbitkan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan perubahan: Mengisi Formulir Permintaan Perubahan: perubahan, alasan, dampak jadwal dan anggaran, dan pihak terdampak.","Pengaju","Kebutuhan perubahan","Formulir Permintaan Perubahan","Segera setelah kebutuhan muncul"],["2","Klasifikasi: Menetapkan perubahan sebagai minor atau mayor dan menentukan pihak penyetuju.","Sekjen, Wapres","Formulir","Klasifikasi perubahan","1 hari kerja"],["3","Penilaian dampak: Menilai dampak terhadap anggaran, izin, kalender, dan keselamatan.","Biro Keuangan, Sekjen","Formulir","Catatan dampak","1 hari kerja"],["4","Keputusan: Menyetujui, menyetujui bersyarat, atau menolak perubahan.","Penanggung jawab, Wapres, Presiden","Formulir, catatan dampak","Keputusan perubahan","2 hari kerja"],["5","Pengajuan ulang izin: Bila perlu, mengajukan ulang atau memberi tahu pihak kampus dan pengelola tempat.","Sekjen","Keputusan","Izin ulang atau pemberitahuan","Sesuai jadwal kampus"],["6","Pembaruan dokumen: Memperbarui TOR, RAB, rundown, kalender, dan nomor versi.","Sekjen, ketua pelaksana","Keputusan","Dokumen versi baru","1 hari kerja"],["7","Pemberitahuan: Memberi tahu peserta, narasumber, pengelola tempat, dan panitia; mengoreksi publikasi.","Biro Desain Komunikasi Visual, seksi acara","Dokumen versi baru","Pihak terdampak diberi tahu","1 hari kerja"],["8","Pencatatan: Mencatat pada Register Perubahan dan mengarsipkan.","Sekjen","Formulir, keputusan","Register diperbarui","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Perubahan minor diselesaikan dalam 1 hari kerja; perubahan mayor dalam 3 hari kerja sejak formulir lengkap, di luar waktu persetujuan kampus. Hasil akhir: keputusan perubahan dan dokumen versi baru."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Perbedaan penilaian klasifikasi: diputuskan Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Perubahan mendesak yang tidak dapat menunggu: ikuti SOP-GOV-012 dan ratifikasi pada rapat terdekat.","Persetujuan kampus untuk perubahan belum diperoleh: perubahan tidak berlaku; kegiatan mengikuti jadwal semula atau ditunda (SOP-PRO-022).","Perubahan berulang pada satu kegiatan: dicatat sebagai temuan (SOP-MONEV-009)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% perubahan memiliki Formulir Permintaan Perubahan dan keputusan tertulis.","Tidak ada perubahan mayor tanpa persetujuan pihak berwenang.","Pihak terdampak diberi tahu dalam 1 hari kerja pada 100% perubahan.","Jumlah perubahan mayor dalam 3 hari terakhir sebelum kegiatan menurun."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Permintaan Perubahan.","Keputusan perubahan.","Dokumen versi baru (TOR, RAB, rundown, kalender).","Register Perubahan.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa Register Perubahan dan konsistensi versi dokumen setiap bulan; Wakil Presiden meninjau perubahan berulang pada Rapat Koordinasi."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Ajukan perubahan → Klasifikasi → Nilai dampak → Keputusan → Izin ulang bila perlu → Perbarui dokumen → Beri tahu pihak terdampak → Catat → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Perubahan","Kegiatan; perubahan; alasan; dampak jadwal, anggaran, dan izin; pihak terdampak; pengaju; tanggal."],["Register Perubahan","Nomor; kegiatan; jenis perubahan; keputusan; penyetuju; tanggal; versi dokumen."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Perubahan diajukan tertulis beserta alasan dan dampaknya.","☐ Ya ☐ Tidak"],["2","Perubahan telah diklasifikasi dan disetujui pihak yang berwenang.","☐ Ya ☐ Tidak"],["3","Izin kampus dan pengelola tempat diperbarui bila terdampak.","☐ Ya ☐ Tidak"],["4","Dokumen dan kalender diperbarui dengan nomor versi.","☐ Ya ☐ Tidak"],["5","Seluruh pihak terdampak telah diberi tahu.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-016","g":"Program Kerja dan Kegiatan","t":"Penanganan Keterlambatan dan Kendala Lapangan","o":"Menteri / Kabiro Penanggung Jawab Program","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri / Kabiro penanggung jawab program","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[66,69],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pencatatan, penanganan, dan eskalasi keterlambatan dan kendala lapangan selama persiapan dan pelaksanaan kegiatan agar masalah ditangani cepat, pada tingkat yang tepat, dan menjadi bahan perbaikan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk kendala waktu, teknis, peserta, narasumber, tempat, cuaca, dan dana pada persiapan dan hari pelaksanaan. Keadaan darurat keselamatan mengikuti SOP-PRO-017; keterlambatan tugas pengurus mengikuti SOP-MONEV-008."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 10 ayat (4) huruf c (penyelesaian permasalahan internal pada Rapat Koordinasi).","ART Pasal 11 huruf l (larangan meninggalkan tanggung jawab tanpa alasan sah).","ART Pasal 12 (pembinaan dan penegakan disiplin).","SOP-PRO-014, SOP-PRO-015, dan SOP-GOV-012."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kendala lapangan","Hambatan yang mengganggu jalannya persiapan atau pelaksanaan kegiatan."],["Log Kendala","Catatan kejadian, waktu, penyebab, tindakan, dan penanggung jawab penanganan kendala."],["Eskalasi","Penyampaian masalah kepada tingkat pimpinan yang lebih tinggi karena melampaui kewenangan atau batas toleransi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Tingkat penanganan: Tingkat 1 koordinator lapangan atau seksi terkait; Tingkat 2 ketua pelaksana; Tingkat 3 penanggung jawab program dan Wakil Presiden; Tingkat 4 Presiden.","Kendala diselesaikan pada tingkat serendah mungkin; melapor ke tingkat berikutnya bila tidak selesai atau melampaui batas berikut (usulan): keterlambatan acara lebih dari 30 menit dilaporkan ke Tingkat 3; lebih dari 60 menit diputuskan lanjut, ubah, atau tunda.","Kendala yang menyangkut keselamatan langsung dialihkan ke SOP-PRO-017.","Setiap kendala dicatat pada Log Kendala dengan waktu dan tindakan.","Keputusan penanganan tidak boleh melanggar AD/ART, ART Pasal 11, aturan kampus, atau melebihi anggaran tanpa persetujuan (SOP-KEU-014).","Kendala berulang dibahas pada Rapat Koordinasi dan dicatat sebagai temuan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Koordinator lapangan","R","Menangani kendala tingkat 1 dan mencatat pada Log Kendala."],["Ketua pelaksana","R","Memutuskan penanganan tingkat 2 dan melapor bila perlu."],["Penanggung jawab program","A","Bertanggung jawab atas penanganan kendala dan keputusan tingkat 3."],["Wakil Presiden","C","Memberi arahan dan keputusan bersama penanggung jawab pada tingkat 3."],["Presiden","C","Memutuskan kendala tingkat 4, termasuk penundaan atau pembatalan."],["Sekretaris panitia","R","Memelihara Log Kendala dan menyerahkannya sebagai bahan LPJ dan evaluasi."],["Seluruh panitia","I","Menjalankan keputusan penanganan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Rundown dan Lembar Kendali Hari-H.","Kontak penanggung jawab tiap tingkat.","Log Kendala.","Batas toleransi waktu dan dana."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Identifikasi kendala: Mengenali dan melaporkan kendala kepada koordinator lapangan atau seksi terkait.","Panitia","Kejadian","Laporan kendala","Segera"],["2","Pencatatan: Mencatat waktu, jenis, dan dampak pada Log Kendala.","Sekretaris panitia","Laporan kendala","Entri Log Kendala","Segera"],["3","Penanganan tingkat 1: Menangani dengan sumber daya yang ada dan mencatat tindakan.","Koordinator lapangan","Log Kendala","Kendala tertangani atau dieskalasi","Segera"],["4","Penanganan tingkat 2: Memutuskan penyesuaian kecil pada rundown atau pembagian tugas.","Ketua pelaksana","Kendala dari tingkat 1","Keputusan penyesuaian","Segera"],["5","Eskalasi tingkat 3 dan 4: Melapor dan meminta keputusan bila melebihi batas; memutuskan lanjut, ubah (SOP-PRO-015), atau tunda (SOP-PRO-022).","Penanggung jawab, Wapres, Presiden","Laporan eskalasi","Keputusan tertulis atau tercatat","Segera; maksimal 2 jam saat hari-H"],["6","Pemberitahuan pihak terdampak: Memberi tahu peserta, narasumber, dan pengelola tempat tentang penyesuaian.","Seksi acara","Keputusan","Pihak terdampak diberi tahu","Segera"],["7","Penutupan dan pembelajaran: Menutup entri, mencatat penyebab akar, dan membawa kendala berulang ke Rapat Koordinasi.","Sekretaris panitia, ketua pelaksana","Log Kendala","Log final dan catatan pembelajaran","3 hari kerja setelah kegiatan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Kendala dicatat segera dan dilaporkan sesuai tingkat penanganan; keputusan tingkat 3 dan 4 pada hari-H diambil paling lambat 2 jam setelah laporan. Hasil akhir: Log Kendala dan keputusan penanganan."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kendala menyangkut keselamatan atau kesehatan: ikuti SOP-PRO-017.","Kekurangan dana mendadak: ikuti SOP-KEU-014.","Anggota panitia meninggalkan tugas tanpa alasan sah: ikuti SOP-SDM-011 dan ART Pasal 12.","Kendala memerlukan keputusan mendesak di luar jam rapat: ikuti SOP-GOV-012."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kendala tercatat pada Log Kendala.","Kendala tingkat 1 dan 2 tertangani tanpa eskalasi pada 80% kejadian.","Keputusan eskalasi hari-H diambil dalam 2 jam pada 100% kejadian.","Kendala berulang menurun dari kegiatan ke kegiatan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Log Kendala.","Keputusan penanganan.","Catatan pembelajaran.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden meninjau Log Kendala pada Rapat Koordinasi; Irjen mencatat kendala berulang sebagai temuan pada evaluasi berkala (SOP-MONEV-009)."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Identifikasi → Catat → Tangani tingkat 1 → Tangani tingkat 2 → Eskalasi tingkat 3 dan 4 → Beri tahu pihak terdampak → Tutup dan pembelajaran → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Log Kendala","Nomor; waktu; jenis; dampak; tindakan; penanggung jawab; tingkat; status; keputusan."],["Laporan Eskalasi","Kendala; waktu mulai; upaya yang dilakukan; opsi keputusan; pelapor; waktu lapor."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kendala dicatat pada Log Kendala dengan waktu dan tindakan.","☐ Ya ☐ Tidak"],["2","Penanganan dilakukan pada tingkat yang tepat.","☐ Ya ☐ Tidak"],["3","Kendala keselamatan dialihkan ke SOP-PRO-017.","☐ Ya ☐ Tidak"],["4","Keputusan eskalasi tercatat dan pihak terdampak diberi tahu.","☐ Ya ☐ Tidak"],["5","Kendala berulang dibawa ke Rapat Koordinasi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-017","g":"Program Kerja dan Kegiatan","t":"Keselamatan Peserta dan Keadaan Darurat","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Sekretaris Jenderal dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[70,73],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pencegahan dan penanganan keadaan darurat pada kegiatan agar keselamatan dan kesehatan peserta, panitia, dan narasumber terlindungi, tindakan dilakukan cepat, dan kejadian tercatat serta menjadi bahan perbaikan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kegiatan, termasuk kegiatan luar kampus dan menginap. Penilaian risiko sebelum kegiatan mengikuti SOP-RSK-002; penanganan kecelakaan dan keadaan darurat umum mengikuti SOP-RSK- 003; pencatatan insiden mengikuti SOP-RSK-012; dugaan perundungan atau pelecehan mengikuti SOP-RSK- 005."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Kewajiban) huruf d (menjaga ketertiban dan kedamaian dalam dan luar kampus).","ART Pasal 11 huruf c, f, dan h (larangan kekerasan, penyalahgunaan zat terlarang, dan tindakan asusila, pelecehan, atau perundungan).","ART Pasal 2 (Hak BEM) huruf j (kegiatan luar kampus dengan seizin kampus).","SOP-PRO-011 dan SOP-RSK-002, SOP-RSK-003, SOP-RSK-012."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Keadaan darurat","Kejadian yang mengancam keselamatan jiwa, kesehatan, atau keamanan peserta atau panitia dan memerlukan tindakan segera."],["Rencana Keselamatan Kegiatan","Dokumen ringkas berisi risiko utama, penanggung jawab, perlengkapan, jalur evakuasi, dan kontak darurat."],["Laporan Insiden","Catatan tertulis tentang kejadian, korban, tindakan, dan tindak lanjut."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap kegiatan memiliki penanggung jawab keamanan dan kesehatan, perlengkapan P3K, jalur evakuasi, dan daftar kontak darurat; kegiatan Kategori B dan C melengkapi Rencana Keselamatan Kegiatan.","Kapasitas tempat dan jumlah peserta tidak boleh melebihi batas aman; kegiatan luar kampus dan menginap wajib memiliki daftar peserta, pendamping, izin kampus, dan rencana transportasi aman.","Prioritas penanganan: keselamatan jiwa, pertolongan pertama sesuai kemampuan, menghubungi layanan medis atau pihak berwenang, lalu pelaporan kepada pimpinan.","Penanggung jawab program atau ketua pelaksana berwenang menghentikan atau mengubah kegiatan demi keselamatan; setiap panitia wajib menyampaikan peringatan bahaya.","Laporan Insiden dibuat paling lambat 24 jam setelah kejadian (usulan); kejadian serius dilaporkan segera kepada Wakil Presiden dan pihak kampus.","Komunikasi kepada keluarga dan publik dilakukan oleh pihak yang ditunjuk sesuai SOP-KOM-010 dan SOP-KOM-012."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Wakil Presiden","A","Bertanggung jawab akhir atas sistem keselamatan kegiatan dan keputusan lanjutan insiden."],["Penanggung jawab program","R","Memastikan Rencana Keselamatan tersedia dan memutuskan penghentian kegiatan bila perlu."],["Ketua pelaksana","R","Memimpin tindakan darurat di lapangan dan melaporkan kejadian."],["Seksi keamanan dan kesehatan","R","Menyiapkan perlengkapan, memberi pertolongan pertama, dan mengamankan jalur evakuasi."],["Presiden","C","Mengambil keputusan atas insiden serius dan komunikasi pimpinan."],["Sekretaris Jenderal","R","Mencatat Laporan Insiden dan mengarsipkannya."],["Peserta dan panitia","I","Mengikuti arahan keselamatan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Hasil penilaian risiko (SOP-RSK-002).","Daftar kontak darurat dan jalur evakuasi.","Daftar peserta dan panitia.","Perlengkapan P3K."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan rencana keselamatan: Menyusun Rencana Keselamatan Kegiatan: risiko, penanggung jawab, perlengkapan, jalur evakuasi, dan kontak darurat.","Seksi keamanan dan kesehatan","Penilaian risiko, TOR","Rencana Keselamatan","Paling lambat H-5"],["2","Pemeriksaan rencana: Memeriksa kecukupan rencana dan menyetujuinya.","Penanggung jawab, Wapres","Rencana Keselamatan","Rencana disetujui","2 hari kerja"],["3","Pemeriksaan fasilitas: Memeriksa jalur evakuasi, P3K, kapasitas, dan kondisi tempat sebelum acara.","Seksi keamanan dan kesehatan","Rencana, checklist","Pemeriksaan tercatat","H-1 dan sebelum acara"],["4","Pemantauan selama kegiatan: Memantau kondisi peserta, kerumunan, cuaca, konsumsi, dan tempat.","Seksi keamanan dan kesehatan","Rencana, rundown","Kondisi aman atau peringatan","Selama kegiatan"],["5","Tindakan darurat: Menghentikan atau mengubah kegiatan bila perlu; memberi pertolongan pertama; menghubungi layanan medis atau pihak berwenang.","Ketua pelaksana, seksi keamanan dan kesehatan","Kejadian, kontak darurat","Korban tertangani dan lokasi aman","Segera"],["6","Pelaporan segera: Melaporkan kejadian kepada penanggung jawab, Wakil Presiden, dan pihak kampus untuk kejadian serius.","Ketua pelaksana","Kejadian","Pimpinan mengetahui","Segera; maksimal 1 jam"],["7","Laporan Insiden: Membuat Laporan Insiden dan mencatat pada Register Insiden (SOP- RSK-012).","Sekjen, ketua pelaksana","Kejadian, tindakan","Laporan Insiden","24 jam"],["8","Tinjauan dan tindakan korektif: Meninjau insiden dan menetapkan tindakan korektif.","Wapres, Irjen","Laporan Insiden","Tindakan korektif","5 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Kejadian serius dilaporkan paling lambat 1 jam, Laporan Insiden dibuat paling lambat 24 jam, dan tindakan korektif ditetapkan paling lambat 5 hari kerja. Hasil akhir: korban tertangani, laporan insiden, dan tindakan korektif."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Korban memerlukan penanganan medis: hubungi layanan medis atau rumah sakit dan beri tahu pihak kampus; BEM tidak mengambil keputusan medis.","Dugaan kekerasan, perundungan, atau pelecehan: ikuti SOP-RSK-005 dan jaga kerahasiaan korban.","Dugaan penyalahgunaan zat terlarang atau tindak pidana: laporkan kepada pihak kampus dan pihak berwenang; ikuti ART Pasal 12 dan 13.","Kejadian menyedot perhatian publik atau media: ikuti SOP-KOM-012.","Keputusan mendesak di luar jam rapat: ikuti SOP-GOV-012."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kegiatan Kategori B dan C memiliki Rencana Keselamatan yang disetujui.","Perlengkapan P3K dan jalur evakuasi tersedia pada 100% kegiatan.","Laporan Insiden dibuat dalam 24 jam pada 100% kejadian.","Jumlah insiden menurun atau tidak meningkat dari kegiatan ke kegiatan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Rencana Keselamatan Kegiatan.","Daftar kontak darurat.","Laporan Insiden.","Register Insiden.","Catatan tindakan korektif.","Entri pada Register Dokumen. Laporan Insiden dan data korban termasuk informasi sensitif; disimpan pada repositori resmi BEM (folder Program Kerja, akses terbatas) oleh Sekretaris Jenderal sesuai SOP-RSK-010, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden meninjau Register Insiden setiap bulan; Irjen menilai kepatuhan Rencana Keselamatan dan tindakan korektif pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Rencana keselamatan → Periksa rencana → Periksa fasilitas → Pantau kegiatan → Tindakan darurat → Lapor segera → Laporan insiden → Tindakan korektif → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Rencana Keselamatan Kegiatan","Risiko utama; penanggung jawab; perlengkapan; jalur evakuasi; kapasitas; kontak darurat; rencana transportasi."],["Laporan Insiden","Waktu; tempat; kejadian; korban; tindakan; pelapor; tindak lanjut; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Rencana Keselamatan tersedia dan disetujui untuk Kategori B dan C.","☐ Ya ☐ Tidak"],["2","P3K, jalur evakuasi, dan kontak darurat tersedia.","☐ Ya ☐ Tidak"],["3","Kapasitas tempat tidak dilampaui.","☐ Ya ☐ Tidak"],["4","Kejadian dilaporkan sesuai batas waktu.","☐ Ya ☐ Tidak"],["5","Laporan Insiden dan tindakan korektif tercatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-018","g":"Program Kerja dan Kegiatan","t":"Dokumentasi dan Pengumpulan Bukti Kegiatan","o":"Kepala Biro Desain Komunikasi Visual","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Desain Komunikasi Visual","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Sekretaris Jenderal dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[74,77],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur dokumentasi dan pengumpulan bukti kegiatan agar setiap kegiatan memiliki catatan visual dan administratif yang lengkap, tertata, aman, dan dapat dipakai untuk pertanggungjawaban dan evaluasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk dokumentasi foto, video, dan dokumen bukti seluruh kegiatan. Pengelolaan foto dan video secara umum mengikuti SOP-KOM-011; penamaan file dan struktur folder mengikuti SOP-ADM-014; pengarsipan digital mengikuti SOP-ADM-013."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) dan (2) (pertanggungjawaban berkala; transparan dan akuntabel).","AD Pasal 15 ayat (3) (bukti resmi atas sumber dana).","ART Pasal 3 (Kewajiban) huruf g (laporan pertanggungjawaban kegiatan dan keuangan).","SOP-KOM-011, SOP-ADM-013, SOP-ADM-014, dan SOP-RSK-010."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Bukti kegiatan","Kumpulan dokumen dan dokumentasi yang membuktikan kegiatan terlaksana: daftar hadir, foto, video, notulen, materi, dan bukti keuangan."],["Register Bukti Kegiatan","Daftar bukti per kegiatan beserta lokasi penyimpanan dan penanggung jawab."],["Persetujuan dokumentasi","Pemberitahuan atau izin kepada peserta dan narasumber atas pengambilan dan penggunaan gambar atau rekaman."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Bukti minimal setiap kegiatan: TOR, proposal dan RAB, SK Kepanitiaan, izin tempat, daftar hadir, rundown, foto kegiatan, notulen atau laporan awal, dan salinan bukti pengeluaran.","Dokumentasi menghormati privasi dan nilai Islam; pengambilan gambar atau rekaman narasumber dan peserta dilakukan dengan pemberitahuan dan menghormati keberatan mereka.","Seluruh bukti disimpan di repositori resmi BEM dengan penamaan standar, tidak hanya pada perangkat atau akun pribadi.","Data pribadi dan bukti sensitif dibatasi aksesnya sesuai SOP-ADM-020 dan SOP-RSK-010.","Bukti harus lengkap sebelum LPJ disusun (SOP-PRO-020).","Dokumentasi dipakai untuk publikasi hanya setelah memenuhi SOP-KOM-007."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Seksi publikasi dan dokumentasi","R","Mengambil dokumentasi dan mengunggah ke repositori."],["Sekretaris panitia","R","Mengumpulkan dokumen bukti administratif dan memeriksa kelengkapan."],["Bendahara panitia","R","Menyerahkan salinan bukti pengeluaran."],["Biro Desain Komunikasi Visual","A","Bertanggung jawab atas standar dan keamanan dokumentasi visual."],["Sekretaris Jenderal","R","Memeriksa kelengkapan bukti, mengatur akses, dan mengarsipkan."],["Penanggung jawab program","C","Memastikan bukti lengkap sebelum LPJ."],["Peserta dan narasumber","I","Diberi tahu tentang dokumentasi kegiatan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar bukti minimal.","Daftar hadir dan rundown.","Hasil foto dan video.","Dokumen keuangan kegiatan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Rencana dokumentasi: Menetapkan petugas, kebutuhan foto dan video, dan pemberitahuan dokumentasi kepada peserta dan narasumber.","Seksi publikasi dan dokumentasi","TOR, rundown","Rencana dokumentasi","Paling lambat H-3"],["2","Pengambilan dokumentasi: Mengambil foto dan video sesuai rencana dengan menghormati privasi dan nilai Islam.","Seksi publikasi dan dokumentasi","Rencana dokumentasi","Dokumentasi mentah","Hari pelaksanaan"],["3","Penyaringan dan penamaan: Menyeleksi hasil dan menamai file sesuai standar.","Seksi publikasi dan dokumentasi","Dokumentasi mentah","Dokumentasi terpilih","2 hari kerja setelah kegiatan"],["4","Pengumpulan bukti administratif: Mengumpulkan daftar hadir, notulen, materi, izin, dan salinan bukti pengeluaran.","Sekretaris panitia, bendahara panitia","Dokumen kegiatan","Berkas bukti","3 hari kerja setelah kegiatan"],["5","Pengunggahan: Mengunggah dokumentasi dan bukti ke repositori resmi dengan struktur folder standar.","Seksi publikasi dan dokumentasi, sekretaris panitia","Dokumentasi terpilih, berkas bukti","Bukti tersimpan","4 hari kerja setelah kegiatan"],["6","Pemeriksaan kelengkapan: Memeriksa bukti dengan Register Bukti Kegiatan dan mengatur hak akses.","Sekjen","Repositori, register","Register lengkap","5 hari kerja setelah kegiatan"],["7","Penyerahan untuk LPJ: Menyatakan bukti lengkap kepada penanggung jawab untuk penyusunan LPJ.","Sekjen","Register lengkap","Bukti siap untuk LPJ","5 hari kerja setelah kegiatan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Bukti kegiatan ditargetkan lengkap dan tersimpan paling lambat 5 hari kerja setelah kegiatan. Hasil akhir: Register Bukti Kegiatan yang lengkap dan tersimpan pada repositori resmi."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Bukti tidak lengkap: penanggung jawab menetapkan batas tambahan; kekurangan dicatat pada LPJ.","Narasumber atau peserta keberatan atas dokumentasi: dokumentasi dihapus atau dibatasi penggunaannya.","Kehilangan atau kebocoran data dokumentasi: ikuti SOP-RSK-009.","Bukti keuangan tidak sah atau hilang: ikuti SOP-KEU-016 dan SOP-KEU-018."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kegiatan memiliki Register Bukti Kegiatan yang lengkap.","Bukti tersimpan pada repositori resmi paling lambat 5 hari kerja setelah kegiatan pada 90% kegiatan.","Tidak ada keberatan narasumber atau peserta yang tidak ditindaklanjuti.","Tidak ada bukti hanya tersimpan pada perangkat pribadi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Dokumentasi foto dan video terpilih.","Berkas bukti administratif.","Register Bukti Kegiatan.","Bukti pemberitahuan dokumentasi.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan Register Bukti Kegiatan setiap bulan; Irjen menilai kelengkapan bukti pada pemeriksaan berkala (SOP-MONEV-006)."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Rencana dokumentasi → Ambil dokumentasi → Seleksi dan nama → Kumpulkan bukti administratif → Unggah → Periksa kelengkapan → Serahkan untuk LPJ → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Register Bukti Kegiatan","Kegiatan; jenis bukti; nama file; lokasi; penanggung jawab; status; tanggal."],["Rencana Dokumentasi","Petugas; titik dokumentasi; kebutuhan; pemberitahuan kepada peserta dan narasumber."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Bukti minimal kegiatan telah terkumpul.","☐ Ya ☐ Tidak"],["2","Dokumentasi menghormati privasi dan nilai Islam.","☐ Ya ☐ Tidak"],["3","File diberi nama standar dan disimpan pada repositori resmi.","☐ Ya ☐ Tidak"],["4","Akses data sensitif dibatasi.","☐ Ya ☐ Tidak"],["5","Register Bukti Kegiatan lengkap dan diserahkan untuk LPJ.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-019","g":"Program Kerja dan Kegiatan","t":"Pembubaran Panitia dan Pengembalian Perlengkapan","o":"Menteri / Kabiro Penanggung Jawab Program","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri / Kabiro penanggung jawab program","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Sekretaris Jenderal dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[78,81],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pembubaran panitia kegiatan dan pengembalian seluruh perlengkapan, dokumen, dan dana agar tanggung jawab panitia berakhir secara tertib, aset kembali, dan tidak ada kewajiban yang tertinggal."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh panitia setelah kegiatan selesai. Pengembalian aset mengikuti SOP-AST-004; penanganan aset rusak atau hilang mengikuti SOP-AST-007; penyusunan LPJ mengikuti SOP-PRO-020."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 (Wewenang BEM) huruf c (pembentukan panitia dan tim kerja internal).","ART Pasal 3 (Kewajiban) huruf e dan g (pengelolaan keuangan amanah; laporan pertanggungjawaban).","ART Pasal 11 huruf i dan k (larangan penyelewengan dana dan penggunaan fasilitas untuk kepentingan pribadi).","SOP-PRO-006 (SK Kepanitiaan) dan SOP-PRO-018."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pembubaran panitia","Pengakhiran tugas panitia melalui keputusan setelah seluruh kewajiban diselesaikan."],["Berita Acara Pengembalian","Dokumen penyerahan kembali perlengkapan, dokumen, dan dana beserta kondisinya."],["Kewajiban tertinggal","Tagihan, pinjaman, atau tugas yang belum diselesaikan panitia."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Panitia baru dapat dibubarkan setelah perlengkapan dikembalikan, bukti terkumpul, LPJ diserahkan (SOP-PRO-020), dan tidak ada kewajiban tertinggal.","Seluruh aset pinjaman dikembalikan kepada pemilik dan kondisinya dicatat; kerusakan atau kehilangan dilaporkan segera.","Sisa dana dikembalikan kepada Biro Keuangan sesuai SOP-KEU-018; panitia tidak boleh menyimpan dana atau barang atas nama sendiri.","Pembubaran ditetapkan Presiden melalui Surat Keputusan Pembubaran atau pernyataan dalam LPJ yang disahkan.","Pemberian apresiasi kepada panitia mengikuti SOP-SDM-012."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan pembubaran panitia."],["Penanggung jawab program","R","Memastikan seluruh kewajiban selesai sebelum pembubaran."],["Ketua pelaksana","R","Memimpin pengembalian perlengkapan dan penyerahan berkas."],["Seksi perlengkapan","R","Mengembalikan aset dan memeriksa kondisinya."],["Bendahara panitia","R","Menyerahkan sisa dana dan bukti kepada Biro Keuangan."],["Sekretaris Jenderal","R","Memeriksa kelengkapan serah terima dan mengarsipkan berita acara."],["Biro Keuangan","C","Memeriksa sisa dana dan bukti."],["Pemilik aset atau pengelola tempat","I","Menerima pengembalian dan menyatakan kondisi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar peminjaman aset dan tempat.","Register Bukti Kegiatan.","Rekap pengeluaran dan sisa dana.","SK Kepanitiaan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Inventarisasi kewajiban: Mendata aset pinjaman, tempat, tagihan, dana, dan berkas yang harus diselesaikan.","Ketua pelaksana, sekretaris panitia","Daftar peminjaman, rekap","Daftar Kewajiban Panitia","1 hari kerja setelah kegiatan"],["2","Pengembalian perlengkapan: Mengembalikan aset dan tempat; mengisi berita acara kondisi bersama pemilik.","Seksi perlengkapan","Daftar peminjaman","Berita Acara Pengembalian","2 hari kerja setelah kegiatan"],["3","Penanganan kerusakan atau kehilangan: Melaporkan dan menyelesaikan sesuai SOP-AST-007.","Ketua pelaksana, seksi perlengkapan","Berita acara","Penyelesaian kerusakan atau kehilangan","5 hari kerja"],["4","Penyelesaian keuangan: Menyerahkan sisa dana dan bukti kepada Biro Keuangan.","Bendahara panitia, Biro Keuangan","Rekap, sisa dana","Bukti penyerahan dana","3 hari kerja"],["5","Penyerahan berkas: Menyerahkan seluruh berkas panitia kepada Sekretaris Jenderal.","Sekretaris panitia","Berkas panitia","Berkas terarsip","4 hari kerja"],["6","Pemeriksaan penutupan: Memeriksa daftar kewajiban dan Checklist Penutupan Panitia.","Sekjen, Biro Keuangan","Daftar kewajiban, checklist","Hasil pemeriksaan","2 hari kerja"],["7","Pembubaran: Menetapkan pembubaran panitia dan memberi tahu seluruh anggota.","Presiden, Sekjen","Hasil pemeriksaan, LPJ","Pembubaran panitia","Setelah LPJ disahkan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pengembalian perlengkapan dan dana ditargetkan selesai paling lambat 5 hari kerja setelah kegiatan; pembubaran ditetapkan setelah LPJ disahkan. Hasil akhir: Berita Acara Pengembalian dan keputusan pembubaran."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Aset rusak atau hilang: ikuti SOP-AST-007 dan tentukan penggantian.","Dana tidak sesuai atau bukti tidak lengkap: ikuti SOP-KEU-016 dan SOP-KEU-018.","Panitia tidak menyelesaikan kewajiban: penanggung jawab menetapkan batas akhir; dugaan pelanggaran ditangani sesuai ART Pasal 12 dan 13.","Dugaan penyalahgunaan dana atau aset: ikuti SOP-RSK-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% panitia dibubarkan dengan Berita Acara Pengembalian lengkap.","Seluruh aset pinjaman kembali dalam 2 hari kerja pada 90% kegiatan.","Tidak ada kewajiban tertinggal saat panitia dibubarkan.","Sisa dana diserahkan paling lambat 3 hari kerja pada 100% kegiatan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Kewajiban Panitia.","Berita Acara Pengembalian.","Bukti penyerahan sisa dana.","Keputusan pembubaran panitia.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan penutupan setiap kegiatan; Irjen menilai kepatuhan pada pemeriksaan berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Inventarisasi kewajiban → Kembalikan perlengkapan → Selesaikan keuangan → Serahkan berkas → Periksa penutupan → Pembubaran panitia → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Kewajiban Panitia","Aset pinjaman; tempat; tagihan; sisa dana; berkas; penanggung jawab; status."],["Berita Acara Pengembalian","Barang atau tempat; kondisi; penyerah; penerima; tanggal; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh aset dan tempat telah dikembalikan dengan berita acara.","☐ Ya ☐ Tidak"],["2","Kerusakan atau kehilangan telah diselesaikan.","☐ Ya ☐ Tidak"],["3","Sisa dana dan bukti telah diserahkan kepada Biro Keuangan.","☐ Ya ☐ Tidak"],["4","Seluruh berkas panitia telah diserahkan dan diarsipkan.","☐ Ya ☐ Tidak"],["5","Keputusan pembubaran telah terbit setelah LPJ disahkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-020","g":"Program Kerja dan Kegiatan","t":"Penyusunan Laporan Pertanggungjawaban Kegiatan","o":"Menteri / Kabiro Penanggung Jawab Program","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri / Kabiro penanggung jawab program","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Biro Keuangan dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[82,85],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan, pemeriksaan, pengesahan, dan penyampaian Laporan Pertanggungjawaban (LPJ) kegiatan agar pelaksanaan kegiatan dan penggunaan dana dipertanggungjawabkan secara transparan dan akuntabel."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kegiatan, termasuk yang tidak memakai dana (dengan LPJ ringkas). Pelaporan keuangan kegiatan mengikuti SOP-KEU-015; pemeriksaan bukti mengikuti SOP-KEU-016; pemeriksaan pertanggungjawaban oleh Irjen mengikuti SOP-MONEV-007."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) sampai (3) (laporan pertanggungjawaban berkala; transparan dan akuntabel; disampaikan kepada BPM untuk dibahas dalam Mubes dan dilaporkan kepada KAUR ORMAWA).","ART Bab III (Tugas) Pasal 3 huruf e (laporan pertanggungjawaban anggaran dan program).","ART Pasal 3 (Kewajiban) huruf e dan g (pengelolaan keuangan amanah; laporan berkala).","AD Pasal 15 ayat (3) (bukti resmi) dan SOP-PRO-018."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["LPJ","Laporan Pertanggungjawaban kegiatan yang memuat pelaksanaan, capaian, keuangan, kendala, dan rekomendasi."],["Laporan keuangan kegiatan","Rekap pemasukan dan pengeluaran kegiatan beserta bukti dan selisih terhadap RAB."],["Pengesahan LPJ","Persetujuan tertulis atas LPJ oleh pihak yang berwenang."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["LPJ disusun ketua pelaksana bersama bendahara panitia dan diserahkan paling lambat 14 hari kerja setelah kegiatan (usulan), atau sesuai jadwal kampus bila lebih singkat.","Isi minimal: latar belakang, pelaksanaan dan capaian terhadap indikator, daftar peserta, laporan keuangan dan selisih terhadap RAB, kendala dan pembelajaran, rekomendasi, serta lampiran bukti.","Laporan keuangan wajib disertai bukti sah dan lolos pemeriksaan Biro Keuangan sebelum disahkan.","LPJ disahkan penanggung jawab program dan Presiden; LPJ kegiatan yang menggunakan dana kemahasiswaan disampaikan juga kepada KAUR ORMAWA sesuai jadwal kampus.","Ringkasan LPJ seluruh kegiatan menjadi bahan pertanggungjawaban akhir masa jabatan kepada BPM dalam Mubes (AD Pasal 17 ayat 3).","Panitia yang belum menyerahkan LPJ tidak dapat dibubarkan dan kegiatan baru penanggung jawab terkait dapat ditunda (usulan)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Ketua pelaksana","R","Menyusun LPJ dan menyerahkannya tepat waktu."],["Bendahara panitia","R","Menyusun laporan keuangan dan menyerahkan bukti."],["Penanggung jawab program","A","Bertanggung jawab atas kebenaran dan kelengkapan LPJ serta mengesahkannya."],["Biro Keuangan","R","Memeriksa bukti dan laporan keuangan (SOP-KEU-016)."],["Inspektur Jenderal","C","Memeriksa kelengkapan dan kesesuaian LPJ."],["Presiden","R","Mengesahkan LPJ atas nama BEM."],["Sekretaris Jenderal","R","Memeriksa administrasi, mengarsipkan, dan menyampaikan kepada pihak berwenang."],["KAUR ORMAWA dan BPM","I","Menerima laporan sesuai kewenangan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Register Bukti Kegiatan.","Rekap pengeluaran dan bukti pembayaran.","Proposal, RAB, dan SK Kepanitiaan.","Laporan awal kegiatan dan Log Kendala.","Hasil evaluasi awal peserta bila ada."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan draf LPJ: Menyusun narasi pelaksanaan, capaian indikator, kendala, dan rekomendasi.","Ketua pelaksana","Laporan awal, Log Kendala","Draf narasi LPJ","7 hari kerja setelah kegiatan"],["2","Penyusunan laporan keuangan: Menyusun rekap pemasukan dan pengeluaran, selisih terhadap RAB, dan menyusun bukti.","Bendahara panitia","Rekap, bukti","Laporan keuangan kegiatan","7 hari kerja setelah kegiatan"],["3","Pemeriksaan keuangan: Memeriksa bukti dan laporan keuangan dengan checklist.","Biro Keuangan","Laporan keuangan, bukti","Hasil pemeriksaan","3 hari kerja"],["4","Pemeriksaan kelengkapan dan kesesuaian: Memeriksa kelengkapan LPJ dan kesesuaian dengan proposal serta aturan.","Sekjen, Irjen","Draf LPJ, hasil pemeriksaan keuangan","Catatan pemeriksaan","3 hari kerja"],["5","Revisi: Memperbaiki LPJ sesuai catatan.","Ketua pelaksana, bendahara panitia","Catatan pemeriksaan","LPJ revisi","3 hari kerja"],["6","Pengesahan: Mengesahkan LPJ.","Penanggung jawab, Presiden","LPJ revisi","LPJ sah","2 hari kerja"],["7","Penyampaian dan pengarsipan: Menyampaikan LPJ kepada KAUR ORMAWA bila diwajibkan, mengarsipkan, dan mencatat pada Register Dokumen.","Sekjen","LPJ sah","LPJ tersampaikan dan terarsip","2 hari kerja setelah pengesahan"],["8","Pencatatan pembelajaran: Menyalin catatan pembelajaran ke bahan evaluasi program (SOP-PRO- 021).","Sekjen","LPJ sah","Bahan evaluasi","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"LPJ ditargetkan diserahkan paling lambat 14 hari kerja setelah kegiatan dan disahkan paling lambat 7 hari kerja setelah penyerahan, atau sesuai jadwal kampus bila lebih singkat. Hasil akhir: LPJ yang sah dan terarsip."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["LPJ terlambat: penanggung jawab menetapkan batas akhir; keterlambatan dicatat sebagai temuan (SOP-MONEV-008).","Bukti keuangan tidak lengkap atau tidak sah: ikuti SOP-KEU-016 dan SOP-KEU-018; selisih ditangani sesuai SOP-KEU-014.","Dugaan penyalahgunaan dana: ikuti SOP-RSK-007.","Kampus meminta format atau jadwal berbeda: mengikuti ketentuan kampus dan Sekjen memperbarui templat."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kegiatan memiliki LPJ yang sah.","LPJ diserahkan dalam 14 hari kerja pada 90% kegiatan.","Tidak ada temuan bukti tidak sah yang tidak ditindaklanjuti.","Selisih terhadap RAB dijelaskan pada 100% LPJ."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["LPJ kegiatan beserta lampiran.","Laporan keuangan kegiatan.","Hasil pemeriksaan Biro Keuangan dan Irjen.","Bukti penyampaian kepada pihak berwenang.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memantau status LPJ seluruh kegiatan setiap bulan pada Register LPJ; Irjen menilai kepatuhan pada pemeriksaan pertanggungjawaban keuangan (SOP-MONEV-007)."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Draf LPJ dan laporan keuangan → Periksa keuangan → Periksa kelengkapan Irjen → Revisi → Pengesahan → Sampaikan dan arsip → Catat pembelajaran → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat LPJ Kegiatan","Latar belakang; pelaksanaan; capaian; peserta; keuangan; kendala; rekomendasi; lampiran bukti."],["Templat Laporan Keuangan Kegiatan","Pemasukan; pengeluaran per pos; selisih terhadap RAB; sisa dana; bukti."],["Register LPJ","Kegiatan; penanggung jawab; tanggal serah; tanggal sah; status."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","LPJ memuat seluruh isi minimal.","☐ Ya ☐ Tidak"],["2","Laporan keuangan dilengkapi bukti sah dan telah diperiksa Biro Keuangan.","☐ Ya ☐ Tidak"],["3","Selisih terhadap RAB dijelaskan.","☐ Ya ☐ Tidak"],["4","LPJ disahkan penanggung jawab dan Presiden.","☐ Ya ☐ Tidak"],["5","LPJ disampaikan kepada pihak berwenang dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-021","g":"Program Kerja dan Kegiatan","t":"Evaluasi Hasil dan Dampak Kegiatan","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Sekretaris Jenderal dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[86,89],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur evaluasi hasil dan dampak kegiatan agar capaian dinilai berdasarkan indikator, umpan balik peserta dikumpulkan, dan pembelajaran dipakai untuk memperbaiki program berikutnya."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kegiatan setelah selesai. Evaluasi program kerja secara keseluruhan mengikuti SOP- MONEV-004; evaluasi tengah periode mengikuti SOP-MONEV-011."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 10 ayat (1) dan (4) (Rapat Koordinasi untuk mengevaluasi pelaksanaan program).","AD Pasal 14 huruf d (Rapat Evaluasi sebagai salah satu cara pengambilan keputusan).","ART Pasal 7 ayat (5) huruf c (evaluasi kinerja organisasi pada Mubes).","SOP-PRO-007 (indikator keberhasilan), SOP-PRO-018, dan SOP-PRO-020."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Evaluasi kegiatan","Penilaian capaian kegiatan terhadap indikator dan tujuan beserta penyebab keberhasilan atau kekurangannya."],["Umpan balik","Masukan peserta, narasumber, dan panitia tentang kegiatan."],["Tindak lanjut","Perbaikan yang ditetapkan dan dilaksanakan berdasarkan hasil evaluasi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Evaluasi menggunakan indikator pada TOR, data kehadiran, umpan balik peserta, laporan keuangan, dan Log Kendala.","Umpan balik dikumpulkan dengan formulir ringkas dan bersifat anonim bila peserta menghendaki.","Rapat Evaluasi kegiatan Kategori B dan C dilaksanakan paling lambat 14 hari kerja setelah kegiatan (usulan); Kategori A cukup dibahas pada Rapat Koordinasi.","Dampak diukur secara wajar menurut kemampuan: manfaat bagi peserta, kesesuaian dengan tujuan BEM, dan tindak lanjut yang dihasilkan.","Hasil evaluasi tidak dipakai menyalahkan individu; temuan pelanggaran ditangani sesuai ART Pasal 12 dan 13.","Tindak lanjut wajib memiliki penanggung jawab dan batas waktu, serta dipantau pada program berikutnya."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Wakil Presiden","A","Memimpin Rapat Evaluasi dan bertanggung jawab atas pemanfaatan hasil evaluasi."],["Penanggung jawab program","R","Menyusun bahan evaluasi dan menyampaikan hasilnya."],["Ketua pelaksana","R","Mengumpulkan data kegiatan dan menjelaskan pelaksanaan."],["Seksi publikasi dan dokumentasi","R","Menyiapkan dan mengumpulkan umpan balik peserta."],["Sekretaris Jenderal","R","Mencatat hasil evaluasi, menyebarkan, dan memantau tindak lanjut."],["Inspektur Jenderal","C","Memberi catatan kepatuhan prosedur dan temuan berulang."],["Presiden","I","Menerima laporan hasil evaluasi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["TOR dan indikator keberhasilan.","LPJ dan laporan keuangan.","Hasil umpan balik peserta.","Log Kendala dan laporan awal kegiatan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengumpulan umpan balik: Membagikan formulir umpan balik kepada peserta, narasumber, dan panitia.","Seksi publikasi dan dokumentasi","Formulir umpan balik","Umpan balik terkumpul","3 hari kerja setelah kegiatan"],["2","Penyusunan bahan evaluasi: Merangkum capaian terhadap indikator, umpan balik, keuangan, dan kendala.","Penanggung jawab, ketua pelaksana","Data kegiatan, umpan balik","Ringkasan evaluasi","7 hari kerja setelah kegiatan"],["3","Rapat Evaluasi: Membahas capaian, penyebab, dan usulan perbaikan; mencatat keputusan.","Wapres, panitia, penanggung jawab","Ringkasan evaluasi","Keputusan dan notulen","Paling lambat 14 hari kerja"],["4","Penetapan tindak lanjut: Menetapkan tindak lanjut beserta penanggung jawab dan batas waktu.","Wapres, Sekjen","Keputusan rapat","Daftar tindak lanjut","2 hari kerja"],["5","Penyusunan Laporan Evaluasi: Menyusun Laporan Evaluasi Kegiatan dan menyebarkannya.","Sekjen","Notulen, daftar tindak lanjut","Laporan Evaluasi","3 hari kerja"],["6","Pemantauan tindak lanjut: Memantau tindak lanjut pada Rapat Koordinasi hingga selesai (SOP- ADM-010).","Sekjen, Wapres","Daftar tindak lanjut","Status tindak lanjut","Setiap Rapat Koordinasi"],["7","Pemanfaatan pembelajaran: Memasukkan pembelajaran ke perencanaan program berikutnya dan evaluasi tengah periode.","Wapres, Irjen","Laporan Evaluasi","Pembelajaran terdokumentasi","Setiap perencanaan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Evaluasi ditargetkan selesai dan Laporan Evaluasi diterbitkan paling lambat 21 hari kerja setelah kegiatan Kategori B dan C. Hasil akhir: Laporan Evaluasi Kegiatan dan daftar tindak lanjut."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Penanggung jawab terlambat menyiapkan bahan: dicatat sesuai SOP-MONEV-008 dan Rapat Evaluasi tetap dijadwalkan.","Perbedaan penilaian capaian: diputuskan Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Temuan dugaan pelanggaran saat evaluasi: ikuti ART Pasal 12 dan 13 dan SOP-SDM-013.","Evaluasi darurat atas kegiatan bermasalah berat: ikuti SOP-GOV-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kegiatan Kategori B dan C memiliki Laporan Evaluasi.","Umpan balik peserta terkumpul dari paling sedikit 50% peserta (usulan).","100% tindak lanjut memiliki penanggung jawab dan batas waktu.","Tindak lanjut selesai tepat waktu pada 80% kasus."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir umpan balik dan rekapnya.","Notulen Rapat Evaluasi.","Laporan Evaluasi Kegiatan.","Daftar tindak lanjut.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memantau tindak lanjut setiap Rapat Koordinasi; Irjen menilai pemanfaatan pembelajaran pada evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kumpulkan umpan balik → Susun bahan evaluasi → Rapat Evaluasi → Tetapkan tindak lanjut → Laporan Evaluasi → Pantau tindak lanjut → Manfaatkan pembelajaran → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Umpan Balik Peserta","Penilaian materi, panitia, tempat, dan waktu; manfaat; saran; identitas bersifat opsional."],["Templat Laporan Evaluasi Kegiatan","Capaian indikator; ringkasan umpan balik; kendala; keuangan; kesimpulan; tindak lanjut."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Umpan balik peserta telah dikumpulkan dan direkap.","☐ Ya ☐ Tidak"],["2","Capaian dinilai terhadap indikator pada TOR.","☐ Ya ☐ Tidak"],["3","Rapat Evaluasi dilaksanakan dan dinotulenkan.","☐ Ya ☐ Tidak"],["4","Tindak lanjut memiliki penanggung jawab dan batas waktu.","☐ Ya ☐ Tidak"],["5","Laporan Evaluasi disebarkan dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PRO-022","g":"Program Kerja dan Kegiatan","t":"Pembatalan atau Penundaan Program Kerja","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[90,93],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pembatalan atau penundaan program kerja agar keputusan diambil oleh pihak berwenang dengan alasan jelas, dampak terhadap peserta, dana, dan pihak luar diselesaikan, serta perubahan tercatat."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pembatalan atau penundaan seluruh program atau kegiatan yang telah disetujui, baik dari RKT maupun program baru. Perubahan sebagian jadwal atau konsep diatur pada SOP-PRO-015; keputusan mendesak diatur pada SOP-GOV-012."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 (Wewenang BEM) huruf a (kebijakan pelaksanaan kegiatan kemahasiswaan).","ART Pasal 9 ayat (5) dan (6) (RKT sebagai pedoman dan persetujuan Pembina).","ART Pasal 3 (Kewajiban) huruf e dan g (pengelolaan keuangan amanah dan pelaporan).","SOP-PRO-005, SOP-PRO-015, SOP-GOV-012, dan SOP-KEU-018."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pembatalan","Penghentian program secara tetap sehingga tidak dilaksanakan pada periode kabinet berjalan."],["Penundaan","Pemindahan pelaksanaan program ke waktu lain dengan jadwal baru yang ditetapkan."],["Dampak pembatalan atau penundaan","Akibat terhadap peserta, narasumber, dana, kontrak, izin, dan citra organisasi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pembatalan atau penundaan diputuskan Presiden setelah mendapat pertimbangan Wakil Presiden dan penanggung jawab program; Kategori C atau program yang dibiayai dana kemahasiswaan dilaporkan juga kepada KAUR ORMAWA dan Pembina.","Alasan sah antara lain: larangan atau penolakan izin kampus, keadaan darurat, ancaman keselamatan, ketidaktersediaan dana, kekurangan peserta atau narasumber, atau pertentangan dengan AD/ART atau aturan kampus.","Keputusan harus tertulis, memuat alasan, dampak, dan penanganan hak peserta, narasumber, serta penyedia.","Dana yang telah dicairkan tidak boleh dipakai untuk keperluan lain tanpa persetujuan; sisa dana dikembalikan sesuai SOP-KEU-018 atau dialihkan melalui SOP-PRO-015.","Pembatalan atau penundaan diumumkan melalui kanal resmi secepat mungkin dan tidak berbelit-belit.","Program yang dibatalkan tetap dicatat pada Register Program dengan status dan alasan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Memutuskan pembatalan atau penundaan dan menandatangani keputusan."],["Wakil Presiden","R","Menyusun pertimbangan, menilai dampak, dan memantau pelaksanaan keputusan."],["Penanggung jawab program","R","Mengajukan usulan atau menanggapi dan melaksanakan penanganan dampak."],["Biro Keuangan","R","Menangani dana, kewajiban pembayaran, dan pengembalian."],["Sekretaris Jenderal","R","Mencatat keputusan, memperbarui kalender dan register, serta menyampaikan surat pemberitahuan."],["Biro Desain Komunikasi Visual","R","Menerbitkan pengumuman resmi (SOP-KOM-009)."],["Inspektur Jenderal","C","Memberi catatan kesesuaian alasan dan penanganan dampak."],["KAUR ORMAWA, Pembina, peserta, dan narasumber","I","Diberi tahu secara tertulis."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Usulan atau laporan alasan pembatalan atau penundaan.","Data anggaran, kontrak, dan izin yang telah terbit.","Daftar peserta, narasumber, dan penyedia.","Kalender program kerja."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan atau pelaporan: Menyampaikan usulan dan alasan pembatalan atau penundaan beserta data pendukung.","Penanggung jawab","Alasan, data","Usulan tertulis","Segera setelah alasan muncul"],["2","Penilaian dampak: Menilai dampak terhadap peserta, narasumber, dana, kontrak, izin, dan citra.","Wapres, Biro Keuangan","Usulan, data anggaran","Catatan dampak","1 hari kerja"],["3","Pemeriksaan kesesuaian: Memeriksa kesesuaian alasan dan penanganan dampak dengan AD/ART dan aturan kampus.","Irjen","Usulan, catatan dampak","Catatan keselarasan","1 hari kerja"],["4","Keputusan: Memutuskan batal, tunda dengan jadwal baru, atau lanjut; menerbitkan Keputusan Presiden.","Presiden","Catatan dampak dan keselarasan","Keputusan tertulis","1 hari kerja"],["5","Pemberitahuan resmi: Memberi tahu KAUR ORMAWA atau Pembina (bila perlu), pengelola tempat, narasumber, penyedia, dan peserta; menerbitkan pengumuman.","Sekjen, Biro Desain Komunikasi Visual","Keputusan","Pihak terdampak diberi tahu","1 hari kerja"],["6","Penyelesaian dana dan kewajiban: Menyelesaikan pembayaran, pengembalian, dan hak peserta atau penyedia; mengembalikan sisa dana.","Biro Keuangan, bendahara panitia","Keputusan, data kontrak","Kewajiban selesai","5 hari kerja"],["7","Pembaruan catatan: Memperbarui Register Program, RKT, dan kalender; menetapkan jadwal baru bila ditunda.","Sekjen","Keputusan","Register dan kalender diperbarui","1 hari kerja"],["8","Laporan dan pembelajaran: Mencatat pembelajaran dan melaporkan pada Rapat Koordinasi terdekat.","Wapres, Sekjen","Keputusan, catatan dampak","Laporan dan catatan pembelajaran","Rapat Koordinasi terdekat"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Keputusan ditargetkan terbit paling lambat 3 hari kerja setelah usulan lengkap, dan segera bila kegiatan dekat dengan hari pelaksanaan. Hasil akhir: Keputusan Presiden, pemberitahuan resmi, dan penyelesaian dana serta kewajiban."},{"note":"Catatan: angka waktu, kuorum, nilai batas, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Keputusan mendesak di luar jam rapat: ikuti SOP-GOV-012 dan ratifikasi pada rapat terdekat.","Pembatalan akibat keadaan darurat atau keselamatan: ikuti SOP-PRO-017 dan SOP-RSK-003.","Penyedia atau narasumber menuntut ganti rugi: dibahas Biro Keuangan dan Wakil Presiden; diputuskan Presiden; hal yang menyentuh kerja sama mengikuti SOP-HKE-006.","Pembatalan menyentuh persetujuan BPM, KAUR ORMAWA, atau Pembina: dilaporkan dan perubahan program diajukan sesuai ketentuan.","Penolakan keputusan oleh pengusul: diputuskan Presiden pada Rapat Pimpinan (SOP-GOV-005)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pembatalan atau penundaan memiliki keputusan tertulis.","Seluruh pihak terdampak diberi tahu dalam 1 hari kerja.","Kewajiban dana diselesaikan dalam 5 hari kerja pada 90% kasus.","Register Program dan kalender diperbarui dalam 1 hari kerja pada 100% kasus."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Keputusan Presiden tentang pembatalan atau penundaan.","Catatan dampak.","Pengumuman dan surat pemberitahuan.","Bukti penyelesaian dana dan kewajiban.","Register Program yang diperbarui.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Program Kerja) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan keputusan dan pemberitahuan setiap bulan; Irjen menilai penanganan dampak pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Usulan dan alasan → Nilai dampak → Periksa aturan Irjen → Keputusan Presiden → Beri tahu pihak terdampak → Selesaikan dana dan kewajiban → Perbarui catatan → Laporan dan pembelajaran → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Keputusan Pembatalan atau Penundaan","Nomor; program; alasan; dampak; penanganan hak pihak terdampak; jadwal baru; tanggal; tanda tangan."],["Lembar Penilaian Dampak","Peserta; narasumber; dana; kontrak; izin; citra; usulan penanganan; penilai."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Alasan pembatalan atau penundaan tertulis dan sah.","☐ Ya ☐ Tidak"],["2","Dampak terhadap peserta, dana, kontrak, dan izin telah dinilai.","☐ Ya ☐ Tidak"],["3","Keputusan Presiden telah terbit.","☐ Ya ☐ Tidak"],["4","Seluruh pihak terdampak telah diberi tahu secara tertulis.","☐ Ya ☐ Tidak"],["5","Dana, kewajiban, Register Program, dan kalender telah diselesaikan atau diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADV-001","g":"Advokasi dan Aspirasi Mahasiswa","t":"Penerimaan Aspirasi Mahasiswa","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[108,111],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan kanal, tata cara, dan standar layanan penerimaan aspirasi, kritik, saran, dan keluhan mahasiswa kepada BEM, sehingga setiap aspirasi tercatat, mendapat tanda terima, dan tidak hilang di jalur informal."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk Wakil Presiden, Unit Advokasi, Sekretaris Jenderal, Biro Kesekretariatan, Biro Desain Komunikasi Visual, dan seluruh pengurus BEM Kabinet Samasta yang menerima aspirasi mahasiswa aktif STDIIS Jember, baik melalui kanal resmi maupun secara tidak resmi (pesan pribadi, tatap muka, atau titipan). SOP ini tidak mengatur klasifikasi (SOP-ADV-002), verifikasi (SOP-ADV-003), dan pengaduan rahasia (SOP-ADV-010)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 4 ayat (1) dan (2) (kedaulatan di tangan mahasiswa; prinsip partisipatif, kolaboratif, dan demokratis).","AD Pasal 5 (fungsi BEM sebagai wadah dan media pembelajaran tanggung jawab serta amanah).","ART Pasal 2 huruf g dan h (hak menyampaikan aspirasi, kritik, dan saran kepada kampus; mengkritisi kebijakan kampus secara konstruktif dan beretika).","ART Pasal 3 (Kewajiban BEM) huruf d dan g (menjaga nama baik dan ketertiban; membuat laporan berkala).","ART Pasal 4 (Wewenang BEM) huruf e (mewakili mahasiswa dalam forum resmi).","ART Pasal 11 (larangan), khususnya huruf a, c, g, dan h."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Aspirasi","Aspirasi, kritik, saran, keluhan, atau permintaan mahasiswa yang ditujukan kepada BEM atau melalui BEM kepada pihak lain."],["Kanal resmi","Sarana penerimaan aspirasi yang ditetapkan dan diumumkan BEM (formulir daring, formulir fisik di sekretariat, email atau akun resmi, layanan tatap muka)."],["Nomor tiket","Nomor unik yang diberikan pada setiap aspirasi sebagai identitas pelacakan."],["Petugas piket aspirasi","Anggota Unit Advokasi yang bertugas menerima dan mencatat aspirasi pada jadwal yang ditetapkan."],["Register Aspirasi","Buku atau berkas induk pencatatan seluruh aspirasi yang masuk dan statusnya."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kanal resmi minimal: (1) formulir daring, (2) formulir fisik di sekretariat, (3) email atau akun resmi BEM, (4) layanan tatap muka pada jam yang diumumkan, dan (5) perwakilan HIMA atau UKM yang meneruskan aspirasi anggotanya.","Aspirasi yang diterima pengurus di luar kanal resmi (pesan pribadi, lisan) wajib diteruskan kepada petugas piket paling lambat 1 hari kerja; pengurus tidak boleh menahan atau menyelesaikannya sendiri.","Pengaju mencantumkan nama, NIM, dan program studi agar dapat diproses penuh. Aspirasi tanpa identitas diterima sebagai informasi awal dan wajib diverifikasi (SOP-ADV-003); pengaduan yang memerlukan kerahasiaan mengikuti SOP-ADV-010.","Muatan aspirasi tidak boleh mengandung SARA, ujaran kebencian, ancaman, kekerasan, atau pencemaran nama baik (ART Pasal 11). Aspirasi demikian dikembalikan dengan arahan perbaikan dan tetap dicatat pada register, tidak dihapus.","Aspirasi tentang kinerja atau perilaku pengurus BEM dirutekan kepada Inspektur Jenderal (ART Pasal 12 ayat 3 dan 6) agar tidak ditangani pihak yang berkepentingan.","Aspirasi yang menyangkut keselamatan, pelecehan, perundungan, atau ancaman diperlakukan sebagai kasus mendesak dan disampaikan kepada Presiden dan Wakil Presiden paling lambat 6 jam sejak diterima.","Setiap aspirasi dilayani tanpa membedakan program studi, angkatan, atau kedudukan pengaju, dan setiap pengaju menerima tanda terima."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Mahasiswa pengaju","R","Menyampaikan aspirasi secara jelas melalui kanal resmi disertai identitas dan data pendukung yang tersedia."],["Petugas piket aspirasi","R","Menerima, mencatat, memberi nomor tiket, menyaring awal, dan mengirim tanda terima."],["Wakil Presiden","A","Bertanggung jawab akhir atas berjalannya layanan penerimaan aspirasi dan memutuskan rute aspirasi yang meragukan."],["Biro Desain Komunikasi Visual","R","Membuat dan menyebarkan materi publikasi kanal dan alur aspirasi."],["Biro Kesekretariatan","R","Mengelola email atau akun resmi dan menyimpan arsip aspirasi."],["Inspektur Jenderal","C","Menerima rute aspirasi tentang kinerja pengurus dan memberi masukan bila ada keraguan rute."],["Presiden","I","Diberi tahu atas aspirasi mendesak dan rekap layanan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar kanal resmi dan jadwal piket aspirasi.","Formulir Aspirasi.","Daftar rute aspirasi (biasa, mendesak, rahasia, kinerja BEM)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Sosialisasi kanal: Mempublikasikan kanal resmi, jam layanan, dan alur aspirasi melalui media resmi dan papan informasi.","Unit Advokasi bersama Biro Desain Komunikasi Visual","Daftar kanal, jadwal piket","Materi publikasi tersebar","Awal periode; diperbarui bila kanal berubah"],["2","Penyampaian aspirasi: Mahasiswa mengisi Formulir Aspirasi atau menyampaikannya langsung pada layanan tatap muka.","Mahasiswa pengaju","Formulir Aspirasi, bukti pendukung","Aspirasi masuk","Kapan saja"],["3","Penerimaan dan pencatatan awal: Memeriksa keterbacaan, memberi nomor tiket, dan mencatat pada Register Aspirasi.","Petugas piket aspirasi","Aspirasi masuk","Entri register dan nomor tiket","1 hari kerja"],["4","Penyaringan awal: Memeriksa muatan terhadap larangan ART Pasal 11 dan menentukan rute: biasa, mendesak, rahasia, atau kinerja BEM.","Petugas piket; Wakil Presiden bila ragu","Aspirasi, daftar rute","Rute penanganan","1 hari kerja"],["5","Tanda terima: Mengirim tanda terima berisi nomor tiket dan perkiraan jadwal tanggapan pertama.","Petugas piket aspirasi","Entri register","Tanda terima terkirim","1 hari kerja sejak diterima"],["6","Penerusan: Aspirasi biasa diteruskan ke SOP- ADV-002; mendesak ke Presiden dan Wakil Presiden; rahasia ke SOP-ADV- 010; kinerja BEM ke Inspektur Jenderal.","Petugas piket aspirasi","Rute penanganan","Aspirasi berpindah ke proses berikutnya","Hari yang sama; mendesak maks. 6 jam"],["7","Rekap layanan: Merekap jumlah aspirasi, kanal, rute, dan status layanan; melaporkan kepada Wakil Presiden dan Sekretaris Jenderal.","Petugas piket; Sekjen","Register Aspirasi","Rekap mingguan","Setiap minggu"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Tanda terima dikirim paling lambat 1 hari kerja sejak aspirasi diterima. Aspirasi mendesak sampai kepada Presiden dan Wakil Presiden paling lambat 6 jam. Hasil akhir: aspirasi tercatat pada Register Aspirasi dengan nomor tiket, rute, dan tanda terima."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Aspirasi masuk saat petugas piket berhalangan: pengurus Unit Advokasi lain mencatat; Wakil Presiden menunjuk pengganti (SOP-GOV-008).","Keraguan rute atau muatan: diputuskan Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Aspirasi menyangkut pengurus yang bertugas sebagai petugas piket: aspirasi dialihkan kepada petugas lain atau Inspektur Jenderal.","Kanal resmi tidak dapat diakses: aspirasi diterima melalui kanal cadangan dan dicatat kemudian dengan keterangan waktu terima sebenarnya."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% aspirasi yang masuk memiliki nomor tiket pada Register Aspirasi.","Minimal 95% aspirasi menerima tanda terima dalam 1 hari kerja.","100% aspirasi mendesak sampai kepada Presiden dan Wakil Presiden dalam 6 jam.","Tidak ada temuan aspirasi yang tidak tercatat pada pemeriksaan Inspektur Jenderal."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Aspirasi.","Formulir Aspirasi terisi dan lampiran.","Tanda terima aspirasi.","Rekap layanan mingguan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Advokasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden meninjau rekap layanan setiap minggu; Inspektur Jenderal mengambil sampel aspirasi dari kanal tidak resmi untuk memastikan seluruhnya masuk register."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Aspirasi disampaikan → Dicatat dan diberi nomor tiket → Penyaringan awal → Tanda terima → Rute: biasa (ADV-002) / mendesak / rahasia (ADV-010) / kinerja BEM (Irjen) → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Aspirasi","Nama; NIM; program studi; kontak; tanggal; ringkasan aspirasi; pihak yang dituju; bukti pendukung; pilihan sifat (terbuka atau minta dirahasiakan)."],["Templat Tanda Terima","Nomor tiket; tanggal terima; ringkasan aspirasi; perkiraan jadwal tanggapan; kontak petugas."],["Register Aspirasi","Nomor tiket; tanggal; kanal; pengaju (atau kode); ringkasan; rute; petugas; status."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Aspirasi tercatat dan memiliki nomor tiket.","☐ Ya ☐ Tidak"],["2","Muatan telah diperiksa terhadap ART Pasal 11.","☐ Ya ☐ Tidak"],["3","Rute penanganan sudah ditetapkan dan sesuai.","☐ Ya ☐ Tidak"],["4","Tanda terima terkirim dalam 1 hari kerja.","☐ Ya ☐ Tidak"],["5","Aspirasi mendesak telah disampaikan kepada Presiden dan Wakil Presiden dalam 6 jam.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADV-002","g":"Advokasi dan Aspirasi Mahasiswa","t":"Pencatatan dan Klasifikasi Aspirasi","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[112,115],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara mencatat, mengelompokkan, dan menilai kewenangan setiap aspirasi, sehingga aspirasi sejenis tidak ditangani berulang, ditujukan kepada pihak yang tepat, dan dapat dilacak sampai selesai.."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh aspirasi yang telah berstatus tercatat dan lolos penyaringan awal (SOP-ADV-001). SOP ini tidak mengatur pembuktian fakta (SOP-ADV-003) dan penentuan prioritas (SOP-ADV-004)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf g dan h (aspirasi dan kritik konstruktif di bidang akademik, pelayanan kemahasiswaan, dan sarana prasarana).","ART Pasal 4 (Wewenang BEM) huruf a, e, dan g (kebijakan, mewakili mahasiswa, rekomendasi kepada HIMA dan UKM).","ART Bab III (Tugas BEM) huruf d dan f (koordinasi antar ORMAWA dan seluruh kegiatan kemahasiswaan).","ART Pasal 12 ayat (3) dan (8) (pengawasan Irjen; kewenangan KAUR ORMAWA terhadap BPM).","ART Pasal 3 (Kewajiban BEM) huruf g (pelaporan berkala)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Klasifikasi","Pengelompokan aspirasi menurut jenis, sifat, dan kewenangan penanganan."],["Aspirasi induk","Aspirasi pertama yang menjadi acuan untuk menggabungkan aspirasi serupa."],["Sifat aspirasi","Tingkat keterbukaan informasi: terbuka, terbatas, atau rahasia."],["Pengalihan (referral)","Penerusan aspirasi kepada pihak yang berwenang karena di luar kewenangan BEM."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Jenis aspirasi: (A) akademik; (B) pelayanan kemahasiswaan; (C) sarana dan prasarana; (D) kebijakan kampus; (E) kegiatan ORMAWA atau BEM; (F) etik atau dugaan pelanggaran; (G) lainnya.","Sifat aspirasi: terbuka (dapat dipublikasikan ringkasannya), terbatas (hanya Tim Advokasi dan pimpinan), rahasia (SOP-ADV-010 dan SOP-ADV-011).","Penilaian kewenangan: (1) dalam kewenangan BEM; (2) memerlukan keputusan kampus; (3) menjadi ranah HIMA, UKM, atau BPM; (4) di luar kewenangan sehingga dialihkan. Aspirasi tentang BPM diteruskan melalui KAUR ORMAWA (ART Pasal 12 ayat 8).","Aspirasi di luar bidang akademik, pelayanan kemahasiswaan, dan sarana prasarana tidak ditolak, tetapi diperlakukan sebagai saran dan dikonsultasikan lebih dahulu kepada KAUR ORMAWA (SOP-ADV- 006).","Aspirasi yang substansinya sama digabung ke aspirasi induk; setiap pengaju tetap tercatat dan menerima pembaruan status.","Register induk memuat aspirasi terbuka dan terbatas; aspirasi rahasia dicatat pada register terpisah dengan akses terbatas."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Petugas klasifikasi (Unit Advokasi)","R","Memeriksa kelengkapan, mengklasifikasi jenis dan sifat, menilai kewenangan, serta mencatat pada register."],["Wakil Presiden","A","Bertanggung jawab akhir atas ketepatan klasifikasi dan menetapkan klasifikasi yang meragukan."],["Sekretaris Jenderal","R","Memastikan format register dan penyimpanan sesuai SOP pengarsipan."],["Inspektur Jenderal","C","Menelaah klasifikasi aspirasi yang menyangkut pengurus atau dugaan pelanggaran."],["KAUR ORMAWA / Pembina","C","Dimintai masukan atas aspirasi di luar kewenangan atau menyangkut BPM."],["Pengaju aspirasi","I","Menerima informasi status dan hasil klasifikasi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Aspirasi yang lolos penyaringan awal beserta nomor tiket.","Daftar jenis dan sifat aspirasi.","Register Aspirasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengambilan aspirasi: Mengambil aspirasi dari antrean penyaringan sesuai urutan masuk.","Petugas klasifikasi","Aspirasi bernomor tiket","Aspirasi siap diklasifikasi","Maks. 1 hari kerja"],["2","Pemeriksaan kelengkapan: Memeriksa identitas, uraian, dan bukti awal; meminta data tambahan kepada pengaju bila kurang.","Petugas klasifikasi","Aspirasi, Formulir Aspirasi","Lengkap atau perlu data tambahan","1 hari kerja"],["3","Klasifikasi jenis dan sifat: Menetapkan jenis (A sampai G) dan sifat (terbuka, terbatas, rahasia).","Petugas klasifikasi","Aspirasi lengkap","Jenis dan sifat tercatat","1 hari kerja"],["4","Penilaian kewenangan: Menilai apakah aspirasi dalam kewenangan BEM, memerlukan kampus, ranah HIMA, UKM, atau BPM, atau harus dialihkan.","Petugas klasifikasi dan Wakil Presiden","Matriks kewenangan (SOP-GOV-001), ART","Penilaian kewenangan","1 hari kerja"],["5","Pemeriksaan duplikasi: Mencari aspirasi serupa pada register; menggabungkan ke aspirasi induk bila substansinya sama.","Petugas klasifikasi","Register Aspirasi","Aspirasi induk atau aspirasi baru","1 hari kerja"],["6","Pencatatan dan pengalihan: Melengkapi register; meneruskan ke SOP-ADV-003, atau mengalihkan secara tertulis kepada pihak berwenang bila di luar kewenangan BEM.","Petugas klasifikasi; Sekjen untuk surat","Hasil klasifikasi","Register lengkap; surat pengalihan bila perlu","2 hari kerja sejak aspirasi diambil"],["7","Pemberitahuan kepada pengaju: Memberi tahu pengaju tentang klasifikasi, pihak yang menangani, dan langkah berikutnya.","Petugas klasifikasi","Register lengkap","Pengaju terinformasi","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Klasifikasi selesai paling lambat 2 hari kerja sejak aspirasi diambil dari antrean. Hasil akhir: entri register lengkap (jenis, sifat, kewenangan, status) dan pemberitahuan kepada pengaju."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Klasifikasi meragukan: diputuskan Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Aspirasi menyangkut pelecehan, perundungan, atau penyalahgunaan dana: tidak diproses sebagai advokasi biasa, tetapi diteruskan ke SOP-ADV-010.","Aspirasi di luar kewenangan BEM: dialihkan secara tertulis disertai tembusan kepada pengaju; BEM tidak menjanjikan hasil.","Pengaju tidak merespons permintaan data tambahan dalam 5 hari kerja: aspirasi berstatus menunggu dan dapat dibuka kembali (SOP-ADV-012)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% aspirasi memiliki jenis, sifat, dan penilaian kewenangan pada register.","Klasifikasi selesai dalam 2 hari kerja pada minimal 90% aspirasi.","Tidak ada aspirasi ganda yang ditangani oleh dua penanggung jawab berbeda.","Jumlah koreksi klasifikasi oleh Wakil Presiden menurun dari bulan ke bulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Aspirasi yang telah diklasifikasi.","Surat pengalihan (bila ada).","Pemberitahuan kepada pengaju.","Daftar aspirasi induk dan gabungan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Advokasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan register setiap bulan; Inspektur Jenderal mengambil sampel klasifikasi untuk diperiksa ketepatannya."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Ambil aspirasi → Periksa kelengkapan → Klasifikasi jenis dan sifat → Nilai kewenangan → Cek duplikasi → Catat atau alihkan → Beri tahu pengaju → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Klasifikasi Aspirasi","Nomor tiket; jenis (A-G); sifat; penilaian kewenangan; aspirasi induk; petugas; tanggal."],["Templat Surat Pengalihan","Nomor surat; pihak tujuan; ringkasan aspirasi; alasan pengalihan; permintaan tanggapan; tembusan."],["Register Aspirasi (kolom klasifikasi)","Jenis; sifat; kewenangan; status; penanggung jawab; tenggat."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Identitas dan uraian aspirasi lengkap.","☐ Ya ☐ Tidak"],["2","Jenis dan sifat telah ditetapkan.","☐ Ya ☐ Tidak"],["3","Kewenangan telah dinilai berdasarkan matriks kewenangan.","☐ Ya ☐ Tidak"],["4","Duplikasi telah diperiksa.","☐ Ya ☐ Tidak"],["5","Pengaju telah diberi tahu hasil klasifikasi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADV-003","g":"Advokasi dan Aspirasi Mahasiswa","t":"Verifikasi Fakta dan Bukti","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[116,119],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara memeriksa kebenaran fakta dan kecukupan bukti suatu aspirasi sebelum diadvokasikan, secara adil, objektif, dan menghormati hak klarifikasi pihak yang disebut, agar BEM tidak menyampaikan klaim yang tidak berdasar."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk aspirasi terklasifikasi yang akan diadvokasikan kepada pihak kampus atau pihak lain. SOP ini tidak mengatur penanganan pelanggaran oleh pengurus (ART Pasal 12 dan SOP-SDM-13) dan pengaduan rahasia (SOP-ADV-010), meskipun prinsip pembuktiannya dipakai bersama."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 13 (Mekanisme Pemberian Sanksi) ayat (4) (laporan wajib disertai bukti yang dapat dipertanggungjawabkan), ayat (7) (keadilan, objektivitas, berdasarkan bukti), dan ayat (9) (hak klarifikasi dan pembelaan).","ART Pasal 2 huruf h (kritik konstruktif dan beretika).","ART Pasal 3 (Kewajiban BEM) huruf d (menjaga nama baik).","ART Pasal 11 huruf g dan h (larangan mencemarkan nama baik dan perundungan).","AD Pasal 17 ayat (2) (transparan, akuntabel, efektif)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Verifikasi","Pemeriksaan kebenaran fakta dan kecukupan bukti suatu aspirasi."],["Bukti","Dokumen, foto, tangkapan layar, data, atau keterangan saksi yang diperoleh dengan cara sah."],["Triangulasi","Pencocokan fakta dari sedikitnya dua sumber yang berbeda."],["Laporan Verifikasi","Dokumen hasil pemeriksaan yang memuat temuan dan tingkat keterbuktian."],["Tabayyun","Pengecekan kebenaran informasi kepada pihak terkait sebelum mengambil sikap."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Verifikasi dilakukan oleh petugas verifikasi Unit Advokasi yang tidak memiliki konflik kepentingan dengan pengaju maupun pihak yang disebut.","Prinsip: tabayyun, adil, objektif, dan berdasarkan bukti. Aspirasi tidak dianggap benar atau salah sebelum diperiksa.","Bukti hanya boleh diperoleh dengan cara yang sah. Dilarang merekam diam-diam, meretas, atau memaksa pemberian data.","Fakta penting diperiksa melalui triangulasi sedikitnya dua sumber, misalnya dokumen kampus, peraturan, saksi, atau pengamatan langsung.","Pihak yang disebut dalam aspirasi diberi kesempatan klarifikasi sebelum aspirasi diadvokasikan; identitas pelapor tidak diungkapkan dalam proses klarifikasi (SOP-ADV-011).","Hasil verifikasi bertingkat: terverifikasi; terverifikasi sebagian; tidak terverifikasi; atau perlu data tambahan. Hanya fakta terverifikasi yang boleh dimuat dalam tuntutan atau pernyataan BEM.","Data pribadi dalam bukti dibatasi pada yang diperlukan dan disimpan dengan akses terbatas."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Petugas verifikasi (Unit Advokasi)","R","Menyusun rencana verifikasi, mengumpulkan dan mencocokkan bukti, dan menulis Laporan Verifikasi."],["Pengaju aspirasi","R","Memberikan bukti dan keterangan tambahan yang diminta."],["Wakil Presiden","A","Bertanggung jawab akhir atas kesimpulan verifikasi dan mengesahkan Laporan Verifikasi."],["Inspektur Jenderal","C","Menelaah proses verifikasi untuk kasus berdampak besar atau menyangkut pengurus."],["Pihak yang disebut","C","Memberikan klarifikasi dan pembelaan."],["Presiden","I","Menerima ringkasan hasil verifikasi kasus prioritas tinggi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Aspirasi terklasifikasi.","Bukti dari pengaju.","Dokumen dan peraturan kampus yang relevan.","Formulir Rencana Verifikasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Rencana verifikasi: Merumuskan fakta yang harus dibuktikan, sumber yang akan dihubungi, dan pembagian tugas.","Petugas verifikasi","Aspirasi terklasifikasi","Rencana verifikasi","1 hari kerja"],["2","Pengumpulan bukti dari pengaju: Meminta dan memeriksa bukti serta keterangan lanjutan dari pengaju.","Petugas verifikasi; pengaju","Rencana verifikasi","Bukti awal terkumpul","2 hari kerja"],["3","Pengumpulan data sumber lain: Menghimpun dokumen, peraturan, data, dan keterangan dari sumber sah lain; melakukan pengamatan bila perlu.","Petugas verifikasi","Rencana verifikasi, dokumen kampus","Data pembanding","3 hari kerja"],["4","Triangulasi: Mencocokkan fakta dari sedikitnya dua sumber dan mencatat ketidaksesuaian.","Petugas verifikasi","Bukti dan data","Matriks fakta dan bukti","2 hari kerja"],["5","Klarifikasi pihak yang disebut: Meminta klarifikasi secara tertulis atau lisan tanpa membuka identitas pelapor; mencatat jawabannya.","Petugas verifikasi; Wakil Presiden","Matriks fakta, daftar pertanyaan","Catatan klarifikasi","3 hari kerja"],["6","Penilaian dan Laporan Verifikasi: Menetapkan tingkat keterbuktian dan menyusun Laporan Verifikasi beserta rekomendasi.","Petugas verifikasi","Matriks fakta, catatan klarifikasi","Laporan Verifikasi","2 hari kerja"],["7","Pengesahan hasil: Memeriksa dan mengesahkan Laporan Verifikasi; meneruskan ke SOP-ADV- 004.","Wakil Presiden","Laporan Verifikasi","Laporan disahkan","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Verifikasi selesai paling lambat 5 hari kerja sejak klasifikasi selesai untuk kasus biasa dan dapat diperpanjang 3 hari kerja dengan alasan tertulis. Kasus mendesak: verifikasi awal maksimal 24 jam. Hasil akhir: Laporan Verifikasi yang disahkan Wakil Presiden."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengaju tidak dapat menunjukkan bukti: dicatat sebagai tidak terverifikasi atau perlu data tambahan; BEM tidak mengadvokasikan sebagai fakta.","Pihak yang disebut menolak memberi klarifikasi: penolakan dicatat dan kasus tetap diproses dengan keterangan tersebut.","Bukti diperoleh secara tidak sah: tidak dipakai dan dicatat dalam laporan.","Temuan menunjukkan dugaan pelanggaran oleh pengurus: dialihkan ke Inspektur Jenderal (ART Pasal 12) dan SOP-SDM-13.","Temuan menunjukkan pelecehan, perundungan, atau penyalahgunaan dana: dialihkan ke SOP-ADV- 010."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% aspirasi yang diadvokasikan memiliki Laporan Verifikasi yang disahkan.","Minimal 90% verifikasi selesai dalam 5 hari kerja.","Tidak ada klaim BEM yang dibantah karena salah fakta.","100% klarifikasi pihak yang disebut tercatat sebelum advokasi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Rencana Verifikasi.","Matriks fakta dan bukti.","Catatan klarifikasi.","Laporan Verifikasi yang disahkan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Advokasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden meninjau Laporan Verifikasi sebelum pengesahan; Inspektur Jenderal menilai sampel laporan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Rencana verifikasi → Kumpulkan bukti → Triangulasi → Klarifikasi pihak yang disebut → Penilaian → Pengesahan Wakil Presiden → ADV-004 → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Rencana Verifikasi","Nomor tiket; fakta yang diperiksa; sumber; petugas; tenggat."],["Matriks Fakta dan Bukti","Fakta; sumber 1; sumber 2; status (cocok atau tidak); catatan."],["Laporan Verifikasi","Ringkasan kasus; metode; temuan; tingkat keterbuktian; klarifikasi; rekomendasi; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Petugas verifikasi bebas dari konflik kepentingan.","☐ Ya ☐ Tidak"],["2","Setiap fakta penting dicocokkan dari minimal dua sumber.","☐ Ya ☐ Tidak"],["3","Pihak yang disebut diberi kesempatan klarifikasi.","☐ Ya ☐ Tidak"],["4","Identitas pelapor tidak terbuka dalam dokumen verifikasi.","☐ Ya ☐ Tidak"],["5","Laporan Verifikasi disahkan Wakil Presiden.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADV-004","g":"Advokasi dan Aspirasi Mahasiswa","t":"Penentuan Prioritas Kasus","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[120,123],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan kriteria dan cara menentukan urutan penanganan kasus aspirasi berdasarkan dampak, urgensi, dan risiko, sehingga sumber daya BEM terbatas dipakai untuk kasus yang paling penting dan kasus mendesak tidak terlambat ditangani."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kasus aspirasi yang telah memiliki Laporan Verifikasi (SOP-ADV-003). Penunjukan penanggung jawab diatur SOP-ADV-005. Kasus keselamatan dan pelecehan langsung berstatus mendesak dan mengikuti SOP-ADV-010."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 5 (fungsi dan tujuan BEM) dan AD Pasal 17 ayat (2) (pengelolaan efektif dan efisien).","ART Bab III (Tugas BEM) huruf a, c, dan f.","ART Pasal 4 (Wewenang BEM) huruf a (mengambil kebijakan pelaksanaan kegiatan kemahasiswaan).","ART Pasal 9 ayat (4) (program kerja tahunan sebagai pedoman) sebagai acuan kapasitas kerja.","SOP-GOV-002 (pengambilan keputusan) dan SOP-GOV-005 (Rapat Pimpinan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Prioritas","Urutan penanganan kasus berdasarkan skor dan ketentuan khusus."],["Skor prioritas","Jumlah nilai dari empat kriteria: dampak, jumlah terdampak, urgensi waktu, dan risiko."],["Daftar Prioritas Kasus","Daftar kasus aktif beserta tingkat prioritas, penanggung jawab, dan tenggat."],["Kasus mendesak","Kasus yang menyangkut keselamatan, kesehatan, pelecehan, perundungan, atau ancaman."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kriteria dinilai 1 sampai 3: (1) dampak pada hak atau layanan mahasiswa; (2) jumlah mahasiswa terdampak; (3) urgensi waktu (tenggat, kegiatan, atau perubahan aturan); (4) risiko jika tidak ditangani (keselamatan, hukum, reputasi, keuangan).","Tingkat prioritas: skor 10 sampai 12 = Prioritas 1 (Segera); 7 sampai 9 = Prioritas 2 (Tinggi); 4 sampai 6 = Prioritas 3 (Biasa).","Ketentuan khusus: kasus keselamatan, kesehatan, pelecehan, perundungan, atau ancaman otomatis Prioritas 1 tanpa melihat skor.","Prioritas 1 dan 2 ditetapkan dalam Rapat Pimpinan (SOP-GOV-005); Prioritas 3 ditetapkan Wakil Presiden. Hasil dicatat sesuai SOP-GOV-002.","Kasus yang tidak terverifikasi tidak masuk daftar prioritas, tetapi tetap dicatat dan dapat dibuka kembali bila ada bukti baru.","Daftar Prioritas Kasus ditinjau setiap minggu; prioritas dapat naik atau turun bila ada fakta baru.","Kasus dengan kewenangan di luar BEM tetap dinilai, namun bentuk tindakannya terbatas pada pengalihan, konsultasi, atau rekomendasi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Petugas verifikasi / Unit Advokasi","R","Menghitung skor prioritas dan menyiapkan usulan peringkat."],["Wakil Presiden","A","Bertanggung jawab akhir atas Daftar Prioritas Kasus dan menetapkan Prioritas 3."],["Presiden","R","Memutuskan Prioritas 1 dan 2 bersama pimpinan dalam Rapat Pimpinan."],["Sekretaris Jenderal","R","Mencatat keputusan, memperbarui Daftar Prioritas Kasus, dan mengarsipkan."],["Inspektur Jenderal","C","Menelaah konsistensi penilaian dan kesesuaian dengan AD/ART."],["Penanggung jawab advokasi","I","Menerima penetapan prioritas dan tenggat."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan Verifikasi.","Lembar Penilaian Prioritas.","Daftar Prioritas Kasus terkini.","Informasi kapasitas Unit Advokasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penilaian skor: Menilai empat kriteria dan menghitung skor; menandai kasus mendesak.","Unit Advokasi","Laporan Verifikasi","Lembar Penilaian Prioritas","1 hari kerja"],["2","Pemeriksaan kapasitas: Memeriksa jumlah kasus aktif dan kapasitas Unit Advokasi untuk menentukan tenggat realistis.","Unit Advokasi","Daftar Prioritas Kasus","Usulan tenggat","Bersamaan dengan langkah 1"],["3","Pengajuan usulan: Mengajukan usulan prioritas dan tenggat kepada Wakil Presiden.","Unit Advokasi","Lembar penilaian, usulan tenggat","Usulan prioritas","1 hari kerja"],["4","Penetapan prioritas: Prioritas 3 ditetapkan Wakil Presiden; Prioritas 1 dan 2 ditetapkan melalui Rapat Pimpinan.","Wakil Presiden; Presiden dan pimpinan","Usulan prioritas","Keputusan prioritas","Prioritas 1: maks. 24 jam; lainnya 1 kali rapat"],["5","Pencatatan: Mencatat keputusan dan memperbarui Daftar Prioritas Kasus.","Sekjen","Keputusan","Daftar Prioritas Kasus diperbarui","1 hari kerja"],["6","Pemberitahuan: Menyampaikan prioritas dan tenggat kepada Unit Advokasi dan lanjut ke SOP-ADV-005.","Wakil Presiden","Daftar Prioritas Kasus","Prioritas diketahui","Hari yang sama"],["7","Peninjauan mingguan: Meninjau ulang prioritas dan kasus tertunda; menyesuaikan bila ada fakta baru.","Wakil Presiden dan Unit Advokasi","Daftar Prioritas Kasus","Daftar diperbarui","Setiap minggu"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Prioritas 1 ditetapkan paling lambat 24 jam setelah verifikasi; Prioritas 2 dan 3 paling lambat 3 hari kerja setelah Laporan Verifikasi disahkan. Hasil akhir: Daftar Prioritas Kasus yang diperbarui dan keputusan tercatat."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kasus mendesak muncul di luar jadwal rapat: Presiden atau Wakil Presiden menetapkan Prioritas 1 dan melaporkan pada Rapat Pimpinan berikutnya (SOP-GOV-012).","Perbedaan pendapat soal skor: diputuskan melalui musyawarah sesuai SOP-GOV-002; pendapat berbeda dicatat.","Seluruh kapasitas Unit Advokasi terpakai: Wakil Presiden meminta bantuan unit lain melalui koordinasi antarunit (SOP-GOV-004) atau menunda kasus Prioritas 3.","Kasus berpotensi melibatkan pihak luar kampus atau pelanggaran hukum: dikonsultasikan kepada KAUR ORMAWA atau Pembina sebelum ditetapkan."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kasus terverifikasi memiliki prioritas dan tenggat.","Prioritas 1 ditetapkan dalam 24 jam pada 100% kasus.","Tidak ada kasus Prioritas 1 yang terlambat ditangani.","Daftar Prioritas Kasus diperbarui setiap minggu."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Penilaian Prioritas.","Keputusan prioritas (Lembar Keputusan).","Daftar Prioritas Kasus.","Notulen Rapat Pimpinan bila relevan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Advokasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa pembaruan Daftar Prioritas Kasus setiap bulan; Inspektur Jenderal menguji konsistensi penilaian skor pada sampel kasus."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Hitung skor → Cek kapasitas → Usulan prioritas → Penetapan (Wapres atau Rapat Pimpinan) → Catat di Daftar Prioritas → ADV-005 → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Penilaian Prioritas","Nomor tiket; skor empat kriteria; total skor; penanda kasus mendesak; usulan prioritas; usulan tenggat."],["Daftar Prioritas Kasus","Nomor tiket; judul kasus; prioritas; penanggung jawab; tenggat; status; tanggal tinjau."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Keempat kriteria telah dinilai.","☐ Ya ☐ Tidak"],["2","Kasus mendesak ditandai dan ditangani sebagai Prioritas 1.","☐ Ya ☐ Tidak"],["3","Penetapan dilakukan oleh forum yang berwenang.","☐ Ya ☐ Tidak"],["4","Daftar Prioritas Kasus diperbarui.","☐ Ya ☐ Tidak"],["5","Penanggung jawab dan tenggat telah ditentukan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADV-005","g":"Advokasi dan Aspirasi Mahasiswa","t":"Penunjukan Penanggung Jawab Advokasi","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[124,127],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara menunjuk penanggung jawab dan tim advokasi untuk setiap kasus, termasuk syarat bebas konflik kepentingan, pembagian tugas, dan rencana kerja, sehingga setiap kasus memiliki satu pihak yang jelas bertanggung jawab."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kasus yang telah ditetapkan prioritasnya (SOP-ADV-004). SOP ini tidak mengatur pengangkatan pengurus (SOP-SDM-001) dan pendelegasian umum (SOP-GOV-008)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 11 ayat (2) huruf b (Presiden menetapkan Menteri dan Kabiro secara prerogatif) sebagai dasar penugasan internal.","ART Pasal 4 (Wewenang BEM) huruf b, c, dan f (mengangkat pengurus internal, tim kerja internal, dan menandatangani surat resmi).","ART Pasal 12 ayat (1) (pembinaan dan penegakan disiplin oleh pimpinan BEM).","ART Pasal 11 huruf i dan k (larangan menyalahgunakan dana, fasilitas, atau nama organisasi).","SOP-GOV-001 (matriks kewenangan) dan SOP-GOV-008 (pendelegasian wewenang)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Penanggung jawab advokasi (PJA)","Pengurus yang bertanggung jawab atas satu kasus dari awal sampai penutupan."],["Tim advokasi","PJA beserta anggota dan pendamping yang ditugaskan pada satu kasus."],["Surat Tugas Advokasi","Surat resmi penunjukan PJA dan tim."],["Konflik kepentingan","Keadaan ketika pengurus memiliki kepentingan pribadi, hubungan dekat, atau keterlibatan pada kasus sehingga dapat memengaruhi keputusannya."],["Rencana Kerja Advokasi","Rencana langkah, pihak, hasil, dan tenggat penanganan satu kasus."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap kasus memiliki satu PJA sebagai pihak yang bertanggung jawab atas pelaksanaan; Wakil Presiden tetap menjadi pihak A atas seluruh penunjukan.","Kriteria PJA: kompetensi sesuai jenis kasus, kapasitas waktu, kemampuan komunikasi, dan kemampuan menjaga kerahasiaan.","Pengurus yang terlibat langsung, memiliki hubungan keluarga atau pertemanan dekat, atau berkepentingan pada kasus tidak boleh menjadi PJA dan wajib menyatakan konflik kepentingan.","PJA dan anggota tim menandatangani Pernyataan Kerahasiaan dan Bebas Konflik Kepentingan sebelum bekerja.","Untuk kasus sensitif, tim dilengkapi pendamping yang sesuai, termasuk kesesuaian jenis kelamin dengan pelapor atau korban agar sesuai etika dan syariat.","Penunjukan dituangkan dalam Surat Tugas Advokasi yang memuat ruang lingkup, batas wewenang, dan tenggat.","PJA tidak boleh mengambil keputusan atau menyampaikan sikap atas nama BEM di luar mandat Surat Tugas; sikap resmi hanya disampaikan Presiden atau pihak yang diberi mandat (SOP-HKE-011)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Wakil Presiden","A","Menetapkan PJA dan tim serta bertanggung jawab akhir atas penunjukan."],["Presiden","R","Menandatangani Surat Tugas untuk kasus Prioritas 1 dan kasus yang melibatkan pihak kampus."],["Unit Advokasi","R","Mengusulkan kandidat PJA dan menyusun Rencana Kerja Advokasi."],["Penanggung jawab advokasi","R","Menerima penugasan, menyatakan bebas konflik kepentingan, dan melaksanakan rencana kerja."],["Sekretaris Jenderal","R","Menerbitkan, menomori, dan mengarsipkan Surat Tugas."],["Inspektur Jenderal","C","Memeriksa dugaan konflik kepentingan bila ada keberatan."],["Menteri / Kabiro terkait","I","Diberi tahu bila pengurus unitnya ditugaskan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Prioritas Kasus.","Daftar pengurus dan beban kerja.","Hasil verifikasi.","Formulir Pernyataan Kerahasiaan dan Bebas Konflik Kepentingan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Usulan kandidat: Mengusulkan kandidat PJA dan anggota tim berdasarkan jenis kasus, kompetensi, dan kapasitas.","Unit Advokasi","Daftar Prioritas Kasus, beban kerja","Usulan kandidat","1 hari kerja"],["2","Pemeriksaan konflik kepentingan: Meminta kandidat mengisi pernyataan; memeriksa keberatan dari pihak lain.","Wakil Presiden; Irjen bila ada keberatan","Usulan kandidat, pernyataan","Kandidat dinyatakan layak","1 hari kerja"],["3","Penetapan: Menetapkan PJA dan tim; menentukan pendamping untuk kasus sensitif.","Wakil Presiden","Kandidat layak","Keputusan penunjukan","1 hari kerja"],["4","Penerbitan Surat Tugas: Menyusun, menomori, dan menerbitkan Surat Tugas Advokasi untuk ditandatangani.","Sekjen; Presiden bila diperlukan","Keputusan penunjukan","Surat Tugas Advokasi","1 hari kerja"],["5","Penandatanganan pernyataan: PJA dan tim menandatangani Pernyataan Kerahasiaan dan Bebas Konflik Kepentingan.","PJA dan tim","Surat Tugas","Pernyataan tertandatangani","Sebelum mulai bekerja"],["6","Penyusunan Rencana Kerja Advokasi: Menyusun tujuan, langkah, pihak, hasil, dan tenggat; diperiksa Wakil Presiden.","PJA","Surat Tugas, hasil verifikasi","Rencana Kerja Advokasi disetujui","2 hari kerja"],["7","Pencatatan dan pengarsipan: Mencatat penugasan pada Daftar Prioritas Kasus dan mengarsipkan dokumen.","Sekjen","Surat Tugas, rencana kerja","Arsip lengkap","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penunjukan sampai terbitnya Surat Tugas paling lambat 2 hari kerja setelah prioritas ditetapkan (Prioritas 1: 1 hari kerja); Rencana Kerja Advokasi disetujui paling lambat 2 hari kerja setelah Surat Tugas. Hasil akhir: Surat Tugas Advokasi dan Rencana Kerja Advokasi."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Tidak ada kandidat tanpa konflik kepentingan: Wakil Presiden menugaskan pengurus unit lain (SOP- GOV-004) atau meminta Irjen menunjuk pihak independen.","PJA berhalangan: Wakil Presiden menunjuk pengganti sementara (SOP-GOV-008, SOP-GOV-009).","PJA melanggar kerahasiaan atau batas mandat: dihentikan dari penugasan dan ditangani sesuai ART Pasal 12 dan SOP-SDM-13.","Kasus menyangkut Wakil Presiden atau Presiden: penunjukan dilakukan oleh pimpinan lain dengan pengawasan Inspektur Jenderal."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kasus aktif memiliki tepat satu PJA dan Surat Tugas.","100% PJA menandatangani Pernyataan Kerahasiaan dan Bebas Konflik Kepentingan.","Surat Tugas terbit dalam 2 hari kerja pada minimal 90% kasus.","Tidak ada kasus dengan PJA yang berkonflik kepentingan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Surat Tugas Advokasi.","Pernyataan Kerahasiaan dan Bebas Konflik Kepentingan.","Rencana Kerja Advokasi.","Daftar Prioritas Kasus yang diperbarui. Seluruh dokumen disimpan pada repositori resmi BEM (folder Advokasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan Surat Tugas dan pernyataan setiap bulan; Inspektur Jenderal memeriksa sampel penunjukan terhadap konflik kepentingan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Usulan kandidat → Periksa konflik kepentingan → Penetapan Wapres → Surat Tugas dan pernyataan → Rencana Kerja Advokasi → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Surat Tugas Advokasi","Nomor; nomor tiket; PJA dan tim; ruang lingkup; batas wewenang; tenggat; tanda tangan."],["Pernyataan Kerahasiaan dan Bebas Konflik Kepentingan","Nama; jabatan; nomor tiket; pernyataan tidak berkonflik kepentingan; janji menjaga kerahasiaan; tanda tangan."],["Rencana Kerja Advokasi","Tujuan; langkah; pihak yang dihubungi; hasil yang diharapkan; tenggat; risiko; kebutuhan dukungan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","PJA ditetapkan dan hanya satu orang per kasus.","☐ Ya ☐ Tidak"],["2","Pernyataan konflik kepentingan telah diisi.","☐ Ya ☐ Tidak"],["3","Pendamping ditentukan untuk kasus sensitif.","☐ Ya ☐ Tidak"],["4","Surat Tugas bernomor dan tertandatangani.","☐ Ya ☐ Tidak"],["5","Rencana Kerja Advokasi disetujui Wakil Presiden.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADV-006","g":"Advokasi dan Aspirasi Mahasiswa","t":"Konsultasi dengan Pihak Terkait","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[128,131],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara berkonsultasi dengan pihak terkait secara jelas, yaitu menyebut pihaknya, keputusan yang dibutuhkan, dan hasil yang harus dibuat, sehingga kasus dicoba diselesaikan lebih dahulu melalui dialog yang beretika sebelum audiensi atau penyampaian tuntutan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk PJA dan Tim Advokasi saat berkonsultasi dengan pihak kampus, ORMAWA lain, Inspektur Jenderal, atau pihak lain terkait suatu kasus. Audiensi resmi dan penyampaian tuntutan diatur SOP-ADV-007; hubungan dengan organisasi mahasiswa lain secara umum diatur SOP-HKE."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf g dan h (aspirasi dan kritik konstruktif dengan etika yang baik).","ART Pasal 2 huruf e (kerja sama dengan pihak eksternal dengan persetujuan Ketua STDIIS).","ART Pasal 3 (Kewajiban BEM) huruf b dan d (menjaga ukhuwah, nama baik, dan ketertiban).","ART Bab III (Tugas BEM) huruf d (koordinasi antar ORMAWA dan dengan pihak eksternal perguruan tinggi).","ART Pasal 10 (Rapat Koordinasi) dan ART Pasal 11 huruf g (larangan mencemarkan nama baik)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Konsultasi","Pembicaraan dengan pihak terkait untuk meminta penjelasan, masukan, atau solusi atas kasus, tanpa penyampaian tuntutan resmi."],["Pihak terkait","Pihak yang namanya disebut dalam Lembar Konsultasi karena memiliki kewenangan, informasi, atau kepentingan pada kasus."],["Lembar Konsultasi","Formulir yang memuat pihak, pertanyaan, keputusan yang dibutuhkan, dan hasil yang diharapkan."],["Kementerian Harmonisasi Kampus","Unit BEM yang menjadi jembatan komunikasi dengan pihak internal kampus, termasuk ustadz dan dosen."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap konsultasi wajib menyebut: pihak yang dituju, jabatan, pertanyaan atau permintaan, keputusan yang dibutuhkan, hasil yang harus dibuat, dan tenggat. Frasa kabur seperti 'dikoordinasikan dengan pihak terkait' tidak boleh dipakai.","Urutan pihak yang dituju: (1) pihak yang berwenang langsung atas masalah; (2) KAUR ORMAWA bila menyangkut kebijakan kampus atau di luar bidang akademik, pelayanan kemahasiswaan, dan sarana prasarana; (3) Pembina; (4) pihak lain atas persetujuan Presiden.","Komunikasi dengan ustadz atau dosen dilakukan melalui atau bersama Kementerian Harmonisasi Kampus dengan adab dan bahasa yang santun.","Konsultasi dengan ORMAWA lain (HIMA, UKM, BPM) dilakukan melalui koordinasi resmi; BPM dan KAUR ORMAWA berwenang pada pelanggaran oleh BPM (ART Pasal 12 ayat 8).","Identitas pelapor dan data pribadi tidak disampaikan dalam konsultasi kecuali ada persetujuan tertulis pelapor (SOP-ADV-011).","Konsultasi bersifat mencari penyelesaian lebih dahulu; bila gagal atau tidak ditanggapi dalam batas waktu, kasus dilanjutkan ke SOP-ADV-007 setelah persetujuan Rapat Pimpinan.","Hasil konsultasi dicatat dalam notulen dan tidak boleh dipublikasikan sebelum disepakati."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Penanggung jawab advokasi","R","Menyusun Lembar Konsultasi, melaksanakan konsultasi, dan mencatat hasil."],["Wakil Presiden","A","Menyetujui Lembar Konsultasi dan bertanggung jawab akhir atas strategi konsultasi."],["Kementerian Harmonisasi Kampus","R","Memfasilitasi komunikasi dengan ustadz, dosen, dan unit kampus."],["Sekretaris Jenderal","R","Menyiapkan surat permohonan konsultasi dan mengarsipkan notulen."],["Presiden","C","Memberi arahan atas konsultasi yang melibatkan pimpinan kampus."],["Pihak terkait (kampus, ORMAWA, KAUR ORMAWA)","C","Memberi penjelasan, masukan, dan sikap atas permintaan konsultasi."],["Inspektur Jenderal","I","Menerima ringkasan hasil konsultasi kasus Prioritas 1."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Rencana Kerja Advokasi.","Laporan Verifikasi.","Lembar Konsultasi.","Daftar kontak pihak terkait."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Identifikasi pihak dan kewenangan: Menentukan pihak yang berwenang dan menetapkan keputusan yang dibutuhkan dari masing-masing pihak.","PJA","Rencana Kerja, matriks kewenangan","Daftar pihak dan keputusan yang dibutuhkan","1 hari kerja"],["2","Penyusunan Lembar Konsultasi: Mengisi Lembar Konsultasi: pihak, pertanyaan, keputusan yang dibutuhkan, hasil yang diharapkan, dan tenggat.","PJA","Daftar pihak","Lembar Konsultasi","1 hari kerja"],["3","Persetujuan: Memeriksa Lembar Konsultasi; memastikan tidak membuka identitas pelapor dan bahasa santun.","Wakil Presiden","Lembar Konsultasi","Lembar disetujui","1 hari kerja"],["4","Permohonan konsultasi: Mengirim permohonan melalui surat atau kanal resmi; memakai Kementerian Harmonisasi Kampus untuk ustadz atau dosen.","Sekjen; Kementerian Harmonisasi Kampus","Lembar disetujui","Permohonan terkirim","1 hari kerja"],["5","Pelaksanaan konsultasi: Bertemu atau berkorespondensi dengan pihak terkait; menyampaikan data terverifikasi; mendengar tanggapan.","PJA dan tim","Lembar Konsultasi, Laporan Verifikasi","Tanggapan pihak terkait","Maks. 5 hari kerja sejak permohonan"],["6","Pencatatan hasil: Menyusun notulen dan menyimpulkan keputusan, janji tindak lanjut, dan tenggat.","PJA; Sekjen","Tanggapan","Notulen konsultasi","1 hari kerja setelah pertemuan"],["7","Tinjauan dan keputusan lanjutan: Melaporkan hasil kepada Wakil Presiden; menentukan penyelesaian, lanjut konsultasi, atau eskalasi ke SOP-ADV-007.","Wakil Presiden; Rapat Pimpinan bila eskalasi","Notulen","Keputusan lanjutan","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Permohonan konsultasi terkirim paling lambat 3 hari kerja setelah Rencana Kerja disetujui; pelaksanaan paling lambat 5 hari kerja sejak permohonan; notulen paling lambat 1 hari kerja setelah pertemuan. Hasil akhir: notulen konsultasi dan keputusan lanjutan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pihak terkait tidak menanggapi dalam 5 hari kerja: dikirim pengingat tertulis; bila tetap tidak ditanggapi, dibahas dalam Rapat Pimpinan untuk eskalasi (SOP-ADV-007).","Pihak terkait menolak konsultasi: penolakan dicatat dan dikonsultasikan kepada KAUR ORMAWA atau Pembina.","Konsultasi mengarah pada permintaan agar kasus ditutup tanpa penyelesaian: keputusan diambil Rapat Pimpinan, bukan PJA.","Ketegangan antara BEM dan pihak terkait: SOP-GOV-010 dan SOP-HKE terkait.","Konsultasi menyentuh perubahan AD/ART: tidak diputuskan di sini; ikuti AD Bab XI dan ART Bab VII."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% konsultasi memiliki Lembar Konsultasi yang menyebut pihak, keputusan, dan hasil.","Minimal 80% permohonan konsultasi mendapat tanggapan dalam 5 hari kerja.","100% konsultasi memiliki notulen.","Tidak ada pengungkapan identitas pelapor dalam konsultasi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Konsultasi.","Surat permohonan konsultasi.","Notulen konsultasi.","Daftar tindak lanjut hasil konsultasi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Advokasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden memeriksa kelengkapan Lembar Konsultasi dan notulen setiap bulan; Inspektur Jenderal menilai sampel konsultasi terhadap etika komunikasi dan kerahasiaan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Identifikasi pihak → Lembar Konsultasi → Persetujuan Wapres → Permohonan → Konsultasi → Notulen → Selesai atau eskalasi ke ADV-007"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Konsultasi","Nomor tiket; pihak dan jabatan; pertanyaan atau permintaan; keputusan yang dibutuhkan; hasil yang diharapkan; tenggat; penanggung jawab."],["Templat Surat Permohonan Konsultasi","Nomor surat; pihak tujuan; ringkasan permasalahan tanpa identitas pelapor; usulan waktu dan tempat; tembusan."],["Templat Notulen Konsultasi","Tanggal; peserta; pokok pembahasan; keputusan; tindak lanjut; tenggat; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pihak, keputusan, dan hasil yang dibutuhkan disebut jelas.","☐ Ya ☐ Tidak"],["2","Lembar Konsultasi telah disetujui Wakil Presiden.","☐ Ya ☐ Tidak"],["3","Identitas pelapor tidak terbuka.","☐ Ya ☐ Tidak"],["4","Notulen tersusun dan tersimpan.","☐ Ya ☐ Tidak"],["5","Keputusan lanjutan telah ditetapkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADV-007","g":"Advokasi dan Aspirasi Mahasiswa","t":"Audiensi dan Penyampaian Tuntutan","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[132,136],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara menyampaikan sikap, permintaan, dan tuntutan mahasiswa kepada pihak kampus atau pihak lain melalui audiensi dan surat resmi secara tertib, santun, berbasis fakta terverifikasi, dan sesuai AD/ART."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk kasus yang telah terverifikasi (SOP-ADV-003), telah dikonsultasikan (SOP-ADV-006) atau konsultasinya tidak membuahkan hasil, dan disetujui Rapat Pimpinan. SOP ini hanya mengatur audiensi dan penyampaian tuntutan tertulis. Pengajuan audiensi umum dengan kampus mengikuti SOP-HKE-003 dan penugasan delegasi mengikuti SOP-HKE-011."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf g dan h (menyampaikan aspirasi, kritik, dan saran kepada kampus; mengkritisi secara konstruktif dengan etika yang baik).","ART Pasal 4 (Wewenang BEM) huruf e dan f (mewakili mahasiswa dalam forum resmi; menandatangani surat resmi).","ART Pasal 3 (Kewajiban BEM) huruf d dan h (menjaga nama baik dan ketertiban; mematuhi peraturan kampus).","ART Pasal 11 huruf a, c, e, dan g (larangan SARA, kekerasan dan anarkisme, politik praktis, dan pencemaran nama baik).","AD Pasal 17 ayat (3) (laporan kepada KAUR ORMAWA)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Audiensi","Pertemuan resmi BEM dengan pihak kampus atau pihak lain untuk menyampaikan aspirasi dan meminta tanggapan."],["Tuntutan","Permintaan tertulis agar suatu pihak melakukan atau menghentikan tindakan tertentu, berdasarkan fakta terverifikasi dan disampaikan dengan etika."],["Naskah Audiensi","Dokumen yang memuat kronologi, data, tuntutan, dan tenggat yang akan disampaikan."],["Delegasi","Perwakilan BEM yang diberi mandat menghadiri audiensi."],["Berita Acara Audiensi","Catatan resmi hasil audiensi yang ditandatangani para pihak."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Syarat audiensi dan tuntutan: kasus terverifikasi, jalur konsultasi telah dicoba atau tidak berhasil, dan persetujuan Rapat Pimpinan.","Sikap resmi BEM hanya disampaikan oleh Presiden atau delegasi yang diberi mandat tertulis; PJA tidak boleh menyampaikan tuntutan atas nama BEM tanpa mandat.","Tuntutan memuat hanya fakta terverifikasi, ditulis dengan bahasa santun, menyebut tindakan yang diminta dan tenggat yang wajar, tanpa merendahkan pihak mana pun.","Kritik terhadap kebijakan kampus difokuskan pada bidang akademik, pelayanan kemahasiswaan, dan sarana prasarana (ART Pasal 2 huruf h). Di luar itu disampaikan sebagai saran setelah konsultasi dengan KAUR ORMAWA.","Penyampaian dilakukan melalui audiensi dan surat resmi. Bentuk lain di luar SOP ini memerlukan keputusan Rapat Pimpinan, izin kampus, dan tidak boleh melanggar ART Pasal 11 (kekerasan, anarkisme, SARA, politik praktis).","Permohonan audiensi kepada pihak kampus diajukan melalui KAUR ORMAWA; kerja sama atau pelibatan pihak eksternal memerlukan persetujuan Ketua STDIIS (ART Pasal 2 huruf e).","Identitas pelapor tidak dicantumkan dalam Naskah Audiensi maupun tuntutan (SOP-ADV-011).","Hasil audiensi dituangkan dalam Berita Acara dan tidak dipublikasikan sebelum disetujui Presiden (SOP-KOM-010)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Penanggung jawab advokasi","R","Menyusun Naskah Audiensi dan mendukung delegasi dengan data."],["Presiden","A","Menyetujui tuntutan, memimpin delegasi, dan bertanggung jawab akhir atas sikap resmi BEM."],["Wakil Presiden","R","Memeriksa Naskah Audiensi dan mengoordinasikan persiapan."],["Sekretaris Jenderal","R","Menerbitkan surat permohonan audiensi dan mencatat Berita Acara."],["Kementerian Harmonisasi Kampus","R","Memfasilitasi komunikasi dengan pihak internal kampus."],["Inspektur Jenderal","C","Memeriksa kesesuaian tuntutan dengan AD/ART dan peraturan kampus."],["KAUR ORMAWA / pihak kampus","C","Menerima permohonan, menetapkan jadwal, dan menanggapi tuntutan."],["Seluruh pengurus","I","Menerima ringkasan hasil audiensi yang boleh disampaikan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan Verifikasi.","Notulen konsultasi (SOP-ADV-006).","Keputusan Rapat Pimpinan.","Naskah Audiensi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan Naskah Audiensi: Menyusun kronologi, fakta terverifikasi, tuntutan atau permintaan, dan tenggat tanggapan.","PJA","Laporan Verifikasi, notulen konsultasi","Draf Naskah Audiensi","3 hari kerja"],["2","Pemeriksaan naskah: Memeriksa kesesuaian dengan AD/ART, bahasa santun, dan perlindungan identitas pelapor.","Wakil Presiden; Irjen","Draf naskah","Naskah diperiksa","2 hari kerja"],["3","Persetujuan: Membahas naskah dan menyetujui pengajuan audiensi atau tuntutan sesuai SOP-GOV-002.","Presiden dan Rapat Pimpinan","Naskah diperiksa","Lembar Keputusan","1 kali rapat"],["4","Permohonan audiensi: Mengirim surat permohonan audiensi melalui KAUR ORMAWA disertai ringkasan agenda.","Sekjen","Lembar Keputusan","Surat terkirim dan jadwal diusulkan","2 hari kerja"],["5","Persiapan delegasi: Presiden menunjuk delegasi dan menerbitkan mandat; delegasi berlatih urutan penyampaian dan menyiapkan data.","Presiden; PJA","Mandat, naskah","Delegasi siap","Sebelum audiensi"],["6","Pelaksanaan audiensi: Menyampaikan aspirasi dengan santun, mendengar tanggapan, dan mencatat kesepakatan serta tenggat.","Delegasi","Naskah, data","Kesepakatan atau tanggapan","Sesuai jadwal kampus"],["7","Berita Acara: Menyusun dan menandatangani Berita Acara Audiensi; menyampaikan Surat Tuntutan tertulis bila diputuskan.","Sekjen; Presiden","Hasil audiensi","Berita Acara dan surat","2 hari kerja setelah audiensi"],["8","Tindak lanjut: Menyerahkan hasil kepada PJA untuk pemantauan melalui SOP-ADV-008 dan melaporkan kepada KAUR ORMAWA sesuai ketentuan.","PJA; Sekjen","Berita Acara","Daftar tindak lanjut","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Naskah sampai persetujuan paling lambat 6 hari kerja; surat permohonan paling lambat 2 hari kerja setelah persetujuan; Berita Acara paling lambat 2 hari kerja setelah audiensi. Hasil akhir: Berita Acara Audiensi dan, bila diputuskan, Surat Tuntutan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Permohonan audiensi tidak ditanggapi dalam 7 hari kerja: dikirim pengingat; bila tidak ditanggapi, dikonsultasikan kepada Pembina atau KAUR ORMAWA.","Audiensi menghasilkan kesepakatan berbeda dari tuntutan: perubahan hanya berlaku setelah disetujui Presiden dan dicatat.","Muncul ketegangan atau potensi pelanggaran ART Pasal 11 saat persiapan: Presiden dapat menunda atau membatalkan penyampaian dan membawa ke Rapat Pimpinan.","Tuntutan menyentuh perubahan AD/ART: tidak diputuskan di sini; ikuti AD Bab XI dan ART Bab VII.","Pelanggaran etika audiensi oleh delegasi: ditangani sesuai ART Pasal 12 dan SOP-SDM-13."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% tuntutan memiliki Naskah Audiensi dan persetujuan Presiden.","100% audiensi memiliki Berita Acara.","Tidak ada tuntutan yang memuat fakta tidak terverifikasi.","Minimal 80% audiensi menghasilkan kesepakatan tindak lanjut tertulis."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Naskah Audiensi.","Mandat delegasi.","Surat permohonan audiensi.","Berita Acara Audiensi dan Surat Tuntutan (bila ada). Seluruh dokumen disimpan pada repositori resmi BEM (folder Advokasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Presiden meninjau seluruh tuntutan sebelum dikirim; Inspektur Jenderal memeriksa sampel naskah dan Berita Acara terhadap kepatuhan AD/ART."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Naskah Audiensi → Pemeriksaan → Persetujuan Presiden → Surat permohonan via KAUR ORMAWA → Audiensi → Berita Acara → ADV-008 → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Naskah Audiensi","Nomor tiket; kronologi; fakta terverifikasi; tuntutan atau permintaan; dasar aturan; tenggat; delegasi."],["Templat Surat Permohonan Audiensi","Nomor surat; pihak tujuan; agenda; usulan waktu dan tempat; delegasi; tembusan KAUR ORMAWA."],["Berita Acara Audiensi","Tanggal; peserta; pokok bahasan; kesepakatan; tenggat; tanda tangan para pihak."],["Templat Surat Tuntutan","Nomor surat; dasar; fakta; permintaan tindakan; tenggat; tanda tangan Presiden."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kasus terverifikasi dan telah dikonsultasikan.","☐ Ya ☐ Tidak"],["2","Naskah memuat hanya fakta terverifikasi dan bahasa santun.","☐ Ya ☐ Tidak"],["3","Persetujuan Rapat Pimpinan tercatat.","☐ Ya ☐ Tidak"],["4","Mandat delegasi diterbitkan.","☐ Ya ☐ Tidak"],["5","Berita Acara ditandatangani dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADV-008","g":"Advokasi dan Aspirasi Mahasiswa","t":"Pemantauan Tindak Lanjut Aspirasi","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[137,140],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara memantau pelaksanaan janji dan keputusan pihak terkait atas aspirasi mahasiswa, termasuk pengingat dan eskalasi bertahap, sehingga aspirasi tidak berhenti setelah audiensi atau konsultasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kasus yang telah memiliki kesepakatan, keputusan, atau janji tindak lanjut dari pihak terkait. SOP ini tidak mengatur pemantauan program kerja internal BEM (SOP-MONEV)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Kewajiban BEM) huruf g (laporan kegiatan secara berkala).","ART Pasal 10 (Rapat Koordinasi) ayat (4) (monitoring).","ART Pasal 12 ayat (3) sampai (7) (pengawasan Irjen; pelaporan pelanggaran berat kepada KAUR ORMAWA).","AD Pasal 17 ayat (1) sampai (3) (laporan pertanggungjawaban, transparan, akuntabel)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Tindak lanjut","Tindakan yang dijanjikan atau diputuskan pihak terkait atas suatu aspirasi."],["Register Tindak Lanjut","Daftar tindakan, penanggung jawab pihak terkait, tenggat, dan status."],["Pengingat","Pemberitahuan tertulis kepada pihak terkait mengenai tenggat tindak lanjut."],["Eskalasi","Peningkatan penanganan ke tingkat yang lebih tinggi bila tindak lanjut tidak dilaksanakan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap janji tindak lanjut dicatat pada Register Tindak Lanjut dengan penanggung jawab pihak terkait, indikator selesai, dan tenggat.","Status tindak lanjut: belum dimulai; berjalan; selesai sebagian; selesai; terlambat; tidak dilaksanakan.","Eskalasi bertahap: (1) pengingat langsung oleh PJA; (2) surat pengingat resmi oleh Sekretaris Jenderal; (3) pembahasan Rapat Pimpinan dan permohonan audiensi ulang (SOP-ADV-007); (4) pelaporan kepada KAUR ORMAWA atau Pembina.","Pemantauan dilakukan dengan bukti: dokumen, foto, perubahan layanan, atau konfirmasi pengaju; pernyataan lisan saja tidak cukup untuk menyatakan selesai.","Pemantauan dilakukan secara santun dan tidak menekan pihak terkait dengan cara yang melanggar ART Pasal 11.","Tinjauan Register Tindak Lanjut dilakukan setiap minggu dan hasilnya dibawa ke Rapat Koordinasi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Penanggung jawab advokasi","R","Memantau tindak lanjut, mengumpulkan bukti, dan mengirim pengingat awal."],["Wakil Presiden","A","Bertanggung jawab akhir atas pemantauan dan memutuskan eskalasi."],["Sekretaris Jenderal","R","Menerbitkan surat pengingat dan memperbarui Register Tindak Lanjut."],["Presiden","R","Memutuskan eskalasi ke tingkat Rapat Pimpinan dan pelaporan ke KAUR ORMAWA."],["Inspektur Jenderal","C","Menilai kepatuhan pemantauan dan memeriksa sampel kasus."],["Pihak terkait","C","Melaksanakan dan melaporkan tindak lanjut."],["Pengaju aspirasi","I","Menerima perkembangan (SOP-ADV-009)."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Berita Acara audiensi atau notulen konsultasi.","Register Tindak Lanjut.","Bukti pelaksanaan dari pihak terkait."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan tindak lanjut: Mencatat setiap janji tindak lanjut, indikator selesai, dan tenggat pada Register Tindak Lanjut.","PJA","Berita Acara, notulen","Register Tindak Lanjut","1 hari kerja setelah kesepakatan"],["2","Pemantauan berkala: Menghubungi pihak terkait, mengecek kemajuan, dan mengumpulkan bukti.","PJA","Register Tindak Lanjut","Catatan pemantauan","Sesuai jadwal; minimal setiap minggu"],["3","Penilaian status: Menilai status tindak lanjut berdasarkan bukti dan mencocokkan dengan tenggat.","PJA","Catatan pemantauan, bukti","Status diperbarui","Setiap pemantauan"],["4","Pengingat awal: Bila mendekati atau melewati tenggat, mengirim pengingat langsung kepada pihak terkait.","PJA","Status terlambat","Pengingat terkirim","1 hari kerja setelah tenggat"],["5","Surat pengingat resmi: Bila belum ada tanggapan, mengirim surat pengingat resmi.","Sekjen","Pengingat awal tidak ditanggapi","Surat pengingat","3 hari kerja setelah pengingat awal"],["6","Eskalasi: Membahas kasus pada Rapat Pimpinan; memutuskan audiensi ulang atau pelaporan kepada KAUR ORMAWA atau Pembina.","Wapres; Presiden","Surat pengingat tanpa tanggapan","Keputusan eskalasi","Rapat Pimpinan berikutnya"],["7","Laporan mingguan: Menyusun ringkasan status tindak lanjut untuk Rapat Koordinasi dan Wakil Presiden.","PJA; Sekjen","Register Tindak Lanjut","Laporan mingguan","Setiap minggu"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pemantauan dilakukan minimal setiap minggu; pengingat awal 1 hari kerja setelah tenggat; surat resmi 3 hari kerja setelah pengingat awal. Hasil akhir: Register Tindak Lanjut terbaru dengan bukti pelaksanaan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Tindak lanjut tidak dilaksanakan setelah seluruh tahap eskalasi: kasus dicatat sebagai tidak dilaksanakan, dilaporkan kepada KAUR ORMAWA, dan diputuskan Rapat Pimpinan langkah berikutnya.","Tindak lanjut berubah karena kebijakan baru kampus: PJA memperbarui register dan melaporkan kepada Wakil Presiden.","Pihak terkait meminta perpanjangan waktu: disetujui Wakil Presiden dengan alasan tertulis dan tenggat baru.","Dugaan pembalasan atau tekanan terhadap pelapor: segera dialihkan ke SOP-ADV-011 dan SOP- SDM-17."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% janji tindak lanjut tercatat pada Register Tindak Lanjut.","Minimal 80% tindak lanjut selesai sesuai tenggat.","100% tindak lanjut terlambat mendapat pengingat dalam 1 hari kerja.","Tidak ada kasus tanpa pemantauan lebih dari 14 hari."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Tindak Lanjut.","Catatan dan bukti pemantauan.","Surat pengingat.","Laporan mingguan tindak lanjut. Seluruh dokumen disimpan pada repositori resmi BEM (folder Advokasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden meninjau Register Tindak Lanjut setiap minggu; Inspektur Jenderal memeriksa sampel kasus berstatus terlambat atau tidak dilaksanakan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Catat janji tindak lanjut → Pantau dan kumpulkan bukti → Nilai status → Terlambat? Pengingat → Surat resmi → Eskalasi → Selesai atau ADV-012"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Register Tindak Lanjut","Nomor tiket; tindakan; pihak penanggung jawab; indikator selesai; tenggat; status; bukti; catatan eskalasi."],["Templat Surat Pengingat","Nomor surat; rujukan Berita Acara; tindakan yang dijanjikan; tenggat; permintaan tanggapan; tembusan."],["Laporan Mingguan Tindak Lanjut","Jumlah kasus; status; kasus terlambat; eskalasi; kebutuhan dukungan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap janji tindak lanjut memiliki tenggat dan penanggung jawab.","☐ Ya ☐ Tidak"],["2","Pemantauan dilakukan minimal sekali seminggu.","☐ Ya ☐ Tidak"],["3","Status dinilai berdasarkan bukti.","☐ Ya ☐ Tidak"],["4","Pengingat dan eskalasi dilakukan sesuai tahap.","☐ Ya ☐ Tidak"],["5","Laporan mingguan disampaikan kepada Wakil Presiden.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADV-009","g":"Advokasi dan Aspirasi Mahasiswa","t":"Penyampaian Perkembangan kepada Mahasiswa","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[141,144],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara dan jadwal menyampaikan perkembangan penanganan aspirasi kepada pengaju dan mahasiswa secara transparan, tepat waktu, dan tetap menjaga kerahasiaan serta nama baik pihak mana pun."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pembaruan status kepada pengaju aspirasi dan pengumuman umum perkembangan advokasi kepada mahasiswa. Pernyataan resmi organisasi kepada publik mengikuti SOP-KOM-010; pembuatan konten mengikuti SOP-KOM-007."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 4 ayat (1) (kedaulatan di tangan mahasiswa) dan AD Pasal 17 ayat (2) (transparan dan akuntabel).","ART Pasal 3 (Kewajiban BEM) huruf d, e, dan g (menjaga nama baik; amanah dan transparan; laporan berkala).","ART Pasal 11 huruf a, g, dan h (larangan SARA, pencemaran nama baik, dan perundungan).","ART Pasal 13 ayat (7) dan (9) (keadilan, objektivitas, hak klarifikasi).","SOP-ADV-011 (perlindungan identitas pelapor)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pembaruan status","Pemberitahuan kepada pengaju tentang tahapan terkini penanganan aspirasinya."],["Ringkasan publik","Ringkasan perkembangan kasus tanpa identitas pelapor dan data pribadi untuk disampaikan kepada seluruh mahasiswa."],["Status kasus","Diterima; diverifikasi; diproses; ditindaklanjuti; selesai; dialihkan; dihentikan; ditolak dengan alasan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap pengaju berhak menerima pembaruan status pada setiap perubahan tahapan dan minimal setiap 7 hari kerja selama kasus aktif.","Pembaruan memuat: nomor tiket, status, langkah yang telah dilakukan, langkah berikutnya, dan perkiraan waktu; tidak menjanjikan hasil yang belum pasti.","Penolakan, pengalihan, atau penghentian wajib disertai alasan tertulis dan arahan jalur lain yang tersedia.","Ringkasan publik hanya untuk kasus bersifat terbuka, tidak memuat identitas pelapor, data pribadi, dan bukti rahasia, serta tidak menuduh pihak mana pun tanpa fakta terverifikasi.","Ringkasan publik dan pengumuman disetujui Presiden sebelum disebarkan; konten mengikuti SOP- KOM-007.","Kasus berstatus terbatas atau rahasia hanya diperbarui kepada pengaju melalui kanal yang aman.","Pengumuman perkembangan rutin disampaikan melalui kanal resmi, misalnya setiap bulan, termasuk rekap jumlah aspirasi dan status tanpa data pribadi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Penanggung jawab advokasi","R","Menyusun pembaruan status dan ringkasan publik berdasarkan data terkini."],["Wakil Presiden","A","Menyetujui pembaruan dan bertanggung jawab akhir atas keterbukaan layanan."],["Presiden","R","Menyetujui ringkasan publik dan pengumuman."],["Biro Desain Komunikasi Visual","R","Mendesain dan menyebarkan materi perkembangan melalui kanal resmi."],["Petugas piket aspirasi","R","Mengirim pembaruan status kepada pengaju dan mencatat umpan balik."],["Inspektur Jenderal","C","Menelaah kerahasiaan dan kebenaran isi pada kasus sensitif."],["Pengaju dan mahasiswa","I","Menerima informasi dan memberi umpan balik."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Register Aspirasi dan Register Tindak Lanjut.","Berita Acara dan notulen terkini.","Templat Pembaruan Status."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan jadwal pembaruan: Menetapkan jadwal pembaruan kasus berdasarkan prioritas dan tahapan.","PJA","Daftar Prioritas Kasus","Jadwal pembaruan","Saat kasus ditugaskan"],["2","Penyusunan pembaruan: Menyusun pembaruan status dan, bila kasus terbuka, ringkasan publik.","PJA","Data terkini, templat","Draf pembaruan","1 hari kerja"],["3","Pemeriksaan kerahasiaan dan kebenaran: Memeriksa bahwa tidak ada identitas pelapor, data pribadi, atau tuduhan tanpa bukti.","Wapres; Irjen bila sensitif","Draf pembaruan","Draf layak kirim","1 hari kerja"],["4","Persetujuan: Wakil Presiden menyetujui pembaruan pengaju; Presiden menyetujui ringkasan publik.","Wapres; Presiden","Draf layak kirim","Pembaruan disetujui","1 hari kerja"],["5","Pengiriman kepada pengaju: Mengirim pembaruan melalui kanal yang dipilih pengaju dan mencatat waktu kirim.","Petugas piket","Pembaruan disetujui","Pembaruan terkirim","Setiap perubahan tahapan; min. 7 hari kerja"],["6","Publikasi ringkasan: Mendesain dan menyebarkan ringkasan publik melalui kanal resmi.","Biro Desain Komunikasi Visual","Ringkasan disetujui","Materi terpublikasi","2 hari kerja setelah persetujuan"],["7","Pencatatan umpan balik: Mencatat tanggapan pengaju dan mahasiswa serta menindaklanjuti bila ada koreksi.","Petugas piket; PJA","Tanggapan","Catatan umpan balik","Terus-menerus"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pembaruan kepada pengaju dikirim pada setiap perubahan tahapan dan paling lambat setiap 7 hari kerja selama kasus aktif; ringkasan publik dipublikasikan paling lambat 2 hari kerja setelah disetujui. Hasil akhir: pembaruan terkirim dan tercatat."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengaju tidak dapat dihubungi: dicoba melalui dua kanal; bila gagal dicatat dan kasus tetap berjalan.","Pihak yang disebut dalam ringkasan keberatan atas isinya: PJA meninjau ulang berdasarkan bukti dan memberi kesempatan klarifikasi.","Informasi keliru terlanjur dipublikasikan: dikoreksi sesuai SOP-KOM-009.","Kasus berkembang menjadi isu reputasi: SOP-KOM-012 dan SOP-RSK-11.","Pengaju tidak puas dengan hasil: diberi penjelasan, kesempatan menambah bukti, dan arahan jalur banding melalui Rapat Pimpinan atau KAUR ORMAWA."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% pengaju menerima pembaruan sesuai jadwal.","100% penolakan atau penghentian disertai alasan tertulis.","Tidak ada pelanggaran kerahasiaan pada ringkasan publik.","Rekap aspirasi dipublikasikan setiap bulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Pembaruan status kepada pengaju.","Ringkasan publik.","Rekap aspirasi bulanan.","Catatan umpan balik. Seluruh dokumen disimpan pada repositori resmi BEM (folder Advokasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden memeriksa ketepatan jadwal pembaruan setiap bulan; Inspektur Jenderal memeriksa sampel pembaruan dan ringkasan publik terhadap kerahasiaan dan kebenaran isi."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Jadwal pembaruan → Susun pembaruan → Periksa kerahasiaan dan kebenaran → Persetujuan → Kirim ke pengaju → Publikasi ringkasan → Catat umpan balik → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Pembaruan Status","Nomor tiket; status; langkah yang telah dilakukan; langkah berikutnya; perkiraan waktu; kontak."],["Templat Ringkasan Publik","Judul isu; status; ringkasan tanpa identitas; tindak lanjut; tanggal."],["Catatan Umpan Balik","Nomor tiket; tanggal; umpan balik; tindak lanjut."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Identitas pelapor dan data pribadi tidak tercantum.","☐ Ya ☐ Tidak"],["2","Isi hanya fakta terverifikasi.","☐ Ya ☐ Tidak"],["3","Presiden menyetujui ringkasan publik.","☐ Ya ☐ Tidak"],["4","Pembaruan terkirim sesuai jadwal dan tercatat.","☐ Ya ☐ Tidak"],["5","Penolakan atau penghentian disertai alasan tertulis.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADV-010","g":"Advokasi dan Aspirasi Mahasiswa","t":"Penanganan Pengaduan Rahasia","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[145,148],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara menerima dan menangani pengaduan yang memerlukan kerahasiaan, seperti dugaan pelecehan, perundungan, penyalahgunaan dana atau aset, dan pelanggaran etik, secara aman, adil, dan berdasarkan bukti, serta menyalurkannya kepada pihak yang berwenang."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pengaduan mahasiswa atau pengurus yang meminta dirahasiakan atau yang bersifat sensitif. SOP ini mengatur penerimaan, penilaian awal, dan penyaluran; proses penanganan lanjutan mengikuti SOP- RSK-04, SOP-RSK-05, SOP-RSK-07, dan SOP-SDM-13 yang akan disusun pada tahap berikutnya."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 11 huruf f, h, i, dan k (larangan narkoba dan zat haram, asusila, pelecehan, perundungan, korupsi dan penyelewengan dana, serta penyalahgunaan fasilitas).","ART Pasal 12 ayat (3) sampai (8) (pengawasan Irjen; pelanggaran individu; pelaporan pelanggaran berat kepada KAUR ORMAWA; kewenangan KAUR ORMAWA terhadap BPM).","ART Pasal 13 ayat (4), (7), (8), dan (9) (bukti, keadilan, jangka waktu proporsional, hak klarifikasi dan pembelaan).","ART Pasal 3 (Kewajiban BEM) huruf d (menjaga nama baik dan ketertiban).","AD Pasal 9 ayat (2) (alasan pemberhentian anggota)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pengaduan rahasia","Pengaduan yang identitas pelapornya, isinya, atau keduanya wajib dijaga dan hanya diakses pihak berwenang."],["Petugas penerima rahasia","Pengurus yang ditunjuk Presiden untuk menerima pengaduan rahasia."],["Penilaian risiko awal","Pemeriksaan cepat atas keselamatan pelapor dan keseriusan dugaan."],["Register Terbatas","Register pengaduan rahasia dengan akses hanya bagi Presiden dan petugas penerima rahasia."],["Penyaluran","Penerusan pengaduan kepada pihak berwenang untuk ditangani."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Presiden menunjuk petugas penerima rahasia (usulan: dua orang, sebaiknya satu laki-laki dan satu perempuan) yang telah menandatangani Pernyataan Kerahasiaan.","Kanal rahasia terpisah dari kanal aspirasi biasa: formulir tertutup dan pertemuan tatap muka dengan petugas penerima rahasia.","Pelapor tidak boleh dipaksa membuka identitas kepada pihak selain petugas penerima rahasia dan Presiden.","Kategori utama: (1) pelecehan atau perundungan; (2) penyalahgunaan dana atau aset; (3) pelanggaran etik pengurus; (4) ancaman atau intimidasi; (5) lainnya.","Penyaluran: pelanggaran oleh pengurus BEM ke Inspektur Jenderal (ART Pasal 12 ayat 3 dan 6); pelanggaran berat berdampak pada institusi dilaporkan Irjen kepada KAUR ORMAWA (ayat 7); pelanggaran oleh BPM kepada KAUR ORMAWA (ayat 8).","Pengaduan yang menyangkut keselamatan jiwa atau tindak pidana segera diteruskan kepada Pembina atau KAUR ORMAWA dan, bila perlu, pihak berwenang.","Pelapor dan korban didampingi dan ditawarkan bantuan; BEM tidak menjanjikan hasil tertentu.","Pihak terlapor tetap memiliki hak klarifikasi dan pembelaan (ART Pasal 13 ayat 9) tanpa membuka identitas pelapor.","Pengaduan yang menyangkut Presiden, Wakil Presiden, atau petugas penerima rahasia disalurkan langsung kepada Inspektur Jenderal dan KAUR ORMAWA."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menunjuk petugas, menetapkan penyaluran, dan bertanggung jawab akhir atas perlindungan pelapor."],["Petugas penerima rahasia","R","Menerima pengaduan, melakukan penilaian risiko awal, mencatat, dan mendampingi pelapor."],["Inspektur Jenderal","R","Menelaah pengaduan tentang pengurus dan melaporkan pelanggaran berat kepada KAUR ORMAWA."],["Wakil Presiden","C","Memberi masukan atas penyaluran dan koordinasi dengan unit terkait."],["Sekretaris Jenderal","I","Menerima informasi minimal untuk keperluan arsip terbatas."],["KAUR ORMAWA / Pembina","I","Menerima pelaporan pelanggaran berat atau yang berdampak pada institusi."],["Pelapor","R","Menyampaikan pengaduan dan bukti yang dimiliki."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Pengaduan Rahasia.","Bukti yang dimiliki pelapor.","Daftar petugas penerima rahasia.","Daftar rute penyaluran."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penunjukan petugas: Menunjuk petugas penerima rahasia, mengumumkan kanal rahasia, dan memastikan pernyataan kerahasiaan ditandatangani.","Presiden","Daftar kandidat","Petugas dan kanal rahasia siap","Awal periode"],["2","Penerimaan pengaduan: Menerima pengaduan melalui kanal rahasia; mendengar pelapor tanpa menghakimi; mencatat pokok pengaduan.","Petugas penerima rahasia","Formulir, keterangan pelapor","Pengaduan diterima","1 hari kerja; mendesak maks. 6 jam"],["3","Penilaian risiko awal: Menilai keselamatan pelapor, keseriusan dugaan, dan kategori; menentukan perlunya perlindungan segera.","Petugas penerima rahasia; Presiden","Pengaduan","Penilaian risiko dan kategori","Maks. 24 jam"],["4","Pencatatan terbatas: Mencatat pada Register Terbatas dengan kode pelapor sesuai SOP- ADV-011.","Petugas penerima rahasia","Pengaduan, penilaian risiko","Entri Register Terbatas","Hari yang sama"],["5","Penetapan penyaluran: Menetapkan pihak penerima: Irjen, KAUR ORMAWA, Pembina, atau jalur SOP-RSK dan SOP-SDM; memeriksa konflik kepentingan.","Presiden","Penilaian risiko, daftar rute","Keputusan penyaluran","1 hari kerja"],["6","Penyaluran dan pendampingan: Menyalurkan pengaduan tanpa identitas pelapor; mendampingi pelapor dan memberi tahu langkah berikutnya.","Petugas penerima rahasia; Irjen","Keputusan penyaluran","Pengaduan tersalurkan","1 hari kerja"],["7","Pemantauan: Memantau penanganan oleh pihak berwenang dan memberi pembaruan terbatas kepada pelapor.","Petugas penerima rahasia; Irjen","Register Terbatas","Pembaruan kepada pelapor","Minimal setiap 14 hari"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pengaduan diterima paling lambat 1 hari kerja (mendesak: 6 jam), dinilai risikonya paling lambat 24 jam, dan disalurkan paling lambat 1 hari kerja setelah penilaian. Hasil akhir: pengaduan tercatat pada Register Terbatas dan tersalurkan kepada pihak berwenang."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Ancaman terhadap keselamatan pelapor atau korban: Presiden segera melapor kepada Pembina atau KAUR ORMAWA dan pihak berwenang.","Pengaduan terhadap pengurus yang menjadi petugas, Presiden, atau Wakil Presiden: disalurkan kepada Inspektur Jenderal dan KAUR ORMAWA.","Pelapor menarik pengaduan: dicatat; penanganan dilanjutkan bila ada bukti dan dampak serius pada institusi.","Pengaduan tidak cukup bukti: dicatat, pelapor diberi arahan melengkapi bukti, dan kasus dapat dibuka kembali.","Pengaduan mengandung tuduhan palsu atau pencemaran nama baik: diproses sesuai ART Pasal 11 huruf g dan Pasal 12."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pengaduan rahasia tercatat pada Register Terbatas.","100% pengaduan dinilai risikonya dalam 24 jam.","Tidak ada kebocoran identitas pelapor.","100% pengaduan tersalurkan kepada pihak yang berwenang sesuai kategori."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Pengaduan Rahasia.","Penilaian risiko awal.","Entri Register Terbatas.","Keputusan penyaluran dan bukti penyaluran. Seluruh dokumen disimpan pada repositori resmi BEM (folder Advokasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Presiden meninjau Register Terbatas setiap bulan tanpa membuka identitas pelapor; Inspektur Jenderal memeriksa kepatuhan prosedur melalui kode kasus."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengaduan rahasia diterima → Penilaian risiko → Catat di Register Terbatas → Penetapan penyaluran → Irjen / KAUR ORMAWA / jalur RSK-SDM → Pendampingan dan pemantauan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pengaduan Rahasia","Kode pelapor; kategori; ringkasan; waktu dan tempat; pihak yang diadukan; bukti; permintaan perlindungan; kontak aman."],["Lembar Penilaian Risiko Awal","Kode kasus; ancaman keselamatan; keseriusan; rekomendasi penyaluran; tanggal."],["Register Terbatas","Kode kasus; kategori; tanggal; penyaluran; status; petugas."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Petugas penerima rahasia telah menandatangani pernyataan kerahasiaan.","☐ Ya ☐ Tidak"],["2","Pengaduan dicatat pada Register Terbatas dengan kode.","☐ Ya ☐ Tidak"],["3","Penilaian risiko dilakukan dalam 24 jam.","☐ Ya ☐ Tidak"],["4","Penyaluran sesuai kategori dan tanpa identitas pelapor.","☐ Ya ☐ Tidak"],["5","Pelapor didampingi dan menerima pembaruan terbatas.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADV-011","g":"Advokasi dan Aspirasi Mahasiswa","t":"Perlindungan Identitas Pelapor","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[149,153],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan aturan dan langkah menjaga kerahasiaan identitas pelapor dan data pribadinya sepanjang proses advokasi dan pengaduan, serta mencegah pembalasan, sehingga mahasiswa berani melapor tanpa takut dirugikan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus, petugas, dan pihak yang memegang data pelapor dalam kegiatan advokasi, baik pada kasus terbuka, terbatas, maupun rahasia. Perlindungan data pribadi anggota BEM secara umum diatur SOP-SDM-18 dan pengamanan akses digital SOP-RSK-08."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 11 huruf g dan h (larangan mencemarkan nama baik serta melakukan pelecehan atau perundungan).","ART Pasal 12 ayat (1) sampai (6) (pembinaan, sanksi, dan pengawasan Irjen).","ART Pasal 13 ayat (7) dan (9) (keadilan, objektivitas, hak klarifikasi dan pembelaan).","ART Pasal 3 (Kewajiban BEM) huruf d dan e (menjaga nama baik dan amanah).","AD Pasal 9 ayat (2) huruf a sampai c (pemberhentian anggota karena pelanggaran syariat, prinsip organisasi, dan merugikan nama baik)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pelapor","Mahasiswa atau pengurus yang menyampaikan aspirasi atau pengaduan dan identitasnya wajib dijaga."],["Kode pelapor","Nama samaran atau nomor yang dipakai pada semua dokumen kerja sebagai pengganti identitas asli."],["Tingkat akses","Pembatasan pihak yang boleh melihat data pelapor: Tingkat 1 (petugas penerima rahasia dan Presiden) dan Tingkat 2 (PJA, hanya kode)."],["Pembalasan (retaliasi)","Tindakan merugikan, menekan, atau mengintimidasi pelapor karena pelaporannya."],["Pengungkapan","Pembukaan identitas pelapor kepada pihak yang tidak berhak."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Identitas asli pelapor hanya diketahui Tingkat 1. Seluruh dokumen kerja (Laporan Verifikasi, notulen, Naskah Audiensi, laporan) memakai kode pelapor.","Data identitas disimpan terpisah dari berkas kasus, pada media dengan kata sandi atau pengaman fisik, dan hanya diakses Tingkat 1.","Pelapor dapat memilih tingkat keterbukaan: anonim penuh, hanya kepada petugas, atau terbuka; pilihannya dihormati dan dicatat.","Identitas hanya boleh dibuka dengan persetujuan tertulis pelapor atau karena kewajiban hukum atau perintah pihak berwenang kampus; pembukaan diputuskan Presiden dan pelapor diberi tahu lebih dahulu.","Dilarang menyebarkan, mencari tahu, menebak, atau menanyakan identitas pelapor kepada pihak yang tidak berhak, termasuk dengan tangkapan layar atau percakapan pribadi.","Pembalasan terhadap pelapor merupakan pelanggaran berat yang ditangani sesuai ART Pasal 12 dan SOP-SDM-13; pelapor yang merasa ditekan wajib dilindungi segera.","Perlindungan identitas tidak menghapus hak pihak terlapor atas klarifikasi dan pembelaan; klarifikasi dilakukan tanpa membuka identitas pelapor.","Pelapor yang terbukti sengaja memberi laporan palsu tidak mendapat perlindungan identitas dan ditangani sesuai ART Pasal 11 huruf g dan Pasal 12."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan aturan perlindungan, memutuskan pengungkapan bila diwajibkan, dan bertanggung jawab akhir."],["Petugas penerima rahasia","R","Menetapkan kode pelapor, menyimpan data identitas, dan mengendalikan akses."],["Penanggung jawab advokasi dan tim","R","Bekerja hanya dengan kode pelapor dan menjaga kerahasiaan."],["Sekretaris Jenderal","R","Menyiapkan penyimpanan terpisah dan mencatat akses terbatas pada arsip."],["Inspektur Jenderal","C","Mengaudit akses dan menangani dugaan kebocoran atau pembalasan."],["Wakil Presiden","C","Memastikan seluruh unit memahami aturan dan melaporkan pelanggaran."],["Pelapor","I","Diberi tahu hak dan batas perlindungan; melaporkan bila merasa terancam."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Pengaduan atau aspirasi yang memerlukan perlindungan.","Pilihan tingkat keterbukaan pelapor.","Pernyataan Kerahasiaan.","Daftar akses."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan tingkat keterbukaan: Menanyakan dan mencatat pilihan pelapor tentang tingkat keterbukaan identitas serta menjelaskan batas perlindungan.","Petugas penerima rahasia","Pengaduan, pilihan pelapor","Tingkat keterbukaan tercatat","Saat penerimaan"],["2","Pemberian kode pelapor: Memberi kode pelapor dan memisahkan data identitas dari berkas kasus.","Petugas penerima rahasia","Data pelapor","Kode pelapor; berkas identitas terpisah","1 hari kerja"],["3","Pengaturan akses: Menetapkan daftar pihak yang boleh mengakses (Tingkat 1 dan 2) dan membatasi akses media digital maupun fisik.","Presiden; Sekjen","Daftar pihak","Daftar akses","1 hari kerja"],["4","Pernyataan kerahasiaan: Memastikan seluruh pihak yang memegang data menandatangani pernyataan kerahasiaan.","PJA dan tim; petugas","Daftar akses","Pernyataan tertandatangani","Sebelum akses diberikan"],["5","Penggunaan kode pada dokumen: Memeriksa bahwa dokumen kerja hanya memuat kode pelapor sebelum dibagikan atau dipublikasikan.","PJA; Sekjen","Dokumen kerja","Dokumen bebas identitas","Setiap dokumen"],["6","Pemantauan perlindungan: Memeriksa tanda pembalasan, tekanan, atau kebocoran; menghubungi pelapor secara berkala secara aman.","Petugas penerima rahasia; Irjen","Daftar akses, laporan pelapor","Catatan pemantauan","Minimal setiap 14 hari"],["7","Penanganan pelanggaran: Menghentikan akses pihak yang melanggar, melaporkan kepada Irjen, dan menangani sesuai ART Pasal 12 serta SOP-SDM-13.","Presiden; Irjen","Laporan pelanggaran","Tindakan korektif","Maks. 24 jam sejak diketahui"],["8","Pencabutan akses dan penutupan: Saat kasus ditutup, mencabut akses, menyimpan berkas identitas dengan aman, dan mencatat penutupan.","Petugas; Sekjen","Berita Acara penutupan","Akses dicabut; berkas aman","2 hari kerja setelah penutupan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Kode pelapor dan pemisahan data selesai paling lambat 1 hari kerja sejak aspirasi atau pengaduan diterima; dugaan kebocoran atau pembalasan ditindak paling lambat 24 jam sejak diketahui. Hasil akhir: identitas pelapor terlindungi dan akses tercatat sampai kasus ditutup."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pelapor meminta identitasnya dibuka: dibuka dengan persetujuan tertulis dan dicatat.","Pihak berwenang kampus meminta identitas: Presiden memutuskan dengan konsultasi kepada Pembina; pelapor diberi tahu lebih dahulu sejauh memungkinkan.","Identitas bocor: segera dilaporkan kepada Presiden dan Irjen; pelapor dilindungi; berlaku SOP-RSK-09 (penanganan kebocoran data).","Pelapor mengalami pembalasan atau tekanan: perlindungan segera diberikan dan dilaporkan kepada Pembina atau KAUR ORMAWA bila perlu.","Pelapor ternyata memberi laporan palsu secara sengaja: perlindungan dicabut dan Presiden menetapkan langkah sesuai ART."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% dokumen kerja kasus hanya memuat kode pelapor.","Tidak ada kebocoran identitas pelapor.","100% pihak yang mengakses data pelapor menandatangani pernyataan kerahasiaan.","Dugaan pembalasan ditindak dalam 24 jam."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar kode pelapor dan tingkat keterbukaan (terbatas).","Daftar akses dan pernyataan kerahasiaan.","Catatan pemantauan perlindungan.","Laporan pelanggaran dan tindakan korektif (bila ada). Seluruh dokumen disimpan pada repositori resmi BEM (folder Advokasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Inspektur Jenderal mengaudit daftar akses dan sampel dokumen kasus setiap bulan terhadap kebocoran identitas; Presiden menerima laporan tanpa membuka identitas."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tentukan tingkat keterbukaan → Beri kode dan pisahkan data → Atur akses → Pernyataan kerahasiaan → Pantau perlindungan → Cabut akses saat kasus tutup → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pilihan Keterbukaan Identitas","Kode pelapor; pilihan (anonim, hanya petugas, terbuka); persetujuan; tanggal; tanda tangan."],["Pernyataan Kerahasiaan","Nama; jabatan; kode kasus; janji menjaga rahasia; sanksi; tanda tangan."],["Daftar Akses Data Pelapor","Kode kasus; nama pemegang akses; tingkat; tanggal beri dan cabut akses."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pelapor telah diberi penjelasan batas perlindungan.","☐ Ya ☐ Tidak"],["2","Kode pelapor dipakai pada seluruh dokumen kerja.","☐ Ya ☐ Tidak"],["3","Data identitas disimpan terpisah dengan akses terbatas.","☐ Ya ☐ Tidak"],["4","Pernyataan kerahasiaan ditandatangani semua pemegang akses.","☐ Ya ☐ Tidak"],["5","Akses dicabut dan berkas aman setelah kasus ditutup.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADV-012","g":"Advokasi dan Aspirasi Mahasiswa","t":"Dokumentasi dan Penutupan Kasus","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[154,157],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara mendokumentasikan seluruh proses advokasi dan menutup kasus secara resmi, termasuk evaluasi pembelajaran dan pengarsipan, sehingga setiap kasus dapat dipertanggungjawabkan dan menjadi pengetahuan bagi kabinet berikutnya."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kasus aspirasi yang telah selesai, dialihkan, dihentikan, atau ditolak. SOP ini tidak mengatur pengarsipan umum (SOP-ADM-12 sampai ADM-15) dan serah terima akhir kabinet (SOP-TRN- 03), tetapi menjadi masukan bagi keduanya."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) sampai (3) (laporan pertanggungjawaban, transparan, akuntabel; hasil dilaporkan kepada KAUR ORMAWA).","ART Pasal 3 (Kewajiban BEM) huruf g (laporan berkala) dan ART Bab III (Tugas BEM) huruf e (laporan pertanggungjawaban pada akhir masa jabatan).","ART Pasal 10 (Rapat Koordinasi) ayat (5) (hasil dituangkan dalam notulensi).","ART Pasal 9 (Rapat Kerja) dan ART Pasal 7 ayat (5) (evaluasi kinerja organisasi pada Mubes).","SOP-ADV-011 (perlindungan identitas pelapor)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Penutupan kasus","Penetapan resmi bahwa penanganan suatu kasus telah berakhir."],["Dossier kasus","Berkas lengkap kasus: aspirasi, verifikasi, konsultasi, audiensi, tindak lanjut, dan bukti."],["Berita Acara Penutupan","Dokumen yang menyatakan alasan, status akhir, dan pembelajaran suatu kasus."],["Pembukaan kembali","Pengaktifan kasus tertutup karena ada fakta atau bukti baru."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Status akhir kasus: selesai (tuntas); selesai sebagian dengan persetujuan pengaju; dialihkan; dihentikan (tidak terverifikasi atau dicabut); atau ditolak dengan alasan.","Syarat penutupan: tindak lanjut selesai atau telah melewati seluruh tahap eskalasi (SOP-ADV-008), pengaju telah diberi tahu hasil (SOP-ADV-009), dan Dossier kasus lengkap.","Penutupan diputuskan Wakil Presiden; kasus Prioritas 1, kasus yang berdampak pada institusi, dan kasus rahasia ditutup dengan persetujuan Presiden.","Dokumentasi memuat urutan peristiwa, keputusan, bukti, dan komunikasi; identitas pelapor tidak termuat dalam Dossier (SOP-ADV-011).","Setiap kasus ditutup dengan evaluasi pembelajaran: apa yang berhasil, hambatan, masalah berulang, dan perbaikan prosedur; masalah berulang dicatat untuk tindakan korektif (SOP-MONEV-09 dan MONEV-10).","Kasus tertutup dapat dibuka kembali dalam 30 hari (usulan) bila ada fakta atau bukti baru, atas persetujuan Wakil Presiden.","Rekap kasus dilaporkan dalam laporan bulanan (SOP-ADM-19) dan laporan akhir kabinet (SOP- MONEV-12 dan SOP-TRN-01)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Penanggung jawab advokasi","R","Melengkapi Dossier kasus, menyusun usulan penutupan dan evaluasi pembelajaran."],["Wakil Presiden","A","Memutuskan penutupan dan bertanggung jawab akhir atas kelengkapan dokumentasi."],["Presiden","R","Menyetujui penutupan kasus Prioritas 1, berdampak institusi, atau rahasia."],["Sekretaris Jenderal","R","Mengarsipkan Dossier, mencatat pada register, dan menyusun rekap bulanan."],["Inspektur Jenderal","C","Memeriksa kelengkapan Dossier dan alasan penutupan pada sampel kasus."],["Pengaju","I","Menerima pemberitahuan penutupan dan dapat menyampaikan keberatan."],["Pengurus Unit Advokasi","I","Memakai hasil evaluasi untuk perbaikan layanan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Dossier kasus.","Register Aspirasi dan Register Tindak Lanjut.","Pemberitahuan hasil kepada pengaju."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pemeriksaan syarat penutupan: Memastikan tindak lanjut selesai atau seluruh eskalasi ditempuh, pengaju telah diberi tahu, dan bukti lengkap.","PJA","Register Tindak Lanjut, Dossier","Kasus layak ditutup","2 hari kerja"],["2","Penyusunan Dossier: Melengkapi dan menertibkan Dossier; memastikan tidak ada identitas pelapor.","PJA; Sekjen","Seluruh dokumen kasus","Dossier lengkap","3 hari kerja"],["3","Evaluasi pembelajaran: Menyusun catatan pembelajaran: keberhasilan, hambatan, masalah berulang, dan saran perbaikan.","PJA","Dossier","Catatan Evaluasi Kasus","2 hari kerja"],["4","Usulan penutupan: Mengajukan Berita Acara Penutupan kepada Wakil Presiden.","PJA","Dossier, catatan evaluasi","Usulan penutupan","1 hari kerja"],["5","Keputusan penutupan: Memutuskan penutupan; kasus tertentu disetujui Presiden.","Wapres; Presiden","Usulan penutupan","Berita Acara Penutupan","2 hari kerja"],["6","Pemberitahuan kepada pengaju: Memberi tahu pengaju tentang status akhir, alasan, dan hak mengajukan keberatan atau membuka kembali.","Petugas piket aspirasi","Berita Acara Penutupan","Pengaju terinformasi","1 hari kerja"],["7","Pencatatan dan pengarsipan: Memperbarui register, mengarsipkan Dossier pada repositori resmi, dan mencatat dalam rekap bulanan.","Sekjen","Dossier tertutup","Arsip lengkap; rekap diperbarui","2 hari kerja"],["8","Tindak lanjut pembelajaran: Membawa masalah berulang dan saran perbaikan ke Rapat Evaluasi atau evaluasi SOP.","Wakil Presiden","Catatan evaluasi","Rencana perbaikan","Pada evaluasi terdekat"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penutupan kasus selesai paling lambat 5 hari kerja setelah syarat penutupan terpenuhi, dan pengarsipan paling lambat 2 hari kerja setelah penutupan. Hasil akhir: Berita Acara Penutupan, Dossier kasus, dan Catatan Evaluasi Kasus."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengaju keberatan atas penutupan: dibahas Wakil Presiden dan, bila perlu, Rapat Pimpinan; kasus dapat dibuka kembali bila ada alasan baru.","Dossier tidak lengkap: penutupan ditunda sampai kelengkapan terpenuhi atau ketidaklengkapan dicatat dengan alasan.","Kasus mengungkap pelanggaran oleh pengurus: dilimpahkan ke Inspektur Jenderal (ART Pasal 12) dan SOP-SDM-13 sebelum ditutup.","Kasus tidak dapat ditutup karena menunggu keputusan kampus: berstatus menunggu dan ditinjau setiap bulan.","Akhir masa jabatan kabinet: kasus belum selesai dicatat dan diserahterimakan (SOP-TRN-08)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kasus tertutup memiliki Dossier lengkap dan Berita Acara Penutupan.","Penutupan selesai dalam 5 hari kerja pada minimal 90% kasus.","100% kasus tertutup memiliki Catatan Evaluasi Kasus.","Tidak ada Dossier yang memuat identitas pelapor."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Berita Acara Penutupan.","Dossier kasus yang diarsipkan.","Catatan Evaluasi Kasus.","Rekap kasus bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Advokasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan arsip kasus tertutup setiap bulan; Inspektur Jenderal mengambil sampel Dossier untuk diperiksa pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Cek syarat penutupan → Lengkapi Dossier → Evaluasi pembelajaran → Keputusan penutupan → Beri tahu pengaju → Arsip dan rekap → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Berita Acara Penutupan Kasus","Nomor tiket; status akhir; alasan; ringkasan hasil; tanggal; tanda tangan Wapres atau Presiden."],["Daftar Isi Dossier Kasus","Daftar dokumen; tanggal; lokasi arsip; tanda pemeriksaan; pemeriksa."],["Catatan Evaluasi Kasus","Hal yang berhasil; hambatan; masalah berulang; saran perbaikan; penanggung jawab tindak lanjut."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh tindak lanjut selesai atau eskalasi ditempuh.","☐ Ya ☐ Tidak"],["2","Pengaju telah diberi tahu hasil dan hak keberatan.","☐ Ya ☐ Tidak"],["3","Dossier lengkap dan bebas identitas pelapor.","☐ Ya ☐ Tidak"],["4","Catatan evaluasi tersusun.","☐ Ya ☐ Tidak"],["5","Dossier diarsipkan dan register diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-001","g":"Keuangan dan Pengadaan","t":"Penyusunan Rencana Anggaran Tahunan Kabinet","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[163,167],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan, pembahasan, persetujuan, dan sosialisasi Rencana Anggaran Tahunan (RAT) Kabinet Samasta, sehingga seluruh program kerja memiliki sumber dana yang jelas, kebutuhan biaya terhitung, dan anggaran disusun sesuai waktu pengumpulan anggaran kampus."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk Presiden, Wakil Presiden, Sekretaris Jenderal, Menteri, Kepala Biro, Inspektur Jenderal, dan Biro Keuangan dalam menyusun anggaran seluruh program kerja satu periode kepengurusan. SOP ini tidak mengatur anggaran per program (lihat SOP-KEU-002) dan tidak mengatur persetujuan atas pengajuan anggaran program (lihat SOP-KEU-003)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) sampai (4) (sumber dana, bebas riba, gharar, dan maysir, serta penyusunan anggaran sesuai waktu pengumpulan anggaran kampus dengan persetujuan KAUR ORMAWA).","ART Bab III (Tugas) huruf e (penyusunan anggaran dan program kerja tahunan dengan persetujuan BPM).","ART Pasal 9 ayat (3) huruf d dan ayat (6) (penyusunan anggaran biaya dalam Rapat Kerja dan persetujuan Pembina).","ART Pasal 2 huruf f dan ART Pasal 3 (Kewajiban) huruf e (pengelolaan pendanaan secara terbuka, amanah, dan transparan).","SOP-GOV-002 (Pengambilan Keputusan) dan SOP-GOV-006 (Rapat Kabinet)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["RAT","Rencana Anggaran Tahunan: dokumen yang memuat seluruh rencana pemasukan dan pengeluaran Kabinet Samasta selama satu periode."],["Pagu","Batas maksimal dana yang dapat dipakai suatu unit atau program."],["Sumber dana","Asal dana sebagaimana AD Pasal 15 ayat (1): dana kemahasiswaan, hibah atau donasi atau sponsor, usaha halal, dan hasil pengembangan aset."],["Daftar harga acuan","Daftar harga satuan barang dan jasa yang dipakai sebagai patokan kewajaran biaya dalam RAB."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["RAT disusun bersamaan dengan Rapat Kerja pada awal periode dan wajib mengikuti jadwal pengumpulan anggaran kampus yang diinformasikan KAUR ORMAWA.","Seluruh rencana pengeluaran harus dapat ditelusuri pada program kerja yang tercantum di program kerja tahunan; tidak ada pos tanpa program.","Seluruh sumber dana yang direncanakan harus halal dan bebas dari riba, gharar, dan maysir (AD Pasal 15 ayat 2). Rencana dana sponsor dan donasi diperhitungkan hanya setelah ada komitmen tertulis.","RAT memuat pos biaya tak terduga paling banyak 5% dari total anggaran (usulan) dan pos dana cadangan operasional sekretariat.","RAT yang membutuhkan persetujuan pihak luar (BPM, KAUR ORMAWA, Pembina) belum berlaku sebelum persetujuan diperoleh."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menyetujui dan menetapkan RAT sebagai dasar pelaksanaan anggaran kabinet."],["Kepala Biro Keuangan","R","Menerbitkan format dan kalender penyusunan, mengonsolidasikan kebutuhan unit, dan menyusun draf RAT."],["Menteri / Kabiro","R","Menyampaikan kebutuhan anggaran unit berdasarkan program kerja dan menjelaskan dasar perhitungannya."],["Wakil Presiden","C","Menelaah prioritas dan keseimbangan anggaran antarunit."],["Sekretaris Jenderal","R","Menyiapkan rapat pembahasan, mencatat keputusan, dan mengarsipkan dokumen."],["Inspektur Jenderal","C","Memeriksa keselarasan draf RAT dengan AD/ART dan aturan kampus."],["BPM, KAUR ORMAWA, Pembina","I","Memberikan persetujuan atau masukan sesuai kewenangan masing-masing."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Program kerja tahunan hasil Rapat Kerja.","Kalender anggaran kampus dan plafon dana kemahasiswaan yang diinformasikan KAUR ORMAWA.","Laporan keuangan dan realisasi kabinet sebelumnya, bila ada.","Daftar harga acuan Biro Keuangan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan kalender dan format: Biro Keuangan memperoleh jadwal anggaran kampus dari KAUR ORMAWA, lalu menerbitkan kalender penyusunan, Formulir Kebutuhan Anggaran Unit, dan daftar harga acuan.","Kabiro Keuangan","Kalender kampus, program kerja","Kalender dan format terbit","2 hari kerja setelah program kerja ditetapkan"],["2","Usulan kebutuhan unit: Setiap unit mengisi Formulir Kebutuhan Anggaran Unit: program, rincian biaya, sumber dana yang diharapkan, dan waktu kebutuhan dana.","Menteri / Kabiro","Program unit, format","Usulan kebutuhan unit","5 hari kerja"],["3","Konsolidasi: Biro Keuangan menggabungkan usulan, memeriksa kewajaran harga, menghapus duplikasi, dan memetakan sumber dana terhadap pagu.","Kabiro Keuangan","Usulan unit","Draf RAT","3 hari kerja"],["4","Pemeriksaan keselarasan: Irjen memeriksa draf dengan Checklist Keselarasan Anggaran dan memberi catatan tertulis bila ada pertentangan dengan AD/ART atau aturan kampus.","Irjen","Draf RAT, checklist","Catatan pemeriksaan","2 hari kerja"],["5","Pembahasan: Draf dibahas pada Rapat Kerja atau Rapat Kabinet secara musyawarah (SOP-GOV-002); prioritas ditetapkan bila total usulan melebihi pagu.","Pimpinan dan Eksekutif","Draf RAT, catatan Irjen","Draf RAT final","1 kali rapat; revisi 2 hari kerja"],["6","Persetujuan internal: Presiden menyetujui draf final dan menandatangani Lembar Pengesahan RAT.","Presiden","Draf RAT final","RAT disetujui internal","2 hari kerja"],["7","Persetujuan pihak luar: RAT diajukan kepada BPM dan KAUR ORMAWA; bagian yang terkait program kerja mengikuti persetujuan Pembina melalui alur Rapat Kerja.","Sekjen bersama Kabiro Keuangan","RAT, surat pengantar","Persetujuan atau catatan perbaikan","Sesuai jadwal kampus"],["8","Sosialisasi dan arsip: RAT final dibagikan kepada seluruh unit melalui kanal resmi, disimpan di repositori, dan dicatat pada Register Dokumen.","Sekjen","RAT final","Distribusi tercatat, arsip","3 hari kerja setelah persetujuan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penyusunan RAT dari penerbitan kalender hingga persetujuan internal ditargetkan paling lambat 20 hari kerja sejak program kerja tahunan ditetapkan, dan selalu mendahului batas waktu pengumpulan anggaran kampus. Hasil akhir: RAT yang disetujui beserta Lembar Pengesahan."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Total usulan melebihi pagu: Rapat Kabinet menetapkan prioritas program; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Jadwal kampus berubah atau mepet: Biro Keuangan menyusun RAT sementara untuk program prioritas dan melengkapinya kemudian.","Perbedaan pendapat dengan BPM atau KAUR ORMAWA: dibahas melalui audiensi dan, bila perlu, Pembina.","Kebutuhan mengubah anggaran setelah RAT disahkan: SOP-KEU-014."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% program kerja memiliki pos anggaran dan sumber dana.","RAT selesai sebelum batas waktu pengumpulan anggaran kampus.","Tidak ada temuan pertentangan dengan AD/ART pada pemeriksaan Irjen.","RAT tersosialisasi paling lambat 3 hari kerja setelah persetujuan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["RAT Kabinet Samasta beserta Lembar Pengesahan.","Formulir Kebutuhan Anggaran Unit dari seluruh unit.","Catatan pemeriksaan Irjen.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Biro Keuangan memantau kesesuaian realisasi dengan RAT setiap bulan dan melaporkannya pada rapat kabinet; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kalender dan format → Usulan unit → Konsolidasi → Periksa Irjen → Pembahasan → Persetujuan Presiden → BPM dan KAUR ORMAWA → Sosialisasi dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Kebutuhan Anggaran Unit","Unit; program; rincian biaya; volume dan harga satuan; sumber dana; waktu kebutuhan; penanggung jawab; tanggal."],["Templat Rencana Anggaran Tahunan","Ringkasan pemasukan per sumber; pengeluaran per unit dan program; biaya tak terduga; jadwal arus kas; total."],["Lembar Pengesahan RAT","Nomor dan versi RAT; ringkasan total; tanda tangan Presiden; catatan persetujuan BPM, KAUR ORMAWA, dan Pembina."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap pos anggaran terhubung pada program kerja yang disahkan.","☐ Ya ☐ Tidak"],["2","Sumber dana halal dan sesuai AD Pasal 15.","☐ Ya ☐ Tidak"],["3","Harga mengacu pada daftar harga acuan atau penawaran tertulis.","☐ Ya ☐ Tidak"],["4","Pos biaya tak terduga tidak melebihi batas yang ditetapkan.","☐ Ya ☐ Tidak"],["5","Persetujuan Presiden, BPM, dan KAUR ORMAWA tercatat sebelum RAT dipakai.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-002","g":"Keuangan dan Pengadaan","t":"Pengajuan Anggaran Program Kerja","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[168,171],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengajuan anggaran untuk setiap program kerja dan kegiatan, sehingga kebutuhan biaya terinci dalam Rencana Anggaran Biaya (RAB), sesuai Rencana Anggaran Tahunan, dan siap diverifikasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk setiap kementerian, biro, dan panitia kegiatan yang membutuhkan dana BEM. SOP ini tidak mengatur penilaian dan persetujuan anggaran (lihat SOP-KEU-003) dan tidak mengatur pencairan dana (lihat SOP-KEU-004)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) sampai (4).","ART Bab III (Tugas) huruf e dan ART Pasal 4 (Wewenang BEM) huruf d (pengajuan dana kemahasiswaan kepada perguruan tinggi).","ART Pasal 9 ayat (3) huruf d dan ayat (6).","SOP-KEU-001 (RAT), SOP-PRO-007 (TOR), dan SOP-PRO-008 (proposal dan RAB)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["RAB","Rencana Anggaran Biaya: rincian biaya suatu program atau kegiatan per pos, volume, dan harga satuan."],["Ketua pelaksana","Pengurus yang ditunjuk memimpin pelaksanaan kegiatan dan mengajukan anggarannya."],["Pos anggaran","Kelompok biaya dalam RAB, misalnya konsumsi, perlengkapan, publikasi, dan transportasi."],["Arus kas kegiatan","Jadwal kebutuhan dana kegiatan dari persiapan hingga pelaporan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Anggaran hanya dapat diajukan untuk program yang sudah masuk program kerja tahunan dan RAT, atau program baru yang telah disetujui melalui SOP-PRO-003.","Setiap RAB wajib memuat sumber dana, rincian pos dengan volume dan harga satuan, serta biaya tak terduga yang wajar.","Harga satuan mengacu pada daftar harga acuan Biro Keuangan; harga di luar acuan dilengkapi penawaran tertulis atau penjelasan.","Pengaju tidak boleh menyetujui anggarannya sendiri; fungsi pengaju, pemberi persetujuan, pemegang dana, dan pemeriksa dipisahkan.","Seluruh pos harus sesuai syariat; biaya yang bersifat haram, mubazir, atau tidak berkaitan dengan tujuan kegiatan tidak dicantumkan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Bertanggung jawab atas kelengkapan dan kewajaran pengajuan yang diteruskan untuk diverifikasi."],["Ketua pelaksana / Menteri / Kabiro","R","Menyusun RAB dan mengajukan anggaran program beserta lampirannya."],["Bendahara","R","Memeriksa administrasi pengajuan, mencatat nomor pengajuan, dan memantau sisa pagu."],["Wakil Presiden","C","Memastikan program yang diajukan selaras dengan prioritas kabinet."],["Sekretaris Jenderal","I","Menerima salinan pengajuan sebagai bagian arsip kegiatan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Program kerja dan RAT yang berlaku.","Proposal atau TOR kegiatan.","Daftar harga acuan dan penawaran bila diperlukan.","Formulir Pengajuan Anggaran Program."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan RAB: Ketua pelaksana menyusun RAB per pos beserta sumber dana dan jadwal kebutuhan dana, berdasarkan TOR atau proposal.","Ketua pelaksana","TOR, harga acuan","Draf RAB","Sebelum proposal diajukan"],["2","Pengisian formulir: Pengaju mengisi Formulir Pengajuan Anggaran Program dan melampirkan RAB, TOR atau proposal, dan penawaran bila ada.","Ketua pelaksana","RAB, lampiran","Berkas pengajuan","Paling lambat 14 hari kerja sebelum kebutuhan dana"],["3","Penerimaan dan pencatatan: Bendahara memeriksa kelengkapan, memberi nomor pengajuan, dan mencatat pada Register Pengajuan Anggaran.","Bendahara","Berkas pengajuan","Pengajuan tercatat atau dikembalikan","1 hari kerja"],["4","Pemeriksaan pagu: Kabiro Keuangan memeriksa kesesuaian dengan RAT dan sisa pagu unit; pengajuan di luar pagu dikembalikan atau diproses sebagai perubahan anggaran (SOP-KEU-014).","Kabiro Keuangan","Pengajuan, RAT","Sesuai pagu atau perlu revisi","2 hari kerja"],["5","Revisi: Pengaju memperbaiki RAB sesuai catatan Biro Keuangan, lalu mengirim ulang.","Ketua pelaksana","Catatan revisi","RAB revisi","3 hari kerja"],["6","Penerusan: Berkas lengkap diteruskan ke tahap verifikasi dan persetujuan sesuai SOP- KEU-003.","Kabiro Keuangan","Berkas lengkap","Berkas siap diverifikasi","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pemeriksaan awal kelengkapan paling lambat 1 hari kerja setelah pengajuan diterima. Hasil akhir: berkas pengajuan anggaran yang lengkap, bernomor, dan siap diverifikasi."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Berkas tidak lengkap setelah dua kali revisi: dilaporkan kepada Wakil Presiden untuk pembinaan unit.","Program mendesak tanpa pagu: SOP-KEU-014 dan, bila memenuhi kriteria, SOP-GOV-012.","Perbedaan nilai harga acuan dengan harga pasar: Kabiro Keuangan memutuskan setelah membandingkan penawaran tertulis.","Dugaan penggelembungan biaya: SOP-RSK-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% pengajuan lengkap pada pengajuan pertama.","100% pengajuan memiliki nomor dan tercatat pada register.","Seluruh pengajuan diajukan sesuai tenggat 14 hari kerja sebelum kebutuhan dana.","Tidak ada pengeluaran yang dilakukan sebelum anggaran program disetujui."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Pengajuan Anggaran Program beserta RAB.","Nomor pengajuan pada Register Pengajuan Anggaran.","Catatan revisi, bila ada. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Bendahara memperbarui Register Pengajuan Anggaran setiap minggu; Kabiro Keuangan melaporkan jumlah pengajuan dan sisa pagu pada rapat kabinet."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Susun RAB → Isi formulir → Catat dan periksa kelengkapan → Periksa pagu → Revisi bila perlu → Teruskan ke verifikasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pengajuan Anggaran Program","Nomor; unit; nama program; ketua pelaksana; total anggaran; sumber dana; jadwal kebutuhan dana; lampiran; tanggal."],["Templat RAB","Pos; uraian; volume; satuan; harga satuan; jumlah; sumber dana; keterangan."],["Register Pengajuan Anggaran","Nomor; tanggal; unit; program; nilai; status; tanggal penyelesaian."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Program tercantum pada program kerja dan RAT.","☐ Ya ☐ Tidak"],["2","RAB memuat volume, harga satuan, dan sumber dana.","☐ Ya ☐ Tidak"],["3","Harga sesuai daftar harga acuan atau didukung penawaran.","☐ Ya ☐ Tidak"],["4","Tidak ada pos yang bertentangan dengan syariat atau tujuan kegiatan.","☐ Ya ☐ Tidak"],["5","Pengajuan telah dicatat pada register dan diteruskan tepat waktu.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-003","g":"Keuangan dan Pengadaan","t":"Verifikasi dan Persetujuan Anggaran","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[172,175],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pemeriksaan, penilaian, dan persetujuan anggaran yang diajukan, sehingga setiap pengeluaran yang direncanakan wajar, sesuai pagu, sesuai AD/ART, dan disetujui oleh pihak yang berwenang sebelum dana dipakai."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengajuan anggaran program kerja, perubahan anggaran, dan anggaran kegiatan insidental. SOP ini tidak mengatur penyusunan RAB (lihat SOP-KEU-002) dan tidak mengatur pencairan (lihat SOP-KEU-004)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (4) (persetujuan KAUR ORMAWA atas anggaran dana ORMAWA).","ART Bab III (Tugas) huruf e (persetujuan BPM atas anggaran).","ART Pasal 9 ayat (6) (persetujuan Pembina atas program kerja).","ART Pasal 4 (Wewenang BEM) huruf a dan d.","SOP-GOV-002 (Pengambilan Keputusan) dan SOP-GOV-008 (Pendelegasian Wewenang)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Verifikasi","Pemeriksaan kelengkapan, kewajaran, kesesuaian pagu, dan kepatuhan aturan atas pengajuan anggaran."],["Tingkat persetujuan","Pembagian pejabat penyetuju berdasarkan nilai: Tingkat 1 sampai Rp500.000; Tingkat 2 di atas Rp500.000 sampai Rp5.000.000; Tingkat 3 di atas Rp5.000.000 (usulan)."],["Lembar Persetujuan Anggaran","Formulir resmi yang mencatat hasil verifikasi dan keputusan persetujuan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Persetujuan internal diberikan Presiden. Persetujuan Tingkat 1 dapat dimandatkan kepada Kepala Biro Keuangan melalui SOP-GOV-008 secara tertulis.","Urutan persetujuan (usulan): verifikasi Biro Keuangan, pemeriksaan Irjen untuk Tingkat 3, persetujuan Presiden, lalu persetujuan pihak luar yang dibutuhkan (BPM, KAUR ORMAWA, Pembina).","Anggaran yang membutuhkan persetujuan pihak luar belum berlaku sebelum persetujuan itu diperoleh.","Pengaju, penyetuju, dan pemegang dana tidak boleh orang yang sama untuk satu pengajuan.","Keputusan berupa disetujui penuh, disetujui dengan catatan atau pengurangan, atau ditolak; penolakan wajib disertai alasan tertulis."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Memutuskan persetujuan anggaran dan bertanggung jawab akhir atas keputusan."],["Kepala Biro Keuangan","R","Memverifikasi pengajuan, menyusun rekomendasi, dan menerbitkan Lembar Persetujuan Anggaran."],["Inspektur Jenderal","C","Memeriksa kepatuhan terhadap AD/ART dan aturan kampus, terutama pada anggaran Tingkat 3."],["Wakil Presiden","C","Memberi pertimbangan prioritas bila terdapat benturan antarprogram."],["Sekretaris Jenderal","R","Mengatur surat pengajuan kepada pihak luar dan mengarsipkan keputusan."],["BPM, KAUR ORMAWA, Pembina","I","Memberikan persetujuan eksternal sesuai kewenangan."],["Pengaju","I","Menerima keputusan dan menindaklanjuti catatan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Berkas pengajuan anggaran yang lengkap (SOP-KEU-002).","RAT dan sisa pagu.","Checklist Verifikasi Anggaran.","Ketentuan anggaran kampus yang berlaku."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Verifikasi administrasi: Biro Keuangan memeriksa kelengkapan dokumen, tanda tangan, dan kesesuaian dengan program kerja menggunakan Checklist Verifikasi Anggaran.","Kabiro Keuangan","Berkas pengajuan","Berkas lengkap atau dikembalikan","2 hari kerja"],["2","Verifikasi substansi: Biro Keuangan menilai kewajaran harga, kesesuaian pagu dan sumber dana, serta kepatuhan syariah; menyusun rekomendasi.","Kabiro Keuangan","RAB, daftar harga acuan","Rekomendasi tertulis","2 hari kerja"],["3","Pemeriksaan Irjen: Untuk Tingkat 3, Irjen memeriksa keselarasan dengan AD/ART dan memberi catatan.","Irjen","Berkas, rekomendasi","Catatan pemeriksaan","2 hari kerja"],["4","Keputusan internal: Presiden memutuskan setuju, setuju dengan catatan, atau menolak dengan alasan, lalu menandatangani Lembar Persetujuan Anggaran.","Presiden","Rekomendasi, catatan Irjen","Lembar Persetujuan Anggaran","2 hari kerja"],["5","Persetujuan pihak luar: Bila dibutuhkan, Sekjen mengajukan surat persetujuan kepada BPM, KAUR ORMAWA, atau Pembina melalui SOP-ADM-004.","Sekjen","Lembar Persetujuan, surat","Persetujuan eksternal","Sesuai ketentuan kampus"],["6","Pemberitahuan: Biro Keuangan memberitahukan keputusan kepada pengaju beserta catatan dan pagu yang disetujui.","Kabiro Keuangan","Keputusan","Pengaju diberi tahu","1 hari kerja"],["7","Pencatatan dan arsip: Bendahara memperbarui pagu pada register dan mengarsipkan seluruh dokumen persetujuan.","Bendahara","Dokumen persetujuan","Pagu diperbarui, arsip lengkap","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Verifikasi hingga keputusan internal ditargetkan paling lambat 7 hari kerja sejak berkas lengkap diterima; persetujuan pihak luar mengikuti waktu kampus. Hasil akhir: Lembar Persetujuan Anggaran dan pagu yang diperbarui."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Anggaran ditolak dan pengaju berkeberatan: diajukan ulang dengan perbaikan; bila masih berbeda dibahas pada Rapat Pimpinan (SOP-GOV-005).","Pihak luar menolak atau memberi catatan: unit merevisi RAB dan mengikuti SOP-KEU-002 kembali.","Indikasi pelanggaran aturan atau konflik kepentingan: SOP-RSK-006 atau SOP-RSK-007.","Kebutuhan sangat mendesak: SOP-GOV-012 dengan ratifikasi pada rapat terdekat."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% pengajuan lengkap diputuskan dalam 7 hari kerja.","100% keputusan memiliki alasan tertulis.","Tidak ada pengeluaran yang dilakukan sebelum persetujuan.","Tidak ada temuan Irjen berupa persetujuan yang melampaui kewenangan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Persetujuan Anggaran.","Rekomendasi verifikasi Biro Keuangan dan catatan Irjen.","Surat persetujuan atau tanggapan pihak luar.","Register Pengajuan Anggaran yang diperbarui. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa sampel Lembar Persetujuan Anggaran setiap triwulan; Biro Keuangan melaporkan keputusan yang ditolak dan alasannya pada rapat kabinet."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Verifikasi administrasi → Verifikasi substansi → Periksa Irjen (Tingkat 3) → Keputusan Presiden → Persetujuan pihak luar → Pemberitahuan → Pencatatan dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Persetujuan Anggaran","Nomor pengajuan; unit; program; nilai diajukan; nilai disetujui; tingkat persetujuan; catatan; pejabat penyetuju; tanggal."],["Checklist Verifikasi Anggaran","Butir pemeriksaan administrasi, pagu, kewajaran harga, sumber dana, dan syariah."],["Templat Surat Permohonan Persetujuan Anggaran","Dasar; ringkasan anggaran; permohonan; lampiran; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pengajuan lengkap dan tercatat pada register.","☐ Ya ☐ Tidak"],["2","Nilai tidak melebihi pagu dan sesuai sumber dana.","☐ Ya ☐ Tidak"],["3","Tingkat persetujuan ditentukan dengan benar.","☐ Ya ☐ Tidak"],["4","Persetujuan pihak luar yang diperlukan sudah diperoleh.","☐ Ya ☐ Tidak"],["5","Pengaju tidak terlibat dalam persetujuan anggarannya sendiri.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-004","g":"Keuangan dan Pengadaan","t":"Pengajuan Pencairan Dana","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[176,179],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur permintaan pencairan dana, baik dari kampus maupun dari kas BEM kepada unit atau panitia, sehingga dana hanya dikeluarkan untuk anggaran yang telah disetujui, pada waktu yang dibutuhkan, dan kepada pihak yang berwenang."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pencairan dana kemahasiswaan dari kampus kepada BEM dan pencairan dari kas BEM kepada unit, panitia, atau ketua pelaksana. SOP ini tidak mengatur pembayaran kepada penyedia (lihat SOP-KEU- 006) dan tidak mengatur uang muka (lihat SOP-KEU-007)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf a dan ayat (4).","ART Pasal 4 (Wewenang BEM) huruf d (pengajuan dana kemahasiswaan kepada perguruan tinggi) dan huruf f (penandatanganan surat resmi).","ART Pasal 3 (Kewajiban) huruf e (pengelolaan keuangan yang amanah, transparan, dan akuntabel).","SOP-KEU-003 (Verifikasi dan Persetujuan Anggaran) dan SOP-ADM-004."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pencairan","Pengeluaran dana dari sumber dana kepada BEM atau dari kas BEM kepada penerima yang berwenang untuk kegiatan yang sudah dianggarkan."],["Penerima dana","Pengurus yang ditunjuk secara tertulis untuk menerima dan bertanggung jawab atas dana."],["Permintaan Pencairan Dana","Formulir resmi permintaan pencairan yang mengacu pada anggaran yang disetujui."],["Termin","Pembagian pencairan dana menjadi beberapa tahap sesuai kebutuhan kegiatan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Dana hanya dapat dicairkan bila anggaran telah disetujui sesuai SOP-KEU-003 dan nilai yang diminta tidak melebihi sisa pagu.","Pencairan dana kampus mengikuti mekanisme, formulir, dan jadwal yang ditetapkan kampus melalui KAUR ORMAWA; bila ketentuan kampus lebih ketat, ketentuan kampus berlaku.","Pencairan dari kas BEM dilakukan secara bertahap sesuai kebutuhan nyata (termin) dan tidak melebihi kebutuhan dua pekan ke depan, kecuali ditetapkan lain oleh Presiden (usulan).","Penerima dana harus ditunjuk tertulis, bukan pihak yang menyetujui pencairan, dan tidak boleh memiliki pencairan sebelumnya yang belum dipertanggungjawabkan.","Dana dicairkan ke rekening organisasi atau rekening penerima resmi sesuai SOP-KEU-009; pencairan tunai dibatasi untuk kebutuhan kecil."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Memverifikasi permintaan, memastikan syarat terpenuhi, dan bertanggung jawab atas ketepatan pencairan."],["Pemohon / Ketua pelaksana","R","Mengajukan Permintaan Pencairan Dana lengkap dengan dasar anggaran dan jadwal."],["Bendahara","R","Menyiapkan pencairan, melakukan pembayaran atau pemindahan dana, dan mencatatnya."],["Presiden","R","Menyetujui pencairan Tingkat 2 dan 3 sesuai SOP-KEU-003; Tingkat 1 dapat dimandatkan kepada Kabiro Keuangan."],["Sekretaris Jenderal","R","Membuat surat permohonan pencairan kepada kampus dan mengarsipkan."],["KAUR ORMAWA","I","Menerima permohonan pencairan dana kampus dan memprosesnya sesuai aturan kampus."],["Inspektur Jenderal","I","Menerima salinan laporan pencairan untuk pemantauan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Lembar Persetujuan Anggaran.","Jadwal kebutuhan dana kegiatan.","Surat penunjukan penerima dana.","Data rekening penerima atau rekening organisasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan: Pemohon mengisi Permintaan Pencairan Dana: nilai, termin, tujuan, tanggal butuh, dan penerima; melampirkan Lembar Persetujuan Anggaran.","Pemohon","Lembar Persetujuan Anggaran","Permintaan tercatat","Paling lambat 5 hari kerja sebelum dana dibutuhkan"],["2","Verifikasi: Biro Keuangan memeriksa kesesuaian dengan anggaran yang disetujui, sisa pagu, ketersediaan kas, dan status pencairan sebelumnya.","Kabiro Keuangan","Permintaan, register pagu, saldo kas","Lolos atau dikembalikan","1 hari kerja"],["3","Persetujuan pencairan: Pencairan disetujui sesuai tingkat nilai: Tingkat 1 oleh Kabiro Keuangan (mandat), Tingkat 2 dan 3 oleh Presiden.","Presiden / Kabiro Keuangan","Hasil verifikasi","Persetujuan pencairan","2 hari kerja"],["4","Permohonan ke kampus: Untuk dana kampus, Sekjen menyiapkan surat permohonan dan berkas sesuai ketentuan kampus dan menyampaikannya kepada KAUR ORMAWA.","Sekjen dan Kabiro Keuangan","Berkas pencairan","Permohonan diterima kampus","Sesuai jadwal kampus"],["5","Pencairan dari kas BEM: Bendahara memindahkan dana ke penerima sesuai SOP-KEU-006 dan SOP-KEU-009, lalu meminta tanda terima.","Bendahara","Persetujuan pencairan","Dana diterima, tanda terima","1 hari kerja setelah persetujuan"],["6","Pencatatan: Bendahara mencatat pencairan pada buku kas dan register pencairan; sisa pagu diperbarui.","Bendahara","Bukti pencairan","Catatan diperbarui","1 hari kerja"],["7","Pemantauan: Kabiro Keuangan memantau batas waktu pertanggungjawaban penerima dan menyampaikan pengingat.","Kabiro Keuangan","Register pencairan","Pengingat terkirim","Setiap minggu"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Verifikasi paling lambat 1 hari kerja setelah permintaan lengkap; pencairan dari kas BEM paling lambat 2 hari kerja setelah persetujuan. Pencairan dana kampus mengikuti waktu kampus. Hasil akhir: dana diterima penerima dengan tanda terima dan pencatatan."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kas tidak mencukupi: pencairan ditunda atau dibagi termin; prioritas diputuskan Presiden.","Kampus menolak atau menunda pencairan: dibahas dengan KAUR ORMAWA; kegiatan dijadwal ulang sesuai SOP-PRO-015.","Penerima masih memiliki kewajiban pertanggungjawaban: pencairan baru ditahan sampai selesai.","Dugaan penyalahgunaan dana: SOP-RSK-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% pencairan sesuai waktu yang diminta.","100% pencairan didukung persetujuan anggaran dan tanda terima.","Tidak ada pencairan yang melebihi sisa pagu.","Tidak ada pencairan baru kepada penerima yang masih memiliki tunggakan pertanggungjawaban."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Permintaan Pencairan Dana yang disetujui.","Bukti pencairan dan tanda terima.","Surat permohonan kepada kampus, bila ada.","Register pencairan yang diperbarui. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Keuangan menyandingkan register pencairan dan buku kas setiap minggu; Irjen memeriksa sampel pencairan setiap triwulan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Ajukan permintaan → Verifikasi Biro Keuangan → Persetujuan pencairan → Pencairan (kampus atau kas BEM) → Tanda terima → Pencatatan → Pemantauan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Pencairan Dana","Nomor; pemohon; kegiatan; nomor persetujuan anggaran; nilai; termin; tanggal butuh; penerima dan rekening; tanda tangan."],["Tanda Terima Dana","Penerima; nilai; tujuan; tanggal; saksi; tanda tangan."],["Register Pencairan","Nomor; tanggal; penerima; nilai; termin; batas pertanggungjawaban; status."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Anggaran telah disetujui dan nilai tidak melebihi sisa pagu.","☐ Ya ☐ Tidak"],["2","Penerima ditunjuk tertulis dan tidak memiliki tunggakan.","☐ Ya ☐ Tidak"],["3","Tingkat persetujuan pencairan sesuai nilai.","☐ Ya ☐ Tidak"],["4","Tanda terima dan bukti pemindahan dana tersedia.","☐ Ya ☐ Tidak"],["5","Pencairan tercatat pada buku kas dan register.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-005","g":"Keuangan dan Pengadaan","t":"Penerimaan dan Pencatatan Pemasukan","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[180,183],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penerimaan, verifikasi, bukti, dan pencatatan seluruh pemasukan BEM, sehingga setiap dana yang masuk sah, halal, tercatat lengkap, dan dapat dipertanggungjawabkan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pemasukan BEM dari dana kemahasiswaan, hibah, donasi, sponsor, usaha halal, hasil pengembangan aset, dan kontribusi peserta kegiatan. SOP ini tidak mengatur penilaian kerja sama sponsor (lihat SOP-KEU-012) dan tidak mengatur pencatatan khusus donasi dan kontribusi kegiatan (lihat SOP-KEU- 013)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) (sumber keuangan), ayat (2) (bebas riba, gharar, dan maysir), dan ayat (3) (dokumentasi dengan bukti penerimaan resmi).","ART Pasal 2 huruf f (pengelolaan sumber pendanaan secara mandiri, terbuka, dan syariah).","ART Pasal 3 (Kewajiban) huruf e dan g.","SOP-KEU-009 (Pengelolaan Kas dan Rekening) dan SOP-ADM-003 (Penomoran Surat)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pemasukan","Setiap dana yang diterima BEM dalam bentuk uang, baik tunai maupun transfer."],["Bukti penerimaan resmi","Kuitansi penerimaan bernomor, bukti transfer, atau dokumen sah lain yang mencatat penerima, pemberi, nilai, tanggal, dan tujuan."],["Dana terikat","Dana yang diberikan untuk tujuan tertentu dan tidak boleh dipakai di luar tujuan itu."],["Buku kas","Catatan kronologis semua pemasukan dan pengeluaran beserta saldo."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap pemasukan wajib diberi bukti penerimaan resmi dan dicatat dalam buku kas paling lambat 1 hari kerja (AD Pasal 15 ayat 3).","Pemasukan yang sumbernya tidak jelas, mengandung riba, gharar, atau maysir, atau menimbulkan kewajiban yang melampaui satu periode, ditolak atau dikembalikan.","Dana tunai disetor ke rekening organisasi paling lambat 2 hari kerja (usulan); dana tidak boleh dikuasai pribadi atau dicampur dengan uang pribadi.","Dana terikat dicatat terpisah menurut tujuannya dan hanya dipakai sesuai tujuan.","Penerima dana dan pencatat dana sedapat mungkin bukan orang yang sama; Kabiro Keuangan memeriksa kesesuaian catatan dan mutasi rekening."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Bertanggung jawab atas keabsahan penerimaan dan kelengkapan pencatatan."],["Bendahara","R","Menerima dana, menerbitkan bukti penerimaan, menyetor ke rekening, dan mencatat pada buku kas."],["Penyetor / pemberi dana","R","Menyerahkan dana dengan identitas dan tujuan yang jelas."],["Menteri / Kabiro / Ketua pelaksana","C","Menyampaikan pemasukan yang diterima unit atau kegiatan kepada Bendahara."],["Inspektur Jenderal","C","Memeriksa kesesuaian bukti penerimaan, mutasi rekening, dan buku kas."],["Presiden","I","Menerima laporan pemasukan secara berkala."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Dana atau bukti transfer.","Identitas dan tujuan pemberi dana.","Dokumen dasar (surat dana kampus, perjanjian sponsor, daftar peserta, atau bukti usaha).","Buku kas dan mutasi rekening."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan: Bendahara menerima dana tunai atau memeriksa bukti transfer, memastikan identitas pemberi, nilai, dan tujuan dana.","Bendahara","Dana, bukti, dokumen dasar","Dana diterima","Saat dana diterima"],["2","Verifikasi sumber: Bendahara bersama Kabiro Keuangan memeriksa kehalalan sumber, ikatan atau syarat, dan kesesuaian dengan AD Pasal 15; dana yang meragukan ditahan dan dilaporkan.","Kabiro Keuangan","Dokumen dasar","Sumber dinyatakan sah atau ditolak","1 hari kerja"],["3","Penerbitan bukti: Bendahara menerbitkan kuitansi penerimaan bernomor atau mencocokkan bukti transfer, lalu menyerahkannya kepada pemberi.","Bendahara","Dana yang sah","Bukti penerimaan resmi","Segera"],["4","Penyetoran: Dana tunai disetor ke rekening organisasi dan bukti setoran disimpan.","Bendahara","Dana tunai","Bukti setoran","2 hari kerja"],["5","Pencatatan: Bendahara mencatat pemasukan pada buku kas dengan klasifikasi sumber dan status terikat atau tidak terikat.","Bendahara","Bukti penerimaan","Buku kas diperbarui","1 hari kerja"],["6","Pemeriksaan: Kabiro Keuangan mencocokkan catatan pemasukan dengan bukti dan mutasi rekening setiap minggu.","Kabiro Keuangan","Buku kas, mutasi","Kecocokan terkonfirmasi","Setiap minggu"],["7","Pelaporan: Ringkasan pemasukan disampaikan kepada Presiden dan pada rapat kabinet.","Kabiro Keuangan","Buku kas","Laporan pemasukan","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Bukti penerimaan diterbitkan segera saat dana diterima; pencatatan paling lambat 1 hari kerja; penyetoran dana tunai paling lambat 2 hari kerja. Hasil akhir: pemasukan tercatat pada buku kas dengan bukti penerimaan resmi."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Sumber dana meragukan: ditahan dan dikonsultasikan kepada Presiden serta, bila perlu, KAUR ORMAWA atau Pembina.","Selisih antara dana diterima dan nilai tercatat: SOP-KEU-018 dan, bila ada indikasi pelanggaran, SOP- RSK-007.","Pemberi dana menuntut imbalan yang mengikat: dialihkan ke SOP-KEU-012 dan SOP-HKE-008.","Bukti hilang: dibuat berita acara dan dikonfirmasi kepada pemberi dana."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pemasukan memiliki bukti penerimaan resmi.","100% pemasukan tercatat dalam 1 hari kerja.","Tidak ada dana tunai yang tertahan lebih dari 2 hari kerja tanpa alasan tertulis.","Tidak ada selisih tak terjelaskan antara buku kas dan mutasi rekening."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Kuitansi atau bukti penerimaan resmi.","Bukti setoran.","Buku kas yang diperbarui.","Laporan pemasukan bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa kecocokan bukti penerimaan, buku kas, dan mutasi rekening setiap triwulan; penyimpangan dicatat untuk tindak lanjut."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima dana → Verifikasi sumber → Terbitkan bukti → Setor ke rekening → Catat di buku kas → Periksa Kabiro Keuangan → Laporan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Kuitansi Penerimaan","Nomor; tanggal; pemberi; nilai; terbilang; tujuan; penerima; tanda tangan."],["Buku Kas","Tanggal; uraian; sumber; pemasukan; pengeluaran; saldo; nomor bukti."],["Formulir Verifikasi Sumber Dana","Pemberi; sumber; syarat; kesesuaian AD Pasal 15; keputusan; pemeriksa."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Sumber dana halal dan tidak mengikat melampaui satu periode.","☐ Ya ☐ Tidak"],["2","Bukti penerimaan resmi diterbitkan.","☐ Ya ☐ Tidak"],["3","Dana tunai disetor tepat waktu ke rekening organisasi.","☐ Ya ☐ Tidak"],["4","Dana terikat tercatat terpisah.","☐ Ya ☐ Tidak"],["5","Catatan buku kas cocok dengan mutasi rekening.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-006","g":"Keuangan dan Pengadaan","t":"Pembayaran dan Pengeluaran Dana","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[184,187],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur permintaan, pemeriksaan, persetujuan, pelaksanaan, dan pencatatan pembayaran serta pengeluaran dana BEM, sehingga setiap pengeluaran sesuai anggaran, didukung bukti sah, dan disetujui oleh pihak yang berwenang."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk semua pembayaran kepada penyedia barang dan jasa, honor atau konsumsi yang dianggarkan, biaya operasional, dan pengeluaran lain dari kas atau rekening BEM. SOP ini tidak mengatur uang muka (lihat SOP-KEU-007) dan penggantian biaya (lihat SOP-KEU-008)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (2) (bebas riba, gharar, dan maysir).","ART Pasal 3 (Kewajiban) huruf e (pengelolaan keuangan yang amanah, transparan, dan akuntabel).","ART Pasal 4 (Wewenang BEM) huruf f (penandatanganan dokumen organisasi).","ART Pasal 11 huruf i dan k (larangan korupsi, manipulasi, penyelewengan dana, dan pemakaian nama atau fasilitas organisasi untuk kepentingan pribadi).","SOP-KEU-003 (Verifikasi dan Persetujuan Anggaran) dan SOP-KEU-016 (Pemeriksaan Bukti Transaksi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Permintaan Pembayaran","Formulir resmi untuk meminta pembayaran atas suatu tagihan atau kebutuhan yang telah dianggarkan."],["Bukti transaksi","Nota, faktur, kuitansi, bukti transfer, atau dokumen sah yang membuktikan terjadinya pengeluaran."],["Pembayaran non-tunai","Pembayaran melalui transfer rekening atau cara lain yang meninggalkan jejak."],["Kas kecil","Dana tunai terbatas untuk kebutuhan kecil sesuai SOP-KEU-009."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pembayaran hanya dapat dilakukan untuk pos yang tercantum pada anggaran yang telah disetujui dan masih memiliki sisa pagu.","Tingkat persetujuan (usulan): Tingkat 1 sampai Rp500.000 oleh Kepala Biro Keuangan (mandat); Tingkat 2 di atas Rp500.000 sampai Rp5.000.000 oleh Presiden; Tingkat 3 di atas Rp5.000.000 oleh Presiden setelah diperiksa Irjen.","Pembayaran di atas Rp500.000 (usulan) dilakukan non-tunai kepada rekening penyedia; pembayaran tunai hanya dari kas kecil untuk kebutuhan kecil.","Pembayaran tidak boleh dilakukan kepada rekening pribadi pengurus kecuali sebagai penggantian biaya yang sah (SOP-KEU-008).","Pengaju, penyetuju, pelaksana pembayaran, dan pemeriksa bukti tidak boleh orang yang sama; transaksi bank memakai kontrol ganda sesuai SOP-KEU-009.","Akad dan pembayaran harus sesuai syariat: tanpa bunga, denda keterlambatan yang bersifat riba, pemberian suap, atau praktik yang mengandung gharar dan maysir."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menyetujui pembayaran sesuai tingkat dan bertanggung jawab akhir atas pengeluaran dana."],["Kepala Biro Keuangan","R","Memverifikasi permintaan dan bukti, serta menyetujui Tingkat 1 berdasarkan mandat."],["Bendahara","R","Melaksanakan pembayaran, meminta tanda terima, dan mencatat pada buku kas."],["Pemohon / Ketua pelaksana","R","Mengajukan Permintaan Pembayaran lengkap dengan bukti tagihan dan dasar anggaran."],["Inspektur Jenderal","C","Memeriksa pengeluaran Tingkat 3 dan sampel pengeluaran lain."],["Penerima pembayaran","I","Menerima pembayaran dan menandatangani tanda terima."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Lembar Persetujuan Anggaran.","Tagihan, faktur, atau nota dari penyedia.","Bukti penerimaan barang atau jasa (bila ada).","Data rekening penerima pembayaran."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan: Pemohon mengisi Permintaan Pembayaran dengan melampirkan tagihan atau nota, nomor persetujuan anggaran, dan bukti barang atau jasa telah diterima.","Pemohon","Tagihan, persetujuan anggaran","Permintaan tercatat","Sesuai jatuh tempo tagihan"],["2","Verifikasi: Biro Keuangan memeriksa kesesuaian tagihan dengan anggaran, kewajaran harga, kelengkapan bukti, dan sisa pagu (SOP-KEU-016).","Kabiro Keuangan","Permintaan, bukti","Lolos atau dikembalikan","2 hari kerja"],["3","Persetujuan: Pembayaran disetujui sesuai tingkat nilai dengan tanda tangan pada Permintaan Pembayaran.","Presiden / Kabiro Keuangan","Hasil verifikasi","Persetujuan pembayaran","2 hari kerja"],["4","Pembayaran: Bendahara membayar melalui transfer rekening atau kas kecil sesuai batas; transaksi bank memakai persetujuan ganda.","Bendahara","Persetujuan, data rekening","Pembayaran dilakukan","1 hari kerja setelah persetujuan"],["5","Bukti pembayaran: Bendahara menyimpan bukti transfer atau meminta kuitansi atau tanda terima bertanda tangan penerima.","Bendahara","Pembayaran","Bukti pembayaran lengkap","Segera"],["6","Pencatatan: Bendahara mencatat pengeluaran pada buku kas dengan nomor bukti dan pos anggaran, lalu memperbarui sisa pagu.","Bendahara","Bukti pembayaran","Buku kas dan pagu diperbarui","1 hari kerja"],["7","Pemeriksaan akhir: Kabiro Keuangan mencocokkan permintaan, bukti, dan catatan; berkas dijilid per transaksi atau per kegiatan.","Kabiro Keuangan","Berkas transaksi","Berkas lengkap","Setiap minggu"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Verifikasi paling lambat 2 hari kerja dan pembayaran paling lambat 1 hari kerja setelah persetujuan, dengan memperhatikan jatuh tempo tagihan. Hasil akhir: pembayaran terlaksana, bukti lengkap, dan tercatat pada buku kas."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pembayaran mendesak yang tidak sempat melalui alur normal: SOP-GOV-012 dengan ratifikasi pada rapat terdekat.","Tagihan melebihi anggaran: SOP-KEU-014.","Bukti tidak lengkap atau mencurigakan: pembayaran ditahan dan dilaporkan; bila ada indikasi pelanggaran, SOP-RSK-007.","Sisa kas tidak mencukupi: Presiden menetapkan prioritas pembayaran."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pembayaran didukung bukti lengkap dan persetujuan sesuai tingkat.","Minimal 90% pembayaran dilakukan sebelum jatuh tempo.","Tidak ada pembayaran tanpa anggaran yang disetujui.","Tidak ada temuan Irjen berupa pembayaran ke rekening pribadi tanpa dasar."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Permintaan Pembayaran yang disetujui.","Bukti pembayaran dan tanda terima.","Buku kas yang diperbarui.","Berkas transaksi terjilid. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Keuangan menyandingkan buku kas dan mutasi rekening setiap minggu; Irjen memeriksa sampel pembayaran setiap triwulan dan semua pembayaran Tingkat 3."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Ajukan pembayaran → Verifikasi bukti → Persetujuan sesuai tingkat → Bayar (non- tunai) → Simpan bukti → Catat buku kas → Pemeriksaan akhir → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Pembayaran","Nomor; pemohon; kegiatan; nomor persetujuan anggaran; uraian; nilai; penerima dan rekening; lampiran bukti; tanda tangan."],["Kuitansi atau Tanda Terima Pembayaran","Penerima; nilai; terbilang; keperluan; tanggal; tanda tangan; saksi."],["Voucher Pengeluaran","Nomor; tanggal; pos anggaran; nilai; penyetuju; pembayar; pemeriksa."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pos tercantum pada anggaran yang disetujui dan masih ada pagu.","☐ Ya ☐ Tidak"],["2","Tagihan dan bukti penerimaan barang atau jasa lengkap.","☐ Ya ☐ Tidak"],["3","Persetujuan sesuai tingkat nilai.","☐ Ya ☐ Tidak"],["4","Pembayaran non-tunai kepada rekening penyedia yang benar.","☐ Ya ☐ Tidak"],["5","Pengeluaran tercatat pada buku kas dengan nomor bukti.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-007","g":"Keuangan dan Pengadaan","t":"Uang Muka dan Pertanggungjawabannya","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[188,191],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pemberian uang muka kepada pengurus atau panitia dan pertanggungjawabannya, sehingga dana yang dipegang sementara dipakai sesuai tujuan, dibuktikan dengan bukti sah, dan dikembalikan bila tersisa tepat waktu."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk uang muka yang diberikan dari kas atau rekening BEM kepada ketua pelaksana, koordinator seksi, atau pengurus untuk belanja kegiatan. SOP ini tidak mengatur penggantian biaya yang dikeluarkan sendiri (lihat SOP-KEU-008)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Kewajiban) huruf e dan g.","ART Pasal 11 huruf i, k, dan l (larangan penyelewengan dana, penyalahgunaan nama atau fasilitas, dan meninggalkan tanggung jawab).","ART Pasal 12 dan Pasal 13 (sanksi dan mekanisme pemberian sanksi).","SOP-KEU-004 (Pencairan), SOP-KEU-006 (Pembayaran), dan SOP-KEU-016 (Pemeriksaan Bukti)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Uang muka","Dana yang diberikan di muka kepada pengurus untuk belanja kegiatan dan wajib dipertanggungjawabkan."],["Pemegang uang muka","Pengurus yang ditunjuk secara tertulis untuk menerima dan menggunakan uang muka."],["Pertanggungjawaban","Penyerahan bukti belanja dan pengembalian sisa dana."],["Sisa uang muka","Selisih lebih antara uang muka yang diterima dan belanja yang sah."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Uang muka hanya untuk belanja yang tercantum pada anggaran yang disetujui dan tidak dapat dialihkan kepada orang lain.","Nilai uang muka paling banyak sesuai kebutuhan belanja tahap berjalan dan tidak melebihi 50% dari anggaran kegiatan, kecuali ditetapkan Presiden (usulan).","Pertanggungjawaban paling lambat 7 hari kerja setelah belanja atau kegiatan selesai; sisa dikembalikan paling lambat 3 hari kerja setelah penghitungan (usulan).","Pemegang uang muka yang belum menyelesaikan pertanggungjawaban tidak dapat menerima uang muka baru.","Uang muka tidak boleh dipakai untuk kepentingan pribadi atau dipinjamkan kepada pihak lain."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Menyetujui uang muka sesuai tingkat, memverifikasi pertanggungjawaban, dan memantau tunggakan."],["Pemegang uang muka","R","Menggunakan dana sesuai tujuan, menyimpan bukti, dan mempertanggungjawabkan tepat waktu."],["Bendahara","R","Menyerahkan uang muka, mencatat, menerima sisa dana, dan menutup uang muka."],["Presiden","C","Menyetujui uang muka di atas batas kewenangan Kabiro Keuangan."],["Inspektur Jenderal","C","Memeriksa bukti pertanggungjawaban pada sampel atau bila ada tunggakan."],["Ketua pelaksana","I","Mengetahui status uang muka seksi atau panitianya."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Lembar Persetujuan Anggaran.","Permintaan Uang Muka.","Surat penunjukan pemegang uang muka.","Nota dan bukti belanja."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Permintaan: Pemegang uang muka mengisi Permintaan Uang Muka: tujuan, rincian belanja, nilai, dan tanggal pertanggungjawaban.","Pemegang uang muka","Anggaran disetujui","Permintaan tercatat","Paling lambat 3 hari kerja sebelum belanja"],["2","Verifikasi dan persetujuan: Biro Keuangan memeriksa kesesuaian anggaran dan tunggakan; persetujuan mengikuti tingkat nilai SOP-KEU-006.","Kabiro Keuangan / Presiden","Permintaan","Persetujuan atau penolakan","2 hari kerja"],["3","Penyerahan: Bendahara menyerahkan uang muka non-tunai atau tunai dalam batas kas kecil dan meminta tanda terima.","Bendahara","Persetujuan","Tanda terima uang muka","1 hari kerja"],["4","Belanja: Pemegang uang muka berbelanja sesuai rincian, meminta nota lengkap, dan mencatat setiap pengeluaran.","Pemegang uang muka","Dana, daftar belanja","Nota dan catatan belanja","Sesuai jadwal kegiatan"],["5","Pertanggungjawaban: Pemegang menyerahkan Laporan Pertanggungjawaban Uang Muka, nota asli, dan sisa dana.","Pemegang uang muka","Nota, sisa dana","Berkas pertanggungjawab an","7 hari kerja"],["6","Pemeriksaan: Biro Keuangan memeriksa bukti sesuai SOP-KEU-016, menghitung sisa atau kekurangan, dan mencatat selisih.","Kabiro Keuangan","Berkas pertanggungjawab an","Hasil pemeriksaan","3 hari kerja"],["7","Penutupan: Bendahara menerima sisa dana atau memproses kekurangan (SOP-KEU- 008), mencatat penutupan, dan mengarsipkan.","Bendahara","Hasil pemeriksaan","Uang muka ditutup","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pertanggungjawaban paling lambat 7 hari kerja setelah belanja atau kegiatan selesai; penutupan paling lambat 6 hari kerja sesudahnya. Hasil akhir: uang muka tertutup dengan bukti lengkap dan sisa dana kembali."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Terlambat pertanggungjawaban: peringatan lisan, lalu tertulis; uang muka baru ditahan.","Tidak mempertanggungjawabkan setelah peringatan: dilaporkan kepada Presiden dan diproses sesuai ART Pasal 12 dan SOP-RSK-007.","Bukti tidak sah atau selisih tak terjelaskan: SOP-KEU-016 dan SOP-KEU-018.","Belanja melebihi uang muka: SOP-KEU-008 atau SOP-KEU-014."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% uang muka dipertanggungjawabkan tepat waktu.","100% uang muka ditutup dengan bukti lengkap.","Tidak ada uang muka baru kepada pemegang yang menunggak.","Tidak ada sisa dana yang tidak dikembalikan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Permintaan Uang Muka dan tanda terima.","Laporan Pertanggungjawaban Uang Muka dengan nota.","Catatan penutupan uang muka.","Register Uang Muka. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Keuangan memperbarui Register Uang Muka setiap minggu dan melaporkan tunggakan pada rapat kabinet; Irjen memeriksa kepatuhan secara berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Minta uang muka → Verifikasi dan persetujuan → Penyerahan → Belanja → Pertanggungjawaban → Pemeriksaan bukti → Kembalikan sisa → Tutup → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Uang Muka","Pemegang; kegiatan; tujuan; rincian belanja; nilai; tanggal pertanggungjawaban; persetujuan."],["Laporan Pertanggungjawaban Uang Muka","Uang muka diterima; rincian belanja dan nomor nota; total belanja; sisa atau kekurangan; tanda tangan."],["Register Uang Muka","Nomor; pemegang; nilai; tanggal; batas waktu; status; sisa."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Uang muka sesuai anggaran dan ditunjuk tertulis.","☐ Ya ☐ Tidak"],["2","Pemegang tidak memiliki tunggakan sebelumnya.","☐ Ya ☐ Tidak"],["3","Nota asli dan lengkap dilampirkan.","☐ Ya ☐ Tidak"],["4","Sisa dana disetor tepat waktu.","☐ Ya ☐ Tidak"],["5","Uang muka tercatat ditutup pada register.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-008","g":"Keuangan dan Pengadaan","t":"Penggantian Biaya yang Telah Dikeluarkan","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[192,195],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penggantian biaya (reimbursement) atas pengeluaran yang lebih dahulu ditalangi pengurus atau panitia untuk kepentingan organisasi, sehingga penggantian hanya untuk pengeluaran yang sah, wajar, dan telah atau patut disetujui."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pengeluaran yang ditalangi dengan dana pribadi pengurus atau panitia untuk kegiatan atau operasional BEM. SOP ini tidak mengatur uang muka (lihat SOP-KEU-007) dan pembayaran langsung kepada penyedia (lihat SOP-KEU-006)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Kewajiban) huruf e.","ART Pasal 11 huruf i dan k.","SOP-KEU-006 (Pembayaran dan Pengeluaran Dana) dan SOP-KEU-016 (Pemeriksaan Bukti Transaksi).","SOP-GOV-012 (Pengambilan Keputusan Mendesak dan Pencatatannya)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Penggantian biaya","Pengembalian dana kepada pengurus atas pengeluaran pribadi yang sah untuk kepentingan organisasi."],["Talangan","Pengeluaran dengan uang pribadi sebelum dana organisasi tersedia."],["Persetujuan di muka","Persetujuan tertulis sebelum talangan dilakukan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Talangan dilakukan dengan persetujuan di muka; talangan tanpa persetujuan hanya dapat diganti bila memenuhi kriteria mendesak sesuai SOP-GOV-012 dan disetujui Presiden.","Pengeluaran harus sesuai anggaran yang disetujui, bernilai wajar, dan didukung bukti sah; pengeluaran yang tidak dianggarkan diproses melalui SOP-KEU-014.","Pengajuan penggantian diajukan paling lambat 7 hari kerja setelah pengeluaran; pembayaran diupayakan paling lambat 5 hari kerja setelah verifikasi, sesuai ketersediaan kas (usulan).","Penggantian tidak diberikan untuk pengeluaran pribadi, denda pelanggaran, barang yang tidak sesuai syariat, atau pengeluaran tanpa bukti.","Pengurus tidak diwajibkan menalangi dana organisasi; talangan bersifat sukarela dan tidak boleh disertai bunga atau imbalan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Memverifikasi pengajuan, memutuskan penggantian dalam batas kewenangan, dan bertanggung jawab atas ketepatannya."],["Pemohon","R","Mengajukan penggantian dengan bukti asli dan penjelasan pengeluaran."],["Bendahara","R","Membayar penggantian dan mencatatnya."],["Presiden","C","Menyetujui penggantian Tingkat 2 dan 3 atau pengeluaran tanpa persetujuan di muka."],["Inspektur Jenderal","C","Memeriksa kewajaran dan bukti penggantian pada sampel."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Persetujuan di muka atau alasan mendesak.","Nota atau bukti asli.","Lembar Persetujuan Anggaran.","Data rekening pemohon."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Persetujuan talangan: Pemohon meminta persetujuan di muka kepada Biro Keuangan sebelum menalangi, kecuali keadaan mendesak.","Pemohon","Rencana pengeluaran","Persetujuan di muka","Sebelum pengeluaran"],["2","Pengeluaran: Pemohon mengeluarkan dana sesuai persetujuan dan menyimpan nota asli.","Pemohon","Persetujuan","Nota asli","Sesuai kebutuhan"],["3","Pengajuan penggantian: Pemohon mengisi Formulir Penggantian Biaya, melampirkan nota asli dan dokumentasi bila perlu.","Pemohon","Nota, formulir","Pengajuan tercatat","7 hari kerja setelah pengeluaran"],["4","Verifikasi: Biro Keuangan memeriksa bukti, kesesuaian anggaran, dan kewajaran nilai sesuai SOP-KEU-016.","Kabiro Keuangan","Pengajuan","Lolos, dikurangi, atau ditolak","3 hari kerja"],["5","Persetujuan: Penggantian disetujui sesuai tingkat nilai SOP-KEU-006; pengurangan atau penolakan disertai alasan tertulis.","Presiden / Kabiro Keuangan","Hasil verifikasi","Persetujuan penggantian","2 hari kerja"],["6","Pembayaran: Bendahara membayar melalui transfer kepada rekening pemohon dan meminta tanda terima.","Bendahara","Persetujuan","Penggantian dibayar","5 hari kerja setelah verifikasi"],["7","Pencatatan dan arsip: Pembayaran dicatat pada buku kas; bukti diarsipkan bersama berkas kegiatan.","Bendahara","Bukti pembayaran","Catatan dan arsip","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pengajuan paling lambat 7 hari kerja setelah pengeluaran, verifikasi paling lambat 3 hari kerja, dan pembayaran paling lambat 5 hari kerja setelah verifikasi sesuai kas. Hasil akhir: penggantian dibayar dan tercatat dengan bukti lengkap."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengajuan melewati 7 hari kerja: dapat ditolak, kecuali ada alasan yang diterima Presiden.","Kas belum tersedia: penggantian dijadwalkan dan pemohon diberi tahu tertulis.","Selisih nilai atau bukti meragukan: ditahan dan diproses SOP-KEU-016; bila ada indikasi pelanggaran, SOP-RSK-007.","Perbedaan pendapat soal kewajaran: diputuskan Presiden."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% pengajuan diselesaikan dalam 10 hari kerja sejak lengkap.","100% penggantian didukung nota asli.","Tidak ada penggantian tanpa persetujuan yang tidak diratifikasi.","Tidak ada keluhan keterlambatan lebih dari 14 hari kerja."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Penggantian Biaya yang disetujui.","Nota asli dan bukti pembayaran penggantian.","Catatan buku kas.","Persetujuan di muka atau ratifikasi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Keuangan mencatat seluruh penggantian pada register dan melaporkan nilai serta tunggakan setiap bulan; Irjen memeriksa kewajaran secara berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Persetujuan talangan → Pengeluaran → Ajukan penggantian → Verifikasi → Persetujuan → Bayar → Catat dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Persetujuan Talangan","Pemohon; keperluan; perkiraan nilai; pos anggaran; persetujuan."],["Formulir Penggantian Biaya","Pemohon; kegiatan; uraian; nilai; nomor nota; rekening; tanda tangan."],["Register Penggantian Biaya","Nomor; tanggal; pemohon; nilai; status; tanggal bayar."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Ada persetujuan di muka atau alasan mendesak yang diratifikasi.","☐ Ya ☐ Tidak"],["2","Pengeluaran sesuai anggaran dan wajar.","☐ Ya ☐ Tidak"],["3","Nota asli lengkap dan sah.","☐ Ya ☐ Tidak"],["4","Persetujuan sesuai tingkat nilai.","☐ Ya ☐ Tidak"],["5","Pembayaran ke rekening pemohon tercatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-009","g":"Keuangan dan Pengadaan","t":"Pengelolaan Kas dan Rekening Organisasi","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[196,199],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pembukaan, pengamanan, pengoperasian, dan pencatatan rekening serta kas BEM, sehingga seluruh dana organisasi tersimpan aman, terpisah dari keuangan pribadi, dan hanya dapat dipakai melalui kontrol ganda."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk rekening organisasi, kas kecil, aplikasi perbankan, buku kas, dan penandatangan transaksi. SOP ini tidak mengatur rekonsiliasi berkala (lihat SOP-KEU-017) dan serah terima rekening antarkabinet (lihat SOP-TRN-004 dan SOP-KEU-020)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (2) dan (3).","ART Pasal 3 (Kewajiban) huruf e dan ART Pasal 2 huruf f.","ART Pasal 11 huruf i dan k.","SOP-RSK-008 (Pengamanan Data dan Akses Digital) dan SOP-KOM-013 (Pengelolaan Akses Akun Digital)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rekening organisasi","Rekening atas nama BEM atau rekening yang ditetapkan kampus untuk pengelolaan dana BEM."],["Kontrol ganda","Ketentuan bahwa transaksi memerlukan dua pihak: pelaksana dan penyetuju."],["Kas kecil","Dana tunai terbatas untuk kebutuhan kecil dan mendesak."],["Penandatangan","Pejabat yang ditetapkan berwenang atas rekening organisasi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Seluruh dana organisasi disimpan pada rekening atas nama organisasi atau rekening yang ditetapkan kampus; dana tidak disimpan pada rekening pribadi atau dicampur dengan uang pribadi.","Rekening dan produk perbankan yang dipakai harus bebas dari bunga dan unsur riba; sedapat mungkin menggunakan bank atau layanan syariah. Bila kampus menentukan lain, ketentuan kampus yang berlaku.","Penandatangan ditetapkan melalui Keputusan Presiden (usulan: Presiden dan Kepala Biro Keuangan); Bendahara melaksanakan transaksi, dan transaksi tidak sah tanpa persetujuan penyetuju.","Saldo kas kecil paling banyak Rp1.000.000 (usulan); kelebihan disetor ke rekening.","Kata sandi, token, dan kode OTP bersifat pribadi, tidak dibagikan, dan perangkat yang dipakai harus aman.","Setiap perubahan penandatangan atau pembukaan atau penutupan rekening harus berita acara dan dilaporkan kepada KAUR ORMAWA bila diwajibkan kampus."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan penandatangan, menyetujui pembukaan atau penutupan rekening, dan bertanggung jawab akhir atas keamanan dana."],["Kepala Biro Keuangan","R","Mengelola dan mengawasi rekening dan kas, menjadi penandatangan atau penyetuju, dan memeriksa buku kas."],["Bendahara","R","Melaksanakan transaksi, menyimpan kas kecil, dan mencatat buku kas harian."],["Sekretaris Jenderal","R","Membuat surat dan berita acara terkait pembukaan atau perubahan rekening serta mengarsipkan."],["Inspektur Jenderal","C","Memeriksa kepatuhan terhadap kontrol ganda dan keamanan akses."],["KAUR ORMAWA","I","Menerima pelaporan rekening bila diwajibkan kampus."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Keputusan Presiden tentang penandatangan.","Persyaratan bank atau kampus.","Buku kas dan mutasi rekening.","Daftar akses dan perangkat."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan: Presiden menetapkan penandatangan dan pelaksana dalam Keputusan Presiden; rekening dibuka atau ditetapkan sesuai ketentuan kampus.","Presiden","Struktur kabinet, aturan kampus","Keputusan dan rekening aktif","5 hari kerja setelah struktur ditetapkan"],["2","Pengamanan akses: Bendahara dan penyetuju mengatur akses perbankan, kata sandi, dan perangkat; akses dicatat pada Daftar Akses Keuangan.","Kabiro Keuangan","Data akses","Daftar Akses Keuangan","Saat rekening aktif"],["3","Pelaksanaan transaksi: Setiap transaksi disiapkan Bendahara dan disetujui penyetuju sebelum dieksekusi; tangkapan layar bukti disimpan.","Bendahara","Persetujuan pembayaran","Transaksi terlaksana","Sesuai SOP-KEU- 006"],["4","Pengelolaan kas kecil: Kas kecil diberikan dalam batas saldo; pengisian ulang dilakukan setelah pengeluaran dipertanggungjawabkan.","Bendahara","Bukti pengeluaran","Kas kecil terkendali","Sesuai kebutuhan"],["5","Pencatatan: Bendahara mencatat seluruh transaksi pada buku kas harian dan memperbarui saldo.","Bendahara","Bukti transaksi","Buku kas diperbarui","Setiap hari ada transaksi"],["6","Laporan saldo: Kabiro Keuangan menyampaikan saldo dan mutasi kepada Presiden.","Kabiro Keuangan","Buku kas, mutasi","Laporan saldo","Setiap minggu"],["7","Perubahan penandatangan: Bila ada pergantian atau pengunduran, akses lama dicabut, akses baru diberikan, dan berita acara dibuat.","Presiden dan Sekjen","Keputusan baru","Berita acara perubahan","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Rekening dan penandatangan ditetapkan paling lambat 5 hari kerja setelah struktur kabinet ditetapkan; laporan saldo disampaikan setiap minggu. Hasil akhir: rekening aman dengan kontrol ganda dan buku kas terkini."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Akses digital bocor atau perangkat hilang: segera blokir dan laporkan ke Presiden, lalu SOP-RSK-009.","Selisih kas fisik atau buku: SOP-KEU-017 dan SOP-KEU-018.","Penandatangan berhalangan: SOP-GOV-009 dan pergantian sementara melalui Keputusan Presiden.","Dugaan penyalahgunaan: SOP-RSK-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% transaksi bank memenuhi kontrol ganda.","Saldo kas kecil tidak melebihi batas.","Tidak ada dana organisasi pada rekening pribadi.","Laporan saldo disampaikan setiap minggu."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Keputusan Presiden tentang penandatangan.","Daftar Akses Keuangan.","Buku kas harian dan mutasi rekening.","Berita acara perubahan rekening atau penandatangan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Keuangan memeriksa kas kecil dan buku kas setiap bulan; Irjen memeriksa kontrol ganda dan keamanan akses secara berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tetapkan penandatangan → Buka atau tetapkan rekening → Atur akses → Transaksi dengan kontrol ganda → Catat buku kas → Laporan saldo → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Keputusan Penandatangan Rekening","Nama dan jabatan; kewenangan; batas nilai; masa berlaku; tanda tangan Presiden."],["Daftar Akses Keuangan","Nama; peran; akses; perangkat; tanggal diberikan atau dicabut."],["Buku Kas Harian","Tanggal; uraian; pemasukan; pengeluaran; saldo; nomor bukti."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Rekening atas nama organisasi atau ditetapkan kampus.","☐ Ya ☐ Tidak"],["2","Penandatangan ditetapkan tertulis dan kontrol ganda berjalan.","☐ Ya ☐ Tidak"],["3","Kata sandi dan token tidak dibagikan.","☐ Ya ☐ Tidak"],["4","Saldo kas kecil tidak melebihi batas.","☐ Ya ☐ Tidak"],["5","Laporan saldo disampaikan tepat waktu.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-010","g":"Keuangan dan Pengadaan","t":"Pembelian Barang dan Jasa","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[200,203],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pembelian barang dan jasa untuk kebutuhan BEM dan kegiatan, sehingga pembelian sesuai kebutuhan dan anggaran, harga wajar, kualitas memadai, bebas konflik kepentingan, dan sesuai syariat."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pembelian barang, perlengkapan, konsumsi, dan jasa oleh BEM atau panitia. SOP ini tidak mengatur perbandingan penawaran dan pemilihan penyedia secara rinci (lihat SOP-KEU-011) dan tidak mengatur pembayaran (lihat SOP-KEU-006)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (2) (bebas riba, gharar, dan maysir).","ART Pasal 3 (Kewajiban) huruf e.","ART Pasal 11 huruf i dan k (larangan penyelewengan dana dan penggunaan nama atau fasilitas untuk kepentingan pribadi).","SOP-PRO-012 (Pengadaan Perlengkapan dan Konsumsi), SOP-AST-001 dan SOP-AST-002 (Pendataan dan Kode Inventaris), serta SOP-RSK-006 (Konflik Kepentingan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pembelian","Perolehan barang atau jasa dengan pembayaran dari dana organisasi."],["Penyedia","Toko, perusahaan, atau perorangan yang menjual barang atau jasa."],["Barang inventaris","Barang tahan lama yang dicatat sebagai aset sesuai SOP-AST."],["Berita Acara Penerimaan","Dokumen yang mencatat jenis, jumlah, dan kondisi barang atau hasil jasa yang diterima."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pembelian hanya untuk kebutuhan yang tercantum pada anggaran yang disetujui; pemohon lebih dahulu memeriksa apakah kebutuhan dapat dipenuhi dari inventaris yang ada.","Metode pembelian menurut nilai (usulan): sampai Rp500.000 pembelian langsung dengan nota; di atas Rp500.000 sampai Rp5.000.000 paling sedikit 2 penawaran; di atas Rp5.000.000 paling sedikit 3 penawaran (SOP-KEU-011).","Barang dan jasa harus halal, bermanfaat, dan akadnya jelas; dilarang membeli barang yang diharamkan, memakai akad ribawi, atau menerima komisi atau hadiah pribadi dari penyedia.","Pengurus yang memiliki hubungan kepentingan dengan penyedia wajib menyatakannya dan tidak ikut memutuskan pemilihan penyedia.","Barang inventaris dengan nilai di atas Rp500.000 atau umur manfaat lebih dari satu tahun (usulan) wajib dicatat sebagai aset.","Pembelian tidak boleh dipecah menjadi beberapa transaksi untuk menghindari tingkat persetujuan dan metode yang lebih ketat."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Memastikan pembelian sesuai anggaran, metode, dan aturan; bertanggung jawab atas proses pembelian."],["Pemohon / Ketua pelaksana","R","Menyusun kebutuhan dan spesifikasi, mengajukan pembelian, dan memeriksa barang atau jasa."],["Bendahara","R","Menyiapkan pembayaran, memegang dokumen pembelian, dan mencatat transaksi."],["Presiden","C","Menyetujui pembelian Tingkat 2 dan 3 sesuai SOP-KEU-006."],["Biro atau pengurus aset","R","Mencatat barang inventaris sesuai SOP-AST."],["Inspektur Jenderal","C","Memeriksa kepatuhan metode dan bukti pembelian pada sampel."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Lembar Persetujuan Anggaran.","Spesifikasi kebutuhan.","Daftar inventaris dan daftar harga acuan.","Penawaran atau nota penyedia."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Identifikasi kebutuhan: Pemohon menyusun jenis, jumlah, spesifikasi, waktu butuh, dan memeriksa ketersediaan barang di inventaris.","Pemohon","Anggaran, inventaris","Kebutuhan terdefinisi","Sesuai jadwal kegiatan"],["2","Permintaan pembelian: Pemohon mengisi Formulir Permintaan Pembelian dan menyerahkannya kepada Biro Keuangan.","Pemohon","Spesifikasi","Permintaan tercatat","Paling lambat 5 hari kerja sebelum butuh"],["3","Penentuan metode: Biro Keuangan memeriksa anggaran dan menentukan metode pembelian sesuai nilai serta memastikan tidak ada pemecahan transaksi.","Kabiro Keuangan","Permintaan, anggaran","Metode ditetapkan","1 hari kerja"],["4","Pemilihan penyedia: Pembelian langsung dilakukan untuk nilai kecil; nilai lebih besar mengikuti SOP-KEU-011.","Kabiro Keuangan / Pemohon","Metode","Penyedia terpilih","Sesuai metode"],["5","Persetujuan dan pembelian: Pembelian disetujui sesuai tingkat nilai (SOP-KEU-006), lalu dilakukan sesuai spesifikasi dan harga yang disepakati.","Presiden / Kabiro Keuangan","Persetujuan","Pesanan atau pembelian","2 hari kerja"],["6","Penerimaan dan pemeriksaan: Pemohon bersama Biro Keuangan memeriksa jumlah, spesifikasi, dan kondisi, lalu menandatangani Berita Acara Penerimaan.","Pemohon dan Biro Keuangan","Barang atau hasil jasa","Berita Acara Penerimaan","Saat barang diterima"],["7","Pembayaran dan pencatatan: Pembayaran dilakukan sesuai SOP- KEU-006; barang inventaris dicatat sesuai SOP-AST-001 dan SOP-AST- 002.","Bendahara","Berita Acara, tagihan","Pembayaran dan pencatatan aset","Sesuai jatuh tempo"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pembelian nilai kecil diselesaikan paling lambat 3 hari kerja sejak persetujuan; pembelian dengan penawaran mengikuti SOP-KEU-011. Hasil akhir: barang atau jasa diterima sesuai spesifikasi, dibayar, dan tercatat."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Barang tidak sesuai spesifikasi: ditolak atau diganti penyedia; ditandai pada penilaian penyedia.","Harga melebihi anggaran: SOP-KEU-014.","Kebutuhan sangat mendesak: SOP-GOV-012 dengan bukti pembelian dan ratifikasi.","Indikasi konflik kepentingan atau suap: SOP-RSK-006 atau SOP-RSK-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pembelian memiliki permintaan, persetujuan, dan Berita Acara Penerimaan.","Metode pembelian sesuai nilai pada 100% transaksi.","Tidak ada pemecahan transaksi untuk menghindari kontrol.","Barang inventaris tercatat paling lambat 5 hari kerja setelah diterima."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Permintaan Pembelian yang disetujui.","Penawaran atau nota penyedia.","Berita Acara Penerimaan.","Catatan aset dan arsip pembelian. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Biro Keuangan memeriksa kelengkapan dokumen setiap bulan; Irjen memeriksa sampel pembelian setiap triwulan dan semua pembelian Tingkat 3."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Identifikasi kebutuhan → Permintaan pembelian → Tentukan metode → Pilih penyedia → Persetujuan dan pembelian → Terima dan periksa → Bayar dan catat aset → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Pembelian","Pemohon; kegiatan; barang atau jasa; spesifikasi; jumlah; perkiraan harga; pos anggaran; waktu butuh."],["Berita Acara Penerimaan Barang atau Jasa","Penyedia; nomor pesanan; jenis dan jumlah; kondisi; penerima; pemeriksa; tanda tangan."],["Pernyataan Bebas Konflik Kepentingan","Nama; hubungan dengan penyedia (jika ada); pernyataan; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kebutuhan tercantum pada anggaran dan dicek terhadap inventaris.","☐ Ya ☐ Tidak"],["2","Metode pembelian sesuai nilai dan tidak dipecah.","☐ Ya ☐ Tidak"],["3","Barang atau jasa halal dan akad jelas.","☐ Ya ☐ Tidak"],["4","Berita Acara Penerimaan ditandatangani.","☐ Ya ☐ Tidak"],["5","Barang inventaris dicatat sebagai aset.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-011","g":"Keuangan dan Pengadaan","t":"Perbandingan Penawaran dan Pemilihan Penyedia","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[204,207],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur meminta, membandingkan, menilai, dan menetapkan penawaran penyedia barang atau jasa secara objektif dan terdokumentasi, sehingga BEM memperoleh nilai terbaik tanpa konflik kepentingan dan sesuai syariat."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pembelian barang atau jasa bernilai di atas Rp500.000 (usulan) sebagaimana SOP-KEU-010, termasuk jasa seperti percetakan, konsumsi, sewa perlengkapan, dan desain. SOP ini tidak mengatur penerimaan barang (lihat SOP-KEU-010) dan pembayaran (lihat SOP-KEU-006)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (2).","ART Pasal 3 (Kewajiban) huruf e.","ART Pasal 11 huruf i, j, dan k (larangan penyelewengan dana, kecurangan dalam pengambilan keputusan, dan penggunaan jabatan untuk kepentingan pribadi).","SOP-KEU-010 (Pembelian Barang dan Jasa) dan SOP-RSK-006 (Penanganan Konflik Kepentingan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Penawaran","Tawaran tertulis harga dan syarat dari penyedia atas spesifikasi yang diminta."],["Lembar Perbandingan Penawaran","Tabel yang membandingkan penawaran berdasarkan kriteria yang telah ditetapkan."],["Tim evaluasi","Dua atau lebih pengurus yang menilai penawaran dan tidak memiliki konflik kepentingan."],["Penunjukan langsung","Pemilihan penyedia tanpa persaingan karena alasan terbatas yang diizinkan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Jumlah penawaran minimum (usulan): 2 penawaran untuk nilai di atas Rp500.000 sampai Rp5.000.000, dan 3 penawaran untuk nilai di atas Rp5.000.000.","Kriteria penilaian ditetapkan sebelum penawaran dibuka: harga, kesesuaian spesifikasi, kualitas, ketepatan waktu, kehalalan dan legalitas, reputasi, serta layanan purna.","Tim evaluasi minimal 2 orang dari Biro Keuangan dan unit pemohon; anggota yang memiliki hubungan kepentingan dengan penyedia tidak boleh menilai.","Penyedia ditetapkan oleh Presiden; penetapan Tingkat 3 disertai catatan Irjen. Penawaran terendah tidak otomatis dipilih bila tidak memenuhi spesifikasi.","Penunjukan langsung hanya untuk penyedia tunggal, keadaan mendesak, atau nilai kecil, dengan berita acara alasan dan ratifikasi bila mendesak.","Dilarang menerima hadiah, komisi, atau fasilitas pribadi dari penyedia; kerahasiaan penawaran dijaga sampai evaluasi selesai."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan penyedia terpilih dan bertanggung jawab atas keputusan pemilihan."],["Kepala Biro Keuangan","R","Memimpin tim evaluasi, mengelola permintaan penawaran, dan menyusun Lembar Perbandingan Penawaran."],["Pemohon","R","Menyusun spesifikasi dan memberi penilaian teknis."],["Anggota tim evaluasi","R","Menilai penawaran secara independen dan mengisi pernyataan bebas konflik kepentingan."],["Bendahara","R","Menyimpan dokumen penawaran dan menyiapkan pembayaran setelah penetapan."],["Inspektur Jenderal","C","Memeriksa proses pada Tingkat 3 dan sampel lain."],["Penyedia","I","Menerima undangan penawaran dan pemberitahuan hasil."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Permintaan Pembelian yang disetujui.","Spesifikasi dan kriteria penilaian.","Daftar calon penyedia.","Penawaran tertulis."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan spesifikasi dan kriteria: Pemohon dan Biro Keuangan menetapkan spesifikasi, volume, jadwal, dan kriteria penilaian beserta bobotnya.","Pemohon dan Kabiro Keuangan","Permintaan pembelian","Spesifikasi dan kriteria","2 hari kerja"],["2","Pemilihan calon penyedia: Biro Keuangan menyusun daftar calon penyedia yang halal, kredibel, dan mudah ditelusuri, minimal sesuai jumlah penawaran yang dibutuhkan.","Kabiro Keuangan","Daftar penyedia","Daftar calon penyedia","1 hari kerja"],["3","Permintaan penawaran: Biro Keuangan mengirim permintaan penawaran tertulis kepada calon penyedia dengan batas waktu yang sama.","Kabiro Keuangan","Spesifikasi","Permintaan terkirim","1 hari kerja"],["4","Penerimaan penawaran: Penawaran diterima dan disimpan tertutup sampai batas waktu berakhir; tidak ada negosiasi sebelum evaluasi.","Bendahara","Penawaran","Penawaran terkumpul","3 hari kerja"],["5","Evaluasi: Tim evaluasi menilai penawaran terhadap kriteria dan menyusun Lembar Perbandingan Penawaran beserta rekomendasi.","Tim evaluasi","Penawaran, kriteria","Lembar Perbandingan dan rekomendasi","2 hari kerja"],["6","Pemeriksaan: Untuk Tingkat 3, Irjen memeriksa proses dan kewajaran rekomendasi.","Irjen","Dokumen evaluasi","Catatan pemeriksaan","2 hari kerja"],["7","Penetapan dan pemberitahuan: Presiden menetapkan penyedia terpilih; hasil diberitahukan kepada seluruh penyedia peserta.","Presiden / Kabiro Keuangan","Rekomendasi","Penetapan penyedia","2 hari kerja"],["8","Pesanan dan arsip: Pesanan atau kesepakatan dibuat dalam bentuk tertulis dan seluruh dokumen diarsipkan.","Bendahara dan Sekjen","Penetapan","Pesanan tertulis dan arsip","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari permintaan penawaran hingga penetapan penyedia ditargetkan paling lama 10 hari kerja untuk Tingkat 2 dan 14 hari kerja untuk Tingkat 3, kecuali ditetapkan lain karena jadwal kegiatan. Hasil akhir: penyedia terpilih dengan dokumen perbandingan lengkap."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Penawaran kurang dari jumlah minimum: perpanjangan batas waktu satu kali; bila tetap kurang, penunjukan langsung dengan berita acara.","Seluruh penawaran melebihi anggaran: negosiasi dengan penyedia peringkat terbaik atau SOP-KEU- 014.","Keberatan dari penyedia: Kabiro Keuangan menjawab tertulis; bila perlu diputuskan Presiden.","Indikasi konflik kepentingan atau persekongkolan: SOP-RSK-006 atau SOP-RSK-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pembelian di atas Rp500.000 memiliki Lembar Perbandingan Penawaran.","Minimal 90% pembelian memenuhi jumlah penawaran minimum.","Seluruh anggota tim menandatangani pernyataan bebas konflik kepentingan.","Penetapan selesai dalam batas waktu pada minimal 80% kasus."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Spesifikasi dan kriteria penilaian.","Penawaran dari penyedia.","Lembar Perbandingan Penawaran dan penetapan penyedia.","Pernyataan bebas konflik kepentingan.","Pesanan atau kesepakatan tertulis. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Biro Keuangan menyimpan dokumen proses pemilihan lengkap; Irjen memeriksa sampel proses setiap triwulan dan semua proses Tingkat 3."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Spesifikasi dan kriteria → Calon penyedia → Minta penawaran → Terima penawaran → Evaluasi → Periksa Irjen (Tingkat 3) → Penetapan Presiden → Pesanan dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Penawaran","Spesifikasi; volume; waktu; kriteria; batas penyerahan; kontak."],["Lembar Perbandingan Penawaran","Penyedia; harga; spesifikasi; waktu; syarat; nilai kriteria; skor; rekomendasi."],["Berita Acara Penunjukan Langsung","Alasan; penyedia; nilai; persetujuan; ratifikasi."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kriteria ditetapkan sebelum penawaran dibuka.","☐ Ya ☐ Tidak"],["2","Jumlah penawaran memenuhi minimum atau ada berita acara pengecualian.","☐ Ya ☐ Tidak"],["3","Tim evaluasi bebas konflik kepentingan.","☐ Ya ☐ Tidak"],["4","Penetapan oleh Presiden terdokumentasi.","☐ Ya ☐ Tidak"],["5","Seluruh dokumen proses diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-012","g":"Keuangan dan Pengadaan","t":"Pengelolaan Sponsor dan Dana Eksternal","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[208,211],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengelolaan keuangan atas sponsor, hibah, dan dana eksternal lain, sehingga dana yang diterima halal, tidak mengikat organisasi melampaui satu periode, dipakai sesuai tujuan, dan dipertanggungjawabkan kepada pemberi dan pihak berwenang."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk sisi keuangan seluruh sponsor, hibah, dan dana eksternal yang diterima BEM atau panitia. SOP ini tidak mengatur pengajuan dan negosiasi kerja sama sponsor (lihat SOP-HKE-007 dan SOP-HKE-008) dan tidak mengatur pencatatan donasi atau kontribusi kegiatan (lihat SOP-KEU-013)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf b (hibah, donasi, atau sponsor yang tidak mengikat dan tidak menimbulkan kewajiban melampaui satu periode serta sesuai syariat Islam) dan ayat (2).","ART Pasal 2 huruf e (kerja sama yang halal dan tidak mengikat dengan persetujuan Ketua STDIIS) dan huruf f.","ART Pasal 3 (Kewajiban) huruf d dan e.","SOP-HKE-005 (Kerja Sama), SOP-HKE-007 dan SOP-HKE-008 (Sponsorship), serta SOP-KEU-005 (Penerimaan Pemasukan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Sponsor","Pihak eksternal yang memberi dana, barang, atau jasa untuk mendukung kegiatan dengan imbal balik terbatas, misalnya publikasi."],["Dana eksternal","Dana dari pihak luar kampus berupa hibah, sponsor, atau bantuan lain."],["Dana terikat","Dana eksternal yang hanya boleh dipakai untuk tujuan yang disepakati."],["Laporan kepada pemberi","Laporan penggunaan dana kepada sponsor atau pemberi hibah sesuai kesepakatan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Dana eksternal hanya diterima bila sumbernya halal, tidak mengikat, tidak mengganggu independensi organisasi, tidak menimbulkan kewajiban melampaui satu periode, dan tidak bertentangan dengan Al- Qur'an dan As-Sunnah.","Sponsor dari usaha atau pihak yang bergerak pada hal yang diharamkan atau dari sumber yang tidak jelas ditolak; keputusan penolakan dicatat.","Perjanjian atau kerja sama dengan pihak eksternal memerlukan persetujuan Ketua STDIIS (ART Pasal 2 huruf e) sebelum ditandatangani; imbal balik hanya berupa hal yang wajar dan sesuai syariat.","Seluruh dana diterima ke rekening organisasi dengan bukti penerimaan resmi, tidak ke rekening pribadi (SOP-KEU-005 dan SOP-KEU-009).","Dana eksternal terikat dicatat terpisah, dipakai sesuai kesepakatan, dan dilaporkan kepada pemberi sesuai perjanjian.","Pengurus yang menerima manfaat pribadi dari sponsor dianggap melanggar konflik kepentingan (SOP- RSK-006)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Mengelola sisi keuangan sponsor dan dana eksternal serta bertanggung jawab atas pencatatan dan pelaporannya."],["Menteri Hubungan Eksternal / penghubung mitra","R","Menjalin hubungan dengan calon sponsor dan menyampaikan data awal kepada Biro Keuangan."],["Bendahara","R","Menerima dana, menerbitkan bukti penerimaan, memisahkan dana terikat, dan mencatat penggunaan."],["Presiden","R","Menyetujui penerimaan dan menandatangani kesepakatan setelah ada persetujuan Ketua STDIIS."],["Ketua STDIIS","C","Memberikan persetujuan kerja sama eksternal."],["Inspektur Jenderal","C","Memeriksa kepatuhan terhadap AD Pasal 15 dan perjanjian."],["Sekretaris Jenderal","R","Menyusun dan mengarsipkan surat, perjanjian, dan laporan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Proposal atau permohonan sponsor.","Draf perjanjian atau surat kesepakatan.","Profil calon sponsor.","Rencana penggunaan dana."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan informasi: Penghubung mitra menyampaikan data calon sponsor, bentuk bantuan, dan imbal balik yang diminta kepada Biro Keuangan.","Menteri Hubungan Eksternal / penghubung","Data sponsor","Data tercatat","1 hari kerja"],["2","Uji kelayakan: Biro Keuangan memeriksa kehalalan sumber, ikatan atau syarat, dan kesesuaian dengan AD Pasal 15 menggunakan Checklist Kelayakan Sponsor.","Kabiro Keuangan","Data dan draf perjanjian","Layak atau ditolak","3 hari kerja"],["3","Persetujuan: Presiden memutuskan penerimaan; bila ada perjanjian, diajukan persetujuan Ketua STDIIS melalui SOP-HKE-005.","Presiden dan Sekjen","Hasil uji kelayakan","Persetujuan internal dan Ketua STDIIS","5 hari kerja"],["4","Penandatanganan: Perjanjian ditandatangani oleh pejabat berwenang dengan salinan kepada Biro Keuangan.","Presiden","Persetujuan","Perjanjian ditandatangani","2 hari kerja"],["5","Penerimaan dana: Dana masuk ke rekening organisasi; bukti penerimaan resmi diterbitkan dan dana dicatat sesuai SOP-KEU- 005.","Bendahara","Perjanjian, bukti transfer","Dana tercatat","1 hari kerja"],["6","Penggunaan dan pemantauan: Dana dipakai sesuai tujuan melalui alur SOP-KEU-004 dan SOP-KEU- 006; Biro Keuangan memantau realisasi dan kewajiban imbal balik.","Kabiro Keuangan","Anggaran, perjanjian","Penggunaan sesuai tujuan","Selama kegiatan"],["7","Pelaporan: Laporan penggunaan dana disusun untuk pemberi sesuai perjanjian dan untuk BPM serta pihak berwenang dalam LPJ.","Kabiro Keuangan","Realisasi","Laporan sponsor","Sesuai perjanjian"],["8","Penutupan: Sisa dana diselesaikan sesuai perjanjian (SOP-KEU-018) dan seluruh dokumen diarsipkan.","Bendahara dan Sekjen","Laporan akhir","Sponsor ditutup","7 hari kerja setelah LPJ"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Uji kelayakan paling lambat 3 hari kerja setelah data lengkap; pelaporan kepada sponsor sesuai perjanjian. Hasil akhir: dana eksternal diterima, digunakan, dan dilaporkan sesuai kesepakatan serta aturan."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Sponsor menuntut imbalan yang mengikat atau bertentangan syariat: ditolak atau dinegosiasikan ulang; keputusan akhir pada Presiden dengan konsultasi KAUR ORMAWA atau Ketua STDIIS.","Sponsor melanggar kesepakatan: dibahas dengan Penghubung mitra dan Presiden; tindakan sesuai perjanjian.","Dana masuk ke rekening pribadi: segera dipindahkan ke rekening organisasi dan dilaporkan (SOP- RSK-007).","Sponsor ingin mengubah tujuan penggunaan: perubahan tertulis dan disetujui Presiden."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% sponsor melewati uji kelayakan sebelum diterima.","100% dana eksternal masuk ke rekening organisasi dengan bukti resmi.","Laporan kepada pemberi dikirim sesuai jadwal pada minimal 90% sponsor.","Tidak ada kewajiban sponsor yang melampaui satu periode kepengurusan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Checklist Kelayakan Sponsor.","Perjanjian atau surat kesepakatan.","Bukti penerimaan dan catatan buku kas.","Laporan penggunaan dana kepada pemberi.","Arsip sponsor. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Biro Keuangan memperbarui Register Sponsor dan Dana Eksternal setiap bulan; Irjen memeriksa kepatuhan terhadap AD Pasal 15 secara berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima info sponsor → Uji kelayakan → Persetujuan Presiden dan Ketua STDIIS → Perjanjian → Terima dana → Gunakan dan pantau → Laporan → Tutup → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Checklist Kelayakan Sponsor","Identitas; sumber dana; bidang usaha; syarat dan imbalan; kesesuaian syariah; ikatan lintas periode; keputusan."],["Templat Perjanjian Sponsor","Para pihak; bentuk dukungan; imbal balik terbatas; periode; pelaporan; penyelesaian sisa dana; tanda tangan."],["Register Sponsor dan Dana Eksternal","Sponsor; nilai; tujuan; tanggal; realisasi; laporan; status."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Sumber dana halal dan tidak bertentangan dengan syariat.","☐ Ya ☐ Tidak"],["2","Tidak ada ikatan yang melampaui satu periode.","☐ Ya ☐ Tidak"],["3","Persetujuan Ketua STDIIS diperoleh untuk perjanjian.","☐ Ya ☐ Tidak"],["4","Dana masuk ke rekening organisasi dengan bukti resmi.","☐ Ya ☐ Tidak"],["5","Laporan kepada pemberi dan BPM dilakukan sesuai jadwal.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-013","g":"Keuangan dan Pengadaan","t":"Pencatatan Donasi atau Kontribusi Kegiatan","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[212,215],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penerimaan dan pencatatan donasi, infak, dan kontribusi peserta untuk kegiatan, baik berupa uang maupun barang, sehingga seluruhnya tercatat, amanah, dan dapat diperiksa."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk donasi dan infak dari pengurus, mahasiswa, alumni, atau masyarakat, serta kontribusi atau biaya pendaftaran peserta kegiatan. SOP ini tidak mengatur sponsor dengan perjanjian (lihat SOP-KEU-012)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf b, ayat (2), dan ayat (3).","ART Pasal 2 huruf f dan ART Pasal 3 (Kewajiban) huruf e.","ART Pasal 11 huruf i dan k.","SOP-KEU-005 (Penerimaan dan Pencatatan Pemasukan) dan SOP-PRO-013 (Publikasi dan Pendaftaran Peserta)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Donasi","Pemberian sukarela berupa uang atau barang tanpa imbalan yang mengikat."],["Kontribusi peserta","Biaya pendaftaran atau iuran yang dibayar peserta untuk kegiatan."],["Donasi barang (in-kind)","Pemberian berupa barang atau jasa yang dinilai dengan harga wajar."],["Donatur anonim","Pemberi yang tidak ingin disebut namanya; dicatat dengan kode."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Donasi diterima bila sukarela, tidak mengikat, tidak menimbulkan kewajiban melampaui satu periode, dan tidak bertentangan dengan syariat.","Donasi atau infak yang diberikan untuk tujuan tertentu dicatat sebagai dana terikat dan hanya dipakai sesuai tujuan; bila tujuan tidak dapat dipenuhi, penyelesaian dikonfirmasi kepada donatur.","Setiap donasi uang dan kontribusi peserta dicatat dengan bukti penerimaan resmi; donasi barang dicatat dengan berita acara dan nilai wajar.","Donatur anonim tetap dicatat dengan kode dan identitasnya dirahasiakan sesuai SOP-RSK-010.","Ringkasan penerimaan dan penggunaan donasi dilaporkan kepada donatur atau peserta secara terbuka sesuai kesepakatan.","Biaya kontribusi peserta ditetapkan dalam anggaran dan tidak boleh melampaui kebutuhan yang direncanakan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Bertanggung jawab atas pencatatan, penyimpanan, dan pelaporan donasi serta kontribusi."],["Bendahara","R","Menerima, mencatat, dan mengelola donasi serta menerbitkan bukti penerimaan."],["Ketua pelaksana","R","Membuka penggalangan, menyampaikan donasi kepada Bendahara, dan melaporkan penggunaannya."],["Presiden","C","Menyetujui penggalangan donasi yang berskala besar atau berkaitan dengan pihak luar."],["Inspektur Jenderal","C","Memeriksa kesesuaian catatan dengan bukti."],["Donatur / peserta","I","Menerima bukti dan laporan penggunaan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Persetujuan penggalangan donasi.","Rincian tujuan penggunaan.","Data donatur atau peserta.","Bukti pembayaran atau barang."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Perencanaan penggalangan: Ketua pelaksana menyampaikan tujuan, target, dan cara penggalangan untuk disetujui Biro Keuangan; skala besar disetujui Presiden.","Ketua pelaksana","Tujuan, target","Persetujuan penggalangan","3 hari kerja"],["2","Penerimaan: Donasi atau kontribusi diterima melalui rekening organisasi atau Bendahara; dana tunai tidak dipegang pribadi.","Bendahara","Dana, bukti","Dana diterima","Saat diterima"],["3","Penerbitan bukti: Bendahara menerbitkan bukti penerimaan; donasi barang dibuat berita acara dan dinilai wajar.","Bendahara","Dana atau barang","Bukti penerimaan","Segera"],["4","Pencatatan: Donasi dan kontribusi dicatat pada Register Donasi dan Kontribusi serta buku kas, dengan penanda dana terikat.","Bendahara","Bukti","Register diperbarui","1 hari kerja"],["5","Penggunaan: Dana dipakai sesuai tujuan melalui SOP-KEU-004 dan SOP-KEU-006; donasi barang dicatat sebagai aset atau persediaan.","Ketua pelaksana","Persetujuan pencairan","Penggunaan sesuai tujuan","Selama kegiatan"],["6","Pelaporan: Ringkasan penerimaan dan penggunaan disampaikan kepada donatur atau peserta dan dimasukkan dalam laporan kegiatan.","Kabiro Keuangan","Register","Laporan donasi","Bersama LPJ kegiatan"],["7","Penyelesaian sisa: Sisa dana diselesaikan sesuai tujuan atau sesuai persetujuan donatur (SOP- KEU-018).","Kabiro Keuangan","Laporan","Sisa diselesaikan","7 hari kerja setelah kegiatan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pencatatan paling lambat 1 hari kerja sejak donasi atau kontribusi diterima; laporan bersamaan dengan LPJ kegiatan. Hasil akhir: seluruh donasi dan kontribusi tercatat, digunakan sesuai tujuan, dan dilaporkan."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Donatur menuntut imbalan yang mengikat: dialihkan ke SOP-KEU-012.","Donasi diberikan melalui rekening pribadi pengurus: segera dialihkan ke rekening organisasi dan dilaporkan.","Tujuan donasi tidak dapat dipenuhi: konfirmasi kepada donatur sebelum dialihkan.","Indikasi penyalahgunaan: SOP-RSK-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% donasi dan kontribusi memiliki bukti penerimaan.","100% donasi terikat dipakai sesuai tujuan.","Laporan penerimaan dan penggunaan disampaikan bersama LPJ.","Tidak ada donasi yang dikuasai pribadi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Donasi dan Kontribusi.","Bukti penerimaan dan berita acara donasi barang.","Laporan donasi dan kontribusi.","Catatan penyelesaian sisa. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Biro Keuangan menyandingkan register donasi dengan buku kas dan mutasi rekening setiap bulan; Irjen memeriksa secara berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Rencana penggalangan → Terima donasi → Terbitkan bukti → Catat register → Gunakan sesuai tujuan → Laporan → Selesaikan sisa → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Penggalangan Donasi","Kegiatan; tujuan; target; cara; penanggung jawab; persetujuan."],["Register Donasi dan Kontribusi","Tanggal; donatur atau kode; bentuk; nilai; tujuan; terikat; bukti; penggunaan."],["Berita Acara Donasi Barang","Pemberi; barang; jumlah; kondisi; nilai wajar; penerima."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Donasi sukarela, tidak mengikat, dan halal.","☐ Ya ☐ Tidak"],["2","Bukti penerimaan diterbitkan.","☐ Ya ☐ Tidak"],["3","Dana terikat dicatat dan dipakai sesuai tujuan.","☐ Ya ☐ Tidak"],["4","Identitas donatur anonim dilindungi.","☐ Ya ☐ Tidak"],["5","Laporan penggunaan disampaikan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-014","g":"Keuangan dan Pengadaan","t":"Penanganan Selisih Anggaran dan Biaya Tak Terduga","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[216,219],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyesuaian anggaran bila terjadi selisih antara rencana dan kebutuhan nyata atau muncul biaya tak terduga, sehingga perubahan dilakukan terkendali, disetujui pihak berwenang, dan tidak melampaui pagu atau aturan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk realokasi antarpos, penambahan anggaran, pemakaian pos biaya tak terduga, dan pembatalan sebagian anggaran. SOP ini tidak mengatur penyusunan awal anggaran (lihat SOP-KEU-001 dan SOP-KEU- 002) dan selisih kas (lihat SOP-KEU-018)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (4) (anggaran dengan persetujuan KAUR ORMAWA).","ART Bab III (Tugas) huruf e (anggaran dengan persetujuan BPM).","ART Pasal 10 ayat (4) huruf b (monitoring penggunaan anggaran dalam Rapat Koordinasi).","SOP-KEU-003 (Verifikasi dan Persetujuan Anggaran) dan SOP-GOV-012 (Keputusan Mendesak)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Selisih anggaran","Perbedaan antara nilai yang dianggarkan dan kebutuhan atau realisasi."],["Realokasi","Pemindahan alokasi dana dari satu pos ke pos lain dalam anggaran yang sama."],["Biaya tak terduga","Biaya wajar yang tidak dapat diperkirakan saat menyusun anggaran."],["Perubahan anggaran","Penyesuaian nilai atau struktur anggaran yang telah disetujui."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Realokasi antarpos dalam satu kegiatan sampai 10% dari total anggaran kegiatan disetujui Kepala Biro Keuangan (usulan); di atas 10% atau penambahan pos baru disetujui Presiden.","Pemakaian pos biaya tak terduga (paling banyak 5% dari anggaran kegiatan) disetujui Kabiro Keuangan sampai Rp500.000 dan Presiden di atasnya (usulan).","Penambahan total anggaran kegiatan atau perubahan sumber dana mengikuti SOP-KEU-003 dan, bila menyangkut dana kampus atau program kerja, persetujuan KAUR ORMAWA, BPM, atau Pembina.","Pengeluaran yang belum disetujui dilarang; pengeluaran mendesak mengikuti SOP-GOV-012 dan diratifikasi.","Perubahan tidak boleh dipakai untuk menutup penyimpangan; penyebab selisih dicatat untuk perbaikan perencanaan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menyetujui perubahan anggaran di atas batas kewenangan Kabiro Keuangan dan bertanggung jawab akhir."],["Kepala Biro Keuangan","R","Menilai selisih, menyetujui realokasi dalam batas, dan menyusun usulan perubahan."],["Ketua pelaksana / Menteri / Kabiro","R","Mengajukan usulan perubahan dengan alasan dan dokumen pendukung."],["Bendahara","R","Memperbarui pagu dan mencatat perubahan."],["Inspektur Jenderal","C","Meninjau perubahan besar atau berulang."],["BPM, KAUR ORMAWA, Pembina","I","Menyetujui perubahan yang menyentuh persetujuan mereka."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Anggaran yang berlaku.","Realisasi dan prakiraan kebutuhan.","Alasan dan bukti perubahan.","Sisa pagu dan saldo kas."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Identifikasi selisih: Ketua pelaksana atau Bendahara mengidentifikasi selisih atau kebutuhan baru dan menyampaikannya kepada Biro Keuangan.","Ketua pelaksana","Realisasi, anggaran","Selisih teridentifikasi","Segera"],["2","Pengajuan perubahan: Pengaju mengisi Formulir Perubahan Anggaran: pos, nilai lama dan baru, alasan, dan sumber dana pengganti.","Pengaju","Selisih, bukti","Usulan perubahan","3 hari kerja"],["3","Penilaian: Biro Keuangan menilai kewajaran, ketersediaan pagu atau sumber dana, dan dampaknya pada program lain.","Kabiro Keuangan","Usulan","Rekomendasi","2 hari kerja"],["4","Keputusan: Perubahan disetujui Kabiro Keuangan atau Presiden sesuai batas; yang membutuhkan pihak luar diteruskan sesuai SOP-KEU-003.","Presiden / Kabiro Keuangan","Rekomendasi","Keputusan perubahan","2 hari kerja"],["5","Pembaruan: Bendahara memperbarui anggaran, pagu, dan register perubahan.","Bendahara","Keputusan","Anggaran diperbarui","1 hari kerja"],["6","Pelaksanaan: Pengeluaran baru hanya dilakukan setelah perubahan berlaku sesuai SOP- KEU-006.","Pengaju","Perubahan berlaku","Pengeluaran sesuai","Sesuai jadwal"],["7","Evaluasi penyebab: Penyebab selisih dicatat dan dibahas pada rapat evaluasi untuk perbaikan perencanaan.","Kabiro Keuangan","Register perubahan","Catatan perbaikan","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Keputusan perubahan ditargetkan paling lambat 5 hari kerja sejak usulan lengkap; untuk keadaan mendesak berlaku SOP-GOV-012. Hasil akhir: anggaran terbarui dengan persetujuan yang sah."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Perubahan melampaui total pagu atau saldo kas: dibawa ke Rapat Pimpinan (SOP-GOV-005) untuk prioritas.","Perubahan berulang pada kegiatan yang sama: ditinjau Irjen sebagai indikasi perencanaan lemah.","Pihak luar menolak perubahan: kegiatan disesuaikan dengan anggaran yang ada.","Dugaan manipulasi: SOP-RSK-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% perubahan memiliki formulir dan persetujuan sebelum pengeluaran.","Realokasi dan biaya tak terduga tidak melebihi batas tanpa persetujuan yang sesuai.","Jumlah perubahan per kegiatan menurun dari periode ke periode.","Tidak ada temuan Irjen berupa pengeluaran tanpa perubahan yang disetujui."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Perubahan Anggaran yang disetujui.","Anggaran dan pagu yang diperbarui.","Register Perubahan Anggaran.","Persetujuan pihak luar, bila ada. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Biro Keuangan melaporkan perubahan anggaran dan penggunaan biaya tak terduga pada rapat kabinet; Irjen memeriksa secara berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Identifikasi selisih → Ajukan perubahan → Penilaian Biro Keuangan → Keputusan sesuai batas → Perbarui anggaran → Pengeluaran → Evaluasi penyebab → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Perubahan Anggaran","Kegiatan; pos; nilai lama; nilai baru; selisih; alasan; sumber dana pengganti; persetujuan."],["Register Perubahan Anggaran","Nomor; tanggal; kegiatan; nilai; jenis; penyetuju; status."],["Lembar Pemakaian Biaya Tak Terduga","Kegiatan; kejadian; nilai; bukti; persetujuan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Penyebab selisih jelas dan terdokumentasi.","☐ Ya ☐ Tidak"],["2","Batas kewenangan persetujuan dipatuhi.","☐ Ya ☐ Tidak"],["3","Sumber dana pengganti tersedia dan halal.","☐ Ya ☐ Tidak"],["4","Persetujuan pihak luar diperoleh bila diperlukan.","☐ Ya ☐ Tidak"],["5","Pagu dan register diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-015","g":"Keuangan dan Pengadaan","t":"Penyusunan Laporan Keuangan Kegiatan","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[220,223],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan laporan keuangan setiap kegiatan, sehingga seluruh pemasukan, pengeluaran, dan saldo kegiatan terlaporkan lengkap, tepat waktu, dan dapat diperiksa sebagai bagian laporan pertanggungjawaban."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kegiatan BEM yang menggunakan dana organisasi, dana kampus, sponsor, atau donasi. SOP ini mengatur bagian keuangan; laporan pertanggungjawaban kegiatan secara keseluruhan diatur SOP- PRO-020."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (3) dan AD Pasal 17 ayat (1) sampai (3) (laporan pertanggungjawaban berkala kepada BPM dan pelaporan kepada KAUR ORMAWA).","ART Pasal 3 (Kewajiban) huruf e dan g.","ART Bab III (Tugas) huruf e (laporan pertanggungjawaban anggaran dan program).","SOP-PRO-020 (LPJ Kegiatan) dan SOP-MONEV-007 (Pemeriksaan Pertanggungjawaban Keuangan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Laporan keuangan kegiatan","Dokumen yang memuat anggaran, realisasi, pemasukan, pengeluaran, selisih, dan saldo suatu kegiatan."],["Realisasi","Jumlah dana yang benar-benar digunakan atau diterima."],["Lampiran bukti","Kumpulan nota, kuitansi, dan bukti transfer yang mendukung angka dalam laporan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Laporan keuangan disusun oleh Bendahara kegiatan bersama Biro Keuangan dan disahkan oleh ketua pelaksana serta Kepala Biro Keuangan.","Laporan memuat perbandingan anggaran dengan realisasi per pos, penjelasan selisih, daftar pemasukan, daftar pengeluaran, sisa dana, dan lampiran bukti.","Seluruh angka harus cocok dengan buku kas, mutasi rekening, dan bukti; angka tanpa bukti tidak dimasukkan.","Waktu penyampaian paling lambat 10 hari kerja setelah kegiatan selesai (usulan), kecuali kampus menetapkan batas yang lebih ketat.","Laporan yang melibatkan dana kampus atau sponsor memenuhi format dan batas waktu masing- masing."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Mengesahkan laporan keuangan dan bertanggung jawab atas kebenaran angka."],["Ketua pelaksana","R","Menyerahkan bukti dan memastikan laporan sesuai kegiatan."],["Bendahara kegiatan / Bendahara BEM","R","Menyusun laporan, merekap bukti, dan merekonsiliasi dengan buku kas."],["Inspektur Jenderal","C","Memeriksa laporan bila diminta atau pada sampel."],["Sekretaris Jenderal","R","Menggabungkan laporan keuangan dengan LPJ kegiatan dan mengarsipkan."],["BPM, KAUR ORMAWA, sponsor","I","Menerima laporan sesuai kewenangan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Anggaran yang disetujui dan perubahannya.","Buku kas dan mutasi rekening kegiatan.","Nota dan bukti transaksi.","Laporan donasi dan sponsor terkait."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penutupan transaksi: Setelah kegiatan, Bendahara menyatakan penutupan transaksi dan memastikan seluruh uang muka telah dipertanggungjawabkan (SOP-KEU- 007).","Bendahara","Buku kas, uang muka","Transaksi ditutup","3 hari kerja setelah kegiatan"],["2","Rekapitulasi bukti: Bendahara merekap dan memeriksa kelengkapan bukti sesuai SOP-KEU- 016.","Bendahara","Nota, bukti","Rekap bukti","3 hari kerja"],["3","Penyusunan laporan: Laporan keuangan disusun: anggaran, realisasi, selisih, pemasukan, pengeluaran, dan saldo.","Bendahara","Rekap bukti","Draf laporan","2 hari kerja"],["4","Pemeriksaan: Kabiro Keuangan memeriksa kecocokan laporan dengan buku kas dan mutasi rekening.","Kabiro Keuangan","Draf laporan","Catatan pemeriksaan","2 hari kerja"],["5","Pengesahan: Ketua pelaksana dan Kabiro Keuangan menandatangani laporan.","Ketua pelaksana dan Kabiro Keuangan","Laporan sesuai","Laporan keuangan disahkan","1 hari kerja"],["6","Penyerahan: Laporan diserahkan kepada Sekjen untuk digabung ke LPJ kegiatan dan kepada kampus atau sponsor bila diwajibkan.","Sekjen","Laporan disahkan","LPJ lengkap","Dalam batas 10 hari kerja"],["7","Arsip: Laporan dan lampiran diarsipkan; sisa dana diselesaikan sesuai SOP-KEU- 018.","Sekjen dan Bendahara","Laporan","Arsip lengkap","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Laporan keuangan kegiatan diselesaikan paling lambat 10 hari kerja setelah kegiatan selesai, kecuali kampus menetapkan lain. Hasil akhir: laporan keuangan yang sah, cocok dengan catatan, dan terlampir pada LPJ kegiatan."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Laporan terlambat: peringatan kepada ketua pelaksana; dana kegiatan berikutnya dapat ditahan.","Bukti hilang atau tidak lengkap: SOP-KEU-016 dan pernyataan tertulis; bila bernilai material, dilaporkan kepada Presiden.","Angka tidak cocok: SOP-KEU-017 dan SOP-KEU-018.","Dugaan manipulasi laporan: SOP-RSK-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% laporan keuangan selesai dalam 10 hari kerja.","100% angka laporan cocok dengan buku kas dan bukti.","Seluruh laporan disahkan Kabiro Keuangan sebelum diserahkan.","Tidak ada kegiatan baru tanpa penyelesaian laporan kegiatan sebelumnya."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan Keuangan Kegiatan.","Lampiran bukti.","Catatan pemeriksaan.","Arsip laporan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Biro Keuangan memantau ketepatan waktu laporan setiap bulan; MONEV memeriksa pertanggungjawaban keuangan sesuai SOP-MONEV-007."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tutup transaksi → Rekap bukti → Susun laporan → Periksa Kabiro Keuangan → Pengesahan → Serahkan ke LPJ → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Laporan Keuangan Kegiatan","Kegiatan; periode; anggaran; realisasi; selisih; pemasukan; pengeluaran; saldo; tanda tangan."],["Daftar Bukti Transaksi","Nomor; tanggal; uraian; nilai; pos anggaran; nomor bukti."],["Berita Acara Penutupan Transaksi","Kegiatan; tanggal; saldo; uang muka selesai; penutup."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh uang muka telah dipertanggungjawabkan.","☐ Ya ☐ Tidak"],["2","Angka cocok dengan buku kas dan mutasi rekening.","☐ Ya ☐ Tidak"],["3","Bukti lengkap dan sah.","☐ Ya ☐ Tidak"],["4","Selisih dijelaskan.","☐ Ya ☐ Tidak"],["5","Laporan disahkan dan diserahkan tepat waktu.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-016","g":"Keuangan dan Pengadaan","t":"Pemeriksaan Bukti Transaksi","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[224,227],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan standar dan prosedur pemeriksaan bukti transaksi keuangan, sehingga setiap pengeluaran dan pemasukan didukung bukti yang sah, lengkap, wajar, dan dapat ditelusuri."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pemeriksaan bukti atas pembayaran, uang muka, penggantian biaya, pembelian, dan pemasukan. SOP ini tidak mengatur pemeriksaan kegiatan oleh Inspektorat Jenderal secara menyeluruh (lihat SOP-MONEV-006 dan SOP-MONEV-007)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (3) (dokumentasi dengan bukti penerimaan resmi).","ART Pasal 3 (Kewajiban) huruf e dan g.","ART Pasal 11 huruf i dan j (larangan korupsi, manipulasi, penyelewengan dana, dan kecurangan).","SOP-KEU-006, SOP-KEU-007, SOP-KEU-008, dan SOP-MONEV-007."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Bukti sah","Dokumen yang memuat identitas penerbit, tanggal, uraian, jumlah, nilai, dan tanda tangan atau cap yang dapat diverifikasi."],["Bukti pendukung","Dokumen yang menguatkan terjadinya transaksi, seperti surat tugas, daftar hadir, foto, atau dokumentasi."],["Temuan","Ketidaksesuaian bukti dengan aturan atau fakta."],["Nota fiktif","Bukti yang tidak mencerminkan transaksi yang sebenarnya."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap transaksi wajib ada bukti asli yang sah; fotokopi hanya diterima dengan keterangan alasan dan persetujuan Kepala Biro Keuangan.","Syarat bukti pengeluaran: tanggal, nama dan identitas penyedia, uraian barang atau jasa, volume dan harga satuan, jumlah, bukti pembayaran, dan keterkaitan dengan kegiatan serta pos anggaran.","Kuitansi tanpa rincian, nota kosong, nota yang diubah, atau bukti yang tidak masuk akal ditolak.","Honor, konsumsi, dan transportasi dibuktikan dengan daftar penerima yang ditandatangani dan, bila perlu, dokumentasi.","Pemeriksa bukti tidak boleh pihak yang membuat atau menyetujui transaksi yang sama.","Temuan material diteruskan kepada Presiden dan Irjen tanpa ditunda."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Menetapkan hasil pemeriksaan bukti dan bertanggung jawab atas kelayakan bukti yang diterima."],["Pemeriksa bukti (staf Biro Keuangan)","R","Memeriksa bukti menggunakan checklist dan mencatat temuan."],["Bendahara","R","Menyerahkan bukti, menyimpan, dan melengkapi bukti yang kurang."],["Pengaju / Ketua pelaksana","R","Menyerahkan bukti asli dan penjelasan bila diminta."],["Inspektur Jenderal","C","Memeriksa sampel bukti secara independen."],["Presiden","I","Menerima laporan temuan material."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Bukti transaksi asli.","Anggaran yang disetujui dan permintaan pembayaran.","Buku kas dan mutasi rekening.","Checklist Pemeriksaan Bukti."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan bukti: Bendahara menyerahkan bukti beserta Permintaan atau Laporan terkait kepada pemeriksa bukti.","Bendahara","Bukti, dokumen terkait","Bukti diterima","Paling lambat 2 hari kerja setelah transaksi"],["2","Pemeriksaan kelengkapan: Pemeriksa memeriksa unsur wajib bukti dan keterkaitan dengan anggaran dan kegiatan.","Pemeriksa bukti","Bukti, checklist","Lengkap atau kurang","2 hari kerja"],["3","Pemeriksaan kewajaran: Pemeriksa membandingkan harga dengan daftar harga acuan atau penawaran serta memeriksa kecocokan dengan buku kas dan mutasi rekening.","Pemeriksa bukti","Daftar harga, buku kas","Wajar atau perlu klarifikasi","2 hari kerja"],["4","Klarifikasi: Bukti yang kurang atau meragukan dikembalikan kepada pengaju untuk dilengkapi atau dijelaskan secara tertulis.","Pengaju","Catatan pemeriksa","Bukti dilengkapi","3 hari kerja"],["5","Penetapan: Kabiro Keuangan menetapkan bukti diterima, diterima dengan catatan, atau ditolak, lalu membubuhkan paraf pemeriksaan.","Kabiro Keuangan","Hasil pemeriksaan","Status bukti","1 hari kerja"],["6","Pencatatan temuan: Temuan dicatat pada Register Temuan Bukti dan dilaporkan; temuan material diteruskan kepada Presiden dan Irjen.","Pemeriksa bukti","Temuan","Register temuan","1 hari kerja"],["7","Pengarsipan: Bukti yang diterima dijilid per kegiatan dan per bulan serta diarsipkan di repositori.","Bendahara dan Sekjen","Bukti diterima","Arsip bukti","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pemeriksaan bukti diselesaikan paling lambat 5 hari kerja sejak bukti diterima lengkap. Hasil akhir: bukti berstatus diterima atau ditolak dengan alasan, dan temuan tercatat."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Bukti tidak dapat dilengkapi: pengaju membuat pernyataan tertulis; penerimaan atau penolakan diputuskan Kabiro Keuangan, dan nilai material diputuskan Presiden.","Indikasi bukti fiktif atau manipulasi: dihentikan dan dilaporkan sesuai SOP-RSK-007.","Pemeriksa memiliki konflik kepentingan: pemeriksaan dialihkan kepada pemeriksa lain atau Irjen.","Perbedaan penilaian kewajaran: diputuskan Presiden."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% transaksi diperiksa buktinya sebelum diarsipkan.","Minimal 90% bukti selesai diperiksa dalam 5 hari kerja.","Tidak ada bukti yang diterima tanpa paraf pemeriksa.","Jumlah temuan berulang menurun dari bulan ke bulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Checklist Pemeriksaan Bukti.","Bukti yang telah diperiksa dan diparaf.","Register Temuan Bukti.","Arsip bukti transaksi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa sampel bukti dan Register Temuan Bukti setiap triwulan; temuan dibahas pada rapat evaluasi."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima bukti → Periksa kelengkapan → Periksa kewajaran → Klarifikasi bila perlu → Penetapan Kabiro Keuangan → Catat temuan → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Checklist Pemeriksaan Bukti","Unsur bukti; kelengkapan; kewajaran harga; kecocokan buku kas; paraf pemeriksa."],["Register Temuan Bukti","Nomor; tanggal; transaksi; temuan; tindak lanjut; status."],["Pernyataan Kehilangan Bukti","Transaksi; nilai; alasan; bukti pengganti; tanda tangan pengaju dan penyetuju."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Bukti asli, sah, dan memuat unsur wajib.","☐ Ya ☐ Tidak"],["2","Transaksi terkait anggaran dan kegiatan.","☐ Ya ☐ Tidak"],["3","Harga wajar dan sesuai acuan atau penawaran.","☐ Ya ☐ Tidak"],["4","Cocok dengan buku kas dan mutasi rekening.","☐ Ya ☐ Tidak"],["5","Pemeriksa bukan pihak yang menyetujui transaksi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-017","g":"Keuangan dan Pengadaan","t":"Rekonsiliasi Saldo dan Pemeriksaan Kas Berkala","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[228,231],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pencocokan buku kas, mutasi rekening, dan kas fisik secara berkala, sehingga saldo organisasi akurat, selisih cepat terdeteksi, dan dana terjaga dari kesalahan maupun penyalahgunaan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk rekening organisasi, kas kecil, dan buku kas BEM. SOP ini tidak mengatur penyelesaian selisih (lihat SOP-KEU-018) dan serah terima akhir (lihat SOP-KEU-020)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Kewajiban) huruf e dan g.","ART Pasal 10 ayat (4) huruf b (monitoring penggunaan anggaran dalam Rapat Koordinasi).","ART Pasal 12 (kewenangan Irjen dalam pengawasan dan evaluasi).","SOP-KEU-009 (Pengelolaan Kas dan Rekening) dan SOP-MONEV-007."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rekonsiliasi","Pencocokan saldo menurut buku kas dengan mutasi rekening dan kas fisik."],["Mutasi rekening","Daftar transaksi dan saldo pada rekening bank dalam periode tertentu."],["Opname kas","Penghitungan kas fisik pada waktu tertentu."],["Selisih","Perbedaan antara dua sumber data saldo."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Rekonsiliasi dilakukan setiap bulan (usulan) dan segera setelah transaksi besar; opname kas kecil dilakukan paling sedikit sekali sebulan, termasuk secara mendadak.","Rekonsiliasi dikerjakan oleh pihak selain yang melakukan transaksi dan diperiksa oleh Kepala Biro Keuangan; Irjen dapat menyaksikan atau memeriksa sampel secara triwulan.","Selisih dicatat tanpa ditutup-tutupi; tidak boleh ada penyesuaian tanpa bukti dan persetujuan.","Hasil rekonsiliasi dituangkan dalam berita acara yang ditandatangani pelaksana dan pemeriksa.","Hasil rekonsiliasi dilaporkan kepada Presiden dan dibahas pada rapat kabinet."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Memastikan rekonsiliasi terlaksana tepat waktu dan menandatangani berita acara."],["Pelaksana rekonsiliasi (staf Biro Keuangan)","R","Mencocokkan buku kas, mutasi, dan kas fisik, serta menyusun berita acara."],["Bendahara","R","Menyerahkan buku kas, bukti, dan kas untuk diperiksa."],["Inspektur Jenderal","C","Menyaksikan atau memeriksa rekonsiliasi pada sampel."],["Presiden","I","Menerima laporan hasil rekonsiliasi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Buku kas bulanan.","Mutasi rekening dari bank.","Kas fisik dan bukti kas kecil.","Daftar transaksi dalam proses."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Persiapan: Pelaksana mengumpulkan buku kas, mutasi rekening periode berjalan, dan bukti transaksi.","Pelaksana rekonsiliasi","Buku kas, mutasi","Data siap","3 hari kerja pertama setiap bulan"],["2","Pencocokan rekening: Saldo dan transaksi buku kas dicocokkan dengan mutasi rekening; transaksi dalam proses dicatat.","Pelaksana rekonsiliasi","Buku kas, mutasi","Daftar selisih","2 hari kerja"],["3","Opname kas: Kas kecil dihitung bersama Bendahara dan dicocokkan dengan buku dan bukti.","Pelaksana dan Bendahara","Kas fisik","Hasil opname","1 hari kerja"],["4","Analisis selisih: Setiap selisih dijelaskan penyebabnya; selisih yang tidak dapat dijelaskan ditandai.","Pelaksana rekonsiliasi","Daftar selisih","Analisis selisih","2 hari kerja"],["5","Pembuatan berita acara: Hasil dituangkan pada Berita Acara Rekonsiliasi dan Opname Kas yang ditandatangani pelaksana, Bendahara, dan Kabiro Keuangan.","Kabiro Keuangan","Analisis","Berita acara","1 hari kerja"],["6","Tindak lanjut: Selisih diselesaikan melalui SOP- KEU-018; koreksi pencatatan dilakukan dengan persetujuan dan bukti.","Kabiro Keuangan","Berita acara","Selisih ditindaklanjuti","3 hari kerja"],["7","Pelaporan: Hasil dilaporkan kepada Presiden dan pada rapat kabinet; salinan kepada Irjen.","Kabiro Keuangan","Berita acara","Laporan rekonsiliasi","Pekan pertama bulan berikutnya"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Rekonsiliasi bulanan diselesaikan paling lambat 10 hari kerja pertama bulan berikutnya. Hasil akhir: berita acara rekonsiliasi dan opname kas dengan selisih yang dijelaskan atau ditindaklanjuti."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Selisih tidak dapat dijelaskan dalam 5 hari kerja: dilaporkan kepada Presiden dan Irjen serta SOP- KEU-018.","Indikasi penyalahgunaan: SOP-RSK-007.","Bank belum menyediakan mutasi: rekonsiliasi dilakukan sementara dan dilengkapi setelah mutasi tersedia.","Pelaksana berhalangan: Kabiro Keuangan menunjuk pengganti yang bukan pelaksana transaksi."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% bulan memiliki berita acara rekonsiliasi.","Opname kas kecil dilakukan sedikitnya sekali sebulan.","Selisih yang tidak terjelaskan selesai dalam batas waktu.","Tidak ada koreksi tanpa bukti dan persetujuan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Berita Acara Rekonsiliasi dan Opname Kas.","Daftar selisih dan tindak lanjutnya.","Laporan kepada Presiden.","Arsip mutasi rekening bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa berita acara dan menyaksikan opname secara berkala; kepatuhan jadwal dipantau Sekretaris Jenderal melalui kalender organisasi."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Siapkan data → Cocokkan buku kas dan mutasi → Opname kas → Analisis selisih → Berita acara → Tindak lanjut → Laporan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Berita Acara Rekonsiliasi dan Opname Kas","Periode; saldo buku; saldo bank; kas fisik; selisih; penjelasan; tanda tangan."],["Daftar Transaksi Dalam Proses","Tanggal; uraian; nilai; alasan tertunda; perkiraan selesai."],["Laporan Rekonsiliasi Bulanan","Ringkasan saldo; selisih; tindak lanjut; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Buku kas dan mutasi periode lengkap.","☐ Ya ☐ Tidak"],["2","Kas kecil dihitung dan dicocokkan.","☐ Ya ☐ Tidak"],["3","Setiap selisih dijelaskan atau ditandai.","☐ Ya ☐ Tidak"],["4","Berita acara ditandatangani pihak yang berwenang.","☐ Ya ☐ Tidak"],["5","Hasil dilaporkan tepat waktu.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-018","g":"Keuangan dan Pengadaan","t":"Penanganan Kelebihan atau Kekurangan Dana","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[232,235],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyelesaian kelebihan atau kekurangan dana pada kegiatan, uang muka, kas, maupun sumber dana eksternal, sehingga setiap selisih diselesaikan secara jujur, sesuai tujuan dana, dan tercatat."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk sisa dana kegiatan, kekurangan dana kegiatan, selisih kas hasil rekonsiliasi, serta sisa dana terikat dari sponsor, donasi, atau kampus. SOP ini tidak mengatur dugaan penyalahgunaan (lihat SOP-RSK- 007)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf b dan ayat (3).","ART Pasal 3 (Kewajiban) huruf e dan g.","ART Pasal 11 huruf i dan k.","SOP-KEU-007, SOP-KEU-012, SOP-KEU-013, SOP-KEU-014, dan SOP-KEU-017."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kelebihan dana","Dana tersisa setelah kegiatan atau pekerjaan selesai dan seluruh kewajiban terpenuhi."],["Kekurangan dana","Kebutuhan biaya yang tidak tertutup dana yang tersedia."],["Selisih kas","Perbedaan antara kas atau saldo menurut catatan dan kenyataan."],["Dana terikat","Dana yang hanya boleh dipakai untuk tujuan tertentu."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kelebihan dana dari dana BEM disetorkan ke kas organisasi paling lambat 3 hari kerja setelah laporan kegiatan; dari dana kampus dikembalikan atau dipakai sesuai ketentuan kampus.","Kelebihan dari sponsor atau donatur dikembalikan, dialihkan, atau dipakai sesuai perjanjian atau persetujuan tertulis pemberi.","Kekurangan dana ditutup melalui realokasi atau pos biaya tak terduga (SOP-KEU-014); kekurangan tidak boleh ditutup dengan utang berbunga atau dana pribadi tanpa pencatatan.","Selisih kas yang tidak jelas penyebabnya tidak boleh dihapus tanpa pemeriksaan; diselesaikan sesuai tingkat selisih dan hasil penelusuran.","Pengurus tidak boleh menyimpan sisa dana secara pribadi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Memutuskan penyelesaian sesuai kewenangan dan bertanggung jawab atas ketepatan pencatatan."],["Bendahara","R","Menerima sisa dana, mencatat, dan menyiapkan penyelesaian."],["Ketua pelaksana","R","Melaporkan sisa atau kekurangan dan mengembalikan sisa dana."],["Presiden","C","Memutuskan penyelesaian untuk nilai besar, selisih tak jelas, atau perubahan tujuan."],["Inspektur Jenderal","C","Meninjau penyelesaian selisih yang signifikan."],["Donatur / sponsor / KAUR ORMAWA","I","Menyetujui penyelesaian sesuai kewenangan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan keuangan kegiatan.","Berita acara rekonsiliasi.","Perjanjian atau persetujuan pemberi dana.","Daftar kewajiban yang tertunda."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Identifikasi: Bendahara menghitung kelebihan atau kekurangan berdasarkan laporan keuangan atau rekonsiliasi.","Bendahara","Laporan, rekonsiliasi","Nilai selisih","2 hari kerja"],["2","Klasifikasi: Selisih diklasifikasikan: sisa dana, kekurangan, atau selisih kas, serta sumber dan statusnya (terikat atau tidak).","Bendahara","Selisih","Klasifikasi selisih","1 hari kerja"],["3","Penelusuran: Penyebab ditelusuri dengan bukti; selisih yang tidak jelas dibahas dengan Kabiro Keuangan.","Kabiro Keuangan","Bukti","Penyebab teridentifikasi","3 hari kerja"],["4","Usulan penyelesaian: Disusun: setor ke kas, pengembalian kepada pemberi, pengalihan dengan persetujuan, atau pembiayaan kekurangan.","Kabiro Keuangan","Hasil penelusuran","Usulan penyelesaian","2 hari kerja"],["5","Persetujuan: Usulan disetujui Kabiro Keuangan (di bawah Rp500.000) atau Presiden (di atasnya); yang menyangkut pemberi dana mengikuti persetujuan pemberi.","Presiden / Kabiro Keuangan","Usulan","Keputusan","2 hari kerja"],["6","Pelaksanaan: Bendahara melaksanakan setoran, pengembalian, atau pembayaran sesuai keputusan dan mencatatnya.","Bendahara","Keputusan","Selisih diselesaikan","3 hari kerja"],["7","Penutupan: Berita acara penyelesaian dibuat dan diarsipkan; dilaporkan dalam laporan kegiatan atau rapat kabinet.","Bendahara dan Sekjen","Bukti penyelesaian","Selisih ditutup","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penyelesaian ditargetkan paling lambat 12 hari kerja sejak selisih teridentifikasi, kecuali menunggu persetujuan pihak luar. Hasil akhir: selisih diselesaikan, dicatat, dan dilaporkan."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Selisih tidak terjelaskan: dilaporkan kepada Presiden dan Irjen; bila terdapat indikasi pelanggaran, SOP-RSK-007.","Pemberi dana tidak dapat dihubungi: dana tetap dicatat sebagai dana terikat sampai ada keputusan Presiden dengan konsultasi KAUR ORMAWA.","Kekurangan besar: dibahas pada Rapat Pimpinan (SOP-GOV-005) dan SOP-KEU-014.","Pihak yang menahan sisa dana: peringatan sesuai ART Pasal 12 dan SOP-KEU-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% sisa dana disetor atau dikembalikan dalam batas waktu.","100% selisih kas memiliki penjelasan atau tindak lanjut tercatat.","Tidak ada dana yang disimpan pribadi.","Sisa dana terikat selalu diselesaikan sesuai tujuan atau persetujuan pemberi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Berita Acara Penyelesaian Selisih Dana.","Bukti setoran atau pengembalian.","Persetujuan pemberi dana, bila ada.","Catatan buku kas dan laporan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Keuangan melaporkan selisih yang belum diselesaikan pada rapat kabinet; Irjen memeriksa penyelesaian selisih material."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Identifikasi selisih → Klasifikasi → Penelusuran → Usulan penyelesaian → Persetujuan → Pelaksanaan → Penutupan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Berita Acara Penyelesaian Selisih Dana","Kegiatan atau sumber; jenis selisih; nilai; penyebab; penyelesaian; persetujuan; tanda tangan."],["Formulir Pengembalian Sisa Dana","Kegiatan; sumber; nilai; penerima; bukti setoran."],["Register Selisih Dana","Nomor; tanggal; jenis; nilai; status; tanggal selesai."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Selisih dihitung dan diklasifikasikan.","☐ Ya ☐ Tidak"],["2","Penyebab ditelusuri dan terdokumentasi.","☐ Ya ☐ Tidak"],["3","Penyelesaian sesuai tujuan dana dan persetujuan pemberi.","☐ Ya ☐ Tidak"],["4","Persetujuan sesuai tingkat nilai.","☐ Ya ☐ Tidak"],["5","Setoran atau pengembalian dicatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-019","g":"Keuangan dan Pengadaan","t":"Pengelolaan Utang dan Kewajiban Organisasi","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[236,239],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pencatatan, pembatasan, dan penyelesaian utang serta kewajiban keuangan organisasi, sehingga BEM tidak terjerat kewajiban berbunga atau yang melampaui satu periode kepengurusan dan seluruh kewajiban diselesaikan tepat waktu."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk tagihan penyedia yang belum dibayar, pembayaran bertahap, talangan pengurus, uang muka dari pihak ketiga, dan kewajiban lain yang timbul dari kegiatan. SOP ini tidak mengatur penggantian biaya (lihat SOP-KEU-008)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf b (tidak menimbulkan kewajiban melampaui satu periode kepengurusan) dan ayat (2) (bebas riba, gharar, dan maysir).","ART Pasal 3 (Kewajiban) huruf e.","ART Pasal 11 huruf i dan k.","SOP-KEU-006, SOP-KEU-008, SOP-KEU-017, dan SOP-KEU-020."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Utang atau kewajiban","Dana yang harus dibayar organisasi kepada pihak lain atas barang, jasa, atau talangan yang telah diterima."],["Jatuh tempo","Batas waktu pembayaran kewajiban."],["Pembayaran bertahap","Pembayaran yang dibagi menjadi beberapa tahap berdasarkan kesepakatan tertulis."],["Register Kewajiban","Daftar semua kewajiban beserta nilai, pihak, dan jatuh tempo."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["BEM tidak mengambil pinjaman berbunga atau dengan unsur riba, gharar, atau maysir; kewajiban hanya timbul dari transaksi yang sah dan dianggarkan.","Tidak ada kewajiban yang jatuh tempo atau mengikat melampaui masa kepengurusan; sisa kewajiban wajib diselesaikan sebelum serah terima (SOP-KEU-020).","Pembelian dengan pembayaran tertunda atau bertahap harus dengan persetujuan tertulis Presiden dan tidak boleh melebihi anggaran yang disetujui.","Setiap kewajiban dicatat pada Register Kewajiban sejak timbul, lengkap dengan bukti dan jatuh tempo.","Pembayaran kewajiban diprioritaskan menurut jatuh tempo dan kewajiban kepada pihak luar; keterlambatan tidak boleh dikenai bunga atau denda ribawi.","Talangan pengurus bersifat sukarela, tidak berbunga, dan diganti sesuai SOP-KEU-008."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menyetujui kewajiban bertahap dan menetapkan prioritas pembayaran; bertanggung jawab akhir atas posisi kewajiban."],["Kepala Biro Keuangan","R","Memelihara Register Kewajiban, memantau jatuh tempo, dan menyusun rencana pelunasan."],["Bendahara","R","Membayar kewajiban dan memperbarui register."],["Ketua pelaksana","R","Melaporkan tagihan yang timbul dari kegiatan."],["Inspektur Jenderal","C","Memeriksa kewajaran dan kelengkapan Register Kewajiban."],["Pihak yang ditagih / penagih","I","Menerima kepastian pembayaran dan bukti pelunasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Tagihan atau perjanjian pembayaran.","Anggaran dan saldo kas.","Bukti penerimaan barang atau jasa.","Register Kewajiban."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pencatatan: Setiap tagihan atau kewajiban baru dicatat pada Register Kewajiban dengan pihak, nilai, dasar, dan jatuh tempo.","Bendahara","Tagihan, bukti","Kewajiban tercatat","1 hari kerja"],["2","Verifikasi: Biro Keuangan memeriksa kebenaran tagihan, kesesuaian anggaran, dan kehalalan akad.","Kabiro Keuangan","Tagihan, perjanjian","Kewajiban sah","2 hari kerja"],["3","Persetujuan pembayaran bertahap: Bila kewajiban tidak dapat dibayar sekaligus, rencana pembayaran tertulis diajukan dan disetujui Presiden.","Presiden","Rencana pelunasan","Persetujuan pembayaran bertahap","3 hari kerja"],["4","Penjadwalan: Biro Keuangan menyusun jadwal pelunasan menurut jatuh tempo dan saldo kas.","Kabiro Keuangan","Register, saldo kas","Jadwal pelunasan","Setiap minggu"],["5","Pembayaran: Pembayaran dilakukan melalui SOP- KEU-006 dan bukti pelunasan diminta dari penerima.","Bendahara","Jadwal, persetujuan","Kewajiban lunas","Sebelum jatuh tempo"],["6","Pemantauan: Register ditinjau setiap bulan dan kewajiban yang akan jatuh tempo atau tertunggak dilaporkan pada rapat kabinet.","Kabiro Keuangan","Register","Laporan kewajiban","Setiap bulan"],["7","Penutupan akhir periode: Menjelang akhir periode, seluruh kewajiban diselesaikan atau dicatat dalam serah terima sesuai SOP-KEU- 020.","Presiden dan Kabiro Keuangan","Register","Kewajiban selesai atau diserahterimakan","30 hari sebelum akhir periode"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pencatatan paling lambat 1 hari kerja sejak kewajiban timbul; pelunasan sebelum jatuh tempo. Hasil akhir: seluruh kewajiban tercatat, terkendali, dan lunas pada akhir periode."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kas tidak cukup untuk jatuh tempo: Presiden menetapkan prioritas dan menegosiasikan jadwal baru tanpa bunga.","Penagih menuntut bunga atau denda ribawi: ditolak dan dikonsultasikan dengan Presiden serta, bila perlu, Pembina.","Kewajiban melampaui periode: tidak boleh; solusi dibahas dengan KAUR ORMAWA.","Kewajiban tanpa dasar jelas: SOP-RSK-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kewajiban tercatat pada register.","Minimal 90% kewajiban lunas sebelum jatuh tempo.","Tidak ada kewajiban berbunga atau yang melampaui periode.","Kewajiban akhir periode nol atau tercatat dalam serah terima."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Kewajiban.","Persetujuan pembayaran bertahap.","Jadwal pelunasan dan bukti pelunasan.","Laporan kewajiban bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Keuangan menyandingkan Register Kewajiban dengan buku kas setiap bulan; Irjen memeriksa kelengkapan register secara berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Catat kewajiban → Verifikasi tagihan → Persetujuan bertahap bila perlu → Jadwal pelunasan → Bayar → Pantau → Selesaikan akhir periode → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Register Kewajiban","Nomor; pihak; dasar; nilai; tanggal timbul; jatuh tempo; status; bukti pelunasan."],["Formulir Rencana Pembayaran Bertahap","Kewajiban; nilai; tahap; tanggal; sumber dana; persetujuan."],["Surat Konfirmasi Pelunasan","Pihak; nilai; tanggal; tanda tangan penerima."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kewajiban tercatat dengan bukti dan jatuh tempo.","☐ Ya ☐ Tidak"],["2","Tidak ada bunga atau unsur riba.","☐ Ya ☐ Tidak"],["3","Persetujuan Presiden untuk pembayaran bertahap.","☐ Ya ☐ Tidak"],["4","Kewajiban tidak melampaui satu periode.","☐ Ya ☐ Tidak"],["5","Pelunasan memiliki bukti.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KEU-020","g":"Keuangan dan Pengadaan","t":"Pemeriksaan dan Serah Terima Keuangan Akhir Kabinet","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[240,243],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pemeriksaan keuangan akhir dan serah terima seluruh dana, rekening, dokumen keuangan, dan kewajiban dari Kabinet Samasta kepada kabinet berikutnya, sehingga transisi keuangan jelas, akuntabel, dan tidak meninggalkan masalah bagi pengurus baru."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk Presiden, Kepala Biro Keuangan, Bendahara, Sekretaris Jenderal, Inspektur Jenderal, dan seluruh unit yang memegang dana atau dokumen keuangan pada akhir masa jabatan. SOP ini adalah rincian bagian keuangan dari serah terima kabinet (SOP-TRN-004) dan tidak mengatur serah terima jabatan pimpinan (SOP-TRN-002)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) sampai (3) (laporan pertanggungjawaban kepada BPM, pembahasan dalam Musyawarah Besar, dan pelaporan kepada KAUR ORMAWA).","ART Bab III (Tugas) huruf e (laporan pertanggungjawaban anggaran dan program pada akhir masa jabatan).","ART Pasal 3 (Kewajiban) huruf e dan g.","ART Pasal 7 (Musyawarah BEM) dan ART Pasal 12 (Irjen).","SOP-KEU-009, SOP-KEU-017, SOP-KEU-018, SOP-KEU-019, SOP-AST-011, dan SOP-TRN-004."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pemeriksaan akhir","Pemeriksaan menyeluruh atas saldo, bukti, kewajiban, dan laporan keuangan pada akhir periode."],["Berita Acara Serah Terima Keuangan","Dokumen resmi penyerahan dana, rekening, dokumen, dan kewajiban kepada penerima."],["LPJ akhir","Laporan pertanggungjawaban keuangan dan program kabinet pada akhir masa jabatan."],["Penerima serah terima","Pejabat yang ditetapkan kabinet berikutnya untuk menerima tanggung jawab keuangan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pemeriksaan akhir dimulai paling lambat 30 hari sebelum akhir masa jabatan (usulan) dan harus selesai sebelum serah terima.","Serah terima tidak dapat dilakukan sebelum rekonsiliasi akhir, penyelesaian uang muka, dan penyelesaian atau pencatatan seluruh kewajiban.","Dana, rekening, buku kas, bukti, register, dan akses perbankan diserahkan lengkap; penandatangan rekening diganti kepada pengurus baru dengan berita acara.","LPJ akhir disampaikan kepada BPM untuk dibahas dalam Musyawarah Besar dan hasilnya dilaporkan kepada KAUR ORMAWA (AD Pasal 17 ayat 3).","Pengurus lama tetap bertanggung jawab atas keuangan periodenya sampai LPJ diterima atau ditetapkan.","Pemeriksaan akhir juga mencakup sisa dana terikat, aset yang dibeli, dan kewajiban kepada sponsor atau penyedia."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menyetujui hasil pemeriksaan akhir dan menandatangani berita acara serah terima keuangan."],["Kepala Biro Keuangan","R","Memimpin pemeriksaan akhir, menyiapkan laporan, dan menyerahkan dokumen serta dana kepada penerima."],["Bendahara","R","Menyerahkan kas, buku kas, bukti, dan akses; melunasi atau menyerahkan catatan kewajiban."],["Inspektur Jenderal","R","Memeriksa laporan dan saldo akhir secara independen dan menyampaikan hasil."],["Sekretaris Jenderal","R","Menyusun berita acara, mengarsipkan, dan mengoordinasikan serah terima dokumen."],["Penerima serah terima","C","Memeriksa dan menerima dana, dokumen, rekening, dan catatan kewajiban."],["BPM dan KAUR ORMAWA","I","Menerima LPJ akhir dan laporan hasil pembahasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Buku kas dan mutasi rekening seluruh periode.","Register Kewajiban, Register Uang Muka, dan Register Sponsor dan Dana Eksternal.","Laporan keuangan seluruh kegiatan.","Daftar aset dan kode akses keuangan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan jadwal: Presiden menetapkan jadwal pemeriksaan dan serah terima keuangan beserta pejabat penerima setelah berkoordinasi dengan kabinet berikutnya.","Presiden","Kalender periode","Jadwal ditetapkan","30 hari sebelum akhir periode"],["2","Penyelesaian pekerjaan keuangan: Seluruh uang muka dipertanggungjawabkan, penggantian dibayar, dan kewajiban dilunasi atau dicatat (SOP-KEU-007, SOP-KEU- 008, SOP-KEU-019).","Kabiro Keuangan dan Bendahara","Register","Pekerjaan selesai","14 hari kerja"],["3","Rekonsiliasi akhir: Rekonsiliasi dan opname kas akhir dilakukan sesuai SOP-KEU-017; selisih diselesaikan sesuai SOP-KEU- 018.","Kabiro Keuangan","Buku kas, mutasi","Berita acara rekonsiliasi akhir","5 hari kerja"],["4","Penyusunan laporan akhir: Laporan keuangan periode dan LPJ akhir disusun dengan seluruh lampiran bukti.","Kabiro Keuangan","Laporan kegiatan","LPJ keuangan akhir","7 hari kerja"],["5","Pemeriksaan Irjen: Irjen memeriksa laporan, saldo, dan kelengkapan dokumen serta menyampaikan hasil tertulis.","Irjen","LPJ, berita acara","Hasil pemeriksaan Irjen","5 hari kerja"],["6","Pengesahan dan penyerahan LPJ: Presiden menyetujui laporan, lalu LPJ diserahkan kepada BPM untuk dibahas dan dilaporkan kepada KAUR ORMAWA sesuai AD Pasal 17.","Presiden dan Sekjen","Hasil Irjen","LPJ diserahkan","Sesuai jadwal Musyawarah Besar"],["7","Serah terima: Dana, rekening, penandatangan, dokumen, register, dan akses diserahkan kepada penerima dengan Berita Acara Serah Terima Keuangan.","Presiden, Kabiro Keuangan, penerima","Berkas serah terima","Berita acara serah terima","3 hari kerja"],["8","Arsip dan tindak lanjut: Berita acara dan salinan dokumen diarsipkan; catatan pembelajaran keuangan dimasukkan dalam laporan akhir kabinet.","Sekjen","Berita acara","Arsip transisi","5 hari kerja setelah serah terima"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Seluruh proses dari penetapan jadwal sampai serah terima ditargetkan selesai sebelum masa jabatan berakhir; LPJ akhir disampaikan sesuai jadwal Musyawarah Besar. Hasil akhir: Berita Acara Serah Terima Keuangan dan LPJ keuangan akhir."},{"note":"Catatan: angka waktu, batas nominal, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Selisih tidak terselesaikan: dicatat dalam berita acara dan dilaporkan kepada Irjen, KAUR ORMAWA, dan penerima; penelusuran lanjutan sesuai SOP-RSK-007.","Penerima serah terima belum ditetapkan: dana dan dokumen dititipkan sesuai arahan KAUR ORMAWA dan dicatat.","Kewajiban melampaui periode: tidak dibenarkan; dikonsultasikan dengan KAUR ORMAWA.","Perselisihan hasil serah terima: dibawa kepada Pembina atau KAUR ORMAWA."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% dana, rekening, dokumen, dan kewajiban tercatat dalam berita acara serah terima.","Tidak ada kewajiban tanpa pencatatan pada akhir periode.","LPJ keuangan akhir tersedia sebelum Musyawarah Besar.","Tidak ada temuan Irjen yang belum ditindaklanjuti saat serah terima."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Berita Acara Serah Terima Keuangan.","LPJ keuangan akhir dan hasil pemeriksaan Irjen.","Berita acara rekonsiliasi akhir.","Dokumen keuangan dan register lengkap, serta bukti pergantian penandatangan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Sekretaris Jenderal bersama Biro Keuangan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memantau kepatuhan jadwal; Irjen memeriksa kelengkapan serah terima; kabinet berikutnya memverifikasi dalam 14 hari kerja setelah serah terima."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tetapkan jadwal → Selesaikan uang muka dan kewajiban → Rekonsiliasi akhir → Susun LPJ akhir → Periksa Irjen → Pengesahan dan LPJ ke BPM → Serah terima → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Berita Acara Serah Terima Keuangan","Pihak; saldo rekening dan kas; dokumen; register; kewajiban; akses; catatan; tanda tangan."],["Daftar Periksa Serah Terima Keuangan","Dana; rekening; buku kas; bukti; register; kewajiban; akses; aset."],["Templat LPJ Keuangan Akhir Kabinet","Ringkasan anggaran dan realisasi; pemasukan; pengeluaran; saldo; kewajiban; temuan; pembelajaran."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Rekonsiliasi akhir dan opname kas selesai.","☐ Ya ☐ Tidak"],["2","Uang muka dan penggantian telah selesai.","☐ Ya ☐ Tidak"],["3","Kewajiban lunas atau tercatat lengkap.","☐ Ya ☐ Tidak"],["4","Penandatangan rekening dan akses telah diganti.","☐ Ya ☐ Tidak"],["5","LPJ akhir diperiksa Irjen dan diserahkan sesuai AD Pasal 17.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan dan Bendahara; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-RSK-001","g":"Risiko, Etika, dan Penanganan Masalah","t":"Identifikasi dan Pencatatan Risiko Organisasi","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[248,252],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur identifikasi, penilaian awal, pencatatan, penunjukan pemilik, dan peninjauan berkala risiko organisasi pada Register Risiko, sehingga ancaman terhadap keselamatan, keuangan, nama baik, kepatuhan terhadap AD/ART dan aturan kampus, data, serta keberlanjutan program dapat dikenali sejak dini dan memiliki penanggung jawab pengendalian."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus BEM Kabinet Samasta dalam mengidentifikasi risiko pada tingkat organisasi: kabinet, kementerian, biro, dan program kerja tahunan. SOP ini tidak mengatur penilaian risiko satu kegiatan tertentu (lihat SOP-RSK-002) dan tidak mengatur penanganan insiden yang sudah terjadi (lihat SOP-RSK-003 sampai SOP-RSK-012)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Kewajiban) huruf d, e, dan h (menjaga nama baik, mengelola keuangan secara amanah, mematuhi peraturan kampus).","ART Pasal 9 ayat (3) (agenda Rapat Kerja: anggaran biaya, pembagian tugas, target capaian).","ART Pasal 10 ayat (4) (Rapat Koordinasi: monitoring anggaran dan penyelesaian permasalahan internal).","ART Pasal 12 ayat (3) dan (4) (pengawasan Irjen dalam rangka pembinaan organisasi dan pencegahan pelanggaran).","Pedoman Penyusunan SOP BEM Kabinet Baru, Bagian VII (Register risiko)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Risiko","Kemungkinan terjadinya kejadian yang berdampak negatif pada tujuan, keselamatan, keuangan, nama baik, atau kelangsungan organisasi."],["Register Risiko","Dokumen yang mencatat risiko, penilaian, pengendalian, pemilik risiko, tenggat, dan status."],["Pemilik risiko","Pengurus yang bertanggung jawab memantau dan mengendalikan satu risiko tertentu."],["Tingkat risiko","Hasil kali kemungkinan dan dampak (skala 1 sampai 3): rendah (1-2), sedang (3-4), tinggi (6-9). Angka merupakan usulan."],["Pengendalian","Tindakan untuk mencegah atau mengurangi kemungkinan maupun dampak suatu risiko."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kategori risiko: keselamatan dan kesehatan; keuangan dan aset; nama baik dan etika; kepatuhan (AD/ART, aturan kampus, syariat); data dan digital; sumber daya manusia dan keberlanjutan; operasional program.","Setiap risiko sedang dan tinggi wajib memiliki pemilik risiko, tindakan pengendalian, dan tenggat.","Risiko tinggi dilaporkan pada Rapat Pimpinan (SOP-GOV-005) paling lambat 2 hari kerja setelah ditetapkan.","Register ditinjau paling sedikit sekali sebulan dan diperbarui bila struktur berubah, program besar disahkan, atau insiden terjadi (SOP-RSK-012).","Register tidak memuat identitas orang atau rincian kasus sensitif; cukup kode rujukan ke berkas terbatas (SOP-RSK-010).","Mengidentifikasi risiko bukan mencari kesalahan orang. Pelaporan risiko dengan itikad baik tidak dikenai sanksi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan Register Risiko dan prioritas pengendalian."],["Wakil Presiden","R","Mengoordinasikan Eksekutif dalam mengidentifikasi dan mengendalikan risiko."],["Sekretaris Jenderal","R","Menyiapkan formulir, menyusun dan memelihara Register Risiko, serta memantau tindak lanjut."],["Menteri / Kabiro","R","Mengidentifikasi dan menilai risiko unit, serta menjalankan pengendalian."],["Seluruh pengurus","R","Melaporkan risiko yang ditemukan melalui kanal resmi."],["Inspektur Jenderal","C","Menelaah kelengkapan dan kewajaran penilaian serta memeriksa tindak lanjut."],["Biro Keuangan","C","Memberi masukan risiko keuangan dan aset."],["Pembina / KAUR ORMAWA","I","Diberi ringkasan risiko tinggi yang menyangkut institusi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["AD/ART dan peraturan kampus.","Program kerja dan anggaran hasil Rapat Kerja.","Catatan insiden (SOP-RSK-012) serta temuan Irjen dan hasil evaluasi.","Formulir Identifikasi Risiko dari setiap unit.","Arsip risiko kabinet sebelumnya (bila ada)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Persiapan: Menyiapkan Formulir Identifikasi Risiko dan menjadwalkan sesi identifikasi singkat bersama seluruh unit.","Sekjen","Struktur kabinet, program kerja","Formulir dan jadwal sesi","5 hari kerja setelah program kerja disahkan"],["2","Identifikasi unit: Menginventarisasi hal yang dapat menghambat atau merugikan: penyebab, dampak, dan pihak terdampak untuk setiap program dan tugas unit.","Menteri / Kabiro","Program kerja, formulir","Formulir terisi","5 hari kerja"],["3","Penilaian awal: Menggabungkan usulan, menghapus duplikasi, menetapkan kategori, serta menilai kemungkinan dan dampak sehingga tingkat risiko diketahui.","Sekjen bersama Wapres","Formulir terisi","Draf Register Risiko","3 hari kerja"],["4","Telaah Irjen: Memeriksa kelengkapan, kewajaran penilaian, dan risiko yang terlewat; memberi catatan tertulis.","Irjen","Draf register","Catatan telaah","2 hari kerja"],["5","Penetapan: Membahas risiko sedang dan tinggi pada Rapat Pimpinan, menetapkan pemilik risiko, pengendalian, dan tenggat; Presiden menetapkan register.","Presiden bersama pimpinan","Draf register, catatan Irjen","Register Risiko ditetapkan","1 kali rapat"],["6","Sosialisasi dan arsip: Membagikan ringkasan risiko kepada pemilik risiko, menyimpan register di repositori, dan mencatat pada Register Dokumen.","Sekjen","Register ditetapkan","Distribusi tercatat, arsip","3 hari kerja setelah penetapan"],["7","Pemantauan: Memperbarui status pengendalian; Sekjen mengingatkan pembaruan yang terlambat.","Pemilik risiko, Sekjen","Register","Register terbarui","Setiap bulan"],["8","Peninjauan berkala: Menambah risiko baru, menutup risiko yang tidak relevan beserta alasannya, dan melaporkan risiko tinggi pada Rapat Kabinet.","Sekjen dan Irjen","Register, catatan insiden, hasil evaluasi","Register revisi, laporan","Setiap bulan; tinjauan penuh pada evaluasi tengah periode"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Register Risiko awal ditargetkan ditetapkan paling lambat 15 hari kerja setelah program kerja disahkan (usulan). Hasil akhir: Register Risiko yang ditetapkan beserta daftar pemilik risiko dan rencana pengendalian."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Risiko tinggi yang mendesak dan tidak dapat menunggu jadwal: disampaikan langsung kepada Presiden melalui Sekjen dan diputuskan sesuai SOP-GOV-012.","Perbedaan penilaian antara unit dan Sekjen: diputuskan Wakil Presiden (SOP-GOV-004); bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Risiko yang berasal dari dugaan pelanggaran: ditangani melalui SOP-RSK-004.","Risiko yang melampaui kewenangan BEM atau menyangkut institusi: Presiden menyampaikan kepada KAUR ORMAWA atau Pembina."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% program kerja utama memiliki risiko yang teridentifikasi.","100% risiko sedang dan tinggi memiliki pemilik, pengendalian, dan tenggat.","Register diperbarui paling sedikit sekali setiap bulan.","Insiden berat yang risikonya belum tercatat sebelumnya semakin berkurang."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Identifikasi Risiko.","Register Risiko versi terkini.","Catatan telaah Irjen dan notulen Rapat Pimpinan.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Risiko dan Etika) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa Register setiap bulan untuk memastikan tidak ada risiko tinggi tanpa pemilik, lalu melaporkan hasilnya pada Rapat Kabinet; Sekretaris Jenderal memeriksa ketersediaan versi terkini."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Persiapan → Identifikasi unit → Penilaian awal → Telaah Irjen → Penetapan Presiden → Sosialisasi dan arsip → Pemantauan bulanan → Peninjauan berkala → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Identifikasi Risiko","Unit; pelapor; uraian risiko; penyebab; dampak; kategori; kemungkinan; dampak; usulan pengendalian; tanggal."],["Templat Register Risiko","Nomor risiko; kategori; uraian; kemungkinan; dampak; tingkat; pengendalian; pemilik; tenggat; status; tanggal tinjau."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh program kerja utama telah ditelaah risikonya.","☐ Ya ☐ Tidak"],["2","Risiko sedang dan tinggi memiliki pemilik, pengendalian, dan tenggat.","☐ Ya ☐ Tidak"],["3","Telaah Irjen terdokumentasi.","☐ Ya ☐ Tidak"],["4","Register tidak memuat identitas atau rincian kasus sensitif.","☐ Ya ☐ Tidak"],["5","Versi register terkini tersimpan dan tercatat pada Register Dokumen.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta.."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-RSK-002","g":"Risiko, Etika, dan Penanganan Masalah","t":"Penilaian Risiko Sebelum Kegiatan","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[253,256],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur menilai risiko kegiatan sebelum disetujui dan dilaksanakan, sehingga keselamatan peserta, keuangan, nama baik, dan kepatuhan terhadap aturan terjaga, serta keputusan melanjutkan, mengubah, menunda, atau membatalkan kegiatan didasarkan pada penilaian tertulis."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kegiatan BEM yang diselenggarakan panitia atau unit, di dalam maupun di luar kampus, luring maupun daring, termasuk kegiatan bersama pihak eksternal. SOP ini tidak mengatur penyusunan risiko organisasi (SOP-RSK-001), penanganan keadaan darurat saat kegiatan (SOP-RSK-003), dan pembatalan atau penundaan program (SOP-PRO-022)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 (Hak) huruf e dan j (kerja sama dengan pihak eksternal atas persetujuan Ketua STDIIS; kegiatan di luar kampus dengan seizin kampus).","ART Pasal 3 (Kewajiban) huruf a, c, dan d (program sesuai tujuan, bermanfaat, menjaga ketertiban dan kedamaian).","ART Pasal 9 ayat (6) (program kerja hasil Rapat Kerja harus mendapat persetujuan Pembina sebelum dilaksanakan).","ART Pasal 11 huruf c dan f (larangan kekerasan, perusakan fasilitas, serta narkoba dan zat haram).","SOP-RSK-001, SOP-PRO-004 (pemeriksaan kelayakan program), dan SOP-PRO-017 (keselamatan peserta)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Penilaian risiko kegiatan","Pemeriksaan tertulis atas bahaya, kemungkinan, dampak, dan pengendalian sebelum kegiatan dilaksanakan."],["Kegiatan berisiko tinggi","Kegiatan yang memenuhi salah satu kriteria: aktivitas fisik berat atau di alam terbuka, perjalanan luar kota, peserta banyak, dana besar, tamu atau pejabat eksternal, atau isu sensitif (usulan)."],["Rencana mitigasi","Tindakan yang disiapkan untuk menghindari, mengurangi, atau menanggapi risiko."],["Syarat lanjut","Kondisi yang wajib dipenuhi sebelum kegiatan boleh dimulai."],["Koordinator keselamatan","Anggota panitia yang bertanggung jawab atas keselamatan peserta, pertolongan pertama, dan kontak darurat selama kegiatan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Penilaian dilakukan sebelum proposal diajukan dan sebelum izin tempat atau pihak eksternal diajukan. Proposal tanpa Lembar Penilaian Risiko dianggap belum lengkap (SOP-ADM-008).","Tingkat kegiatan: rendah (rapat, kegiatan daring, kegiatan dalam ruangan kecil), sedang (kegiatan kampus berpeserta banyak), tinggi (memenuhi kriteria kegiatan berisiko tinggi).","Aspek yang dinilai: keselamatan dan kesehatan, tempat dan transportasi, cuaca atau lingkungan, keuangan, nama baik dan isi kegiatan (narasumber, materi, atribut), kepatuhan (izin kampus, syariat, ART Pasal 11), data peserta, dan kesiapan darurat.","Kegiatan berisiko tinggi wajib memiliki rencana tanggap darurat, koordinator keselamatan, perlengkapan pertolongan pertama, daftar kontak darurat, pemberitahuan atau izin tertulis kepada kampus, dan persetujuan Presiden.","Kegiatan yang syarat lanjutnya belum terpenuhi tidak boleh dimulai.","Pengaturan peserta dan panitia mengikuti adab Islam dan ketentuan kampus."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Ketua pelaksana","R","Mengisi Lembar Penilaian Risiko, melaksanakan mitigasi, dan memenuhi syarat lanjut."],["Menteri / Kabiro","R","Memeriksa dan menandatangani penilaian unit."],["Sekretaris Jenderal","R","Memeriksa kelengkapan, mencatat, dan mengarsipkan."],["Wakil Presiden","A","Menyetujui penilaian dan syarat lanjut kegiatan berisiko rendah dan sedang."],["Presiden","A","Menetapkan keputusan kegiatan berisiko tinggi: lanjut, lanjut dengan syarat, ubah, tunda, atau batal."],["Inspektur Jenderal","C","Menelaah kegiatan berisiko tinggi dan mengusulkan syarat tambahan."],["Biro Keuangan","C","Memberi masukan anggaran mitigasi."],["Pembina / KAUR ORMAWA","I","Diberi tahu atau dimintai persetujuan sesuai aturan kampus."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Draf TOR atau proposal dan RAB.","Rencana teknis (lokasi, jadwal, transportasi, daftar peserta).","Data narasumber atau mitra.","Register Risiko dan catatan insiden kegiatan sebelumnya."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Klasifikasi awal: Menentukan tingkat awal kegiatan berdasarkan kriteria.","Ketua pelaksana","TOR, kriteria","Tingkat awal kegiatan","Saat TOR disusun"],["2","Penilaian: Mengisi Lembar Penilaian Risiko: bahaya, kemungkinan, dampak, tingkat, mitigasi, dan penanggung jawab mitigasi.","Ketua pelaksana bersama panitia","TOR, rencana teknis","Lembar terisi","3 hari kerja"],["3","Pemeriksaan unit: Memeriksa dan menandatangani lembar penilaian.","Menteri / Kabiro","Lembar penilaian","Lembar diperiksa","2 hari kerja"],["4","Verifikasi dan telaah: Memeriksa kelengkapan administrasi; Irjen menelaah kegiatan berisiko tinggi dan memberi catatan syarat tambahan.","Sekjen dan Irjen","Lembar, proposal","Catatan verifikasi","2 hari kerja"],["5","Keputusan: Menyetujui kegiatan rendah dan sedang; kegiatan tinggi dibahas pada Rapat Pimpinan (SOP-GOV-005) dan ditetapkan Presiden.","Wapres; Presiden (kegiatan tinggi)","Lembar, catatan verifikasi","Keputusan tertulis dan syarat lanjut","3 hari kerja; kegiatan tinggi 1 kali rapat"],["6","Pemenuhan syarat: Melaksanakan mitigasi (pertolongan pertama, kontak darurat, izin kampus, pengarahan peserta) dan melampirkan bukti.","Ketua pelaksana","Keputusan dan syarat lanjut","Bukti pemenuhan syarat","Paling lambat H-3 kegiatan"],["7","Pemeriksaan kesiapan: Memeriksa Checklist Kesiapan Keselamatan untuk kegiatan berisiko tinggi.","Sekjen dan Irjen","Bukti syarat","Konfirmasi kesiapan","H-2 kegiatan"],["8","Pemantauan dan evaluasi: Memantau kondisi selama kegiatan; bila risiko meningkat, kegiatan diubah atau dihentikan; hasil dicatat pada LPJ.","Ketua pelaksana, koordinator keselamatan","Lembar, kondisi lapangan","Catatan evaluasi risiko pada LPJ","Bersamaan LPJ (SOP-PRO-020)"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penilaian diselesaikan sebelum proposal diajukan. Kegiatan berisiko tinggi diajukan paling lambat 14 hari kerja sebelum pelaksanaan agar tersedia waktu telaah, izin, dan pemenuhan syarat (usulan). Hasil akhir: Lembar Penilaian Risiko yang disetujui beserta syarat lanjut."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kegiatan mendesak tanpa waktu penilaian penuh: dilakukan penilaian ringkas dengan persetujuan Presiden sesuai SOP-GOV-012; syarat keselamatan kegiatan tinggi tetap tidak boleh dilewati.","Risiko berubah mendadak (cuaca, lokasi, narasumber, isu): pelaksana mengubah atau menghentikan kegiatan; penundaan atau pembatalan mengikuti SOP-PRO-022.","Kecelakaan atau keadaan darurat: SOP-RSK-003.","Kegiatan yang membutuhkan izin kampus atau pihak lain tidak dimulai sebelum izin tertulis diperoleh.","Perbedaan penilaian antarpihak: diputuskan Wakil Presiden; untuk kegiatan tinggi diputuskan Presiden."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kegiatan memiliki Lembar Penilaian Risiko sebelum proposal diajukan.","100% kegiatan berisiko tinggi memiliki rencana tanggap darurat dan koordinator keselamatan.","Tidak ada kegiatan berisiko tinggi yang dimulai sebelum syarat lanjut terpenuhi.","Insiden pada kegiatan yang risikonya tidak dinilai semakin berkurang."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Penilaian Risiko Kegiatan.","Keputusan persetujuan dan syarat lanjut.","Checklist Kesiapan Keselamatan (kegiatan berisiko tinggi).","Catatan evaluasi risiko pada LPJ dan, bila ada risiko baru, entri Register Risiko. Seluruh dokumen disimpan pada repositori resmi BEM (folder Risiko dan Etika) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa seluruh kegiatan berisiko tinggi dan sampel kegiatan lain setiap bulan; Sekretaris Jenderal memastikan Lembar Penilaian Risiko menjadi syarat kelengkapan proposal."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Klasifikasi awal → Penilaian risiko → Pemeriksaan unit → Verifikasi dan telaah → Keputusan persetujuan → Pemenuhan syarat → Pemeriksaan kesiapan → Pelaksanaan dan pemantauan → Evaluasi pada LPJ → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Penilaian Risiko Kegiatan","Nama kegiatan; ketua pelaksana; tanggal dan lokasi; jumlah peserta; kriteria tingkat; bahaya; kemungkinan; dampak; tingkat; mitigasi; penanggung jawab mitigasi; tanda tangan."],["Checklist Kesiapan Keselamatan","Rencana tanggap darurat; daftar kontak darurat; pertolongan pertama; koordinator keselamatan; izin kampus atau lokasi; pengaturan transportasi; pengarahan peserta."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Lembar Penilaian Risiko terisi lengkap dan ditandatangani.","☐ Ya ☐ Tidak"],["2","Tingkat kegiatan dan dasar penilaian jelas.","☐ Ya ☐ Tidak"],["3","Setiap mitigasi memiliki penanggung jawab dan tenggat.","☐ Ya ☐ Tidak"],["4","Kegiatan tinggi memiliki rencana darurat, kontak darurat, dan persetujuan Presiden.","☐ Ya ☐ Tidak"],["5","Izin kampus atau pihak terkait tersedia sebelum kegiatan dimulai.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-RSK-003","g":"Risiko, Etika, dan Penanganan Masalah","t":"Penanganan Kecelakaan dan Keadaan Darurat","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[257,261],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan langkah cepat, urutan prioritas, pembagian peran, dan pelaporan dalam menangani kecelakaan, cedera, gangguan kesehatan, kebakaran, bencana, atau keadaan darurat lain pada kegiatan atau lingkungan kerja BEM, dengan mendahulukan keselamatan jiwa."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk kejadian darurat pada kegiatan BEM di dalam maupun di luar kampus, perjalanan kegiatan, dan ruang sekretariat. SOP ini tidak mengatur perencanaan keselamatan sebelum kegiatan (SOP-RSK-002 dan SOP-PRO-017) dan tidak menggantikan prosedur darurat kampus atau instruksi aparat berwenang."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Kewajiban) huruf c dan d (memberi manfaat bagi civitas kampus; menjaga ketertiban dan kedamaian).","ART Pasal 12 ayat (7) (pelaporan pelanggaran berat yang berdampak pada institusi kepada KAUR ORMAWA), dipakai sebagai prinsip pelaporan kejadian berat.","ART Pasal 4 huruf a dan f (kebijakan pelaksanaan kegiatan dan penandatanganan dokumen).","SOP-GOV-007 (Rapat Evaluasi Darurat), SOP-GOV-009 (Pengganti Sementara), dan SOP-GOV-012 (Keputusan Mendesak).","Prosedur darurat dan kontak darurat kampus, sepanjang ada."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Keadaan darurat","Kejadian yang mengancam keselamatan jiwa, kesehatan, atau keamanan dan menuntut tindakan segera."],["Komandan lapangan","Ketua pelaksana atau penanggung jawab yang ditunjuk untuk mengambil keputusan di lokasi."],["Koordinator keselamatan","Anggota panitia yang menangani pertolongan pertama dan kontak darurat (SOP-RSK- 002)."],["Klasifikasi kejadian","Ringan (luka kecil, cukup pertolongan pertama); sedang (perlu perawatan medis atau mengganggu kegiatan); berat (korban jiwa, cedera serius, kebakaran, bencana, kekerasan, atau berdampak pada kampus dan publik). Usulan."],["Daftar Kontak Darurat","Daftar nomor layanan medis, keamanan kampus, pemadam kebakaran, pimpinan BEM, dan Pembina atau KAUR ORMAWA."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Urutan prioritas: keselamatan jiwa; pengamanan lokasi; pelaporan; baru kemudian pencarian sebab dan penanggung jawab. Pencarian kesalahan tidak boleh menunda pertolongan.","Komandan lapangan berwenang menghentikan kegiatan tanpa menunggu persetujuan bila terdapat bahaya nyata.","Pertolongan pertama hanya diberikan oleh yang mampu; korban cedera serius tidak dipindahkan kecuali ada bahaya lanjutan; layanan medis segera dihubungi.","Kejadian sedang dan berat dilaporkan kepada Wakil Presiden dan Presiden; kejadian berat yang berdampak pada institusi dilaporkan kepada KAUR ORMAWA atau Pembina.","Kabar kepada keluarga korban disampaikan oleh pimpinan atau pihak kampus, bukan melalui media sosial. Nama dan kondisi korban tidak disebarkan tanpa persetujuan keluarga atau pihak berwenang.","Pendokumentasian tidak boleh menghambat pertolongan.","Biaya penanganan darurat tidak boleh menjadi alasan menunda pertolongan; pertanggungjawabannya dicatat setelahnya (SOP-KEU-014)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Komandan lapangan","R","Memimpin penanganan di lokasi, menghentikan kegiatan bila perlu, dan melapor kepada pimpinan."],["Koordinator keselamatan","R","Memberi pertolongan pertama dan menghubungi layanan darurat."],["Panitia dan pengurus di lokasi","R","Mengikuti instruksi, membantu pengamanan, dan menjaga ketertiban peserta."],["Sekretaris Jenderal","R","Mencatat kronologi, menghubungi kontak darurat, dan menyusun laporan."],["Wakil Presiden","R","Mengoordinasikan bantuan antarunit dan pendampingan korban."],["Presiden","A","Bertanggung jawab akhir atas penanganan lanjutan, keputusan kegiatan, dan pelaporan kepada kampus."],["Inspektur Jenderal","C","Menelaah penyebab dan kesesuaian prosedur setelah kejadian."],["Layanan medis, keamanan kampus, aparat berwenang","C","Dimintai bantuan dan arahan sesuai jenis kejadian."],["Pembina / KAUR ORMAWA","I","Diberi tahu atas kejadian sedang dan berat."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan awal dari pengurus atau panitia di lokasi.","Daftar Kontak Darurat dan rencana tanggap darurat kegiatan.","Lembar Penilaian Risiko Kegiatan (SOP-RSK-002).","Data kontak keluarga dan kondisi kesehatan peserta yang dikumpulkan sesuai SOP-RSK-010."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Hentikan bahaya dan tolong: Siapa pun yang mengetahui kejadian segera memberi tahu komandan lapangan; kegiatan dihentikan bila perlu, korban dijauhkan dari bahaya, dan pertolongan pertama diberikan sesuai kemampuan.","Pengurus di lokasi, komandan lapangan","Kejadian","Korban aman, bahaya berhenti","Seketika"],["2","Panggil bantuan: Menghubungi layanan medis, keamanan kampus, pemadam kebakaran, atau aparat sesuai jenis kejadian.","Komandan lapangan atau koordinator keselamatan","Daftar Kontak Darurat","Bantuan dihubungi","Maks. 10 menit setelah kejadian diketahui"],["3","Klasifikasi dan lapor pimpinan: Menentukan klasifikasi kejadian dan melapor kepada Sekjen dan Wapres melalui telepon, disusul pesan tertulis di kanal resmi.","Komandan lapangan","Kondisi korban dan lokasi","Laporan awal dan klasifikasi","Sedang dan berat maks. 30 menit; ringan maks. 24 jam"],["4","Kendalikan situasi: Mengatur peserta, mengamankan lokasi dan barang, mendampingi korban sampai ditangani, serta menetapkan satu juru bicara.","Komandan lapangan, panitia","Instruksi pimpinan","Situasi terkendali","Selama kejadian"],["5","Putuskan kegiatan: Menentukan kegiatan dilanjutkan, diubah, ditunda, atau dibatalkan; keputusan mendesak mengikuti SOP- GOV-012.","Presiden (atau Wapres bila berhalangan)","Laporan, kondisi lapangan","Keputusan tercatat","Maks. 2 jam setelah laporan (sedang dan berat)"],["6","Beri tahu kampus dan keluarga: Melaporkan kepada KAUR ORMAWA atau Pembina dan memberi tahu keluarga korban melalui pimpinan atau pihak kampus; bila berpotensi menjadi isu publik, lanjutkan ke SOP-RSK-011.","Presiden dan Sekjen","Laporan kejadian","Pemberitahuan terkirim","Berat maks. 3 jam; sedang maks. 24 jam"],["7","Dampingi korban: Memastikan korban memperoleh perawatan, pendampingan, dan kontak dengan keluarga; pimpinan menjenguk atau menghubungi korban.","Wapres dan unit terkait","Data korban","Korban terdampingi","Selama pemulihan"],["8","Laporan kejadian: Menyusun Laporan Kejadian Darurat: kronologi, tindakan, pihak terlibat, dan kondisi akhir.","Sekjen bersama komandan lapangan","Catatan kronologi","Laporan Kejadian Darurat","2 hari kerja setelah kejadian"],["9","Evaluasi dan tindakan korektif: Menelaah penyebab dan kesesuaian dengan penilaian risiko; menetapkan tindakan korektif dan mencatatnya pada register insiden (SOP-RSK-012).","Irjen dan Sekjen","Laporan kejadian","Catatan insiden, tindakan korektif","7 hari kerja setelah penutupan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pertolongan dan pemanggilan bantuan dilakukan seketika; pimpinan menerima laporan kejadian sedang dan berat paling lambat 30 menit (usulan). Hasil akhir: korban tertangani, Laporan Kejadian Darurat, serta catatan insiden dan tindakan korektif."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kejadian di wilayah yang memiliki prosedur darurat resmi kampus: prosedur kampus didahulukan dan BEM mengikuti instruksi petugas.","Komandan lapangan terluka atau tidak dapat dihubungi: koordinator keselamatan atau pengurus senior di lokasi mengambil alih sampai pimpinan menunjuk pengganti.","Presiden dan Wakil Presiden tidak dapat dihubungi: Sekjen menghubungi Pembina atau KAUR ORMAWA dan mengikuti SOP-GOV-009.","Dugaan kekerasan atau pelecehan: SOP-RSK-005; dugaan kelalaian panitia: SOP-RSK-004; kejadian yang menjadi isu publik: SOP-RSK-011.","Dugaan tindak pidana pada kejadian: Pembina menentukan pelaporan kepada pihak berwenang."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Bantuan dihubungi paling lambat 10 menit pada 100% kejadian sedang dan berat.","Pimpinan menerima laporan paling lambat 30 menit pada minimal 90% kejadian sedang dan berat.","100% kejadian memiliki Laporan Kejadian Darurat dan catatan insiden.","Tidak ada informasi korban yang tersebar melalui kanal tidak resmi.","Kejadian berulang pada penyebab yang sama menurun."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan Kejadian Darurat.","Keputusan kelanjutan kegiatan.","Bukti pemberitahuan kepada kampus dan keluarga.","Catatan insiden dan tindakan korektif pada register. Seluruh dokumen disimpan pada repositori resmi BEM (folder Risiko dan Etika) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa Daftar Kontak Darurat setiap awal semester dan sebelum kegiatan berisiko tinggi; Irjen meninjau seluruh kejadian setiap bulan dan melaporkan pola pada Rapat Kabinet."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Hentikan bahaya dan tolong → Panggil bantuan → Klasifikasi dan lapor pimpinan → Kendalikan situasi → Putuskan kegiatan → Beri tahu kampus dan keluarga → Dampingi korban → Laporan kejadian → Evaluasi dan tindakan korektif → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Laporan Kejadian Darurat","Waktu; tempat; kegiatan; jenis kejadian; klasifikasi; korban; kronologi; tindakan; pihak yang dihubungi; kondisi akhir; pelapor."],["Daftar Kontak Darurat","Layanan medis terdekat; keamanan kampus; pemadam kebakaran; pimpinan BEM; Pembina atau KAUR ORMAWA; koordinator keselamatan; nomor diisi per kegiatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Korban memperoleh pertolongan dan bantuan dihubungi tanpa menunggu persetujuan.","☐ Ya ☐ Tidak"],["2","Klasifikasi dan waktu pelaporan tercatat.","☐ Ya ☐ Tidak"],["3","Kampus dan keluarga diberi tahu sesuai klasifikasi.","☐ Ya ☐ Tidak"],["4","Informasi korban tidak disebarkan melalui kanal tidak resmi.","☐ Ya ☐ Tidak"],["5","Laporan kejadian, catatan insiden, dan tindakan korektif dibuat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-RSK-004","g":"Risiko, Etika, dan Penanganan Masalah","t":"Penanganan Pengaduan Internal","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[262,266],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan saluran, tahapan, dan batas waktu penerimaan, penelaahan, penanganan, dan penutupan pengaduan internal terhadap pengurus, unit, kegiatan, atau keputusan BEM, dengan menjaga keadilan bagi pelapor dan terlapor serta kerahasiaan, dan tidak bertentangan dengan AD/ART."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pengaduan dari pengurus, anggota, mahasiswa, atau pihak lain tentang dugaan pelanggaran ketentuan organisasi, kelalaian tugas, atau ketidakadilan dalam pelayanan BEM. Pengaduan khusus ditangani melalui SOP tersendiri: perundungan dan pelecehan (SOP-RSK-005), konflik kepentingan (SOP-RSK-006), dana atau aset (SOP-RSK-007), dan kebocoran data (SOP-RSK-009). Pengaduan terhadap BPM atau pihak kampus tidak diatur SOP ini (ART Pasal 12 ayat 8)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 11 (Larangan).","ART Pasal 12 ayat (1) sampai (6) dan (9) (kewenangan pimpinan, jenis sanksi, pengawasan Irjen, klasifikasi pelanggaran).","ART Pasal 13 ayat (1) sampai (9) (mekanisme pemberian sanksi, bukti, keadilan, hak klarifikasi dan pembelaan).","AD Pasal 9 ayat (2) (alasan pemberhentian anggota).","SOP-GOV-010 (Penyelesaian Konflik Internal) dan SOP-SDM-013 (Penanganan Dugaan Pelanggaran Kode Etik)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pengaduan","Penyampaian dugaan pelanggaran, kelalaian, atau ketidakadilan oleh siapa pun kepada BEM."],["Pelapor / terlapor","Pihak yang menyampaikan pengaduan / pihak yang diduga melakukan pelanggaran."],["Penelaahan awal","Pemeriksaan apakah pengaduan masuk kewenangan BEM dan memiliki informasi yang cukup untuk diperiksa."],["Klarifikasi","Kesempatan bagi terlapor menjelaskan dan membela diri sebelum keputusan diambil (ART Pasal 13 ayat 9)."],["Perlindungan pelapor","Jaminan kerahasiaan identitas dan tidak adanya pembalasan terhadap pelapor, korban, dan saksi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Saluran resmi: Formulir Pengaduan kepada Irjen, pesan langsung kepada Irjen, atau langsung kepada Pembina atau KAUR ORMAWA. Bila Irjen terlibat, pelapor dapat melapor kepada Wakil Presiden atau Presiden; bila ketiganya terlibat, kepada KAUR ORMAWA.","Pengaduan tidak ditolak hanya karena bentuknya tidak baku; Irjen membantu melengkapi. Bukti yang dapat dipertanggungjawabkan (ART Pasal 13 ayat 4) mencakup keterangan pelapor dan saksi, pesan, dokumen, foto, dan catatan.","Pengaduan tanpa bukti lengkap tetap ditelaah awal, tetapi sanksi hanya dijatuhkan berdasarkan bukti (ART Pasal 13 ayat 7). Pengaduan tanpa nama diterima sebatas dapat diverifikasi dan tidak menjadi satu-satunya dasar sanksi.","Identitas pelapor dirahasiakan (SOP-RSK-010). Pembalasan terhadap pelapor adalah pelanggaran tersendiri. Pengaduan beritikad baik yang tidak terbukti tidak dikenai sanksi; laporan palsu yang disengaja diproses sebagai pelanggaran.","Terlapor berhak klarifikasi dan pembelaan sebelum keputusan yang merugikannya (ART Pasal 13 ayat 9). Prinsip tabayyun dipegang: kebenaran diperiksa sebelum disimpulkan.","Pihak yang terlibat atau berkonflik kepentingan tidak ikut menelaah dan memutus (SOP-RSK-006).","Klasifikasi usulan berdasarkan dampak (ART Pasal 12 ayat 9): ringan (pelanggaran disiplin tanpa kerugian); sedang (kerugian terbatas atau berulang); berat (melanggar larangan ART Pasal 11 yang berdampak pada organisasi atau institusi).","Sanksi mengikuti ART Pasal 12 ayat (2) dan dijatuhkan pimpinan BEM (ayat 1 dan 5). Pemberhentian pengurus mengikuti SOP-SDM-014 dan, untuk pengurus inti atau pelanggaran berat, Musyawarah Istimewa (ART Pasal 8 ayat 3). Pelanggaran berat yang berdampak pada institusi dilaporkan Irjen kepada KAUR ORMAWA (ART Pasal 12 ayat 7)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pelapor","R","Menyampaikan pengaduan dan bukti serta bersedia dimintai keterangan."],["Inspektur Jenderal","A","Menerima, menelaah, memeriksa fakta, mengusulkan klasifikasi, dan menjaga jalannya proses."],["Sekretaris Jenderal","R","Mencatat pada Register Pengaduan dengan identitas terbatas dan menjaga arsip terbatas."],["Wakil Presiden","R","Memastikan tindak lanjut pada Eksekutif dan perlindungan pelapor."],["Presiden / BPH","A","Memutuskan tindak lanjut dan sanksi dalam kewenangan, tanpa pihak yang berkonflik kepentingan."],["Terlapor","C","Memberi klarifikasi dan pembelaan."],["Menteri / Kabiro terkait","C","Memberi keterangan dan menangani pelanggaran individu di unitnya sesuai ART Pasal 13 ayat (1) dan (2)."],["Pembina / KAUR ORMAWA","I","Diberi laporan pelanggaran berat dan menjadi tempat keberatan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Pengaduan atau catatan pengaduan lisan.","Bukti pendukung dan keterangan saksi.","AD/ART dan SOP terkait.","Data kegiatan atau penugasan yang berkaitan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan: Menerima pengaduan melalui saluran resmi, memberi tanda terima, dan menjelaskan proses, hak pelapor, dan kerahasiaan.","Irjen","Pengaduan, bukti awal","Pengaduan tercatat, tanda terima","1 hari kerja"],["2","Pencatatan terbatas: Mencatat pada Register Pengaduan (kode, tanggal, kategori, status) tanpa identitas lengkap; berkas lengkap hanya pada folder terbatas.","Sekjen","Pengaduan","Entri register","1 hari kerja"],["3","Penelaahan awal: Menilai kewenangan, kecukupan informasi, urgensi, dan konflik kepentingan; menetapkan klasifikasi awal; mengalihkan ke SOP khusus bila perlu.","Irjen","Pengaduan, bukti","Hasil telaah dan klasifikasi awal","3 hari kerja"],["4","Pelindungan sementara: Menetapkan langkah bila ada risiko pembalasan atau bahaya (menjaga jarak tugas, membatasi akses, pendampingan) tanpa menyatakan terlapor bersalah.","Wapres dan Irjen","Hasil telaah","Langkah sementara tercatat","Segera setelah telaah awal"],["5","Pemeriksaan dan klarifikasi: Mengumpulkan bukti dan keterangan saksi, lalu meminta klarifikasi terlapor dengan waktu yang wajar untuk menjawab.","Irjen","Bukti, keterangan saksi","Berita Acara Klarifikasi","Sedang 7 hari kerja; berat 14 hari kerja"],["6","Laporan hasil: Menyusun Laporan Hasil Pemeriksaan: fakta, temuan (terbukti, tidak terbukti, atau belum cukup bukti), klasifikasi, dan usulan tindak lanjut.","Irjen","Hasil pemeriksaan","Laporan Hasil Pemeriksaan","3 hari kerja"],["7","Keputusan: Memutuskan pembinaan, sanksi (ART Pasal 12 ayat 2), atau tidak terbukti melalui musyawarah (SOP-GOV-002); pelanggaran berat dilaporkan kepada KAUR ORMAWA.","Presiden / BPH","Laporan hasil","Keputusan Tindak Lanjut","5 hari kerja"],["8","Pemberitahuan: Memberi tahu pelapor dan terlapor secara terpisah dan tertulis tentang hasil dan hak keberatan.","Irjen","Keputusan","Pemberitahuan hasil","2 hari kerja"],["9","Pelaksanaan dan pemantauan: Melaksanakan pembinaan atau sanksi; Irjen memantau pelaksanaan dan memastikan tidak ada pembalasan.","Wapres, Irjen","Keputusan","Tindak lanjut terlaksana","Sesuai keputusan"],["10","Penutupan: Menutup kasus pada register, mengarsipkan berkas terbatas, dan melaporkan statistik anonim melalui forum resmi BEM (ART Pasal 13 ayat 6).","Sekjen dan Irjen","Dokumen kasus","Kasus ditutup, laporan statistik","7 hari kerja setelah pelaksanaan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Tanda terima diberikan paling lambat 1 hari kerja dan telaah awal 3 hari kerja. Penyelesaian ditargetkan paling lambat 21 hari kerja (sedang) dan 30 hari kerja (berat) sejak pengaduan diterima (usulan). Hasil akhir: Laporan Hasil Pemeriksaan, Keputusan Tindak Lanjut, dan kasus ditutup."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Perundungan atau pelecehan: SOP-RSK-005; dana atau aset: SOP-RSK-007; kebocoran data: SOP- RSK-009; konflik antarpengurus yang bukan pelanggaran: SOP-GOV-010.","Terlapor adalah Presiden, Wakil Presiden, atau Sekjen: Irjen tetap menelaah, melapor kepada KAUR ORMAWA, dan pihak terlapor tidak ikut memutus. Terlapor adalah Irjen: Presiden menunjuk pemeriksa pengganti sementara dengan sepengetahuan KAUR ORMAWA.","Pengaduan terhadap BPM atau pihak kampus: diteruskan kepada KAUR ORMAWA (ART Pasal 12 ayat 8).","Keberatan atas keputusan dapat diajukan tertulis kepada Pembina atau KAUR ORMAWA dalam 5 hari kerja setelah pemberitahuan (usulan; ART tidak mengatur keberatan).","Dugaan tindak pidana: tidak diselesaikan hanya secara internal; Pembina menentukan pelaporan kepada pihak berwenang.","Bahaya yang mengancam keselamatan: SOP-RSK-003."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pengaduan menerima tanda terima paling lambat 1 hari kerja.","Minimal 90% pengaduan ditelaah awal paling lambat 3 hari kerja.","100% terlapor diberi kesempatan klarifikasi.","Tidak ada kebocoran identitas pelapor.","100% keputusan didasarkan bukti tertulis dan sesuai jenis sanksi pada ART Pasal 12 ayat (2)."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir atau catatan pengaduan dan tanda terima.","Entri Register Pengaduan.","Berita Acara Klarifikasi dan Laporan Hasil Pemeriksaan.","Keputusan Tindak Lanjut.","Laporan statistik anonim. Seluruh dokumen disimpan pada repositori resmi BEM (folder Risiko dan Etika, akses terbatas sesuai SOP- RSK-010) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen melaporkan statistik anonim (jumlah, kategori, waktu penyelesaian) setiap bulan pada Rapat Kabinet; Presiden dan Wakil Presiden memeriksa kepatuhan batas waktu; Sekretaris Jenderal memeriksa pembatasan akses berkas."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima pengaduan → Catat terbatas → Telaah awal → Pelindungan sementara → Pemeriksaan dan klarifikasi → Laporan hasil → Keputusan Presiden / BPH → Pemberitahuan → Pelaksanaan dan pemantauan → Penutupan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pengaduan Internal","Tanggal; identitas pelapor (dapat dirahasiakan); pihak yang diadukan; uraian kejadian; waktu dan tempat; bukti; saksi; harapan penyelesaian; pernyataan itikad baik."],["Berita Acara Klarifikasi","Identitas; tanggal; pertanyaan dan jawaban; hak pembelaan; tanda tangan."],["Laporan Hasil Pemeriksaan dan Keputusan Tindak Lanjut","Nomor kasus; ringkasan; fakta; bukti; temuan; klasifikasi; keputusan; dasar pasal; sanksi atau pembinaan; pelaksana; tenggat."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Tanda terima diberikan dan kasus tercatat dengan identitas terbatas.","☐ Ya ☐ Tidak"],["2","Tidak ada pihak yang berkonflik kepentingan dalam proses.","☐ Ya ☐ Tidak"],["3","Terlapor diberi kesempatan klarifikasi dan pembelaan.","☐ Ya ☐ Tidak"],["4","Keputusan berdasarkan bukti, proporsional, dan sesuai jenis sanksi ART Pasal 12 ayat (2).","☐ Ya ☐ Tidak"],["5","Pelapor dan terlapor diberi tahu hasil dan kerahasiaan terjaga.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-RSK-005","g":"Risiko, Etika, dan Penanganan Masalah","t":"Penanganan Dugaan Perundungan dan Pelecehan","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[267,271],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penerimaan, perlindungan, pemeriksaan, dan tindak lanjut dugaan perundungan, intimidasi, asusila, dan pelecehan di lingkungan BEM dan kegiatannya, dengan mendahulukan keselamatan dan martabat korban, menjaga kerahasiaan, serta memberi hak klarifikasi kepada terlapor."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk dugaan perundungan (fisik, verbal, sosial, daring), intimidasi, tindakan asusila, dan pelecehan yang melibatkan pengurus BEM, panitia, atau peserta kegiatan BEM. SOP ini tidak menggantikan proses hukum atau pembinaan oleh kampus. Pencegahan melalui SOP-SDM-017; pengaduan umum melalui SOP- RSK-004."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 11 huruf a, c, g, dan h (larangan SARA, kekerasan, pencemaran nama baik, serta asusila, pelecehan, dan perundungan).","AD Pasal 9 ayat (2) huruf a sampai c (pemberhentian karena pelanggaran syariat dan merugikan nama baik).","ART Pasal 12 ayat (2), (5), (6), dan (7) (jenis sanksi, kewenangan, pelaporan pelanggaran berat kepada KAUR ORMAWA).","ART Pasal 13 ayat (4), (7), dan (9) (bukti, keadilan, hak klarifikasi dan pembelaan).","SOP-RSK-004, SOP-RSK-010, dan SOP-SDM-017."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Perundungan","Tindakan berulang atau disengaja yang merendahkan, mengintimidasi, atau menyakiti orang lain secara fisik, lisan, sosial, maupun daring."],["Pelecehan","Perilaku atau ucapan bernuansa seksual atau asusila yang tidak dikehendaki dan merendahkan martabat seseorang."],["Korban / saksi","Pihak yang mengalami dugaan tindakan / pihak yang melihat atau mengetahui kejadian."],["Pendamping","Orang yang dipercaya korban atau ditunjuk, yang mendampingi selama proses; sesama jenis dengan korban bila diminta."],["Pelindungan korban","Langkah menjaga keselamatan, kerahasiaan, dan mencegah pembalasan terhadap korban dan saksi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Keselamatan dan martabat korban didahulukan. Korban tidak dipaksa menceritakan ulang berkali-kali, tidak disalahkan, dan tidak dipertemukan dengan terlapor tanpa persetujuannya.","Pemeriksa dan pendamping sedapat mungkin sejenis dengan korban; pertemuan berlainan jenis dilakukan dengan pendamping dan sesuai adab Islam dan ketentuan kampus.","Pelaporan terbuka bagi korban, saksi, atau siapa pun. Bukti tidak menjadi syarat penerimaan laporan; keterangan korban dan saksi, pesan, dan catatan dinilai sebagai bukti (ART Pasal 13 ayat 4). Sanksi hanya berdasarkan bukti yang dapat dipertanggungjawabkan.","Klasifikasi usulan: ringan (ejekan atau candaan merendahkan tanpa pola); sedang (berulang, intimidasi, atau menyebar di grup); berat (kekerasan fisik, ancaman, pelecehan seksual, asusila, atau korban di bawah tekanan atasan). Sedang dan berat dilaporkan kepada KAUR ORMAWA atau Pembina.","Dugaan kekerasan, ancaman, atau pelecehan seksual tidak diselesaikan dengan perdamaian paksa. Pembina menentukan pelaporan kepada pihak berwenang dan layanan kampus.","Terlapor berhak klarifikasi dan pembelaan, dan dapat dinonaktifkan sementara dari tugas yang berhubungan dengan korban tanpa dinyatakan bersalah.","Pembalasan terhadap korban, saksi, atau pelapor adalah pelanggaran tersendiri.","Sanksi mengikuti ART Pasal 12 ayat (2). Pelanggaran berat dapat berujung pemberhentian tetap melalui SOP-SDM-014 dan Musyawarah Istimewa bila pengurus inti."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Korban / pelapor","R","Menyampaikan dugaan sebatas yang diketahui dan menyatakan kebutuhan pelindungan."],["Inspektur Jenderal","A","Menerima laporan, menjaga proses, memeriksa fakta, dan mengusulkan klasifikasi dan tindak lanjut."],["Pendamping","R","Mendampingi korban selama proses dan menyampaikan kebutuhannya."],["Sekretaris Jenderal","R","Mencatat dengan identitas terbatas dan menjaga arsip terbatas."],["Wakil Presiden","R","Mengatur pelindungan sementara, penonaktifan sementara, dan pemulihan suasana kerja."],["Presiden / BPH","A","Memutuskan sanksi dalam kewenangan, tanpa pihak yang berkonflik kepentingan."],["Terlapor","C","Memberi klarifikasi dan pembelaan."],["Saksi","C","Memberi keterangan sebatas yang diketahui."],["Pembina / KAUR ORMAWA","I","Diberi laporan kasus sedang dan berat serta menentukan pelaporan kepada pihak berwenang."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan korban, saksi, atau pihak lain (lisan atau tertulis).","Bukti yang ada (pesan, tangkapan layar, foto, catatan kejadian).","Keterangan saksi.","Data kegiatan, penugasan, dan hubungan kerja pihak terkait."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan: Menerima laporan secara tertutup dan empatik, memastikan keselamatan korban, menjelaskan proses dan kerahasiaan, serta menawarkan pendamping.","Irjen (atau penerima pertama yang segera melapor)","Laporan","Laporan tercatat","Seketika; diteruskan maks. 1 hari kerja"],["2","Pelindungan segera: Memisahkan korban dari terlapor bila perlu, mengatur penugasan, mencegah kontak dan pembalasan, serta menghubungi layanan medis atau pendamping bila dibutuhkan; bahaya fisik segera ditangani sesuai SOP- RSK-003.","Wapres dan Irjen","Laporan","Langkah pelindungan tercatat","Maks. 24 jam"],["3","Pencatatan terbatas: Mencatat pada Register Pengaduan dengan kode dan identitas terbatas; berkas lengkap pada folder terbatas.","Sekjen","Laporan","Entri register","1 hari kerja"],["4","Klasifikasi dan lapor kampus: Menetapkan klasifikasi awal dan melaporkan kasus sedang dan berat kepada KAUR ORMAWA atau Pembina untuk menentukan pelaporan kepada pihak berwenang.","Irjen dan Presiden","Laporan, bukti","Klasifikasi; surat laporan","Maks. 2 hari kerja"],["5","Pemeriksaan: Mengambil keterangan korban (sekali dan dengan pendamping), saksi, lalu terlapor dengan kesempatan klarifikasi; mengumpulkan bukti dengan menjaga privasi.","Irjen (dengan pemeriksa tambahan sejenis bila perlu)","Laporan, bukti","Berita Acara Keterangan","Sedang 10 hari kerja; berat 14 hari kerja"],["6","Laporan hasil: Menyusun Laporan Hasil Pemeriksaan: fakta, temuan, klasifikasi, dan usulan sanksi serta pemulihan korban.","Irjen","Berita acara","Laporan Hasil Pemeriksaan","3 hari kerja"],["7","Keputusan: Memutuskan sanksi dan langkah pemulihan melalui musyawarah (SOP- GOV-002); usulan pemberhentian mengikuti SOP-SDM-014.","Presiden / BPH","Laporan hasil","Keputusan Tindak Lanjut","5 hari kerja"],["8","Pemberitahuan dan pemulihan: Memberi tahu korban dan terlapor secara terpisah; menyediakan pendampingan, penyesuaian tugas, dan pengawasan agar tidak ada pembalasan.","Irjen dan Wapres","Keputusan","Pemberitahuan; rencana pemulihan","2 hari kerja"],["9","Pemantauan dan penutupan: Memantau selama 3 bulan, menutup kasus, mengarsipkan, dan melaporkan statistik anonim.","Irjen dan Sekjen","Dokumen kasus","Kasus ditutup; laporan statistik","Pemantauan 3 bulan; penutupan 7 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pelindungan segera diberikan paling lambat 24 jam sejak laporan diterima dan penyelesaian ditargetkan paling lambat 21 hari kerja (sedang) dan 30 hari kerja (berat) (usulan). Hasil akhir: Laporan Hasil Pemeriksaan, Keputusan Tindak Lanjut, dan rencana pemulihan korban."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Korban atau saksi menolak melapor secara resmi: Irjen tetap menanggapi dengan pendampingan, menelaah tanpa menyebut identitas, dan melaporkan kepada Pembina bila ada risiko bagi orang lain.","Terlapor adalah pimpinan BEM atau Irjen: Irjen (atau pemeriksa pengganti yang ditunjuk Presiden) melapor kepada KAUR ORMAWA, dan pihak terlapor tidak ikut memutus.","Korban di bawah umur atau dugaan tindak pidana: segera dilaporkan kepada Pembina untuk penentuan pelaporan kepada pihak berwenang.","Korban dalam kondisi psikologis berat: pendampingan profesional melalui layanan kampus.","Bahaya fisik berlangsung: SOP-RSK-003 didahulukan."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% laporan menerima pelindungan segera paling lambat 24 jam.","100% kasus sedang dan berat dilaporkan kepada KAUR ORMAWA atau Pembina.","100% terlapor diberi hak klarifikasi dan pembelaan.","Tidak ada pembalasan terhadap korban atau saksi pada masa pemantauan.","Tidak ada kebocoran identitas korban."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Catatan laporan dan entri register terbatas.","Berita Acara Keterangan.","Laporan Hasil Pemeriksaan dan Keputusan Tindak Lanjut.","Rencana pelindungan dan pemulihan korban.","Laporan statistik anonim. Seluruh dokumen disimpan pada repositori resmi BEM (folder Risiko dan Etika, akses terbatas sesuai SOP- RSK-010) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen melaporkan statistik anonim setiap bulan pada Rapat Kabinet; Presiden memeriksa kepatuhan batas waktu pelindungan; Sekretaris Jenderal memeriksa pembatasan akses berkas."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima laporan → Pelindungan segera → Catat terbatas → Klasifikasi dan lapor kampus → Pemeriksaan → Laporan hasil → Keputusan → Pemberitahuan dan pemulihan → Pemantauan dan penutupan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan Dugaan Perundungan atau Pelecehan","Tanggal; identitas pelapor (dapat dirahasiakan); korban; terlapor; kronologi; waktu dan tempat; bukti; saksi; kebutuhan pelindungan; pendamping yang diinginkan."],["Berita Acara Keterangan","Identitas; tanggal; pemeriksa dan pendamping; ringkasan keterangan; hak klarifikasi; tanda tangan."],["Rencana Pelindungan dan Pemulihan","Kasus; langkah pelindungan; penyesuaian tugas; pendampingan; penanggung jawab; tanggal tinjau."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Keselamatan korban dipastikan dan pelindungan segera diberikan.","☐ Ya ☐ Tidak"],["2","Korban ditawari pendamping dan tidak dipertemukan dengan terlapor tanpa persetujuannya.","☐ Ya ☐ Tidak"],["3","Kasus sedang dan berat dilaporkan kepada KAUR ORMAWA atau Pembina.","☐ Ya ☐ Tidak"],["4","Terlapor diberi kesempatan klarifikasi dan pembelaan.","☐ Ya ☐ Tidak"],["5","Pemantauan pembalasan dan pemulihan korban dilakukan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-RSK-006","g":"Risiko, Etika, dan Penanganan Masalah","t":"Penanganan Konflik Kepentingan","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[272,275],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara mendeklarasikan, menilai, dan mengelola konflik kepentingan pengurus, agar keputusan, pengadaan, penilaian, seleksi, dan pemeriksaan BEM objektif dan tidak menguntungkan pribadi, keluarga, kelompok, atau organisasi lain."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus dan panitia BEM, termasuk pengurus yang merangkap jabatan di ORMAWA lain. SOP ini mengatur deklarasi dan pengelolaan; bila konflik kepentingan berubah menjadi penyalahgunaan dana atau aset digunakan SOP-RSK-007, dan sanksi mengikuti SOP-RSK-004."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 8 ayat (5) sampai (7) (rangkap jabatan di ORMAWA lain dan syaratnya).","ART Pasal 6 ayat (1) huruf d (pengurus tidak sedang menjabat di organisasi kemahasiswaan lain pada periode yang sama) dan ayat (2).","ART Pasal 11 huruf i, j, dan k (larangan penyelewengan dana, kecurangan dalam pemilihan atau keputusan, dan penyalahgunaan fasilitas atau nama organisasi).","ART Pasal 3 (Kewajiban) huruf e (mengelola keuangan secara amanah).","SOP-GOV-002, SOP-KEU-011, dan SOP-SDM-001."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Konflik kepentingan","Keadaan ketika kepentingan pribadi, keluarga, kelompok, atau organisasi lain dapat memengaruhi, atau tampak memengaruhi, keputusan dan tindakan pengurus."],["Deklarasi kepentingan","Pernyataan tertulis pengurus tentang hubungan atau kepentingan yang berpotensi menimbulkan konflik."],["Pengurus berkepentingan","Pengurus yang memiliki konflik kepentingan atas suatu keputusan atau proses."],["Pengecualian diri (recusal)","Tidak ikut membahas, menilai, memberi suara, atau memutus suatu perkara."],["Register Kepentingan","Catatan deklarasi dan langkah pengelolaan konflik kepentingan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Contoh konflik: terlibat dalam seleksi atau pengadaan yang menguntungkan keluarga, teman dekat, atau organisasi lain tempatnya menjabat; menilai kinerja atau memeriksa kerabat; atau menerima hadiah dari pihak yang berurusan dengan BEM.","Setiap pengurus mengisi Deklarasi Kepentingan awal masa jabatan dan memperbaruinya saat ada perubahan, termasuk rangkap jabatan di ORMAWA lain beserta kelengkapan syarat AD Pasal 8 ayat (7).","Pengurus wajib mendeklarasikan konflik sebelum pembahasan dimulai dan mengecualikan diri dari pembahasan, pemungutan suara, dan penetapan.","Hadiah, bingkisan, atau fasilitas dari pihak yang berurusan dengan BEM dilaporkan; bila tidak wajar ditolak atau dikembalikan dan dicatat.","Menyembunyikan konflik kepentingan adalah pelanggaran. Pengelolaan konflik tidak dengan sendirinya merupakan pelanggaran.","Keputusan yang dibuat tanpa pengecualian diri pada konflik yang diketahui dapat ditinjau ulang oleh Rapat Pimpinan.","Ketidakselarasan AD Pasal 8 ayat (5) sampai (7) dan ART Pasal 6 ayat (1) huruf d ditafsirkan melalui KAUR ORMAWA dan dibahas pada revisi AD/ART."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pengurus berkepentingan","R","Mengisi dan memperbarui deklarasi, melapor sebelum pembahasan, dan mengecualikan diri."],["Pemimpin rapat","R","Menanyakan konflik sebelum pembahasan dan memastikan pengecualian diri dicatat."],["Sekretaris Jenderal","R","Mengumpulkan deklarasi, memelihara Register Kepentingan, dan mencatat pengecualian pada notulen."],["Inspektur Jenderal","A","Menilai konflik yang dilaporkan atau ditemukan dan menetapkan langkah pengelolaan."],["Presiden","A","Memutus bila konflik menyangkut pimpinan atau unit dan menetapkan penggantian penanggung jawab."],["Wakil Presiden","C","Memberi masukan pengalihan tugas pada unit."],["Pembina / KAUR ORMAWA","I","Diberi tahu bila konflik menyangkut Presiden, Wakil Presiden, Irjen, atau institusi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Deklarasi Kepentingan.","Daftar jabatan di ORMAWA lain dan surat rekomendasi serta komitmen sesuai AD.","Agenda rapat dan daftar pihak yang terlibat pada seleksi atau pengadaan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Deklarasi awal: Seluruh pengurus mengisi Deklarasi Kepentingan, termasuk rangkap jabatan dan hubungan keluarga atau kemitraan yang relevan.","Seluruh pengurus","Formulir","Deklarasi terkumpul","7 hari kerja setelah pelantikan"],["2","Pencatatan: Mencatat deklarasi pada Register Kepentingan; menandai pengurus yang perlu dikecualikan pada proses tertentu.","Sekjen","Deklarasi","Register Kepentingan","3 hari kerja"],["3","Pemeriksaan sebelum proses: Sebelum rapat, seleksi, penilaian, atau pengadaan, pemimpin rapat atau panitia menanyakan konflik kepentingan dan mencatat jawabannya.","Pemimpin rapat atau ketua panitia","Register, agenda","Konflik teridentifikasi","Setiap proses"],["4","Pelaporan konflik: Pengurus yang berkepentingan atau yang mengetahui konflik melapor kepada Irjen secara tertulis.","Pengurus","Informasi konflik","Laporan tercatat","Segera, sebelum keputusan"],["5","Penilaian: Menilai tingkat konflik (rendah, sedang, tinggi), keterkaitan dengan keputusan, dan menetapkan langkah pengelolaan.","Irjen","Laporan, register","Penilaian dan rekomendasi","2 hari kerja"],["6","Pengelolaan: Menetapkan pengecualian diri, pengalihan tugas, pengganti pemeriksa, atau pengawasan tambahan; mencatat pada notulen.","Presiden dan Irjen","Rekomendasi","Langkah pengelolaan","2 hari kerja"],["7","Pelaksanaan dan pemantauan: Memastikan pengurus berkepentingan tidak ikut memengaruhi keputusan; Irjen memantau.","Pemimpin rapat, Irjen","Langkah pengelolaan","Pengecualian terlaksana","Selama proses"],["8","Peninjauan berkala: Memperbarui deklarasi tiap semester dan saat perubahan jabatan atau keadaan.","Pengurus, Sekjen","Register","Register diperbarui","Setiap semester"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Deklarasi awal terkumpul paling lambat 7 hari kerja setelah pelantikan dan penilaian konflik yang dilaporkan diselesaikan paling lambat 2 hari kerja (usulan). Hasil akhir: Register Kepentingan terkini dan keputusan yang bebas konflik."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Konflik menyangkut Presiden atau Wakil Presiden: Irjen menilai dan melaporkan kepada KAUR ORMAWA; yang bersangkutan tidak ikut memutus.","Konflik menyangkut Irjen: Presiden menunjuk pemeriksa pengganti sementara dengan sepengetahuan KAUR ORMAWA.","Pengecualian diri menyebabkan kuorum tidak terpenuhi: penundaan atau pelaksanaan melalui SOP- GOV-012 dengan persetujuan Pembina bila perlu.","Konflik yang menimbulkan kerugian dana atau aset: SOP-RSK-007; pelanggaran disiplin: SOP-RSK- 004.","Rangkap jabatan yang tidak memenuhi syarat AD Pasal 8 ayat (7): pengurus memilih salah satu jabatan; pengesahan diminta dari KAUR ORMAWA."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pengurus mengisi Deklarasi Kepentingan paling lambat 7 hari kerja setelah pelantikan.","100% rapat seleksi dan pengadaan mencatat pertanyaan konflik kepentingan.","Tidak ada keputusan yang ditinjau ulang karena konflik tersembunyi.","Register Kepentingan diperbarui setiap semester."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Deklarasi Kepentingan.","Register Kepentingan.","Catatan penilaian dan langkah pengelolaan.","Catatan pengecualian diri pada notulen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Risiko dan Etika) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa Register Kepentingan setiap semester dan sampel keputusan pengadaan dan seleksi; Sekretaris Jenderal memastikan pengecualian diri tercatat pada notulen."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Deklarasi awal → Catat di register → Periksa sebelum proses → Lapor konflik → Penilaian Irjen → Pengelolaan → Pelaksanaan dan pemantauan → Tinjau berkala → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Deklarasi Kepentingan","Nama; jabatan; jabatan di ORMAWA lain; hubungan keluarga atau kemitraan relevan; hadiah diterima; pernyataan; tanggal; tanda tangan."],["Register Kepentingan","Nama; konflik; proses terkait; penilaian; langkah pengelolaan; tanggal; status."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh pengurus telah mengisi deklarasi.","☐ Ya ☐ Tidak"],["2","Rangkap jabatan beserta syarat AD tercatat.","☐ Ya ☐ Tidak"],["3","Konflik ditanyakan sebelum rapat, seleksi, dan pengadaan.","☐ Ya ☐ Tidak"],["4","Pengurus berkepentingan mengecualikan diri dan dicatat pada notulen.","☐ Ya ☐ Tidak"],["5","Penilaian dan langkah pengelolaan terdokumentasi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-RSK-007","g":"Risiko, Etika, dan Penanganan Masalah","t":"Penanganan Dugaan Penyalahgunaan Dana atau Aset","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[276,280],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengamanan, pemeriksaan, pemulihan, dan tindak lanjut dugaan penyalahgunaan dana atau aset BEM secara cepat, adil, dan terdokumentasi, sehingga kerugian dibatasi, amanah dijaga, dan pertanggungjawaban kepada pihak berwenang terpenuhi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk dugaan korupsi, manipulasi, penyelewengan, penggunaan tanpa hak, pemalsuan bukti, atau kehilangan janggal atas dana dan aset BEM, termasuk dana kegiatan, sponsor, donasi, dan inventaris. Kehilangan atau kerusakan aset tanpa dugaan penyalahgunaan diatur SOP-AST-007; selisih anggaran biasa diatur SOP-KEU-014."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 (sumber dan prinsip keuangan: terhindar dari riba, gharar, dan maysir; bukti penerimaan resmi) dan Pasal 17 (laporan pertanggungjawaban kepada BPM dan KAUR ORMAWA).","AD Pasal 9 ayat (2) huruf b sampai d (pemberhentian karena tindakan merugikan kampus dan organisasi, atau tindak pidana).","ART Pasal 3 (Kewajiban) huruf e dan g (mengelola keuangan secara amanah dan membuat laporan).","ART Pasal 11 huruf i dan k (larangan korupsi, manipulasi, penyelewengan dana, dan penggunaan fasilitas untuk kepentingan pribadi).","ART Pasal 12 ayat (6) sampai (8) dan Pasal 13 (pemeriksaan Irjen, pelaporan pelanggaran berat, hak klarifikasi).","SOP-KEU-016, SOP-KEU-017, SOP-RSK-004, dan SOP-RSK-006."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Penyalahgunaan","Penggunaan dana atau aset BEM di luar peruntukan, tanpa persetujuan, atau untuk keuntungan pribadi atau pihak lain."],["Pembekuan sementara","Pembatasan sementara akses dana atau aset yang diduga disalahgunakan, tanpa menyatakan seseorang bersalah."],["Pemeriksaan keuangan khusus","Penelusuran bukti transaksi, saldo, dan penggunaan terkait dugaan oleh pihak yang tidak terlibat."],["Kerugian","Selisih dana atau nilai aset yang hilang, rusak, atau berpindah tanpa dasar yang sah."],["Pengembalian","Penggantian dana atau aset oleh pihak yang bertanggung jawab atas kerugian."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap dugaan wajib ditelaah, tidak ditutup-tutupi, dan tidak diselesaikan hanya dengan kesepakatan lisan.","Pembekuan sementara rekening, kartu, dana kegiatan, atau aset dapat dilakukan Presiden atas usulan Irjen sambil menunggu pemeriksaan, dengan pemberitahuan kepada KAUR ORMAWA bila dana kemahasiswaan kampus terlibat.","Klasifikasi usulan: ringan (kesalahan administrasi tanpa kerugian); sedang (kerugian terbatas atau bukti tidak lengkap); berat (kerugian signifikan, pemalsuan, atau niat memperkaya diri). Ambang nilai ditetapkan Rapat Pimpinan setelah uji coba.","Pemeriksa harus orang yang tidak terlibat dan tidak berkonflik kepentingan (SOP-RSK-006). Bila Bendahara, Biro Keuangan, atau BPH terlibat, Irjen melapor kepada KAUR ORMAWA dan BPM dan Presiden tidak mengintervensi pemeriksaan.","Terlapor berhak klarifikasi dan pembelaan (ART Pasal 13 ayat 9). Putusan hanya berdasarkan bukti.","Pengembalian kerugian tidak menghapus pelanggaran dan tidak menggantikan sanksi; kesepakatan pengembalian dibuat tertulis dan disetujui pimpinan.","Dugaan tindak pidana: Pembina menentukan pelaporan kepada pihak berwenang. Dana atau transaksi yang mengandung riba, gharar, atau maysir ditelaah juga dari sisi syariat (AD Pasal 15 ayat 2).","Pelanggaran berat yang berdampak pada institusi dilaporkan Irjen kepada KAUR ORMAWA (ART Pasal 12 ayat 7); hasil keuangan juga dilaporkan pada pertanggungjawaban kepada BPM (AD Pasal 17)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pelapor","R","Menyampaikan dugaan beserta bukti yang ada melalui SOP-RSK-004."],["Inspektur Jenderal","A","Menelaah, memeriksa, mengusulkan pembekuan sementara, dan menyusun laporan hasil."],["Sekretaris Jenderal","R","Mencatat, menyiapkan dokumen, dan menjaga arsip terbatas."],["Biro Keuangan / Bendahara","R","Menyediakan data keuangan dan melaksanakan pembekuan sementara; tidak ikut memeriksa bila terlibat."],["Presiden","A","Menetapkan pembekuan sementara dan keputusan tindak lanjut dalam kewenangan."],["Wakil Presiden","R","Memastikan kegiatan tetap berjalan dan mengatur pengganti sementara."],["Terlapor","C","Memberi klarifikasi dan membantu penelusuran bukti."],["BPM","I","Diberi laporan sesuai AD Pasal 17 ayat (3) dan ART Pasal 12 ayat (8)."],["Pembina / KAUR ORMAWA","I","Diberi laporan dugaan sedang dan berat dan menentukan pelaporan kepada pihak berwenang."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan dugaan dan bukti (bukti transaksi, mutasi rekening, nota, dokumen aset).","Anggaran, LPJ, dan catatan kas terkait.","Daftar inventaris dan catatan peminjaman aset.","Keterangan saksi dan pihak yang berwenang atas dana atau aset."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan dan pencatatan: Menerima dugaan melalui saluran SOP-RSK-004 dan mencatat pada register terbatas dengan menjaga kerahasiaan pelapor.","Irjen dan Sekjen","Laporan, bukti","Laporan tercatat","1 hari kerja"],["2","Penelaahan awal: Menilai kelayakan dugaan, klasifikasi awal, urgensi pembekuan sementara, dan konflik kepentingan.","Irjen","Laporan, data keuangan","Hasil telaah dan klasifikasi","2 hari kerja"],["3","Pengamanan sementara: Bila perlu, membekukan akses dana atau aset, mengamankan dokumen, dan mengganti penanggung jawab sementara; memberi tahu KAUR ORMAWA bila dana kampus terlibat.","Presiden atas usulan Irjen","Hasil telaah","Keputusan pengamanan","Maks. 24 jam setelah usulan"],["4","Pemeriksaan keuangan khusus: Mencocokkan bukti, mutasi, nota, kas, dan inventaris dengan catatan; menghitung kerugian; mengambil keterangan saksi.","Irjen (dengan pemeriksa yang tidak terlibat)","Bukti, catatan keuangan","Temuan sementara","Sedang 10 hari kerja; berat 14 hari kerja"],["5","Klarifikasi: Memberi terlapor kesempatan menjelaskan dan menyertakan bukti pembelaan.","Irjen","Temuan sementara","Berita Acara Klarifikasi","3 hari kerja"],["6","Laporan hasil: Menyusun Laporan Hasil Pemeriksaan: fakta, nilai kerugian, temuan, klasifikasi, dan usulan sanksi serta pemulihan.","Irjen","Berita acara, temuan","Laporan Hasil Pemeriksaan","3 hari kerja"],["7","Keputusan dan pelaporan: Memutuskan sanksi dan pemulihan melalui musyawarah (SOP-GOV-002) tanpa pihak berkonflik; melaporkan pelanggaran berat kepada KAUR ORMAWA dan hasil keuangan kepada BPM.","Presiden / BPH; Irjen","Laporan hasil","Keputusan; surat laporan","5 hari kerja"],["8","Pemulihan: Menetapkan jadwal pengembalian, memperbaiki pencatatan, dan menutup celah pengendalian.","Biro Keuangan dan Irjen","Keputusan","Pemulihan tercatat","Sesuai kesepakatan"],["9","Penutupan dan pembelajaran: Menutup kasus, mencatat penyebab dan tindakan korektif pada SOP-RSK- 012.","Sekjen dan Irjen","Dokumen kasus","Kasus ditutup; tindakan korektif","7 hari kerja setelah pemulihan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pengamanan sementara diputuskan paling lambat 24 jam setelah diusulkan dan pemeriksaan ditargetkan selesai paling lambat 14 hari kerja (sedang) dan 21 hari kerja (berat) (usulan). Hasil akhir: Laporan Hasil Pemeriksaan, Keputusan Tindak Lanjut, dan rencana pemulihan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pihak yang diduga adalah Bendahara, Biro Keuangan, atau BPH: pembekuan dan pemeriksaan tidak dilakukan oleh yang bersangkutan; Irjen melapor kepada KAUR ORMAWA dan BPM.","Pihak yang diduga adalah Irjen: Presiden menunjuk pemeriksa pengganti sementara dengan sepengetahuan KAUR ORMAWA.","Dugaan tindak pidana atau kerugian signifikan: Pembina menentukan pelaporan kepada pihak berwenang; BEM tidak menyelesaikannya hanya secara internal.","Kegiatan berjalan membutuhkan dana saat pembekuan: Presiden menunjuk pengelola sementara melalui SOP-GOV-009 dan SOP-KEU-006.","Aset hilang tanpa dugaan penyalahgunaan: SOP-AST-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Pengamanan sementara diputuskan dalam 24 jam pada minimal 90% kasus.","100% kasus memiliki laporan hasil yang didukung bukti.","100% kasus sedang dan berat dilaporkan kepada KAUR ORMAWA atau BPM.","Nilai kerugian yang dipulihkan sesuai keputusan.","Celah pengendalian yang ditemukan ditutup melalui tindakan korektif."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan dugaan dan catatan register terbatas.","Keputusan pembekuan sementara.","Berita Acara Klarifikasi dan Laporan Hasil Pemeriksaan.","Keputusan Tindak Lanjut dan rencana pemulihan.","Surat laporan kepada KAUR ORMAWA atau BPM. Seluruh dokumen disimpan pada repositori resmi BEM (folder Risiko dan Etika, akses terbatas sesuai SOP- RSK-010) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen melaporkan statistik anonim dan status pemulihan setiap bulan pada Rapat Kabinet; Sekretaris Jenderal memeriksa pembatasan akses berkas dan catatan tindakan korektif."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima dan catat → Telaah awal → Pengamanan sementara → Pemeriksaan keuangan khusus → Klarifikasi → Laporan hasil → Keputusan dan pelaporan → Pemulihan → Penutupan dan pembelajaran → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan Dugaan Penyalahgunaan","Pelapor (dapat dirahasiakan); dana atau aset terkait; kegiatan; dugaan penyimpangan; perkiraan nilai; bukti; saksi; tanggal."],["Berita Acara Pemeriksaan Keuangan Khusus","Objek periksa; periode; prosedur; temuan; nilai selisih; pemeriksa; tanggal."],["Keputusan Pengamanan dan Tindak Lanjut","Kasus; klasifikasi; pembekuan; sanksi; kewajiban pengembalian; jadwal; penanggung jawab."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Laporan tercatat, pelapor dilindungi, dan konflik kepentingan diperiksa.","☐ Ya ☐ Tidak"],["2","Pengamanan sementara dipertimbangkan dan diputuskan secara tertulis.","☐ Ya ☐ Tidak"],["3","Pemeriksa tidak terlibat dan terlapor diberi kesempatan klarifikasi.","☐ Ya ☐ Tidak"],["4","Pelanggaran sedang dan berat dilaporkan kepada KAUR ORMAWA atau BPM.","☐ Ya ☐ Tidak"],["5","Pemulihan kerugian dan tindakan korektif tercatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-RSK-008","g":"Risiko, Etika, dan Penanganan Masalah","t":"Pengamanan Data dan Akses Digital","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[281,284],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan standar pengamanan akun, perangkat, penyimpanan, dan hak akses digital BEM serta data pribadi pengurus dan peserta, sehingga data terlindungi dari akses tanpa hak, kehilangan, dan penyalahgunaan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh akun resmi organisasi (surel, penyimpanan awan, media sosial, platform koordinasi), perangkat yang dipakai mengelola data BEM, serta dokumen digital. SOP ini tidak mengatur penamaan berkas dan struktur folder (SOP-ADM-014), pengelolaan akses akun secara administratif (SOP-KOM-013), atau penanganan kebocoran (SOP-RSK-009)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Kewajiban) huruf d dan h (menjaga nama baik dan mematuhi peraturan kampus).","ART Pasal 11 huruf g dan k (larangan mencemarkan nama baik dan menyalahgunakan fasilitas atau nama organisasi).","ART Pasal 12 ayat (3) (pengawasan Irjen).","SOP-ADM-015 (hak akses, pencadangan, dan pemulihan), SOP-KOM-013, dan SOP-RSK-010.","Peraturan kampus dan peraturan perundang-undangan tentang pelindungan data pribadi, sepanjang berlaku."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Akun resmi","Akun digital yang dibuat atas nama BEM atau jabatan, bukan akun pribadi."],["Hak akses","Kewenangan melihat, mengubah, membagikan, atau menghapus data dan akun."],["Prinsip hak minimum","Setiap pengurus hanya memiliki akses yang dibutuhkan untuk tugasnya."],["Verifikasi dua langkah","Pengamanan akun dengan kode tambahan selain kata sandi."],["Data pribadi","Data yang dapat mengenali seseorang, misalnya nama lengkap, nomor induk, kontak, alamat, foto, dan data kesehatan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Akun resmi dibuat atas nama jabatan, didaftarkan pada Register Akun, dan memiliki dua pengelola yaitu pemegang utama dan cadangan. Pemegang utama bukan satu-satunya yang mengetahui cara pemulihan akun.","Verifikasi dua langkah wajib diaktifkan pada akun resmi. Kata sandi tidak dibagikan melalui grup percakapan, tidak ditulis di tempat umum, dan diganti saat pengurus berganti.","Akses diberikan menurut prinsip hak minimum dan ditinjau setiap 3 bulan serta saat pengurus berhenti, berganti jabatan, atau kegiatan selesai.","Data pribadi dikumpulkan hanya sebatas kebutuhan, disimpan pada penyimpanan resmi dengan akses terbatas, dan dihapus setelah masa simpan berakhir (SOP-RSK-010).","Berkas penting dicadangkan paling sedikit sekali seminggu pada penyimpanan resmi kedua.","Perangkat pribadi yang dipakai mengakses data BEM wajib berkunci layar dan, bila memungkinkan, disimpan tanpa unduhan data pribadi peserta.","Tautan berbagi berkas tidak diatur \"siapa saja dengan tautan\" untuk berkas yang memuat data pribadi atau informasi sensitif.","Kehilangan perangkat, akun diretas, atau kecurigaan akses tanpa hak segera dilaporkan kepada Sekjen sesuai SOP-RSK-009."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan standar pengamanan dan menyetujui pembuatan atau penutupan akun resmi."],["Sekretaris Jenderal","R","Memelihara Register Akun dan hak akses, memantau kepatuhan, dan memimpin tinjauan akses."],["Pemegang akun (utama dan cadangan)","R","Mengamankan akun, mengaktifkan verifikasi dua langkah, dan melapor bila ada kejanggalan."],["Biro Desain Komunikasi Visual","R","Mengamankan akun media sosial dan aset visual."],["Menteri / Kabiro","R","Mengajukan dan mencabut akses anggota unit."],["Seluruh pengurus","R","Mematuhi aturan penggunaan akun dan menjaga data pribadi."],["Inspektur Jenderal","C","Memeriksa kepatuhan dan mengaudit hak akses."],["Pihak teknologi informasi kampus","C","Dimintai bantuan teknis bila diperlukan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar akun, penyimpanan, dan perangkat yang dipakai organisasi.","Daftar pengurus dan jabatannya.","Daftar data pribadi yang dikelola.","Aturan kampus tentang penggunaan sistem informasi, bila ada."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Inventarisasi: Mendata seluruh akun, penyimpanan, perangkat, dan data pribadi yang dikelola setiap unit.","Sekjen dan Menteri / Kabiro","Daftar unit","Register Akun dan Aset Data","7 hari kerja setelah kabinet terbentuk"],["2","Pengamanan akun: Menetapkan pemegang utama dan cadangan, mengaktifkan verifikasi dua langkah, dan mengubah kata sandi awal.","Pemegang akun","Register Akun","Akun aman tercatat","7 hari kerja"],["3","Pemberian akses: Memberi akses sesuai hak minimum berdasarkan permintaan tertulis unit dan persetujuan Sekjen.","Menteri / Kabiro; Sekjen","Permintaan akses","Hak akses tercatat","2 hari kerja"],["4","Pencadangan: Mencadangkan berkas penting pada penyimpanan resmi kedua dan menguji pemulihan sampel.","Sekjen dan admin dokumen","Berkas penting","Cadangan terbarui","Setiap minggu; uji pemulihan tiap 3 bulan"],["5","Tinjauan akses: Meninjau seluruh hak akses, mencabut akses yang tidak diperlukan, dan memperbarui register.","Sekjen dan Irjen","Register Akun, daftar pengurus","Laporan tinjauan akses","Setiap 3 bulan"],["6","Pencabutan akses: Mencabut akses pengurus yang berhenti, berpindah jabatan, atau kegiatan yang selesai dan mengganti kata sandi akun bersama.","Sekjen dan pemegang akun","Pemberitahuan perubahan pengurus","Akses dicabut tercatat","Maks. 2 hari kerja setelah perubahan"],["7","Pelaporan kejanggalan: Melaporkan akun diretas, perangkat hilang, atau akses mencurigakan kepada Sekjen; penanganan lanjut mengikuti SOP-RSK-009.","Pengurus","Informasi kejanggalan","Laporan tercatat","Segera, maks. 6 jam"],["8","Pemeriksaan kepatuhan: Memeriksa pelaksanaan pengamanan dan melaporkan temuan.","Irjen","Register, hasil tinjauan","Catatan pemeriksaan","Setiap 6 bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pengamanan akun resmi diselesaikan paling lambat 7 hari kerja setelah kabinet terbentuk dan akses pengurus yang berhenti dicabut paling lambat 2 hari kerja (usulan). Hasil akhir: Register Akun dan Aset Data, hak akses sesuai prinsip hak minimum, dan cadangan terbaru."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pemegang utama akun tidak dapat dihubungi: pemegang cadangan atau Sekjen mengambil alih sesuai SOP-GOV-009.","Akun diretas atau data bocor: SOP-RSK-009 didahulukan.","Pengurus keberatan menyerahkan akses saat berhenti: Sekjen melaporkan kepada Presiden; pelanggaran ditangani sesuai SOP-RSK-004.","Kebutuhan akses mendesak di luar prosedur: diputuskan Presiden dan dicatat sesuai SOP-GOV-012.","Penggunaan layanan digital yang tidak disetujui kampus: dikonsultasikan kepada KAUR ORMAWA."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% akun resmi memiliki pemegang utama, cadangan, dan verifikasi dua langkah.","100% akses pengurus yang berhenti dicabut dalam 2 hari kerja.","Tinjauan akses dilakukan setiap 3 bulan.","Cadangan mingguan tersedia dan pemulihan sampel berhasil.","Tidak ada data pribadi pada tautan berbagi publik."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Akun dan Aset Data.","Catatan pemberian dan pencabutan akses.","Laporan tinjauan akses dan pemeriksaan kepatuhan.","Catatan cadangan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Risiko dan Etika, akses terbatas sesuai SOP- RSK-010) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa Register Akun dan hak akses setiap 6 bulan, sedangkan Sekretaris Jenderal melaporkan hasil tinjauan akses setiap 3 bulan pada Rapat Pimpinan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Inventarisasi → Pengamanan akun → Pemberian akses → Pencadangan → Tinjauan akses berkala → Pencabutan akses → Pemeriksaan kepatuhan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Register Akun dan Aset Data","Nama akun; platform; pemegang utama dan cadangan; unit; verifikasi dua langkah; tanggal dibuat; tanggal tinjau; status."],["Formulir Permintaan dan Pencabutan Akses","Pemohon; unit; sumber daya; tingkat akses; alasan; persetujuan; tanggal mulai; tanggal berakhir."],["Laporan Tinjauan Akses","Tanggal; akun; pengguna; akses; temuan; tindakan; pemeriksa."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh akun resmi terdaftar dan memiliki pemegang cadangan.","☐ Ya ☐ Tidak"],["2","Verifikasi dua langkah aktif pada seluruh akun resmi.","☐ Ya ☐ Tidak"],["3","Hak akses sesuai prinsip hak minimum dan ditinjau berkala.","☐ Ya ☐ Tidak"],["4","Akses pengurus yang berhenti dicabut tepat waktu.","☐ Ya ☐ Tidak"],["5","Cadangan mingguan tersedia dan diuji.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-RSK-009","g":"Risiko, Etika, dan Penanganan Masalah","t":"Penanganan Kebocoran Data","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[285,289],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan langkah cepat menangani dugaan atau kejadian kebocoran, kehilangan, atau akses tanpa hak atas data BEM dan data pribadi, sehingga kerugian dibatasi, pihak terdampak diberi tahu, dan perbaikan pencegahan dilakukan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk kebocoran data akibat akun diretas, perangkat hilang, berkas terbagi ke pihak tidak berwenang, salah kirim, atau penyebaran tanpa izin, baik disengaja maupun tidak. SOP ini tidak mengatur pengamanan rutin (SOP-RSK-008) dan tidak mengatur pengelolaan informasi sensitif (SOP-RSK-010)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Kewajiban) huruf d dan e (menjaga nama baik dan mengelola secara amanah).","ART Pasal 11 huruf g dan k (larangan pencemaran nama baik dan penyalahgunaan fasilitas atau nama organisasi).","ART Pasal 12 ayat (7) (pelaporan pelanggaran berat yang berdampak pada institusi kepada KAUR ORMAWA).","ART Pasal 13 ayat (4) sampai (9) (laporan disertai bukti, keadilan, hak klarifikasi).","SOP-RSK-008, SOP-RSK-010, SOP-RSK-011, dan SOP-RSK-012."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kebocoran data","Terbukanya, hilangnya, atau tersebarnya data kepada pihak yang tidak berhak, disengaja atau tidak."],["Data terdampak","Data yang diketahui atau diduga ikut terbuka atau hilang."],["Pihak terdampak","Orang atau lembaga yang datanya terdampak kebocoran."],["Pembatasan dampak","Langkah menghentikan penyebaran, seperti mencabut akses, mengganti kata sandi, dan menghapus tautan."],["Klasifikasi kebocoran","Ringan (data umum, sedikit, terbatas); sedang (data pribadi terbatas atau internal sensitif); berat (data pribadi banyak, data keuangan, atau data rahasia, atau sudah menyebar publik). Usulan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Siapa pun yang mengetahui dugaan kebocoran wajib segera melapor kepada Sekjen. Pelaporan dengan itikad baik tidak dikenai sanksi, termasuk bila kebocoran berasal dari kelalaian sendiri.","Langkah pertama adalah membatasi dampak: mencabut akses, mengganti kata sandi, menghapus atau mencabut tautan, dan mengamankan perangkat. Pelaku atau penyebab dicari setelah dampak dibatasi.","Bukti (tangkapan layar, log akses, pesan) disimpan sebelum dihapus agar dapat diperiksa.","Pihak terdampak diberi tahu secara jujur dan segera pada kebocoran sedang dan berat, tanpa menyalahkan.","Kebocoran sedang dan berat dilaporkan kepada KAUR ORMAWA atau Pembina karena dapat berdampak pada institusi.","Dugaan pelanggaran oleh pengurus diproses melalui SOP-RSK-004 setelah fakta dikumpulkan; perilaku sengaja yang merugikan dapat dikenai sanksi.","Dugaan peretasan atau tindak pidana: Pembina menentukan pelaporan kepada pihak berwenang."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pelapor","R","Melapor segera dan menyimpan bukti."],["Sekretaris Jenderal","A","Memimpin penanganan teknis dan koordinasi serta menyusun laporan kebocoran."],["Pemegang akun terkait","R","Mencabut akses, mengganti kata sandi, dan memulihkan akun."],["Presiden","A","Menetapkan klasifikasi sedang dan berat, keputusan pemberitahuan, dan keputusan publik."],["Wakil Presiden","R","Mengoordinasikan unit dan pendampingan pihak terdampak."],["Inspektur Jenderal","C","Menelaah penyebab dan kepatuhan; memproses dugaan pelanggaran bila ada."],["Biro Desain Komunikasi Visual","C","Menyusun pernyataan bila perlu (SOP-RSK-011)."],["Pihak teknologi informasi kampus","C","Memberi bantuan teknis."],["Pembina / KAUR ORMAWA","I","Diberi laporan kebocoran sedang dan berat."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan dugaan kebocoran dan bukti awal.","Register Akun dan Aset Data (SOP-RSK-008).","Daftar data pribadi dan pihak terdampak.","Log akses atau riwayat aktivitas yang tersedia."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pelaporan: Melaporkan kejadian kepada Sekjen melalui kanal resmi atau telepon, disertai bukti yang ada.","Pelapor","Dugaan dan bukti","Laporan tercatat","Segera, maks. 6 jam sejak diketahui"],["2","Pembatasan dampak: Mencabut akses, mengganti kata sandi, mencabut tautan, mengamankan atau menghapus jarak jauh perangkat hilang, dan menyimpan bukti.","Pemegang akun dan Sekjen","Laporan","Dampak dibatasi","Maks. 2 jam setelah laporan"],["3","Penilaian dan klasifikasi: Menentukan data yang terdampak, jumlah dan pihak terdampak, serta klasifikasi; kebocoran sedang dan berat dibawa kepada Presiden.","Sekjen dan Irjen","Laporan, log","Klasifikasi dan daftar terdampak","Maks. 12 jam"],["4","Keputusan penanganan: Menetapkan pemberitahuan kepada pihak terdampak dan kampus serta perlu tidaknya pernyataan publik atau pelaporan kepada pihak berwenang.","Presiden","Klasifikasi","Keputusan penanganan","Maks. 24 jam"],["5","Pemberitahuan: Memberi tahu pihak terdampak dan KAUR ORMAWA atau Pembina dengan bahasa jujur, jelas, dan tidak menyalahkan, disertai langkah perlindungan.","Sekjen dan Wapres","Keputusan penanganan","Pemberitahuan terkirim","Sedang maks. 48 jam; berat maks. 24 jam"],["6","Pemulihan: Memulihkan akun dan data dari cadangan, menutup celah, dan memantau penyalahgunaan lanjutan.","Sekjen dan pemegang akun","Cadangan, log","Sistem pulih","Sesuai tingkat, target 7 hari kerja"],["7","Pemeriksaan penyebab: Menelusuri sebab dan memeriksa dugaan pelanggaran; bila ada, diproses melalui SOP-RSK-004.","Irjen","Bukti, log","Laporan penyebab","7 hari kerja"],["8","Tindakan korektif: Menetapkan perbaikan (kebijakan akses, pelatihan, perangkat) dan mencatat pada SOP-RSK-012.","Sekjen","Laporan penyebab","Tindakan korektif","7 hari kerja setelah laporan penyebab"],["9","Penutupan: Menutup kasus dan melaporkan hasil pada forum resmi BEM tanpa membuka data pribadi.","Sekjen dan Irjen","Dokumen kasus","Kasus ditutup","7 hari kerja setelah pemulihan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dampak dibatasi paling lambat 2 jam setelah laporan dan pimpinan diberi tahu kejadian sedang dan berat paling lambat 12 jam (usulan). Hasil akhir: dampak terbatas, pihak terdampak diberi tahu, Laporan Kebocoran Data, dan tindakan korektif."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kebocoran melibatkan akun Sekjen: Wakil Presiden mengambil alih koordinasi dan Irjen mengawasi.","Kebocoran meluas ke pihak kampus atau publik: Presiden menyampaikan kepada KAUR ORMAWA dan SOP-RSK-011 dijalankan.","Data terdampak berupa data keuangan atau dana: SOP-RSK-007 juga dijalankan.","Pelaku diduga pengurus: dugaan pelanggaran diproses SOP-RSK-004; pelaku tidak dilibatkan dalam penanganan.","Ancaman atau pemerasan berkaitan data: dilaporkan kepada Pembina dan pihak berwenang."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Dampak dibatasi dalam 2 jam pada minimal 90% kejadian.","100% kebocoran sedang dan berat diberitahukan kepada KAUR ORMAWA atau Pembina.","100% kasus memiliki laporan penyebab dan tindakan korektif.","Kebocoran berulang pada penyebab yang sama menurun."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan Kebocoran Data.","Keputusan penanganan dan bukti pemberitahuan.","Laporan penyebab dan tindakan korektif.","Catatan insiden pada register. Seluruh dokumen disimpan pada repositori resmi BEM (folder Risiko dan Etika, akses terbatas sesuai SOP- RSK-010) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal melaporkan seluruh kejadian setiap bulan pada Rapat Pimpinan dan Irjen memeriksa kepatuhan batas waktu dan tindakan korektif."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Laporan kejadian → Pembatasan dampak → Penilaian dan klasifikasi → Keputusan Presiden → Pemberitahuan → Pemulihan → Pemeriksaan penyebab → Tindakan korektif → Penutupan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan Kebocoran Data","Pelapor; waktu diketahui; jenis data; akun atau perangkat; kronologi singkat; langkah awal; bukti."],["Laporan Kebocoran Data","Klasifikasi; data terdampak; pihak terdampak; penyebab; langkah pembatasan; pemberitahuan; pemulihan; tindakan korektif."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Dampak dibatasi dan bukti disimpan sebelum perubahan.","☐ Ya ☐ Tidak"],["2","Klasifikasi dan keputusan Presiden tercatat.","☐ Ya ☐ Tidak"],["3","Pihak terdampak dan kampus diberi tahu sesuai klasifikasi.","☐ Ya ☐ Tidak"],["4","Pemulihan akun dan data dilakukan dari cadangan.","☐ Ya ☐ Tidak"],["5","Penyebab diperiksa dan tindakan korektif dicatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-RSK-010","g":"Risiko, Etika, dan Penanganan Masalah","t":"Pengelolaan Informasi Sensitif","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[290,294],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara mengklasifikasikan, menyimpan, membagikan, mengakses, dan menghapus informasi sensitif BEM, termasuk berkas pengaduan, data pribadi, dokumen keuangan, dan dokumen rahasia, agar kerahasiaan terjaga dan tetap dapat dipertanggungjawabkan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus dan panitia yang menerima, mengelola, atau membagikan informasi sensitif BEM dalam bentuk fisik maupun digital. Pengelolaan dokumen rahasia secara administratif mengikuti SOP- ADM-020; pengamanan akun mengikuti SOP-RSK-008."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Kewajiban) huruf d, e, dan g (menjaga nama baik, mengelola secara amanah, dan melapor kepada pihak berwenang).","ART Pasal 11 huruf g, i, dan k (larangan pencemaran nama baik, penyelewengan, dan penyalahgunaan fasilitas atau nama organisasi).","ART Pasal 12 ayat (3) dan (6) serta Pasal 13 ayat (6) (pengawasan Irjen dan penyampaian hasil melalui forum resmi).","AD Pasal 17 ayat (3) (laporan pertanggungjawaban kepada BPM dan KAUR ORMAWA).","SOP-RSK-004, SOP-RSK-008, dan SOP-ADM-020."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Informasi sensitif","Informasi yang bila terbuka dapat merugikan orang atau organisasi, seperti identitas pelapor, data pribadi, kasus, keuangan internal, dan strategi organisasi."],["Tingkat kerahasiaan","Umum; internal (hanya pengurus); terbatas (hanya pihak tertentu); rahasia (hanya pihak yang ditunjuk tertulis)."],["Prinsip perlu-tahu","Informasi hanya diberikan kepada pihak yang membutuhkannya untuk tugas."],["Masa simpan","Jangka waktu informasi disimpan sebelum diarsipkan atau dimusnahkan."],["Pernyataan Kerahasiaan","Surat pernyataan pengurus untuk menjaga kerahasiaan informasi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Klasifikasi usulan: rahasia (berkas pengaduan, identitas pelapor dan korban, kasus disiplin); terbatas (data pribadi, data keuangan rinci, keputusan sebelum diumumkan); internal (notulen rapat, rencana program); umum (publikasi resmi).","Informasi dibagikan hanya sesuai prinsip perlu-tahu dan melalui kanal resmi yang diberi akses; tidak melalui grup percakapan umum atau akun pribadi.","Pengurus yang menangani informasi rahasia dan terbatas menandatangani Pernyataan Kerahasiaan. Kerahasiaan tetap berlaku setelah masa jabatan berakhir.","Berkas pengaduan dan kasus disimpan pada folder terbatas dengan daftar yang berhak mengakses; setiap akses tercatat.","Data pribadi hanya dikumpulkan sebatas kebutuhan, disertai pemberitahuan tujuan, dan dihapus atau dianonimkan setelah masa simpan berakhir.","Pengecualian kerahasiaan: kewajiban melapor kepada KAUR ORMAWA, Pembina, atau pihak berwenang; keselamatan jiwa; dan permintaan tertulis pihak yang berwenang atas dana atau pemeriksaan.","Membocorkan informasi rahasia tanpa hak merupakan pelanggaran yang diproses melalui SOP-RSK- 004 dan, bila terjadi kebocoran, SOP-RSK-009.","Penyebaran informasi sensitif yang menyangkut kehormatan seseorang dijaga sesuai adab Islam dan prinsip tabayyun."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan klasifikasi dan daftar pihak berhak akses informasi rahasia."],["Sekretaris Jenderal","R","Mengelola folder terbatas, daftar akses, dan Pernyataan Kerahasiaan serta mencatat pembagian informasi."],["Inspektur Jenderal","R","Mengelola berkas pengaduan dan kasus dan memeriksa kepatuhan kerahasiaan."],["Pemilik informasi (unit)","R","Memberi label tingkat kerahasiaan dan meminta pembagian sesuai perlu-tahu."],["Seluruh pengurus dan panitia","R","Menjaga kerahasiaan dan melapor bila terjadi kebocoran."],["Wakil Presiden","C","Memberi masukan pembatasan akses unit."],["Pembina / KAUR ORMAWA","I","Diberi laporan pelanggaran kerahasiaan yang berdampak pada institusi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar jenis informasi yang dikelola.","Daftar pengurus dan jabatannya.","Register Akun dan hak akses (SOP-RSK-008).","Kebijakan kampus tentang data pribadi dan arsip, bila ada."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Klasifikasi: Pemilik informasi menandai tingkat kerahasiaan dokumen atau data saat dibuat atau diterima.","Pemilik informasi","Dokumen atau data","Label kerahasiaan","Saat dibuat atau diterima"],["2","Pernyataan kerahasiaan: Pengurus yang menangani informasi rahasia atau terbatas menandatangani Pernyataan Kerahasiaan.","Sekjen","Daftar pengurus","Pernyataan terkumpul","7 hari kerja setelah penunjukan"],["3","Penyimpanan: Menyimpan informasi pada folder atau lemari sesuai tingkat; berkas terbatas dan rahasia pada penyimpanan akses terbatas dan terkunci.","Sekjen dan Irjen","Dokumen berlabel","Dokumen tersimpan aman","1 hari kerja"],["4","Permintaan akses: Pemohon menjelaskan kebutuhan; pemilik atau Sekjen menyetujui sesuai perlu-tahu; akses dicatat pada Daftar Akses.","Pemohon; Sekjen atau pemilik","Permintaan","Akses diberikan atau ditolak beralasan","2 hari kerja"],["5","Pembagian: Membagikan melalui kanal resmi dengan tautan terbatas, menandai kerahasiaan, dan tidak mengunggah ke grup umum.","Pengurus berwenang","Dokumen","Pembagian tercatat","Sesuai kebutuhan"],["6","Tinjauan akses: Meninjau daftar akses dan mencabut akses yang tidak lagi diperlukan.","Sekjen dan Irjen","Daftar Akses","Daftar Akses terbarui","Setiap 3 bulan dan saat pergantian pengurus"],["7","Penanganan pelanggaran: Pembocoran dilaporkan dan ditangani sesuai SOP-RSK-009 dan SOP-RSK- 004.","Sekjen dan Irjen","Laporan pembocoran","Kasus ditangani","Segera"],["8","Penyimpanan akhir dan pemusnahan: Setelah masa simpan berakhir, mengarsipkan atau memusnahkan informasi sesuai kebijakan; pemusnahan dicatat dan disaksikan dua orang.","Sekjen","Daftar masa simpan","Berita Acara Pemusnahan","Sesuai masa simpan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Label kerahasiaan diberikan saat dokumen dibuat, Pernyataan Kerahasiaan terkumpul paling lambat 7 hari kerja setelah penunjukan, dan akses ditinjau setiap 3 bulan (usulan). Hasil akhir: informasi sensitif tersimpan terbatas, akses tercatat, dan kebocoran dicegah."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kewajiban pelaporan kepada KAUR ORMAWA, Pembina, atau pihak berwenang: informasi dibuka sebatas yang diperlukan dan dicatat.","Keselamatan jiwa terancam: informasi dibuka kepada pihak yang dapat menolong (SOP-RSK-003).","Informasi rahasia terlanjur tersebar: SOP-RSK-009.","Permintaan informasi oleh pihak eksternal: dijawab Presiden setelah berkonsultasi dengan KAUR ORMAWA bila menyangkut institusi.","Perselisihan klasifikasi: diputuskan Wakil Presiden; bila belum selesai diputuskan Presiden."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pengurus penangan informasi rahasia menandatangani Pernyataan Kerahasiaan.","100% berkas pengaduan dan kasus tersimpan pada folder terbatas.","Daftar Akses ditinjau setiap 3 bulan.","Tidak ada informasi rahasia pada grup percakapan umum.","Pemusnahan informasi tercatat pada 100% kasus."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Klasifikasi Informasi.","Pernyataan Kerahasiaan.","Daftar Akses folder terbatas.","Berita Acara Pemusnahan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Risiko dan Etika, akses terbatas sesuai SOP- RSK-010) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa Daftar Akses dan kepatuhan kerahasiaan setiap 6 bulan, sedangkan Sekretaris Jenderal melaporkan ringkasan pembagian dan pembatasan akses pada Rapat Pimpinan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Klasifikasi → Pernyataan kerahasiaan → Penyimpanan terbatas → Permintaan dan pemberian akses → Pembagian terkendali → Tinjauan akses berkala → Pemusnahan atau arsip akhir → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Pernyataan Kerahasiaan","Nama; jabatan; jenis informasi; pernyataan menjaga kerahasiaan; berlaku setelah masa jabatan; tanggal; tanda tangan."],["Daftar Akses Informasi Terbatas","Dokumen atau folder; tingkat; pihak berhak; dasar akses; tanggal diberikan; tanggal dicabut; pemberi persetujuan."],["Berita Acara Pemusnahan","Dokumen; masa simpan; alasan; cara pemusnahan; saksi; tanggal; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Dokumen sensitif memiliki label tingkat kerahasiaan.","☐ Ya ☐ Tidak"],["2","Pernyataan Kerahasiaan tersedia untuk pengurus terkait.","☐ Ya ☐ Tidak"],["3","Berkas terbatas tersimpan pada penyimpanan akses terbatas.","☐ Ya ☐ Tidak"],["4","Daftar Akses ditinjau secara berkala.","☐ Ya ☐ Tidak"],["5","Pembagian dan pemusnahan tercatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-RSK-011","g":"Risiko, Etika, dan Penanganan Masalah","t":"Penanganan Krisis Reputasi","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[295,299],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan langkah cepat, satu suara, dan terkendali dalam menanggapi isu atau kejadian yang mengancam nama baik BEM, mahasiswa, atau STDI Imam Syafi'i Jember, agar kebenaran diklarifikasi dengan adab, kerugian dibatasi, dan kepercayaan dipulihkan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk isu negatif, berita tidak benar, kesalahan publikasi, kontroversi atau kritik besar di media sosial, kejadian kegiatan yang menjadi sorotan publik, dan dugaan pelanggaran oleh pengurus yang diketahui publik. SOP ini tidak mengatur pernyataan resmi rutin (SOP-KOM-010) dan koreksi publikasi biasa (SOP-KOM- 009)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Kewajiban) huruf d (menjaga nama baik STDIIS Jember dan menciptakan ketertiban serta kedamaian).","ART Pasal 11 huruf a, b, e, dan g (larangan SARA, penistaan agama, politik praktis tanpa izin, dan pencemaran nama baik).","ART Pasal 4 huruf e (mewakili mahasiswa dalam forum resmi sebagai pimpinan tertinggi eksekutif mahasiswa).","ART Pasal 12 ayat (7) (pelaporan pelanggaran berat yang berdampak pada institusi kepada KAUR ORMAWA).","SOP-GOV-007, SOP-GOV-012, SOP-RSK-003, SOP-RSK-009, dan SOP-KOM-010."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Krisis reputasi","Keadaan ketika isu atau kejadian berpotensi menurunkan kepercayaan publik atau kampus terhadap BEM dan perlu tanggapan segera."],["Juru bicara","Satu orang yang ditunjuk menyampaikan pernyataan atas nama BEM."],["Tim krisis","Presiden, Wakil Presiden, Sekretaris Jenderal, Irjen, dan Biro Desain Komunikasi Visual, bersama pihak terkait."],["Pernyataan resmi","Pernyataan tertulis atau lisan yang disetujui Presiden dan disampaikan melalui kanal resmi."],["Tingkat isu","Rendah (keluhan terbatas); sedang (menyebar di mahasiswa); tinggi (menyentuh kampus, publik luas, atau berkaitan SARA dan agama). Usulan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Prinsip: tabayyun sebelum menanggapi, jujur, cepat, santun, dan satu suara. Tidak membalas dengan emosi, tidak menyerang, dan tidak menyebar prasangka.","Hanya juru bicara yang menanggapi atas nama BEM. Pengurus lain tidak berkomentar sendiri di media sosial atau grup; pertanyaan diarahkan kepada juru bicara.","Isu tingkat sedang dan tinggi dilaporkan kepada KAUR ORMAWA atau Pembina sebelum atau bersamaan dengan pernyataan resmi bila menyangkut institusi.","Bila BEM atau pengurus bersalah, BEM mengakui, meminta maaf, dan memperbaiki. Bila isu tidak benar, BEM mengklarifikasi dengan bukti tanpa menyerang pihak lain.","Isu yang berkaitan dengan dugaan pelanggaran, kebocoran, atau dana ditangani paralel melalui SOP- RSK-004, SOP-RSK-009, atau SOP-RSK-007, dan pernyataan tidak boleh membuka identitas pihak yang dilindungi.","Penghapusan unggahan hanya dilakukan setelah arsip bukti dibuat, tidak untuk menyembunyikan kesalahan (SOP-KOM-009).","Dalam pernyataan dan unggahan dijaga adab Islam dan tidak mengandung SARA, politik praktis, atau pencemaran nama baik (ART Pasal 11)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pelapor isu","R","Menyampaikan isu atau tangkapan layar beserta sumbernya."],["Sekretaris Jenderal","R","Mencatat isu, mengumpulkan fakta, dan menyiapkan rapat."],["Biro Desain Komunikasi Visual","R","Memantau kanal, menyusun draf pernyataan, dan menerbitkannya setelah disetujui."],["Inspektur Jenderal","R","Memeriksa fakta dan kepatuhan prosedur bila isu berkaitan pelanggaran."],["Presiden","A","Menetapkan tingkat isu, menyetujui pernyataan, dan menunjuk juru bicara."],["Wakil Presiden","R","Mengoordinasikan unit terkait dan pemulihan hubungan."],["Juru bicara","R","Menyampaikan pernyataan dan menjawab pertanyaan sesuai bahan yang disetujui."],["Pembina / KAUR ORMAWA","C","Dimintai arahan dan persetujuan untuk isu yang menyangkut institusi."],["Seluruh pengurus","I","Diberi arahan untuk tidak berkomentar sendiri dan menyalurkan pertanyaan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Isu, tautan, tangkapan layar, dan sumber.","Fakta dan dokumen terkait kegiatan atau kejadian.","Pedoman publikasi dan identitas visual (SOP-KOM-007 dan SOP-KOM-014).","Catatan insiden terkait."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Deteksi dan pelaporan: Pengurus yang mengetahui isu segera melaporkan kepada Sekjen atau Biro Desain Komunikasi Visual tanpa berkomentar.","Pelapor","Isu dan sumber","Isu tercatat","Segera, maks. 3 jam"],["2","Verifikasi fakta: Memeriksa kebenaran, sumber, jangkauan, dan pihak terkait; mengamankan bukti.","Sekjen, Biro DKV, Irjen","Isu, dokumen","Ringkasan fakta","Maks. 6 jam"],["3","Penetapan tingkat: Menilai tingkat isu dan menetapkan tim krisis dan juru bicara.","Presiden","Ringkasan fakta","Tingkat isu; juru bicara","Maks. 6 jam setelah verifikasi"],["4","Rapat tim krisis: Membahas opsi tanggapan (klarifikasi, permintaan maaf, diam sementara, tindak lanjut) bersama pihak terkait; konsultasi kepada KAUR ORMAWA bila menyangkut institusi.","Presiden memimpin","Ringkasan fakta","Keputusan tanggapan","Maks. 12 jam (tinggi 6 jam)"],["5","Penyusunan pernyataan: Menyusun pernyataan yang jujur, singkat, santun, dan tanpa membuka data terlindungi; diperiksa Irjen untuk kesesuaian aturan.","Biro DKV","Keputusan tanggapan","Draf pernyataan","6 jam"],["6","Persetujuan dan penerbitan: Presiden menyetujui, pernyataan diterbitkan melalui kanal resmi, dan pengurus diberi arahan satu suara.","Presiden dan Biro DKV","Draf pernyataan","Pernyataan resmi terbit","Maks. 24 jam sejak isu diketahui"],["7","Pemantauan: Memantau tanggapan dan menjawab pertanyaan lewat juru bicara; memutuskan pernyataan lanjutan bila perlu.","Biro DKV dan juru bicara","Pernyataan, reaksi","Laporan pemantauan","Setiap hari selama isu berlangsung"],["8","Perbaikan dan pemulihan: Melaksanakan perbaikan nyata (koreksi, permintaan maaf, perubahan prosedur) dan memulihkan hubungan dengan pihak terdampak.","Wapres dan unit terkait","Keputusan","Perbaikan terlaksana","Sesuai rencana"],["9","Penutupan dan pembelajaran: Menutup isu, mencatat penyebab dan pembelajaran pada SOP-RSK-012, dan memperbarui pedoman komunikasi bila perlu.","Sekjen","Dokumen kasus","Catatan insiden","7 hari kerja setelah penutupan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Isu dilaporkan paling lambat 3 jam setelah diketahui dan pernyataan resmi diterbitkan paling lambat 24 jam bila diperlukan (usulan). Hasil akhir: tanggapan resmi yang disetujui, perbaikan terlaksana, dan catatan pembelajaran."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Isu menyangkut SARA, penistaan agama, atau pelanggaran syariat: Presiden segera berkonsultasi dengan KAUR ORMAWA atau Pembina sebelum menanggapi.","Presiden atau Wakil Presiden terlibat dalam isu: Sekjen dan Irjen memimpin dan melapor kepada KAUR ORMAWA; juru bicara ditunjuk Pembina atau Sekjen.","Isu berasal dari kejadian darurat atau korban: SOP-RSK-003 didahulukan; identitas korban tidak diumumkan tanpa persetujuan keluarga.","Isu berkaitan data atau dana: SOP-RSK-009 atau SOP-RSK-007 dijalankan bersamaan.","Isu berupa fitnah atau hoaks berat: Pembina menentukan langkah hukum atau pelaporan; BEM tidak membalas dengan serangan."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% isu sedang dan tinggi diverifikasi dalam 6 jam.","Pernyataan resmi terbit dalam 24 jam pada minimal 90% kasus yang memerlukan.","Tidak ada pengurus yang menanggapi sendiri di luar juru bicara.","100% isu sedang dan tinggi dilaporkan kepada KAUR ORMAWA atau Pembina.","Isu berulang pada penyebab yang sama menurun."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Catatan isu dan ringkasan fakta.","Keputusan tim krisis.","Pernyataan resmi dan arsip tanggapan.","Laporan pemantauan dan catatan insiden. Seluruh dokumen disimpan pada repositori resmi BEM (folder Risiko dan Etika) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa seluruh penanganan isu setiap bulan dan melaporkan pola pada Rapat Kabinet; Biro Desain Komunikasi Visual menjaga arsip pernyataan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Deteksi dan lapor → Verifikasi fakta → Penetapan tingkat dan juru bicara → Rapat tim krisis → Susun pernyataan → Persetujuan Presiden dan terbit → Pemantauan → Perbaikan dan pemulihan → Penutupan dan pembelajaran → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pelaporan Isu","Pelapor; waktu; sumber atau tautan; ringkasan isu; jangkauan; bukti; pihak terkait."],["Lembar Keputusan Tim Krisis","Isu; tingkat; fakta; opsi; keputusan; juru bicara; penanggung jawab; tenggat."],["Templat Pernyataan Resmi","Judul; fakta; sikap BEM; permintaan maaf bila perlu; langkah perbaikan; kontak juru bicara; tanggal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Fakta diverifikasi sebelum menanggapi.","☐ Ya ☐ Tidak"],["2","Tingkat isu dan juru bicara ditetapkan.","☐ Ya ☐ Tidak"],["3","Kampus diberi tahu dan dikonsultasikan bila menyangkut institusi.","☐ Ya ☐ Tidak"],["4","Pernyataan disetujui Presiden dan tidak membuka data terlindungi.","☐ Ya ☐ Tidak"],["5","Perbaikan dan pembelajaran dicatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-RSK-012","g":"Risiko, Etika, dan Penanganan Masalah","t":"Pencatatan Insiden dan Tindakan Korektif","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[300,303],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara mencatat seluruh insiden, menemukan penyebab, menetapkan tindakan korektif dan pencegahan, serta memantau penyelesaiannya, agar kejadian tidak berulang dan pembelajaran organisasi tersimpan lintas kabinet."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh insiden dan temuan pada BEM, baik kecelakaan, pelanggaran, kebocoran data, penyimpangan dana atau aset, isu reputasi, maupun kegagalan proses, termasuk temuan Irjen dan pengaduan yang telah ditutup. SOP ini tidak mengatur penanganan insiden itu sendiri (SOP-RSK-003 sampai SOP-RSK- 011)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 10 ayat (4) (Rapat Koordinasi: penyelesaian permasalahan internal).","ART Pasal 12 ayat (3) sampai (6) dan Pasal 13 ayat (5) sampai (6) (pengawasan, evaluasi, dan penyampaian hasil oleh Irjen).","AD Pasal 17 ayat (1) dan (2) (laporan pertanggungjawaban berkala dan tata kelola yang baik).","SOP-GOV-007 dan SOP-RSK-001.","SOP-MONEV-009 dan SOP-MONEV-010 (pencatatan temuan dan tindakan korektif)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Insiden","Kejadian yang menimbulkan atau berpotensi menimbulkan kerugian, cedera, pelanggaran, atau gangguan pada organisasi dan kegiatan."],["Nyaris celaka (near miss)","Kejadian yang hampir menimbulkan kerugian tetapi tidak terjadi."],["Penyebab akar","Sebab mendasar yang jika diperbaiki mencegah kejadian berulang."],["Tindakan korektif","Tindakan memperbaiki penyebab insiden yang telah terjadi."],["Tindakan pencegahan","Tindakan mencegah insiden serupa terjadi di unit atau kegiatan lain."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Seluruh insiden, termasuk nyaris celaka, dicatat dalam Register Insiden melalui kanal resmi paling lambat 2 hari kerja setelah penanganan awal selesai (kecuali kasus rahasia dicatat dengan kode).","Pencatatan bertujuan belajar, bukan menghukum. Pelaporan nyaris celaka tidak dikenai sanksi.","Insiden dengan kerahasiaan (pengaduan, pelecehan, dana, data) dicatat ringkas dengan kode dan tanpa identitas; berkas lengkap tetap pada folder terbatas (SOP-RSK-010).","Klasifikasi usulan: ringan, sedang, berat, mengikuti dampak terhadap ORMAWA dan institusi (ART Pasal 12 ayat 9).","Penyebab akar ditelusuri untuk insiden sedang dan berat dan masalah yang berulang. Setiap tindakan memiliki penanggung jawab dan tenggat.","Insiden berulang tiga kali pada penyebab yang sama dilaporkan pada Rapat Kabinet dan dimasukkan ke Register Risiko (SOP-RSK-001).","Pencatatan tidak menggantikan sanksi atau pemeriksaan yang diatur SOP lain."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menyetujui tindakan korektif untuk insiden berat dan prioritas perbaikan."],["Sekretaris Jenderal","R","Memelihara Register Insiden, memantau tindak lanjut, dan menyusun laporan."],["Pelapor / penanggung jawab penanganan","R","Menyampaikan Formulir Insiden dan data kejadian."],["Menteri / Kabiro","R","Melaksanakan tindakan korektif di unit dan melapor perkembangan."],["Wakil Presiden","R","Mengoordinasikan tindakan korektif lintas unit."],["Inspektur Jenderal","C","Menelaah penyebab, memeriksa efektivitas, dan memantau kepatuhan."],["Pembina / KAUR ORMAWA","I","Diberi ringkasan insiden berat atau berdampak pada institusi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Insiden dan laporan penanganan (SOP-RSK-003 sampai SOP-RSK-011).","Temuan Irjen dan hasil evaluasi.","Register Risiko dan catatan insiden sebelumnya."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pencatatan: Mengisi Formulir Insiden setelah penanganan awal: waktu, tempat, jenis, klasifikasi, dampak, pihak terkait (dengan kode untuk kasus rahasia), dan tindakan awal.","Penanggung jawab penanganan","Laporan penanganan","Formulir Insiden","2 hari kerja setelah penanganan awal"],["2","Registrasi: Memeriksa kelengkapan dan memasukkan ke Register Insiden dengan nomor urut.","Sekjen","Formulir","Entri register","1 hari kerja"],["3","Analisis penyebab: Menelusuri penyebab akar untuk insiden sedang dan berat dan masalah berulang; melibatkan pihak terkait tanpa menyalahkan.","Irjen dan unit terkait","Formulir, bukti","Catatan penyebab akar","Sedang 7 hari kerja; berat 10 hari kerja"],["4","Perencanaan tindakan: Menetapkan tindakan korektif dan pencegahan, penanggung jawab, tenggat, dan indikator.","Wapres dan Menteri / Kabiro","Catatan penyebab","Rencana Tindakan Korektif","5 hari kerja"],["5","Persetujuan: Menyetujui rencana; yang berdampak pada kebijakan dibahas pada Rapat Pimpinan atau Rapat Kabinet.","Presiden","Rencana tindakan","Rencana disetujui","3 hari kerja"],["6","Pelaksanaan: Melaksanakan tindakan dan mengunggah bukti pelaksanaan.","Penanggung jawab tindakan","Rencana disetujui","Bukti pelaksanaan","Sesuai tenggat"],["7","Pemantauan: Memantau status dan mengingatkan tindakan yang terlambat; keterlambatan dilaporkan pada Rapat Pimpinan.","Sekjen","Register","Status terbarui","Setiap 2 minggu"],["8","Verifikasi efektivitas: Memeriksa apakah tindakan menyelesaikan penyebab dan tidak ada kejadian berulang; bila belum efektif, tindakan diulang.","Irjen","Bukti, data insiden","Catatan verifikasi","30 hari setelah tindakan selesai"],["9","Penutupan dan pelaporan: Menutup insiden, memasukkan pembelajaran dan risiko baru pada Register Risiko, dan melaporkan ringkasan pada Rapat Kabinet.","Sekjen","Catatan verifikasi","Insiden ditutup; laporan ringkasan","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Insiden dicatat paling lambat 2 hari kerja setelah penanganan awal dan tindakan korektif insiden berat ditetapkan paling lambat 15 hari kerja (usulan). Hasil akhir: Register Insiden terkini, Rencana Tindakan Korektif yang terlaksana, dan laporan ringkasan bulanan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Insiden menyangkut kerahasiaan atau korban: pencatatan memakai kode dan tanpa identitas; akses berkas mengikuti SOP-RSK-010.","Penanggung jawab tindakan berhalangan: Sekjen mengusulkan pengganti kepada Wakil Presiden.","Tindakan korektif membutuhkan perubahan kebijakan atau SOP: diajukan melalui SOP-GOV-011.","Tindakan korektif membutuhkan dana: pengajuan melalui SOP-KEU-014.","Pelanggaran berulang oleh pengurus yang sama: dibahas sebagai pembinaan pada SOP-SDM-011 atau diproses melalui SOP-RSK-004."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% insiden tercatat paling lambat 2 hari kerja setelah penanganan awal.","100% insiden sedang dan berat memiliki analisis penyebab dan Rencana Tindakan Korektif.","Minimal 90% tindakan korektif selesai sesuai tenggat.","Insiden berulang pada penyebab yang sama menurun dari periode ke periode."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Insiden dan Register Insiden.","Catatan penyebab akar.","Rencana Tindakan Korektif dan bukti pelaksanaan.","Catatan verifikasi dan laporan ringkasan bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Risiko dan Etika, akses terbatas sesuai SOP- RSK-010) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa Register Insiden setiap bulan dan melaporkan pola insiden serta tindakan yang terlambat pada Rapat Kabinet; Sekretaris Jenderal memastikan arsip tersimpan untuk serah terima kabinet (SOP-TRN-009)."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Catat insiden → Registrasi → Analisis penyebab → Rencana tindakan → Persetujuan → Pelaksanaan → Pemantauan → Verifikasi efektivitas → Penutupan dan laporan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Insiden","Nomor; tanggal dan waktu; tempat; jenis; klasifikasi; dampak; pihak terkait (kode); tindakan awal; pelapor; bukti."],["Register Insiden","Nomor; tanggal; kategori; klasifikasi; penyebab; tindakan; penanggung jawab; tenggat; status; tanggal tutup."],["Rencana Tindakan Korektif","Insiden; penyebab akar; tindakan korektif dan pencegahan; penanggung jawab; tenggat; indikator; bukti."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh insiden dan nyaris celaka tercatat tepat waktu.","☐ Ya ☐ Tidak"],["2","Kasus rahasia dicatat dengan kode tanpa identitas.","☐ Ya ☐ Tidak"],["3","Penyebab akar ditelusuri untuk insiden sedang dan berat.","☐ Ya ☐ Tidak"],["4","Setiap tindakan memiliki penanggung jawab dan tenggat.","☐ Ya ☐ Tidak"],["5","Efektivitas tindakan diverifikasi dan pembelajaran dicatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-AST-001","g":"Inventaris dan Aset","t":"Pendataan Seluruh Aset BEM","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[308,311],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pendataan, klasifikasi, verifikasi, dan pencatatan seluruh aset yang dimiliki, dikuasai, atau digunakan BEM ke dalam Daftar Induk Aset, sehingga setiap aset diketahui statusnya, kondisinya, penanggung jawabnya, dan lokasinya."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh aset berwujud (perangkat elektronik, perlengkapan acara, perabot, atribut, dan perlengkapan sekretariat) dan aset digital bernilai (akun, domain, lisensi) yang berada dalam penguasaan BEM, baik milik BEM, milik kampus yang digunakan BEM, maupun titipan pihak lain. SOP ini tidak mengatur pemberian kode (lihat SOP-AST-002) dan pencatatan keuangan pembelian (lihat SOP-KEU-010)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf d (hasil pengembangan aset organisasi dikelola secara produktif) dan ayat (3) (dokumentasi dengan bukti resmi).","AD Pasal 15 ayat (1) huruf b dan ayat (2) (hibah atau donasi yang tidak mengikat dan terhindar dari riba, gharar, dan maysir).","ART Pasal 2 huruf i (fasilitas dan dukungan dari kampus).","ART Pasal 3 (Kewajiban BEM) huruf e dan h (pengelolaan amanah, transparan, akuntabel, dan kepatuhan pada peraturan STDIIS).","ART Pasal 11 huruf k (larangan memakai fasilitas atau nama organisasi untuk kepentingan pribadi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Aset","Barang berwujud atau aset digital bernilai yang dimiliki, dikuasai, atau digunakan BEM."],["Daftar Induk Aset","Register tunggal seluruh aset BEM yang memuat kode, nama, kategori, status kepemilikan, asal, nilai, kondisi, lokasi, dan penanggung jawab."],["Aset milik BEM","Aset yang dibeli dengan dana BEM atau diterima sebagai hibah atas nama BEM."],["Aset milik kampus","Fasilitas atau barang milik STDIIS yang digunakan BEM; pengelolaannya mengikuti aturan kampus."],["Aset titipan","Barang milik pihak lain yang dipegang sementara oleh BEM berdasarkan kesepakatan."],["PJ Aset","Menteri atau Kabiro yang ditetapkan bertanggung jawab atas aset di unitnya."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap aset wajib dikelompokkan menurut status kepemilikan: milik BEM, milik kampus, atau titipan. Status ini menentukan prosedur perawatan, kehilangan, dan penghapusan.","Pendataan awal dilakukan menyeluruh pada awal kabinet bersama penerimaan aset dari kabinet sebelumnya (SOP-TRN-005); pendataan lanjutan dilakukan setiap ada penambahan aset.","Aset tanpa bukti asal (nota, berita acara, surat hibah, atau surat serah terima) dicatat sebagai \"perlu penelusuran\" dan tidak boleh dipinjamkan ke pihak luar sebelum statusnya jelas.","Hibah atau donasi dicatat sebagai aset BEM hanya bila tidak mengikat organisasi melampaui satu periode dan sesuai syariat (AD Pasal 15 ayat (1) huruf b dan ayat (2)).","Aset bernilai tinggi atau sensitif ditandai khusus (usulan: nilai perolehan Rp1.000.000 ke atas, atau perangkat elektronik yang menyimpan data).","Barang pribadi pengurus yang dipakai untuk kegiatan BEM tidak dicatat sebagai aset BEM, tetapi didata pada kolom pinjaman pribadi beserta surat pernyataan agar tidak terjadi sengketa.","Daftar Induk Aset hanya diubah oleh Petugas Inventaris berdasarkan dokumen sah; setiap perubahan dicatat dengan tanggal dan alasan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Menetapkan kebijakan pendataan dan mengesahkan Daftar Induk Aset."],["Petugas Inventaris","R","Mendata, memotret, menyusun draf Daftar Induk Aset, dan mengarsipkannya."],["Menteri / Kabiro (PJ Aset)","R","Menyerahkan data aset unit dan memastikan keberadaan serta kondisi fisik aset unit."],["Biro Keuangan","C","Menyediakan bukti pembelian dan nilai perolehan aset."],["Inspektur Jenderal","C","Menguji sampel kesesuaian data dengan kondisi fisik."],["Presiden","I","Menerima salinan Daftar Induk Aset yang telah disahkan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Dokumen serah terima aset dari kabinet sebelumnya.","Nota, bukti pembelian, surat hibah, atau berita acara perolehan.","Daftar aset kampus yang digunakan BEM (dari KAUR ORMAWA atau bagian sarana kampus).","Formulir Pendataan Aset.."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan tim: Menunjuk Petugas Inventaris, menetapkan jadwal dan cakupan (semua ruang, unit, dan aset digital).","Sekjen","Struktur kabinet, dokumen serah terima","Surat tugas pendataan","2 hari kerja setelah struktur ditetapkan"],["2","Pengumpulan data unit: Mengisi Formulir Pendataan Aset: nama, jumlah, kondisi, lokasi, asal, dan bukti perolehan.","Menteri / Kabiro","Aset unit, bukti perolehan","Formulir terisi","5 hari kerja"],["3","Pencacahan fisik: Mencocokkan formulir dengan barang, memotret, mencatat kondisi, dan menandai selisih.","Petugas Inventaris bersama PJ Aset","Formulir, aset","Hasil pencacahan","5 hari kerja"],["4","Klasifikasi dan penelusuran: Menetapkan status kepemilikan, kategori, dan nilai; aset tanpa bukti ditelusuri ke arsip atau KAUR ORMAWA.","Petugas Inventaris","Hasil pencacahan, arsip","Draf Daftar Induk Aset","3 hari kerja"],["5","Verifikasi: Menguji sampel aset (usulan 20% atau minimal 10 butir) terhadap draf daftar.","Irjen","Draf daftar, aset","Catatan verifikasi","2 hari kerja"],["6","Pengesahan: Mengesahkan Daftar Induk Aset; aset bernilai tinggi dilaporkan kepada Presiden.","Sekjen","Draf, catatan Irjen","Daftar Induk Aset sah","2 hari kerja"],["7","Penerusan dan arsip: Meneruskan ke pemberian kode (SOP- AST-002) dan menyimpan arsip pada repositori.","Petugas Inventaris","Daftar sah","Arsip, daftar siap diberi kode","2 hari kerja"],["8","Pemutakhiran: Mencatat aset baru, berubah, atau dihapus berdasarkan dokumen sah.","Petugas Inventaris","Dokumen perubahan","Daftar terkini","3 hari kerja setelah perubahan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pendataan awal ditargetkan selesai paling lambat 20 hari kerja sejak struktur kabinet ditetapkan. Hasil akhir: Daftar Induk Aset yang disahkan Sekretaris Jenderal."},{"note":"Catatan: angka waktu, kuorum, nilai ambang, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Aset tanpa bukti asal atau status tidak jelas: dikonsultasikan kepada KAUR ORMAWA atau Pembina; aset tidak dipinjamkan ke pihak luar selama belum jelas.","Selisih antara fisik dan catatan: aset yang tidak ditemukan diproses melalui SOP-AST-007; bila ada indikasi penyalahgunaan, SOP-RSK-007.","Perbedaan klasifikasi antara unit dan Petugas Inventaris diputuskan Sekjen; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% aset tercatat pada Daftar Induk Aset.","Selisih fisik dan catatan pada pemeriksaan Irjen tidak lebih dari 5%.","Pemutakhiran daftar dilakukan paling lambat 3 hari kerja setelah perubahan.","Tidak ada aset berstatus \"perlu penelusuran\" lebih dari satu semester."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Induk Aset.","Formulir Pendataan Aset yang terisi dan foto dokumentasi.","Catatan verifikasi Irjen.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Aset dan Inventaris) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kemutakhiran Daftar Induk Aset setiap bulan; Irjen menilai kesesuaian data dengan fisik pada pemeriksaan berkala (SOP-AST-010)."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tetapkan tim → Isi formulir unit → Cacah fisik → Klasifikasi → Verifikasi Irjen → Pengesahan Sekjen → Pemutakhiran → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pendataan Aset","Unit; PJ Aset; nama dan merek; jumlah; asal dan tahun perolehan; status kepemilikan; kondisi; lokasi; bukti; foto; tanggal."],["Templat Daftar Induk Aset","Kode; nama; kategori; status kepemilikan; asal dan nilai; tanggal perolehan; kondisi; lokasi; PJ Aset; keterangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap aset memiliki status kepemilikan.","☐ Ya ☐ Tidak"],["2","Setiap aset memiliki penanggung jawab dan lokasi.","☐ Ya ☐ Tidak"],["3","Aset tanpa bukti ditandai \"perlu penelusuran\".","☐ Ya ☐ Tidak"],["4","Aset bernilai tinggi atau sensitif ditandai khusus.","☐ Ya ☐ Tidak"],["5","Daftar disahkan Sekjen dan tercatat pada Register Dokumen.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-AST-002","g":"Inventaris dan Aset","t":"Pemberian Kode Inventaris","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[312,315],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan sistem kode, pelabelan, dan pencatatan kode inventaris yang seragam pada setiap aset BEM, sehingga aset dapat dikenali, dilacak, dan tidak tercatat ganda."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh aset yang tercatat pada Daftar Induk Aset, baik label fisik maupun penandaan aset digital. Aset kampus yang sudah berkode kampus tetap memakai kode kampus, dan kode BEM hanya ditambahkan sebagai kode pendamping. SOP ini tidak mengatur pendataan aset (lihat SOP-AST-001)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf d dan ayat (3) (pengelolaan aset produktif dan dokumentasi resmi).","ART Pasal 3 (Kewajiban BEM) huruf e (pengelolaan amanah, transparan, dan akuntabel).","ART Pasal 11 huruf k (larangan memakai fasilitas atau nama organisasi untuk kepentingan pribadi).","SOP-AST-001 (Daftar Induk Aset sebagai sumber kode)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kode inventaris","Identitas unik satu aset yang tidak dipakai ulang untuk aset lain."],["Label aset","Penanda fisik (stiker atau plat) yang memuat kode inventaris dan identitas BEM."],["Buku Kode","Dokumen yang memuat kode kategori, kode unit, dan format nomor urut."],["Kode pendamping","Kode BEM yang ditambahkan pada aset milik kampus yang telah memiliki kode kampus."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pola kode (usulan): BEM/[Kategori]/[Unit]/[Tahun]/[Nomor urut], misalnya BEM/ELK/SEK/26/001.","Kode kategori (usulan): ELK elektronik, PRB perabot, PAC perlengkapan acara, ATR atribut dan seragam, DIG aset digital, LNN lainnya. Kode unit memakai singkatan unit pemegang awal.","Satu aset satu kode. Kode tidak dipakai ulang dan tidak dihapus walaupun aset sudah dihapus; statusnya diubah menjadi \"dihapus\".","Barang sejenis bernilai rendah (misalnya kursi plastik atau gelas) boleh diberi kode kelompok disertai jumlah.","Label dipasang pada bagian yang terlihat dan tidak mudah lepas; label rusak atau hilang diganti dengan kode yang sama.","Hanya Petugas Inventaris yang menerbitkan kode; unit tidak boleh membuat kode sendiri.","Melepas atau mengganti label tanpa izin merupakan pelanggaran disiplin (SOP-SDM-007)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Menetapkan Buku Kode dan mengesahkan pola kode."],["Petugas Inventaris","R","Menerbitkan kode, menyiapkan dan memasang label, serta mencatat pada Daftar Induk Aset."],["Menteri / Kabiro (PJ Aset)","R","Menyerahkan aset untuk dilabeli dan menjaga label tetap utuh."],["Biro Desain Komunikasi Visual","C","Menyediakan templat label yang seragam."],["Inspektur Jenderal","C","Memeriksa keunikan kode dan kelengkapan label pada sampel."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Induk Aset yang telah disahkan atau dokumen penambahan aset baru.","Buku Kode.","Templat label aset.","Bukti perolehan aset."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan Buku Kode: Menetapkan kategori, kode unit, dan format nomor urut.","Sekjen","Struktur kabinet, Daftar Induk Aset","Buku Kode","2 hari kerja"],["2","Penerbitan kode: Memberi kode unik pada setiap aset dan mencatatnya pada Daftar Induk Aset.","Petugas Inventaris","Daftar Induk Aset, Buku Kode","Daftar berkode","3 hari kerja setelah aset tercatat"],["3","Pembuatan label: Membuat label berisi kode dan identitas BEM sesuai templat.","Petugas Inventaris bersama Biro DKV","Daftar berkode, templat","Label siap pasang","3 hari kerja"],["4","Pemasangan: Memasang label pada aset; aset digital diberi penamaan sesuai kode; mengambil foto bukti.","Petugas Inventaris dan PJ Aset","Label, aset","Aset berlabel","5 hari kerja"],["5","Pemeriksaan: Memeriksa tidak ada kode ganda dan tidak ada aset tanpa label; Irjen memeriksa sampel.","Petugas Inventaris dan Irjen","Daftar, aset","Catatan pemeriksaan","2 hari kerja"],["6","Penggantian label: Melaporkan label hilang atau rusak, lalu menggantinya dengan kode yang sama dan mencatatnya.","PJ Aset dan Petugas Inventaris","Laporan PJ Aset","Label baru terpasang","3 hari kerja"],["7","Pengarsipan: Menyimpan Buku Kode dan daftar berkode pada repositori.","Petugas Inventaris","Buku Kode, daftar","Arsip","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Aset yang sudah ada pada awal kabinet diberi kode paling lambat 10 hari kerja setelah Daftar Induk Aset disahkan; aset baru diberi kode paling lambat 3 hari kerja setelah diterima. Hasil akhir: seluruh aset berkode dan berlabel."},{"note":"Catatan: angka waktu, kuorum, nilai ambang, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kode ganda atau salah: diperbaiki Petugas Inventaris dan dilaporkan kepada Sekjen.","Aset kampus tanpa kode kampus: ditanyakan kepada KAUR ORMAWA sebelum diberi kode pendamping.","Aset yang tidak boleh ditempel label (barang pinjaman atau titipan): dicatat dengan penanda lain atas keputusan Sekjen.","Pelepasan label tanpa izin: SOP-SDM-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% aset berkode dan berlabel.","Tidak ada kode ganda pada Daftar Induk Aset.","Label rusak atau hilang diganti paling lambat 3 hari kerja.","Aset baru berkode paling lambat 3 hari kerja."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Buku Kode.","Daftar Induk Aset berkode.","Foto aset berlabel dan catatan pemeriksaan.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Aset dan Inventaris) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa konsistensi kode setiap bulan bersamaan dengan pemutakhiran daftar; Irjen menilai pada pemeriksaan berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tetapkan Buku Kode → Terbitkan kode → Buat label → Pasang label → Periksa → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Buku Kode","Kode kategori; kode unit; format nomor urut; contoh penulisan; tanggal pengesahan."],["Templat Label Aset","Kode inventaris; nama organisasi; ruang untuk tanggal pemasangan; kontak PJ Aset."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kode aset unik dan sesuai pola.","☐ Ya ☐ Tidak"],["2","Label terpasang pada tempat yang terlihat.","☐ Ya ☐ Tidak"],["3","Kode tercatat pada Daftar Induk Aset.","☐ Ya ☐ Tidak"],["4","Aset digital diberi penamaan sesuai kode.","☐ Ya ☐ Tidak"],["5","Tidak ditemukan aset tanpa label pada sampel.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-AST-003","g":"Inventaris dan Aset","t":"Peminjaman Aset","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[316,319],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengajuan, pemeriksaan, persetujuan, serah terima, dan pemantauan peminjaman aset BEM oleh pengurus, panitia, dan organisasi kemahasiswaan STDIIS, agar aset dipakai untuk kepentingan organisasi dan tetap terlindungi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk peminjaman aset oleh pengurus BEM, panitia kegiatan BEM, serta BPM, HIMA, dan UKM STDIIS. Peminjaman kepada pihak di luar lingkungan tersebut diatur pada SOP-AST-008, pengembalian pada SOP-AST-004, dan penggunaan ruang sekretariat pada SOP-AST-005."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf i (fasilitas dan dukungan dari kampus untuk menjalankan program kerja).","ART Pasal 3 (Kewajiban BEM) huruf e dan h (pengelolaan amanah dan kepatuhan pada peraturan STDIIS).","ART Pasal 4 (Wewenang BEM) huruf g (rekomendasi kepada HIMA dan UKM dalam pelaksanaan kegiatan).","ART Pasal 11 huruf k (larangan memakai fasilitas atau nama organisasi untuk kepentingan pribadi yang merugikan organisasi).","ART Pasal 12 dan Pasal 13 (pembinaan, jenis sanksi, dan mekanisme penanganan pelanggaran)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Peminjam","Pengurus, panitia, atau organisasi kemahasiswaan STDIIS yang meminjam aset."],["Register Peminjaman","Catatan seluruh peminjaman: aset, peminjam, tujuan, tanggal pinjam, tanggal kembali, dan status."],["Berita Acara Peminjaman","Dokumen serah terima aset yang memuat kondisi aset dan tanggung jawab peminjam."],["Aset bernilai tinggi atau sensitif","Aset yang ditandai pada Daftar Induk Aset (usulan: Rp1.000.000 ke atas atau perangkat berisi data)."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Hanya aset yang tercatat, berkode, dan berkondisi baik yang boleh dipinjam. Aset milik kampus atau titipan hanya dipinjamkan bila pemiliknya mengizinkan.","Peminjaman hanya untuk kegiatan organisasi atau kemahasiswaan dan tidak untuk kepentingan pribadi.","Peminjaman biasa disetujui Sekjen; peminjaman aset bernilai tinggi atau sensitif memerlukan persetujuan Presiden.","Masa pinjam standar paling lama 3 hari kerja (usulan) dan dapat diperpanjang dengan persetujuan Sekjen sebelum jatuh tempo.","Kondisi aset diperiksa bersama peminjam saat penyerahan dengan checklist; kerusakan yang sudah ada dicatat agar tidak dibebankan kepada peminjam.","Peminjam bertanggung jawab atas aset selama masa pinjam dan dilarang meminjamkan kembali kepada pihak lain.","Bila jadwal bentrok, kegiatan BEM yang telah disetujui didahulukan; selebihnya diputuskan Sekjen."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Peminjam","R","Mengajukan peminjaman, memakai aset sesuai tujuan, menjaga, dan mengembalikan tepat waktu."],["Petugas Inventaris","R","Memeriksa pengajuan, mengelola kalender, membuat Berita Acara, dan mencatat Register Peminjaman."],["Menteri / Kabiro (PJ Aset)","R","Menyerahkan aset unit dan memastikan kondisinya."],["Sekretaris Jenderal","A","Menyetujui atau menolak peminjaman dan memutuskan bentrok jadwal."],["Presiden","C","Memberi persetujuan untuk peminjaman aset bernilai tinggi atau sensitif."],["Inspektur Jenderal","I","Menerima rekap peminjaman bulanan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Peminjaman Aset.","Surat tugas, proposal, atau bukti kegiatan yang membutuhkan aset.","Daftar Induk Aset dan kalender peminjaman.","Identitas peminjam dan penanggung jawab."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan: Mengisi Formulir Peminjaman Aset melalui kanal resmi: aset, tujuan, tanggal pinjam dan kembali, serta lokasi pemakaian.","Peminjam","Kebutuhan kegiatan","Pengajuan tercatat","Paling lambat 2 hari kerja sebelum dipakai"],["2","Verifikasi: Memeriksa ketersediaan pada kalender, status dan kondisi aset, kelengkapan formulir, dan kesesuaian tujuan.","Petugas Inventaris","Pengajuan, Daftar Induk Aset","Layak atau perlu revisi","1 hari kerja"],["3","Persetujuan: Menyetujui atau menolak dengan alasan; aset bernilai tinggi atau sensitif dimintakan persetujuan Presiden.","Sekjen / Presiden","Hasil verifikasi","Disetujui atau ditolak dengan alasan","1 hari kerja"],["4","Serah aset: Menyerahkan aset, memeriksa kondisi bersama peminjam dengan checklist, menandatangani Berita Acara, dan memotret aset bernilai tinggi.","Petugas, PJ Aset, Peminjam","Persetujuan, aset","Berita Acara Peminjaman","Pada hari pinjam"],["5","Penggunaan: Memakai aset sesuai tujuan; kerusakan atau kehilangan dilaporkan segera (SOP-AST-007).","Peminjam","Aset","Aset terpakai sesuai tujuan","Selama masa pinjam"],["6","Pemantauan: Memantau kalender, mengingatkan peminjam sehari sebelum jatuh tempo, dan memproses perpanjangan.","Petugas Inventaris","Register Peminjaman","Pengingat atau perpanjangan tercatat","H-1 jatuh tempo"],["7","Pencatatan dan rekap: Mencatat pada Register Peminjaman dan menyampaikan rekap bulanan kepada Sekjen dan Irjen.","Petugas Inventaris","Register","Rekap peminjaman","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Keputusan peminjaman diberikan paling lambat 2 hari kerja sejak pengajuan lengkap. Hasil akhir: Berita Acara Peminjaman dan catatan pada Register Peminjaman. Pengembalian mengikuti SOP-AST-004."},{"note":"Catatan: angka waktu, kuorum, nilai ambang, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengajuan ditolak: peminjam dapat mengajukan ulang setelah memperbaiki, atau meminta pertimbangan Wakil Presiden.","Bentrok jadwal: diputuskan Sekjen berdasarkan prioritas kegiatan; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Kebutuhan mendesak di luar jam kerja: Sekjen dapat menyetujui secara lisan dan wajib dicatat tertulis dalam 1 x 24 jam.","Pemakaian tidak sesuai tujuan: SOP-SDM-013 (penanganan dugaan pelanggaran kode etik)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% peminjaman memiliki formulir dan Berita Acara.","Paling sedikit 90% keputusan diberikan dalam 2 hari kerja.","Tidak ada peminjaman aset tanpa kode atau tanpa persetujuan berwenang.","Keterlambatan pengembalian kurang dari 10% dari seluruh peminjaman."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Peminjaman Aset.","Berita Acara Peminjaman dan checklist kondisi.","Register Peminjaman.","Rekap peminjaman bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Aset dan Inventaris) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal meninjau Register Peminjaman setiap bulan; Irjen memeriksa sampel kesesuaian register dengan Berita Acara."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengajuan → Verifikasi → Persetujuan → Serah aset dan Berita Acara → Penggunaan → Pemantauan → Pengembalian (SOP-AST-004) → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Peminjaman Aset","Nama dan unit peminjam; kegiatan; aset dan kode; tujuan; tanggal pinjam dan kembali; lokasi; persetujuan."],["Berita Acara Peminjaman dan Checklist Kondisi","Aset dan kode; kondisi dan kelengkapan; foto; pihak penyerah dan penerima; tanggal; tanda tangan."],["Register Peminjaman","Nomor; aset; peminjam; tujuan; tanggal pinjam; tanggal kembali; status; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Aset tercatat, berkode, dan berkondisi baik.","☐ Ya ☐ Tidak"],["2","Tujuan sesuai kegiatan organisasi.","☐ Ya ☐ Tidak"],["3","Jadwal tidak bentrok dengan kegiatan lain.","☐ Ya ☐ Tidak"],["4","Persetujuan sesuai tingkat aset.","☐ Ya ☐ Tidak"],["5","Kondisi diperiksa bersama dan Berita Acara ditandatangani.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-AST-004","g":"Inventaris dan Aset","t":"Pengembalian Aset","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[320,323],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengembalian, pemeriksaan kondisi, penanganan selisih dan keterlambatan, serta penutupan peminjaman aset, sehingga aset kembali tepat waktu dan dalam kondisi yang dapat dipertanggungjawabkan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh aset yang dipinjam melalui SOP-AST-003 dan SOP-AST-008, serta aset yang dikembalikan panitia setelah kegiatan (lihat SOP-PRO-019). Perbaikan lanjutan diatur pada SOP-AST-006, dan kerusakan atau kehilangan diatur pada SOP-AST-007."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf d (pengelolaan aset organisasi).","ART Pasal 3 (Kewajiban BEM) huruf e dan h.","ART Pasal 11 huruf k dan l (larangan memakai fasilitas untuk kepentingan pribadi dan meninggalkan tanggung jawab tanpa alasan sah).","ART Pasal 12 ayat (1) dan (2) (pembinaan dan jenis sanksi).","ART Pasal 13 ayat (4), (7), dan (9) (bukti, keadilan, dan hak klarifikasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pengembalian","Penyerahan kembali aset oleh peminjam kepada Petugas Inventaris atau PJ Aset."],["Keterlambatan","Pengembalian setelah tanggal jatuh tempo pada Berita Acara Peminjaman tanpa perpanjangan."],["Selisih","Perbedaan jumlah, kelengkapan, atau kondisi aset saat dikembalikan dibandingkan saat dipinjam."],["Berita Acara Pengembalian","Dokumen penutup yang memuat hasil pemeriksaan kondisi saat aset dikembalikan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Aset dikembalikan langsung kepada Petugas Inventaris atau PJ Aset di tempat yang ditentukan, tidak melalui pihak ketiga tanpa kuasa tertulis.","Pemeriksaan dilakukan di hadapan peminjam dengan checklist yang sama seperti saat peminjaman.","Aset dikembalikan dalam kondisi sama, bersih, dan lengkap, dengan memperhitungkan pemakaian yang wajar.","Selisih dicatat pada Berita Acara Pengembalian dan ditangani melalui SOP-AST-007 sebelum peminjaman ditutup.","Keterlambatan ditindaklanjuti bertahap (usulan): H+1 pengingat, H+3 teguran tertulis, H+7 dilaporkan kepada Presiden dan ditangani melalui SOP-SDM-007 atau SOP-SDM-013.","Peminjaman dianggap selesai hanya setelah Berita Acara Pengembalian ditandatangani kedua pihak.","Peminjam berhak memberikan klarifikasi atas selisih yang dicatat (ART Pasal 13 ayat (9))."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Peminjam","R","Mengembalikan aset tepat waktu, bersih, dan lengkap; menandatangani Berita Acara."],["Petugas Inventaris","R","Memeriksa aset, membuat Berita Acara, menutup peminjaman, dan memperbarui daftar."],["Menteri / Kabiro (PJ Aset)","R","Menguji fungsi aset yang dikembalikan dan menempatkannya kembali."],["Sekretaris Jenderal","A","Mengetahui hasil pengembalian dan menindaklanjuti keterlambatan atau selisih."],["Inspektur Jenderal","I","Menerima rekap keterlambatan dan selisih bulanan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Berita Acara Peminjaman dan checklist kondisi awal.","Register Peminjaman.","Aset yang dikembalikan.","Formulir Berita Acara Pengembalian."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pemberitahuan pengembalian: Menyampaikan rencana atau waktu pengembalian kepada Petugas Inventaris.","Peminjam","Berita Acara Peminjaman","Jadwal serah kembali","Paling lambat pada jatuh tempo"],["2","Penerimaan dan pemeriksaan: Memeriksa jumlah, kelengkapan, kebersihan, dan fungsi aset dengan checklist awal di hadapan peminjam.","Petugas Inventaris dan PJ Aset","Aset, checklist awal","Hasil pemeriksaan","Saat penyerahan"],["3","Penetapan hasil: Bila sesuai, dilanjutkan; bila ada selisih, dicatat pada Berita Acara dan diteruskan ke SOP-AST-007.","Petugas Inventaris","Hasil pemeriksaan","Berita Acara Pengembalian","Hari yang sama"],["4","Penempatan: Menyimpan aset pada tempat semula (SOP-AST-009) dan memperbarui kondisi pada Daftar Induk Aset.","Petugas dan PJ Aset","Aset, Berita Acara","Aset tersimpan, daftar diperbarui","1 hari kerja"],["5","Penutupan: Mengubah status Register Peminjaman menjadi \"selesai\" atau \"selesai dengan catatan\".","Petugas Inventaris","Berita Acara","Peminjaman ditutup","1 hari kerja"],["6","Tindak lanjut keterlambatan: Mengirim pengingat dan teguran sesuai tahapan; mencatat setiap tindakan.","Petugas dan Sekjen","Register Peminjaman","Pengingat atau teguran tercatat","H+1, H+3, H+7"],["7","Rekap: Menyampaikan rekap pengembalian, keterlambatan, dan selisih kepada Sekjen dan Irjen.","Petugas Inventaris","Register","Rekap bulanan","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Aset dikembalikan paling lambat pada tanggal jatuh tempo; pemeriksaan selesai saat penyerahan dan penutupan peminjaman paling lambat 1 hari kerja setelahnya. Hasil akhir: Berita Acara Pengembalian dan Register Peminjaman yang tertutup."},{"note":"Catatan: angka waktu, kuorum, nilai ambang, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Rusak, kurang, atau hilang: SOP-AST-007.","Peminjam membantah kondisi: diputuskan berdasarkan foto dan checklist awal; bila belum selesai dimediasi Wakil Presiden (SOP-GOV-010).","Keterlambatan lebih dari 7 hari: dilaporkan kepada Presiden dan ditangani melalui SOP-SDM-013.","Aset milik pihak eksternal: ikuti perjanjian pada SOP-AST-008."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Paling sedikit 90% aset dikembalikan tepat waktu.","100% pengembalian disertai Berita Acara.","Peminjaman ditutup paling lambat 1 hari kerja setelah aset kembali.","Tidak ada aset yang kembali tanpa pemeriksaan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Berita Acara Pengembalian dan checklist kondisi.","Register Peminjaman yang diperbarui.","Catatan keterlambatan dan selisih.","Rekap bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Aset dan Inventaris) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa peminjaman yang belum tertutup setiap minggu; Irjen menilai kepatuhan pada pemeriksaan berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pemberitahuan pengembalian → Pemeriksaan kondisi → Selisih? (ya: SOP-AST-007) → Penempatan → Penutupan peminjaman → Rekap → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Berita Acara Pengembalian dan Checklist Kondisi","Aset dan kode; kondisi saat kembali; selisih; foto; pihak penyerah dan penerima; tanggal; tanda tangan."],["Surat Teguran Keterlambatan","Nomor; peminjam; aset; tanggal jatuh tempo; lama keterlambatan; batas waktu pengembalian; pejabat penandatangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Jumlah dan kelengkapan aset sesuai.","☐ Ya ☐ Tidak"],["2","Kondisi diperiksa dengan checklist awal.","☐ Ya ☐ Tidak"],["3","Selisih dicatat pada Berita Acara.","☐ Ya ☐ Tidak"],["4","Daftar Induk Aset diperbarui.","☐ Ya ☐ Tidak"],["5","Register Peminjaman ditutup.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-AST-005","g":"Inventaris dan Aset","t":"Penggunaan Ruang Sekretariat","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[324,327],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan aturan, jadwal, ketertiban, keamanan, dan kebersihan penggunaan ruang sekretariat BEM, sehingga ruang dapat dipakai secara adil, tertib, aman, dan sesuai nilai Islam serta aturan kampus."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk ruang sekretariat BEM beserta isinya, bagi pengurus, panitia, organisasi kemahasiswaan, dan tamu. SOP ini tidak mengatur peminjaman ruang kampus lain untuk kegiatan (lihat SOP-PRO-009) dan penerimaan tamu resmi (lihat SOP-HKE-009)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 3 ayat (1) (landasan Al-Qur'an dan As-Sunnah) sebagai dasar adab penggunaan ruang.","ART Pasal 2 huruf i (fasilitas dan dukungan dari kampus).","ART Pasal 3 (Kewajiban BEM) huruf d dan h (ketertiban dan kepatuhan pada peraturan STDIIS).","ART Pasal 11 huruf c, f, h, dan k (larangan kekerasan atau perusakan fasilitas, zat haram, perbuatan asusila atau perundungan, dan memakai fasilitas untuk kepentingan pribadi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Ruang sekretariat","Ruang milik kampus yang diberikan atau diizinkan untuk dipakai BEM sebagai pusat administrasi dan koordinasi."],["Piket sekretariat","Pengurus yang bertugas menjaga ketertiban, kebersihan, dan pencatatan penggunaan ruang pada jadwal tertentu."],["Pemegang kunci","Pengurus yang ditunjuk Sekjen untuk menyimpan dan memakai kunci ruang."],["Log Penggunaan","Catatan harian pengguna, waktu, tujuan, dan kondisi ruang."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Ruang sekretariat adalah fasilitas kampus; bila aturan kampus berbeda dengan SOP ini, aturan kampus yang berlaku.","Ruang dipakai untuk kegiatan keorganisasian (rapat, administrasi, koordinasi, dan penyimpanan), bukan untuk kegiatan pribadi, usaha pribadi, atau menginap tanpa izin tertulis kampus.","Jam operasional ditetapkan Sekjen mengikuti jam kampus; penggunaan di luar jam operasional hanya dengan izin Sekjen dan diketahui keamanan kampus bila diwajibkan.","Tata pergaulan dan berpakaian di dalam ruang mengikuti syariat Islam dan aturan kampus.","Kunci hanya dipegang pemegang kunci resmi; duplikat hanya dengan izin Sekjen dan setiap penggunaan kunci dicatat.","Penggunaan oleh organisasi lain atau tamu memerlukan izin Sekjen dan dicatat pada Log Penggunaan.","Dokumen dan aset tidak dibawa keluar ruang tanpa prosedur SOP-AST-003."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Menetapkan jam operasional, jadwal piket, dan pemegang kunci; memutuskan izin dan bentrok pemakaian."],["Pemegang kunci","R","Membuka dan mengunci ruang serta mencatat penggunaan kunci."],["Pengurus piket","R","Menjaga ketertiban dan kebersihan serta mengisi Log Penggunaan."],["Pengguna ruang","R","Mematuhi tata tertib dan merapikan ruang setelah dipakai."],["Petugas Inventaris","R","Memeriksa kondisi ruang dan isi secara berkala."],["KAUR ORMAWA","C","Menjadi rujukan aturan fasilitas kampus dan penerima laporan masalah."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Aturan fasilitas kampus.","Jadwal kuliah dan kalender organisasi.","Jadwal piket dan daftar pemegang kunci.","Formulir Pemesanan Ruang dan Log Penggunaan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan jadwal dan piket: Menetapkan jam operasional, jadwal piket, dan pemegang kunci, lalu menempelkannya di ruang dan membagikannya.","Sekjen","Jadwal kampus, struktur kabinet","Jadwal piket, daftar pemegang kunci","5 hari kerja setelah kabinet dibentuk dan di awal tiap semester"],["2","Pemesanan khusus: Memesan ruang untuk rapat atau kegiatan di luar rutinitas melalui Formulir Pemesanan Ruang.","Pengguna ruang","Kebutuhan kegiatan","Pemesanan tercatat","Paling lambat 1 hari kerja sebelum dipakai"],["3","Persetujuan: Menyetujui, menolak, atau menjadwalkan ulang; rapat resmi BEM didahulukan bila bentrok.","Sekjen","Pemesanan, kalender","Keputusan penggunaan","1 hari kerja"],["4","Pembukaan ruang: Membuka ruang, memeriksa kondisi awal, dan mengisi Log Penggunaan (waktu, pengguna, tujuan).","Pemegang kunci atau piket","Log Penggunaan","Ruang dibuka dan tercatat","Saat mulai"],["5","Penggunaan: Menjaga ketertiban dan kebersihan; perlengkapan sekretariat dipakai di dalam ruang.","Pengguna ruang","Tata tertib","Ruang tertib","Selama penggunaan"],["6","Penutupan: Merapikan ruang, memeriksa perangkat listrik, jendela, dan pengunci, mencatat kondisi akhir, lalu mengunci.","Pengurus piket","Log, checklist","Ruang terkunci, log lengkap","Saat selesai"],["7","Pemeriksaan berkala: Memeriksa kondisi ruang dan isi serta melaporkan temuan kepada Sekjen.","Petugas Inventaris","Log, Daftar Induk Aset","Catatan pemeriksaan","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pemesanan khusus diputuskan paling lambat 1 hari kerja; Log Penggunaan terisi lengkap pada setiap hari ruang dibuka. Hasil akhir: ruang terkelola tertib dan terdokumentasi."},{"note":"Catatan: angka waktu, kuorum, nilai ambang, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Bentrok pemakaian: diputuskan Sekjen; bila belum selesai dibawa ke Wakil Presiden.","Pelanggaran tata tertib ringan ditegur oleh piket; pelanggaran berat (zat terlarang, kekerasan, perbuatan asusila, atau perundungan) diproses melalui SOP-SDM-013 dan SOP-RSK-005 serta dilaporkan kepada Presiden.","Kerusakan atau kehilangan: SOP-AST-007.","Keadaan darurat (kebakaran, kecelakaan, atau pencurian): SOP-RSK-003.","Kunci hilang: dilaporkan kepada Sekjen dan kunci diganti atas persetujuan Sekjen."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Log Penggunaan terisi pada 100% hari ruang dibuka.","Seluruh kunci tercatat pada daftar pemegang kunci.","Tidak ada kehilangan akibat ruang tidak terkunci.","Ruang bersih dan tertib pada pemeriksaan bulanan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Jadwal piket dan daftar pemegang kunci.","Log Penggunaan Ruang Sekretariat.","Formulir Pemesanan Ruang.","Catatan pemeriksaan bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Aset dan Inventaris) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal meninjau Log Penggunaan setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tetapkan jadwal dan piket → Pemesanan khusus → Persetujuan Sekjen → Buka ruang dan isi log → Penggunaan → Tutup dan kunci → Pemeriksaan bulanan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Log Penggunaan Ruang Sekretariat","Tanggal; waktu masuk dan keluar; nama pengguna; tujuan; kondisi awal dan akhir; petugas piket."],["Formulir Pemesanan Ruang","Pemesan; kegiatan; tanggal dan jam; jumlah peserta; kebutuhan; persetujuan."],["Jadwal Piket dan Daftar Pemegang Kunci","Hari; nama piket; nama pemegang kunci; nomor kontak; tanda terima kunci."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Jadwal piket dipasang dan dibagikan.","☐ Ya ☐ Tidak"],["2","Penggunaan kunci tercatat.","☐ Ya ☐ Tidak"],["3","Log hari ini terisi lengkap.","☐ Ya ☐ Tidak"],["4","Perangkat listrik dimatikan dan ruang terkunci.","☐ Ya ☐ Tidak"],["5","Tidak ada aset keluar ruang tanpa SOP-AST-003.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-AST-006","g":"Inventaris dan Aset","t":"Perawatan dan Pemeriksaan Aset","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[328,331],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur perawatan rutin, pemeriksaan kondisi, dan perbaikan terencana atas aset BEM agar aset tetap layak pakai, tahan lama, dan aman."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk aset milik BEM dan aset kampus atau titipan yang dipegang BEM (perawatan ringan; perbaikan aset milik pihak lain hanya atas izin pemiliknya), termasuk pembaruan dan pencadangan aset digital. SOP ini tidak mengatur kerusakan berat atau kehilangan (lihat SOP-AST-007) dan pemeriksaan inventaris (lihat SOP- AST-010)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf d (aset organisasi dikelola secara produktif).","ART Pasal 3 (Kewajiban BEM) huruf e dan h.","ART Pasal 4 (Wewenang BEM) huruf d (mengajukan dana kemahasiswaan kepada perguruan tinggi).","ART Pasal 10 ayat (4) huruf b (monitoring penggunaan anggaran pada Rapat Koordinasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Perawatan rutin","Kegiatan berkala menjaga aset tetap bersih, berfungsi, dan lengkap."],["Pemeriksaan kondisi","Penilaian kondisi aset: baik, rusak ringan, atau rusak berat."],["Rusak ringan","Aset masih dapat dipakai atau dapat diperbaiki dengan biaya wajar."],["Rusak berat","Aset tidak dapat dipakai dan perbaikannya tidak ekonomis atau berisiko."],["Kartu Perawatan","Catatan riwayat perawatan, perbaikan, dan biaya untuk setiap aset."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Perawatan rutin dilakukan PJ Aset sesuai jadwal (usulan: bulanan untuk perangkat elektronik, dan setelah setiap pemakaian untuk perlengkapan acara).","Pemeriksaan kondisi oleh Petugas Inventaris dilakukan setiap 3 bulan (usulan) dan hasilnya dicatat pada Daftar Induk Aset.","Perbaikan memakai anggaran sesuai prosedur keuangan (SOP-KEU-002 dan SOP-KEU-004); perbaikan di atas ambang yang ditetapkan Presiden (usulan Rp500.000) memerlukan persetujuan Presiden.","Perbaikan dilakukan oleh pihak yang kompeten; aset milik kampus diperbaiki oleh kampus melalui KAUR ORMAWA.","Aset rusak berat ditandai \"tidak boleh dipakai\" dan tidak boleh dipinjamkan sampai ada keputusan (SOP-AST-007 atau SOP-AST-012).","Perawatan aset digital mencakup pembaruan, pengelolaan lisensi, dan pencadangan; kata sandi tidak dicatat pada daftar aset (lihat SOP-KOM-013 dan SOP-ADM-015).","Setiap perawatan dan perbaikan dicatat pada Kartu Perawatan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Menyetujui jadwal, usulan perbaikan, dan menindaklanjuti laporan kondisi."],["Menteri / Kabiro (PJ Aset)","R","Melakukan perawatan rutin dan melaporkan kerusakan pada aset unit."],["Petugas Inventaris","R","Menyusun jadwal, memeriksa kondisi tiap 3 bulan, dan memperbarui Kartu Perawatan."],["Biro Keuangan","C","Memproses anggaran dan pembayaran perbaikan."],["Presiden","C","Menyetujui perbaikan di atas ambang."],["Inspektur Jenderal","I","Menerima laporan kondisi aset."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Induk Aset.","Jadwal perawatan.","Kartu Perawatan.","Estimasi biaya perbaikan dan anggaran yang tersedia."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan jadwal: Menyusun jadwal perawatan dan pemeriksaan per kategori aset.","Petugas Inventaris","Daftar Induk Aset, kalender","Jadwal perawatan","Awal tiap semester"],["2","Perawatan rutin: Membersihkan, menguji fungsi, memeriksa kelengkapan, dan memperbarui perangkat lunak; mencatat pada Kartu Perawatan.","PJ Aset","Jadwal, aset","Kartu Perawatan terisi","Sesuai jadwal"],["3","Pemeriksaan kondisi: Menilai kondisi aset (baik, rusak ringan, rusak berat) dan memotret aset bermasalah.","Petugas Inventaris","Aset, kartu","Laporan kondisi","Setiap 3 bulan"],["4","Pelaporan: Menyampaikan laporan kondisi disertai usulan tindakan: perbaikan, penggantian, atau penghapusan.","Petugas Inventaris","Laporan kondisi","Usulan tindakan","2 hari kerja"],["5","Persetujuan perbaikan: Menyetujui perbaikan; biaya di atas ambang diajukan kepada Presiden; aset kampus dilaporkan kepada KAUR ORMAWA.","Sekjen / Presiden","Usulan, estimasi biaya","Persetujuan","2 hari kerja"],["6","Pelaksanaan perbaikan: Mengajukan dana melalui Biro Keuangan, melaksanakan perbaikan, dan mengumpulkan bukti.","PJ Aset dan Biro Keuangan","Persetujuan, anggaran","Aset diperbaiki, bukti perbaikan","Sesuai estimasi"],["7","Verifikasi dan pencatatan: Memastikan aset berfungsi, memperbarui kondisi pada Daftar Induk Aset dan Kartu Perawatan.","Petugas Inventaris","Aset, bukti","Daftar diperbarui","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Perawatan rutin sesuai jadwal; laporan kondisi disusun setiap 3 bulan; keputusan perbaikan diberikan paling lambat 2 hari kerja sejak usulan. Hasil akhir: aset layak pakai dengan riwayat perawatan tercatat."},{"note":"Catatan: angka waktu, kuorum, nilai ambang, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kerusakan akibat kelalaian: SOP-AST-007 dan, bila perlu, SOP-SDM-013.","Anggaran tidak tersedia: Sekjen membawa ke Rapat Pimpinan (SOP-GOV-005) atau mengajukan penyesuaian sesuai SOP-KEU-014.","Aset milik kampus: dikoordinasikan dengan KAUR ORMAWA.","Perbaikan tidak ekonomis: diusulkan penghapusan melalui SOP-AST-012.","Risiko keselamatan (misalnya kabel terkelupas): aset dihentikan pemakaiannya dan ditangani sesuai SOP-RSK-003."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Paling sedikit 90% aset berstatus layak pakai.","100% jadwal perawatan terlaksana dan tercatat.","Laporan kondisi triwulanan terlaksana tepat waktu.","Tidak ada aset rusak yang tetap dipinjamkan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Jadwal perawatan.","Kartu Perawatan setiap aset.","Laporan kondisi triwulanan.","Persetujuan dan bukti perbaikan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Aset dan Inventaris) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa pelaksanaan jadwal perawatan setiap bulan; Irjen menilai laporan kondisi pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Susun jadwal → Perawatan rutin → Pemeriksaan kondisi → Laporan dan usulan → Persetujuan → Perbaikan → Verifikasi dan catat → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Kartu Perawatan Aset","Kode dan nama aset; tanggal; jenis perawatan atau perbaikan; pelaksana; biaya; bukti; kondisi setelah perawatan."],["Formulir Laporan Kondisi dan Usulan Tindakan","Aset dan kode; kondisi; foto; penyebab; usulan tindakan; estimasi biaya; pelapor; tanggal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Jadwal perawatan tersedia.","☐ Ya ☐ Tidak"],["2","Kartu Perawatan terisi untuk aset yang dirawat.","☐ Ya ☐ Tidak"],["3","Aset rusak berat ditandai tidak boleh dipakai.","☐ Ya ☐ Tidak"],["4","Perbaikan disetujui sesuai tingkat biaya.","☐ Ya ☐ Tidak"],["5","Daftar Induk Aset diperbarui setelah perbaikan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-AST-007","g":"Inventaris dan Aset","t":"Penanganan Aset Rusak atau Hilang","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[332,335],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pelaporan, verifikasi, penentuan penyebab, penyelesaian tanggung jawab, dan pencatatan atas aset BEM yang rusak berat atau hilang, secara adil, berdasarkan bukti, dan sesuai aturan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh aset yang dikuasai BEM, termasuk aset yang sedang dipinjam atau berada di ruang sekretariat. Dugaan penyalahgunaan atau penggelapan ditangani lebih lanjut melalui SOP-RSK-007. Penghapusan aset diatur pada SOP-AST-012."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 9 ayat (2) huruf b dan c (pemberhentian karena tindakan yang bertentangan dengan prinsip atau merugikan organisasi dan kampus).","ART Pasal 3 (Kewajiban BEM) huruf e dan h.","ART Pasal 11 huruf i dan k (larangan penyelewengan dan penggunaan fasilitas untuk kepentingan pribadi).","ART Pasal 12 (jenis sanksi dan kewenangan) dan Pasal 13 ayat (4), (7) sampai (9) (bukti, keadilan, proporsionalitas, dan hak klarifikasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rusak berat","Aset tidak dapat dipakai dan tidak ekonomis diperbaiki."],["Hilang","Aset tidak ditemukan setelah penelusuran wajar."],["Laporan Kejadian Aset","Formulir resmi yang memuat kronologi, bukti, dan perkiraan nilai aset yang rusak atau hilang."],["Kelalaian","Perbuatan atau pembiaran yang melanggar kewajiban menjaga aset tanpa niat merugikan."],["Force majeure","Kejadian di luar kendali seperti bencana atau musibah yang tidak dapat dihindari dengan upaya wajar."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kerusakan atau kehilangan wajib dilaporkan secepatnya, paling lambat 1 x 24 jam setelah diketahui.","Penelusuran dilakukan lebih dahulu (usulan 3 hari kerja) sebelum aset dinyatakan hilang.","Penyebab dibedakan: pemakaian wajar atau usang, kelalaian, kesengajaan, atau force majeure.","Pada pemakaian wajar atau force majeure, kerugian tidak dibebankan kepada individu; pada kelalaian atau kesengajaan, penyelesaiannya (perbaikan, penggantian setara, atau sanksi) diputuskan secara proporsional.","Penyelesaian memperhatikan hak klarifikasi dan pembelaan pihak yang bersangkutan (ART Pasal 13 ayat (9)).","Dugaan pencurian dilaporkan kepada KAUR ORMAWA atau keamanan kampus; pelaporan ke pihak berwajib mengikuti keputusan Presiden bersama kampus.","Aset milik kampus atau titipan dilaporkan kepada pemiliknya, dan penyelesaian mengikuti aturan atau perjanjian pemilik.","Pembebanan kerugian bersifat usulan internal dan tidak boleh bertentangan dengan aturan kampus."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pelapor / pengguna aset","R","Melaporkan kejadian, menyerahkan kronologi dan bukti."],["Petugas Inventaris","R","Memverifikasi, memotret, mencatat Laporan Kejadian Aset, dan memperbarui daftar."],["Menteri / Kabiro (PJ Aset)","R","Membantu penelusuran dan memberi keterangan kondisi aset."],["Inspektur Jenderal","C","Memeriksa kronologi dan bukti serta merekomendasikan penyebab dan penyelesaian."],["Sekretaris Jenderal","R","Memimpin pemrosesan laporan dan menyusun usulan penyelesaian."],["Presiden","A","Memutuskan penyelesaian akhir dan pembebanan kerugian."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan Kejadian Aset.","Berita Acara Peminjaman atau Log Penggunaan terkait.","Daftar Induk Aset dan Kartu Perawatan.","Foto, kesaksian, atau rekaman yang relevan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pelaporan: Melaporkan kejadian kepada Petugas Inventaris dan Sekjen, mengisi Laporan Kejadian Aset.","Pelapor","Kejadian, bukti awal","Laporan tercatat","1 x 24 jam"],["2","Pengamanan: Mengamankan aset rusak, menandai \"tidak boleh dipakai\", dan menutup akses bila hilang.","Petugas Inventaris","Laporan","Kondisi aman","Segera"],["3","Penelusuran: Menelusuri riwayat pemakaian, melakukan pencarian, dan mengumpulkan keterangan.","Petugas, PJ Aset","Register, log, saksi","Hasil penelusuran","3 hari kerja"],["4","Verifikasi dan penentuan penyebab: Menilai bukti, memberi kesempatan klarifikasi kepada pihak terkait, dan merekomendasikan penyebab dan penyelesaian.","Irjen","Hasil penelusuran, klarifikasi","Rekomendasi tertulis","3 hari kerja"],["5","Usulan penyelesaian: Menyusun usulan: perbaikan, penggantian, pembebanan proporsional, atau pembebasan tanggung jawab.","Sekjen","Rekomendasi Irjen","Usulan penyelesaian","2 hari kerja"],["6","Keputusan: Memutuskan penyelesaian akhir; pelanggaran disiplin diteruskan ke SOP-SDM-013.","Presiden","Usulan","Keputusan tertulis","2 hari kerja"],["7","Pelaksanaan dan pencatatan: Melaksanakan keputusan, mengubah status aset (dalam perbaikan, diganti, atau hilang) pada Daftar Induk Aset, dan mencatat insiden (SOP-RSK-012).","Petugas Inventaris","Keputusan","Daftar diperbarui, insiden tercatat","5 hari kerja"],["8","Tindak lanjut: Memperbaiki penyebab (penyimpanan, pengawasan, atau peminjaman) agar tidak berulang.","Sekjen","Catatan insiden","Perbaikan prosedur","Sesuai kebutuhan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Kejadian dilaporkan dalam 1 x 24 jam; penyelesaian ditargetkan paling lambat 15 hari kerja sejak laporan. Hasil akhir: keputusan tertulis dan Daftar Induk Aset yang diperbarui."},{"note":"Catatan: angka waktu, kuorum, nilai ambang, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Indikasi penyalahgunaan atau penggelapan: SOP-RSK-007 dan SOP-SDM-013.","Aset kampus: dilaporkan kepada KAUR ORMAWA dalam 1 x 24 jam.","Pihak terkait keberatan: dapat mengajukan klarifikasi tertulis kepada Presiden; Wakil Presiden memediasi (SOP-GOV-010).","Nilai kerugian besar atau perlu dibawa ke luar organisasi: dikonsultasikan dengan Pembina atau KAUR ORMAWA."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kejadian dilaporkan dalam 1 x 24 jam.","100% keputusan didasarkan pada bukti tertulis.","Penyelesaian selesai dalam 15 hari kerja pada paling sedikit 80% kasus.","Kejadian serupa menurun dari semester ke semester."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan Kejadian Aset.","Catatan penelusuran dan rekomendasi Irjen.","Keputusan Presiden tentang penyelesaian.","Daftar Induk Aset yang diperbarui dan catatan insiden. Seluruh dokumen disimpan pada repositori resmi BEM (folder Aset dan Inventaris) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal melaporkan seluruh kejadian dan statusnya pada evaluasi bulanan; Irjen meninjau kepatuhan prosedur."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Laporan 1 x 24 jam → Amankan aset → Penelusuran → Verifikasi dan klarifikasi → Usulan → Keputusan Presiden → Perbarui daftar → Tindak lanjut → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Laporan Kejadian Aset","Pelapor; aset dan kode; waktu dan tempat; kronologi; dugaan penyebab; saksi; bukti; perkiraan nilai; tanggal."],["Berita Acara Penyelesaian","Nomor; ringkasan kejadian; penyebab; keputusan; bentuk penyelesaian; pihak terkait; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Laporan masuk dalam 1 x 24 jam.","☐ Ya ☐ Tidak"],["2","Aset diamankan dan ditandai.","☐ Ya ☐ Tidak"],["3","Pihak terkait diberi kesempatan klarifikasi.","☐ Ya ☐ Tidak"],["4","Keputusan disertai alasan tertulis.","☐ Ya ☐ Tidak"],["5","Daftar Induk Aset dan catatan insiden diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-AST-008","g":"Inventaris dan Aset","t":"Peminjaman Aset kepada Pihak Eksternal","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[336,339],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur dan syarat peminjaman aset BEM kepada pihak di luar BEM, BPM, HIMA, dan UKM STDIIS secara terkendali, dengan persetujuan berwenang, jaminan tanggung jawab, dan perlindungan nama baik organisasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk permintaan pinjam dari mahasiswa non-pengurus, organisasi luar kampus, institusi, atau masyarakat. Peminjaman internal diatur pada SOP-AST-003. Aset milik kampus atau titipan tidak dipinjamkan kepada pihak eksternal tanpa izin pemiliknya."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf d.","ART Pasal 2 huruf e (kerja sama yang halal dan tidak mengikat dengan pihak eksternal dengan persetujuan Ketua STDIIS).","ART Pasal 3 (Kewajiban BEM) huruf d, e, dan h.","ART Pasal 11 huruf g dan k (larangan mencemarkan nama baik dan memakai fasilitas untuk kepentingan pribadi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pihak eksternal","Perorangan atau lembaga di luar BEM, BPM, HIMA, dan UKM STDIIS."],["Surat Perjanjian Peminjaman","Dokumen yang memuat hak dan kewajiban kedua pihak, jangka waktu, dan tanggung jawab bila aset rusak atau hilang."],["Penjamin","Pihak yang menyatakan bertanggung jawab atas pengembalian aset."],["Jaminan","Identitas atau dokumen yang dititipkan selama masa pinjam sebagaimana disepakati."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Peminjaman hanya untuk tujuan halal, bermanfaat, tidak melanggar syariat, serta tidak merugikan nama baik BEM dan STDIIS.","Setiap peminjaman eksternal memerlukan persetujuan Presiden dan, bila menyangkut kerja sama atau penggunaan di luar kampus, mendapat persetujuan Ketua STDIIS melalui KAUR ORMAWA (ART Pasal 2 huruf e).","Tidak dipinjamkan: aset bernilai tinggi atau sensitif, perangkat berisi data organisasi, serta aset yang masih dibutuhkan kegiatan BEM dalam masa pinjam (kecuali ada persetujuan Presiden).","Peminjam wajib membuat surat permohonan resmi dan melampirkan identitas serta penjamin.","Peminjaman tidak dikenai tarif sebagai usaha; bila ada biaya penggantian operasional, diputuskan Presiden dan dicatat sesuai ketentuan keuangan.","Aset dipakai sesuai tujuan; peminjam tidak boleh meminjamkan kembali.","Kerusakan atau kehilangan diselesaikan sesuai Surat Perjanjian dan SOP-AST-007."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pihak eksternal (peminjam)","R","Mengajukan permohonan, menandatangani perjanjian, menjaga dan mengembalikan aset."],["Petugas Inventaris","R","Memeriksa permohonan dan kondisi aset, menyiapkan perjanjian dan Berita Acara."],["Sekretaris Jenderal","R","Menelaah dan merekomendasikan permohonan."],["Presiden","A","Menyetujui atau menolak peminjaman dan menandatangani perjanjian."],["KAUR ORMAWA / Ketua STDIIS","C","Memberi persetujuan bila disyaratkan."],["Inspektur Jenderal","I","Menerima rekap peminjaman eksternal."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Surat permohonan dari pihak eksternal.","Identitas peminjam dan penjamin.","Daftar Induk Aset dan kalender peminjaman.","Surat Perjanjian Peminjaman dan Berita Acara."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan permohonan: Menerima surat permohonan melalui kanal resmi dan mencatatnya pada Register Peminjaman.","Petugas Inventaris","Surat permohonan","Permohonan tercatat","1 hari kerja"],["2","Verifikasi: Memeriksa tujuan, identitas, ketersediaan aset, dan kesesuaian dengan larangan.","Petugas Inventaris","Permohonan, daftar aset","Layak atau tidak","2 hari kerja"],["3","Telaah: Menelaah risiko, manfaat, dan kebutuhan izin kampus; memberi rekomendasi.","Sekjen","Hasil verifikasi","Rekomendasi tertulis","1 hari kerja"],["4","Persetujuan: Menyetujui atau menolak; bila perlu meminta izin KAUR ORMAWA atau Ketua STDIIS.","Presiden","Rekomendasi","Keputusan tertulis","2 hari kerja"],["5","Perjanjian dan serah terima: Menandatangani Surat Perjanjian, memeriksa kondisi aset bersama, dan membuat Berita Acara.","Presiden, Petugas, Peminjam","Keputusan, aset","Perjanjian dan Berita Acara","Pada hari pinjam"],["6","Pemantauan: Mengingatkan jatuh tempo dan menjawab perpanjangan.","Petugas Inventaris","Register","Pengingat tercatat","H-1 jatuh tempo"],["7","Pengembalian dan penutupan: Menerima aset melalui SOP-AST-004, menutup perjanjian, dan melaporkan kepada Presiden.","Petugas Inventaris","Aset, perjanjian","Peminjaman ditutup","Saat kembali"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Keputusan diberikan paling lambat 5 hari kerja sejak permohonan lengkap. Hasil akhir: Surat Perjanjian, Berita Acara, dan Register Peminjaman yang tertutup."},{"note":"Catatan: angka waktu, kuorum, nilai ambang, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Permohonan menyangkut kerja sama atau pihak berpengaruh: dibawa ke Rapat Pimpinan (SOP-GOV- 005) dan dikonfirmasi kepada KAUR ORMAWA.","Aset rusak atau hilang: SOP-AST-007 dan Surat Perjanjian.","Peminjam terlambat atau tidak kooperatif: Presiden menghubungi pihak peminjam secara tertulis dan melaporkan kepada KAUR ORMAWA bila perlu.","Penggunaan tidak sesuai tujuan atau mencemarkan nama baik: peminjaman dihentikan dan ditangani sesuai SOP-RSK-011."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% peminjaman eksternal disertai perjanjian dan persetujuan Presiden.","Tidak ada aset bernilai tinggi atau sensitif yang dipinjamkan.","Pengembalian tepat waktu pada paling sedikit 90% peminjaman.","Tidak ada sengketa yang tidak terselesaikan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Surat permohonan dan keputusan tertulis.","Surat Perjanjian Peminjaman.","Berita Acara serah terima dan pengembalian.","Register Peminjaman. Seluruh dokumen disimpan pada repositori resmi BEM (folder Aset dan Inventaris) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal melaporkan seluruh peminjaman eksternal pada evaluasi bulanan; Irjen memeriksa kelengkapan dokumen secara sampel."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima permohonan → Verifikasi → Telaah Sekjen → Persetujuan Presiden → Perjanjian dan Berita Acara → Pemantauan → Pengembalian → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permohonan Peminjaman Eksternal","Pemohon dan lembaga; kontak; aset; tujuan; lokasi; tanggal pinjam dan kembali; penjamin; identitas."],["Surat Perjanjian Peminjaman","Para pihak; aset dan kode; jangka waktu; kewajiban; tanggung jawab bila rusak atau hilang; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Tujuan peminjaman halal dan sesuai.","☐ Ya ☐ Tidak"],["2","Identitas peminjam dan penjamin lengkap.","☐ Ya ☐ Tidak"],["3","Aset termasuk kategori yang boleh dipinjamkan.","☐ Ya ☐ Tidak"],["4","Persetujuan Presiden dan izin kampus (bila perlu) tersedia.","☐ Ya ☐ Tidak"],["5","Surat Perjanjian dan Berita Acara ditandatangani.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-AST-009","g":"Inventaris dan Aset","t":"Penyimpanan dan Pengamanan Barang","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[340,343],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan tata cara penyimpanan, penataan, pengamanan, dan pengendalian akses atas barang dan aset BEM, sehingga terlindung dari kehilangan, kerusakan, dan penyalahgunaan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk penyimpanan aset di ruang sekretariat, lemari, gudang, dan tempat lain yang digunakan BEM, serta penyimpanan aset kegiatan pasca-acara. Pengamanan data digital diatur pada SOP-RSK-008 dan SOP- ADM-015."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf d dan ayat (3).","ART Pasal 3 (Kewajiban BEM) huruf d, e, dan h.","ART Pasal 11 huruf i dan k (larangan penyelewengan dan penyalahgunaan fasilitas).","ART Pasal 10 ayat (4) huruf c (penyelesaian masalah internal pada Rapat Koordinasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Tempat penyimpanan","Lemari, rak, laci, atau ruang yang ditetapkan untuk menyimpan aset."],["Akses terbatas","Hak masuk ke tempat penyimpanan hanya bagi orang yang ditunjuk."],["Peta Penyimpanan","Denah atau daftar letak setiap aset."],["Barang bernilai tinggi atau sensitif","Aset yang ditandai khusus pada Daftar Induk Aset."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap aset memiliki tempat tetap yang tercatat pada Peta Penyimpanan; aset dikembalikan ke tempat semula setelah dipakai.","Barang bernilai tinggi atau sensitif disimpan di tempat terkunci dengan akses terbatas.","Penyimpanan memperhatikan kebersihan, kelembapan, dan keselamatan (kabel rapi, alat listrik dimatikan, tidak menumpuk di dekat jalan keluar).","Barang pribadi dipisah dari aset BEM dan tidak menjadi tanggung jawab BEM.","Tidak ada barang titipan pihak lain tanpa catatan tertulis dan persetujuan Sekjen.","Pengambilan aset hanya melalui prosedur peminjaman (SOP-AST-003) atau penugasan yang tercatat.","Kunci tempat penyimpanan dicatat dan hanya dipegang pihak berwenang."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Menetapkan tempat dan aturan akses penyimpanan."],["Petugas Inventaris","R","Menyusun Peta Penyimpanan, memeriksa penataan, dan mengelola akses."],["Menteri / Kabiro (PJ Aset)","R","Menjaga penyimpanan aset unit sesuai aturan."],["Pemegang kunci","R","Menyimpan kunci dan mencatat pemakaiannya."],["KAUR ORMAWA","C","Memberi arahan bila tempat penyimpanan milik kampus."],["Inspektur Jenderal","I","Menerima laporan temuan pengamanan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Induk Aset.","Daftar tempat penyimpanan yang tersedia.","Daftar akses dan pemegang kunci.","Peta Penyimpanan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan tempat: Menentukan tempat penyimpanan tiap kategori aset dan menandai aset bernilai tinggi atau sensitif.","Sekjen dan Petugas Inventaris","Daftar aset, tempat tersedia","Peta Penyimpanan","5 hari kerja"],["2","Penataan: Menata aset sesuai peta, memberi penanda tempat, dan memeriksa kondisi tempat.","PJ Aset","Peta","Aset tertata","3 hari kerja"],["3","Penetapan akses: Menetapkan pemegang kunci dan daftar pengguna; menyerahkan kunci dengan tanda terima.","Sekjen","Daftar akses","Daftar akses dan tanda terima","2 hari kerja"],["4","Pengambilan dan pengembalian: Mencatat setiap pengambilan dan penempatan kembali aset pada log.","Pemegang kunci","Log","Log lengkap","Setiap kejadian"],["5","Pemeriksaan harian dan mingguan: Memeriksa penguncian, kerapian, listrik, dan kebersihan.","Pengurus piket","Checklist","Catatan harian","Harian atau mingguan"],["6","Pemeriksaan bulanan: Mencocokkan isi tempat dengan Peta Penyimpanan dan Daftar Induk Aset.","Petugas Inventaris","Peta, daftar","Catatan bulanan","Setiap bulan"],["7","Penanganan temuan: Menindaklanjuti ketidakwajaran (barang hilang, tempat terbuka, atau kunci hilang).","Sekjen","Catatan temuan","Tindakan korektif","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penataan awal ditargetkan selesai paling lambat 10 hari kerja sejak Daftar Induk Aset disahkan. Hasil akhir: aset tersimpan di tempat tertata dan aman dengan akses terkendali."},{"note":"Catatan: angka waktu, kuorum, nilai ambang, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Aset tidak ditemukan di tempat: SOP-AST-007.","Kunci hilang atau digandakan tanpa izin: dilaporkan kepada Sekjen; kunci diganti dan penanggung jawab dibina melalui SOP-SDM-007.","Penyimpanan tidak aman atau ruang bocor: dilaporkan kepada KAUR ORMAWA; aset dipindahkan sementara.","Ancaman keselamatan: SOP-RSK-003."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% aset memiliki lokasi pada Peta Penyimpanan.","Seluruh aset bernilai tinggi tersimpan terkunci.","Tidak ada temuan akses tanpa izin pada pemeriksaan.","Pemeriksaan bulanan terlaksana pada 100% bulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Peta Penyimpanan.","Daftar akses dan tanda terima kunci.","Log pengambilan dan pengembalian.","Catatan pemeriksaan harian dan bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Aset dan Inventaris) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal meninjau catatan pemeriksaan setiap bulan; Irjen menilai pada pemeriksaan berkala (SOP- AST-010)."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tetapkan tempat dan akses → Tata aset → Catat pengambilan dan pengembalian → Pemeriksaan rutin → Temuan? (ya: tindakan korektif) → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Peta Penyimpanan","Kode aset; nama; tempat penyimpanan; tingkat akses; PJ Aset; tanggal pembaruan."],["Log Pengambilan dan Pengembalian Barang","Tanggal; aset; pengambil; keperluan; waktu keluar dan kembali; petugas."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap aset berada di tempat yang tercatat.","☐ Ya ☐ Tidak"],["2","Aset bernilai tinggi terkunci.","☐ Ya ☐ Tidak"],["3","Daftar akses dan kunci mutakhir.","☐ Ya ☐ Tidak"],["4","Listrik dan kondisi tempat aman.","☐ Ya ☐ Tidak"],["5","Tidak ada barang tanpa catatan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-AST-010","g":"Inventaris dan Aset","t":"Pemeriksaan Inventaris Berkala","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Sekretaris Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[344,347],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pemeriksaan fisik dan dokumen atas seluruh aset BEM secara berkala, untuk memastikan data sesuai kenyataan, menemukan selisih sejak dini, dan menjadi dasar perbaikan pengelolaan aset."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh aset pada Daftar Induk Aset, aset digital, dan perlengkapan di ruang sekretariat serta tempat penyimpanan. Pemeriksaan akhir periode untuk serah terima diatur pada SOP-AST-011 dan SOP-TRN- 005."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 12 ayat (3) dan (4) (kewenangan Irjen dalam pengawasan, evaluasi, dan penilaian kinerja pengurus untuk pembinaan dan pencegahan pelanggaran).","ART Pasal 13 ayat (5) sampai (7) (pemantauan, klarifikasi, evaluasi, dan keadilan).","ART Pasal 10 ayat (4) huruf b (monitoring pada Rapat Koordinasi).","AD Pasal 17 ayat (1) dan (2) (pertanggungjawaban berkala yang transparan dan akuntabel)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pemeriksaan berkala","Pencocokan Daftar Induk Aset dengan kondisi fisik yang dilakukan menurut jadwal."],["Pemeriksaan sampel","Pemeriksaan sebagian aset yang dipilih berdasarkan kriteria atau acak."],["Selisih","Perbedaan data dan fisik: aset tidak ditemukan, berlebih, atau kondisi berbeda."],["Berita Acara Pemeriksaan","Dokumen yang mencatat hasil, selisih, dan rekomendasi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pemeriksaan penuh dilakukan 2 kali dalam periode: tengah periode dan sebelum serah terima (usulan). Pemeriksaan sampel dilakukan setiap bulan (usulan 10% aset atau paling sedikit 10 butir).","Pemeriksa tidak boleh memeriksa aset di unit yang dipimpinnya sendiri agar objektif.","Pemeriksaan memperhatikan keberadaan, kondisi, label, lokasi, dan kesesuaian status dengan Daftar Induk Aset.","Selisih diklarifikasi dengan PJ Aset; pihak terkait berhak menjelaskan sebelum selisih diputuskan (ART Pasal 13 ayat (9)).","Selisih yang tidak terjelaskan dalam batas waktu diteruskan ke SOP-AST-007.","Hasil pemeriksaan disampaikan melalui forum resmi BEM (ART Pasal 13 ayat (6)).","Temuan berulang dicatat untuk perbaikan sistem, bukan semata menyalahkan individu."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Inspektur Jenderal","A","Memimpin pemeriksaan, menandatangani Berita Acara, dan melaporkan hasil."],["Petugas Inventaris","R","Menyiapkan Daftar Induk Aset dan mendampingi pemeriksaan."],["Menteri / Kabiro (PJ Aset)","R","Menunjukkan aset dan memberi klarifikasi atas selisih."],["Sekretaris Jenderal","R","Menindaklanjuti rekomendasi perbaikan."],["Presiden","I","Menerima laporan hasil pemeriksaan."],["KAUR ORMAWA","I","Menerima laporan bila ada temuan berat yang berdampak pada institusi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Induk Aset terkini.","Register Peminjaman dan Kartu Perawatan.","Jadwal pemeriksaan.","Formulir Pemeriksaan Inventaris."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penjadwalan: Menetapkan jadwal pemeriksaan penuh dan sampel serta tim pemeriksa.","Irjen","Kalender kabinet","Jadwal pemeriksaan","Awal tiap semester"],["2","Persiapan: Menyerahkan Daftar Induk Aset, Register Peminjaman, dan menginformasikan unit.","Petugas Inventaris","Daftar, register","Bahan pemeriksaan siap","3 hari kerja sebelum"],["3","Pemeriksaan fisik: Mencocokkan aset dengan daftar: ada, kondisi, label, dan lokasi; memotret temuan.","Irjen dan PJ Aset","Daftar, aset","Catatan pemeriksaan","Sesuai jadwal"],["4","Pemeriksaan dokumen: Mencocokkan register peminjaman, kartu perawatan, dan berita acara dengan fisik.","Irjen","Dokumen","Catatan dokumen","2 hari kerja"],["5","Klarifikasi: Meminta penjelasan PJ Aset atas selisih dan memeriksa bukti tambahan.","Irjen","Temuan","Klarifikasi tertulis","3 hari kerja"],["6","Pelaporan: Menyusun Berita Acara Pemeriksaan dan rekomendasi; menyampaikan di forum resmi BEM.","Irjen","Catatan, klarifikasi","Berita Acara","3 hari kerja"],["7","Tindak lanjut: Memperbarui daftar, memproses selisih (SOP-AST-007), dan memantau pelaksanaan rekomendasi.","Sekjen dan Irjen","Berita Acara","Daftar diperbarui, tindak lanjut tercatat","5 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Berita Acara Pemeriksaan disampaikan paling lambat 5 hari kerja setelah pemeriksaan fisik selesai; rekomendasi ditindaklanjuti paling lambat 10 hari kerja. Hasil akhir: Berita Acara Pemeriksaan dan Daftar Induk Aset yang mutakhir."},{"note":"Catatan: angka waktu, kuorum, nilai ambang, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Selisih besar atau berulang: dibawa ke Rapat Pimpinan (SOP-GOV-005).","Indikasi penyalahgunaan: SOP-RSK-007 dan, bila terbukti, SOP-SDM-013.","Temuan berat yang berdampak pada institusi: Irjen melapor kepada KAUR ORMAWA (ART Pasal 12 ayat (7)).","Perselisihan hasil pemeriksaan: dimediasi Wakil Presiden (SOP-GOV-010)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Pemeriksaan penuh dan sampel terlaksana sesuai jadwal.","Selisih fisik dan catatan kurang dari 5%.","100% selisih terklarifikasi dalam 3 hari kerja.","Rekomendasi ditindaklanjuti dalam 10 hari kerja."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Jadwal dan formulir pemeriksaan.","Berita Acara Pemeriksaan dan rekomendasi.","Daftar Induk Aset yang diperbarui.","Catatan tindak lanjut. Seluruh dokumen disimpan pada repositori resmi BEM (folder Aset dan Inventaris) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen melaporkan hasil pemeriksaan pada evaluasi bulanan dan evaluasi tengah periode; Sekjen memantau tindak lanjut."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Jadwal → Persiapan → Pemeriksaan fisik dan dokumen → Klarifikasi → Berita Acara → Tindak lanjut → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pemeriksaan Inventaris","Kode dan nama aset; ada atau tidak; kondisi; label; lokasi; selisih; keterangan; pemeriksa; tanggal."],["Berita Acara Pemeriksaan Inventaris","Nomor; tanggal; cakupan; hasil; selisih; rekomendasi; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Jadwal dan tim pemeriksa ditetapkan.","☐ Ya ☐ Tidak"],["2","Pemeriksa tidak memeriksa unitnya sendiri.","☐ Ya ☐ Tidak"],["3","Seluruh selisih diklarifikasi.","☐ Ya ☐ Tidak"],["4","Berita Acara ditandatangani dan disampaikan di forum resmi.","☐ Ya ☐ Tidak"],["5","Rekomendasi dipantau sampai selesai.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-AST-011","g":"Inventaris dan Aset","t":"Serah Terima Aset antarpenanggung Jawab","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[348,351],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur serah terima aset antarpenanggung jawab, yaitu antarpengurus, antarunit, dan pada pergantian jabatan, agar tanggung jawab beralih secara tertib, tercatat, dan dapat dipertanggungjawabkan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk perpindahan tanggung jawab aset karena mutasi, pengunduran diri, pemberhentian, atau pergantian PJ Aset di tengah periode. Serah terima akhir kabinet diatur pada SOP-TRN-005; pergantian pengurus pada SOP-SDM-014 dan SOP-SDM-015."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 9 (berhentinya anggota) dan Pasal 10 (masa jabatan).","ART Pasal 5 ayat (7) dan (8) (berhentinya pimpinan dan penggantian).","ART Pasal 3 (Kewajiban BEM) huruf e dan g.","ART Pasal 13 ayat (4) (laporan disertai bukti)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Penyerah","Penanggung jawab aset yang sedang menyerahkan."],["Penerima","Penanggung jawab baru yang menerima aset."],["Berita Acara Serah Terima Aset","Dokumen yang menyatakan aset, jumlah, dan kondisi yang diserahkan serta tanda tangan kedua pihak."],["Saksi","Pihak yang menyaksikan serah terima, yaitu Sekjen atau Irjen."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Serah terima dilakukan secara tertulis dan berdasarkan Daftar Induk Aset terkini; penerimaan lisan tidak dianggap sah.","Aset dihitung dan diperiksa bersama; selisih dicatat pada Berita Acara sebelum penerima menandatangani.","Penyerah tetap bertanggung jawab atas selisih sampai Berita Acara ditandatangani; setelahnya tanggung jawab berpindah.","Pengurus yang berhenti wajib menyelesaikan serah terima sebelum berhenti secara efektif, termasuk pengembalian kunci dan akses digital.","Serah terima dihadiri saksi (Sekjen atau Irjen).","Aset yang sedang dipinjam diserahkan beserta Berita Acara Peminjamannya.","Penerima berhak memeriksa dan menolak menandatangani bila ada ketidaksesuaian yang belum jelas, dan selisih diselesaikan melalui SOP-AST-007."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Penyerah","R","Menyiapkan aset dan dokumen; hadir pada serah terima."],["Penerima","R","Memeriksa aset, menandatangani, dan menjaga aset."],["Petugas Inventaris","R","Menyusun Berita Acara dan memperbarui Daftar Induk Aset."],["Sekretaris Jenderal","A","Menyaksikan, mengesahkan, dan menyimpan arsip serah terima."],["Inspektur Jenderal","C","Menjadi saksi dan memeriksa sampel."],["Presiden","I","Menerima laporan serah terima untuk jabatan penting."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Induk Aset terkini.","Register Peminjaman yang masih berjalan.","Kunci, akun, dan dokumen terkait.","Formulir Berita Acara Serah Terima Aset."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pemberitahuan: Penyerah atau Sekjen memberitahu rencana serah terima dan menetapkan jadwal.","Sekjen","Surat atau keputusan penggantian","Jadwal serah terima","2 hari kerja"],["2","Persiapan: Petugas mencetak daftar aset unit, menandai aset dipinjam, dan memutakhirkan kondisi.","Petugas Inventaris","Daftar Induk Aset","Daftar serah terima","2 hari kerja"],["3","Pencocokan fisik: Penyerah dan penerima menghitung dan memeriksa aset satu per satu; selisih dicatat.","Penyerah, Penerima","Daftar, aset","Hasil pencocokan","Hari serah terima"],["4","Penyelesaian selisih: Selisih diklarifikasi; yang tidak terjelaskan diproses SOP-AST-007.","Sekjen","Catatan selisih","Selisih diselesaikan atau dicatat","3 hari kerja"],["5","Penandatanganan: Penyerah, penerima, dan saksi menandatangani Berita Acara.","Para pihak","Berita Acara","Berita Acara sah","Hari serah terima"],["6","Penyerahan kunci dan akses: Menyerahkan kunci, akses penyimpanan, dan akun terkait aset dengan tanda terima.","Penyerah","Kunci, akses","Tanda terima","Hari serah terima"],["7","Pembaruan dan arsip: Memperbarui PJ Aset pada Daftar Induk Aset dan mengarsipkan Berita Acara.","Petugas Inventaris","Berita Acara","Daftar dan arsip diperbarui","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Serah terima dilaksanakan paling lambat 5 hari kerja sejak pemberitahuan dan diselesaikan sebelum penyerah berhenti efektif. Hasil akhir: Berita Acara Serah Terima Aset yang ditandatangani dan Daftar Induk Aset yang diperbarui."},{"note":"Catatan: angka waktu, kuorum, nilai ambang, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Penyerah tidak hadir atau tidak kooperatif: Sekjen menunjuk saksi, serah terima dilakukan sepihak dengan pemeriksaan Irjen, dan hal itu dicatat serta ditangani melalui SOP-SDM-013.","Selisih aset: SOP-AST-007.","Penerima menolak menandatangani: diputuskan Presiden setelah mendengar kedua pihak.","Serah terima akhir kabinet: SOP-TRN-005."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pergantian PJ Aset disertai Berita Acara.","Daftar Induk Aset diperbarui dalam 2 hari kerja.","Tidak ada aset tanpa PJ Aset yang jelas.","Selisih serah terima menurun dari waktu ke waktu."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Berita Acara Serah Terima Aset.","Daftar serah terima beserta catatan selisih.","Tanda terima kunci dan akses.","Daftar Induk Aset yang diperbarui. Seluruh dokumen disimpan pada repositori resmi BEM (folder Aset dan Inventaris) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan Berita Acara serah terima setiap bulan; Irjen menilai pada pemeriksaan berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pemberitahuan → Persiapan daftar → Pencocokan fisik → Selesaikan selisih → Tanda tangan → Serah kunci dan akses → Perbarui daftar → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Berita Acara Serah Terima Aset","Nomor; penyerah dan penerima; daftar aset dan kondisi; selisih; saksi; tanggal; tanda tangan."],["Tanda Terima Kunci dan Akses","Jenis kunci atau akses; jumlah; tanggal; penyerah; penerima; keterangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Jadwal dan saksi ditetapkan.","☐ Ya ☐ Tidak"],["2","Seluruh aset dicocokkan satu per satu.","☐ Ya ☐ Tidak"],["3","Aset dipinjam disertakan Berita Acaranya.","☐ Ya ☐ Tidak"],["4","Kunci dan akses diserahkan dengan tanda terima.","☐ Ya ☐ Tidak"],["5","Daftar Induk Aset diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-AST-012","g":"Inventaris dan Aset","t":"Penghapusan atau Pemindahtanganan Aset sesuai Aturan","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[352,355],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penghapusan dan pemindahtanganan aset BEM yang rusak berat, hilang, usang, atau tidak lagi dibutuhkan, secara sah, transparan, dan sesuai aturan kampus serta syariat."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk aset milik BEM, termasuk pemusnahan, hibah kepada pihak lain, atau penyerahan kepada kampus. Aset milik kampus atau titipan dikembalikan kepada pemiliknya dan tidak dihapus oleh BEM."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf b dan d, ayat (2), dan ayat (3) (hibah, aset, bebas riba, gharar, maysir, dan dokumentasi).","AD Pasal 17 ayat (1) sampai (3) (pertanggungjawaban berkala, transparan, dan akuntabel).","ART Pasal 3 (Kewajiban BEM) huruf e, g, dan h.","ART Pasal 11 huruf i dan k (larangan penyelewengan dan penggunaan fasilitas untuk kepentingan pribadi).","ART Pasal 12 dan Pasal 13 (pengawasan Irjen dan penanganan pelanggaran)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Penghapusan","Pencatatan keluarnya aset dari Daftar Induk Aset karena alasan sah."],["Pemindahtanganan","Pengalihan penguasaan aset kepada pihak lain, misalnya hibah, penyerahan kepada kampus, atau penjualan bila diizinkan."],["Pemusnahan","Penghancuran aset yang tidak layak dan tidak bernilai."],["Tim Penilai","Tim yang menilai kondisi dan nilai wajar aset."],["Berita Acara Penghapusan","Dokumen resmi penghapusan beserta alasan dan tindak lanjut."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Alasan penghapusan yang sah: rusak berat tidak ekonomis, usang, hilang yang telah diputuskan (SOP- AST-007), tidak lagi dibutuhkan, atau diserahkan kepada pemiliknya.","Penghapusan oleh Sekjen disetujui Presiden; aset bernilai tinggi (usulan Rp1.000.000 ke atas) dilaporkan atau dimintakan persetujuan KAUR ORMAWA/Pembina.","Penilaian dilakukan tim yang tidak berkepentingan; Irjen memeriksa sebelum persetujuan.","Pemindahtanganan melalui hibah atau penyerahan kepada kampus didahulukan; penjualan hanya bila diizinkan kampus, dengan harga wajar, transparan, dan dihindari dari unsur riba, gharar, dan maysir.","Hasil penjualan masuk kas organisasi dan dicatat sesuai SOP-KEU-005; tidak boleh dikuasai pribadi.","Pengurus dilarang membeli atau menerima aset yang dihapus tanpa prosedur terbuka dan persetujuan Presiden (larangan konflik kepentingan; SOP-RSK-006).","Aset yang berisi data dihapus datanya secara aman sebelum dipindahtangankan atau dimusnahkan.","Seluruh proses terdokumentasi dan dilaporkan dalam laporan pertanggungjawaban."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","R","Mengajukan usulan penghapusan dan menyusun dokumen."],["Petugas Inventaris","R","Menyiapkan daftar, foto, dan memperbarui Daftar Induk Aset."],["Tim Penilai","R","Menilai kondisi dan nilai wajar aset."],["Inspektur Jenderal","C","Memeriksa alasan, bukti, dan kepatuhan prosedur."],["Biro Keuangan","C","Mencatat hasil penjualan bila ada."],["Presiden","A","Menyetujui penghapusan dan menetapkan bentuk pemindahtanganan."],["KAUR ORMAWA / Pembina","C","Memberi persetujuan atau arahan untuk aset bernilai tinggi atau yang menyangkut kampus."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Usulan penghapusan beserta alasan dan foto.","Laporan kondisi atau keputusan SOP-AST-007.","Daftar Induk Aset dan Kartu Perawatan.","Hasil penilaian nilai wajar."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Usulan: Mengajukan usulan penghapusan dengan alasan dan bukti dukung.","Sekjen","Laporan kondisi, foto","Usulan tertulis","Kapan saja"],["2","Penilaian: Menilai kondisi dan nilai wajar serta merekomendasikan bentuk penghapusan.","Tim Penilai","Aset, kartu","Hasil penilaian","5 hari kerja"],["3","Pemeriksaan: Memeriksa alasan, bukti, kewajaran nilai, dan potensi konflik kepentingan.","Irjen","Usulan, penilaian","Catatan pemeriksaan","3 hari kerja"],["4","Persetujuan: Menyetujui; bila bernilai tinggi atau menyangkut kampus, meminta persetujuan KAUR ORMAWA atau Pembina.","Presiden","Usulan, catatan Irjen","Keputusan tertulis","3 hari kerja"],["5","Pelaksanaan: Melaksanakan bentuk yang disetujui: hibah, penyerahan kepada kampus, penjualan terbuka, atau pemusnahan; menghapus data sensitif.","Sekjen dan Petugas","Keputusan","Aset dialihkan atau dimusnahkan","7 hari kerja"],["6","Dokumentasi: Membuat Berita Acara Penghapusan, memotret pelaksanaan, dan mencatat penerimaan hasil penjualan melalui Biro Keuangan.","Petugas, Biro Keuangan","Hasil pelaksanaan","Berita Acara, bukti","2 hari kerja"],["7","Pembaruan dan pelaporan: Mengubah status aset menjadi \"dihapus\" pada Daftar Induk Aset dan melaporkan pada laporan berkala.","Petugas dan Sekjen","Berita Acara","Daftar diperbarui, laporan","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Seluruh proses ditargetkan selesai paling lambat 25 hari kerja sejak usulan lengkap. Hasil akhir: Berita Acara Penghapusan dan Daftar Induk Aset yang diperbarui."},{"note":"Catatan: angka waktu, kuorum, nilai ambang, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Dugaan penyimpangan dalam penghapusan: SOP-RSK-007.","Konflik kepentingan (pengurus ingin memperoleh aset): ditolak kecuali melalui prosedur terbuka dan persetujuan Presiden; SOP-RSK-006.","Perbedaan penilaian nilai: dinilai ulang oleh tim lain atau dimintakan pendapat Biro Keuangan.","Aset milik kampus atau titipan: dikembalikan kepada pemiliknya dan tidak diproses melalui SOP ini."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% penghapusan disertai persetujuan tertulis dan Berita Acara.","Tidak ada penghapusan tanpa pemeriksaan Irjen.","Seluruh hasil penjualan tercatat pada kas organisasi.","Daftar Induk Aset sesuai dengan penghapusan paling lambat 3 hari kerja."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Usulan dan hasil penilaian.","Catatan pemeriksaan Irjen dan keputusan Presiden.","Berita Acara Penghapusan dan foto pelaksanaan.","Bukti penerimaan (bila ada) dan Daftar Induk Aset yang diperbarui. Seluruh dokumen disimpan pada repositori resmi BEM (folder Aset dan Inventaris) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen meninjau seluruh penghapusan setiap semester; Sekjen melaporkannya pada laporan bulanan dan laporan akhir kabinet."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Usulan → Penilaian → Periksa Irjen → Persetujuan Presiden (dan kampus bila perlu) → Pelaksanaan → Berita Acara → Perbarui daftar → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Usulan Penghapusan Aset","Aset dan kode; alasan; kondisi; foto; nilai perolehan dan taksiran; usulan bentuk; pengusul; tanggal."],["Berita Acara Penghapusan Aset","Nomor; aset; alasan; persetujuan; bentuk pelaksanaan; penerima (bila ada); hasil; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Alasan penghapusan sah dan terbukti.","☐ Ya ☐ Tidak"],["2","Aset bukan milik kampus atau titipan.","☐ Ya ☐ Tidak"],["3","Pemeriksaan Irjen dan persetujuan sesuai tingkat nilai.","☐ Ya ☐ Tidak"],["4","Pelaksanaan terbuka, dan data sensitif dihapus.","☐ Ya ☐ Tidak"],["5","Daftar Induk Aset dan laporan diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-GOV-001","g":"Tata Kelola dan Kepemimpinan","t":"Pembagian Tugas dan Wewenang","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[360,363],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan, pengesahan, sosialisasi, dan peninjauan pembagian tugas serta wewenang antara pimpinan, kementerian, biro, dan Inspektorat Jenderal, sehingga setiap pekerjaan penting memiliki penanggung jawab yang jelas dan tidak melampaui AD/ART maupun peraturan kampus."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk Presiden, Wakil Presiden, Sekretaris Jenderal, Menteri, Kepala Biro, Inspektur Jenderal, dan seluruh pengurus BEM Kabinet Samasta. SOP ini tidak mengatur pendelegasian sementara (lihat SOP-GOV- 008) dan tidak mengatur pengangkatan pengurus (lihat SOP-SDM-001)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 7 dan Pasal 13 (susunan pengurus dan pimpinan BEM).","AD Pasal 11 ayat (2) huruf b (pengangkatan Menteri dan Kabiro secara prerogatif oleh Presiden melalui forum musyawarah internal).","ART Pasal 4 (Wewenang BEM), khususnya huruf a, b, dan f.","ART Pasal 5 ayat (2) dan (6) (susunan pengurus, kementerian, dan biro).","ART Pasal 12 (kewenangan Irjen dalam pengawasan dan penilaian kinerja pengurus)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Matriks kewenangan (RACI)","Dokumen yang menjelaskan siapa yang melaksanakan (R), bertanggung jawab akhir (A), dimintai masukan (C), dan diberi informasi (I) pada setiap aktivitas."],["Uraian tugas","Rincian tugas, hasil kerja, dan batas wewenang suatu jabatan atau unit."],["Pihak A","Pihak yang bertanggung jawab akhir atas hasil suatu proses; hanya satu untuk setiap aktivitas."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan pembagian tugas dan wewenang melalui Keputusan Presiden."],["Wakil Presiden","R","Mengoordinasikan Eksekutif, menelaah usulan unit, memastikan tidak ada tumpang tindih tugas."],["Sekretaris Jenderal","R","Menyusun peta tugas, draf matriks, uraian tugas; mensosialisasikan dan mengarsipkan."],["Menteri / Kabiro","R","Mengusulkan tugas dan batas wewenang unit, menyusun uraian tugas unit."],["Inspektur Jenderal","C","Memeriksa keselarasan draf dengan AD/ART dan peraturan kampus."],["Seluruh pengurus","I","Memahami dan menjalankan pembagian tugas yang berlaku."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["AD/ART dan peraturan kampus.","Struktur kabinet yang telah ditetapkan.","Hasil Rapat Kerja dan arsip kabinet sebelumnya.","Usulan tugas dari setiap unit."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pemetaan tugas: Menginventarisasi tugas dan kewenangan dari AD/ART, peraturan kampus, dan dokumen kabinet sebelumnya; mencatat proses yang belum jelas pemiliknya.","Sekjen","AD/ART, aturan kampus, arsip","Draf peta tugas","3 hari kerja setelah struktur ditetapkan"],["2","Usulan unit: Mengisi Formulir Usulan Tugas Unit: tugas utama, hasil kerja, batas wewenang, dan pihak yang perlu dikoordinasikan.","Menteri / Kabiro","Peta tugas","Usulan tertulis tiap unit","3 hari kerja"],["3","Penyusunan matriks: Menggabungkan usulan, menghapus tumpang tindih, menetapkan satu pihak A pada tiap aktivitas, lalu menyusun draf matriks kewenangan dan uraian tugas.","Sekjen bersama Wapres","Usulan unit","Draf matriks dan uraian tugas","3 hari kerja"],["4","Pemeriksaan keselarasan: Memeriksa draf dengan Checklist Keselarasan; memberi catatan tertulis bila ada ketentuan yang bertentangan dengan AD/ART atau aturan kampus.","Irjen","Draf, checklist","Catatan pemeriksaan","2 hari kerja"],["5","Pembahasan: Membahas draf pada rapat kabinet secara musyawarah (SOP-GOV-002), lalu merevisi sesuai catatan.","Pimpinan dan Eksekutif","Draf, catatan Irjen","Draf final","1 kali rapat; revisi 2 hari kerja"],["6","Pengesahan: Menetapkan matriks dan uraian tugas melalui Keputusan Presiden. Bagian yang menyangkut program kerja mengikuti persetujuan Pembina melalui alur Rapat Kerja.","Presiden","Draf final","Keputusan Presiden","2 hari kerja"],["7","Sosialisasi dan arsip: Membagikan dokumen melalui kanal resmi, menyimpan di repositori, dan mencatat pada Register Dokumen.","Sekjen","Keputusan Presiden","Distribusi tercatat, arsip","3 hari kerja setelah pengesahan"],["8","Peninjauan berkala: Meninjau ulang matriks saat struktur berubah, ada pengangkatan atau pemberhentian pengurus, dan pada evaluasi tengah periode.","Sekjen dan Irjen","Hasil evaluasi, temuan","Revisi atau penegasan matriks","Setiap ada pemicu"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Penyusunan awal dari pemetaan hingga pengesahan ditargetkan paling lambat 15 hari kerja sejak struktur kabinet ditetapkan. Hasil akhir: Keputusan Presiden beserta matriks kewenangan dan uraian tugas."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Tumpang tindih tugas antarunit diputuskan Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Temuan Irjen berupa pertentangan dengan AD/ART: ketentuan wajib diubah; bila perlu penafsiran, dikonsultasikan kepada KAUR ORMAWA atau Pembina.","Perselisihan kewenangan antarpengurus: SOP-GOV-010.","Kebutuhan mengubah AD/ART tidak diputuskan melalui SOP ini; ikuti AD Bab XI dan ART Bab VII."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% aktivitas utama memiliki tepat satu pihak A.","Tidak ada temuan pertentangan dengan AD/ART pada pemeriksaan Irjen.","Dokumen tersosialisasi paling lambat 3 hari kerja setelah pengesahan.","Jumlah sengketa kewenangan per bulan menurun dari bulan ke bulan."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Keputusan Presiden tentang pembagian tugas dan wewenang.","Matriks kewenangan (RACI) dan uraian tugas tiap unit.","Catatan pemeriksaan Irjen.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tata Kelola) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa ketersediaan dan versi terkini dokumen setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pemetaan tugas → Usulan unit → Draf matriks → Periksa Irjen → Pembahasan → Pengesahan Presiden → Sosialisasi dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Usulan Tugas Unit","Nama unit; pengusul; tugas utama; hasil kerja; batas wewenang; pihak yang dikoordinasikan; tanggal."],["Templat Matriks Kewenangan (RACI)","Aktivitas; R; A; C; I; dasar aturan; keterangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap aktivitas memiliki tepat satu pihak A.","☐ Ya ☐ Tidak"],["2","Tidak ada kewenangan yang bertentangan dengan AD/ART dan aturan kampus.","☐ Ya ☐ Tidak"],["3","Fungsi pengaju, pemberi persetujuan, pemegang dana, dan pemeriksa dipisahkan pada aktivitas keuangan.","☐ Ya ☐ Tidak"],["4","Uraian tugas seluruh unit tersedia.","☐ Ya ☐ Tidak"],["5","Dokumen tercatat pada Register Dokumen.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-GOV-002","g":"Tata Kelola dan Kepemimpinan","t":"Pengambilan Keputusan","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[364,368],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan tingkatan keputusan, forum yang berwenang, cara pengambilan keputusan secara musyawarah, serta pencatatan dan tindak lanjutnya, agar setiap keputusan sah, dapat dipertanggungjawabkan, dan tidak bertentangan dengan AD/ART."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh keputusan BEM di tingkat pimpinan, kabinet, dan unit. Keputusan forum permusyawaratan (Mubes dan Musyawarah Istimewa) tetap mengikuti AD/ART; SOP ini hanya mengatur keterkaitannya. Keputusan mendesak diatur pada SOP-GOV-012."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 4 (kedaulatan di tangan mahasiswa, prinsip partisipatif, kolaboratif, dan demokratis; diwujudkan melalui Mubes).","AD Pasal 11 ayat (2) (demokrasi permusyawaratan) dan Pasal 14 (cara pengambilan keputusan).","ART Pasal 7 ayat (6) sampai (8) (kuorum dan keputusan Mubes).","ART Pasal 8 ayat (5) sampai (7) (kuorum dan keputusan Musyawarah Istimewa).","ART Pasal 9 ayat (4) dan (6) (keputusan Rapat Kerja dan persetujuan Pembina).","ART Pasal 4 (Wewenang BEM)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Mufakat","Kesepakatan yang dicapai melalui musyawarah tanpa pemungutan suara."],["Suara terbanyak","Persetujuan sekurang-kurangnya 50% + 1 dari peserta yang hadir."],["Kuorum","Jumlah minimal peserta hadir agar rapat sah."],["Lembar Keputusan","Formulir resmi pencatatan satu keputusan."],["Pemrakarsa","Pengurus atau unit yang mengajukan usulan keputusan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Tingkat 1 - Forum permusyawaratan: Mubes (kuorum 50% peserta berhak hadir; keputusan mufakat atau 50%+1 yang hadir; berita acara disahkan Ketua STDIIS atau pejabat yang ditunjuk) dan Musyawarah Istimewa (kuorum 50%+1; berita acara disahkan Ketua STDIIS).","Tingkat 2 - Rapat Kerja dan rapat kabinet: program kerja tahunan diputuskan mufakat atau pemungutan suara, dan wajib mendapat persetujuan Pembina sebelum dilaksanakan.","Tingkat 3 - Keputusan pimpinan: kebijakan pelaksanaan kegiatan dan pengangkatan Menteri/Kabiro oleh Presiden secara prerogatif melalui forum musyawarah internal.","Tingkat 4 - Keputusan unit: terbatas pada batas wewenang dalam uraian tugas.","Prinsip: musyawarah mufakat didahulukan; pemungutan suara dilakukan bila mufakat tidak tercapai; satu orang satu suara; pendapat berbeda dicatat.","Rapat internal kabinet dan pimpinan: kuorum 50%+1 dari peserta berhak hadir (usulan, mengacu pada ART Pasal 8 ayat 5 karena ART tidak mengatur kuorum rapat internal).","Keputusan yang membutuhkan persetujuan pihak luar (Pembina, KAUR ORMAWA, BPM, Ketua STDIIS) belum berlaku sebelum persetujuan diperoleh.","Keputusan yang bertentangan dengan AD/ART atau peraturan kampus tidak sah dan wajib ditinjau ulang."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pemrakarsa","R","Menyusun usulan keputusan lengkap dengan opsi dan dasar aturan."],["Sekretaris Jenderal","R","Mengklasifikasi tingkat keputusan, memverifikasi kewenangan, mencatat, dan mengarsipkan."],["Pimpinan rapat (Presiden/Wapres/ditunjuk)","R","Memimpin musyawarah, memeriksa kuorum, menetapkan hasil."],["Presiden","A","Bertanggung jawab akhir atas keputusan dan mengesahkannya."],["Peserta rapat","C","Memberi pendapat dan hak suara."],["Inspektur Jenderal","C","Menelaah kesesuaian keputusan dengan AD/ART bila diminta atau ada indikasi pertentangan."],["Penerima keputusan","I","Menjalankan dan memberi umpan balik pelaksanaan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Lembar Usulan Keputusan.","Dasar aturan dan data pendukung.","Matriks kewenangan (SOP-GOV-001)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan usulan: Mengisi Lembar Usulan Keputusan: masalah, opsi, rekomendasi, dampak anggaran dan aturan.","Pemrakarsa","Data dan dasar aturan","Usulan tercatat","Paling lambat 2 hari kerja sebelum rapat"],["2","Klasifikasi dan verifikasi kewenangan: Menentukan tingkat keputusan, forum, pejabat berwenang, dan ada tidaknya persetujuan pihak luar yang dibutuhkan.","Sekjen","Usulan, matriks kewenangan","Forum dan agenda ditetapkan","1 hari kerja"],["3","Penyiapan rapat: Memasukkan ke agenda; mengirim bahan dan undangan sesuai SOP rapat terkait.","Sekjen","Agenda","Undangan dan bahan","H-1"],["4","Pembahasan: Memeriksa kuorum, membuka dengan doa, memberi kesempatan setiap pihak berpendapat, merangkum opsi.","Pimpinan rapat","Bahan rapat","Opsi yang jelas","Dalam rapat"],["5","Pengambilan keputusan: Mengupayakan mufakat. Bila tidak tercapai, dilakukan pemungutan suara; keputusan sah jika disetujui 50%+1 peserta hadir. Bila suara seimbang, pembahasan ditunda satu kali (maks. 2 hari kerja); bila tetap seimbang, Presiden memutuskan untuk keputusan internal kabinet.","Pimpinan rapat dan peserta","Opsi","Keputusan dan pendapat berbeda","Dalam rapat"],["6","Pencatatan: Menuangkan hasil pada Lembar Keputusan dan notulen. Untuk forum permusyawaratan disusun Berita Acara yang ditandatangani pimpinan sidang.","Sekjen / notulis","Hasil rapat","Lembar Keputusan, notulen","1 hari kerja (Lembar); 2 hari kerja (notulen)"],["7","Pengesahan dan persetujuan pihak luar: Menandatangani keputusan; mengajukan keputusan yang memerlukan persetujuan Pembina, KAUR ORMAWA, BPM, atau Ketua STDIIS. Keputusan berlaku setelah persetujuan diperoleh.","Presiden","Lembar Keputusan","Keputusan sah","2 hari kerja"],["8","Komunikasi dan tindak lanjut: Mengumumkan melalui kanal resmi, memasukkan tindak lanjut ke daftar tindak lanjut, menetapkan penanggung jawab dan tenggat.","Sekjen","Keputusan sah","Pengumuman, daftar tindak lanjut","2 hari kerja setelah rapat"],["9","Pengarsipan: Mencatat pada Register Keputusan dan menyimpan dokumen di repositori resmi.","Sekjen","Dokumen keputusan","Arsip lengkap","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Keputusan diumumkan paling lambat 2 hari kerja setelah rapat. Hasil akhir: Lembar Keputusan yang ditandatangani dan tercatat pada register."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Buntu setelah penundaan: diputuskan Presiden (keputusan internal) atau dibawa ke Rapat Pimpinan.","Kewenangan tidak jelas: rujuk matriks kewenangan; bila masih ragu, konsultasi kepada KAUR ORMAWA atau Pembina.","Keputusan diduga bertentangan dengan AD/ART: ditunda dan ditelaah Irjen.","Keputusan yang tidak dapat menunggu rapat: SOP-GOV-012.","Masalah yang menurut ART harus diputus Musyawarah Istimewa tidak boleh diputus di rapat kabinet."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% keputusan tercatat pada Register Keputusan.","Keputusan diumumkan paling lambat 2 hari kerja setelah rapat.","Tidak ada keputusan dibatalkan karena melampaui kewenangan.","Minimal 80% tindak lanjut selesai sesuai tenggat."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Keputusan bertanda tangan.","Notulen dan, bila forum permusyawaratan, Berita Acara.","Daftar tindak lanjut.","Entri Register Keputusan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tata Kelola) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal merekap Register Keputusan setiap bulan; Irjen mengambil sampel keputusan untuk diperiksa kesesuaiannya dengan AD/ART."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Usulan keputusan → Klasifikasi dan verifikasi kewenangan → Pembahasan → Mufakat? Jika tidak, voting → Pencatatan → Pengesahan (dan persetujuan luar bila perlu) → Tindak lanjut dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Usulan Keputusan","Pemrakarsa; masalah; opsi; rekomendasi; dasar aturan; dampak anggaran; persetujuan pihak luar yang diperlukan."],["Lembar Keputusan","Nomor; tanggal; forum; kuorum; ringkasan keputusan; hasil mufakat atau voting (jumlah suara); pendapat berbeda; penanggung jawab; tenggat; tanda tangan."],["Register Keputusan","Nomor; tanggal; judul; tingkat; penanggung jawab; status tindak lanjut; lokasi arsip."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kuorum terpenuhi dan tercatat.","☐ Ya ☐ Tidak"],["2","Forum dan pejabat berwenang sudah diverifikasi.","☐ Ya ☐ Tidak"],["3","Pendapat berbeda dicatat.","☐ Ya ☐ Tidak"],["4","Persetujuan pihak luar (jika perlu) sudah dimintakan.","☐ Ya ☐ Tidak"],["5","Keputusan diumumkan, tindak lanjut ditetapkan, dan arsip tersimpan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-GOV-003","g":"Tata Kelola dan Kepemimpinan","t":"Koordinasi Pimpinan","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[369,372],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara Presiden, Wakil Presiden, dan Sekretaris Jenderal berkoordinasi secara rutin agar arah kebijakan, pembagian peran, dan tindak lanjut pekerjaan pimpinan selaras dan satu suara."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Koordinasi rutin tiga unsur pimpinan BEM. Rapat pimpinan yang menghasilkan keputusan formal diatur pada SOP-GOV-005."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 7 dan Pasal 13 (pimpinan BEM terdiri atas Presiden, Wakil Presiden, dan Sekretaris Jenderal).","ART Pasal 5 ayat (6) dan (8) (struktur minimal dan penggantian Presiden).","ART Pasal 10 (Rapat Koordinasi).","ART Pasal 4 (Wewenang BEM)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Koordinasi pimpinan","Pertemuan atau komunikasi terjadwal antara Presiden, Wakil Presiden, dan Sekjen untuk menyelaraskan sikap dan tindak lanjut."],["Satu suara","Sikap bersama pimpinan yang disampaikan kepada Eksekutif dan pihak luar."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Presiden menetapkan arah dan mengambil keputusan akhir; Wakil Presiden mengoordinasikan Eksekutif dan mendampingi Presiden; Sekjen menyelenggarakan administrasi, pencatatan, dan pemantauan tindak lanjut. Rincian mengikuti Keputusan Presiden pada SOP-GOV-001.","Perbedaan pendapat antarpimpinan diselesaikan di internal pimpinan dan tidak disampaikan terbuka kepada Eksekutif atau pihak luar.","Koordinasi memakai kanal resmi; hal penting tidak boleh hanya disepakati secara lisan dan wajib dicatat.","Frekuensi minimal satu kali per pekan (usulan; ditetapkan final setelah uji coba)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Memimpin koordinasi, menetapkan arah dan keputusan akhir."],["Wakil Presiden","R","Menyampaikan kondisi Eksekutif; menindaklanjuti hasil kepada Menteri/Kabiro."],["Sekretaris Jenderal","R","Menyusun agenda, mencatat, dan memantau tindak lanjut."],["Inspektur Jenderal","C","Memberi masukan bila ada temuan pengawasan yang perlu diketahui pimpinan."],["Menteri / Kabiro","I","Menerima hasil yang relevan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan progres unit.","Daftar tindak lanjut sebelumnya.","Kalender organisasi.","Temuan atau catatan Irjen."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengumpulan isu: Menghimpun isu dari laporan unit, temuan Irjen, daftar tindak lanjut, dan kalender.","Sekjen","Laporan, kalender","Daftar isu","H-2"],["2","Penyusunan agenda: Memprioritaskan isu menjadi tiga golongan: perlu keputusan, perlu informasi, perlu antisipasi risiko.","Sekjen; disetujui Presiden","Daftar isu","Agenda ringkas","H-1"],["3","Pelaksanaan koordinasi: Meninjau tindak lanjut sebelumnya, membahas isu strategis, menyepakati posisi bersama.","Presiden (memimpin)","Agenda","Kesepakatan pimpinan","Maks. 90 menit (usulan)"],["4","Klasifikasi hasil: Memilah hasil: (a) keputusan yang dapat langsung ditetapkan pimpinan, (b) perlu dibawa ke rapat kabinet, (c) perlu persetujuan pihak luar.","Pimpinan","Kesepakatan","Daftar klasifikasi","Dalam koordinasi"],["5","Pencatatan: Menyusun ringkasan hasil dan daftar tindak lanjut beserta penanggung jawab dan tenggat.","Sekjen","Catatan koordinasi","Ringkasan hasil","1 hari kerja"],["6","Penyampaian kepada Eksekutif: Menyampaikan hasil yang relevan kepada Menteri/Kabiro melalui kanal resmi.","Wakil Presiden","Ringkasan","Instruksi diterima","1 hari kerja"],["7","Pemantauan tindak lanjut: Memantau pelaksanaan dan melaporkan status pada koordinasi berikutnya.","Sekjen","Daftar tindak lanjut","Status tindak lanjut","Setiap pertemuan"],["8","Penyelesaian perbedaan: Bila pimpinan belum sepakat, gunakan mekanisme SOP-GOV-002; bila menyangkut hubungan antarpimpinan, gunakan SOP-GOV-010.","Presiden","Catatan perbedaan","Keputusan atau rujukan","Maks. 3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Ringkasan hasil dikirim paling lambat 1 hari kerja setelah koordinasi. Hasil akhir: ringkasan koordinasi dan daftar tindak lanjut yang diperbarui."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Isu melampaui kewenangan BEM: diajukan kepada Pembina, KAUR ORMAWA, atau Ketua STDIIS melalui prosedur audiensi.","Pimpinan tidak sepakat: SOP-GOV-002 lalu SOP-GOV-010.","Salah satu pimpinan berhalangan: SOP-GOV-009."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Koordinasi terlaksana minimal sesuai frekuensi yang ditetapkan.","100% hasil koordinasi tercatat dalam 1 hari kerja.","Minimal 80% tindak lanjut pimpinan selesai tepat waktu."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Agenda koordinasi.","Ringkasan hasil dan daftar tindak lanjut.","Arsip digital pada folder pimpinan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tata Kelola) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal melaporkan kepatuhan jadwal koordinasi dan ketepatan tindak lanjut pada evaluasi bulanan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kumpulkan isu → Susun agenda → Koordinasi pimpinan → Klasifikasi hasil → Catat dan sampaikan ke Eksekutif → Pantau tindak lanjut → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Agenda Koordinasi Pimpinan","Tanggal; isu; golongan (keputusan/informasi/risiko); penanggung jawab."],["Templat Ringkasan dan Tindak Lanjut","Hasil; klasifikasi; penanggung jawab; tenggat; status."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Agenda dikirim H-1.","☐ Ya ☐ Tidak"],["2","Semua hasil penting tercatat.","☐ Ya ☐ Tidak"],["3","Hasil relevan disampaikan kepada Eksekutif dalam 1 hari kerja.","☐ Ya ☐ Tidak"],["4","Tindak lanjut dipantau pada pertemuan berikutnya.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-GOV-004","g":"Tata Kelola dan Kepemimpinan","t":"Koordinasi Antarkementerian atau Antarunit","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[373,376],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara kementerian, biro, dan unit lain meminta, menyepakati, melaksanakan, dan menutup koordinasi lintas unit dengan menyebut jelas pihak, keputusan yang diperlukan, hasil kerja, dan tenggatnya."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh kebutuhan koordinasi antarkementerian, antarbiro, tim acara, dan unit lain di dalam BEM. Koordinasi dengan ormawa lain dan pihak luar mengikuti SOP kelompok Hubungan Eksternal (HKE)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Bab III (Tugas BEM) huruf d dan f (koordinasi antar-ormawa dan seluruh kegiatan kemahasiswaan).","ART Pasal 4 huruf c (usulan panitia kegiatan dan tim kerja internal).","ART Pasal 5 ayat (2) (kementerian dan biro).","ART Pasal 10 (Rapat Koordinasi).","ART Pasal 13 ayat (3) (pengawasan BPH atas dugaan pelanggaran kementerian/biro)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Unit utama (lead)","Unit yang bertanggung jawab atas hasil akhir pekerjaan lintas unit."],["Unit pendukung","Unit yang memberi kontribusi tertentu kepada unit utama."],["Lembar Kesepakatan Antarunit","Catatan tertulis tentang peran, hasil kerja, dan tenggat yang disepakati."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Frasa seperti \"dikoordinasikan dengan pihak terkait\" tidak dipakai tanpa menyebut nama unit, keputusan yang diperlukan, dan hasil yang harus dibuat.","Setiap koordinasi lintas unit memiliki satu unit utama.","Koordinasi dilakukan melalui kanal resmi dengan tembusan Sekjen agar tercatat."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pemrakarsa (unit peminta)","R","Mengajukan kebutuhan, melaksanakan bagiannya, dan menutup koordinasi."],["Unit tujuan","R","Menanggapi dan melaksanakan peran yang disepakati."],["Wakil Presiden","A","Menengahi dan memutuskan bila unit tidak sepakat."],["Sekretaris Jenderal","R","Memfasilitasi, mencatat kesepakatan, dan memantau."],["Inspektur Jenderal","I","Menerima rekap untuk bahan pengawasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Rencana kerja unit.","Formulir Permintaan Koordinasi.","Kalender organisasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Identifikasi kebutuhan: Menentukan apa yang dibutuhkan dari unit lain: data, tenaga, dana, keputusan, atau fasilitas, beserta tanggal dibutuhkan.","Pemrakarsa","Rencana kerja","Rumusan kebutuhan","Sesuai kebutuhan"],["2","Permintaan koordinasi: Mengirim Formulir Permintaan Koordinasi kepada unit tujuan dengan tembusan Sekjen dan Wakil Presiden.","Pemrakarsa","Rumusan kebutuhan","Permintaan tercatat","Minimal 5 hari kerja sebelum dibutuhkan (kecuali mendesak)"],["3","Tanggapan: Menerima, menolak dengan alasan tertulis, atau mengusulkan alternatif.","Unit tujuan","Permintaan","Tanggapan tertulis","2 hari kerja"],["4","Kesepakatan: Bertemu singkat bila perlu; menetapkan unit utama, peran pendukung, hasil kerja, dan tenggat dalam Lembar Kesepakatan Antarunit.","Pemrakarsa dan unit tujuan; difasilitasi Sekjen","Tanggapan","Lembar Kesepakatan","3 hari kerja"],["5","Pelaksanaan dan pelaporan: Melaksanakan peran masing-masing dan melaporkan progres melalui kanal dan format resmi.","Unit utama dan pendukung","Lembar Kesepakatan","Laporan progres","Sesuai tenggat"],["6","Penyelesaian hambatan: Bila ada keterlambatan atau tidak tercapai kesepakatan, memanggil unit terkait dan memutuskan unit utama serta tenggat baru.","Wakil Presiden","Laporan, tanggapan","Keputusan Wakil Presiden","2 hari kerja"],["7","Penutupan: Mengonfirmasi hasil diterima dan mencatat catatan perbaikan.","Pemrakarsa","Hasil kerja","Penutupan tercatat","2 hari kerja setelah hasil diterima"],["8","Pencatatan dan evaluasi: Merekap pada Register Koordinasi dan menjadikannya bahan evaluasi bulanan.","Sekjen","Lembar, laporan","Register, bahan evaluasi","Bulanan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari permintaan hingga kesepakatan paling lama 5 hari kerja. Hasil akhir: Lembar Kesepakatan Antarunit dan catatan penutupan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Wakil Presiden tidak dapat menyelesaikan: dibawa ke Rapat Pimpinan (SOP-GOV-005).","Hambatan bersifat konflik antarpengurus: SOP-GOV-010.","Dugaan kelalaian kementerian atau biro: berada dalam pengawasan BPH dan dipantau Irjen sesuai ART Pasal 13 ayat (3).","Koordinasi dengan ormawa lain: melalui Kementerian Harmonisasi Kampus dan, bila perlu, KAUR ORMAWA."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Permintaan ditanggapi dalam 2 hari kerja pada minimal 90% kasus.","Setiap koordinasi lintas unit memiliki unit utama dan tenggat tertulis.","Jumlah eskalasi ke Wakil Presiden menurun tiap bulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Permintaan Koordinasi.","Lembar Kesepakatan Antarunit.","Register Koordinasi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tata Kelola) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen mengecek kelengkapan lembar kesepakatan dan ketepatan penutupan setiap bulan; Irjen memakai rekap untuk bahan pengawasan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Identifikasi kebutuhan → Permintaan koordinasi → Tanggapan unit tujuan → Kesepakatan dan unit utama → Pelaksanaan dan laporan → Penutupan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Koordinasi","Unit peminta; unit tujuan; kebutuhan; tujuan; tanggal dibutuhkan; keputusan yang diperlukan."],["Lembar Kesepakatan Antarunit","Unit utama; unit pendukung; peran; hasil kerja; tenggat; tanda tangan pihak terkait."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Unit tujuan dan hasil yang diminta disebut jelas.","☐ Ya ☐ Tidak"],["2","Tembusan ke Sekjen dan Wakil Presiden terkirim.","☐ Ya ☐ Tidak"],["3","Unit utama dan tenggat disepakati tertulis.","☐ Ya ☐ Tidak"],["4","Penutupan dicatat pada register.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-GOV-005","g":"Tata Kelola dan Kepemimpinan","t":"Rapat Pimpinan","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[377,380],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan tata cara penyelenggaraan Rapat Pimpinan yang tertib, memiliki kuorum, menghasilkan keputusan yang tercatat, dan dapat ditindaklanjuti."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Rapat formal Presiden, Wakil Presiden, dan Sekretaris Jenderal. Rapat dengan seluruh Eksekutif diatur pada SOP-GOV-006."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 13 (pimpinan BEM) dan Pasal 14 (cara pengambilan keputusan).","ART Pasal 5 ayat (6) dan (8).","ART Pasal 10 (Rapat Koordinasi, sebagai acuan tata rapat; luring atau daring, notulensi resmi).","SOP-GOV-002 (Pengambilan Keputusan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rapat Pimpinan","Rapat formal tiga unsur pimpinan BEM untuk memutuskan hal strategis dan menyiapkan rapat kabinet."],["Notulen","Catatan resmi jalannya rapat dan keputusan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Peserta: Presiden, Wakil Presiden, dan Sekjen. Inspektur Jenderal, Menteri, atau Kabiro dapat diundang sesuai agenda tanpa hak suara.","Kuorum: minimal dua dari tiga unsur pimpinan dan wajib dihadiri Presiden atau Wakil Presiden (usulan).","Keputusan: mufakat; bila tidak tercapai, 50%+1 dari pimpinan yang hadir.","Rapat Pimpinan tidak dapat memutuskan hal yang menjadi kewenangan Mubes atau Musyawarah Istimewa, atau yang memerlukan persetujuan pihak luar sebelum berlaku.","Rapat dapat diadakan luring atau daring."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","R","Menyusun agenda, undangan, notulen, dan memantau tindak lanjut."],["Presiden / Wakil Presiden","A","Memimpin rapat dan mengesahkan hasil."],["Peserta undangan","C","Memberi masukan pada agenda terkait."],["Menteri / Kabiro","I","Menerima hasil yang relevan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Agenda dan bahan rapat.","Daftar tindak lanjut sebelumnya.","Laporan unit atau temuan Irjen bila relevan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan jadwal dan agenda: Menetapkan jadwal dan menyusun agenda berdasarkan isu prioritas serta tindak lanjut.","Sekjen","Daftar isu","Agenda rapat","H-2"],["2","Undangan dan bahan: Mengirim undangan dan bahan rapat kepada peserta melalui kanal resmi.","Sekjen","Agenda, bahan","Undangan terkirim","H-1"],["3","Pembukaan dan kuorum: Membuka dengan doa, memeriksa presensi dan kuorum.","Presiden atau Wakil Presiden","Daftar hadir","Rapat sah dibuka","Awal rapat"],["4","Pembahasan: Membahas agenda berurutan dengan pembatasan waktu per agenda.","Pimpinan rapat","Bahan rapat","Opsi dan pandangan","Sesuai agenda"],["5","Keputusan: Mengambil keputusan sesuai SOP- GOV-002 dan membacakan ulang ringkasan keputusan.","Pimpinan rapat","Opsi","Keputusan tercatat","Dalam rapat"],["6","Penyusunan notulen: Menyusun notulen berisi hadir, agenda, ringkasan pembahasan, keputusan, penanggung jawab, dan tenggat; ditandatangani Sekjen dan pimpinan rapat.","Sekjen / notulis","Catatan rapat","Notulen sah","1 hari kerja (draf); 2 hari kerja (sah)"],["7","Distribusi: Mengirim hasil relevan kepada Eksekutif; hasil bersifat rahasia dibatasi aksesnya.","Sekjen","Notulen sah","Distribusi tercatat","1 hari kerja setelah notulen sah"],["8","Pemantauan tindak lanjut: Memasukkan tindak lanjut ke daftar dan melaporkan statusnya pada rapat berikutnya.","Sekjen","Daftar tindak lanjut","Status tindak lanjut","Setiap rapat"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Notulen sah paling lambat 2 hari kerja setelah rapat. Hasil akhir: notulen bertanda tangan, daftar tindak lanjut, dan arsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kuorum tidak terpenuhi: rapat ditunda paling lama 1 hari kerja; bila mendesak gunakan SOP-GOV- 012.","Pimpinan tidak sepakat: SOP-GOV-002 dan SOP-GOV-010.","Hal di luar kewenangan: diajukan ke forum atau pejabat berwenang."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% rapat dimulai dengan kuorum.","Notulen sah dalam 2 hari kerja pada minimal 90% rapat.","Minimal 80% tindak lanjut tuntas tepat waktu."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Undangan dan daftar hadir.","Notulen bertanda tangan.","Daftar tindak lanjut.","Arsip digital. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tata Kelola) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen memeriksa kepatuhan jadwal, kuorum, dan ketepatan notulen; hasilnya dilaporkan pada evaluasi bulanan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Agenda dan jadwal → Undangan dan bahan → Pembukaan dan cek kuorum → Pembahasan → Keputusan → Notulen → Distribusi → Pantau tindak lanjut → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Undangan Rapat","Nomor; hal; hari, tanggal, waktu; tempat atau tautan; agenda; peserta."],["Templat Daftar Hadir","Nama; jabatan; hadir/izin/sakit; tanda tangan."],["Templat Notulen","Hadir; agenda; pembahasan; keputusan; penanggung jawab; tenggat; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Agenda dan bahan dikirim H-1.","☐ Ya ☐ Tidak"],["2","Kuorum tercatat.","☐ Ya ☐ Tidak"],["3","Keputusan dibacakan ulang sebelum rapat ditutup.","☐ Ya ☐ Tidak"],["4","Notulen sah dalam 2 hari kerja.","☐ Ya ☐ Tidak"],["5","Tindak lanjut masuk daftar.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-GOV-006","g":"Tata Kelola dan Kepemimpinan","t":"Rapat Kabinet","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[381,384],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan tata cara Rapat Kabinet (Rapat Kerja, Rapat Koordinasi, dan Rapat Evaluasi berkala) sebagai forum koordinasi, monitoring, dan evaluasi seluruh Eksekutif."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Rapat yang dihadiri BPH dan Eksekutif (Menteri dan Kabiro), termasuk Rapat Kerja awal periode. Rapat darurat diatur pada SOP-GOV-007; rapat pimpinan pada SOP-GOV-005."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 14 huruf c dan d (Rapat Koordinasi dan Rapat Evaluasi).","ART Pasal 9 (Rapat Kerja): dilaksanakan BPH dan Eksekutif pada awal periode; program kerja memerlukan persetujuan Pembina.","ART Pasal 10 (Rapat Koordinasi): peserta BPH dan Eksekutif; agenda; notulensi resmi; luring atau daring.","ART Pasal 13 ayat (6) (hasil pengawasan Irjen disampaikan melalui forum resmi BEM).","AD Pasal 9 ayat (2) huruf e (tidak mengikuti kegiatan organisasi 3 kali berturut-turut tanpa uzur)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rapat Kabinet","Sebutan operasional untuk rapat berkala BPH dan Eksekutif."],["Rapat Kerja (Raker)","Forum perencanaan program kerja tahunan pada awal periode."],["Rapat Evaluasi","Rapat untuk menilai capaian dan masalah berulang."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Peserta: BPH dan Eksekutif. Irjen hadir untuk menyampaikan hasil pengawasan.","Agenda tetap: koordinasi kegiatan mendatang, monitoring penggunaan anggaran, penyelesaian masalah internal (ART Pasal 10 ayat 4), laporan unit, laporan Irjen, dan tindak lanjut.","Kuorum: 50%+1 dari peserta berhak hadir (usulan). Keputusan mengikuti SOP-GOV-002.","Frekuensi: Rapat Kabinet minimal sekali sebulan dan sewaktu-waktu bila dibutuhkan (usulan).","Program kerja hasil Raker hanya dilaksanakan setelah mendapat persetujuan Pembina.","Menteri/Kabiro yang berhalangan wajib izin tertulis dan dapat mengutus wakil unit dengan mandat tertulis.","Hasil rapat dituangkan dalam notulensi resmi dan disosialisasikan kepada seluruh pengurus."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","R","Menjadwalkan, menyusun agenda dan undangan, mengelola notulen dan presensi."],["Presiden / Wakil Presiden","A","Memimpin rapat dan menetapkan keputusan."],["Menteri / Kabiro","R","Menyampaikan laporan unit dan menjalankan tindak lanjut."],["Inspektur Jenderal","R","Menyampaikan hasil pengawasan dan evaluasi."],["Biro Kesekretariatan","R","Menyusun notulensi resmi dan mengarsipkan."],["Seluruh pengurus","I","Menerima hasil rapat."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Kalender organisasi.","Laporan unit singkat.","Laporan pengawasan Irjen.","Daftar tindak lanjut rapat sebelumnya."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penjadwalan: Menetapkan jadwal pada kalender organisasi dan memberi tahu seluruh Eksekutif.","Sekjen","Kalender","Jadwal tetap","Minimal 5 hari kerja sebelum rapat"],["2","Laporan unit: Menyerahkan laporan singkat: capaian, kendala, kebutuhan keputusan, penggunaan anggaran.","Menteri / Kabiro","Format laporan progres","Laporan unit","H-2"],["3","Agenda dan undangan: Menyusun agenda, mengirim undangan beserta tautan bila daring.","Sekjen","Laporan unit, laporan Irjen","Undangan dan agenda","H-1"],["4","Pembukaan dan presensi: Membuka dengan doa, memeriksa kuorum, mencatat presensi (digunakan sebagai data SOP-SDM-006).","Pimpinan rapat","Daftar hadir","Rapat sah","Awal rapat"],["5","Pembahasan: Menyampaikan laporan, membahas koordinasi kegiatan, anggaran, dan masalah internal.","Menteri/Kabiro dan Irjen","Laporan","Isu dan opsi","Sesuai agenda"],["6","Keputusan: Mengambil keputusan sesuai SOP- GOV-002.","Pimpinan rapat","Opsi","Keputusan tercatat","Dalam rapat"],["7","Notulensi resmi: Menyusun dan menandatangani notulensi bersama Sekjen, kemudian menyosialisasikan kepada seluruh pengurus.","Biro Kesekretariatan","Catatan rapat","Notulensi resmi","2 hari kerja"],["8","Tindak lanjut: Memasukkan tindak lanjut ke daftar dan memantaunya.","Sekjen","Notulensi","Daftar tindak lanjut","Setiap rapat"],["9","Pengarsipan: Menyimpan notulensi, daftar hadir, dan bahan rapat di repositori resmi.","Biro Kesekretariatan","Dokumen rapat","Arsip","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Notulensi resmi disosialisasikan paling lambat 2 hari kerja setelah rapat. Hasil akhir: notulensi resmi, daftar tindak lanjut, dan arsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Ketidakhadiran 3 kali berturut-turut tanpa uzur: diproses melalui SOP-SDM-011 dan SOP-SDM-014 sesuai AD Pasal 9 ayat (2) huruf e.","Kuorum tidak terpenuhi: rapat ditunda; bila mendesak gunakan SOP-GOV-012.","Masalah mendesak yang mengancam organisasi: SOP-GOV-007.","Hasil Raker menyangkut program: diajukan kepada Pembina untuk persetujuan."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Tingkat kehadiran Eksekutif minimal 80% per rapat.","Notulensi tersosialisasi dalam 2 hari kerja.","Minimal 80% tindak lanjut selesai tepat waktu.","Laporan unit terkumpul sebelum H-1 minimal 90%."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Undangan, agenda, dan daftar hadir.","Notulensi resmi.","Daftar tindak lanjut.","Arsip digital. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tata Kelola) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Biro Kesekretariatan memeriksa kelengkapan dokumen rapat; Irjen menilai kepatuhan pada evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Jadwal → Laporan unit → Agenda dan undangan → Pembukaan dan presensi → Pembahasan → Keputusan → Notulensi dan sosialisasi → Tindak lanjut dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan Unit Rapat Kabinet","Unit; capaian; kendala; kebutuhan keputusan; penggunaan anggaran; rencana berikut."],["Templat Mandat Wakil Rapat","Nama unit; pemberi mandat; penerima; rapat; batas mandat."],["Templat Notulensi","Hadir; agenda; keputusan; penanggung jawab; tenggat."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Jadwal diumumkan minimal 5 hari kerja sebelum rapat.","☐ Ya ☐ Tidak"],["2","Seluruh laporan unit diterima H-2.","☐ Ya ☐ Tidak"],["3","Kuorum dan presensi tercatat.","☐ Ya ☐ Tidak"],["4","Notulensi tersosialisasi dalam 2 hari kerja.","☐ Ya ☐ Tidak"],["5","Tindak lanjut tercatat dan dipantau.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-GOV-007","g":"Tata Kelola dan Kepemimpinan","t":"Rapat Evaluasi Darurat","o":"Presiden","r":"00","st":"Draf (siap diuji coba).","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[385,388],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara menyelenggarakan rapat evaluasi secara cepat ketika terjadi kejadian atau temuan yang mengancam kegiatan, nama baik, keuangan, keselamatan, atau kelangsungan organisasi, sekaligus menegaskan batas dengan Musyawarah Istimewa."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Kejadian luar biasa di internal BEM dan kegiatannya, misalnya insiden kegiatan, dugaan penyalahgunaan dana atau aset, temuan berat Irjen, krisis reputasi, atau kebuntuan yang menghambat jalannya organisasi. Rapat ini bukan pengganti Musyawarah Istimewa."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 14 huruf d (Rapat Evaluasi).","ART Pasal 8 (Musyawarah Istimewa: kondisi darurat, agenda, paling lambat 14 hari, kuorum 50%+1, pengesahan Ketua STDIIS).","ART Pasal 12 ayat (3) sampai (7) (pengawasan Irjen dan pelaporan pelanggaran berat kepada KAUR ORMAWA).","ART Pasal 13 ayat (9) (hak klarifikasi dan pembelaan).","ART Pasal 11 (larangan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rapat Evaluasi Darurat","Rapat BPH dan pihak terkait untuk menilai kejadian dan memutuskan langkah cepat di dalam kewenangan kabinet."],["Status darurat","Penetapan bahwa suatu kejadian perlu ditangani di luar jadwal rapat reguler."],["Musyawarah Istimewa","Forum permusyawaratan menurut ART Pasal 8, dengan agenda dan kuorum yang diatur ART."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pemicu: kejadian yang perlu penanganan segera karena berisiko pada keselamatan, keuangan, reputasi, kepatuhan terhadap aturan, atau kelangsungan organisasi.","Yang dapat memicu: Presiden, Wakil Presiden, Sekjen, atau Irjen (untuk temuan berat).","Rapat Evaluasi Darurat hanya memutuskan langkah dalam kewenangan kabinet. Penggantian pengurus inti yang berhalangan tetap, perubahan mendesak AD/ART, pemberhentian pengurus yang melanggar ketentuan berat, dan masalah luar biasa yang mengancam stabilitas organisasi dibawa ke Musyawarah Istimewa (ART Pasal 8 ayat 3).","Pihak yang diduga terlibat diberi kesempatan klarifikasi sebelum keputusan yang merugikannya diambil.","Pelanggaran berat yang berdampak pada institusi dilaporkan kepada KAUR ORMAWA oleh Irjen."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pelapor / pemicu","R","Menyampaikan laporan kejadian awal dengan bukti yang ada."],["Sekretaris Jenderal","R","Memverifikasi awal, menyiapkan rapat, mencatat."],["Inspektur Jenderal","R","Menelaah fakta dan kesesuaian aturan; melaporkan pelanggaran berat kepada KAUR ORMAWA."],["Presiden","A","Menetapkan status darurat dan keputusan akhir."],["Wakil Presiden","R","Mengoordinasikan unit terkait dalam pelaksanaan keputusan."],["Pihak terkait","C","Memberi klarifikasi dan keterangan."],["Pembina / KAUR ORMAWA","I","Diberi tahu bila menyangkut institusi atau pelanggaran berat."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan kejadian.","Bukti pendukung (dokumen, foto, tangkapan layar, saksi).","Data kegiatan atau keuangan terkait."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pelaporan: Menyampaikan Laporan Kejadian kepada Sekjen atau Presiden melalui kanal resmi.","Pelapor","Informasi dan bukti awal","Laporan tercatat","Segera, maksimal 6 jam setelah diketahui"],["2","Verifikasi cepat: Memeriksa kebenaran awal, dampak, dan klasifikasi: ringan, sedang, atau berat.","Sekjen dan Irjen","Laporan, bukti","Hasil verifikasi","Maks. 12 jam"],["3","Penetapan status darurat: Menetapkan perlu atau tidaknya rapat darurat dan menentukan peserta.","Presiden (atau Wakil Presiden bila Presiden berhalangan)","Hasil verifikasi","Keputusan status darurat","Maks. 12 jam setelah verifikasi"],["4","Undangan darurat: Mengirim undangan melalui kanal cepat; rapat dapat luring atau daring.","Sekjen","Penetapan status","Undangan terkirim","Segera"],["5","Rapat evaluasi: Memaparkan fakta, mendengar klarifikasi pihak terkait, menimbang opsi, dan mengambil keputusan sesuai SOP-GOV-002.","Presiden memimpin","Laporan, klarifikasi","Keputusan langkah penanganan","Maks. 24 jam setelah penetapan"],["6","Penetapan langkah: Menetapkan penanggung jawab, tindakan, dan tenggat; membuat pernyataan atau sanksi sesuai kewenangan.","Presiden","Keputusan rapat","Rencana tindakan","Dalam rapat"],["7","Eskalasi bila diperlukan: Mengajukan usulan resmi Musyawarah Istimewa, melapor kepada KAUR ORMAWA/Pembina, atau melibatkan pihak berwenang lain.","Presiden dan Irjen","Keputusan rapat","Surat usulan atau laporan","Musyawarah Istimewa paling lambat 14 hari setelah usulan resmi"],["8","Pemantauan dan penutupan: Memantau pelaksanaan, menutup kasus bila selesai, dan menyampaikan hasil pada forum resmi BEM.","Sekjen dan Irjen","Laporan pelaksanaan","Penutupan tercatat","Sesuai rencana tindakan"],["9","Evaluasi pembelajaran: Mencatat penyebab, tindakan, dan perbaikan pencegahan pada catatan insiden.","Sekjen","Dokumen kasus","Catatan insiden","7 hari kerja setelah penutupan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Rapat dimulai paling lambat 24 jam sejak status darurat ditetapkan (usulan). Hasil akhir: Keputusan Rapat Evaluasi Darurat, rencana tindakan, dan catatan insiden."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kejadian menyangkut keselamatan jiwa: dahulukan penanganan darurat (SOP-PRO-017 atau SOP- RSK-003), rapat menyusul.","Dugaan penyalahgunaan dana: SOP-RSK-007; dugaan perundungan atau pelecehan: SOP-RSK-005.","Presiden dan Wakil Presiden terlibat dalam kejadian: pemimpin rapat diganti oleh Sekjen dan Irjen melapor kepada KAUR ORMAWA.","Keputusan yang butuh persetujuan pihak luar belum berlaku sebelum persetujuan diperoleh."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Rapat darurat dimulai dalam 24 jam pada minimal 90% kasus.","100% kasus memiliki penanggung jawab dan tenggat.","Eskalasi ke Musyawarah Istimewa dilakukan sesuai batas ART.","Kejadian berulang pada penyebab yang sama menurun."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan Kejadian.","Keputusan Rapat Evaluasi Darurat dan notulen.","Rencana tindakan.","Catatan insiden pada register. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tata Kelola) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa seluruh kasus darurat setiap bulan dan melaporkan pola kejadian pada Rapat Kabinet."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Laporan kejadian → Verifikasi cepat → Penetapan status darurat → Rapat evaluasi → Keputusan dan rencana tindakan → Perlu Musyawarah Istimewa? Ajukan usulan resmi → Pemantauan dan penutupan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan Kejadian","Pelapor; waktu; tempat; kronologi; pihak terkait; bukti; dampak awal."],["Keputusan Rapat Evaluasi Darurat","Kasus; klasifikasi; peserta; keputusan; penanggung jawab; tenggat; eskalasi."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Laporan dan bukti awal tercatat.","☐ Ya ☐ Tidak"],["2","Klasifikasi dan dasar status darurat jelas.","☐ Ya ☐ Tidak"],["3","Pihak terkait diberi kesempatan klarifikasi.","☐ Ya ☐ Tidak"],["4","Batas dengan Musyawarah Istimewa dijaga.","☐ Ya ☐ Tidak"],["5","Catatan insiden dan perbaikan pencegahan dibuat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-GOV-008","g":"Tata Kelola dan Kepemimpinan","t":"Pendelegasian Wewenang","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[389,392],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan tata cara pemberian wewenang secara tertulis, terbatas, dan terkendali dari pejabat kepada pengurus lain agar pekerjaan tetap berjalan tanpa melanggar AD/ART."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Pelimpahan wewenang oleh Presiden, Wakil Presiden, Sekjen, Menteri, dan Kabiro kepada pengurus BEM, baik untuk tugas tertentu maupun jangka waktu tertentu. Mandat kepada delegasi eksternal mengikuti SOP- HKE-011; pengganti saat pimpinan tidak hadir mengikuti SOP-GOV-009."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf e dan f (mewakili mahasiswa dan menandatangani surat serta dokumen organisasi).","ART Pasal 4 huruf b (pengangkatan dan pemberhentian pengurus internal).","ART Pasal 3 (Hak) huruf e: kerja sama dengan pihak eksternal memerlukan persetujuan Ketua STDIIS.","AD Pasal 11 ayat (2) huruf b (prerogatif Presiden dalam pengangkatan Menteri/Kabiro)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Delegasi","Pelimpahan sebagian wewenang oleh pemberi kepada penerima."],["Pemberi delegasi","Pejabat yang memiliki wewenang asli."],["Penerima delegasi","Pengurus yang diberi wewenang terbatas."],["Surat Mandat","Dokumen tertulis yang memuat ruang lingkup, batas, dan jangka waktu delegasi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Delegasi harus tertulis, menyebut ruang lingkup, batas, jangka waktu, dan kewajiban melapor.","Tanggung jawab akhir tetap pada pemberi delegasi.","Penerima tidak boleh mendelegasikan kembali tanpa izin tertulis pemberi.","Wewenang berikut tidak dapat didelegasikan (usulan): pengangkatan atau pemberhentian pengurus, penetapan sanksi pemberhentian tetap, penandatanganan perjanjian kerja sama, pengesahan keputusan forum, dan pernyataan resmi atas isu strategis atas nama BEM.","Delegasi berakhir otomatis pada tanggal berakhir, saat tugas selesai, atau saat dicabut."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pemberi delegasi","A","Menentukan, menandatangani, dan bertanggung jawab atas delegasi."],["Penerima delegasi","R","Melaksanakan dalam batas mandat dan melaporkan hasilnya."],["Sekretaris Jenderal","R","Memeriksa larangan delegasi, menyusun Surat Mandat, mencatat register."],["Biro Kesekretariatan","R","Menomori dan mengarsipkan Surat Mandat."],["Inspektur Jenderal","C","Meninjau kepatuhan delegasi pada pengawasan berkala."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Permohonan atau kebutuhan delegasi.","Daftar wewenang yang tidak dapat didelegasikan.","Matriks kewenangan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Identifikasi kebutuhan: Menentukan tugas yang akan didelegasikan, calon penerima, dan alasan.","Pemberi delegasi","Kebutuhan kerja","Rencana delegasi","Sesuai kebutuhan"],["2","Pemeriksaan batas: Memeriksa apakah tugas termasuk wewenang yang tidak dapat didelegasikan dan apakah penerima memenuhi syarat.","Sekjen","Rencana, daftar larangan","Hasil pemeriksaan","1 hari kerja"],["3","Penyusunan Surat Mandat: Menyusun Surat Mandat: pemberi, penerima, ruang lingkup, batas, jangka waktu, kewajiban lapor.","Sekjen / Biro Kesekretariatan","Hasil pemeriksaan","Draf Surat Mandat","1 hari kerja"],["4","Persetujuan: Menandatangani Surat Mandat.","Pemberi delegasi","Draf","Surat Mandat sah","1 hari kerja"],["5","Penerimaan: Membaca, menyatakan menerima, dan menandatangani tanda terima.","Penerima delegasi","Surat Mandat","Penerimaan tercatat","1 hari kerja"],["6","Pelaksanaan dan pelaporan: Melaksanakan dalam batas mandat dan melaporkan hasil kepada pemberi.","Penerima delegasi","Surat Mandat","Laporan pelaksanaan","Maks. 2 hari kerja setelah tugas selesai"],["7","Pencabutan atau berakhirnya: Mencabut bila perlu atau menyatakan selesai.","Pemberi delegasi","Laporan","Pencabutan atau penutupan tercatat","Segera"],["8","Pencatatan: Mencatat pada Register Delegasi dan mengarsipkan Surat Mandat.","Sekjen","Surat Mandat, laporan","Register, arsip","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Delegasi biasa diterbitkan paling lambat 3 hari kerja sejak permintaan; delegasi mendesak mengikuti SOP- GOV-012. Hasil akhir: Surat Mandat sah, laporan pelaksanaan, dan entri register."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Penerima bertindak di luar mandat: mandat dicabut seketika dan ditinjau melalui mekanisme sanksi (ART Pasal 12 dan 13).","Pemberi tidak dapat dihubungi dan delegasi mendesak: SOP-GOV-009 atau SOP-GOV-012.","Ragu apakah wewenang boleh didelegasikan: diputuskan Presiden setelah masukan Irjen."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% delegasi memiliki Surat Mandat tertulis.","Tidak ada tindakan di luar mandat.","Laporan pelaksanaan masuk dalam 2 hari kerja pada minimal 90% delegasi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Surat Mandat.","Laporan pelaksanaan delegasi.","Register Delegasi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tata Kelola) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen memeriksa register setiap bulan; Irjen mengambil sampel delegasi untuk diperiksa kepatuhannya."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Identifikasi kebutuhan → Periksa batas delegasi → Susun Surat Mandat → Persetujuan pemberi → Penerimaan → Pelaksanaan dan laporan → Pencabutan atau selesai → Arsip"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Surat Mandat","Pemberi; penerima; tugas; batas wewenang; jangka waktu; kewajiban lapor; tanda tangan pemberi dan penerima."],["Register Delegasi","Nomor mandat; pemberi; penerima; tugas; periode; status."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Tugas tidak termasuk wewenang yang tidak dapat didelegasikan.","☐ Ya ☐ Tidak"],["2","Ruang lingkup, batas, dan jangka waktu tertulis.","☐ Ya ☐ Tidak"],["3","Penerima menyatakan menerima.","☐ Ya ☐ Tidak"],["4","Laporan pelaksanaan diterima.","☐ Ya ☐ Tidak"],["5","Register diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-GOV-009","g":"Tata Kelola dan Kepemimpinan","t":"Ketidakhadiran Pimpinan dan Pengganti Sementara","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[393,396],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan siapa yang menjalankan tugas pimpinan ketika Presiden, Wakil Presiden, atau Sekretaris Jenderal berhalangan sementara, batas wewenangnya, dan alur bila halangan menjadi tetap."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Ketidakhadiran sementara karena sakit, izin, kegiatan akademik, atau kegiatan lain. Halangan tetap hanya diatur sejauh langkah awal; mekanisme lanjutan mengikuti AD/ART."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 13 (pimpinan BEM).","ART Pasal 5 ayat (7) (Presiden dan Wakil Presiden berhenti karena masa jabatan berakhir, mengundurkan diri, diberhentikan melalui forum, atau tidak lagi mahasiswa aktif).","ART Pasal 5 ayat (8) (Wakil Presiden menggantikan Presiden berdasarkan kesepakatan musyawarah internal).","ART Pasal 8 (Musyawarah Istimewa, termasuk penggantian pengurus inti yang berhalangan tetap).","AD Pasal 9 ayat (1) (alasan berhenti)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Berhalangan sementara","Tidak dapat menjalankan tugas untuk jangka waktu terbatas dan akan kembali."],["Berhalangan tetap","Berhenti karena sebab seperti yang diatur ART Pasal 5 ayat (7)."],["Pelaksana Harian (Plh)","Pimpinan yang ditunjuk menjalankan tugas rutin selama pimpinan berhalangan sementara."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Ketidakhadiran 3 hari kerja atau kurang: pelimpahan tugas rutin tanpa penunjukan Plh formal.","Ketidakhadiran lebih dari 3 hari kerja (usulan): wajib ditunjuk Plh melalui Surat Mandat (SOP-GOV- 008).","Urutan Plh: Presiden digantikan Wakil Presiden, lalu Sekjen. Wakil Presiden digantikan Sekjen atau pengurus yang ditunjuk Presiden. Sekjen digantikan Sekjen lainnya atau staf yang ditunjuk Presiden.","Plh tidak boleh: mengangkat atau memberhentikan pengurus, mengubah kebijakan strategis, menandatangani perjanjian kerja sama baru, menjatuhkan sanksi berat, atau mengubah struktur, kecuali mendesak dan dengan persetujuan tertulis Presiden (termasuk melalui kanal resmi).","Halangan tetap: Wakil Presiden menggantikan Presiden melalui musyawarah internal; karena ART Pasal 8 ayat (3) huruf a juga menyebut penggantian pengurus inti dalam Musyawarah Istimewa, hasil musyawarah internal diratifikasi melalui Musyawarah Istimewa sesuai ketentuan ART dan dikonfirmasi kepada KAUR ORMAWA/Ketua STDIIS karena Presiden dilantik oleh Ketua STDIIS (ART Pasal 5 ayat 3)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pimpinan yang berhalangan","R","Memberi tahu, menyerahkan tugas, dan melapor saat kembali."],["Presiden","A","Menunjuk Plh dan menyetujui tindakan Plh yang melampaui batas."],["Plh","R","Menjalankan tugas rutin sesuai batas Surat Mandat."],["Sekretaris Jenderal","R","Memverifikasi, menerbitkan Surat Mandat, memberitahu Eksekutif, dan mencatat."],["Inspektur Jenderal","C","Memeriksa kepatuhan batas wewenang Plh."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Pemberitahuan ketidakhadiran.","Kalender agenda kritis.","Daftar tugas tertunda."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pemberitahuan: Memberi tahu Sekjen dan Presiden secara tertulis: alasan, rentang waktu, dan agenda kritis.","Pimpinan yang berhalangan","Rencana ketidakhadiran","Pemberitahuan tercatat","H-1 (terencana); segera (mendadak)"],["2","Verifikasi dan klasifikasi: Memeriksa durasi, menggolongkan sementara atau tetap, dan mengidentifikasi agenda yang tidak boleh tertunda.","Sekjen","Pemberitahuan, kalender","Klasifikasi","1 hari kerja"],["3","Penunjukan Plh: Menunjuk Plh sesuai urutan. Bila Presiden tidak dapat dihubungi, berlaku urutan otomatis.","Presiden","Klasifikasi","Keputusan penunjukan","1 hari kerja"],["4","Surat Mandat: Menerbitkan Surat Mandat Plh yang memuat batas wewenang (SOP-GOV- 008).","Sekjen","Penunjukan","Surat Mandat","1 hari kerja"],["5","Pengumuman: Memberi tahu Eksekutif melalui kanal resmi.","Sekjen","Surat Mandat","Pengumuman","Pada hari penunjukan"],["6","Serah terima tugas: Menyerahkan daftar tugas tertunda, kontak penting, dan akses yang perlu.","Pimpinan yang berhalangan dan Plh","Daftar tugas","Catatan serah terima","Sebelum ketidakhadiran"],["7","Pelaksanaan dan pelaporan: Menjalankan tugas dalam batas mandat dan melaporkan hal penting.","Plh","Surat Mandat","Laporan Plh","Mingguan atau saat ada keputusan penting"],["8","Pengembalian wewenang: Menyerahkan kembali tugas dan melaporkan hasil; Sekjen mencabut Surat Mandat.","Plh dan pimpinan","Laporan","Pengembalian tercatat","1 hari kerja setelah kembali"],["9","Alih ke halangan tetap: Bila halangan menjadi tetap: musyawarah internal segera, lalu usulan Musyawarah Istimewa dan pemberitahuan kepada KAUR ORMAWA/Ketua STDIIS.","Presiden/Wakil Presiden dan Sekjen","Pemberitahuan resmi","Penggantian diproses sesuai ART","Musyawarah internal maks. 3 hari kerja; Musyawarah Istimewa maks. 14 hari setelah usulan resmi"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Plh ditetapkan paling lambat 1 hari kerja setelah halangan lebih dari 3 hari kerja diketahui. Hasil akhir: Surat Mandat Plh, catatan serah terima, dan laporan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Seluruh unsur pimpinan berhalangan: Irjen memanggil Menteri/Kabiro untuk menetapkan koordinator sementara dan melapor kepada KAUR ORMAWA.","Halangan tetap: SOP-SDM-014 dan SOP-SDM-015, serta Musyawarah Istimewa sesuai ART Pasal 8.","Plh melampaui batas: tindakan ditinjau dan dapat dicabut oleh Presiden; Irjen menilai."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% ketidakhadiran lebih dari 3 hari kerja memiliki Plh tertulis.","Tidak ada keputusan terlarang oleh Plh.","Pengembalian wewenang dicatat paling lambat 1 hari kerja setelah kembali."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Pemberitahuan ketidakhadiran.","Surat Mandat Plh.","Catatan serah terima dan laporan Plh. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tata Kelola) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen memeriksa register ketidakhadiran dan mandat setiap bulan; Irjen memeriksa kepatuhan batas wewenang."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pemberitahuan → Klasifikasi → Penunjukan Plh → Surat Mandat dan pengumuman → Pelaksanaan terbatas → Pengembalian wewenang → Selesai atau alih ke halangan tetap"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pemberitahuan Ketidakhadiran","Nama; jabatan; alasan; mulai dan selesai; agenda kritis; usulan pengganti."],["Templat Surat Mandat Plh","Pemberi; Plh; periode; wewenang yang dilimpahkan; wewenang yang dilarang."],["Catatan Serah Terima Tugas","Tugas tertunda; kontak; akses; tenggat."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Durasi dan klasifikasi ditentukan.","☐ Ya ☐ Tidak"],["2","Plh ditunjuk sesuai urutan dan tertulis.","☐ Ya ☐ Tidak"],["3","Batas wewenang Plh tercantum.","☐ Ya ☐ Tidak"],["4","Eksekutif diberi tahu.","☐ Ya ☐ Tidak"],["5","Pengembalian wewenang dicatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-GOV-010","g":"Tata Kelola dan Kepemimpinan","t":"Penyelesaian Konflik Internal","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[397,400],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara menyelesaikan konflik antarpengurus secara adil dan beradab, dengan prinsip tabayyun, musyawarah, dan ukhuwah, sebelum konflik merusak kerja organisasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Konflik antarpengurus atau antarunit yang tidak berupa dugaan pelanggaran. Dugaan pelanggaran etik atau disiplin diproses melalui SOP-SDM-013, dugaan perundungan atau pelecehan melalui SOP-RSK-005, dan dugaan penyalahgunaan dana melalui SOP-RSK-007."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 5 (fungsi mempererat ukhuwah Islamiah dan melatih tanggung jawab).","ART Pasal 3 (Kewajiban) huruf b (menjaga persatuan dan ukhuwah Islamiyah).","ART Pasal 11 (larangan) dan Pasal 12 (sanksi dan kewenangan).","ART Pasal 13 (mekanisme pemberian sanksi, prinsip keadilan, objektivitas, bukti, dan hak klarifikasi serta pembelaan).","ART Pasal 8 ayat (3) huruf d (masalah luar biasa yang mengancam stabilitas organisasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Konflik internal","Perbedaan kepentingan, pendapat, atau kewenangan antarpengurus yang mengganggu pekerjaan."],["Tabayyun","Klarifikasi dan pemeriksaan kebenaran informasi dari masing-masing pihak."],["Fasilitator","Pihak netral yang memimpin mediasi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Prinsip: tabayyun, keadilan, objektivitas, kerahasiaan, dan penyelesaian secepat yang wajar.","Fasilitator tidak boleh pihak yang berkonflik atau memiliki konflik kepentingan.","Setiap pihak berhak memberi klarifikasi dan pembelaan.","Konflik yang melibatkan Presiden atau Wakil Presiden dikoordinasikan Irjen dan dapat dilaporkan kepada KAUR ORMAWA/Pembina.","Kesepakatan dituangkan tertulis dan menjadi dasar pemantauan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pihak berkonflik","R","Menyampaikan keterangan jujur dan menaati kesepakatan."],["Wakil Presiden","A","Menunjuk fasilitator dan memastikan proses berjalan."],["Fasilitator (Wapres, Sekjen, Irjen, atau Menteri PSDM)","R","Memimpin tabayyun dan mediasi."],["Sekretaris Jenderal","R","Mencatat laporan, Berita Acara Mediasi, dan arsip rahasia."],["Presiden / BPH","A","Memutus bila mediasi gagal dan menetapkan sanksi dalam kewenangan."],["Inspektur Jenderal","C","Memantau kepatuhan dan menilai bila konflik berasal dari pelanggaran."],["KAUR ORMAWA / Pembina","I","Diberi tahu bila melibatkan pimpinan atau berdampak pada institusi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan konflik.","Keterangan para pihak.","Bukti yang relevan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pelaporan: Melaporkan konflik kepada Wakil Presiden atau Sekjen melalui kanal tertutup.","Pihak berkonflik atau pihak ketiga","Laporan","Laporan tercatat","Segera"],["2","Penerimaan dan klasifikasi: Mencatat, menentukan jenis: kewenangan, komunikasi, atau pribadi; merujuk ke SOP lain bila ada indikasi pelanggaran; memeriksa konflik kepentingan.","Sekjen dan Wakil Presiden","Laporan","Klasifikasi dan rujukan","1 hari kerja"],["3","Tabayyun: Meminta klarifikasi terpisah dari masing-masing pihak dan memeriksa bukti.","Fasilitator","Keterangan, bukti","Catatan tabayyun","3 hari kerja"],["4","Mediasi: Mempertemukan para pihak, mencari titik temu, dan merumuskan kesepakatan.","Fasilitator","Catatan tabayyun","Rumusan kesepakatan","Mulai maks. 5 hari kerja sejak laporan"],["5","Kesepakatan tertulis: Menyusun Berita Acara Mediasi yang ditandatangani para pihak dan fasilitator.","Sekjen dan para pihak","Rumusan kesepakatan","Berita Acara Mediasi","1 hari kerja setelah mediasi"],["6","Penetapan bila mediasi gagal: Memutus dalam rapat tertutup dengan memberi kesempatan pembelaan; sanksi bila ada mengikuti ART Pasal 12 dan 13.","Presiden dan BPH","Seluruh catatan","Keputusan penyelesaian","3 hari kerja"],["7","Eskalasi bila perlu: Melaporkan kepada KAUR ORMAWA/Pembina bila melibatkan pimpinan atau berdampak institusi; mengusulkan Musyawarah Istimewa bila mengancam stabilitas organisasi.","Presiden dan Irjen","Keputusan","Laporan atau usulan","Maks. 14 hari untuk Musyawarah Istimewa setelah usulan resmi"],["8","Pemantauan: Memeriksa pelaksanaan kesepakatan setelah 14 hari.","Wakil Presiden dan Irjen","Berita Acara","Laporan pemantauan","14 hari setelah kesepakatan"],["9","Penutupan dan arsip: Menutup kasus dan menyimpan arsip bersifat terbatas.","Sekjen","Dokumen kasus","Arsip tertutup","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Mediasi dimulai paling lambat 5 hari kerja sejak laporan diterima dan ditargetkan selesai dalam 14 hari kerja (usulan). Hasil akhir: Berita Acara Mediasi atau keputusan penyelesaian."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Mediasi gagal: Presiden dan BPH memutus.","Konflik melibatkan pimpinan: Irjen mengoordinasikan dan, bila perlu, melapor kepada KAUR ORMAWA/Pembina.","Indikasi pelanggaran: dialihkan ke SOP-SDM-013, SOP-RSK-005, atau SOP-RSK-007.","Konflik mengancam stabilitas organisasi: usulan Musyawarah Istimewa (ART Pasal 8)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 80% konflik selesai melalui mediasi.","Mediasi dimulai paling lambat 5 hari kerja pada minimal 90% kasus.","Kesepakatan dipatuhi pada pemantauan 14 hari."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Catatan tabayyun.","Berita Acara Mediasi atau keputusan penyelesaian.","Laporan pemantauan.","Arsip kasus bersifat terbatas. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tata Kelola) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen memeriksa seluruh kasus setiap bulan tanpa membuka identitas yang tidak perlu dan melaporkan pola konflik pada Rapat Kabinet secara umum."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pelaporan → Klasifikasi dan cek kepentingan → Tabayyun → Mediasi → Berhasil? Berita Acara → Gagal? Penetapan Presiden dan BPH → Eskalasi bila perlu → Pemantauan 14 hari → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan Konflik","Pelapor; pihak berkonflik; ringkasan; waktu; bukti; harapan penyelesaian."],["Berita Acara Mediasi","Pihak; fasilitator; ringkasan; kesepakatan; tenggat pelaksanaan; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Fasilitator bebas konflik kepentingan.","☐ Ya ☐ Tidak"],["2","Kedua pihak diberi kesempatan klarifikasi.","☐ Ya ☐ Tidak"],["3","Kesepakatan tertulis dan ditandatangani.","☐ Ya ☐ Tidak"],["4","Pemantauan 14 hari dilakukan.","☐ Ya ☐ Tidak"],["5","Arsip dijaga kerahasiaannya.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-GOV-011","g":"Tata Kelola dan Kepemimpinan","t":"Perubahan Kebijakan Internal","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[401,404],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara mengusulkan, menelaah, memutuskan, memberlakukan, dan mensosialisasikan perubahan kebijakan internal (SOP, pedoman, keputusan Presiden) dengan menjaga keselarasan terhadap AD/ART."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Perubahan SOP, pedoman, formulir baku, dan keputusan Presiden BEM. Perubahan AD dan ART tidak diatur di sini; keduanya mengikuti AD Bab XI dan ART Bab VII."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf a (kebijakan pelaksanaan kegiatan).","AD Pasal 20 (perubahan AD oleh unsur BEM, BPM, HIMA, dan UKM; disetujui 50%+1 dan pihak kampus).","ART Pasal 14 (perubahan ART diusulkan Eksekutif, dibahas di Mubes atau Musyawarah Istimewa, disetujui 2/3 peserta dan KAUR ORMAWA).","AD Pasal 21 ayat (2) dan ART Pasal 15 ayat (2) (ketentuan lama berlaku selama tidak bertentangan dengan AD/ART)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kebijakan internal","Aturan di bawah AD/ART yang dibuat pimpinan atau kabinet, seperti SOP dan Keputusan Presiden."],["Revisi","Perubahan resmi pada isi dokumen yang dicatat dengan nomor revisi baru."],["Perubahan minor","Perbaikan redaksi, kontak, atau lampiran tanpa mengubah substansi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kebijakan internal tidak boleh bertentangan dengan AD/ART atau peraturan kampus.","Bila usulan menyentuh isi AD/ART, usulan dialihkan ke prosedur perubahan AD/ART dan tidak diproses sebagai kebijakan internal.","Perubahan minor disetujui Sekjen dan Wakil Presiden lalu disahkan Presiden; perubahan substansial dibahas pada rapat kabinet.","Setiap revisi memuat nomor revisi, tanggal berlaku, alasan, dan status versi lama (diganti, dicabut, atau diarsipkan)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pengusul (Presiden, BPH, Menteri/Kabiro, Irjen)","R","Menyampaikan usulan beserta alasan dan draf perubahan."],["Sekretaris Jenderal","R","Mencatat, mengklasifikasi, mengelola draf, nomor revisi, dan register."],["Inspektur Jenderal","C","Menelaah keselarasan dengan AD/ART dan aturan kampus."],["Unit terdampak","C","Memberi masukan pelaksanaan."],["Rapat kabinet","R","Membahas perubahan substansial."],["Presiden","A","Mengesahkan perubahan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Usulan Perubahan.","Dokumen yang akan diubah.","Temuan evaluasi atau masukan unit."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Usulan: Mengisi Formulir Usulan Perubahan: alasan, ketentuan terdampak, usulan redaksi, dampak, dan kesesuaian dengan AD/ART.","Pengusul","Temuan atau kebutuhan","Usulan tertulis","Kapan saja"],["2","Pencatatan dan klasifikasi: Mencatat usulan, menggolongkan minor atau substansial, dan memeriksa apakah menyentuh AD/ART.","Sekjen","Usulan","Klasifikasi","2 hari kerja"],["3","Telaah: Menelaah keselarasan aturan dan dampak operasional; memberi catatan tertulis.","Irjen dan unit terdampak","Usulan, aturan","Catatan telaah","3 hari kerja"],["4","Pembahasan: Membahas dan memutuskan sesuai SOP-GOV-002.","Rapat kabinet atau Sekjen dan Wakil Presiden (minor)","Usulan, catatan telaah","Keputusan perubahan","Pada rapat terdekat"],["5","Uji coba bila perlu: Menguji ketentuan baru pada proses nyata sebelum diberlakukan penuh.","Unit terdampak","Draf revisi","Hasil uji coba","Maks. 1 bulan"],["6","Pengesahan: Menandatangani revisi, mencantumkan nomor revisi dan tanggal berlaku.","Presiden","Draf final","Dokumen revisi sah","2 hari kerja"],["7","Pemberlakuan dan versi lama: Memperbarui Register Dokumen; menandai versi lama diganti, dicabut, atau diarsipkan; menyimpan di repositori.","Sekjen","Dokumen sah","Register terbarui","2 hari kerja"],["8","Sosialisasi: Menyampaikan perubahan kepada pengurus terkait melalui kanal resmi dan menetapkan masa transisi bila perlu.","Sekjen","Dokumen sah","Sosialisasi tercatat","3 hari kerja setelah pengesahan"],["9","Evaluasi: Menilai efektivitas perubahan setelah satu bulan.","Sekjen dan Irjen","Laporan unit","Catatan evaluasi","1 bulan setelah berlaku"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Perubahan minor selesai paling lambat 5 hari kerja; perubahan substansial paling lambat 20 hari kerja (usulan). Hasil akhir: dokumen revisi sah, register diperbarui, dan sosialisasi tercatat."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Usulan menyentuh AD/ART: dialihkan ke prosedur AD Bab XI atau ART Bab VII.","Telaah Irjen menyatakan bertentangan dengan AD/ART atau aturan kampus: usulan ditolak atau direvisi.","Perbedaan pendapat dalam pembahasan: SOP-GOV-002.","Perubahan yang berdampak pada program kerja: diajukan kepada Pembina bila diperlukan."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% revisi memiliki nomor revisi, tanggal berlaku, dan alasan.","Tidak ada kebijakan internal yang bertentangan dengan AD/ART.","Sosialisasi dalam 3 hari kerja setelah pengesahan.","Register Dokumen selalu menunjukkan versi terbaru."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Usulan Perubahan.","Catatan telaah Irjen.","Dokumen revisi bertanda tangan.","Register Dokumen yang diperbarui. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tata Kelola) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen mengecek register dokumen setiap bulan; Irjen mengambil sampel revisi untuk dinilai kepatuhannya."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Usulan perubahan → Klasifikasi: minor, substansial, atau AD/ART → Telaah Irjen dan unit → Pembahasan dan keputusan → Pengesahan Presiden → Perbarui register dan versi lama → Sosialisasi → Evaluasi 1 bulan"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Usulan Perubahan Kebijakan","Pengusul; dokumen; ketentuan terdampak; alasan; usulan redaksi; dampak; kesesuaian AD/ART."],["Riwayat Perubahan Dokumen","Revisi; tanggal; ringkasan perubahan; alasan; pengesah."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Usulan tidak menyentuh isi AD/ART.","☐ Ya ☐ Tidak"],["2","Catatan telaah Irjen tersedia.","☐ Ya ☐ Tidak"],["3","Nomor revisi, tanggal berlaku, dan alasan dicantumkan.","☐ Ya ☐ Tidak"],["4","Versi lama ditandai statusnya.","☐ Ya ☐ Tidak"],["5","Perubahan disosialisasikan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-GOV-012","g":"Tata Kelola dan Kepemimpinan","t":"Pengambilan Keputusan Mendesak dan Pencatatannya","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[405,408],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara mengambil keputusan yang tidak dapat menunggu rapat reguler secara cepat namun tetap terkendali, tercatat, diratifikasi, dan dapat diperiksa."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Keputusan operasional kabinet yang mendesak karena keselamatan, tenggat eksternal, atau kerugian yang jelas jika ditunda. SOP ini tidak berlaku untuk keputusan yang menurut AD/ART harus diputuskan Mubes atau Musyawarah Istimewa."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf a (kebijakan pelaksanaan kegiatan) dan huruf f (penandatanganan dokumen).","ART Pasal 8 (batas Musyawarah Istimewa).","SOP-GOV-002 (Pengambilan Keputusan) dan SOP-GOV-008 (Pendelegasian)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Keputusan mendesak","Keputusan yang harus diambil sebelum rapat reguler dapat digelar karena risiko nyata bila ditunda."],["Ratifikasi","Pengesahan atau koreksi keputusan mendesak oleh rapat yang berwenang setelah keputusan dijalankan."],["Lembar Keputusan Mendesak","Formulir pencatatan keputusan mendesak."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kriteria mendesak (harus terpenuhi): (a) waktu tidak memungkinkan rapat reguler, (b) ada risiko nyata pada keselamatan, keuangan, reputasi, atau tenggat eksternal, (c) langkah yang diambil terbatas dan sebisa mungkin dapat dibatalkan, (d) tidak termasuk keputusan yang dilarang.","Pengambil keputusan: Presiden, atau Plh sesuai SOP-GOV-009; keputusan dikonsultasikan minimal kepada satu unsur pimpinan lain.","Keputusan mendesak tidak boleh: mengangkat atau memberhentikan pengurus, menetapkan sanksi pemberhentian tetap, menandatangani perjanjian kerja sama, mengubah AD/ART, atau mengeluarkan dana di atas batas yang ditetapkan SOP keuangan tanpa konsultasi Biro Keuangan.","Setiap keputusan mendesak wajib diratifikasi pada rapat terdekat.","Penggunaan keputusan mendesak yang sering (misalnya lebih dari 3 kali dalam sebulan, usulan) dianggap tanda perencanaan lemah dan dibahas pada evaluasi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pemrakarsa","R","Melaporkan alasan mendesak dan opsi."],["Presiden / Plh","A","Mengambil keputusan mendesak."],["Unsur pimpinan lain","C","Memberi pertimbangan cepat."],["Sekretaris Jenderal","R","Menguji kriteria, mencatat, dan memastikan ratifikasi."],["Inspektur Jenderal","C","Menerima salinan dan meninjau keputusan mendesak."],["Rapat kabinet / Rapat Pimpinan","R","Meratifikasi keputusan."],["Eksekutif","I","Menerima pemberitahuan dan melaksanakan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan urgensi dari pemrakarsa.","Data dan dasar aturan yang tersedia."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Laporan urgensi: Melaporkan kepada Sekjen atau Presiden: kejadian, alasan mendesak, opsi, dan batas waktu.","Pemrakarsa","Informasi kejadian","Laporan urgensi","Segera"],["2","Uji kriteria: Memeriksa empat kriteria mendesak dan daftar larangan; jika tidak terpenuhi, kembalikan ke jalur rapat reguler.","Sekjen","Laporan","Hasil uji","Maks. 2 jam (usulan)"],["3","Konsultasi cepat: Meminta pertimbangan minimal satu unsur pimpinan lain dan unit terkait; memberi tahu Irjen.","Presiden","Hasil uji","Pertimbangan tercatat","Maks. 3 jam (usulan)"],["4","Keputusan: Mengambil keputusan; mengisi Lembar Keputusan Mendesak: waktu, dasar, opsi, pengambil keputusan, dampak, dan batas pelaksanaan.","Presiden / Plh","Pertimbangan","Lembar Keputusan Mendesak","Segera"],["5","Pelaksanaan terbatas: Melaksanakan hanya sebatas yang diputuskan dan menjaga bukti pelaksanaan.","Unit pelaksana","Lembar Keputusan","Bukti pelaksanaan","Sesuai batas waktu"],["6","Pemberitahuan: Memberi tahu Eksekutif dan pihak terdampak melalui kanal resmi.","Sekjen","Lembar Keputusan","Pemberitahuan terkirim","Maks. 1 x 24 jam"],["7","Ratifikasi: Membahas keputusan; hasilnya: dikukuhkan, dikoreksi, atau dicabut dengan langkah pemulihan.","Rapat terdekat (Rapat Pimpinan atau Rapat Kabinet)","Lembar Keputusan, bukti","Hasil ratifikasi","Maks. 3 hari kerja"],["8","Pencatatan: Mencatat pada Register Keputusan Mendesak dan mengarsipkan seluruh dokumen.","Sekjen","Dokumen","Register, arsip","3 hari kerja"],["9","Tinjauan: Memeriksa kepatuhan dan frekuensi keputusan mendesak; melaporkan pola pada evaluasi.","Irjen","Register","Catatan tinjauan","Bulanan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Keputusan diambil secepat kebutuhan (usulan: dalam hitungan jam), dilaporkan kepada Eksekutif paling lambat 1 x 24 jam, dan diratifikasi paling lambat 3 hari kerja. Hasil akhir: Lembar Keputusan Mendesak, hasil ratifikasi, dan entri register."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Keputusan termasuk larangan: tidak boleh diambil; alihkan ke rapat atau forum yang berwenang.","Ratifikasi menolak: keputusan dicabut, dampak dipulihkan, dan hasilnya dicatat.","Keputusan mendesak berdampak pada institusi: Presiden memberi tahu Pembina atau KAUR ORMAWA.","Penggunaan keputusan mendesak berulang: dibahas pada evaluasi dan SOP-MONEV-009."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% keputusan mendesak memiliki Lembar Keputusan Mendesak.","100% keputusan diratifikasi dalam 3 hari kerja.","Frekuensi keputusan mendesak tidak melebihi batas yang ditetapkan.","Tidak ada keputusan mendesak yang termasuk daftar larangan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Keputusan Mendesak.","Notulen ratifikasi.","Register Keputusan Mendesak.","Bukti pelaksanaan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tata Kelola) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen meninjau seluruh keputusan mendesak setiap bulan; Sekjen melaporkan frekuensinya pada evaluasi bulanan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Laporan urgensi → Uji kriteria mendesak → Konsultasi cepat → Keputusan Presiden atau Plh → Pelaksanaan terbatas dan pemberitahuan → Ratifikasi rapat terdekat → Catat dan tinjau Irjen → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Keputusan Mendesak","Tanggal dan jam; kejadian; alasan mendesak; opsi; keputusan; pengambil keputusan; yang dikonsultasikan; dampak; batas pelaksanaan; status ratifikasi."],["Register Keputusan Mendesak","Nomor; tanggal; ringkasan; pengambil keputusan; status ratifikasi; tinjauan Irjen."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Empat kriteria mendesak terpenuhi.","☐ Ya ☐ Tidak"],["2","Keputusan tidak termasuk larangan.","☐ Ya ☐ Tidak"],["3","Minimal satu unsur pimpinan lain dikonsultasikan.","☐ Ya ☐ Tidak"],["4","Eksekutif diberi tahu dalam 1 x 24 jam.","☐ Ya ☐ Tidak"],["5","Ratifikasi dilakukan dalam 3 hari kerja.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-TRN-001","g":"Transisi dan Keberlanjutan Kabinet","t":"Penyusunan Laporan Akhir Masa Jabatan","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[413,417],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan, verifikasi, pengesahan, penyampaian, dan pengarsipan Laporan Akhir Masa Jabatan kabinet yang memuat capaian program, keuangan, aset, kerja sama, dan evaluasi, sehingga pertanggungjawaban kepada BPM, KAUR ORMAWA, dan pengurus penerus lengkap, dapat diperiksa, dan sesuai AD/ART."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk Presiden, Wakil Presiden, Sekretaris Jenderal, Menteri, Kepala Biro, Inspektur Jenderal, dan seluruh pengurus BEM Kabinet Samasta yang menyumbang bahan laporan. SOP ini menjadi prosedur induk laporan akhir; LPJ per kegiatan mengikuti SOP-PRO-020, laporan keuangan akhir mengikuti SOP-TRN-004, dan serah terima jabatan mengikuti SOP-TRN-002."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) sampai (3) (laporan pertanggungjawaban berkala, transparan, dan akuntabel; disampaikan kepada BPM untuk dibahas pada Mubes dan hasilnya dilaporkan kepada KAUR ORMAWA).","AD Pasal 9 ayat (1) huruf b dan Pasal 10 (masa jabatan berakhir; masa jabatan satu periode kepengurusan).","ART Bab III (Tugas) huruf e (laporan pertanggungjawaban anggaran dan program pada akhir masa jabatan).","ART Pasal 3 (Kewajiban) huruf g (laporan kegiatan dan keuangan secara berkala kepada pihak berwenang).","ART Pasal 7 ayat (2), (5) huruf c, dan (8) (Mubes mengevaluasi kinerja organisasi; berita acara disahkan Ketua STDIIS).","ART Pasal 12 ayat (3) (kewenangan Irjen mengawasi, mengevaluasi, dan menilai kinerja pengurus)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Laporan Akhir Masa Jabatan","Dokumen induk pertanggungjawaban kabinet untuk satu periode kepengurusan: capaian program, keuangan, aset, kerja sama, temuan, dan rekomendasi."],["Laporan Unit","Laporan capaian dan kendala yang disusun setiap kementerian atau biro sebagai bahan Laporan Akhir."],["Hari-H","Tanggal serah terima jabatan pimpinan sebagaimana SOP-TRN-002; dasar semua hitungan H-/H+."],["Penerima laporan","BPM (membahas pada Mubes), KAUR ORMAWA (menerima hasil pembahasan), dan kabinet baru; Pembina menerima salinan."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Mengesahkan Laporan Akhir, bertanggung jawab atas isinya, dan menyampaikannya kepada BPM pada Mubes."],["Wakil Presiden","R","Mengoordinasikan Eksekutif agar Laporan Unit tepat waktu dan konsisten."],["Sekretaris Jenderal","R","Menyusun kerangka dan jadwal, menghimpun dan menyunting laporan, menyampaikan, dan mengarsipkan."],["Menteri / Kabiro","R","Menyusun Laporan Unit lengkap dengan bukti pendukung."],["Kepala Biro Keuangan","R","Menyusun ringkasan dan laporan keuangan akhir selaras SOP-TRN-004."],["Inspektur Jenderal","C","Memverifikasi kelengkapan dan kesesuaian data dengan bukti serta AD/ART."],["BPM, KAUR ORMAWA, kabinet baru","I","Menerima laporan; BPM membahasnya pada Mubes dan KAUR ORMAWA menerima hasil pembahasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Program kerja dan RAB hasil Rapat Kerja (RAKER) beserta perubahannya.","LPJ kegiatan, laporan keuangan, dan Register Keputusan.","Daftar inventaris, daftar kerja sama, dan daftar program belum selesai (SOP-TRN-005, 007, 008).","Hasil evaluasi tengah periode dan Register Temuan dan Pembelajaran (SOP-TRN-009)."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Kerangka dan jadwal: Menyusun kerangka Laporan Akhir (ringkasan eksekutif, capaian program, keuangan, aset, kerja sama, SDM, kendala, rekomendasi) dan jadwal penyerahan setiap unit.","Sekjen","Templat laporan, Kalender Transisi","Kerangka dan jadwal","3 hari kerja setelah Tim Transisi ditetapkan"],["2","Laporan Unit: Mengisi Formulir Laporan Unit: capaian terhadap target, kendala, rekomendasi, dan daftar lampiran bukti.","Menteri / Kabiro","Program kerja, LPJ, notulen","Laporan Unit","H-30"],["3","Laporan keuangan: Menyusun ringkasan pemasukan, pengeluaran, saldo, dan kewajiban sampai tanggal cut-off sementara.","Biro Keuangan","Buku kas, bukti transaksi","Ringkasan keuangan","H-30"],["4","Penghimpunan: Menggabungkan laporan, memeriksa konsistensi angka antarunit, dan menyusun draf Laporan Akhir.","Sekjen bersama Wapres","Laporan Unit, ringkasan keuangan","Draf Laporan Akhir","5 hari kerja (H-21)"],["5","Verifikasi: Memeriksa draf dengan Checklist Pemeriksaan terhadap bukti dan AD/ART; mencatat temuan secara tertulis.","Irjen","Draf, checklist","Catatan verifikasi","5 hari kerja (H-14)"],["6","Pembahasan: Membahas draf pada rapat kabinet (SOP-GOV-006), lalu merevisi sesuai catatan Irjen.","Pimpinan dan Eksekutif","Draf, catatan Irjen","Draf final","1 rapat; revisi 3 hari kerja (H-7)"],["7","Pengesahan: Menandatangani Laporan Akhir yang telah diverifikasi.","Presiden","Draf final","Laporan Akhir disahkan","2 hari kerja"],["8","Penyampaian: Menyerahkan Laporan Akhir kepada BPM untuk dibahas pada Mubes; menyalin kepada KAUR ORMAWA, Pembina, dan kabinet baru; Presiden memaparkan pada Mubes.","Sekjen; Presiden","Laporan disahkan","Tanda terima; paparan Mubes","Paling lambat 7 hari kerja sebelum Mubes"],["9","Tindak lanjut dan arsip: Mencatat masukan BPM, memastikan Berita Acara Mubes disahkan Ketua STDIIS, melaporkan hasil pembahasan kepada KAUR ORMAWA, menyerahkan daftar tindak lanjut kepada kabinet baru, dan mengarsipkan.","Sekjen","Berita Acara Mubes","Laporan hasil pembahasan, arsip","5 hari kerja setelah Mubes"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Proses dari penetapan kerangka sampai pengesahan ditargetkan selesai paling lambat H-7. Laporan Akhir diserahkan kepada BPM paling lambat 7 hari kerja sebelum Mubes. Hasil akhir: Laporan Akhir yang disahkan Presiden, diverifikasi Irjen, dan diterima BPM serta KAUR ORMAWA."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Unit terlambat menyerahkan Laporan Unit: Sekjen mengingatkan; keterlambatan lebih dari 3 hari kerja dilaporkan kepada Wakil Presiden (SOP-MONEV-008).","Data tidak sesuai bukti: laporan dikembalikan kepada unit; temuan yang belum selesai dicantumkan sebagai catatan dan diteruskan kepada kabinet baru.","Mubes belum terlaksana pada Hari-H: Presiden lama tetap menyampaikan dan menjelaskan laporan pada Mubes; Laporan Akhir tetap diserahkan kepada kabinet baru.","BPM meminta perbaikan: Sekjen mencatat; perbaikan dilakukan Presiden lama dalam batas waktu yang disepakati dengan BPM; bila tidak sepakat, dikonsultasikan kepada KAUR ORMAWA.","Ditemukan dugaan penyalahgunaan dana atau aset: hentikan penyusunan bagian terkait dan alihkan ke SOP-RSK-007; pelaporan kepada KAUR ORMAWA mengikuti ART Pasal 12 ayat (7)."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% unit menyerahkan Laporan Unit paling lambat H-30.","Laporan Akhir disahkan paling lambat H-7.","Tidak ada angka keuangan pada laporan yang berbeda dengan buku kas pada verifikasi Irjen.","100% temuan memiliki penanggung jawab dan tenggat tindak lanjut."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan Akhir Masa Jabatan yang disahkan Presiden.","Laporan Unit dan lampiran bukti.","Catatan verifikasi Irjen.","Tanda terima BPM dan KAUR ORMAWA serta salinan Berita Acara Mubes.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Transisi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan bahan laporan setiap bulan menjelang akhir periode (mulai H-90); Irjen menilai kepatuhan jadwal dan kualitas bukti pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kerangka dan jadwal → Laporan Unit → Laporan keuangan → Himpun dan sunting → Verifikasi Irjen → Pembahasan kabinet → Pengesahan Presiden → Penyampaian ke BPM dan KAUR ORMAWA → Tindak lanjut dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan Unit","Nama unit; periode; program dan capaian terhadap target; kendala; rekomendasi; daftar lampiran bukti; penanggung jawab; tanggal."],["Templat Laporan Akhir Masa Jabatan","Ringkasan eksekutif; capaian program; keuangan; aset; kerja sama; SDM; temuan dan tindak lanjut; rekomendasi; lampiran."],["Tanda Terima Penyampaian Laporan","Penerima; tanggal; daftar dokumen; pengirim; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh Menteri dan Kabiro telah menyerahkan Laporan Unit.","☐ Ya ☐ Tidak"],["2","Capaian dibandingkan dengan target RAKER dan alasan selisih dicatat.","☐ Ya ☐ Tidak"],["3","Ringkasan keuangan sesuai buku kas dan bukti transaksi.","☐ Ya ☐ Tidak"],["4","Daftar aset, kerja sama, dan program belum selesai dilampirkan.","☐ Ya ☐ Tidak"],["5","Catatan verifikasi Irjen telah ditindaklanjuti.","☐ Ya ☐ Tidak"],["6","Laporan disahkan Presiden dan tercatat pada Register Dokumen.","☐ Ya ☐ Tidak"],["7","Tanda terima BPM dan KAUR ORMAWA tersedia.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; BPM (untuk dibahas pada Mubes); KAUR ORMAWA; Presiden terpilih dan kabinet baru; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina bila diminta.."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-TRN-002","g":"Transisi dan Keberlanjutan Kabinet","t":"Serah Terima Jabatan Pimpinan","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[418,422],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur serah terima kewenangan Presiden, Wakil Presiden, dan Sekretaris Jenderal dari pimpinan lama kepada pimpinan baru, serta memicu serah terima dokumen, keuangan, inventaris, akun, kerja sama, dan program, sehingga tidak ada kekosongan kewenangan dan setiap pengalihan tercatat."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku pada pergantian pimpinan di akhir periode dan pergantian di tengah periode (ART Pasal 5 ayat 7 dan 8). SOP ini tidak mengatur pemilihan Presiden dan Wakil Presiden (AD Pasal 11 ayat 2 huruf a), pengangkatan pengurus (SOP-SDM-001), maupun orientasi (SOP-TRN-010). SOP ini menjadi induk yang menentukan Hari- H bagi SOP-TRN-001 sampai SOP-TRN-010."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 7 dan Pasal 13 (susunan pengurus dan pimpinan BEM).","AD Pasal 8 ayat (4) (Presiden disahkan dan dilantik oleh Ketua STDIIS).","AD Pasal 9 ayat (1) huruf b dan Pasal 10 (masa jabatan satu periode; Presiden tidak dapat dipilih kembali).","AD Pasal 11 ayat (2) huruf a dan b (pemilihan Presiden dan Wakil Presiden; pengangkatan Menteri dan Kabiro secara prerogatif oleh Presiden).","ART Pasal 4 huruf b (mengangkat dan memberhentikan pengurus internal).","ART Pasal 5 ayat (3), (4), (7), dan (8) (pelantikan, masa jabatan, berhentinya pimpinan, dan penggantian Presiden)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Hari-H","Tanggal pelantikan Presiden terpilih oleh Ketua STDIIS dan penandatanganan Berita Acara Serah Terima Jabatan."],["Kabinet lama / demisioner","Pengurus yang masa jabatannya berakhir; tetap bertanggung jawab atas pelaporan dan serah terima sampai selesai."],["Tim Transisi","Tim yang ditetapkan Presiden untuk mengoordinasikan seluruh serah terima, dikoordinasikan Sekretaris Jenderal."],["Berita Acara Serah Terima Jabatan (BASTJ)","Dokumen resmi pengalihan jabatan beserta daftar lampiran dan catatan pengecualian."],["Masa peralihan","Periode H-14 sampai Hari-H ketika keputusan yang mengikat kabinet baru dibatasi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kewenangan Presiden lama beralih saat BASTJ ditandatangani setelah pelantikan (usulan); sebelum itu kabinet lama menjalankan tugas rutin.","Pada masa peralihan kabinet lama tidak membuat kebijakan, pengangkatan, atau kerja sama baru yang mengikat kabinet baru tanpa konsultasi dengan Presiden terpilih.","Presiden dilantik oleh Ketua STDIIS (AD Pasal 8 ayat 4); Wakil Presiden, Sekretaris Jenderal, dan pengurus lain dilantik Presiden terpilih (ART Pasal 5 ayat 4), sebaiknya pada acara yang sama dan dikonfirmasi kepada KAUR ORMAWA.","Menteri dan Kabiro baru diangkat Presiden terpilih secara prerogatif melalui forum musyawarah internal (AD Pasal 11 ayat 2 huruf b); pejabat lama tetap menjalankan unit sampai serah terima unit selesai.","Serah terima tidak menghapus tanggung jawab kabinet lama atas laporan (SOP-TRN-001) dan temuan yang belum selesai.","Pergantian di tengah periode: Wakil Presiden menggantikan Presiden berdasarkan kesepakatan musyawarah internal (ART Pasal 5 ayat 8) dengan ratifikasi mengikuti SOP-GOV-009; BASTJ dibuat dalam bentuk ringkas."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden (lama)","A","Bertanggung jawab akhir atas serah terima, menetapkan Tim Transisi, dan menandatangani BASTJ."],["Presiden terpilih","R","Menerima jabatan, menandatangani BASTJ, melantik pengurus, dan menetapkan Menteri dan Kabiro baru."],["Wakil Presiden","R","Memastikan kesiapan Eksekutif dan ikut menyerahkan kondisi organisasi kepada pimpinan baru."],["Sekretaris Jenderal","R","Mengoordinasikan Tim Transisi, menyusun Kalender Transisi, Daftar Periksa, dan BASTJ; mengarsipkan."],["Inspektur Jenderal","C","Memverifikasi kelengkapan paket serah terima dan menjadi pengamat."],["Ketua STDIIS / KAUR ORMAWA","C","Dikonfirmasi jadwal dan pelaksanaan pelantikan; KAUR ORMAWA atau Pembina diundang sebagai saksi."],["Seluruh pengurus","I","Menerima pengumuman dan menjalankan serah terima unit."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Hasil pemilihan Presiden dan Wakil Presiden dan jadwal pelantikan dari kampus.","Daftar susunan kabinet lama dan baru.","SOP-TRN-003 sampai SOP-TRN-008 beserta hasilnya.","Laporan Akhir (SOP-TRN-001) dan Catatan Pembelajaran (SOP-TRN-009)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan Tim Transisi: Menetapkan Tim Transisi melalui Keputusan Presiden dan menyusun Kalender Transisi berdasarkan Hari-H.","Presiden; Sekjen","Jadwal pelantikan, daftar SOP-TRN","Keputusan Presiden; Kalender Transisi","H-45"],["2","Konfirmasi kampus: Mengonfirmasi jadwal, pelantik, dan saksi pelantikan kepada KAUR ORMAWA atau Ketua STDIIS melalui surat resmi.","Sekjen","Kalender Transisi","Jadwal terkonfirmasi","H-40"],["3","Pembekalan Presiden terpilih: Menyampaikan Ringkasan Kondisi Organisasi: isu strategis, risiko, keputusan tertunda, kerja sama, dan kewajiban.","Presiden dan Wapres","Laporan Akhir (draf), temuan Irjen","Catatan pembekalan","H-30 sampai H-14"],["4","Penyiapan paket serah terima: Memastikan SOP-TRN-003 sampai SOP-TRN-008 berjalan sesuai Kalender dan menyusun Daftar Periksa Serah Terima.","Sekjen","Hasil SOP-TRN- 003 sampai 008","Paket serah terima","H-7"],["5","Verifikasi: Memeriksa kelengkapan paket dengan Daftar Periksa dan mencatat kekurangan.","Irjen","Paket, Daftar Periksa","Catatan verifikasi","H-5"],["6","Rapat serah terima: Membahas ringkasan, kendala, dan keputusan yang ditangguhkan untuk kabinet baru pada Rapat Pimpinan (SOP-GOV-005).","Pimpinan lama dan Presiden terpilih","Catatan verifikasi","Daftar keputusan tertunda","H-3"],["7","Pelantikan dan BASTJ: Presiden dilantik Ketua STDIIS; Presiden lama dan baru menandatangani BASTJ beserta lampiran dan Catatan Pengecualian.","Presiden lama dan baru","Paket serah terima","BASTJ","Hari-H"],["8","Pelantikan pengurus dan serah terima unit: Presiden baru melantik Wakil Presiden, Sekretaris Jenderal, Menteri, Kabiro, dan pengurus; pejabat lama menyerahkan unit memakai Formulir Serah Terima Unit.","Presiden baru; Menteri / Kabiro","SK pengangkatan, Formulir Serah Terima Unit","Formulir Serah Terima Unit","Hari-H sampai H+7"],["9","Penutupan: Mengumumkan susunan kabinet baru dan kanal resmi, mengalihkan akses (SOP-TRN-006), dan mengarsipkan seluruh berkas.","Sekjen","BASTJ, Formulir Serah Terima Unit","Pengumuman, arsip","H+3"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Tim Transisi ditetapkan paling lambat H-45. BASTJ ditandatangani pada Hari-H. Serah terima unit selesai paling lambat 7 hari kerja setelah Hari-H. Hasil akhir: BASTJ beserta lampiran, Daftar Periksa, dan Formulir Serah Terima Unit seluruh unit."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pelantikan mundur atau Presiden terpilih belum dilantik: kabinet lama menjalankan tugas rutin dan menangguhkan keputusan strategis; Kalender Transisi disesuaikan dan dikonsultasikan kepada KAUR ORMAWA.","Presiden lama berhalangan hadir: Wakil Presiden menandatangani dengan Surat Mandat (SOP-GOV- 008). Presiden terpilih berhalangan: BASTJ tidak ditandatangani sebelum pelantikan.","Paket serah terima belum lengkap: BASTJ tetap ditandatangani dengan Catatan Pengecualian berisi butir, penanggung jawab, dan tenggat paling lama 7 hari kerja; Irjen memantau.","Sengketa hasil pemilihan atau pengesahan: di luar SOP ini; mengikuti AD Pasal 11 dan Musyawarah Istimewa; serah terima ditangguhkan.","Pergantian di tengah periode: ikuti SOP-GOV-009 dan ART Pasal 5 ayat (8)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["BASTJ ditandatangani pada Hari-H.","100% butir Daftar Periksa berstatus selesai atau tercatat pada Catatan Pengecualian.","Tidak ada kekosongan kewenangan pimpinan selama masa peralihan.","Serah terima unit selesai paling lambat 7 hari kerja setelah Hari-H.","Tidak ada keputusan mengikat yang dibuat kabinet lama pada masa peralihan tanpa konsultasi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Keputusan Presiden tentang Tim Transisi dan Kalender Transisi.","Ringkasan Kondisi Organisasi dan catatan pembekalan.","Daftar Periksa Serah Terima dan catatan verifikasi Irjen.","BASTJ beserta Catatan Pengecualian.","Formulir Serah Terima Unit seluruh unit dan pengumuman susunan kabinet baru.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Transisi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memantau Kalender Transisi setiap pekan mulai H-45; Irjen menilai kelengkapan BASTJ dan kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tim Transisi dan Kalender → Konfirmasi kampus → Pembekalan Presiden terpilih → Paket serah terima → Verifikasi Irjen → Pelantikan dan BASTJ → Serah terima unit → Pengumuman dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Berita Acara Serah Terima Jabatan","Hari dan tanggal; para pihak dan jabatan; dasar pengalihan; daftar lampiran; Catatan Pengecualian; tanda tangan para pihak dan saksi."],["Ringkasan Kondisi Organisasi","Isu strategis; risiko; keputusan dan program tertunda; kerja sama; kewajiban; rekomendasi."],["Formulir Serah Terima Unit","Unit; pejabat lama dan baru; dokumen; aset; akun; pekerjaan berjalan; kontak mitra; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Jadwal, pelantik, dan saksi pelantikan telah dikonfirmasi kampus.","☐ Ya ☐ Tidak"],["2","Tim Transisi dan Kalender Transisi telah ditetapkan.","☐ Ya ☐ Tidak"],["3","Ringkasan Kondisi Organisasi telah disampaikan kepada Presiden terpilih.","☐ Ya ☐ Tidak"],["4","SOP-TRN-003 sampai SOP-TRN-008 selesai atau tercatat pada Catatan Pengecualian.","☐ Ya ☐ Tidak"],["5","Verifikasi Irjen telah dilakukan dan dicatat.","☐ Ya ☐ Tidak"],["6","BASTJ ditandatangani lengkap dan diarsipkan.","☐ Ya ☐ Tidak"],["7","Akses digital lama telah dicabut (SOP-TRN-006).","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden lama dan baru; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro lama dan baru; arsip Biro Kesekretariatan. Salinan diberikan kepada KAUR ORMAWA atau Pembina dan Ketua STDIIS bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-TRN-003","g":"Transisi dan Keberlanjutan Kabinet","t":"Serah Terima Dokumen dan Arsip","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[423,426],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Memastikan seluruh dokumen resmi dan arsip kabinet, baik fisik maupun digital, tercatat, lengkap, aman, dan berpindah kepada kabinet baru tanpa ada yang hilang, tertinggal pada akun atau perangkat pribadi, atau diakses pihak yang tidak berwenang."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh dokumen kabinet: AD/ART, keputusan dan surat tugas, surat masuk dan keluar, proposal, LPJ, notulen dan berita acara, dokumen kerja sama, data pengurus, serta dokumen rahasia. SOP ini mengatur serah terima akhir; pengelolaan harian mengikuti SOP-ADM-012 sampai SOP-ADM-016, dan serah terima akun digital mengikuti SOP-TRN-006."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (3) (sumber dana didokumentasikan dengan bukti resmi).","AD Pasal 17 ayat (2) (pengelolaan transparan dan akuntabel).","ART Pasal 4 huruf f (wewenang menandatangani surat resmi dan dokumen organisasi).","ART Pasal 7 ayat (8) dan Pasal 10 ayat (5) (Berita Acara dan notulensi resmi).","Pedoman Penyusunan SOP, Bagian V (sistem kode dan data pengendalian dokumen)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Daftar Induk Arsip","Indeks seluruh dokumen: kode, judul, tanggal, lokasi, status, dan tingkat kerahasiaan."],["Repositori resmi","Penyimpanan digital milik organisasi, bukan akun atau perangkat pribadi."],["Dokumen rahasia","Dokumen yang aksesnya dibatasi, seperti data pribadi anggota, pengaduan, dan dokumen keuangan sensitif."],["Berita Acara Serah Terima Dokumen (BASTD)","Bukti resmi penyerahan arsip beserta daftar yang diserahkan."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Bertanggung jawab akhir atas kelengkapan dan penyerahan arsip serta menandatangani BASTD."],["Kepala Biro Kesekretariatan","R","Memperbarui Daftar Induk Arsip, mengklasifikasi, mencadangkan, dan menyerahkan arsip."],["Menteri / Kabiro","R","Menyerahkan arsip unit dan memindahkan dokumen dari perangkat atau akun pribadi ke repositori resmi."],["Inspektur Jenderal","C","Mencocokkan Daftar Induk dengan arsip fisik dan digital."],["Sekretaris Jenderal dan Kabiro Kesekretariatan baru","R","Menerima, memeriksa, dan menetapkan Daftar Induk sebagai acuan awal kabinet baru."],["Presiden","I","Menerima laporan kelengkapan arsip."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Register Dokumen dan folder resmi.","Daftar arsip setiap unit.","Standar penamaan file dan struktur folder (SOP-ADM-014).","Daftar dokumen rahasia dan hak akses (SOP-ADM-020)."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Inventarisasi: Memperbarui Daftar Induk Arsip dari Register Dokumen dan folder resmi; setiap unit mengisi daftar arsipnya.","Biro Kesekretariatan; Menteri / Kabiro","Register Dokumen, folder","Draf Daftar Induk","H-30"],["2","Pengumpulan: Menyerahkan arsip fisik dan digital unit serta memindahkan dokumen dari akun atau perangkat pribadi ke repositori resmi.","Menteri / Kabiro","Daftar arsip unit","Arsip terkumpul","H-21"],["3","Klasifikasi: Memisahkan dokumen umum, terbatas, dan rahasia; memberi kode dan nama file; menandai dokumen yang masih berlaku dan menunggu tindak lanjut.","Biro Kesekretariatan","Arsip terkumpul","Arsip terklasifikasi","H-14"],["4","Pemeriksaan: Mencocokkan Daftar Induk dengan arsip fisik dan digital, termasuk memeriksa urutan nomor surat tanpa celah.","Irjen","Daftar Induk, arsip","Catatan verifikasi","H-10"],["5","Pelengkapan: Mencari atau merekonstruksi dokumen yang kurang; dokumen yang tidak ditemukan dicatat dalam Catatan Dokumen Tidak Ditemukan.","Biro Kesekretariatan","Catatan verifikasi","Arsip lengkap atau tercatat","H-7"],["6","Pencadangan: Membuat dan menguji cadangan repositori yang disimpan terpisah (SOP-ADM-015).","Biro Kesekretariatan","Repositori","Cadangan terverifikasi","H-3"],["7","Serah terima: Menandatangani BASTD; arsip fisik diserahkan dengan daftar, arsip digital melalui pengalihan akses (SOP-TRN- 006); dokumen rahasia hanya kepada pejabat berwenang.","Sekjen lama dan baru","Daftar Induk, cadangan","BASTD","Hari-H sampai H+3"],["8","Penerimaan: Memeriksa arsip yang diterima, mencatat keberatan, dan menetapkan Daftar Induk sebagai acuan awal.","Sekjen dan Biro Kesekretariatan baru","BASTD","Daftar Induk acuan awal","5 hari kerja setelah Hari-H"],["9","Penutupan: Mencabut akses lama, memindahkan arsip yang telah selesai ke arsip tidak aktif, dan memperbarui Register Dokumen.","Biro Kesekretariatan baru","Daftar Induk","Register diperbarui","7 hari kerja setelah Hari-H"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Inventarisasi dimulai H-30 dan seluruh arsip lengkap atau tercatat paling lambat H-7. BASTD ditandatangani paling lambat H+3. Hasil akhir: BASTD beserta Daftar Induk Arsip dan Catatan Dokumen Tidak Ditemukan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Dokumen tidak ditemukan: dicatat, direkonstruksi bila memungkinkan, dan dilaporkan kepada Presiden; dokumen tidak boleh dibuat ulang dengan tanggal lama tanpa keterangan.","Dokumen pada akun atau perangkat pribadi belum dipindahkan: Sekjen menetapkan tenggat 3 hari kerja; bila tetap tidak diserahkan, Irjen melaporkan kepada Presiden (ART Pasal 11 huruf k).","Dokumen pengaduan, identitas pelapor, dan data pribadi anggota: diserahkan hanya kepada pejabat berwenang dengan berita acara tersendiri (SOP-ADV-011, SOP-SDM-018).","Celah nomor surat: ditelusuri; surat batal dicatat, bukan dihapus.","Dugaan penghapusan atau pemalsuan dokumen: SOP-RSK-004."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% dokumen inti (AD/ART, keputusan, LPJ, perjanjian, berita acara) tercatat pada Daftar Induk.","BASTD ditandatangani paling lambat H+3.","Tidak ada dokumen resmi yang hanya tersimpan pada akun atau perangkat pribadi setelah Hari-H.","Cadangan terverifikasi dapat dibuka sebelum serah terima."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Induk Arsip dan Catatan Dokumen Tidak Ditemukan.","Catatan verifikasi Irjen.","BASTD.","Bukti cadangan repositori.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Transisi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Biro Kesekretariatan memperbarui Daftar Induk Arsip setiap bulan sepanjang periode; Irjen memeriksa sampel arsip pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Inventarisasi → Pengumpulan → Klasifikasi → Pemeriksaan Irjen → Pelengkapan → Pencadangan → Serah terima BASTD → Penerimaan → Penutupan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Induk Arsip","Kode dokumen; judul; tanggal; unit; lokasi; format; status; tingkat kerahasiaan; keterangan."],["Berita Acara Serah Terima Dokumen","Hari dan tanggal; para pihak; daftar dokumen; Catatan Dokumen Tidak Ditemukan; tanda tangan."],["Catatan Dokumen Tidak Ditemukan","Dokumen; terakhir diketahui; upaya penelusuran; penanggung jawab; tindak lanjut."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Daftar Induk Arsip memuat dokumen seluruh unit.","☐ Ya ☐ Tidak"],["2","Dokumen pada akun atau perangkat pribadi telah dipindahkan ke repositori resmi.","☐ Ya ☐ Tidak"],["3","Dokumen rahasia dipisahkan dan aksesnya dibatasi.","☐ Ya ☐ Tidak"],["4","Cadangan telah dibuat dan diuji.","☐ Ya ☐ Tidak"],["5","BASTD ditandatangani dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Kesekretariatan; seluruh Menteri dan Kepala Biro. Daftar dokumen rahasia hanya diberikan kepada pejabat yang berwenang."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-TRN-004","g":"Transisi dan Keberlanjutan Kabinet","t":"Serah Terima Saldo, Rekening, dan Kewajiban Keuangan","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[427,431],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penutupan pembukuan, pemeriksaan, dan serah terima saldo, rekening, serta kewajiban keuangan kabinet kepada Biro Keuangan baru, sehingga tidak ada dana atau kewajiban yang tidak jelas keberadaan, jumlah, atau pertanggungjawabannya."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk kas tunai, rekening organisasi, dana kemahasiswaan dari kampus, dana sponsor, hibah, donasi, uang muka, piutang, dan kewajiban yang belum dibayar. SOP ini tidak mengatur pemeriksaan kas berkala (SOP-KEU-017) maupun LPJ kegiatan (SOP-PRO-020); bila SOP-KEU-020 disusun, SOP ini menjadi acuan atau digabung."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) sampai (4) (sumber dana, bebas riba, gharar, dan maysir, bukti penerimaan resmi, dan persetujuan penyusunan anggaran).","AD Pasal 17 ayat (1) sampai (3) (laporan pertanggungjawaban, transparansi, dan akuntabilitas).","ART Pasal 3 (Kewajiban) huruf e dan g (pengelolaan keuangan amanah dan laporan berkala).","ART Bab III (Tugas) huruf e dan Wewenang huruf d (anggaran dan pengajuan dana kemahasiswaan).","ART Pasal 11 huruf i dan k (larangan korupsi, manipulasi, penyelewengan dana, dan penyalahgunaan fasilitas).","ART Pasal 12 ayat (3) dan (7) (pengawasan Irjen dan pelaporan pelanggaran berat kepada KAUR ORMAWA)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Cut-off","Tanggal penutupan pembukuan; transaksi setelah tanggal ini dicatat sebagai transaksi masa peralihan."],["Rekonsiliasi","Pencocokan buku kas, rekening koran, dan uang tunai."],["Laporan Posisi Keuangan Akhir","Ringkasan saldo, piutang, kewajiban, dan uang muka pada tanggal cut-off."],["Kewajiban lintas periode","Kewajiban atau komitmen pembayaran yang jatuh tempo atau berlaku setelah Hari-H."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Tanggal cut-off ditetapkan H-7 (usulan); transaksi setelah cut-off disetujui bersama Presiden lama dan terpilih.","Saldo diserahkan sebesar hasil rekonsiliasi dan hitung fisik; selisih dicatat dan dijelaskan, tidak disembunyikan.","Fungsi dipisahkan: penyusun (Biro Keuangan), pemeriksa (Irjen), pemberi persetujuan (Presiden), dan penerima (Biro Keuangan baru).","Dana organisasi tidak disimpan pada rekening pribadi; bila ditemukan, dipindahkan ke rekening resmi dan dicatat sebagai temuan.","Sponsor dan hibah tidak boleh menimbulkan kewajiban melampaui satu periode (AD Pasal 15 ayat 1 huruf b); bila terlanjur ada, dicatat dan dikonsultasikan kepada KAUR ORMAWA.","Pengalihan akses rekening mengikuti ketentuan bank atau kampus dan tidak dilakukan dengan sekadar membagikan kata sandi (SOP-TRN-006)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Bertanggung jawab akhir atas serah terima keuangan dan menyetujui Laporan Posisi Keuangan Akhir."],["Kepala Biro Keuangan (lama)","R","Menutup pembukuan, merekonsiliasi, menyelesaikan kewajiban, dan menyerahkan saldo serta dokumen."],["Kepala Biro Keuangan (baru)","R","Memeriksa dan menerima saldo, rekening, dan kewajiban."],["Sekretaris Jenderal","R","Mencatat Berita Acara dan mengarsipkan seluruh bukti."],["Inspektur Jenderal","C","Menyaksikan hitung kas, memeriksa bukti dan kewajiban, dan mencatat temuan."],["KAUR ORMAWA","I","Menerima laporan bila disyaratkan ketentuan kampus."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Buku kas, bukti transaksi, dan rekening koran.","Daftar uang muka, piutang, dan kewajiban belum dibayar.","RAB dan LPJ kegiatan.","Dokumen sponsor, hibah, dan donasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Persiapan: Menyusun daftar kas, rekening, uang muka, piutang, kewajiban, dan kegiatan yang masih berbiaya; menetapkan tanggal cut-off.","Biro Keuangan","Buku kas, rekening koran","Daftar posisi keuangan","H-14"],["2","Penutupan pembukuan: Mencatat seluruh transaksi sampai cut- off, melengkapi bukti, dan menandai transaksi tanpa bukti.","Biro Keuangan","Daftar transaksi","Buku kas ditutup","H-7 (cut-off)"],["3","Rekonsiliasi dan hitung fisik: Mencocokkan buku kas, rekening koran, dan uang tunai; hitung fisik disaksikan Irjen.","Biro Keuangan; Irjen","Buku kas, rekening koran","Berita Acara Hitung Kas","3 hari kerja setelah cut-off"],["4","Pemeriksaan bukti dan kewajiban: Memeriksa bukti transaksi, kesesuaian dengan RAB, uang muka belum dipertanggungjawabkan, dan kewajiban belum dibayar.","Irjen","Bukti, RAB","Catatan pemeriksaan","3 hari kerja"],["5","Penyelesaian: Melunasi kewajiban jatuh tempo, mempertanggungjawabkan uang muka, dan menyelesaikan kelebihan atau kekurangan dana (SOP-KEU- 018); sisanya didaftar.","Biro Keuangan","Catatan pemeriksaan","Daftar Kewajiban dan Piutang","5 hari kerja"],["6","Persetujuan: Menelaah dan menyetujui Laporan Posisi Keuangan Akhir untuk diserahkan.","Presiden","Laporan, catatan Irjen","Persetujuan tertulis","2 hari kerja"],["7","Serah terima: Menandatangani Berita Acara Serah Terima Keuangan; menyerahkan saldo tunai, buku kas, bukti rekening, dan dokumen pendukung.","Kabiro Keuangan lama dan baru; Presiden","Laporan disetujui","BA Serah Terima Keuangan","Hari-H"],["8","Pengalihan akses rekening: Mengubah penandatangan atau pengguna rekening sesuai ketentuan bank atau kampus dan mencabut akses lama.","Biro Keuangan baru; Sekjen","BA, surat keputusan","Bukti perubahan akses","5 hari kerja setelah Hari-H"],["9","Pemeriksaan penerima: Memeriksa penerimaan, mencatat keberatan, dan menetapkan saldo awal kabinet baru.","Biro Keuangan baru","BA, laporan","Saldo awal ditetapkan","5 hari kerja setelah Hari-H"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Cut-off ditetapkan H-7. Hitung kas dan rekonsiliasi selesai 3 hari kerja setelah cut-off. Berita Acara Serah Terima Keuangan ditandatangani pada Hari-H dan akses rekening lama dicabut paling lambat 5 hari kerja setelahnya. Hasil akhir: Laporan Posisi Keuangan Akhir dan BA Serah Terima Keuangan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Selisih kas: dicatat dan ditelusuri 5 hari kerja; bila belum terjelaskan dibawa ke Rapat Pimpinan; dugaan penyalahgunaan dialihkan ke SOP-RSK-007 dan dilaporkan kepada KAUR ORMAWA (ART Pasal 12 ayat 7).","Bukti transaksi tidak lengkap: dibuat berita acara klarifikasi; bukti tidak boleh diubah atau dibuat ulang tanpa keterangan.","Kewajiban atau komitmen melampaui satu periode: dicatat, dilaporkan kepada Presiden, dan dikonsultasikan kepada KAUR ORMAWA.","LPJ dana kampus belum disetujui: kabinet lama tetap melengkapi dan dana tidak dihitung sebagai saldo bebas.","Pejabat keuangan berhalangan: Presiden menunjuk pelaksana secara tertulis (SOP-GOV-008)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Saldo buku, rekening koran, dan kas fisik cocok pada tanggal cut-off atau selisih terjelaskan.","100% kewajiban dan piutang tercatat pada daftar serah terima.","BA Serah Terima Keuangan ditandatangani pada Hari-H.","Akses rekening lama dicabut paling lambat 5 hari kerja setelah Hari-H."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan Posisi Keuangan Akhir.","Berita Acara Hitung Kas dan rekonsiliasi.","Daftar Kewajiban dan Piutang.","Catatan pemeriksaan Irjen.","BA Serah Terima Keuangan dan bukti perubahan akses rekening.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Transisi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Biro Keuangan merekonsiliasi saldo setiap bulan sepanjang periode; Irjen memeriksa kepatuhan dan kelengkapan bukti pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Persiapan → Tutup pembukuan → Rekonsiliasi dan hitung kas → Pemeriksaan Irjen → Selesaikan kewajiban → Persetujuan Presiden → Serah terima keuangan → Pengalihan akses rekening → Pemeriksaan penerima → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Berita Acara Hitung Kas dan Rekonsiliasi","Tanggal cut-off; saldo buku; saldo rekening; kas fisik; selisih dan penjelasan; tanda tangan."],["Daftar Kewajiban dan Piutang","Pihak; jenis; jumlah; jatuh tempo; dasar dokumen; penanggung jawab; keterangan."],["Berita Acara Serah Terima Keuangan","Para pihak; saldo; daftar rekening; kewajiban; dokumen; catatan; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pembukuan ditutup pada tanggal cut-off dan setiap transaksi memiliki bukti.","☐ Ya ☐ Tidak"],["2","Buku kas, rekening koran, dan kas fisik telah direkonsiliasi.","☐ Ya ☐ Tidak"],["3","Uang muka telah dipertanggungjawabkan atau tercatat.","☐ Ya ☐ Tidak"],["4","Kewajiban lintas periode didaftar dan dilaporkan.","☐ Ya ☐ Tidak"],["5","Tidak ada dana organisasi pada rekening pribadi.","☐ Ya ☐ Tidak"],["6","Akses rekening lama telah dicabut dan bukti tersedia.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden lama dan baru; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro Keuangan lama dan baru; arsip Biro Kesekretariatan. Salinan diberikan kepada KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-TRN-005","g":"Transisi dan Keberlanjutan Kabinet","t":"Serah Terima Inventaris","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[432,435],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pemeriksaan fisik dan serah terima seluruh inventaris BEM, ruang sekretariat, dan aset pinjaman kepada pengurus baru, sehingga keberadaan, kondisi, dan penanggung jawab setiap aset jelas serta aset tidak hilang atau berpindah tanpa catatan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk aset milik BEM, aset pinjaman dari kampus, perlengkapan acara, kunci dan ruang sekretariat, serta atribut organisasi. SOP ini tidak mengatur peminjaman harian (SOP-AST-003 dan SOP-AST-004) dan penanganan aset hilang atau rusak (SOP-AST-007); SOP-AST-011 menjadi acuan bila disusun."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf d (hasil pengembangan aset organisasi yang dikelola secara produktif).","AD Pasal 18 ayat (1) dan (2) (lambang yang disahkan STDIIS; lambang tidak disahkan dilarang di dalam kampus).","ART Pasal 2 huruf b dan i (hak atas nama, lambang, dan identitas resmi; fasilitas dan dukungan kampus).","ART Pasal 11 huruf k (larangan menggunakan fasilitas atau nama organisasi untuk kepentingan pribadi).","ART Pasal 12 ayat (3) (pengawasan dan penilaian kinerja pengurus oleh Irjen)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Aset BEM","Barang yang dibeli, dihibahkan, atau diperoleh BEM dan tercatat pada Daftar Inventaris."],["Aset pinjaman kampus","Barang atau ruang milik kampus yang dipakai BEM; dicatat terpisah dan dikembalikan sesuai ketentuan kampus."],["Daftar Inventaris","Daftar seluruh aset: kode, nama, jumlah, kondisi, lokasi, dan pemegang."],["Opname fisik","Pemeriksaan keberadaan dan kondisi aset dengan mencocokkan fisik terhadap Daftar Inventaris."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Bertanggung jawab akhir atas kelengkapan inventaris dan menandatangani Berita Acara."],["Penanggung jawab inventaris","R","Memutakhirkan daftar, melakukan opname, menyerahkan aset dan kunci, dan memperbarui kode."],["Menteri / Kabiro","R","Menyerahkan aset yang dipegang unit dan mengembalikan aset yang dipinjam."],["Inspektur Jenderal","C","Mengamati opname dan memeriksa kesesuaian daftar dengan fisik."],["Penanggung jawab inventaris baru","R","Menerima, memeriksa, dan menetapkan Daftar Inventaris awal kabinet baru."],["Presiden dan KAUR ORMAWA","I","Menerima laporan; KAUR ORMAWA untuk aset pinjaman kampus."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Inventaris terakhir dan kode inventaris (SOP-AST-001 dan SOP-AST-002).","Catatan peminjaman aset (SOP-AST-003).","Catatan aset rusak atau hilang.","Daftar aset pinjaman kampus."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pemutakhiran daftar: Memutakhirkan Daftar Inventaris dan memisahkan aset BEM dari aset pinjaman kampus.","Penanggung jawab inventaris","Daftar terakhir","Draf Daftar Inventaris","H-30"],["2","Opname fisik: Memeriksa keberadaan, kondisi, lokasi, dan pemegang setiap aset; mendokumentasikan dengan foto.","Penanggung jawab inventaris; Irjen","Daftar, aset","Berita Acara Opname","H-21"],["3","Penelusuran: Menarik aset yang sedang dipinjam dan menelusuri aset hilang atau rusak (SOP-AST-007).","Penanggung jawab; Menteri / Kabiro","Catatan peminjaman","Daftar penyesuaian","H-14"],["4","Penyelesaian: Memperbaiki aset yang layak diperbaiki dan mengusulkan penghapusan sesuai aturan (SOP-AST- 012); tidak ada penghapusan tanpa persetujuan berwenang.","Penanggung jawab","Daftar penyesuaian","Daftar final","H-10"],["5","Verifikasi: Mencocokkan Daftar Inventaris final dengan fisik dan Berita Acara Opname.","Irjen","Daftar final","Catatan verifikasi","H-7"],["6","Persetujuan: Menyetujui penyerahan inventaris.","Presiden","Daftar final, catatan Irjen","Persetujuan tertulis","2 hari kerja"],["7","Serah terima: Menyerahkan aset, ruang sekretariat, dan kunci serta menandatangani Berita Acara Serah Terima Inventaris.","Sekjen lama dan baru","Daftar final","BASTI","Hari-H"],["8","Pemeriksaan penerima: Memeriksa aset diterima, mencatat keberatan, dan menetapkan Daftar Inventaris awal.","Penanggung jawab baru","BASTI","Daftar awal ditetapkan","5 hari kerja setelah Hari-H"],["9","Pengamanan dan pembaruan: Memperbarui pemegang dan kode, mengganti kunci atau akses ruang bila perlu, dan mengarsipkan.","Sekjen baru","BASTI","Daftar dan akses diperbarui","7 hari kerja setelah Hari-H"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Opname fisik selesai paling lambat H-21 dan daftar final paling lambat H-10. Berita Acara Serah Terima Inventaris ditandatangani pada Hari-H. Hasil akhir: BASTI beserta Daftar Inventaris final dan Berita Acara Opname."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Aset hilang: dicatat pada Berita Acara, ditelusuri 5 hari kerja, dan diproses SOP-AST-007; dugaan penyalahgunaan dialihkan ke SOP-RSK-007.","Aset pinjaman kampus rusak atau hilang: dilaporkan kepada KAUR ORMAWA atau unit kampus terkait.","Aset dipinjam pihak luar belum kembali: dikirimi surat penagihan, dicatat sebagai piutang aset, dan diserahkan sebagai pekerjaan berjalan.","Atribut atau lambang yang tidak disahkan: tidak dicatat sebagai aset sah dan dilaporkan kepada Presiden (AD Pasal 18 ayat 2).","Penanggung jawab berhalangan: Presiden menunjuk pelaksana secara tertulis (SOP-GOV-008)."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% aset pada Daftar Inventaris diperiksa fisik.","Aset hilang atau rusak memiliki catatan dan tindak lanjut.","BASTI ditandatangani pada Hari-H.","Tidak ada aset yang dibawa pengurus lama setelah Hari-H."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Inventaris final.","Berita Acara Opname dan dokumentasi foto.","Catatan verifikasi Irjen.","BASTI.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Transisi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Penanggung jawab inventaris memeriksa Daftar Inventaris setiap bulan; Irjen menilai kesesuaian daftar dan fisik pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Mutakhirkan daftar → Opname fisik → Penelusuran → Penyelesaian → Verifikasi Irjen → Persetujuan Presiden → Serah terima BASTI → Pemeriksaan penerima → Pengamanan dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Inventaris","Kode; nama aset; jumlah; kondisi; lokasi; pemegang; asal (BEM atau kampus); keterangan."],["Berita Acara Opname","Tanggal; pemeriksa; aset ditemukan, rusak, atau hilang; foto; tanda tangan."],["Berita Acara Serah Terima Inventaris","Para pihak; daftar aset; kondisi; kunci dan akses; catatan; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Daftar Inventaris memisahkan aset BEM dan aset pinjaman kampus.","☐ Ya ☐ Tidak"],["2","Seluruh aset telah diperiksa fisik dan didokumentasikan.","☐ Ya ☐ Tidak"],["3","Aset dipinjam, rusak, atau hilang telah ditindaklanjuti.","☐ Ya ☐ Tidak"],["4","Kunci dan akses ruang sekretariat telah diserahkan.","☐ Ya ☐ Tidak"],["5","BASTI ditandatangani dan tercatat pada Register Dokumen.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; penanggung jawab inventaris lama dan baru; seluruh Menteri dan Kepala Biro. Salinan diberikan kepada KAUR ORMAWA untuk aset pinjaman kampus."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-TRN-006","g":"Transisi dan Keberlanjutan Kabinet","t":"Serah Terima Akun dan Akses Digital","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[436,439],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur serah terima kendali atas akun dan akses digital resmi BEM (surel, media sosial, penyimpanan dan repositori, grup koordinasi, dan aplikasi) secara aman, sehingga akun milik organisasi tidak tertinggal pada pribadi, kata sandi diganti, akses lama dicabut, dan setiap perubahan tercatat."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh akun dan akses digital yang memakai nama BEM atau menyimpan dokumen organisasi. SOP ini tidak mengatur penggunaan akun harian (SOP-KOM-013) maupun penanganan kebocoran data (SOP- RSK-009), tetapi menjadi acuan ketika kedua SOP tersebut disusun."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (2) (pengelolaan transparan dan akuntabel).","AD Pasal 18 ayat (1) dan (2) (lambang BEM yang disahkan STDIIS).","ART Pasal 2 huruf b (hak atas penggunaan nama, lambang, dan identitas resmi organisasi).","ART Pasal 11 huruf g dan k (larangan mencemarkan nama baik dan memakai fasilitas atau nama organisasi untuk kepentingan pribadi).","Pedoman Penyusunan SOP, Bagian I (dokumen final disimpan di repositori resmi, bukan hanya di perangkat atau akun pribadi; perlindungan data sejak awal)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Akun resmi","Akun atau akses yang dipakai atas nama BEM atau untuk menyimpan dokumen organisasi."],["Daftar Akun dan Akses","Daftar seluruh akun: platform, pemilik terdaftar, pengelola, surel dan nomor pemulihan, status verifikasi dua langkah, dan tingkat akses; berklasifikasi rahasia."],["Verifikasi dua langkah","Lapisan pengamanan tambahan selain kata sandi."],["Rotasi kredensial","Penggantian kata sandi, kode pemulihan, dan sesi login oleh penerima."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap akun resmi memiliki sekurang-kurangnya dua pengelola tercatat (utama dan cadangan).","Kata sandi tidak disampaikan melalui grup percakapan atau ditulis pada berita acara; disampaikan melalui pengelola kata sandi bersama atau cara aman yang ditetapkan Sekjen.","Surel dan nomor pemulihan harus milik organisasi atau pengurus aktif; penerima mengaktifkan verifikasi dua langkah pada perangkatnya sendiri.","Akses pengelola lama dicabut paling lambat 1 hari kerja setelah rotasi kredensial (usulan).","Daftar Akun dan Akses diklasifikasikan rahasia dan hanya dipegang pejabat berwenang (SOP-ADM- 020).","Akun milik kampus mengikuti prosedur kampus."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Bertanggung jawab akhir atas seluruh pengalihan akun dan menandatangani Berita Acara."],["Pengelola akun (Biro Desain Komunikasi Visual dan unit lain)","R","Mendata akun, membersihkan akses, melakukan serah terima, dan menguji fungsi."],["Penerima / pengelola baru","R","Mengganti kredensial, mengaktifkan verifikasi dua langkah, dan memperbarui data pemulihan."],["Inspektur Jenderal","C","Memeriksa kesesuaian Daftar Akun dan memastikan tidak ada akun pribadi dipakai sebagai akun resmi."],["Presiden","I","Menerima laporan penyelesaian; menerbitkan Surat Mandat bila pemulihan akun memerlukannya."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Akun dan Akses yang berjalan.","Daftar pengelola lama dan baru.","Ketentuan kampus untuk akun milik institusi.","Pedoman pengamanan data dan akses (SOP-RSK-008)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Inventarisasi akun: Menyusun Daftar Akun dan Akses lengkap dengan pemilik terdaftar, pengelola, dan data pemulihan.","Sekjen; pengelola akun","Akun yang berjalan","Daftar Akun dan Akses","H-21"],["2","Pembersihan akses: Mencabut akses pengelola yang tidak lagi menjabat dan memastikan data pemulihan milik organisasi atau pengurus aktif.","Pengelola akun","Daftar Akun","Akses bersih","H-14"],["3","Pemeriksaan: Memeriksa Daftar Akun dan memastikan tidak ada akun resmi yang hanya dikuasai satu orang pribadi.","Irjen","Daftar Akun","Catatan pemeriksaan","H-10"],["4","Persiapan penerima: Menyiapkan perangkat dan surel penerima serta verifikasi dua langkah milik penerima.","Pengelola baru","Daftar pengelola baru","Penerima siap","H-7"],["5","Serah terima akun: Pengelola lama dan baru login bersama; penerima mengganti kata sandi, verifikasi dua langkah, dan data pemulihan; Berita Acara ditandatangani tanpa mencantumkan kata sandi.","Pengelola lama dan baru; Sekjen","Daftar Akun","BA Serah Terima Akun","Hari-H sampai H+1"],["6","Pencabutan akses lama: Mengeluarkan sesi dan perangkat lama, mencabut token dan aplikasi pihak ketiga yang tidak diperlukan.","Pengelola baru","BA","Akses lama tidak berlaku","1 hari kerja setelah rotasi"],["7","Pengujian: Menguji fungsi akun: surel masuk dan keluar, unggah dan akses folder, penjadwalan publikasi, dan keanggotaan grup.","Pengelola baru","Akun","Hasil pengujian","3 hari kerja"],["8","Pembaruan data dan arsip: Memperbarui Daftar Akun dan Akses, mengumumkan pengelola baru melalui kanal resmi, dan mengarsipkan.","Sekjen","Hasil pengujian","Daftar diperbarui, arsip","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Daftar Akun dan Akses lengkap paling lambat H-21. Rotasi kredensial dilakukan pada Hari-H sampai H+1 dan akses lama dicabut paling lambat 1 hari kerja setelahnya. Hasil akhir: Daftar Akun dan Akses terbaru dan Berita Acara Serah Terima Akun."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pemilik lama tidak dapat dihubungi atau lupa kredensial: gunakan prosedur pemulihan platform dengan Surat Mandat Presiden dan bukti kepemilikan organisasi.","Akun terdaftar atas nama pribadi: dialihkan kepemilikannya bila platform mengizinkan; bila tidak, pemilik lama membuat pernyataan tertulis bahwa akun milik organisasi dan menyerahkan kendali.","Akun tidak diserahkan: Irjen melapor kepada Presiden; tindak lanjut mengikuti ART Pasal 11 huruf k dan Pasal 12.","Akses tidak sah atau kebocoran terdeteksi: ganti seluruh kredensial segera dan alihkan ke SOP-RSK- 009.","Akun milik kampus: serah terima mengikuti prosedur kampus; BEM hanya melaporkan perubahan pengelola."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% akun resmi tercatat pada Daftar Akun dan Akses.","Seluruh akun memiliki sekurang-kurangnya dua pengelola dan verifikasi dua langkah aktif.","Kata sandi dan sesi pengelola lama tidak berlaku paling lambat 1 hari kerja setelah serah terima.","Tidak ada akun resmi yang dikuasai satu orang pribadi tanpa cadangan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Akun dan Akses terbaru (rahasia).","Catatan pemeriksaan Irjen.","Berita Acara Serah Terima Akun.","Hasil pengujian dan pengumuman pengelola baru.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Transisi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal meninjau Daftar Akun dan Akses setiap triwulan dan saat pergantian pengelola; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Inventarisasi akun → Pembersihan akses → Pemeriksaan Irjen → Persiapan penerima → Serah terima dan rotasi kredensial → Pencabutan akses lama → Pengujian → Pembaruan data dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Akun dan Akses","Akun; platform; pemilik terdaftar; pengelola utama dan cadangan; surel dan nomor pemulihan; verifikasi dua langkah; tanggal rotasi terakhir."],["Berita Acara Serah Terima Akun","Para pihak; daftar akun; tanggal rotasi; catatan; tanda tangan (tanpa kata sandi)."],["Pernyataan Kepemilikan Akun","Nama akun; pernyataan akun milik organisasi; pemilik terdaftar; tanggal; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh akun resmi tercatat pada Daftar Akun dan Akses.","☐ Ya ☐ Tidak"],["2","Setiap akun memiliki pengelola utama dan cadangan.","☐ Ya ☐ Tidak"],["3","Data pemulihan milik organisasi atau pengurus aktif.","☐ Ya ☐ Tidak"],["4","Kata sandi dan sesi pengelola lama telah dicabut.","☐ Ya ☐ Tidak"],["5","Berita Acara tidak memuat kata sandi dan telah diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Sekretaris Jenderal; Inspektur Jenderal; pengelola akun lama dan baru. Daftar Akun dan Akses tidak disebarkan secara umum dan hanya diberikan kepada pejabat yang berwenang."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-TRN-007","g":"Transisi dan Keberlanjutan Kabinet","t":"Pendataan Kerja Sama yang Masih Berjalan","o":"Menteri Hubungan Eksternal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Hubungan Eksternal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[440,443],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pendataan, pemeriksaan, dan penyerahan seluruh kerja sama, kemitraan, sponsorship, dan komitmen kepada pihak eksternal yang masih berjalan, sehingga hak dan kewajiban organisasi tidak terputus, tidak ada kewajiban yang tersembunyi, dan hubungan dengan mitra tetap terjaga."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk kerja sama dengan institusi pemerintah, swasta, ORMAWA, dan organisasi mahasiswa lain, sponsor, mitra kegiatan, dan narasumber, baik tertulis maupun lisan. SOP ini tidak mengatur pengajuan kerja sama baru (SOP-HKE-005 dan SOP-HKE-006) maupun penerimaan sponsor (SOP-HKE-007 dan SOP-HKE- 008)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf e (kerja sama yang halal dan tidak mengikat dengan persetujuan Ketua STDIIS).","ART Bab III (Tugas) huruf d (koordinasi dan kerja sama antar ORMAWA dan pihak eksternal).","ART Pasal 3 (Kewajiban) huruf d (menjaga nama baik STDIIS).","AD Pasal 15 ayat (1) huruf b dan ayat (2) (sponsor tidak menimbulkan kewajiban melampaui satu periode; bebas riba, gharar, dan maysir).","AD Pasal 10 (masa jabatan satu periode kepengurusan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kerja sama","Kesepakatan tertulis atau lisan dengan pihak eksternal yang menimbulkan hak atau kewajiban bagi BEM."],["Lembar Status Kerja Sama","Rangkuman satu kerja sama: mitra, dasar dokumen, masa berlaku, hak dan kewajiban, kontak, dan status."],["Kewajiban lintas periode","Kewajiban yang berlaku setelah Hari-H, termasuk pembayaran, publikasi, atau kegiatan yang dijanjikan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Status kerja sama diklasifikasikan: selesai, berjalan dan dapat dilanjutkan, berjalan dengan kewajiban tersisa, atau perlu keputusan kabinet baru.","Pada masa peralihan kabinet lama tidak memperpanjang atau membuat kerja sama baru yang mengikat melampaui periode tanpa konsultasi dengan Presiden terpilih dan persetujuan Ketua STDIIS.","Menteri lama memperkenalkan penerus kepada mitra melalui surat atau pertemuan.","Data kontak mitra dipakai hanya untuk keperluan organisasi.","Kerja sama yang tidak memiliki dokumen resmi dicatat apa adanya dan tidak dilanjutkan sebelum diformalkan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Hubungan Eksternal (lama)","A","Bertanggung jawab akhir atas kelengkapan data dan penyerahan kerja sama."],["Menteri / Kabiro","R","Melaporkan kerja sama yang dikelola unit masing-masing."],["Sekretaris Jenderal","R","Menyediakan dokumen kerja sama dari arsip dan mencatat Berita Acara."],["Inspektur Jenderal","C","Memeriksa dokumen dasar dan kesesuaian dengan AD/ART dan syariat."],["Presiden","C","Memutuskan kerja sama yang ditutup atau diteruskan dan menyetujui pemberitahuan kepada mitra."],["Menteri Hubungan Eksternal (baru)","R","Menerima data, menghubungi mitra, dan memutuskan tindak lanjut bersama Presiden baru."],["Ketua STDIIS / KAUR ORMAWA","I","Menerima laporan kerja sama yang memerlukan persetujuan atau perpanjangan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Dokumen perjanjian, surat persetujuan Ketua STDIIS, dan korespondensi mitra.","Register Kerja Sama yang dipelihara sepanjang periode.","Laporan pertemuan eksternal (SOP-HKE-012).","Daftar kewajiban keuangan (SOP-TRN-004)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pemeliharaan register: Memperbarui Register Kerja Sama setiap ada kerja sama baru, perubahan, atau berakhirnya kerja sama sepanjang periode.","Menlu","Dokumen kerja sama","Register terbaru","Berkelanjutan; ditinjau saat evaluasi tengah periode"],["2","Pendataan akhir: Menghimpun seluruh kerja sama dari unit dan mengisi Lembar Status Kerja Sama.","Menlu; Menteri / Kabiro","Register, laporan unit","Lembar Status","H-30"],["3","Pemeriksaan dokumen: Memeriksa dokumen dasar, masa berlaku, persetujuan Ketua STDIIS, kewajiban, dan kesesuaian syariat.","Irjen; Sekjen","Lembar Status, dokumen","Catatan pemeriksaan","H-21"],["4","Penilaian: Mengklasifikasikan status, menandai kewajiban lintas periode, dan menyusun rekomendasi lanjut, akhiri, atau negosiasi ulang.","Menlu","Catatan pemeriksaan","Daftar rekomendasi","H-14"],["5","Keputusan: Membahas rekomendasi pada Rapat Pimpinan (SOP-GOV-005) dan memutuskan tindakan sebelum Hari- H.","Presiden dan pimpinan","Daftar rekomendasi","Keputusan tercatat","H-10"],["6","Pemberitahuan mitra: Mengirim surat pergantian pengurus dan kontak penerus; mengatur perkenalan bila perlu.","Menlu lama; Sekjen","Keputusan","Surat terkirim","H-7 sampai H+14"],["7","Serah terima: Menyerahkan Daftar Serah Terima Kerja Sama beserta dokumen asli atau salinan; menandatangani Berita Acara.","Menlu lama dan baru","Daftar, dokumen","BA Serah Terima Kerja Sama","Hari-H"],["8","Tindak lanjut: Memutuskan kelanjutan setiap kerja sama; perubahan atau perpanjangan diajukan sesuai ART Pasal 2 huruf e.","Presiden baru; Menlu baru","BA, daftar","Keputusan lanjutan","14 hari kerja setelah Hari-H"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pendataan akhir selesai paling lambat H-30 dan keputusan atas kerja sama dibuat paling lambat H-10. Berita Acara Serah Terima Kerja Sama ditandatangani pada Hari-H. Hasil akhir: Daftar Serah Terima Kerja Sama dan Berita Acara."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kerja sama tanpa dokumen resmi: dicatat, dikonfirmasi tertulis kepada mitra, dan tidak dilanjutkan sebelum diformalkan.","Kewajiban lintas periode ditemukan: dilaporkan kepada Presiden dan dikonsultasikan kepada KAUR ORMAWA atau Ketua STDIIS.","Kerja sama diduga bertentangan dengan syariat atau AD/ART: dihentikan sementara dan dikonsultasikan kepada Pembina.","Mitra keberatan atas pergantian pengurus atau tidak merespons: dicatat dan diserahkan sebagai pekerjaan berjalan.","Menteri Hubungan Eksternal berhalangan: Presiden menunjuk pengganti secara tertulis (SOP-GOV-008)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kerja sama berjalan tercatat pada Register Kerja Sama.","100% kerja sama memiliki status dan rekomendasi pada hari serah terima.","Tidak ada kewajiban lintas periode yang tidak dilaporkan.","Surat pergantian pengurus terkirim kepada seluruh mitra aktif paling lambat H+14."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Kerja Sama dan Lembar Status Kerja Sama.","Catatan pemeriksaan Irjen dan keputusan Rapat Pimpinan.","Daftar Serah Terima Kerja Sama dan Berita Acara.","Surat pergantian pengurus kepada mitra.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Transisi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri Hubungan Eksternal meninjau Register Kerja Sama setiap bulan sepanjang periode; Irjen menilai kelengkapan dokumen dasar pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pemeliharaan register → Pendataan akhir → Pemeriksaan dokumen → Penilaian → Keputusan Rapat Pimpinan → Pemberitahuan mitra → Serah terima → Tindak lanjut kabinet baru → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Status Kerja Sama","Mitra; jenis; dasar dokumen; masa berlaku; hak dan kewajiban; kontak; status; rekomendasi."],["Daftar Serah Terima Kerja Sama","Nomor; mitra; status; kewajiban tersisa; dokumen; penanggung jawab; tindak lanjut."],["Surat Pergantian Pengurus kepada Mitra","Pengirim; penerima; pengurus baru dan kontak; terima kasih; tanggal; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh kerja sama berjalan tercatat dengan dokumen dasar.","☐ Ya ☐ Tidak"],["2","Kewajiban lintas periode ditandai dan dilaporkan.","☐ Ya ☐ Tidak"],["3","Persetujuan Ketua STDIIS tersedia untuk kerja sama yang memerlukannya.","☐ Ya ☐ Tidak"],["4","Setiap kerja sama memiliki status dan rekomendasi.","☐ Ya ☐ Tidak"],["5","Surat pergantian pengurus telah dikirim kepada mitra aktif.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden lama dan baru; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Hubungan Eksternal lama dan baru; arsip Biro Kesekretariatan. Salinan diberikan kepada Ketua STDIIS atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-TRN-008","g":"Transisi dan Keberlanjutan Kabinet","t":"Pendataan Program Kerja yang Belum Selesai","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[444,447],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pendataan status seluruh program kerja (selesai, berjalan, tertunda, dibatalkan) dan penyerahan program yang belum selesai, sehingga pekerjaan tidak terputus, tanggung jawab atas LPJ dan kewajiban jelas, dan kabinet baru memiliki dasar untuk menyusun Rapat Kerja."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh program kerja tahunan hasil RAKER dan kegiatan di luar rencana yang telah berjalan, termasuk kegiatan yang belum menyerahkan LPJ. SOP ini tidak mengatur pembatalan atau penundaan program (SOP-PRO-022) dan evaluasi hasil kegiatan (SOP-PRO-021)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 9 ayat (1) sampai (3), (5), dan (6) (RAKER; hasil RAKER menjadi pedoman satu periode; program wajib mendapat persetujuan Pembina).","ART Pasal 7 ayat (5) huruf b (Mubes menetapkan garis besar program kerja periode mendatang).","ART Pasal 10 ayat (4) (Rapat Koordinasi memonitor pelaksanaan program).","ART Bab III (Tugas) huruf e (anggaran, program tahunan, dan LPJ pada akhir masa jabatan).","AD Pasal 17 ayat (1) (laporan pertanggungjawaban secara berkala)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Register Program Kerja","Daftar seluruh program: penanggung jawab, jadwal, anggaran, status, dan bukti."],["Program belum selesai","Program berstatus berjalan, tertunda, atau selesai tetapi LPJ belum diserahkan."],["Daftar Program Belum Selesai","Dokumen serah terima yang memuat status, sisa anggaran, kewajiban, dan rekomendasi setiap program."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kabinet baru tidak otomatis melanjutkan program; program lanjutan dibahas pada RAKER kabinet baru dan memperoleh persetujuan Pembina sebelum dilaksanakan (ART Pasal 9 ayat 6).","Program yang telah memiliki kewajiban eksternal atau dana yang dicairkan diselesaikan kabinet lama; bila diserahkan, wajib ada penanggung jawab, anggaran, dan berita acara.","LPJ kegiatan yang telah selesai tetap menjadi tanggung jawab panitia dan kabinet lama (SOP-PRO- 020).","Status program didukung bukti: dokumentasi, LPJ, atau catatan keuangan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Wakil Presiden","A","Bertanggung jawab akhir atas kelengkapan dan ketepatan status program serta menyerahkan Daftar Program Belum Selesai."],["Sekretaris Jenderal","R","Menarik data dari Register Program Kerja dan kalender, mengarsipkan."],["Menteri / Kabiro","R","Memperbarui status program unit, menyelesaikan program atau LPJ yang tertunggak, dan menyusun rekomendasi."],["Kepala Biro Keuangan","C","Memberikan sisa anggaran dan kewajiban setiap program."],["Inspektur Jenderal","C","Memverifikasi status program terhadap bukti."],["Presiden","R","Menyetujui Daftar Program Belum Selesai dan memutuskan program yang dihentikan sebelum Hari-H."],["Presiden dan Wapres baru","I","Menerima daftar sebagai bahan RAKER kabinet baru."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Program kerja dan RAB hasil RAKER.","Register Program Kerja dan kalender program.","LPJ dan laporan keuangan kegiatan.","Hasil evaluasi program (SOP-PRO-021)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penarikan status: Menarik data dari Register Program Kerja dan meminta unit memperbarui status setiap program.","Sekjen; Menteri / Kabiro","Register, kalender","Status terbaru","H-30"],["2","Klasifikasi: Mengklasifikasikan program: selesai, selesai belum LPJ, berjalan, tertunda, dan dibatalkan.","Wapres; Menteri / Kabiro","Status terbaru","Daftar terklasifikasi","H-30"],["3","Rincian program lanjutan: Mengisi penanggung jawab, sisa anggaran, kewajiban eksternal, dokumen, dan rekomendasi lanjut atau hentikan.","Menteri / Kabiro; Biro Keuangan","Daftar terklasifikasi","Draf Daftar Program Belum Selesai","H-21"],["4","Penyelesaian: Menyelesaikan program yang dapat diselesaikan dan melengkapi LPJ yang tertunggak.","Menteri / Kabiro","Draf daftar","Program atau LPJ selesai","H-14"],["5","Verifikasi: Mencocokkan status dengan bukti dokumentasi, LPJ, dan keuangan.","Irjen","Draf daftar, bukti","Catatan verifikasi","H-10"],["6","Pembahasan dan persetujuan: Membahas pada rapat kabinet (SOP- GOV-006), lalu Presiden menyetujui daftar final.","Pimpinan dan Eksekutif; Presiden","Daftar, catatan Irjen","Daftar final disetujui","H-7"],["7","Serah terima: Menyerahkan Daftar Program Belum Selesai dan dokumen pendukung kepada pimpinan baru; menjelaskan setiap program.","Wapres lama; Sekjen","Daftar final","BA Serah Terima Program","Hari-H sampai H+7"],["8","Penerimaan dan keputusan: Memasukkan program lanjutan ke bahan RAKER, memutuskan lanjut, ubah, atau hentikan, dan mengajukan persetujuan Pembina.","Presiden dan Wapres baru","BA, daftar","Keputusan RAKER","Pada RAKER kabinet baru (paling lambat 30 hari kerja setelah pelantikan)"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Status program diperbarui paling lambat H-30 dan Daftar Program Belum Selesai disetujui paling lambat H- 7. Penyerahan dilakukan pada Hari-H sampai H+7. Hasil akhir: Daftar Program Belum Selesai beserta Berita Acara Serah Terima Program."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Status program tidak sesuai bukti: dikembalikan kepada unit; status ditetapkan berdasarkan bukti, bukan pernyataan.","Program berjalan memerlukan keputusan sebelum Hari-H: Presiden memutuskan melalui Rapat Pimpinan (SOP-GOV-005) dengan konsultasi kepada Presiden terpilih.","Kewajiban eksternal belum terpenuhi: dicatat sebagai kewajiban lintas periode dan dikoordinasikan dengan SOP-TRN-004 dan SOP-TRN-007.","Program dihentikan atau ditunda: prosesnya mengikuti SOP-PRO-022.","Penanggung jawab program berhalangan: Wapres menunjuk pengganti secara tertulis."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% program pada Register Program Kerja memiliki status dan bukti.","100% program belum selesai memiliki penanggung jawab, sisa anggaran, dan rekomendasi.","Daftar Program Belum Selesai disetujui paling lambat H-7.","Tidak ada LPJ kegiatan yang selesai dan belum memiliki penanggung jawab penyelesaian setelah Hari-H."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Program Kerja terbaru.","Daftar Program Belum Selesai.","Catatan verifikasi Irjen.","Berita Acara Serah Terima Program.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Transisi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden dan Sekretaris Jenderal meninjau Register Program Kerja setiap bulan; Irjen menilai ketepatan status pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Penarikan status → Klasifikasi → Rincian program lanjutan → Penyelesaian → Verifikasi Irjen → Persetujuan Presiden → Serah terima → RAKER kabinet baru → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Register Program Kerja","Program; penanggung jawab; jadwal; anggaran; status; bukti; catatan."],["Daftar Program Belum Selesai","Program; status; sisa anggaran; kewajiban eksternal; dokumen; penanggung jawab; rekomendasi."],["Berita Acara Serah Terima Program","Para pihak; daftar program; catatan; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh program tercatat dengan status dan bukti.","☐ Ya ☐ Tidak"],["2","Program belum selesai memiliki penanggung jawab, sisa anggaran, dan rekomendasi.","☐ Ya ☐ Tidak"],["3","LPJ tertunggak telah dilengkapi atau memiliki penanggung jawab.","☐ Ya ☐ Tidak"],["4","Kewajiban eksternal dicatat dan dikoordinasikan.","☐ Ya ☐ Tidak"],["5","Daftar disetujui Presiden dan diverifikasi Irjen.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden lama dan baru; Wakil Presiden lama dan baru; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro. Salinan diberikan kepada Pembina bila program lanjutan memerlukan persetujuan."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-TRN-009","g":"Transisi dan Keberlanjutan Kabinet","t":"Dokumentasi Evaluasi dan Pembelajaran Kabinet","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[448,451],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penghimpunan, perumusan, dan pendokumentasian evaluasi kinerja dan pembelajaran kabinet (praktik baik, masalah berulang, dan rekomendasi) agar menjadi pengetahuan organisasi yang dapat dipakai kabinet berikutnya."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk temuan pengawasan, hasil evaluasi program (SOP-PRO-021), evaluasi tengah periode (SOP- MONEV-011), masalah berulang (SOP-MONEV-009), tindakan korektif (SOP-MONEV-010), dan umpan balik pengurus, mahasiswa, serta mitra. SOP ini tidak menggantikan Laporan Akhir (SOP-TRN-001); Catatan Pembelajaran menjadi lampiran dan dasar rekomendasi."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 12 ayat (3) sampai (6) dan Pasal 13 ayat (5) dan (6) (pengawasan dan evaluasi Irjen; hasil pengawasan disampaikan melalui forum resmi BEM).","ART Pasal 7 ayat (5) huruf c (Mubes mengevaluasi kinerja organisasi).","AD Pasal 14 huruf d dan ART Pasal 10 (Rapat Evaluasi dan Rapat Koordinasi).","AD Pasal 5 ayat (1) dan (4) (organisasi sebagai wadah pengembangan diri dan media pembelajaran tanggung jawab)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Catatan Pembelajaran Kabinet","Dokumen ringkas yang memuat praktik baik, masalah berulang beserta akar masalah, dan rekomendasi bagi kabinet berikutnya."],["Register Temuan dan Pembelajaran","Catatan yang dipelihara sepanjang periode: temuan, kejadian, keputusan, dan perbaikan."],["Akar masalah","Penyebab mendasar suatu masalah yang berulang pada proses, aturan, atau sumber daya."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Evaluasi diarahkan pada proses dan sistem, bukan menyalahkan individu; penyampaian dilakukan dengan etika yang baik.","Data pribadi, identitas pelapor, dan kasus pengaduan disamarkan atau dipisahkan (SOP-ADV-011, SOP-SDM-018).","Rekomendasi dirumuskan konkret: tindakan, penanggung jawab usulan, dan prioritas.","Catatan Pembelajaran diserahkan kepada kabinet baru dan menjadi masukan RAKER berikutnya.","Irjen tidak memeriksa dokumen unit yang dipimpinnya sendiri; bagian tersebut diperiksa Wakil Presiden."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Inspektur Jenderal","A","Bertanggung jawab akhir atas isi Catatan Pembelajaran; menghimpun dan merumuskannya."],["Wakil Presiden","R","Memimpin Rapat Evaluasi bersama Irjen dan memeriksa bagian yang menyangkut Inspektorat."],["Sekretaris Jenderal","R","Menyediakan notulen, arsip keputusan, dan mengarsipkan dokumen."],["Menteri / Kabiro","R","Menyampaikan evaluasi unit dan memberi umpan balik."],["Presiden","C","Menelaah dan mengesahkan Catatan Pembelajaran melalui forum resmi BEM."],["Presiden dan Irjen baru","I","Menerima dan memanfaatkan sebagai bahan RAKER dan pengawasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Register Temuan dan Pembelajaran.","Hasil evaluasi tengah periode dan evaluasi program.","Daftar masalah berulang dan tindakan korektif.","Umpan balik pengurus, mahasiswa, dan mitra."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pemeliharaan register: Mencatat temuan, masalah berulang, dan perbaikan sepanjang periode.","Irjen","Laporan pengawasan, notulen","Register terbaru","Berkelanjutan"],["2","Umpan balik akhir: Mengumpulkan umpan balik tertulis dari pengurus, mahasiswa, dan mitra; dapat tanpa nama bila perlu.","Irjen; Menteri / Kabiro","Formulir umpan balik","Rekap umpan balik","H-30"],["3","Rapat Evaluasi: Membahas capaian, hambatan, dan akar masalah bersama pimpinan dan Eksekutif.","Wapres; Irjen","Register, rekap","Catatan hasil rapat","H-21"],["4","Penyusunan: Menyusun Catatan Pembelajaran: ringkasan, praktik baik, masalah berulang dan akar masalah, rekomendasi prioritas, dan status tindak lanjut.","Irjen","Catatan hasil rapat","Draf Catatan Pembelajaran","H-14"],["5","Penelaahan dan pengesahan: Menelaah dan mengesahkan melalui forum resmi BEM (ART Pasal 13 ayat 6).","Presiden; Wapres","Draf","Catatan Pembelajaran disahkan","H-7"],["6","Penyampaian: Menyerahkan kepada kabinet baru pada orientasi (SOP-TRN-010) dan melampirkan pada Laporan Akhir untuk BPM.","Irjen; Sekjen","Catatan disahkan","Tanda terima","Hari-H sampai H+7"],["7","Pengarsipan: Menyimpan dokumen dan Register pada repositori resmi.","Sekjen","Dokumen","Arsip dan Register Dokumen","H+7"],["8","Pemanfaatan: Memasukkan rekomendasi prioritas ke RAKER dan memantau tindak lanjutnya; meninjau kembali pada evaluasi tengah periode kabinet baru.","Presiden dan Irjen baru","Catatan Pembelajaran","Rencana tindak lanjut","Pada RAKER kabinet baru"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Umpan balik terkumpul paling lambat H-30 dan Catatan Pembelajaran disahkan paling lambat H-7. Penyerahan kepada kabinet baru dilakukan paling lambat H+7. Hasil akhir: Catatan Pembelajaran Kabinet dan Register Temuan dan Pembelajaran."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Catatan memuat data pribadi atau pengaduan: dipisahkan sebagai lampiran terbatas; ringkasan tanpa identitas.","Perbedaan pendapat yang tajam: dicatat sebagai pandangan berbeda; bila memerlukan keputusan, ikuti SOP-GOV-010.","Dugaan pelanggaran ditemukan saat evaluasi: dialihkan ke SOP-SDM-013 atau SOP-RSK-007 dan tidak diputuskan dalam forum evaluasi.","Irjen berhalangan: Wakil Presiden menunjuk pengganti sementara secara tertulis (SOP-GOV-008)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Catatan Pembelajaran disahkan paling lambat H-7.","100% masalah berulang memiliki akar masalah dan rekomendasi.","Rekomendasi prioritas dibahas pada RAKER kabinet baru.","Register Temuan dan Pembelajaran diperbarui sepanjang periode."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Catatan Pembelajaran Kabinet.","Register Temuan dan Pembelajaran.","Rekap umpan balik.","Tanda terima penyerahan.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Transisi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen meninjau Register Temuan dan Pembelajaran setiap bulan; Wakil Presiden memeriksa kepatuhan Inspektorat pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pemeliharaan register → Umpan balik akhir → Rapat Evaluasi → Penyusunan Catatan Pembelajaran → Pengesahan Presiden → Penyampaian ke kabinet baru → Pengarsipan → Pemanfaatan pada RAKER → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Umpan Balik","Pengisi (opsional); unit atau mitra; hal yang berjalan baik; hambatan; saran."],["Templat Catatan Pembelajaran Kabinet","Ringkasan; praktik baik; masalah berulang dan akar masalah; rekomendasi prioritas; status tindak lanjut."],["Register Temuan dan Pembelajaran","Tanggal; temuan atau kejadian; unit; tindakan; status; pembelajaran."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Register Temuan dan Pembelajaran dipelihara sepanjang periode.","☐ Ya ☐ Tidak"],["2","Umpan balik dari pengurus, mahasiswa, dan mitra telah dikumpulkan.","☐ Ya ☐ Tidak"],["3","Setiap masalah berulang memiliki akar masalah dan rekomendasi.","☐ Ya ☐ Tidak"],["4","Data pribadi dan pengaduan telah disamarkan atau dipisahkan.","☐ Ya ☐ Tidak"],["5","Catatan disahkan, diserahkan kepada kabinet baru, dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden lama dan baru; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal lama dan baru; seluruh Menteri dan Kepala Biro; BPM (sebagai lampiran Laporan Akhir); arsip Biro Kesekretariatan."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-TRN-010","g":"Transisi dan Keberlanjutan Kabinet","t":"Orientasi dan Transfer Pengetahuan kepada Pengurus Baru","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[452,455],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur orientasi dan transfer pengetahuan dari pengurus lama kepada pengurus baru, sehingga pengurus baru memahami AD/ART, struktur, SOP, program, kerja sama, dan praktik kerja unitnya sejak awal masa jabatan dan pengetahuan organisasi tidak hilang bersama pergantian orang."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus kabinet baru: Presiden, Wakil Presiden, Sekretaris Jenderal, Menteri, Kepala Biro, Inspektur Jenderal, dan staf. SOP ini selaras dengan SOP-SDM-003 (pelantikan dan orientasi pengurus baru) dan SOP-SDM-016 (pengembangan kapasitas) dan menekankan transfer pengetahuan dari kabinet lama; dapat digabung dengan SOP-SDM-003 bila disusun."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 5 ayat (1), (4), dan (5) (wadah pengembangan diri, media pembelajaran tanggung jawab, dan dukungan terhadap visi dan misi STDIIS).","AD Pasal 11 ayat (2) huruf b dan c (pengangkatan Menteri dan Kabiro serta seleksi anggota).","ART Pasal 5 ayat (4) (pengurus dilantik Presiden terpilih).","ART Pasal 6 (syarat umum kepengurusan).","ART Pasal 9 ayat (2) dan (3) (RAKER pada awal periode: pembagian tugas dan program kerja).","ART Pasal 11 dan Pasal 12 (larangan dan sanksi) sebagai materi wajib orientasi."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Orientasi umum","Pengenalan seluruh pengurus baru terhadap AD/ART, struktur, etika, larangan dan sanksi, SOP, dan kanal kerja."],["Transfer pengetahuan unit","Penyerahan pengetahuan praktis dari pejabat lama kepada pejabat baru: pekerjaan berjalan, alur kerja, templat, kontak, dan kendala."],["Panduan Transisi","Kumpulan bahan tertulis orientasi yang diperbarui setiap periode."],["Masa pendampingan","Periode kabinet lama dapat dihubungi untuk konsultasi; tidak memiliki kewenangan memutuskan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Orientasi dua tingkat: umum untuk seluruh pengurus, dan unit antara pejabat lama dan baru.","Bahan wajib tertulis dan disimpan pada repositori resmi.","Masa pendampingan 30 hari setelah Hari-H (usulan); pejabat lama bersifat konsultatif dan tidak mengambil keputusan.","Kehadiran wajib; pengurus yang tidak hadir mengikuti sesi susulan paling lambat 7 hari kerja.","Materi tentang keamanan data, kerahasiaan, dan anti perundungan wajib diberikan (SOP-SDM-017, SOP-SDM-018)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri PSDM","A","Bertanggung jawab akhir atas rancangan, pelaksanaan, dan evaluasi orientasi."],["Sekretaris Jenderal","R","Menyiapkan paket bahan (AD/ART, SOP, struktur, kalender, Laporan Akhir) dan mengarsipkan."],["Menteri / Kabiro (lama)","R","Menyusun Panduan Unit dan mentransfer pengetahuan kepada penerus."],["Menteri / Kabiro (baru)","R","Mengikuti orientasi, mempelajari bahan, dan menyusun rencana kerja awal unit."],["Presiden dan Wakil Presiden baru","C","Menetapkan prioritas materi dan membuka orientasi umum."],["Inspektur Jenderal","C","Menyampaikan Catatan Pembelajaran (SOP-TRN-009) dan etika dan pengawasan."],["KAUR ORMAWA / Pembina","I","Menerima jadwal bila terlibat sebagai narasumber."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["AD/ART dan Pedoman Penyusunan SOP.","Laporan Akhir dan Catatan Pembelajaran Kabinet.","Daftar Program Belum Selesai dan Daftar Serah Terima Kerja Sama.","Struktur dan susunan kabinet baru."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Rancangan orientasi: Menyusun peserta, materi, jadwal, pemateri, dan bahan dengan memanfaatkan Catatan Pembelajaran.","Menteri PSDM; Sekjen","Susunan kabinet, Catatan Pembelajaran","Rancangan Orientasi","H-30"],["2","Penyiapan paket: Menyiapkan Paket Bahan Orientasi dan Panduan Unit setiap kementerian atau biro.","Sekjen; Menteri / Kabiro lama","Dokumen kabinet, pengalaman unit","Paket Bahan; Panduan Unit","H-21"],["3","Koordinasi jadwal: Mengonfirmasi jadwal dan narasumber, termasuk kampus bila terlibat.","Menteri PSDM; Sekjen","Rancangan","Jadwal terkonfirmasi","H-14"],["4","Orientasi umum: Melaksanakan sesi untuk seluruh pengurus baru secara luring atau daring.","Menteri PSDM; Pimpinan","Paket Bahan","Presensi, bahan terbagi","Hari-H sampai H+7"],["5","Transfer pengetahuan unit: Menyelenggarakan sesi pejabat lama dan baru: pekerjaan berjalan, mitra, templat, kendala, dan simulasi tugas utama.","Menteri / Kabiro lama dan baru","Panduan Unit","Formulir Transfer Pengetahuan Unit","Hari-H sampai H+14"],["6","Pendampingan: Menyediakan kanal konsultasi dengan pejabat lama selama masa pendampingan.","Menteri / Kabiro lama","Kanal resmi","Catatan konsultasi","H+30"],["7","Evaluasi: Mengukur pemahaman dengan checklist atau uji singkat, mengumpulkan umpan balik, dan menjadwalkan sesi susulan.","Menteri PSDM","Presensi, umpan balik","Laporan Orientasi","H+21"],["8","Pembaruan panduan: Memperbarui Panduan Transisi berdasarkan Laporan Orientasi dan mengarsipkannya.","Menteri PSDM; Sekjen","Laporan Orientasi","Panduan Transisi terbaru","H+30"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Rancangan siap paling lambat H-30. Orientasi umum dan transfer pengetahuan unit selesai paling lambat H+14, masa pendampingan 30 hari, dan Laporan Orientasi selesai paling lambat H+21. Hasil akhir: Laporan Orientasi dan Panduan Transisi terbaru."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengurus tidak hadir: mengikuti sesi susulan paling lambat 7 hari kerja dan dicatat pada presensi.","Pejabat lama tidak dapat hadir: Panduan Unit tertulis tetap diserahkan dan sesi dilakukan secara daring atau melalui perwakilan unit.","Pengurus baru belum memenuhi syarat kepengurusan: ditindaklanjuti sesuai ART Pasal 6 dan SOP- SDM-001.","Pejabat lama menolak mentransfer pengetahuan: Menteri PSDM melapor kepada Wakil Presiden; eskalasi mengikuti SOP-SDM-013.","Menteri PSDM berhalangan: Presiden menunjuk pengganti secara tertulis (SOP-GOV-008)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pengurus baru mengikuti orientasi umum atau sesi susulan paling lambat H+21.","100% unit memiliki Formulir Transfer Pengetahuan Unit yang ditandatangani.","Seluruh pengurus baru lulus uji pemahaman AD/ART dan SOP inti.","Panduan Transisi diperbarui setiap periode."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Rancangan Orientasi dan Paket Bahan Orientasi.","Panduan Unit dan Formulir Transfer Pengetahuan Unit.","Presensi dan hasil evaluasi pemahaman.","Laporan Orientasi.","Panduan Transisi terbaru dan entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Transisi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri PSDM memeriksa kelengkapan paket dan kehadiran; Irjen menilai kepatuhan pada evaluasi berkala dan evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Rancangan orientasi → Penyiapan paket → Koordinasi jadwal → Orientasi umum → Transfer pengetahuan unit → Pendampingan → Evaluasi → Pembaruan Panduan Transisi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Rancangan Orientasi","Peserta; materi; jadwal; pemateri; bahan; kebutuhan khusus."],["Formulir Transfer Pengetahuan Unit","Unit; pejabat lama dan baru; tugas utama; pekerjaan berjalan; templat; kontak; kendala; tanda tangan."],["Presensi dan Uji Pemahaman","Nama; unit; sesi; kehadiran; nilai atau checklist; tindak lanjut."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Rancangan Orientasi dan Paket Bahan telah disiapkan.","☐ Ya ☐ Tidak"],["2","Seluruh pengurus baru mengikuti orientasi umum atau sesi susulan.","☐ Ya ☐ Tidak"],["3","Setiap unit memiliki Panduan Unit dan Formulir Transfer yang ditandatangani.","☐ Ya ☐ Tidak"],["4","Materi AD/ART, larangan dan sanksi, serta keamanan data telah diberikan.","☐ Ya ☐ Tidak"],["5","Laporan Orientasi dan Panduan Transisi terbaru telah diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri PSDM; seluruh Menteri dan Kepala Biro lama dan baru; arsip Biro Kesekretariatan."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-001","g":"Kesekretariatan dan Administrasi","t":"Pengelolaan Surat Masuk","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[461,464],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penerimaan, pencatatan, klasifikasi, penyampaian, pemantauan tindak lanjut, dan pengarsipan surat masuk yang ditujukan kepada BEM, sehingga setiap surat tercatat, sampai kepada pejabat yang tepat, dan ditindaklanjuti tepat waktu."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh surat dan dokumen yang diterima BEM, baik surat fisik maupun surat digital melalui email resmi dan kanal resmi, dari pihak kampus, ORMAWA lain, instansi, dan pihak lain. SOP ini tidak mengatur penerbitan surat keluar (lihat SOP-ADM-002) dan tidak mengatur surat rahasia (lihat SOP-ADM- 020)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 7 dan Pasal 13 (Sekretaris Jenderal sebagai unsur pimpinan BEM).","ART Pasal 3 (Kewajiban BEM) huruf g dan h (laporan berkala dan kepatuhan pada kebijakan STDIIS Jember).","ART Pasal 4 huruf e (mewakili mahasiswa dalam forum resmi internal dan eksternal).","Pedoman Penyusunan SOP BEM Kabinet Baru, Kelompok Kesekretariatan dan Administrasi.","Ketentuan persuratan STDIIS Jember, bila ada."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Surat masuk","Setiap surat atau dokumen resmi dari pihak luar BEM yang ditujukan kepada BEM atau salah satu pengurusnya atas nama jabatan."],["Register Surat Masuk","Buku atau berkas digital yang mencatat seluruh surat masuk berikut nomor agenda dan status tindak lanjutnya."],["Disposisi","Arahan tertulis pejabat atas suatu surat yang memuat tindakan, penanggung jawab, dan tenggat."],["Kanal resmi","Email resmi BEM, platform koordinasi yang ditetapkan, dan sekretariat BEM."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Admin kesekretariatan","R","Menerima, memeriksa, mencatat, memindai, dan mendistribusikan surat."],["Kabiro Kesekretariatan","R","Memeriksa klasifikasi, meneruskan kepada pejabat, dan memantau tenggat."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas pengelolaan surat masuk dan memberi disposisi surat rutin."],["Presiden","C","Memberi disposisi surat yang menyangkut kebijakan, keuangan, atau pihak kampus."],["Unit penanggung jawab","R","Menindaklanjuti surat sesuai disposisi dan melaporkan hasilnya."],["Admin dokumen","R","Menyimpan surat dan bukti tindak lanjut pada arsip."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Surat asli atau salinan digital yang terbaca.","Register Surat Masuk dan Lembar Disposisi.","Daftar pejabat dan unit penerima disposisi (SOP-GOV-001).","Akses ke email resmi dan repositori resmi BEM."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan: Menerima surat fisik di sekretariat atau surat digital pada kanal resmi; memberi tanda terima bila diminta pengirim.","Admin kesekretariatan","Surat fisik atau digital","Surat diterima","Hari yang sama"],["2","Pemeriksaan awal: Memeriksa pengirim, tujuan, tanggal, lampiran, dan keaslian; surat yang tidak jelas peruntukannya dikonfirmasi kepada pengirim.","Admin kesekretariatan","Surat","Layak catat atau dikembalikan","1 hari kerja"],["3","Pencatatan: Mencatat pada Register Surat Masuk (nomor agenda, tanggal terima, asal, nomor dan tanggal surat, perihal, lampiran), lalu memindai surat.","Admin kesekretariatan","Surat","Entri register dan berkas pindai","1 hari kerja"],["4","Klasifikasi dan penyampaian: Menggolongkan surat: biasa, penting dan berbatas waktu, atau rahasia (dialihkan ke SOP-ADM-020); meneruskan kepada Sekjen dengan Lembar Disposisi.","Kabiro Kesekretariatan","Entri register","Surat terklasifikasi","1 hari kerja"],["5","Disposisi: Membaca surat dan memberi disposisi: tindakan, penanggung jawab, dan tenggat. Surat yang menyangkut kebijakan, keuangan, atau kampus diteruskan kepada Presiden.","Sekjen atau Presiden","Surat, Lembar Disposisi","Disposisi tertulis","2 hari kerja"],["6","Distribusi: Mengirim salinan surat dan disposisi kepada penanggung jawab melalui kanal resmi dan mencatat penerimanya.","Admin kesekretariatan","Disposisi","Distribusi tercatat","1 hari kerja"],["7","Tindak lanjut: Menindaklanjuti surat; bila perlu balasan, diajukan melalui SOP-ADM- 002 dan SOP-ADM-004. Admin memantau tenggat dan mengingatkan 1 hari sebelumnya.","Unit penanggung jawab","Disposisi","Tindak lanjut atau balasan; status register","Sesuai tenggat"],["8","Penutupan dan pengarsipan: Menandai register selesai dan menyimpan surat, disposisi, dan bukti tindak lanjut sesuai SOP-ADM-012 dan SOP-ADM-013.","Admin dokumen","Dokumen lengkap","Arsip lengkap","3 hari kerja setelah selesai"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Surat dicatat paling lambat 1 hari kerja sejak diterima; surat berbatas waktu disampaikan kepada pejabat pada hari yang sama. Hasil akhir: surat tercatat, terdisposisi, dan terarsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Surat berbatas waktu kurang dari 2 hari kerja disampaikan langsung kepada Sekjen atau Presiden melalui kanal resmi pada hari yang sama.","Surat salah alamat diteruskan kepada pihak tujuan dan pengirim diberi tahu.","Surat yang memuat pengaduan, ancaman, atau data pribadi diperlakukan sesuai SOP-ADM-020 dan dilaporkan kepada Sekjen.","Surat perintah atau kebijakan dari pihak kampus disampaikan kepada Presiden pada hari yang sama.","Perbedaan pendapat atas disposisi dibawa ke Rapat Pimpinan (SOP-GOV-005)."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% surat masuk tercatat pada Register Surat Masuk.","Minimal 95% surat dicatat dalam 1 hari kerja.","Minimal 90% surat berbatas waktu ditindaklanjuti sebelum tenggat.","Tidak ada surat tanpa penanggung jawab."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Surat Masuk.","Surat dan berkas pindai.","Lembar Disposisi.","Bukti distribusi dan tindak lanjut. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Surat Masuk) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Kesekretariatan merekap surat yang belum selesai setiap pekan; Sekjen memeriksa register setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima surat → Periksa → Catat di register → Klasifikasi → Disposisi → Distribusi → Tindak lanjut → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Disposisi","Nomor agenda; tanggal terima; asal; perihal; klasifikasi; tindakan yang diminta; penanggung jawab; tenggat; paraf pejabat."],["Register Surat Masuk","Nomor agenda; tanggal terima; asal; nomor dan tanggal surat; perihal; klasifikasi; penerima disposisi; status; lokasi arsip."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Surat tercatat pada register dengan nomor agenda.","☐ Ya ☐ Tidak"],["2","Surat telah dipindai dan tersimpan di folder resmi.","☐ Ya ☐ Tidak"],["3","Disposisi memuat tindakan, penanggung jawab, dan tenggat.","☐ Ya ☐ Tidak"],["4","Distribusi tercatat dan penerima mengonfirmasi.","☐ Ya ☐ Tidak"],["5","Status akhir dan lokasi arsip terisi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-002","g":"Kesekretariatan dan Administrasi","t":"Pembuatan dan Penerbitan Surat Keluar","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[465,468],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pembuatan, pemeriksaan, persetujuan, penomoran, penerbitan, pengiriman, dan pengarsipan surat keluar BEM."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kementerian, biro, panitia, dan pengurus yang mengajukan atau menerbitkan surat atas nama BEM. Pengelolaan nomor diatur pada SOP-ADM-003, jenjang persetujuan pada SOP-ADM-004, dan penggunaan kop, stempel, serta tanda tangan pada SOP-ADM-005."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 13 (Sekretaris Jenderal sebagai unsur pimpinan BEM).","ART Pasal 4 huruf f (wewenang menandatangani surat resmi dan dokumen organisasi).","ART Pasal 11 huruf e, g, dan k (larangan mengatasnamakan BEM tanpa izin, mencemarkan nama baik, dan menyalahgunakan nama organisasi).","Ketentuan persuratan dan tata naskah STDIIS Jember, bila ada.","SOP-GOV-008 (pendelegasian wewenang)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Surat keluar","Surat resmi yang diterbitkan atas nama BEM kepada pihak di dalam atau di luar BEM."],["Pemohon","Pengurus atau unit yang meminta diterbitkannya surat."],["Pejabat penandatangan","Pejabat yang berwenang menandatangani surat sesuai matriks tanda tangan (SOP-ADM- 004)."],["Register Surat Keluar","Catatan seluruh nomor dan surat keluar yang diterbitkan."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pemohon","R","Menyiapkan kebutuhan, data, tujuan, penerima, isi, dan lampiran surat."],["Admin kesekretariatan","R","Memeriksa kelengkapan dan format, menyiapkan draf, menomori, dan mengirim."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas ketertiban penerbitan surat dan memeriksa kesesuaian administrasi dan kewenangan."],["Pejabat penandatangan","R","Menyetujui dan menandatangani sesuai kewenangan."],["Admin dokumen","R","Menyimpan surat final dan bukti pengiriman."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Pengajuan Surat dan bahan isi surat.","Templat surat resmi pada SOP-ADM-005.","Matriks tanda tangan (SOP-ADM-004).","Register Surat Keluar."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan: Mengirim Formulir Pengajuan Surat beserta tujuan, penerima, isi pokok, tenggat, dan lampiran melalui kanal resmi.","Pemohon","Formulir dan bahan","Pengajuan tercatat","Sesuai kebutuhan"],["2","Verifikasi: Memeriksa kelengkapan, format, kewenangan, ejaan, dan kesesuaian isi dengan kebijakan BEM.","Admin kesekretariatan","Pengajuan","Lengkap atau perlu revisi","1 hari kerja"],["3","Revisi: Mengembalikan draf kepada pemohon bila ada kekurangan; pemohon memperbaiki dan mengirim ulang.","Pemohon","Catatan verifikasi","Draf diperbaiki","1 hari kerja"],["4","Pemeriksaan Sekjen: Memeriksa kesesuaian administrasi dan kewenangan lalu meneruskan kepada penandatangan.","Sekjen","Draf lengkap","Draf layak tanda tangan","1 hari kerja"],["5","Persetujuan: Menyetujui atau menolak dengan alasan sesuai jenjang pada SOP-ADM- 004.","Pejabat penandatangan","Draf layak","Disetujui atau ditolak","2 hari kerja"],["6","Penerbitan: Memberi nomor sesuai SOP-ADM- 003, mencetak pada kop resmi, dan memproses tanda tangan serta stempel (SOP-ADM-005).","Admin kesekretariatan","Draf disetujui","Surat resmi","1 hari kerja"],["7","Pengiriman: Mengirim surat melalui kanal resmi yang sesuai dan meminta bukti terima bila diperlukan.","Admin kesekretariatan","Surat resmi","Bukti pengiriman","1 hari kerja"],["8","Pengarsipan: Menyimpan surat final, lampiran, dan bukti pengiriman di folder resmi serta melengkapi register.","Admin dokumen","Surat dan bukti","Arsip lengkap","2 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Pemeriksaan awal paling lambat 1 hari kerja setelah pengajuan lengkap. Surat rutin ditargetkan terbit paling lambat 5 hari kerja sejak pengajuan lengkap; surat berbatas waktu mengikuti tenggat yang disepakati pemohon dan Sekjen. Hasil akhir: surat resmi bernomor, bukti pengiriman, dan arsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Surat mendesak dapat diterbitkan dengan jalur cepat atas persetujuan Sekjen dan dicatat alasannya; kelengkapan administrasi dilengkapi paling lambat 2 hari kerja setelahnya.","Surat yang ditolak dikembalikan dengan alasan tertulis; pemohon dapat mengajukan ulang atau meminta pertimbangan Wakil Presiden.","Surat yang keliru terbit ditarik, dicatat pada register, dan diganti surat perbaikan bernomor baru.","Surat yang menyangkut keuangan, kerja sama, atau pernyataan publik mengikuti SOP-KEU, SOP- HKE, dan SOP-KOM yang terkait.","Dugaan pemalsuan atau penyalahgunaan surat dilaporkan kepada Irjen."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% surat keluar tercatat pada Register Surat Keluar.","Minimal 90% surat rutin terbit dalam 5 hari kerja.","Tidak ada surat terbit tanpa persetujuan penandatangan yang berwenang.","Tidak ada nomor ganda atau nomor tanpa surat."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Surat final yang telah disahkan.","Nomor surat yang tercatat.","Arsip digital.","Bukti pengiriman, jika relevan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Surat Keluar) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretariat memeriksa kelengkapan arsip dan kepatuhan prosedur secara berkala; Sekjen memeriksa register setiap bulan. Penyimpangan dicatat untuk ditindaklanjuti."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengajuan → Verifikasi → Revisi bila perlu → Pemeriksaan Sekjen → Persetujuan → Penerbitan → Pengiriman → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pengajuan Surat","Nama pemohon dan unit; jenis surat; tujuan dan penerima; perihal; isi pokok; lampiran; tenggat; pejabat penandatangan yang diusulkan."],["Templat Surat Resmi","Kop; nomor; lampiran; hal; tujuan; isi; penutup; penandatangan; tembusan."],["Register Surat Keluar","Nomor; tanggal; jenis; tujuan; perihal; penandatangan; pemohon; bukti kirim; lokasi arsip."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Formulir pengajuan lengkap dan tujuan jelas.","☐ Ya ☐ Tidak"],["2","Format dan ejaan sesuai templat resmi.","☐ Ya ☐ Tidak"],["3","Penandatangan sesuai matriks kewenangan.","☐ Ya ☐ Tidak"],["4","Nomor tercatat pada register.","☐ Ya ☐ Tidak"],["5","Surat final dan bukti pengiriman telah diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-003","g":"Kesekretariatan dan Administrasi","t":"Penomoran Surat Resmi","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[469,472],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan format, cara permintaan, pencatatan, dan pembatalan nomor surat dan dokumen resmi BEM agar setiap dokumen memiliki nomor unik yang dapat ditelusuri."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh surat dan dokumen resmi yang diterbitkan atas nama BEM, termasuk undangan, surat tugas, mandat, rekomendasi, berita acara, proposal, dan keputusan. Nomor dokumen eksternal (misalnya keputusan BPM) tidak diberikan oleh BEM dan dicatat sesuai nomor aslinya."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 13 (Sekretaris Jenderal sebagai unsur pimpinan BEM).","ART Pasal 4 huruf f (wewenang menandatangani surat resmi dan dokumen organisasi).","ART Pasal 3 (Kewajiban BEM) huruf g (laporan berkala).","SOP-ADM-011 (Register Dokumen)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Nomor surat","Kode unik dokumen resmi dengan format baku sesuai SOP ini."],["Kode jenis","Singkatan yang menunjukkan jenis dokumen."],["Buku Register Nomor","Catatan seluruh nomor yang telah diberikan beserta statusnya (terpakai, batal)."],["Pemesanan nomor","Permintaan nomor sebelum dokumen ditandatangani, dengan masa berlaku terbatas."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Format nomor (usulan): [nomor urut 3 digit]/[kode jenis]/BEM-STDIIS/[bulan Romawi]/[tahun], misalnya 014/UND/BEM-STDIIS/X/2026.","Nomor urut berjalan tunggal untuk semua jenis dokumen dalam satu tahun kalender dan dimulai dari 001 pada bulan Januari."]},{"tb":{"h":["Kode jenis","Jenis dokumen"],"r":[["UND","Surat undangan"],["TGS","Surat tugas"],["MDT","Surat mandat"],["REK","Surat rekomendasi"],["PMH","Surat permohonan"],["PBT","Surat pemberitahuan"],["BLS","Surat balasan"],["BA","Berita acara"],["KEP","Keputusan Presiden"],["PRO","Proposal kegiatan"],["LAIN","Dokumen resmi lain yang disetujui Sekjen"]]}},{"ul":["Hanya Admin kesekretariatan yang memberikan nomor; unit lain dilarang menomori sendiri.","Nomor tidak boleh dipakai ulang. Nomor yang dibatalkan tetap tercatat dengan status batal dan alasan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pemohon","R","Mengajukan permintaan nomor dengan menyebut jenis dokumen, perihal, dan penandatangan."],["Admin kesekretariatan","R","Memberikan nomor sesuai format, mencatat pada register, dan membatalkan nomor tidak terpakai."],["Kabiro Kesekretariatan","R","Memeriksa register setiap pekan dan menindaklanjuti nomor yang menggantung."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas keteraturan penomoran dan menetapkan perubahan format."],["Irjen","C","Memeriksa konsistensi nomor dan register pada pemeriksaan berkala."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Jenis dokumen dan kode jenisnya.","Perihal dan nama penandatangan.","Buku Register Nomor yang terkini."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Permintaan nomor: Pemohon mengirim jenis dokumen, perihal, tanggal rencana terbit, dan penandatangan kepada Admin melalui kanal resmi.","Pemohon","Data dokumen","Permintaan tercatat","Sesuai kebutuhan"],["2","Pemeriksaan: Memeriksa kode jenis dan kelengkapan data serta memastikan dokumen telah disetujui atau sedang diproses.","Admin kesekretariatan","Permintaan","Layak diberi nomor","Hari yang sama"],["3","Pemberian nomor: Mengambil nomor urut berikutnya, menyusun nomor sesuai format, dan mencatatnya pada register dengan status dipesan.","Admin kesekretariatan","Data dokumen","Nomor dan entri register","Hari yang sama"],["4","Pemakaian: Pemohon mencantumkan nomor pada dokumen; setelah ditandatangani, status diubah menjadi terpakai.","Pemohon, Admin","Dokumen bertanda tangan","Status terpakai","Paling lama 3 hari kerja"],["5","Pembatalan: Nomor yang tidak dipakai dalam 3 hari kerja dibatalkan dengan alasan dan tidak dipakai ulang.","Admin kesekretariatan","Register","Status batal","3 hari kerja"],["6","Rekonsiliasi: Mencocokkan register dengan arsip surat; nomor tanpa dokumen ditelusuri.","Kabiro Kesekretariatan","Register, arsip","Catatan temuan","Setiap pekan"],["7","Tinjauan format: Meninjau format dan kode jenis pada evaluasi tengah periode dan mengusulkan perubahan bila diperlukan.","Sekjen","Hasil rekonsiliasi","Penegasan atau perubahan format","Tengah periode"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Nomor diberikan pada hari permintaan diterima bila data lengkap. Hasil akhir: nomor unik pada dokumen dan entri register yang lengkap."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Permintaan nomor sebelum dokumen disetujui dibatasi dan hanya berlaku untuk dokumen yang dijadwalkan terbit dalam 3 hari kerja.","Kesalahan penulisan nomor pada dokumen yang sudah terbit diperbaiki dengan surat perbaikan bernomor baru dan dicatat pada register.","Nomor ganda atau nomor hilang dilaporkan kepada Sekjen dan dicatat sebagai temuan.","Perubahan format nomor mengikuti SOP-GOV-011 (perubahan kebijakan internal)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Tidak ada nomor ganda.","100% nomor pada register memiliki status dan dokumen terkait.","Nomor tanpa dokumen ditindaklanjuti dalam 1 pekan.","Register cocok dengan arsip pada setiap rekonsiliasi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Nomor dokumen pada surat atau dokumen resmi.","Buku Register Nomor.","Catatan pembatalan dan rekonsiliasi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Register) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Kesekretariatan merekonsiliasi register setiap pekan; Sekjen memeriksa setiap bulan; Irjen menilai konsistensi pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Permintaan nomor → Pemeriksaan → Pemberian nomor → Pemakaian pada dokumen → Status terpakai atau batal → Rekonsiliasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Nomor","Pemohon; unit; jenis dokumen dan kode; perihal; penandatangan; tanggal rencana terbit."],["Buku Register Nomor","Nomor; tanggal; kode jenis; perihal; pemohon; penandatangan; status; keterangan pembatalan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kode jenis sesuai tabel.","☐ Ya ☐ Tidak"],["2","Nomor urut berurutan dan tidak ganda.","☐ Ya ☐ Tidak"],["3","Status nomor (dipesan, terpakai, batal) terisi.","☐ Ya ☐ Tidak"],["4","Nomor pada dokumen sama dengan register.","☐ Ya ☐ Tidak"],["5","Rekonsiliasi pekan ini telah dilakukan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-004","g":"Kesekretariatan dan Administrasi","t":"Pengajuan dan Persetujuan Surat","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[473,476],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan jenjang pemeriksaan, persetujuan, dan penandatanganan surat agar setiap surat diterbitkan oleh pejabat yang berwenang dan isinya telah diperiksa sebelum dikirim."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh surat keluar BEM dari semua kementerian, biro, dan panitia. SOP ini mengatur siapa yang memeriksa dan menyetujui; tata cara penerbitan surat diatur pada SOP-ADM-002."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf f (wewenang menandatangani surat resmi dan dokumen organisasi).","ART Pasal 4 huruf e (mewakili mahasiswa sebagai pimpinan tertinggi eksekutif).","ART Pasal 11 huruf e (larangan mengatasnamakan BEM dalam politik praktis tanpa izin kampus).","SOP-GOV-001 (matriks kewenangan) dan SOP-GOV-008 (pendelegasian wewenang)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Matriks tanda tangan","Daftar jenis surat dan pejabat yang berwenang menyetujui serta menandatanganinya."],["Paraf","Tanda pemeriksaan pejabat pada draf sebelum surat ditandatangani."],["Atas nama","Penandatanganan oleh pejabat lain berdasarkan mandat tertulis dari pejabat yang berwenang."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Jenjang persetujuan (usulan): (a) surat rutin internal dan undangan rapat: paraf Sekjen, ditandatangani Sekjen dengan mandat Presiden; (b) surat kepada pihak kampus, ORMAWA lain, atau pihak eksternal: ditandatangani Presiden; (c) surat yang berdampak anggaran, kerja sama, atau pernyataan publik: ditandatangani Presiden setelah pemeriksaan unit terkait.","Setiap penandatanganan atas nama wajib berdasarkan mandat tertulis sesuai SOP-GOV-008.","Surat yang memuat sikap atau pernyataan resmi BEM kepada publik wajib melalui Presiden.","Pejabat yang berhalangan digantikan sesuai SOP-GOV-009."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pemohon dan Menteri atau Kabiro","R","Menyiapkan draf dan memberi paraf kelayakan isi unit."],["Admin kesekretariatan","R","Memeriksa kelengkapan dan menyiapkan draf untuk diajukan."],["Sekretaris Jenderal","A","Memeriksa kesesuaian administrasi dan kewenangan serta bertanggung jawab atas keteraturan jenjang persetujuan."],["Presiden atau pejabat penandatangan","R","Menyetujui dan menandatangani surat sesuai kewenangan."],["Bendahara atau Biro Keuangan","C","Memberi masukan pada surat yang menyangkut anggaran."],["Irjen","C","Diminta masukan bila surat berpotensi bertentangan dengan AD/ART."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Draf surat yang telah diparaf unit pemohon.","Matriks tanda tangan.","Mandat tertulis, bila penandatanganan atas nama.","Bahan pendukung (data, lampiran, dasar aturan)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan dan paraf unit: Pemohon menyusun draf dan memperoleh paraf Menteri atau Kabiro pada unitnya.","Pemohon","Bahan surat","Draf berparaf unit","1 hari kerja"],["2","Pemeriksaan administrasi: Admin memeriksa format dan kelengkapan; Sekjen memeriksa kewenangan dan menentukan jenjang persetujuan.","Admin, Sekjen","Draf","Draf diparaf Sekjen","1 hari kerja"],["3","Masukan unit terkait: Draf yang menyangkut anggaran, kerja sama, atau hal teknis dimintakan masukan unit terkait.","Sekjen","Draf","Masukan tertulis","1 hari kerja"],["4","Penyampaian kepada penandatangan: Draf lengkap diajukan kepada Presiden atau pejabat penandatangan beserta ringkasan isi.","Admin kesekretariatan","Draf berparaf","Draf di meja penandatangan","Hari yang sama"],["5","Keputusan: Menyetujui, meminta perbaikan, atau menolak dengan alasan tertulis.","Pejabat penandatangan","Draf","Persetujuan atau catatan","2 hari kerja"],["6","Penandatanganan: Menandatangani surat final sesuai SOP-ADM-005 dan mengembalikannya kepada Admin.","Pejabat penandatangan","Surat final","Surat bertanda tangan","1 hari kerja"],["7","Pencatatan: Mencatat persetujuan dan paraf pada register; surat dilanjutkan ke penerbitan dan pengarsipan (SOP- ADM-002).","Admin kesekretariatan","Surat bertanda tangan","Entri register","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pemeriksaan administrasi paling lambat 1 hari kerja dan keputusan penandatangan paling lambat 2 hari kerja sejak draf lengkap diterima. Hasil akhir: surat bertanda tangan pejabat berwenang dengan jejak persetujuan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Penandatangan berhalangan: mandat diberikan sesuai SOP-GOV-008 atau pelaksana harian ditunjuk sesuai SOP-GOV-009.","Perbedaan pendapat antara unit pemohon dan Sekjen mengenai isi atau jenjang diputuskan Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Surat yang diduga bertentangan dengan AD/ART atau aturan kampus ditahan dan dimintakan telaah Irjen.","Penandatanganan tanpa kewenangan dicatat sebagai pelanggaran prosedur dan dilaporkan kepada Irjen (ART Pasal 12 dan Pasal 13)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% surat keluar memiliki jejak persetujuan.","Tidak ada surat ditandatangani di luar kewenangan.","Minimal 90% draf lengkap diputuskan dalam 2 hari kerja.","Jumlah revisi berulang per surat menurun dari bulan ke bulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Surat bertanda tangan pejabat berwenang.","Lembar paraf atau catatan persetujuan.","Mandat tertulis, bila ada.","Entri register persetujuan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Surat Keluar) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen memeriksa kesesuaian jenjang persetujuan setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Draf dan paraf unit → Periksa administrasi dan kewenangan → Masukan unit terkait → Keputusan penandatangan → Tanda tangan → Catat dan terbitkan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Paraf dan Persetujuan","Nomor draf; perihal; unit pemohon; paraf Menteri atau Kabiro; paraf Sekjen; keputusan penandatangan; tanggal; catatan."],["Matriks Tanda Tangan","Jenis surat; pemeriksa; penandatangan; syarat mandat; keterangan."],["Surat Mandat Penandatanganan","Pemberi mandat; penerima; jenis surat; masa berlaku; batas wewenang; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Draf telah diparaf unit pemohon dan Sekjen.","☐ Ya ☐ Tidak"],["2","Jenjang persetujuan sesuai matriks.","☐ Ya ☐ Tidak"],["3","Penandatangan berwenang atau memiliki mandat.","☐ Ya ☐ Tidak"],["4","Masukan unit terkait telah diperoleh bila diperlukan.","☐ Ya ☐ Tidak"],["5","Persetujuan tercatat pada register.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-005","g":"Kesekretariatan dan Administrasi","t":"Penggunaan Kop Surat, Stempel, dan Tanda Tangan","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[477,480],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan ketentuan penggunaan, penyimpanan, dan pengamanan kop surat, lambang, stempel, dan tanda tangan agar identitas resmi BEM tidak disalahgunakan dan setiap dokumen dapat dipertanggungjawabkan keasliannya."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus yang menyiapkan, menandatangani, atau mengesahkan dokumen resmi atas nama BEM, baik dalam bentuk cetak maupun digital. Pemakaian logo pada media publikasi diatur pada SOP- KOM (akan disusun)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 18 ayat (1) dan (2) (lambang BEM adalah lambang yang disahkan STDIIS Jember; lambang yang tidak disahkan dilarang di dalam kampus).","ART Pasal 2 huruf b (hak atas penggunaan nama, lambang, dan identitas resmi yang disetujui STDIIS Jember).","ART Pasal 4 huruf f (wewenang menandatangani surat resmi dan dokumen organisasi).","ART Pasal 11 huruf i dan k (larangan penyelewengan dan penggunaan nama atau fasilitas organisasi untuk kepentingan pribadi).","SOP-ADM-004 (matriks tanda tangan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kop surat","Bagian atas surat resmi yang memuat lambang, nama organisasi, dan alamat sekretariat."],["Stempel","Cap resmi organisasi yang menyatakan keabsahan dokumen, bila diizinkan kampus."],["Tanda tangan basah","Tanda tangan langsung pada dokumen cetak."],["Tanda tangan digital","Tanda tangan elektronik yang dibuat dan diberikan sendiri oleh pejabat melalui sarana yang ditetapkan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Hanya lambang dan kop yang disahkan STDIIS Jember yang boleh dipakai; templat resmi disimpan pada repositori dan hanya diubah melalui SOP-GOV-011.","Stempel dipegang Sekjen, dikunci saat tidak dipakai, dan dibubuhkan hanya pada dokumen yang telah bertanda tangan pejabat berwenang.","Setiap pembubuhan stempel dicatat pada Buku Penggunaan Stempel.","Tanda tangan hanya dibubuhkan pejabat bersangkutan atau penerima mandat tertulis; memindai tanda tangan untuk dipakai berulang tanpa persetujuan pejabat dilarang.","Dokumen yang ditandatangani digital disimpan dalam bentuk PDF dan tidak diedit setelah ditandatangani.","Penyalahgunaan kop, stempel, atau tanda tangan diproses sebagai pelanggaran sesuai ART Pasal 11 sampai Pasal 13."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pejabat penandatangan","R","Menandatangani dokumen yang menjadi kewenangannya dan menjaga tanda tangannya."],["Sekretaris Jenderal","A","Memegang stempel dan bertanggung jawab akhir atas penggunaan kop, stempel, dan tanda tangan."],["Admin kesekretariatan","R","Menyiapkan dokumen di atas kop resmi, memproses stempel, dan mengisi buku penggunaan."],["Presiden","C","Menetapkan pengganti pemegang stempel bila Sekjen berhalangan dan menyetujui perubahan templat."],["Irjen","C","Memeriksa penggunaan stempel dan keaslian dokumen secara berkala."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Templat kop surat resmi.","Dokumen yang telah disetujui sesuai SOP-ADM-004.","Buku Penggunaan Stempel.","Izin kampus untuk stempel BEM, bila diperlukan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyiapan dokumen: Admin menyiapkan dokumen pada templat kop resmi terbaru dan memeriksa tidak ada ruang kosong yang dapat disalahgunakan.","Admin kesekretariatan","Draf disetujui","Dokumen siap tanda tangan","1 hari kerja"],["2","Penandatanganan: Pejabat menandatangani dokumen (basah atau digital) sesuai kewenangan atau mandat.","Pejabat penandatangan","Dokumen siap","Dokumen bertanda tangan","1 hari kerja"],["3","Pemeriksaan sebelum stempel: Sekjen memeriksa nomor, tanda tangan, dan kesesuaian dengan register sebelum stempel dibubuhkan.","Sekjen","Dokumen bertanda tangan","Dokumen layak distempel","Hari yang sama"],["4","Pembubuhan stempel: Stempel dibubuhkan pada tanda tangan dan dicatat pada Buku Penggunaan Stempel (nomor, tanggal, pemohon).","Sekjen atau Admin yang ditunjuk","Dokumen layak","Dokumen sah","Hari yang sama"],["5","Penyimpanan alat: Stempel dan blangko kop dikembalikan ke tempat terkunci setelah dipakai.","Sekjen","Stempel, blangko","Alat tersimpan","Hari yang sama"],["6","Pemeriksaan berkala: Mencocokkan Buku Penggunaan Stempel dengan Register Surat Keluar dan memeriksa dokumen digital tidak diubah.","Kabiro Kesekretariatan","Buku, register","Catatan pemeriksaan","Setiap bulan"],["7","Penanganan kehilangan: Kehilangan atau penyalahgunaan dilaporkan segera, penggunaan dihentikan, dan tindak lanjut ditetapkan Presiden.","Sekjen, Presiden","Laporan kehilangan","Keputusan tindak lanjut","Maksimal 1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pemeriksaan sebelum stempel dan pembubuhan dilakukan pada hari dokumen bertanda tangan diterima. Hasil akhir: dokumen sah, Buku Penggunaan Stempel terisi, dan alat resmi tersimpan aman."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pemegang stempel berhalangan: Presiden menunjuk pengganti sementara sesuai SOP-GOV-009 dan pergantian dicatat.","Kampus tidak mengizinkan stempel BEM: pengesahan dilakukan dengan tanda tangan pejabat dan nomor register.","Kop surat atau lambang yang berbeda dari yang disahkan kampus segera ditarik dan diganti.","Kehilangan stempel atau tanda tangan digital dilaporkan kepada Presiden dan Irjen, dan kampus diberi tahu bila diperlukan."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Tidak ada dokumen resmi tanpa kop yang disahkan.","100% pembubuhan stempel tercatat.","Tidak ada kasus penyalahgunaan stempel atau tanda tangan.","Buku stempel cocok dengan Register Surat Keluar pada setiap pemeriksaan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Dokumen resmi bertanda tangan dan bercap (bila berlaku).","Buku Penggunaan Stempel.","Catatan pemeriksaan berkala.","Laporan kehilangan atau penyalahgunaan, bila terjadi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Identitas Resmi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Kesekretariatan memeriksa penggunaan stempel setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Siapkan dokumen pada kop resmi → Tanda tangan → Periksa nomor dan tanda tangan → Bubuhkan stempel dan catat → Simpan alat → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Buku Penggunaan Stempel","Nomor urut; tanggal; nomor dokumen; perihal; pemohon; pejabat penandatangan; paraf pemegang stempel."],["Templat Kop Surat","Lambang yang disahkan; nama organisasi; alamat sekretariat; kontak resmi."],["Laporan Kehilangan atau Penyalahgunaan","Jenis alat atau dokumen; waktu dan tempat; kronologi; pihak yang mengetahui; tindakan awal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Dokumen memakai templat kop terbaru.","☐ Ya ☐ Tidak"],["2","Penandatangan berwenang atau bermandat.","☐ Ya ☐ Tidak"],["3","Nomor dokumen sama dengan register.","☐ Ya ☐ Tidak"],["4","Pembubuhan stempel tercatat pada buku.","☐ Ya ☐ Tidak"],["5","Stempel dan blangko tersimpan terkunci.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-006","g":"Kesekretariatan dan Administrasi","t":"Pembuatan Surat Undangan, Tugas, Mandat, dan Rekomendasi","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[481,484],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan isi minimal, syarat, dan prosedur pembuatan surat undangan, surat tugas, surat mandat, dan surat rekomendasi agar dokumen tersebut memiliki dasar yang jelas, batas wewenang yang tegas, dan dapat dipertanggungjawabkan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk keempat jenis surat yang diterbitkan atas nama BEM. Pengiriman delegasi dan laporan hasil pertemuan eksternal diatur pada SOP-HKE (akan disusun); penerbitan surat secara umum mengikuti SOP- ADM-002."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf f (wewenang menandatangani surat resmi) dan huruf g (memberikan rekomendasi kepada HIMA dan UKM dalam pelaksanaan kegiatan).","ART Pasal 4 huruf c (mengusulkan pembentukan panitia kegiatan dan tim kerja internal).","ART Pasal 2 huruf e (kerja sama dengan pihak eksternal dengan persetujuan Ketua STDIIS Jember).","SOP-GOV-008 (pendelegasian wewenang) dan SOP-ADM-004 (jenjang persetujuan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Surat undangan","Surat yang meminta kehadiran pihak tertentu pada rapat atau kegiatan."],["Surat tugas","Surat yang menugaskan pengurus atau panitia melaksanakan pekerjaan tertentu dalam jangka waktu tertentu."],["Surat mandat","Surat yang memberi kuasa kepada pihak tertentu bertindak atas nama BEM dengan batas wewenang tertulis."],["Surat rekomendasi","Surat yang menyatakan dukungan atau persetujuan BEM atas kegiatan atau pihak tertentu."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Surat undangan memuat nomor, hal, hari, tanggal, waktu, tempat atau tautan daring, agenda, pakaian atau perlengkapan yang diminta, dan kontak panitia; dikirim paling lambat H-2 untuk rapat internal dan H-7 untuk kegiatan besar (usulan).","Surat tugas memuat nama dan jabatan penerima tugas, uraian tugas, tempat dan waktu, sumber pendanaan bila ada, serta kewajiban melapor.","Surat mandat memuat pemberi dan penerima mandat, hal yang dikuasakan, batas wewenang, masa berlaku, dan larangan bertindak di luar mandat.","Surat rekomendasi hanya diberikan setelah penerima rekomendasi menyerahkan proposal atau data pendukung yang lengkap dan diperiksa sesuai SOP-ADM-008.","Surat mandat dan surat rekomendasi ditandatangani Presiden atau penerima mandat yang berwenang sesuai SOP-ADM-004."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pemohon","R","Menyampaikan kebutuhan surat beserta data pendukung."],["Admin kesekretariatan","R","Menyusun draf pada templat yang sesuai dan memeriksa kelengkapan isi minimal."],["Sekretaris Jenderal","A","Memeriksa kesesuaian isi dan kewenangan serta bertanggung jawab akhir atas surat yang terbit."],["Pejabat penandatangan","R","Menyetujui dan menandatangani surat."],["Penerima surat","I","Menjalankan tugas, mandat, atau rekomendasi sesuai isi surat dan melapor."],["Irjen","C","Meninjau surat mandat atau rekomendasi yang berpotensi bertentangan dengan AD/ART."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Pengajuan Surat.","Dasar keputusan atau penugasan (keputusan rapat atau disposisi).","Data penerima surat dan rincian kegiatan.","Templat tiap jenis surat."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan: Pemohon mengajukan jenis surat dan data pendukung (agenda, waktu, penerima, rincian tugas atau wewenang).","Pemohon","Formulir, data","Pengajuan tercatat","Sesuai kebutuhan"],["2","Penentuan jenis dan dasar: Admin menentukan jenis surat, memeriksa dasar keputusan, dan memastikan wewenang yang diberikan tidak melampaui kewenangan pemberi.","Admin kesekretariatan","Pengajuan","Jenis dan dasar surat jelas","1 hari kerja"],["3","Penyusunan draf: Menyusun draf pada templat dengan isi minimal sesuai jenis surat.","Admin kesekretariatan","Templat, data","Draf surat","1 hari kerja"],["4","Pemeriksaan: Sekjen memeriksa isi, kewenangan, dan batas mandat; surat rekomendasi diperiksa kelengkapan dokumen pendukung.","Sekjen","Draf","Draf layak atau revisi","1 hari kerja"],["5","Persetujuan dan penomoran: Draf disetujui dan ditandatangani sesuai SOP-ADM-004, kemudian diberi nomor sesuai SOP-ADM-003.","Pejabat penandatangan","Draf layak","Surat resmi","2 hari kerja"],["6","Pengiriman: Mengirim surat melalui kanal resmi; undangan dikirim sesuai batas waktu H-2 atau H-7.","Admin kesekretariatan","Surat resmi","Bukti kirim","Sesuai batas waktu undangan"],["7","Pemantauan: Mencatat konfirmasi kehadiran undangan dan memantau laporan pelaksanaan tugas atau mandat.","Admin, Sekjen","Konfirmasi, laporan","Daftar konfirmasi dan laporan","Sampai kegiatan selesai"],["8","Pengarsipan: Menyimpan surat, bukti kirim, dan laporan pelaksanaan pada folder resmi.","Admin dokumen","Dokumen lengkap","Arsip lengkap","3 hari kerja setelah selesai"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Surat tugas, mandat, dan rekomendasi ditargetkan terbit paling lambat 5 hari kerja sejak pengajuan lengkap; undangan mengikuti batas pengiriman H-2 atau H-7. Hasil akhir: surat resmi bernomor, bukti kirim, dan arsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Undangan rapat mendesak (SOP-GOV-007 dan SOP-GOV-012) dapat dikirim kurang dari H-2 dengan alasan dicatat.","Mandat yang batas wewenangnya tidak jelas dikembalikan kepada pemohon dan tidak diterbitkan.","Rekomendasi tidak diberikan bila kegiatan bertentangan dengan AD/ART, peraturan kampus, atau syariat, dan alasan disampaikan tertulis.","Penerima mandat atau tugas yang bertindak di luar batas wewenang dilaporkan kepada Irjen dan mandat dicabut.","Perselisihan atas penerbitan atau penolakan rekomendasi diputuskan Wakil Presiden dan, bila perlu, Rapat Pimpinan (SOP-GOV-005)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% surat tugas dan mandat memuat batas wewenang dan masa berlaku.","Minimal 90% undangan terkirim sesuai batas waktu.","Tidak ada rekomendasi terbit tanpa dokumen pendukung lengkap.","Tidak ada laporan tindakan di luar mandat."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Surat undangan, tugas, mandat, atau rekomendasi yang telah disahkan.","Daftar konfirmasi kehadiran undangan.","Laporan pelaksanaan tugas atau mandat.","Bukti kirim dan arsip digital. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Surat Keluar) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen memeriksa kelengkapan isi dan ketepatan waktu setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengajuan → Tentukan jenis dan dasar → Susun draf → Periksa Sekjen → Setujui dan nomori → Kirim → Pantau → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Surat Undangan","Nomor; lampiran; hal; tujuan; hari, tanggal, waktu; tempat atau tautan; agenda; kontak; penandatangan."],["Templat Surat Tugas","Dasar penugasan; nama dan jabatan; uraian tugas; waktu dan tempat; sumber dana; kewajiban melapor."],["Templat Surat Mandat","Pemberi dan penerima; hal yang dikuasakan; batas wewenang; masa berlaku; larangan."],["Templat Surat Rekomendasi","Pihak yang direkomendasikan; kegiatan; dasar pertimbangan; syarat dan catatan; masa berlaku."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Jenis surat sesuai tujuan dan dasar keputusan.","☐ Ya ☐ Tidak"],["2","Isi minimal surat lengkap.","☐ Ya ☐ Tidak"],["3","Batas wewenang atau masa berlaku jelas (tugas dan mandat).","☐ Ya ☐ Tidak"],["4","Dokumen pendukung rekomendasi lengkap.","☐ Ya ☐ Tidak"],["5","Surat bernomor, terkirim, dan terarsip.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-007","g":"Kesekretariatan dan Administrasi","t":"Penyusunan Proposal Kegiatan","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[485,488],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan struktur baku, pembagian peran, dan alur penyusunan proposal kegiatan agar setiap proposal lengkap, seragam, sesuai AD/ART dan aturan kampus, dan siap diperiksa untuk persetujuan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh proposal kegiatan yang diajukan kementerian, biro, dan panitia BEM kepada pimpinan, Pembina, atau kampus. Penyusunan TOR dan RAB secara rinci serta siklus kegiatan diatur pada SOP-PRO (akan disusun); pemeriksaan kelengkapan diatur pada SOP-ADM-008."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 (Tugas BEM) huruf b dan e (merancang program kerja dan menyusun anggaran dengan persetujuan BPM).","ART Pasal 4 huruf c dan d (mengusulkan panitia dan mengajukan dana kemahasiswaan).","ART Pasal 9 ayat (6) (program kerja yang disahkan dalam RAKER harus mendapat persetujuan Pembina sebelum dilaksanakan).","AD Pasal 15 ayat (1) sampai (4) (sumber dana halal, terhindar dari riba, gharar, dan maysir, serta dokumentasi bukti penerimaan).","AD Pasal 5 dan Pasal 6 (fungsi dan tujuan BEM)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Proposal kegiatan","Dokumen tertulis yang menjelaskan rencana, tujuan, anggaran, dan panitia suatu kegiatan untuk memperoleh persetujuan."],["Ketua pelaksana","Penanggung jawab penyusunan proposal dan pelaksanaan kegiatan di lapangan."],["RAB","Rencana Anggaran Biaya kegiatan yang memuat rincian pemasukan dan pengeluaran."],["Menteri pembina","Menteri atau Kabiro yang membawahi bidang kegiatan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Susunan baku proposal: halaman pengesahan; latar belakang dan dasar kegiatan; tujuan dan sasaran; bentuk, waktu, dan tempat; susunan panitia; rencana kegiatan dan jadwal; RAB dan sumber dana; analisis risiko singkat; penutup; lampiran.","Kegiatan harus selaras dengan program kerja yang disahkan RAKER; kegiatan di luar program kerja mengikuti SOP-PRO-003 (akan disusun).","Sumber dana harus halal dan sesuai AD Pasal 15; sponsor yang mengikat kewajiban melampaui satu periode tidak diterima.","Proposal ditandatangani ketua pelaksana, Menteri pembina, dan pejabat berwenang sesuai SOP-ADM- 004."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Ketua pelaksana","R","Menyusun proposal bersama panitia dan menyerahkannya sesuai jadwal."],["Menteri pembina","R","Memberi arahan isi dan memeriksa kesesuaian dengan program kerja."],["Bendahara atau Biro Keuangan","C","Memeriksa RAB dan sumber dana."],["Sekretaris Jenderal","A","Memeriksa kelengkapan administrasi dan bertanggung jawab akhir atas kerapian proposal sebelum diajukan."],["Presiden","R","Menyetujui proposal sesuai kewenangan dan meneruskannya kepada Pembina atau kampus bila diperlukan."],["Irjen","C","Memeriksa kesesuaian proposal dengan AD/ART pada kegiatan berisiko atau berbiaya besar."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Program kerja yang disahkan RAKER.","Keputusan pembentukan panitia.","Templat proposal dan RAB.","Data pendukung (jadwal, tempat, narasumber, penawaran)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penentuan kegiatan: Ketua pelaksana memastikan kegiatan tercantum pada program kerja dan memperoleh arahan dari Menteri pembina.","Ketua pelaksana","Program kerja","Kegiatan terkonfirmasi","2 hari kerja"],["2","Penyusunan draf: Panitia menyusun proposal sesuai susunan baku dan menyiapkan RAB serta jadwal.","Panitia","Templat, data","Draf proposal","5 hari kerja"],["3","Pemeriksaan internal: Menteri pembina memeriksa isi; Bendahara atau Biro Keuangan memeriksa RAB dan sumber dana.","Menteri pembina, Keuangan","Draf","Catatan perbaikan","2 hari kerja"],["4","Perbaikan: Panitia memperbaiki proposal berdasarkan catatan dan menyerahkan versi lengkap.","Panitia","Catatan","Proposal lengkap","2 hari kerja"],["5","Pemeriksaan kelengkapan: Mengajukan proposal kepada Sekretariat untuk diperiksa sesuai SOP-ADM-008.","Ketua pelaksana, Admin","Proposal lengkap","Hasil pemeriksaan kelengkapan","Sesuai SOP-ADM- 008"],["6","Persetujuan: Presiden menyetujui atau menolak dengan alasan; bila perlu proposal diteruskan kepada Pembina atau kampus.","Presiden","Proposal lulus","Persetujuan atau penolakan","3 hari kerja"],["7","Pengarsipan: Menyimpan versi final, bukti persetujuan, dan dokumen pendukung pada folder kegiatan.","Admin dokumen","Proposal disetujui","Arsip proposal","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penyusunan hingga pengajuan ditargetkan 10 hari kerja sebelum kegiatan untuk kegiatan biasa dan 20 hari kerja untuk kegiatan besar atau yang memerlukan persetujuan kampus; waktu final mengikuti kalender kampus. Hasil akhir: proposal final yang disetujui dan terarsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kegiatan mendesak dapat memakai proposal ringkas atas persetujuan Presiden dan dicatat alasannya.","Proposal yang ditolak dapat diperbaiki dan diajukan ulang paling banyak 2 kali sebelum dibawa ke Rapat Pimpinan (SOP-GOV-005).","Proposal yang memuat sumber dana tidak sesuai AD Pasal 15 dikembalikan dan dilaporkan kepada Irjen.","Perubahan besar pada konsep, waktu, atau anggaran setelah disetujui mengikuti SOP-PRO-015 (akan disusun)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% proposal memakai susunan baku.","Minimal 80% proposal lolos pemeriksaan kelengkapan pada pengajuan pertama.","Tidak ada kegiatan berjalan tanpa proposal yang disetujui.","Proposal diajukan sesuai batas waktu minimal 90%."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Proposal final yang disetujui.","RAB dan dokumen pendukung.","Bukti persetujuan.","Arsip digital. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Proposal) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen merekap status proposal setiap bulan; Irjen menilai kepatuhan susunan dan sumber dana pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Konfirmasi kegiatan → Susun draf → Periksa internal → Perbaikan → Periksa kelengkapan → Persetujuan Presiden → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Proposal Kegiatan","Halaman pengesahan; latar belakang; tujuan; bentuk, waktu, tempat; panitia; jadwal; RAB; risiko; penutup; lampiran."],["Templat RAB","Pos pemasukan; pos pengeluaran; volume; harga satuan; jumlah; sumber dana; keterangan."],["Lembar Pengesahan Proposal","Ketua pelaksana; Menteri pembina; Sekjen; Presiden; tanggal; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kegiatan tercantum pada program kerja.","☐ Ya ☐ Tidak"],["2","Susunan proposal sesuai baku.","☐ Ya ☐ Tidak"],["3","RAB dan sumber dana telah diperiksa.","☐ Ya ☐ Tidak"],["4","Lembar pengesahan lengkap.","☐ Ya ☐ Tidak"],["5","Proposal final terarsip.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-008","g":"Kesekretariatan dan Administrasi","t":"Pemeriksaan Kelengkapan Proposal","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[489,492],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara memeriksa kelengkapan dan kesesuaian administrasi proposal kegiatan sebelum diajukan untuk persetujuan, sehingga proposal yang masuk ke pimpinan sudah lengkap, konsisten, dan sesuai aturan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh proposal kegiatan yang diajukan kepada Presiden, Pembina, atau kampus. Pemeriksaan ini bersifat administratif; penilaian kelayakan program dan keputusan persetujuan dilakukan sesuai SOP-PRO dan SOP-ADM-004."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 9 ayat (6) (persetujuan Pembina atas program kerja).","ART Pasal 12 ayat (3) (pengawasan dan evaluasi Irjen atas kinerja pengurus).","AD Pasal 15 (keuangan dan sumber dana) dan AD Pasal 17 (pertanggungjawaban).","SOP-ADM-007 (penyusunan proposal)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pemeriksaan kelengkapan","Pengecekan bahwa semua unsur, lampiran, tanda tangan, dan angka pada proposal telah ada dan konsisten."],["Checklist kelengkapan","Daftar butir pemeriksaan baku yang diisi pemeriksa."],["Status pemeriksaan","Salah satu dari: Lengkap, Perlu perbaikan, atau Ditolak."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Ketua pelaksana","R","Menyerahkan proposal lengkap dan memperbaiki catatan."],["Admin kesekretariatan","R","Memeriksa kelengkapan dan mengisi checklist."],["Bendahara atau Biro Keuangan","C","Memeriksa konsistensi RAB dan sumber dana."],["Sekretaris Jenderal","A","Menetapkan status pemeriksaan dan bertanggung jawab akhir atas proposal yang diteruskan."],["Irjen","C","Memverifikasi dokumen pada kegiatan berisiko atau berbiaya besar."],["Presiden","I","Menerima proposal yang telah dinyatakan lengkap."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Proposal final dan lampirannya.","Checklist Kelengkapan Proposal.","Bukti keputusan program kerja dan pembentukan panitia.","Penawaran atau dasar harga RAB."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan: Admin menerima proposal dan mencatatnya pada Register Proposal.","Admin kesekretariatan","Proposal","Proposal tercatat","Hari yang sama"],["2","Pemeriksaan administrasi: Memeriksa susunan, halaman pengesahan, tanda tangan, nomor, tanggal, nama panitia, dan lampiran dengan checklist.","Admin kesekretariatan","Proposal, checklist","Checklist terisi","1 hari kerja"],["3","Pemeriksaan keselarasan: Mencocokkan kegiatan dengan program kerja, jadwal dengan kalender organisasi (SOP-ADM-018), dan RAB dengan sumber dana.","Admin, Bendahara","Program kerja, kalender, RAB","Catatan keselarasan","1 hari kerja"],["4","Penetapan status: Sekjen menetapkan status: Lengkap, Perlu perbaikan, atau Ditolak, disertai alasan tertulis.","Sekjen","Checklist, catatan","Status pemeriksaan","1 hari kerja"],["5","Perbaikan: Proposal berstatus Perlu perbaikan dikembalikan kepada ketua pelaksana untuk diperbaiki paling banyak 2 kali putaran.","Ketua pelaksana","Catatan","Proposal diperbaiki","2 hari kerja"],["6","Verifikasi tambahan: Untuk kegiatan berisiko atau berbiaya besar, Irjen memverifikasi dokumen dan memberi catatan.","Irjen","Proposal lengkap","Catatan verifikasi","2 hari kerja"],["7","Penerusan: Proposal berstatus Lengkap diteruskan kepada Presiden beserta ringkasan hasil pemeriksaan.","Sekjen","Proposal lengkap","Proposal di meja Presiden","1 hari kerja"],["8","Pengarsipan: Menyimpan checklist, catatan, dan versi proposal pada folder kegiatan.","Admin dokumen","Dokumen pemeriksaan","Arsip lengkap","2 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Pemeriksaan awal paling lambat 2 hari kerja sejak proposal diterima lengkap; penetapan status 1 hari kerja setelahnya. Hasil akhir: status pemeriksaan tertulis dan proposal yang diteruskan kepada Presiden."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Proposal kegiatan mendesak diperiksa dengan prioritas pada hari yang sama atas permintaan Sekjen.","Setelah dua kali perbaikan proposal masih tidak lengkap, Sekjen melaporkannya kepada Wakil Presiden untuk diputuskan.","Dugaan manipulasi data atau dokumen pada proposal dilaporkan kepada Irjen sesuai ART Pasal 13.","Proposal yang bertentangan dengan AD/ART atau aturan kampus ditolak dan alasan disampaikan tertulis."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% proposal diperiksa sebelum diajukan kepada Presiden.","Minimal 90% pemeriksaan selesai dalam 2 hari kerja.","Tidak ada proposal lolos dengan lampiran atau tanda tangan kurang.","Jumlah putaran perbaikan rata-rata kurang dari 2."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Checklist Kelengkapan Proposal yang terisi.","Catatan keselarasan dan status pemeriksaan.","Register Proposal.","Proposal yang telah dinyatakan lengkap. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Proposal) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen merekap proposal yang ditolak atau diperbaiki setiap bulan untuk bahan perbaikan templat; Irjen menilai pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima proposal → Periksa administrasi → Periksa keselarasan → Tetapkan status → Perbaikan bila perlu → Teruskan ke Presiden → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Checklist Kelengkapan Proposal","Butir pemeriksaan; status (ada atau tidak ada); catatan; pemeriksa; tanggal."],["Register Proposal","Nomor; judul kegiatan; pengusul; tanggal terima; status; tanggal selesai; lokasi arsip."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kegiatan tercantum pada program kerja.","☐ Ya ☐ Tidak"],["2","Halaman pengesahan dan tanda tangan lengkap.","☐ Ya ☐ Tidak"],["3","RAB konsisten dan sumber dana sesuai AD Pasal 15.","☐ Ya ☐ Tidak"],["4","Jadwal tidak berbenturan dengan kalender organisasi.","☐ Ya ☐ Tidak"],["5","Status pemeriksaan dan catatan telah diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-009","g":"Kesekretariatan dan Administrasi","t":"Penyusunan Notulen Rapat","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[493,496],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara pencatatan, penyusunan, pengesahan, dan penyebaran notulen rapat serta berita acara forum permusyawaratan agar setiap hasil rapat tercatat akurat dan dapat ditindaklanjuti."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh rapat internal BEM (Rapat Pimpinan, Rapat Kabinet, Rapat Evaluasi, Rapat Koordinasi, rapat unit dan panitia) dan forum permusyawaratan (Mubes dan Musyawarah Istimewa). Tata cara rapat diatur pada SOP-GOV-005, SOP-GOV-006, dan SOP-GOV-007; daftar tindak lanjut diatur pada SOP-ADM-010."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 10 ayat (5) (hasil Rapat Koordinasi dituangkan dalam notulensi resmi dan disosialisasikan kepada seluruh pengurus).","ART Pasal 7 ayat (8) dan Pasal 8 ayat (7) (berita acara Mubes dan Musyawarah Istimewa disahkan Ketua STDIIS).","AD Pasal 14 (cara pengambilan keputusan).","SOP-GOV-002 (pengambilan keputusan) dan SOP-GOV-005 serta SOP-GOV-006 (rapat)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Notulen","Catatan resmi jalannya rapat, keputusan, dan tindak lanjutnya."],["Berita acara","Dokumen resmi hasil forum permusyawaratan yang ditandatangani pimpinan sidang dan disahkan pihak berwenang."],["Notulis","Pengurus yang ditugaskan mencatat jalannya rapat."],["Pimpinan rapat","Pengurus yang memimpin rapat dan mengesahkan notulen."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Notulis","R","Mencatat rapat, menyusun draf notulen, dan mencocokkan dengan rekaman bila ada."],["Pimpinan rapat","R","Memeriksa dan mengesahkan notulen serta menandatangani berita acara."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas ketersediaan notulen sah dan distribusinya."],["Peserta rapat","C","Memberi koreksi atas draf notulen dalam batas waktu."],["Ketua STDIIS atau pejabat yang ditunjuk","R","Mengesahkan berita acara Mubes dan Musyawarah Istimewa."],["Admin dokumen","R","Menyimpan notulen, daftar hadir, dan lampiran."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Undangan dan agenda rapat.","Daftar hadir.","Templat notulen atau berita acara.","Rekaman rapat bila disepakati peserta.","Daftar tindak lanjut rapat sebelumnya."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penunjukan notulis: Sekjen atau pimpinan rapat menunjuk notulis dan cadangannya sebelum rapat.","Sekjen","Undangan","Notulis ditetapkan","H-1"],["2","Pencatatan: Notulis mencatat peserta hadir, kuorum, agenda, pokok pembahasan, pendapat berbeda, keputusan, penanggung jawab, dan tenggat.","Notulis","Agenda, daftar hadir","Catatan rapat","Selama rapat"],["3","Penyusunan draf: Menyusun draf notulen pada templat dan mencocokkan keputusan dengan Lembar Keputusan (SOP-GOV-002).","Notulis","Catatan, Lembar Keputusan","Draf notulen","1 hari kerja"],["4","Koreksi: Draf dikirim kepada peserta melalui kanal resmi untuk dikoreksi; koreksi dicatat.","Notulis, peserta","Draf","Draf terkoreksi","1 hari kerja"],["5","Pengesahan: Pimpinan rapat mengesahkan notulen; untuk forum permusyawaratan disusun berita acara yang ditandatangani pimpinan sidang dan disahkan Ketua STDIIS atau pejabat yang ditunjuk.","Pimpinan rapat","Draf terkoreksi","Notulen sah atau berita acara","2 hari kerja setelah rapat"],["6","Distribusi: Menyebarkan notulen sah kepada peserta dan pihak yang terkait melalui kanal resmi dan mencatat penerimanya.","Admin kesekretariatan","Notulen sah","Distribusi tercatat","1 hari kerja"],["7","Penyusunan daftar tindak lanjut: Menyalin keputusan dan tugas pada Daftar Tindak Lanjut sesuai SOP- ADM-010.","Notulis","Notulen sah","Daftar tindak lanjut","Bersamaan dengan distribusi"],["8","Pengarsipan: Menyimpan notulen, daftar hadir, rekaman, dan lampiran pada folder rapat.","Admin dokumen","Dokumen rapat","Arsip lengkap","3 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Notulen sah paling lambat 2 hari kerja setelah rapat (selaras dengan SOP-GOV-005 dan SOP-GOV-006); berita acara forum permusyawaratan mengikuti jadwal pengesahan Ketua STDIIS. Hasil akhir: notulen bertanda tangan, daftar tindak lanjut, dan arsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Notulis berhalangan: cadangan menggantikan; bila tidak ada, pimpinan rapat menunjuk peserta pada awal rapat.","Perbedaan pendapat tentang isi notulen diselesaikan pimpinan rapat berdasarkan rekaman atau catatan; hasil dicatat.","Rapat darurat (SOP-GOV-007 dan SOP-GOV-012) membuat notulen ringkas pada hari yang sama dan notulen lengkap dalam 2 hari kerja.","Keputusan yang memerlukan persetujuan pihak luar ditandai belum berlaku sampai persetujuan diperoleh.","Pembahasan yang bersifat rahasia dicatat terpisah dan disimpan sesuai SOP-ADM-020."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["Notulen sah dalam 2 hari kerja pada minimal 90% rapat.","100% rapat resmi memiliki daftar hadir dan notulen.","Minimal 95% keputusan tercatat pada notulen dan Lembar Keputusan secara konsisten.","Berita acara forum permusyawaratan tersedia untuk 100% forum."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Notulen bertanda tangan.","Berita acara forum permusyawaratan.","Daftar hadir.","Daftar tindak lanjut.","Arsip digital. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Notulen) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen memeriksa kepatuhan jadwal dan ketepatan notulen; Irjen menilai kesesuaian keputusan dan notulen pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tunjuk notulis → Catat rapat → Susun draf → Koreksi peserta → Pengesahan → Distribusi → Daftar tindak lanjut → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Notulen","Nomor; hari dan tanggal; tempat; pimpinan dan notulis; peserta hadir; kuorum; agenda; pembahasan; keputusan; penanggung jawab; tenggat; pengesahan."],["Templat Berita Acara Forum","Nama forum; waktu dan tempat; pimpinan sidang; kuorum; keputusan; hasil pemungutan suara bila ada; tanda tangan; pengesahan."],["Daftar Hadir Rapat","Nama; jabatan; unit; tanda tangan atau konfirmasi daring."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kuorum dan peserta tercatat.","☐ Ya ☐ Tidak"],["2","Keputusan sama dengan Lembar Keputusan.","☐ Ya ☐ Tidak"],["3","Penanggung jawab dan tenggat setiap keputusan jelas.","☐ Ya ☐ Tidak"],["4","Notulen disahkan dan didistribusikan dalam 2 hari kerja.","☐ Ya ☐ Tidak"],["5","Dokumen rapat telah diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-010","g":"Kesekretariatan dan Administrasi","t":"Pembuatan dan Pemantauan Daftar Tindak Lanjut Rapat","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[497,500],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara menyusun, memantau, dan menutup daftar tindak lanjut hasil rapat agar setiap keputusan memiliki penanggung jawab, tenggat, dan status yang dapat diperiksa."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk tindak lanjut hasil seluruh rapat internal BEM. Tindak lanjut yang berupa program kerja mengikuti SOP-PRO, dan keterlambatan pekerjaan mengikuti SOP-MONEV-08 (akan disusun)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 10 ayat (1) (Rapat Koordinasi untuk mengevaluasi pelaksanaan program kerja dan koordinasi antar pengurus).","ART Pasal 10 ayat (4) huruf b (monitoring penggunaan anggaran).","ART Pasal 12 ayat (3) (Irjen berwenang mengawasi kinerja pengurus).","SOP-ADM-009 (notulen rapat) dan SOP-GOV-002 (pengambilan keputusan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Daftar tindak lanjut","Tabel berisi keputusan atau tugas hasil rapat beserta penanggung jawab, tenggat, dan status."],["Penanggung jawab","Pengurus yang ditugaskan menyelesaikan satu butir tindak lanjut."],["Status","Salah satu dari: Belum mulai, Berjalan, Selesai, Tertunda, atau Dibatalkan."],["Tindak lanjut terlambat","Butir yang melewati tenggat tanpa status Selesai."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Notulis","R","Menyalin keputusan dan tugas ke daftar tindak lanjut dengan penanggung jawab dan tenggat."],["Penanggung jawab tugas","R","Menyelesaikan tugas dan melaporkan status serta bukti penyelesaian."],["Admin kesekretariatan","R","Memperbarui daftar dan mengirim pengingat."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas pemantauan dan melaporkan status pada rapat berikutnya."],["Pimpinan rapat","C","Menetapkan tindakan atas butir yang terlambat."],["Irjen","C","Meninjau butir yang terlambat berulang."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Notulen sah dan Lembar Keputusan.","Daftar tindak lanjut rapat sebelumnya.","Kanal resmi untuk pengingat dan laporan progres."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan daftar: Menyalin setiap keputusan yang membutuhkan tindakan beserta penanggung jawab, tenggat, dan keluaran yang diharapkan.","Notulis","Notulen sah","Daftar tindak lanjut","Bersamaan dengan notulen sah"],["2","Konfirmasi: Penanggung jawab mengonfirmasi tugas dan tenggat; ketidaksesuaian disampaikan kepada pimpinan rapat.","Penanggung jawab","Daftar","Tugas terkonfirmasi","1 hari kerja"],["3","Pengingat: Admin mengirim pengingat 1 hari sebelum tenggat melalui kanal resmi.","Admin kesekretariatan","Daftar","Pengingat terkirim","H-1 tenggat"],["4","Pelaporan status: Penanggung jawab memperbarui status dan melampirkan bukti penyelesaian.","Penanggung jawab","Pekerjaan","Status terbarui","Sesuai tenggat"],["5","Rekap pekanan: Admin merekap status dan menandai butir yang terlambat.","Admin kesekretariatan","Daftar terbarui","Rekap status","Setiap pekan"],["6","Pembahasan pada rapat berikutnya: Sekjen melaporkan status; butir terlambat dibahas untuk diputuskan: perpanjangan tenggat, penggantian penanggung jawab, atau pembatalan.","Sekjen, pimpinan rapat","Rekap status","Keputusan atas butir terlambat","Pada rapat berikutnya"],["7","Penutupan: Butir yang selesai diverifikasi bukti penyelesaiannya dan ditutup; butir dibatalkan dicatat alasannya.","Sekjen","Bukti penyelesaian","Butir ditutup","2 hari kerja"],["8","Pengarsipan: Menyimpan daftar akhir dan bukti penyelesaian pada folder rapat.","Admin dokumen","Daftar akhir","Arsip lengkap","3 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Daftar tindak lanjut disusun bersamaan dengan notulen sah (paling lambat 2 hari kerja setelah rapat) dan diperbarui sekurang-kurangnya setiap pekan. Hasil akhir: daftar tindak lanjut terbarui dan butir yang tertutup beserta buktinya."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Butir yang bergantung pada pihak luar ditandai Tertunda dengan keterangan pihak dan tanggal konfirmasi berikutnya.","Butir terlambat dua kali berturut-turut dibawa ke Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Penanggung jawab yang berhenti atau berhalangan digantikan melalui keputusan Presiden atau pimpinan rapat.","Keterlambatan berulang oleh pengurus yang sama diteruskan kepada Irjen untuk pembinaan sesuai SOP-SDM-011 (akan disusun)."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 80% butir tindak lanjut selesai tepat waktu.","100% butir memiliki penanggung jawab dan tenggat.","Rekap status tersedia pada setiap rapat berikutnya.","Jumlah butir terlambat per bulan menurun."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar tindak lanjut.","Rekap status pekanan.","Bukti penyelesaian.","Arsip digital. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Notulen) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen melaporkan persentase ketepatan tindak lanjut pada evaluasi bulanan; Irjen menilai pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Susun daftar → Konfirmasi tugas → Pengingat → Laporan status → Rekap pekanan → Bahas butir terlambat → Tutup dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Tindak Lanjut","Nomor; rapat dan tanggal; keputusan atau tugas; penanggung jawab; tenggat; status; bukti; keterangan."],["Rekap Status Tindak Lanjut","Periode; jumlah butir; selesai; berjalan; terlambat; tertunda; dibatalkan; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap keputusan yang perlu tindakan masuk daftar.","☐ Ya ☐ Tidak"],["2","Penanggung jawab dan tenggat terisi.","☐ Ya ☐ Tidak"],["3","Pengingat dikirim sebelum tenggat.","☐ Ya ☐ Tidak"],["4","Butir terlambat dibahas pada rapat berikutnya.","☐ Ya ☐ Tidak"],["5","Butir tertutup memiliki bukti dan arsip.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-011","g":"Kesekretariatan dan Administrasi","t":"Pengelolaan Dokumen Keputusan dan Kebijakan","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[501,504],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara pencatatan, penomoran, penyimpanan, pengendalian versi, dan pencabutan dokumen keputusan dan kebijakan BEM agar setiap dokumen yang berlaku dapat ditemukan, tidak ganda, dan jelas statusnya."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk Keputusan Presiden, keputusan rapat, berita acara forum permusyawaratan, SOP, kebijakan internal, serta dokumen eksternal yang mengikat BEM (misalnya AD/ART dan keputusan BPM atau kampus). Proses pengambilan keputusan diatur pada SOP-GOV-002 dan perubahan kebijakan pada SOP-GOV-011."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 11 ayat (2) huruf b (pengangkatan Menteri dan Kabiro oleh Presiden secara prerogatif).","AD Pasal 21 ayat (2) dan Pasal 22 (peraturan yang ada tetap berlaku selama tidak bertentangan dengan AD/ART).","ART Pasal 7 ayat (8) dan Pasal 8 ayat (7) (berita acara disahkan Ketua STDIIS).","ART Pasal 4 huruf a dan f (kebijakan pelaksanaan kegiatan dan penandatanganan dokumen).","Pedoman Penyusunan SOP, Bagian V (standar pengendalian dokumen)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Register Dokumen","Daftar induk seluruh dokumen keputusan dan kebijakan berikut kode, versi, pemilik, dan status."],["Register Keputusan","Daftar keputusan yang memuat nomor, tanggal, judul, tingkat, penanggung jawab, dan status tindak lanjut."],["Versi berlaku","Revisi dokumen terbaru yang telah disahkan dan berlaku."],["Dokumen eksternal","Dokumen yang diterbitkan pihak lain dan mengikat BEM, dicatat sesuai nomor aslinya."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Status dokumen: Draf, Dalam uji coba, Berlaku, Diganti, Dicabut, atau Diarsipkan.","Dokumen berlaku sejak tanggal ditetapkan; dokumen yang memerlukan persetujuan pihak luar belum berlaku sebelum persetujuan diperoleh.","Setiap dokumen memiliki nomor unik; dokumen eksternal dicatat sesuai nomor aslinya dan tidak diberi nomor BEM.","Dokumen lama yang diganti ditandai Diganti, dicantumkan penggantinya, dan dipindahkan ke arsip; versi lama tidak dihapus.","Dokumen yang bertentangan dengan AD/ART atau aturan kampus tidak sah dan ditinjau ulang (SOP- GOV-002)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Penyusun dokumen","R","Menyusun dokumen dan menyerahkan versi final."],["Admin kesekretariatan","R","Memberi nomor, mencatat pada register, dan menandai status."],["Kabiro Kesekretariatan","R","Memeriksa kelengkapan register dan versi."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas Register Dokumen dan Register Keputusan."],["Presiden","R","Menetapkan Keputusan Presiden dan mengesahkan kebijakan internal."],["Irjen","C","Memeriksa konsistensi dokumen dengan AD/ART pada pemeriksaan berkala."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Dokumen final yang telah ditetapkan atau disahkan.","Lembar Keputusan atau notulen yang menjadi dasarnya.","Register Dokumen dan Register Keputusan terkini."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan dokumen final: Admin menerima dokumen final dan dasar penetapannya; dokumen draf tidak dicatat sebagai berlaku.","Admin kesekretariatan","Dokumen, dasar","Dokumen diterima","1 hari kerja"],["2","Pemeriksaan: Memeriksa tanda tangan, tanggal, dasar hukum, dan persetujuan pihak luar bila diperlukan.","Kabiro Kesekretariatan","Dokumen","Layak dicatat","1 hari kerja"],["3","Penomoran dan pencatatan: Memberi nomor sesuai SOP-ADM- 003 (dokumen BEM), mencatat pada Register Dokumen atau Register Keputusan, dan menetapkan status.","Admin kesekretariatan","Dokumen layak","Entri register","1 hari kerja"],["4","Pengendalian versi: Memastikan hanya versi berlaku yang tersedia di folder aktif; versi lama diberi status Diganti dan dipindahkan ke arsip.","Admin dokumen","Versi baru dan lama","Versi terkendali","1 hari kerja"],["5","Sosialisasi: Mengumumkan dokumen baru atau perubahan kepada pengurus terkait melalui kanal resmi dan mencatat penerimanya.","Admin, Sekjen","Dokumen berlaku","Pengumuman terkirim","3 hari kerja"],["6","Peninjauan berkala: Meninjau Register Dokumen untuk dokumen yang perlu dievaluasi, kedaluwarsa, atau bertentangan.","Sekjen dan Irjen","Register","Daftar dokumen ditinjau","Setiap bulan"],["7","Pencabutan: Dokumen dicabut berdasarkan keputusan berwenang; status diubah menjadi Dicabut dan alasannya dicatat.","Presiden, Sekjen","Keputusan pencabutan","Status Dicabut","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dokumen yang telah ditetapkan dicatat paling lambat 1 hari kerja dan disosialisasikan paling lambat 3 hari kerja sejak pengesahan (selaras dengan SOP-GOV-001). Hasil akhir: entri register lengkap dan hanya versi berlaku yang tersedia."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Dokumen tanpa nomor atau tanpa tanda tangan ditolak untuk dicatat sebagai berlaku dan dikembalikan kepada penyusun.","Dokumen eksternal dengan nomor ganda atau periode tidak seragam (misalnya Keputusan Induk BPM) dicatat dengan nomor aslinya disertai catatan temuan dan dilaporkan kepada Sekjen.","Dugaan pemalsuan atau perubahan dokumen tanpa wewenang dilaporkan kepada Irjen.","Dua dokumen yang saling bertentangan diselesaikan melalui Rapat Pimpinan (SOP-GOV-005); usulan perubahan AD/ART mengikuti AD Bab XI dan ART Bab VII."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% dokumen keputusan dan kebijakan tercatat pada register.","Tidak ada nomor ganda pada dokumen BEM.","100% dokumen berlaku memiliki versi dan status yang jelas.","Dokumen baru tersosialisasi dalam 3 hari kerja pada minimal 90% kasus."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Dokumen.","Register Keputusan.","Dokumen berlaku dan dokumen yang diganti atau dicabut.","Bukti sosialisasi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Dokumen Keputusan dan Kebijakan) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen merekap Register Dokumen dan Register Keputusan setiap bulan; Irjen menilai konsistensi dan kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima dokumen final → Periksa → Nomori dan catat → Kendalikan versi → Sosialisasi → Tinjau berkala → Cabut atau arsipkan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Register Dokumen","Kode atau nomor; judul; jenis; versi; tanggal berlaku; pemilik; pengesah; status; lokasi arsip; riwayat perubahan."],["Register Keputusan","Nomor; tanggal; judul; tingkat; penanggung jawab; status tindak lanjut; lokasi arsip."],["Formulir Pencabutan Dokumen","Dokumen yang dicabut; dasar; alasan; dokumen pengganti; pengesah; tanggal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Dokumen final bertanda tangan dan bertanggal.","☐ Ya ☐ Tidak"],["2","Nomor unik dan tercatat pada register.","☐ Ya ☐ Tidak"],["3","Status dan versi sesuai.","☐ Ya ☐ Tidak"],["4","Versi lama telah ditandai dan diarsipkan.","☐ Ya ☐ Tidak"],["5","Sosialisasi dan penerimanya tercatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-012","g":"Kesekretariatan dan Administrasi","t":"Pengarsipan Dokumen Fisik","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[505,508],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara penerimaan, pengelompokan, penyimpanan, pengamanan, dan pemeliharaan dokumen fisik BEM agar dokumen asli yang penting tersimpan aman, tertata, dan mudah ditemukan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk dokumen cetak asli milik BEM, termasuk surat, keputusan, berita acara, notulen bertanda tangan, proposal, LPJ, dan bukti transaksi. Dokumen digital diatur pada SOP-ADM-013 dan pembatasan akses dokumen rahasia pada SOP-ADM-020."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (3) (semua sumber dana didokumentasikan dengan bukti penerimaan resmi).","AD Pasal 17 ayat (1) dan (2) (laporan pertanggungjawaban, transparansi, dan akuntabilitas).","ART Pasal 3 (Kewajiban BEM) huruf e dan g (amanah, transparan, dan akuntabel dalam keuangan serta laporan berkala).","ART Pasal 11 huruf i (larangan korupsi, manipulasi, dan penyelewengan dana).","SOP-ADM-014 (penamaan dan struktur) dan SOP-AST-09 (penyimpanan barang, akan disusun)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Arsip fisik","Dokumen cetak asli yang disimpan sebagai bukti kegiatan dan keputusan organisasi."],["Kode arsip","Kode klasifikasi yang menunjukkan kelompok dan tahun dokumen."],["Retensi","Jangka waktu dokumen disimpan sebelum ditinjau untuk dimusnahkan atau diserahkan."],["Berita Acara Pemusnahan","Dokumen resmi yang mencatat dokumen yang dimusnahkan, alasan, dan pihak yang menyetujui."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Dokumen keputusan, kebijakan, berita acara, LPJ, dan bukti keuangan disimpan permanen selama organisasi ada dan diserahkan pada transisi kabinet (SOP-TRN-003, akan disusun).","Surat rutin dan notulen disimpan sekurang-kurangnya dua periode kabinet (usulan; ditetapkan final oleh Rapat Kabinet).","Pemusnahan hanya dengan Berita Acara Pemusnahan yang disetujui Sekjen dan Presiden serta diperiksa Irjen; dokumen yang menjadi bukti perkara atau pemeriksaan tidak dimusnahkan.","Arsip fisik disimpan di sekretariat pada lemari yang dapat dikunci dan dijauhkan dari kelembapan, api, dan hama."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Unit penyerah dokumen","R","Menyerahkan dokumen asli yang lengkap dan sudah final."],["Admin dokumen","R","Mengelompokkan, memberi kode, menyimpan, dan memelihara arsip."],["Kabiro Kesekretariatan","R","Memeriksa kerapian arsip dan mengusulkan pemusnahan."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas keamanan dan kelengkapan arsip fisik."],["Presiden","C","Menyetujui pemusnahan dokumen."],["Irjen","C","Memeriksa arsip dan berita acara pemusnahan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Dokumen asli final dan telah dicatat pada register.","Kode arsip dan daftar isi arsip.","Lemari dan map arsip yang memadai.","Buku Peminjaman Dokumen (SOP-ADM-016)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan arsip: Admin menerima dokumen asli dari unit penyerah dan memeriksa kelengkapan, tanda tangan, dan nomor.","Admin dokumen","Dokumen asli","Dokumen diterima","1 hari kerja"],["2","Pengelompokan: Mengelompokkan dokumen berdasarkan kelompok (tata kelola, keuangan, kegiatan, dan seterusnya) dan tahun, lalu memberi kode arsip.","Admin dokumen","Dokumen","Dokumen berkode","2 hari kerja"],["3","Pencatatan: Mencatat pada Daftar Isi Arsip: kode, judul, tanggal, jumlah lembar, dan lokasi simpan.","Admin dokumen","Dokumen berkode","Daftar isi arsip","2 hari kerja"],["4","Penyimpanan: Menyimpan dokumen pada map dan lemari sesuai kode dan mengunci lemari; dokumen rahasia dipisah (SOP-ADM-020).","Admin dokumen","Dokumen","Arsip tersimpan","Hari yang sama"],["5","Pemeriksaan berkala: Mencocokkan fisik arsip dengan daftar isi dan memeriksa kondisi dokumen.","Kabiro Kesekretariatan","Daftar isi, arsip","Catatan pemeriksaan","Setiap tiga bulan"],["6","Peninjauan retensi: Mengidentifikasi dokumen yang telah melewati retensi dan mengusulkan pemusnahan atau penyerahan.","Kabiro Kesekretariatan","Daftar retensi","Usulan pemusnahan","Setiap akhir periode"],["7","Pemusnahan: Memusnahkan dokumen yang disetujui dengan Berita Acara Pemusnahan dan mencatatnya pada daftar isi.","Sekjen, Presiden","Usulan, persetujuan","Berita Acara Pemusnahan","Sesuai persetujuan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dokumen diterima dan dicatat paling lambat 2 hari kerja setelah diserahkan; penyimpanan pada hari yang sama setelah pengkodean. Hasil akhir: arsip fisik tertata, tercatat, dan aman."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Dokumen asli yang diperlukan untuk kepentingan mendesak dipinjam sesuai SOP-ADM-016.","Dokumen hilang atau rusak dilaporkan kepada Sekjen dan dicatat; rekonstruksi memakai salinan digital bila ada.","Kebakaran, banjir, atau pencurian dilaporkan segera kepada Presiden dan Irjen serta ditangani sesuai SOP-RSK (akan disusun).","Dokumen yang diminta pihak berwenang diserahkan atas persetujuan Presiden dengan bukti serah terima."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% dokumen penting tercatat pada Daftar Isi Arsip.","Arsip fisik cocok dengan daftar pada setiap pemeriksaan berkala.","Tidak ada dokumen penting hilang.","Pemusnahan seluruhnya didukung Berita Acara."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Isi Arsip.","Arsip fisik tertata.","Catatan pemeriksaan berkala.","Berita Acara Pemusnahan, bila ada. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Arsip Fisik (pindai daftar isi)) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Kesekretariatan memeriksa arsip setiap tiga bulan; Irjen menilai pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima dokumen asli → Kelompokkan dan beri kode → Catat daftar isi → Simpan dan kunci → Periksa berkala → Tinjau retensi → Musnahkan atau serahkan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Isi Arsip","Kode arsip; judul; tanggal; jumlah lembar; lokasi simpan; retensi; status."],["Berita Acara Pemusnahan","Daftar dokumen; alasan; tanggal; saksi; persetujuan Sekjen dan Presiden; pemeriksaan Irjen."],["Formulir Serah Terima Arsip","Dokumen yang diserahkan; jumlah; kondisi; penyerah dan penerima; tanggal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Dokumen asli lengkap dan bertanda tangan.","☐ Ya ☐ Tidak"],["2","Kode arsip dan daftar isi terisi.","☐ Ya ☐ Tidak"],["3","Lemari terkunci dan kondisi ruang aman.","☐ Ya ☐ Tidak"],["4","Pemeriksaan berkala dilakukan.","☐ Ya ☐ Tidak"],["5","Pemusnahan memiliki berita acara.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-013","g":"Kesekretariatan dan Administrasi","t":"Pengarsipan Dokumen Digital","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[509,512],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara menyimpan, memindai, memberi metadata, dan memelihara dokumen digital BEM pada repositori resmi agar dokumen tidak hanya tersimpan pada perangkat atau akun pribadi dan dapat dicari serta dipulihkan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh dokumen digital BEM, termasuk hasil pindai dokumen fisik. Penamaan dan struktur folder diatur pada SOP-ADM-014, hak akses dan pencadangan pada SOP-ADM-015, dan pengamanan lebih lanjut pada SOP-RSK-08 (akan disusun)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["Pedoman Penyusunan SOP, Prinsip penyusunan (dokumen final disimpan di repositori resmi, bukan hanya di perangkat atau akun pribadi).","ART Pasal 3 (Kewajiban BEM) huruf e dan g (amanah, transparan, dan laporan berkala).","ART Pasal 11 huruf k (larangan menggunakan fasilitas atau nama organisasi untuk kepentingan pribadi).","SOP-ADM-014 dan SOP-ADM-015."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Repositori resmi","Penyimpanan digital milik organisasi yang dikelola menggunakan akun organisasi."],["Folder Kerja","Tempat draf dan dokumen yang masih dikerjakan."],["Folder Arsip","Tempat dokumen final yang tidak lagi diubah."],["Metadata","Keterangan dokumen: jenis, nomor, tanggal, pemilik, versi, dan status."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Repositori resmi dibuat dengan akun organisasi dan dimiliki organisasi, bukan perorangan; pemilik dan cadangan pemilik ditetapkan Sekjen.","Draf disimpan di Folder Kerja; dokumen final dalam format PDF disimpan di Folder Arsip dan bersifat hanya-baca.","Hasil pindai dokumen fisik dibuat dengan keterbacaan yang jelas (usulan 300 dpi) dan diberi nama sesuai SOP-ADM-014.","Dokumen yang tersimpan hanya pada perangkat pribadi dianggap belum diarsipkan dan harus diunggah dalam 3 hari kerja.","Dokumen rahasia disimpan sesuai SOP-ADM-020."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pengurus pembuat dokumen","R","Mengunggah dokumen final ke repositori resmi sesuai jadwal."],["Admin dokumen","R","Memeriksa, memberi metadata, memindahkan ke Folder Arsip, dan mengunci."],["Kabiro Kesekretariatan","R","Memeriksa kepatuhan unggah dan kerapian repositori."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas repositori resmi dan kelengkapan arsip digital."],["Irjen","C","Memeriksa kelengkapan arsip digital pada pemeriksaan berkala."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Dokumen final yang telah disahkan.","Akses ke repositori resmi.","Aturan penamaan dan struktur folder (SOP-ADM-014).","Perangkat pemindai, bila dokumen fisik."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pembuatan repositori: Sekjen menetapkan repositori resmi, pemilik, dan cadangan pemilik, serta membuat struktur folder.","Sekjen","Struktur folder","Repositori siap","Awal periode"],["2","Pengunggahan: Pengurus mengunggah dokumen final ke folder unitnya dengan nama sesuai aturan; draf tetap di Folder Kerja.","Pengurus pembuat dokumen","Dokumen final","Dokumen terunggah","3 hari kerja setelah final"],["3","Pemindaian: Dokumen fisik asli dipindai, diperiksa keterbacaannya, dan diberi nama sesuai aturan.","Admin dokumen","Dokumen fisik","Berkas pindai","2 hari kerja"],["4","Pemeriksaan dan metadata: Memeriksa kelengkapan, nama, format PDF, dan mengisi metadata pada Register Dokumen.","Admin dokumen","Berkas","Berkas terverifikasi","2 hari kerja"],["5","Pengunciran: Memindahkan berkas ke Folder Arsip dan menjadikannya hanya-baca.","Admin dokumen","Berkas terverifikasi","Arsip digital","1 hari kerja"],["6","Pemeriksaan kepatuhan: Mencocokkan Register Dokumen dengan isi repositori dan menandai dokumen yang belum diunggah.","Kabiro Kesekretariatan","Register, repositori","Daftar kekurangan","Setiap bulan"],["7","Tindak lanjut: Menagih dokumen yang belum diunggah dan membersihkan dokumen ganda atau salah folder.","Admin dokumen, pemilik dokumen","Daftar kekurangan","Repositori rapi","5 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dokumen final diunggah paling lambat 3 hari kerja setelah disahkan dan dikunci pada Folder Arsip paling lambat 5 hari kerja. Hasil akhir: arsip digital lengkap, bernama baku, dan tercatat pada Register Dokumen."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Dokumen yang terlambat diunggah ditandai pada rekap bulanan dan dilaporkan kepada Sekjen.","Dokumen salah folder atau salah nama diperbaiki oleh Admin dan pemilik dokumen diberi tahu.","Dokumen yang tidak terbaca setelah dipindai dipindai ulang atau diminta dari pemilik.","Pengurus yang menyimpan dokumen organisasi hanya pada akun pribadi diminta mengunggah ulang dan dibina oleh Sekjen; pelanggaran berulang diteruskan kepada Irjen."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 95% dokumen final diunggah dalam 3 hari kerja.","100% dokumen berlaku tersedia pada Folder Arsip.","Register Dokumen cocok dengan isi repositori pada setiap pemeriksaan.","Tidak ada dokumen organisasi yang hanya ada pada perangkat pribadi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Arsip digital pada Folder Arsip.","Register Dokumen yang diperbarui.","Daftar kekurangan unggah.","Catatan pemeriksaan bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Repositori dan Arsip Digital) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Kesekretariatan memeriksa kepatuhan unggah setiap bulan; Sekjen melaporkan hasil pada evaluasi bulanan; Irjen menilai pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Siapkan repositori → Unggah atau pindai → Periksa dan beri metadata → Kunci ke Folder Arsip → Periksa kepatuhan → Tindak lanjut → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Unggah Dokumen","Nama dokumen; nomor atau kode; unit; tanggal final; lokasi unggah; pengunggah."],["Rekap Kepatuhan Unggah","Periode; unit; dokumen final; terunggah; terlambat; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Dokumen final berformat PDF dan terbaca.","☐ Ya ☐ Tidak"],["2","Nama berkas sesuai aturan.","☐ Ya ☐ Tidak"],["3","Metadata pada Register Dokumen terisi.","☐ Ya ☐ Tidak"],["4","Berkas berada pada Folder Arsip dan hanya-baca.","☐ Ya ☐ Tidak"],["5","Tidak ada salinan resmi hanya pada perangkat pribadi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-014","g":"Kesekretariatan dan Administrasi","t":"Penamaan File dan Struktur Folder","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[513,516],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan aturan baku penamaan file dan struktur folder repositori resmi BEM agar dokumen dapat dicari, dibedakan versinya, dan diserahterimakan antarkabinet dengan mudah."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus dan panitia yang membuat, menyimpan, atau membagikan dokumen digital atas nama BEM. Penyimpanan dan pengarsipan diatur pada SOP-ADM-013, sedangkan hak akses pada SOP- ADM-015."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["Pedoman Penyusunan SOP, Bagian V (sistem kode dokumen dan data pengendalian wajib).","ART Pasal 3 (Kewajiban BEM) huruf g (laporan berkala).","SOP-ADM-011 (Register Dokumen) dan SOP-ADM-013."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Konvensi penamaan","Pola baku nama file yang berisi tanggal, kode, judul singkat, dan versi."],["Versi","Nomor urutan revisi dokumen, ditulis v00, v01, dan seterusnya."],["Folder tingkat 1","Folder utama yang mengikuti dua belas kelompok SOP pada Pedoman."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pola nama file (usulan): TAHUN-BULAN-TANGGAL_KODE_Judul-singkat_vNN.ekstensi, misalnya 2026-10-05_SOP-ADM-001_Pengelolaan-Surat-Masuk_v00.pdf.","Tanpa spasi, tanpa karakter khusus; kata dipisah dengan tanda hubung; judul singkat maksimal 6 kata.","Kode dokumen memakai nomor surat atau kode SOP; dokumen tanpa nomor memakai kode jenis (misalnya NTL untuk notulen, PRO untuk proposal, LPJ untuk laporan pertanggungjawaban).","Nomor versi naik setiap perubahan isi; versi final berlaku ditandai dengan menghapus kata draf dan disimpan PDF pada Folder Arsip."]},{"tb":{"h":["Nomor","Folder tingkat 1"],"r":[["01","Tata Kelola"],["02","Keanggotaan dan SDM"],["03","Kesekretariatan dan Administrasi"],["04","Keuangan dan Pengadaan"],["05","Program Kerja dan Kegiatan"],["06","Komunikasi dan Informasi"],["07","Hubungan Eksternal dan Kemitraan"],["08","Advokasi dan Aspirasi Mahasiswa"],["09","Risiko, Etika, dan Penanganan Masalah"],["10","Inventaris dan Aset"],["11","Monitoring, Evaluasi, dan Pengawasan"],["12","Transisi dan Keberlanjutan Kabinet"]]}},{"ul":["Di dalam setiap folder tingkat 1 dibuat subfolder per tahun kepengurusan, kemudian per jenis dokumen atau kegiatan, dan masing-masing memiliki Folder Kerja dan Folder Arsip."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pengurus dan panitia","R","Menamai dan menyimpan dokumen sesuai aturan."],["Admin dokumen","R","Memeriksa nama dan lokasi file, memperbaiki bila keliru, dan menjaga struktur folder."],["Kabiro Kesekretariatan","R","Menyusun dan menjaga templat struktur folder serta melatih pengurus."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas konvensi penamaan dan struktur folder."],["Menteri dan Kabiro","I","Memastikan anggota unitnya mematuhi aturan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Struktur folder induk.","Daftar kode dokumen dan jenis.","Templat nama file.","Panduan singkat bagi pengurus."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan struktur: Sekjen menetapkan struktur folder tingkat 1 dan subfolder standar pada repositori resmi.","Sekjen","Pedoman","Struktur folder","Awal periode"],["2","Sosialisasi: Menyampaikan aturan penamaan dan struktur kepada seluruh pengurus melalui kanal resmi dan tutorial singkat.","Kabiro Kesekretariatan","Panduan","Pengurus memahami aturan","Minggu pertama"],["3","Penamaan saat membuat file: Pengurus menamai file sesuai pola dan menaikkan versi setiap perubahan isi.","Pengurus","Dokumen","File bernama baku","Setiap file dibuat"],["4","Penyimpanan: Pengurus menyimpan file pada folder yang sesuai; draf pada Folder Kerja, final pada Folder Arsip melalui Admin.","Pengurus, Admin","File","File pada lokasi benar","Sesuai SOP-ADM- 013"],["5","Pemeriksaan: Admin memeriksa nama dan lokasi file secara acak dan menandai yang keliru.","Admin dokumen","Repositori","Daftar penyimpangan","Setiap bulan"],["6","Perbaikan: Admin memperbaiki nama atau lokasi file dan memberi tahu pemiliknya.","Admin dokumen","Daftar penyimpangan","File diperbaiki","3 hari kerja"],["7","Tinjauan aturan: Sekjen meninjau aturan pada evaluasi tengah periode dan mengusulkan perubahan melalui SOP-GOV-011.","Sekjen","Hasil pemeriksaan","Penegasan atau perubahan aturan","Tengah periode"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Struktur folder dibuat pada minggu pertama kabinet; file dinamai saat dibuat dan diperbaiki paling lambat 3 hari kerja setelah ditemukan keliru. Hasil akhir: repositori yang rapi dan seragam."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["File kiriman pihak luar tetap memakai nama aslinya dan disalin dengan nama baku pada repositori.","Dokumen yang tidak jelas kodenya memakai kode LAIN dan dicatat pada Register Dokumen.","Perubahan struktur folder setelah repositori berjalan dilakukan oleh Admin dengan persetujuan Sekjen dan menjaga tautan lama.","Pelanggaran berulang terhadap aturan ditegur Sekjen dan dapat dibawa ke Irjen untuk pembinaan."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 95% file pada Folder Arsip bernama sesuai pola.","Tidak ada file organisasi di luar struktur folder resmi.","Pengurus baru memahami aturan dalam minggu pertama.","Penyimpangan per bulan menurun."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Struktur folder repositori resmi.","Panduan penamaan file.","Daftar penyimpangan dan perbaikannya. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Panduan) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Admin dokumen memeriksa penamaan setiap bulan; Sekjen meninjau pada evaluasi tengah periode; Irjen menilai pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tetapkan struktur → Sosialisasi → Namai file saat dibuat → Simpan pada folder benar → Periksa bulanan → Perbaiki → Tinjau aturan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Panduan Singkat Penamaan File","Pola nama; contoh; daftar kode jenis; aturan versi; larangan karakter."],["Templat Struktur Folder","Folder tingkat 1; subfolder tahun; Folder Kerja dan Folder Arsip; pemilik folder."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Nama file sesuai pola dan tanpa spasi.","☐ Ya ☐ Tidak"],["2","Versi dan kode dokumen benar.","☐ Ya ☐ Tidak"],["3","File berada pada folder tingkat 1 yang sesuai.","☐ Ya ☐ Tidak"],["4","Final berformat PDF pada Folder Arsip.","☐ Ya ☐ Tidak"],["5","Penyimpangan bulan ini telah diperbaiki.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-015","g":"Kesekretariatan dan Administrasi","t":"Hak Akses, Pencadangan, dan Pemulihan Dokumen","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[517,520],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan pembagian hak akses, jadwal pencadangan, dan cara pemulihan dokumen digital BEM agar dokumen terlindungi dari akses tidak berwenang, kehilangan, dan kerusakan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk repositori resmi BEM, akun organisasi, dan dokumen digital seluruh unit. Pengelolaan akun media sosial dan akses digital komunikasi diatur pada SOP-KOM-13 (akan disusun); penanganan kebocoran data pada SOP-RSK-09 (akan disusun)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 9 ayat (1) dan (2) (berhentinya dan diberhentikannya anggota).","ART Pasal 11 huruf i dan k (larangan penyelewengan dan penyalahgunaan fasilitas atau nama organisasi).","ART Pasal 3 (Kewajiban BEM) huruf e (pengelolaan secara amanah).","Pedoman Penyusunan SOP, Prinsip penyusunan (perlindungan data sejak awal).","SOP-ADM-013 dan SOP-ADM-020."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Hak akses","Kewenangan pengguna terhadap dokumen: Pemilik, Penyunting, Pengomentar, atau Pembaca."],["Prinsip akses minimal","Pengguna hanya diberi akses sebatas yang diperlukan untuk tugasnya."],["Pencadangan","Penyalinan dokumen ke lokasi lain untuk pemulihan bila terjadi kehilangan."],["Pemulihan","Pengembalian dokumen dari cadangan ke repositori."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pemilik repositori: Sekjen dan satu cadangan pemilik yang ditunjuk Presiden; Penyunting: Admin dan penanggung jawab unit; Pembaca: pengurus lain sesuai kebutuhan.","Akun organisasi memakai verifikasi dua langkah (usulan) dan kata sandi tidak dibagikan melalui kanal umum.","Pencadangan (usulan): otomatis atau manual mingguan ke penyimpanan kedua dan bulanan ke penyimpanan terpisah yang dikelola organisasi.","Uji pemulihan dilakukan setiap tiga bulan dengan memulihkan sampel dokumen.","Akses pengurus yang berhenti atau diberhentikan dicabut paling lambat 1 hari kerja setelah keputusan atau berakhirnya masa jabatan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pengguna (pengurus)","R","Menjaga akun dan tidak membagikan akses atau dokumen kepada pihak tidak berwenang."],["Admin dokumen","R","Mengatur hak akses, menjalankan pencadangan, dan mengikuti uji pemulihan."],["Kabiro Kesekretariatan","R","Memeriksa daftar akses dan hasil pencadangan."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas hak akses, pencadangan, dan pemulihan."],["Presiden","C","Menyetujui akses khusus dan menunjuk cadangan pemilik."],["Irjen","C","Memeriksa daftar akses dan hasil uji pemulihan secara berkala."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar pengurus aktif (SOP-ADM-017).","Matriks hak akses per folder.","Penyimpanan cadangan yang dikelola organisasi.","Jadwal pencadangan dan uji pemulihan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan matriks akses: Sekjen menetapkan matriks hak akses per folder berdasarkan jabatan dan unit.","Sekjen","Struktur organisasi","Matriks akses","Awal periode"],["2","Pemberian akses: Admin memberi akses sesuai matriks setelah pengurus dilantik dan dicatat pada Daftar Akses.","Admin dokumen","Matriks, daftar pengurus","Akses aktif","1 hari kerja"],["3","Perubahan akses: Perubahan jabatan atau tugas diajukan melalui Sekjen dan dicatat; akses khusus memerlukan persetujuan Presiden.","Admin, Sekjen","Permintaan perubahan","Akses diperbarui","2 hari kerja"],["4","Pencabutan akses: Mencabut akses pengurus yang berhenti, diberhentikan, atau selesai tugasnya dan memindahkan kepemilikan dokumennya.","Admin dokumen","Keputusan, daftar pengurus","Akses dicabut","1 hari kerja"],["5","Pencadangan: Menjalankan pencadangan mingguan dan bulanan serta mencatat hasilnya pada Log Pencadangan.","Admin dokumen","Repositori","Cadangan dan log","Mingguan dan bulanan"],["6","Uji pemulihan: Memulihkan sampel dokumen dari cadangan untuk menguji keandalannya dan mencatat hasil.","Admin, Kabiro","Cadangan","Laporan uji","Setiap tiga bulan"],["7","Peninjauan akses: Mencocokkan Daftar Akses dengan daftar pengurus aktif dan mencabut akses yang tidak diperlukan.","Kabiro Kesekretariatan","Daftar akses","Catatan peninjauan","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Akses diberikan paling lambat 1 hari kerja setelah pengurus dilantik dan dicabut paling lambat 1 hari kerja setelah berhenti. Pencadangan dilakukan mingguan dan bulanan; uji pemulihan setiap tiga bulan. Hasil akhir: akses sesuai tugas, cadangan tersedia, dan pemulihan teruji."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kehilangan atau pencurian akun dilaporkan segera kepada Sekjen; kata sandi diganti dan aktivitas akun diperiksa sesuai SOP-RSK-08 dan SOP-RSK-09 (akan disusun).","Dokumen terhapus tidak sengaja dipulihkan dari cadangan terbaru dan pemilik dokumen diberi tahu.","Akses darurat bagi pengganti sementara diberikan Presiden atau Sekjen dan dicabut ketika tugas selesai (SOP-GOV-009).","Dugaan akses tidak sah dilaporkan kepada Irjen untuk diperiksa sesuai ART Pasal 13."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Daftar Akses cocok dengan daftar pengurus aktif pada setiap peninjauan.","Akses dicabut dalam 1 hari kerja untuk 100% pengurus yang berhenti.","Pencadangan dilakukan sesuai jadwal minimal 95%.","Uji pemulihan berhasil pada setiap pelaksanaan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Matriks hak akses.","Daftar Akses.","Log Pencadangan.","Laporan uji pemulihan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Keamanan dan Cadangan) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Kesekretariatan meninjau akses setiap bulan dan hasil cadangan setiap pekan; Irjen menilai pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tetapkan matriks akses → Beri akses → Ubah atau cabut akses → Cadangkan → Uji pemulihan → Tinjau akses bulanan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Akses","Nama; jabatan; unit; folder; tingkat akses; tanggal diberikan; tanggal dicabut; persetujuan."],["Log Pencadangan","Tanggal; jenis; lokasi cadangan; ukuran; hasil; pelaksana."],["Laporan Uji Pemulihan","Tanggal; sampel dokumen; hasil; kendala; tindak lanjut."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Akses sesuai matriks dan prinsip akses minimal.","☐ Ya ☐ Tidak"],["2","Akses pengurus yang berhenti telah dicabut.","☐ Ya ☐ Tidak"],["3","Pencadangan mingguan dan bulanan berjalan.","☐ Ya ☐ Tidak"],["4","Uji pemulihan triwulan telah dilakukan.","☐ Ya ☐ Tidak"],["5","Daftar Akses cocok dengan daftar pengurus aktif.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-016","g":"Kesekretariatan dan Administrasi","t":"Peminjaman dan Pengembalian Dokumen","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[521,524],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara peminjaman dan pengembalian dokumen fisik maupun akses dokumen digital yang tersimpan pada arsip BEM agar dokumen tidak hilang, rusak, atau bocor."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk dokumen fisik pada arsip sekretariat dan dokumen digital berakses terbatas yang dipinjam pengurus atau pihak luar. Peminjaman barang atau aset diatur pada SOP-AST-03 dan SOP-AST-04 (akan disusun)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 11 huruf i dan k (larangan penyelewengan dan penyalahgunaan fasilitas atau nama organisasi).","ART Pasal 3 (Kewajiban BEM) huruf e (pengelolaan amanah dan akuntabel).","SOP-ADM-012 (arsip fisik) dan SOP-ADM-020 (dokumen rahasia)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Peminjaman dokumen","Pemakaian sementara dokumen asli dari arsip atau pemberian akses sementara pada dokumen digital."],["Peminjam","Pengurus atau pihak luar yang meminta dokumen."],["Buku Peminjaman Dokumen","Catatan setiap peminjaman, pengembalian, dan kondisi dokumen."],["Salinan kerja","Fotokopi atau salinan digital yang diberikan sebagai pengganti dokumen asli."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Dokumen asli sebaiknya tidak keluar sekretariat; permintaan diutamakan dipenuhi dengan salinan kerja.","Batas peminjaman dokumen fisik (usulan) paling lama 3 hari kerja dan dapat diperpanjang satu kali.","Dokumen rahasia atau dokumen keuangan asli hanya dipinjam atas persetujuan Sekjen dan, bila diperlukan, Presiden.","Peminjaman oleh pihak luar BEM memerlukan surat permohonan dan persetujuan Presiden."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Peminjam","R","Mengajukan permintaan, memakai dokumen sesuai tujuan, dan mengembalikannya utuh tepat waktu."],["Admin dokumen","R","Memeriksa permintaan, menyerahkan dokumen, mencatat, dan memeriksa kondisi saat pengembalian."],["Sekretaris Jenderal","A","Menyetujui peminjaman dan bertanggung jawab akhir atas dokumen yang keluar dari arsip."],["Presiden","C","Menyetujui peminjaman dokumen rahasia atau oleh pihak luar."],["Irjen","I","Menerima laporan dokumen hilang atau rusak dan memeriksa buku peminjaman."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Permintaan Peminjaman.","Buku Peminjaman Dokumen.","Daftar Isi Arsip.","Kartu identitas peminjam bila pihak luar."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Permintaan: Peminjam mengisi Formulir Permintaan Peminjaman: dokumen, tujuan, dan lama pinjam.","Peminjam","Formulir","Permintaan tercatat","Sesuai kebutuhan"],["2","Pemeriksaan: Admin memeriksa ketersediaan dokumen dan klasifikasinya serta menawarkan salinan kerja bila memungkinkan.","Admin dokumen","Permintaan, Daftar Isi Arsip","Layak atau perlu persetujuan","Hari yang sama"],["3","Persetujuan: Sekjen menyetujui atau menolak dengan alasan; dokumen rahasia atau permintaan pihak luar diteruskan kepada Presiden.","Sekjen, Presiden","Permintaan","Persetujuan","1 hari kerja"],["4","Penyerahan: Admin menyerahkan dokumen, mencatat kondisi, tanggal, dan batas kembali pada buku, dan peminjam menandatangani.","Admin dokumen","Dokumen","Peminjaman tercatat","Hari yang sama"],["5","Pengingat: Admin mengingatkan peminjam 1 hari sebelum batas kembali.","Admin dokumen","Buku Peminjaman","Pengingat terkirim","H-1 batas kembali"],["6","Pengembalian: Peminjam mengembalikan dokumen; Admin memeriksa kelengkapan dan kondisi, mencatat, dan mengembalikan dokumen ke tempat semula.","Peminjam, Admin","Dokumen","Pengembalian tercatat","Paling lambat batas kembali"],["7","Penanganan masalah: Dokumen terlambat, rusak, atau hilang dilaporkan kepada Sekjen dan ditangani sesuai pengecualian.","Admin, Sekjen","Laporan","Keputusan tindak lanjut","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Permintaan diperiksa pada hari yang sama dan diputuskan paling lambat 1 hari kerja. Dokumen dikembalikan paling lambat pada batas kembali. Hasil akhir: dokumen kembali utuh dan buku peminjaman lengkap."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Dokumen terlambat lebih dari 3 hari kerja ditagih Sekjen dan dilaporkan kepada Wakil Presiden.","Dokumen rusak diperbaiki atau diganti salinan sah atas tanggungan peminjam sesuai keputusan Sekjen; kerusakan disengaja dilaporkan kepada Irjen.","Dokumen hilang dilaporkan segera kepada Presiden dan Irjen, dan salinan digital dipakai sebagai pengganti sementara.","Peminjaman mendesak di luar jam sekretariat dilakukan atas izin Sekjen dengan pencatatan susulan pada hari berikutnya."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% peminjaman tercatat pada buku.","Minimal 95% dokumen kembali tepat waktu.","Tidak ada dokumen hilang akibat peminjaman.","Peminjaman dokumen asli menurun karena salinan kerja."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Permintaan Peminjaman.","Buku Peminjaman Dokumen.","Laporan dokumen terlambat, rusak, atau hilang, bila ada. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Peminjaman Dokumen) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Admin dokumen mencocokkan buku dengan arsip setiap bulan; Sekjen memeriksa pada evaluasi bulanan; Irjen menilai pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Permintaan → Pemeriksaan → Persetujuan → Serahkan dan catat → Pengingat → Pengembalian → Periksa kondisi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Peminjaman","Peminjam; unit; dokumen; tujuan; lama pinjam; tanggal; persetujuan."],["Buku Peminjaman Dokumen","Nomor; tanggal pinjam; dokumen; peminjam; kondisi awal; batas kembali; tanggal kembali; kondisi akhir; paraf."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Permintaan dan tujuan jelas.","☐ Ya ☐ Tidak"],["2","Persetujuan sesuai klasifikasi dokumen.","☐ Ya ☐ Tidak"],["3","Kondisi dokumen dicatat saat pinjam dan kembali.","☐ Ya ☐ Tidak"],["4","Pengembalian tepat waktu atau terlambat telah ditindaklanjuti.","☐ Ya ☐ Tidak"],["5","Dokumen kembali ke lokasi arsip.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-017","g":"Kesekretariatan dan Administrasi","t":"Pengelolaan Basis Data Pengurus dan Program Kerja","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[525,528],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara menyusun, memperbarui, mengamankan, dan memakai basis data pengurus dan program kerja BEM agar data yang digunakan untuk undangan, penugasan, pelaporan, dan pemantauan selalu mutakhir dan terlindungi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk data induk pengurus (identitas jabatan, unit, dan kontak) dan data program kerja (nama, penanggung jawab, jadwal, anggaran, dan status). Pengelolaan data pribadi anggota secara lebih luas diatur pada SOP-SDM-18 (akan disusun)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 7, Pasal 8, dan Pasal 9 (susunan, keanggotaan, serta berhenti dan diberhentikannya anggota).","ART Pasal 5 (ketentuan pengurus BEM).","ART Pasal 9 (RAKER dan program kerja tahunan).","Pedoman Penyusunan SOP, Prinsip penyusunan (perlindungan data) dan SOP-SDM-018 (akan disusun)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Basis data pengurus","Daftar terpusat pengurus aktif beserta jabatan, unit, dan kontak resmi."],["Basis data program kerja","Daftar terpusat program kerja beserta penanggung jawab, jadwal, anggaran, dan status."],["Data pribadi","Data yang dapat mengenali seseorang, seperti nomor telepon, alamat, dan identitas."],["Pemilik data","Unit yang bertanggung jawab atas kebenaran suatu kelompok data."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Basis data pengurus memuat hanya data yang diperlukan: nama, jabatan, unit, periode, kontak resmi, dan status aktif; data lain yang bersifat pribadi tidak disimpan kecuali diperlukan dan disetujui Sekjen.","Basis data program kerja bersumber dari program kerja yang disahkan RAKER dan diperbarui sesuai keputusan perubahan.","Akses penuh hanya untuk Sekjen dan Admin; pengurus lain hanya melihat data yang diperlukan.","Data pribadi tidak dibagikan kepada pihak luar tanpa persetujuan yang bersangkutan dan Sekjen."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Admin kesekretariatan","R","Menyusun dan memperbarui basis data berdasarkan keputusan dan laporan unit."],["Menteri dan Kabiro","R","Menyampaikan perubahan data unit dan program kerja dalam batas waktu."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas kebenaran, keamanan, dan penggunaan basis data."],["Presiden","C","Menetapkan pengangkatan dan pemberhentian pengurus yang menjadi dasar pembaruan."],["Irjen","C","Memeriksa kebenaran data pada pemeriksaan berkala."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Keputusan pengangkatan, pemberhentian, atau pergantian pengurus.","Program kerja yang disahkan RAKER.","Templat basis data.","Persetujuan penggunaan data pribadi, bila diperlukan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan awal: Admin menyusun basis data pengurus dari keputusan pelantikan dan basis data program kerja dari hasil RAKER.","Admin kesekretariatan","Keputusan, program kerja","Basis data awal","3 hari kerja setelah pelantikan dan RAKER"],["2","Verifikasi: Menteri dan Kabiro memeriksa data unitnya dan memberi koreksi.","Menteri, Kabiro","Basis data awal","Data terverifikasi","2 hari kerja"],["3","Pengesahan data: Sekjen menetapkan basis data sebagai data induk dan mengunci versi awal.","Sekjen","Data terverifikasi","Data induk","1 hari kerja"],["4","Pembaruan: Setiap perubahan (pengangkatan, pemberhentian, pengunduran diri, perubahan program) dicatat berdasarkan keputusan yang sah.","Admin kesekretariatan","Keputusan perubahan","Data terbarui","3 hari kerja setelah keputusan"],["5","Pembatasan akses: Mengatur akses basis data sesuai SOP- ADM-015 dan menyembunyikan data pribadi dari pengguna yang tidak berkepentingan.","Admin dokumen","Matriks akses","Akses terbatas","1 hari kerja"],["6","Penggunaan: Basis data dipakai untuk undangan, penugasan, kalender (SOP-ADM-018), dan laporan (SOP-ADM-019).","Pengguna sah","Data induk","Dokumen dan laporan akurat","Sesuai kebutuhan"],["7","Pemeriksaan berkala: Mencocokkan basis data dengan keputusan, daftar akses, dan laporan unit.","Kabiro Kesekretariatan","Basis data","Catatan pemeriksaan","Setiap bulan"],["8","Serah terima: Basis data final diserahkan pada transisi kabinet sesuai SOP-TRN (akan disusun).","Sekjen","Basis data akhir","Dokumen serah terima","Akhir periode"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Basis data awal disusun paling lambat 3 hari kerja setelah pelantikan dan RAKER; perubahan dicatat paling lambat 3 hari kerja setelah keputusan sah. Hasil akhir: basis data pengurus dan program kerja yang mutakhir dan aman."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Perbedaan data antara unit dan keputusan resmi diselesaikan dengan merujuk pada keputusan sah; bila belum ada keputusan, Presiden memutuskan.","Permintaan data pribadi dari pihak luar ditolak kecuali ada persetujuan yang bersangkutan dan Sekjen.","Kebocoran data pribadi dilaporkan kepada Presiden dan Irjen serta ditangani sesuai SOP-RSK-09 (akan disusun).","Pengurus dapat meminta koreksi atau penghapusan data pribadinya yang tidak diperlukan dan Admin menindaklanjuti dalam 3 hari kerja."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Data pengurus cocok dengan keputusan dan daftar akses pada setiap pemeriksaan.","Perubahan data tercatat dalam 3 hari kerja pada minimal 90% kasus.","Tidak ada kebocoran data pribadi.","Seluruh program kerja memiliki penanggung jawab dan status terkini."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Basis data pengurus.","Basis data program kerja.","Catatan perubahan data.","Catatan pemeriksaan bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Basis Data) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Kesekretariatan memeriksa kebenaran data setiap bulan; Sekjen melaporkan pada evaluasi bulanan; Irjen menilai pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Susun basis data → Verifikasi unit → Tetapkan data induk → Perbarui sesuai keputusan → Batasi akses → Periksa bulanan → Serah terima → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Basis Data Pengurus","Nama; jabatan; unit; periode; kontak resmi; status aktif; tanggal dan dasar keputusan."],["Templat Basis Data Program Kerja","Kode; nama program; penanggung jawab; jadwal; anggaran; status; dasar pengesahan."],["Formulir Perubahan Data","Jenis perubahan; data lama dan baru; dasar keputusan; pengaju; tanggal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Data sesuai keputusan yang sah.","☐ Ya ☐ Tidak"],["2","Hanya data yang diperlukan yang tersimpan.","☐ Ya ☐ Tidak"],["3","Akses dibatasi sesuai peran.","☐ Ya ☐ Tidak"],["4","Perubahan tercatat dalam 3 hari kerja.","☐ Ya ☐ Tidak"],["5","Pemeriksaan bulanan dilakukan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-018","g":"Kesekretariatan dan Administrasi","t":"Pengelolaan Kalender Organisasi","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[529,532],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara menyusun, memperbarui, dan menyebarkan kalender organisasi agar seluruh agenda rapat, kegiatan, dan tenggat tidak berbenturan satu sama lain maupun dengan kalender akademik kampus."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh agenda BEM: rapat, kegiatan, tenggat laporan, tenggat administrasi, dan agenda penting kampus yang terkait. Penyusunan kalender program kerja secara rinci mengikuti SOP-PRO-02 (akan disusun)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 9 ayat (3) huruf c (RAKER menetapkan timeline kegiatan).","ART Pasal 3 (Tugas BEM) huruf f (mengkoordinasikan seluruh kegiatan kemahasiswaan di lingkungan STDIIS Jember).","ART Pasal 3 (Kewajiban BEM) huruf h (mematuhi kebijakan STDIIS Jember).","SOP-ADM-017 (basis data program kerja)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kalender induk","Kalender tunggal organisasi yang memuat seluruh agenda resmi BEM."],["Kalender akademik","Jadwal perkuliahan, ujian, dan libur yang ditetapkan kampus."],["Benturan jadwal","Dua agenda atau lebih yang melibatkan pihak yang sama pada waktu yang bersamaan."],["Masa beku","Periode menjelang kegiatan ketika perubahan jadwal memerlukan persetujuan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kalender induk disusun mengacu pada kalender akademik, jadwal ibadah dan kegiatan keagamaan kampus, serta program kerja yang disahkan RAKER.","Agenda hanya dianggap resmi bila tercantum pada kalender induk.","Perubahan jadwal agenda yang telah dipublikasikan dilakukan paling lambat H-3 (masa beku, usulan); perubahan setelah itu memerlukan persetujuan Presiden.","Rapat internal dijadwalkan di luar jam perkuliahan dan waktu salat."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri, Kabiro, dan ketua pelaksana","R","Mengajukan agenda dan perubahan agenda unitnya."],["Admin kesekretariatan","R","Memasukkan agenda, memeriksa benturan, dan menyebarkan kalender."],["Kabiro Kesekretariatan","R","Menyusun kalender induk dan memeriksa konsistensi dengan kalender kampus."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas kalender induk dan penyelesaian benturan jadwal."],["Presiden","C","Memutuskan prioritas agenda bila benturan tidak terselesaikan."],["Seluruh pengurus","I","Mengikuti kalender dan melaporkan agenda yang belum tercatat."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Kalender akademik kampus.","Program kerja dan timeline hasil RAKER.","Formulir Pengajuan Agenda.","Akses kalender bersama organisasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan kalender awal: Admin menyusun kalender induk dari kalender akademik, program kerja, dan jadwal rapat rutin.","Admin, Kabiro","Kalender akademik, program kerja","Kalender induk draf","3 hari kerja setelah RAKER"],["2","Pemeriksaan benturan: Memeriksa benturan antaragenda dan dengan kalender kampus serta memberi catatan.","Admin kesekretariatan","Kalender draf","Catatan benturan","1 hari kerja"],["3","Penyelesaian benturan: Sekjen memanggil pengaju agenda untuk menggeser jadwal; bila gagal, Presiden memutuskan prioritas.","Sekjen, Presiden","Catatan benturan","Jadwal bebas benturan","2 hari kerja"],["4","Penetapan dan publikasi: Kalender induk ditetapkan dan dibagikan melalui kanal resmi serta dikunci pada repositori.","Sekjen","Kalender final","Kalender resmi","1 hari kerja"],["5","Pengajuan agenda baru: Unit mengajukan agenda baru melalui Formulir Pengajuan Agenda paling lambat 7 hari sebelum pelaksanaan (usulan).","Unit pengaju","Formulir","Agenda diajukan","H-7"],["6","Pembaruan: Admin memasukkan agenda baru atau perubahan yang disetujui dan memberi tahu pihak terkait.","Admin kesekretariatan","Persetujuan","Kalender terbarui","1 hari kerja"],["7","Pengingat dan rekap: Mengirim pengingat agenda pekanan dan merekap agenda terlaksana, ditunda, dan dibatalkan setiap bulan.","Admin, Kabiro","Kalender","Pengingat dan rekap","Mingguan dan bulanan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Kalender induk ditetapkan paling lambat 5 hari kerja setelah RAKER; agenda baru dimasukkan dalam 1 hari kerja setelah persetujuan. Hasil akhir: kalender induk resmi yang mutakhir dan bebas benturan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Agenda mendesak (SOP-GOV-007 dan SOP-GOV-012) dimasukkan pada hari yang sama dengan penjelasan kepada pihak yang terdampak.","Perubahan kalender akademik oleh kampus ditindaklanjuti dengan penyesuaian kalender induk dalam 2 hari kerja.","Benturan yang tidak terselesaikan diputuskan Presiden; agenda yang digeser diumumkan kepada pesertanya.","Kegiatan di luar kalender induk tidak memperoleh dukungan administrasi sampai dimasukkan dan disetujui."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Tidak ada benturan agenda tanpa keputusan.","100% agenda resmi tercantum pada kalender induk.","Kalender diperbarui dalam 1 hari kerja setelah persetujuan pada minimal 95% kasus.","Perubahan jadwal setelah H-3 menurun dari bulan ke bulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Kalender induk organisasi.","Formulir Pengajuan Agenda.","Rekap agenda bulanan.","Pengingat agenda. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Kalender) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kabiro Kesekretariatan memeriksa kalender setiap pekan; Sekjen melaporkan rekap bulanan; Irjen menilai pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Susun kalender induk → Periksa benturan → Selesaikan benturan → Tetapkan dan publikasikan → Agenda baru → Perbarui → Pengingat dan rekap → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pengajuan Agenda","Nama agenda; unit; penanggung jawab; tanggal dan waktu; tempat; peserta; kebutuhan; persetujuan."],["Kalender Induk Organisasi","Tanggal; agenda; unit; penanggung jawab; status; keterangan benturan."],["Rekap Agenda Bulanan","Periode; terlaksana; ditunda; dibatalkan; alasan; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Agenda selaras dengan kalender akademik.","☐ Ya ☐ Tidak"],["2","Tidak ada benturan atau benturan telah diputuskan.","☐ Ya ☐ Tidak"],["3","Kalender dipublikasikan melalui kanal resmi.","☐ Ya ☐ Tidak"],["4","Perubahan setelah H-3 memiliki persetujuan.","☐ Ya ☐ Tidak"],["5","Rekap bulanan telah dibuat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-019","g":"Kesekretariatan dan Administrasi","t":"Penyusunan Laporan Bulanan dan Laporan Kabinet","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[533,536],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara penyusunan, pemeriksaan, penyampaian, dan pengarsipan laporan bulanan unit, laporan bulanan kabinet, dan laporan kabinet akhir periode agar pertanggungjawaban BEM tersusun berkala, transparan, dan dapat dipertanggungjawabkan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kementerian, biro, dan Irjen yang menyampaikan laporan, serta Sekretariat yang menyusun laporan kabinet. Laporan keuangan kegiatan diatur pada SOP-KEU-15, laporan pertanggungjawaban kegiatan pada SOP-PRO-20, dan laporan akhir masa jabatan pada SOP-TRN-01 (seluruhnya akan disusun)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) sampai (3) (laporan pertanggungjawaban berkala, transparan dan akuntabel, dibahas dengan BPM dalam Mubes dan dilaporkan kepada Kepala Urusan Organisasi Kemahasiswaan).","ART Pasal 3 (Kewajiban BEM) huruf g (laporan pertanggungjawaban kegiatan dan keuangan secara berkala).","ART Pasal 3 (Tugas BEM) huruf e (laporan pertanggungjawaban anggaran dan program pada akhir masa jabatan).","ART Pasal 7 ayat (5) huruf c (evaluasi kinerja organisasi pada Mubes).","ART Pasal 12 ayat (3) sampai (6) (pengawasan dan evaluasi Irjen)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Laporan bulanan unit","Laporan singkat kegiatan, capaian, kendala, dan rencana bulan berikutnya dari setiap unit."],["Laporan bulanan kabinet","Rangkuman laporan seluruh unit yang disusun Sekretariat untuk Rapat Kabinet."],["Laporan kabinet","Laporan akhir periode yang menjadi bahan pertanggungjawaban pada Mubes."],["Kanal resmi","Email resmi atau platform koordinasi yang ditetapkan untuk penyampaian laporan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Jadwal (usulan): laporan unit disampaikan paling lambat tanggal 5 setiap bulan; laporan kabinet bulanan disusun paling lambat tanggal 10 dan dibahas pada Rapat Kabinet.","Isi minimal laporan unit: program berjalan, capaian terhadap target, anggaran terpakai (dari catatan keuangan resmi), kendala, tindak lanjut, dan dokumentasi.","Laporan kabinet akhir periode memuat ringkasan program, capaian, anggaran, tindak lanjut, dan temuan pengawasan, dan disampaikan kepada BPM untuk dibahas pada Mubes serta dilaporkan kepada Kepala Urusan Organisasi Kemahasiswaan sesuai AD Pasal 17 ayat (3).","Data angka pada laporan harus bersumber dari dokumen resmi dan dapat ditelusuri."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri dan Kabiro","R","Menyusun dan menyampaikan laporan unit sesuai jadwal."],["Admin kesekretariatan","R","Mengumpulkan laporan, memeriksa kelengkapan, dan menyusun rangkuman."],["Bendahara atau Biro Keuangan","C","Memberi data anggaran yang sah."],["Sekretaris Jenderal","A","Bertanggung jawab akhir atas laporan kabinet dan ketepatan jadwal pelaporan."],["Presiden","R","Memeriksa dan mengesahkan laporan kabinet dan menyampaikannya kepada pihak yang berwenang."],["Irjen","C","Memeriksa kebenaran dan kesesuaian laporan serta memberi catatan pengawasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Templat laporan unit dan laporan kabinet.","Program kerja dan kalender organisasi.","Catatan keuangan resmi.","Notulen, daftar tindak lanjut, dan bukti kegiatan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengingat jadwal: Admin mengingatkan unit tentang tenggat laporan 3 hari sebelumnya.","Admin kesekretariatan","Kalender","Pengingat terkirim","H-3 tenggat"],["2","Penyusunan laporan unit: Unit menyusun laporan pada templat dan melampirkan bukti.","Menteri, Kabiro","Templat, data unit","Laporan unit","Tanggal 5"],["3","Pemeriksaan kelengkapan: Admin memeriksa kelengkapan dan konsistensi data; laporan yang kurang dikembalikan.","Admin kesekretariatan","Laporan unit","Lengkap atau perlu revisi","2 hari kerja"],["4","Penyusunan laporan kabinet bulanan: Sekretariat merangkum seluruh laporan unit, daftar tindak lanjut, dan data anggaran menjadi laporan kabinet bulanan.","Admin, Sekjen","Laporan unit lengkap","Laporan kabinet bulanan","Tanggal 10"],["5","Pemeriksaan Irjen: Irjen memeriksa kebenaran dan kesesuaian laporan dan memberi catatan pengawasan.","Irjen","Laporan kabinet","Catatan Irjen","2 hari kerja"],["6","Pembahasan: Laporan dibahas pada Rapat Kabinet (SOP-GOV-006) dan hasilnya dicatat sebagai keputusan dan tindak lanjut.","Pimpinan, Eksekutif","Laporan, catatan Irjen","Keputusan dan tindak lanjut","Pada Rapat Kabinet"],["7","Laporan akhir periode: Menyusun laporan kabinet akhir periode dari laporan bulanan, evaluasi tengah periode, dan temuan pengawasan; disahkan Presiden.","Sekjen, Presiden","Laporan bulanan","Laporan kabinet akhir periode","Sebelum Mubes"],["8","Penyampaian dan pengarsipan: Menyampaikan laporan akhir periode kepada BPM untuk dibahas pada Mubes dan melaporkan hasilnya kepada Kepala Urusan Organisasi Kemahasiswaan, lalu mengarsipkan.","Presiden, Admin dokumen","Laporan disahkan","Laporan tersampaikan dan terarsip","Sesuai jadwal Mubes"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Laporan unit disampaikan paling lambat tanggal 5 dan laporan kabinet bulanan tersusun paling lambat tanggal 10 setiap bulan. Hasil akhir: laporan bulanan, laporan kabinet akhir periode, dan arsip yang lengkap."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Unit yang terlambat dua kali berturut-turut dibawa ke Wakil Presiden dan dapat dibina melalui SOP- SDM-011 (akan disusun).","Data yang tidak dapat ditelusuri ditandai belum diverifikasi dan tidak dicantumkan sebagai capaian sampai ada bukti.","Temuan Irjen berupa dugaan pelanggaran diteruskan sesuai ART Pasal 12 dan Pasal 13.","Bila Mubes belum dapat dilaksanakan sesuai jadwal, Presiden berkonsultasi dengan KAUR ORMAWA dan BPM untuk jadwal pengganti."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% laporan unit diterima tepat waktu.","100% laporan kabinet bulanan dibahas pada Rapat Kabinet.","Seluruh angka pada laporan dapat ditelusuri ke dokumen sumber.","Laporan kabinet akhir periode tersedia sebelum Mubes."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan bulanan unit.","Laporan kabinet bulanan.","Catatan Irjen.","Laporan kabinet akhir periode dan bukti penyampaian. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Laporan) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen merekap ketepatan laporan setiap bulan; Irjen menilai kualitas dan kebenaran laporan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengingat → Laporan unit → Periksa kelengkapan → Susun laporan kabinet → Periksa Irjen → Bahas di Rapat Kabinet → Laporan akhir periode → Sampaikan dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Laporan Unit","Unit; periode; program berjalan; capaian; anggaran; kendala; tindak lanjut; dokumentasi; penyusun."],["Templat Laporan Kabinet Bulanan","Ringkasan seluruh unit; capaian; anggaran; kendala utama; keputusan yang diperlukan; catatan Irjen."],["Templat Laporan Kabinet Akhir Periode","Pendahuluan; ringkasan program; capaian; anggaran; temuan dan tindak lanjut; rekomendasi; lampiran."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Laporan unit diterima tepat waktu.","☐ Ya ☐ Tidak"],["2","Angka bersumber dari dokumen resmi.","☐ Ya ☐ Tidak"],["3","Catatan Irjen telah diperoleh.","☐ Ya ☐ Tidak"],["4","Laporan kabinet dibahas pada Rapat Kabinet.","☐ Ya ☐ Tidak"],["5","Laporan akhir periode disampaikan kepada pihak yang berwenang.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ADM-020","g":"Kesekretariatan dan Administrasi","t":"Pengelolaan Dokumen Rahasia dan Pembatasan Akses","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[537,540],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara penggolongan, penandaan, penyimpanan, pembatasan akses, dan pemusnahan dokumen rahasia atau terbatas agar informasi sensitif tidak bocor dan identitas pihak yang dilindungi tetap aman."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh dokumen dan informasi BEM yang digolongkan Terbatas atau Rahasia, baik fisik maupun digital, termasuk pengaduan, data pribadi, hasil pemeriksaan etik, temuan Irjen, dan dokumen kebijakan yang belum diumumkan. Penanganan pengaduan mengikuti SOP-ADV dan SOP-RSK, serta penanganan kebocoran data mengikuti SOP-RSK-09 (seluruhnya akan disusun)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 11 huruf g, i, dan k (larangan mencemarkan nama baik, menyelewengkan dana, dan menyalahgunakan fasilitas atau nama organisasi).","ART Pasal 12 ayat (3) sampai (6) dan Pasal 13 ayat (4) sampai (9) (pengawasan Irjen, bukti, klarifikasi dan pembelaan).","Pedoman Penyusunan SOP, Prinsip penyusunan (perlindungan data, etika, dan penanganan pengaduan sejak awal).","SOP-ADM-015 (hak akses) dan SOP-ADM-016 (peminjaman dokumen)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Dokumen Umum","Dokumen yang boleh diketahui seluruh pengurus dan atau publik."],["Dokumen Terbatas","Dokumen yang hanya boleh diakses pengurus yang berkepentingan."],["Dokumen Rahasia","Dokumen yang pengungkapannya dapat merugikan orang atau organisasi dan hanya boleh diakses pihak yang ditunjuk tertulis."],["Daftar Akses Dokumen Rahasia","Daftar nama pihak yang berhak mengakses suatu dokumen rahasia."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Contoh dokumen Rahasia (usulan): identitas pelapor dan isi pengaduan, hasil pemeriksaan dugaan pelanggaran etik, data pribadi pengurus, temuan Irjen yang belum diputuskan, dan dokumen strategi yang belum diumumkan.","Penggolongan ditetapkan pembuat dokumen dan dikonfirmasi Sekjen; golongan Rahasia ditetapkan Presiden dengan masukan Irjen.","Dokumen Rahasia diberi tanda dan nomor salinan, disimpan terkunci (fisik) atau terenkripsi dengan akses terbatas (digital), dan tidak dikirim melalui grup umum.","Pihak yang mengakses wajib menjaga kerahasiaan; pelanggaran diproses sebagai pelanggaran sesuai ART Pasal 11 sampai Pasal 13.","Penggolongan ditinjau ulang saat dokumen tidak lagi sensitif atau diputuskan dibuka."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pembuat dokumen","R","Mengusulkan golongan dokumen dan menandai dokumen."],["Admin dokumen","R","Menyimpan, membatasi akses, mencatat salinan, dan memeriksa penggunaan."],["Sekretaris Jenderal","A","Mengonfirmasi penggolongan, memegang Daftar Akses, dan bertanggung jawab akhir atas pengamanan dokumen."],["Presiden","R","Menetapkan golongan Rahasia dan menyetujui pembukaan akses atau pemusnahan."],["Irjen","C","Memberi masukan penggolongan dan memeriksa kepatuhan serta riwayat akses."],["Pihak yang diberi akses","R","Menjaga kerahasiaan dan melaporkan kehilangan atau kebocoran."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Dokumen yang akan digolongkan.","Daftar Akses Dokumen Rahasia.","Tempat penyimpanan terkunci atau folder berakses terbatas.","Surat pernyataan menjaga kerahasiaan bagi pihak yang diberi akses."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Usulan penggolongan: Pembuat dokumen mengusulkan golongan (Umum, Terbatas, Rahasia) beserta alasan.","Pembuat dokumen","Dokumen","Usulan golongan","Saat dokumen dibuat"],["2","Konfirmasi dan penetapan: Sekjen mengonfirmasi golongan Terbatas; golongan Rahasia ditetapkan Presiden dengan masukan Irjen.","Sekjen, Presiden","Usulan","Golongan ditetapkan","2 hari kerja"],["3","Penandaan dan penyimpanan: Admin menandai dokumen, memberi nomor salinan, dan menyimpannya di tempat terkunci atau folder berakses terbatas.","Admin dokumen","Dokumen","Dokumen tersimpan aman","1 hari kerja"],["4","Penetapan Daftar Akses: Sekjen menetapkan pihak yang berhak mengakses dan memperoleh surat pernyataan kerahasiaan.","Sekjen","Usulan akses","Daftar Akses","1 hari kerja"],["5","Pemberian akses: Admin memberi akses sesuai daftar dan mencatat setiap pembukaan, pembacaan, atau penggandaan.","Admin dokumen","Daftar Akses","Log akses","Setiap akses"],["6","Pemeriksaan: Kabiro dan Irjen memeriksa log akses dan kondisi penyimpanan, serta mencocokkan salinan.","Kabiro, Irjen","Log akses","Catatan pemeriksaan","Setiap bulan"],["7","Peninjauan golongan: Meninjau dokumen yang dapat diturunkan golongannya atau dibuka berdasarkan keputusan Presiden.","Sekjen, Presiden","Daftar dokumen","Keputusan penurunan atau pembukaan","Setiap tengah dan akhir periode"],["8","Pemusnahan atau serah terima: Dokumen dimusnahkan dengan Berita Acara Pemusnahan atau diserahkan kepada kabinet berikutnya sesuai SOP- TRN-03 (akan disusun).","Sekjen, Presiden","Keputusan","Berita acara atau serah terima","Sesuai keputusan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penggolongan ditetapkan paling lambat 2 hari kerja sejak dokumen diusulkan; akses dicatat setiap kali terjadi. Hasil akhir: dokumen terklasifikasi, aman, dan tercatat siapa yang mengaksesnya."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kebocoran atau dugaan kebocoran dilaporkan segera kepada Sekjen, Presiden, dan Irjen; akses ditutup dan penanganan mengikuti SOP-RSK-09 (akan disusun).","Permintaan pembukaan dokumen oleh pihak berwenang kampus atau aparat diteruskan kepada Presiden dan dilaksanakan sesuai ketentuan yang berlaku dengan bukti serah terima.","Dokumen yang memuat identitas pelapor tidak diungkapkan tanpa persetujuan yang bersangkutan, kecuali diwajibkan aturan yang berlaku.","Pihak yang membocorkan dokumen rahasia diproses sesuai ART Pasal 11 dan Pasal 12, dengan hak klarifikasi dan pembelaan (ART Pasal 13 ayat 9)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% dokumen rahasia tercatat pada Daftar Akses.","Tidak ada kebocoran dokumen rahasia.","Log akses lengkap pada setiap pemeriksaan.","Penggolongan dikonfirmasi dalam 2 hari kerja pada minimal 90% kasus."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Akses Dokumen Rahasia.","Log akses.","Catatan pemeriksaan.","Berita Acara Pemusnahan atau serah terima, bila ada. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan / Terbatas (akses khusus)) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen memeriksa Daftar Akses setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala dan memeriksa log akses."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Usulan golongan → Konfirmasi atau tetapkan → Tandai dan simpan → Tetapkan Daftar Akses → Beri akses dan catat → Periksa bulanan → Tinjau golongan → Musnahkan atau serahkan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Penggolongan Dokumen","Judul; pembuat; golongan usulan; alasan; pihak yang perlu akses; penetapan; tanggal."],["Daftar Akses Dokumen Rahasia","Dokumen; nama pihak berakses; jabatan; dasar; tanggal diberikan dan dicabut; surat pernyataan."],["Log Akses Dokumen","Tanggal; dokumen; pengakses; tindakan (baca, salin, kirim); paraf pemegang."],["Surat Pernyataan Menjaga Kerahasiaan","Nama; jabatan; dokumen; larangan; sanksi; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Golongan dokumen telah ditetapkan pihak yang berwenang.","☐ Ya ☐ Tidak"],["2","Dokumen ditandai dan disimpan terkunci atau berakses terbatas.","☐ Ya ☐ Tidak"],["3","Daftar Akses dan surat pernyataan lengkap.","☐ Ya ☐ Tidak"],["4","Log akses terisi dan diperiksa.","☐ Ya ☐ Tidak"],["5","Dokumen dimusnahkan atau diserahkan dengan berita acara.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-001","g":"Komunikasi dan Informasi","t":"Penggunaan Kanal Komunikasi Resmi","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[545,548],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan kanal komunikasi resmi BEM, fungsi tiap kanal, dan aturan memilih kanal, sehingga informasi penting tercatat, mudah ditelusuri, dan tidak bergantung pada perangkat atau akun pribadi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh komunikasi kerja BEM: antarpengurus, antara BEM dan pihak kampus, serta antara BEM dan pihak luar. SOP ini tidak mengatur adab berkomunikasi (lihat SOP-KOM-002), format instruksi (SOP-KOM-003), tata kelola grup (SOP-KOM-005), email (SOP-KOM-006), dan media sosial (SOP-KOM- 008)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (2) (pengelolaan organisasi secara transparan, akuntabel, efektif, dan efisien).","ART Pasal 3 (Kewajiban BEM) huruf d, g, dan h (menjaga nama baik, laporan berkala, mematuhi peraturan kampus).","ART Pasal 4 (Wewenang BEM) huruf f (menandatangani surat-surat resmi dan dokumen organisasi).","ART Pasal 10 ayat (5) dan (6) (notulensi resmi; rapat luring atau daring).","Pedoman Penyusunan SOP BEM Kabinet Baru (dokumen final disimpan di repositori resmi, bukan di perangkat atau akun pribadi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kanal resmi","Sarana komunikasi yang tercatat pada Daftar Kanal Resmi dan dikelola atas nama organisasi atau jabatan."],["Kanal tercatat","Kanal yang meninggalkan bukti yang dapat dirujuk kembali, yaitu surat, email resmi, notulen, dan dokumen di repositori."],["Daftar Kanal Resmi","Dokumen yang memuat nama kanal, fungsi, pemilik (jabatan), pengelola, dan jenis informasi yang boleh disampaikan."],["Pesan pribadi","Pesan langsung antarperorangan di luar kanal resmi; bukan kanal keputusan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kanal resmi terdiri atas: (1) rapat luring atau daring untuk pembahasan dan keputusan; (2) surat dan email resmi untuk undangan, pengajuan, persetujuan, penugasan formal, serta komunikasi dengan kampus dan pihak luar; (3) grup atau platform koordinasi untuk koordinasi harian, pengingat, dan laporan ringkas; (4) media sosial resmi untuk publikasi; (5) repositori resmi untuk penyimpanan dokumen final.","Hal yang wajib melalui kanal tercatat: keputusan, persetujuan, penugasan formal, anggaran dan pembayaran, perubahan jadwal atau konsep kegiatan, kesepakatan dengan pihak luar, serta hal yang berpotensi menimbulkan sengketa.","Hal yang boleh melalui pesan singkat: pengingat, koordinasi teknis ringan, konfirmasi kehadiran, dan informasi yang tidak memerlukan bukti formal.","Pesan pribadi bukan kanal keputusan. Bila substansi keputusan atau persetujuan terjadi lewat pesan pribadi atau lisan, hasilnya dikonfirmasi pada kanal tercatat paling lambat 1 hari kerja.","Komunikasi dengan pihak kampus memakai surat resmi atau audiensi (SOP-ADM-002 dan SOP-HKE- 003). Komunikasi antarormawa dan pihak internal kampus dikoordinasikan melalui Kementerian Harmonisasi Kampus sesuai Pedoman.","Akun, nomor, dan email resmi dimiliki atas nama organisasi atau jabatan dan dikelola sesuai SOP- KOM-013."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan Daftar Kanal Resmi dan menyetujui kanal baru atau penutupan kanal."],["Sekretaris Jenderal","R","Menyusun dan memelihara Daftar Kanal Resmi, mensosialisasikan, serta memeriksa kepatuhan penggunaan kanal."],["Kepala Biro DKV","R","Mengelola kanal publik (media sosial) sesuai SOP-KOM-008 dan melaporkannya dalam Daftar Kanal Resmi."],["Menteri / Kabiro","R","Memastikan unitnya memakai kanal sesuai fungsi dan mengusulkan kanal baru bila dibutuhkan."],["Inspektur Jenderal","C","Memeriksa kepatuhan dan kelengkapan jejak komunikasi pada evaluasi berkala."],["Seluruh pengurus","I","Memahami dan menggunakan kanal sesuai fungsinya."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Struktur kabinet yang telah ditetapkan.","Daftar akun, grup, dan nomor yang sudah ada, termasuk dari kabinet sebelumnya.","Kebutuhan komunikasi tiap unit.","Hasil Rapat Pimpinan (SOP-GOV-005)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan daftar: Menginventarisasi kanal yang ada dan dibutuhkan; menyusun Daftar Kanal Resmi lengkap dengan fungsi, pemilik, dan pengelola.","Sekjen","Struktur kabinet, data kanal","Draf Daftar Kanal Resmi","3 hari kerja setelah struktur ditetapkan"],["2","Pengesahan: Membahas draf pada Rapat Pimpinan dan menetapkan Daftar Kanal Resmi.","Presiden","Draf daftar","Daftar ditetapkan","2 hari kerja"],["3","Sosialisasi: Menyampaikan daftar dan aturan pemakaian kanal pada rapat kabinet pertama; menyimpan pada repositori.","Sekjen","Daftar ditetapkan","Daftar tersosialisasi dan terarsip","3 hari kerja setelah penetapan"],["4","Penggunaan harian: Menggunakan kanal sesuai fungsi; hal yang wajib tercatat disampaikan melalui kanal tercatat.","Seluruh pengurus","Daftar Kanal Resmi","Komunikasi tercatat","Setiap hari"],["5","Konfirmasi keputusan: Mengonfirmasi pada kanal tercatat setiap keputusan, persetujuan, atau penugasan yang terjadi lewat lisan atau pesan pribadi.","Pengurus pemrakarsa","Pesan atau kesepakatan lisan","Konfirmasi tertulis","1 hari kerja"],["6","Usulan kanal baru atau penutupan: Mengajukan Formulir Usulan Kanal; memeriksa kebutuhan dan keamanan (SOP-KOM-013); meminta persetujuan Presiden; memperbarui daftar.","Menteri / Kabiro, Sekjen","Formulir usulan","Daftar diperbarui","3 hari kerja"],["7","Pemeriksaan berkala: Memeriksa kesesuaian daftar, pengelola, dan kanal tidak terdaftar atas nama BEM; mencatat temuan.","Sekjen dan Irjen","Daftar, hasil pemantauan","Catatan pemeriksaan","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Daftar Kanal Resmi ditargetkan ditetapkan paling lambat 5 hari kerja sejak struktur kabinet ditetapkan dan tersosialisasi 3 hari kerja berikutnya. Hasil akhir: Daftar Kanal Resmi yang berlaku dan terarsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengurus tidak merespons pada kanal resmi: ikuti SOP-KOM-003, kemudian SOP-SDM-011.","Kanal atau akun bermasalah atau diduga disusupi: segera lapor Sekjen; ikuti SOP-KOM-013 dan SOP- RSK-008.","Ditemukan kanal atau akun atas nama BEM yang tidak terdaftar: Sekjen mendaftarkan atau menutupnya setelah berkoordinasi dengan Presiden.","Perbedaan pendapat tentang pemilihan kanal: diputuskan Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Penggunaan kanal untuk kepentingan pribadi atau penyebaran informasi sensitif: SOP-RSK-010 dan SOP-SDM-013."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kanal resmi tercatat pada Daftar Kanal Resmi dengan pemilik dan pengelola yang jelas.","Keputusan dan penugasan formal dapat ditelusuri pada kanal tercatat pada pemeriksaan sampel Irjen.","Daftar tersosialisasi paling lambat 3 hari kerja setelah penetapan.","Tidak ada kanal publik atas nama BEM yang tidak terdaftar."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Kanal Resmi yang ditetapkan.","Catatan perubahan kanal dan hasil pemeriksaan berkala.","Notulen sosialisasi.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa Daftar Kanal Resmi setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Susun daftar kanal → Pengesahan Presiden → Sosialisasi → Penggunaan harian → Konfirmasi keputusan → Pemeriksaan berkala → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Kanal Resmi","Nama kanal; platform; fungsi; pemilik (jabatan); pengelola; jenis informasi yang boleh; tanggal dibuat; status."],["Formulir Usulan Kanal","Nama kanal; tujuan; pengusul; pengelola; pertimbangan keamanan; tanggal; keputusan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap kanal memiliki fungsi, pemilik, dan pengelola yang tercatat.","☐ Ya ☐ Tidak"],["2","Tidak ada kanal publik atas nama BEM yang belum terdaftar.","☐ Ya ☐ Tidak"],["3","Seluruh pengurus telah menerima Daftar Kanal Resmi.","☐ Ya ☐ Tidak"],["4","Keputusan dan penugasan formal dapat ditelusuri pada kanal tercatat.","☐ Ya ☐ Tidak"],["5","Dokumen tercatat pada Register Dokumen.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-002","g":"Komunikasi dan Informasi","t":"Etika Komunikasi Internal","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[549,552],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan standar adab, bahasa, waktu, dan batas isi komunikasi internal BEM agar kerja sama terjaga, ukhuwah terpelihara, dan perselisihan tidak berkembang karena cara berkomunikasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus BEM pada setiap kanal komunikasi internal (rapat, grup, pesan pribadi, email, dan dokumen) serta saat berkomunikasi dengan pihak kampus dan mahasiswa dalam kapasitas sebagai pengurus. Pelanggaran berat ditangani melalui SOP-SDM-013; pelecehan dan perundungan melalui SOP- RSK-005."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 3 ayat (1) (landasan Al-Qur'an dan As-Sunnah) dan Pasal 5 ayat (2) serta (4) (ukhuwah Islamiah; tanggung jawab, disiplin, dan amanah).","AD Pasal 9 ayat (2) huruf a dan b (alasan pemberhentian anggota).","ART Pasal 3 (Kewajiban BEM) huruf b dan d (menjaga ukhuwah dan nama baik).","ART Pasal 11 huruf a, b, d, g, dan h (larangan SARA, penistaan agama, paham yang bertentangan, pencemaran nama baik, pelecehan atau perundungan).","ART Pasal 12 dan Pasal 13 (jenis sanksi dan mekanisme pemberian sanksi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Tabayyun","Memeriksa kebenaran informasi dan meminta klarifikasi kepada pihak yang bersangkutan sebelum menanggapi atau menyebarkannya."],["Jam tenang","Rentang waktu ketika pesan yang tidak mendesak tidak dikirim (usulan: pukul 22.00 sampai 04.00 WIB)."],["Pesan mendesak","Pesan yang menyangkut keselamatan, kegiatan yang berlangsung pada hari itu, batas administrasi kurang dari 24 jam, atau potensi kerugian organisasi."],["Kritik konstruktif","Masukan yang disampaikan kepada pihak berwenang dengan data, bahasa santun, dan usulan perbaikan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Adab umum: membuka dengan salam, memakai bahasa santun dan jelas, tidak merendahkan, tidak memakai kata kasar atau candaan yang menyinggung pribadi, suku, atau agama.","Batas isi: tidak memuat SARA, penistaan agama, kabar yang belum terverifikasi, gosip tentang pribadi, atau pembukaan aib sesama pengurus (ART Pasal 11).","Lakukan tabayyun sebelum menanggapi atau meneruskan informasi; kabar yang belum jelas tidak diteruskan ke kanal lain.","Masalah personal dibicarakan langsung dan tertutup, bukan di grup besar; kritik terhadap kinerja disampaikan kepada atasan langsung atau pada rapat evaluasi.","Menjaga batasan interaksi dan kepatutan sesuai syariat dan aturan kampus, termasuk pada komunikasi pribadi antarpengurus.","Menghormati waktu salat, kuliah, dan istirahat; pesan tidak mendesak tidak dikirim pada jam tenang.","Pesan kerja ditanggapi paling lambat 1 x 24 jam hari kerja (usulan), minimal dengan penegasan sudah dibaca dan waktu tindak lanjut.","Perbedaan pendapat disampaikan dalam rapat atau kanal diskusi dengan alasan dan data. Keputusan yang sudah ditetapkan dijalankan; keberatan disalurkan melalui SOP-GOV-002.","Tangkapan layar percakapan internal dan informasi sensitif tidak disebarkan ke luar tanpa izin pimpinan (SOP-SDM-018 dan SOP-RSK-010).."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Wakil Presiden","A","Menetapkan dan memelihara standar etika komunikasi serta membina penerapannya."],["Presiden","C","Dimintai pertimbangan pada pelanggaran berat dan menetapkan tindak lanjut sesuai kewenangan pimpinan (ART Pasal 12)."],["Sekretaris Jenderal","R","Mensosialisasikan standar, mengumpulkan Pernyataan Komitmen, dan mengarsipkan."],["Menteri / Kabiro","R","Menjaga etika di unitnya dan memberi teguran awal yang santun."],["Inspektur Jenderal","C","Menerima laporan, melakukan klarifikasi, dan menilai kepatuhan."],["Seluruh pengurus","R","Menaati standar dan melaporkan pelanggaran dengan bukti."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["AD/ART dan peraturan kampus.","Standar Etika Komunikasi dan Pernyataan Komitmen.","Laporan dugaan pelanggaran beserta bukti percakapan (bila ada)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan standar: Menyusun Standar Etika Komunikasi dan jam tenang; membahasnya pada Rapat Pimpinan.","Wapres bersama Sekjen","AD/ART, SOP ini","Standar disahkan","3 hari kerja setelah struktur ditetapkan"],["2","Sosialisasi dan komitmen: Menyampaikan standar pada rapat kabinet dan orientasi; pengurus menandatangani Pernyataan Komitmen.","Sekjen","Standar, formulir komitmen","Komitmen terkumpul","5 hari kerja setelah orientasi"],["3","Penerapan harian: Berkomunikasi sesuai standar; atasan langsung mengingatkan bila ada penyimpangan ringan.","Seluruh pengurus","Standar","Komunikasi tertib","Setiap hari"],["4","Teguran awal: Menegur secara pribadi dan santun atas pelanggaran ringan (bahasa, waktu, tidak merespons) dan mencatat singkat.","Menteri / Kabiro","Kejadian dan bukti","Teguran lisan tercatat","2 hari kerja sejak diketahui"],["5","Laporan pelanggaran berat: Menyampaikan laporan kepada Wapres atau Irjen dengan bukti.","Pelapor","Laporan dan bukti","Laporan tercatat","Segera setelah diketahui"],["6","Klarifikasi: Meminta penjelasan terlapor, memberi hak jawab, dan menyampaikan hasil kepada pimpinan.","Irjen","Laporan, bukti","Hasil klarifikasi","5 hari kerja"],["7","Tindak lanjut: Memutuskan pembinaan atau sanksi sesuai ART Pasal 12 melalui SOP- SDM-013; pelecehan atau perundungan melalui SOP-RSK-005.","Pimpinan BEM","Hasil klarifikasi","Keputusan tindak lanjut","3 hari kerja setelah hasil klarifikasi"],["8","Evaluasi standar: Meninjau standar berdasarkan temuan dan masukan pengurus.","Wapres dan Irjen","Catatan teguran dan laporan","Revisi atau penegasan standar","Evaluasi tengah periode"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Standar Etika Komunikasi ditargetkan disahkan paling lambat 5 hari kerja sejak struktur kabinet ditetapkan; Pernyataan Komitmen terkumpul 5 hari kerja setelah orientasi. Hasil akhir: Standar yang berlaku, komitmen tertulis, dan catatan penanganan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Konflik antarpengurus yang berlanjut: SOP-GOV-010.","Pelecehan, intimidasi, atau perundungan: SOP-RSK-005 dan SOP-SDM-017; identitas pelapor dijaga.","Dugaan melibatkan pimpinan BEM: Irjen menangani dan bila perlu berkonsultasi dengan KAUR ORMAWA atau Pembina.","Muatan SARA, penistaan agama, atau paham yang bertentangan dengan AD/ART: dikategorikan pelanggaran berat (ART Pasal 11; AD Pasal 9 ayat 2)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pengurus telah menandatangani Pernyataan Komitmen dalam 5 hari kerja setelah orientasi.","Tidak ada laporan komunikasi bermuatan SARA atau penistaan agama yang tidak ditindaklanjuti.","Pesan kerja ditanggapi dalam 1 x 24 jam pada sedikitnya 90% sampel.","Jumlah pelanggaran etika komunikasi per bulan menurun dari bulan ke bulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Standar Etika Komunikasi.","Pernyataan Komitmen seluruh pengurus.","Catatan teguran, laporan, dan hasil klarifikasi (akses terbatas).","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden meninjau penerapan standar setiap bulan pada rapat kabinet; Irjen menilai kepatuhan pada evaluasi berkala; Sekretaris Jenderal mengarsipkan seluruh dokumen."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Penetapan standar → Sosialisasi dan komitmen → Penerapan harian → Teguran awal → (bila berat) Laporan dan klarifikasi Irjen → Keputusan pimpinan → Evaluasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Pernyataan Komitmen Etika Komunikasi","Nama; jabatan; butir komitmen; tanggal; tanda tangan."],["Formulir Laporan Dugaan Pelanggaran","Pelapor (dapat dirahasiakan); terlapor; tanggal; uraian; bukti; kanal yang digunakan."],["Ringkasan Standar Etika","Adab umum; batas isi; jam tenang; batas respons; jalur keberatan dan pelaporan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Standar Etika Komunikasi dan jam tenang telah disahkan.","☐ Ya ☐ Tidak"],["2","Seluruh pengurus telah menandatangani Pernyataan Komitmen.","☐ Ya ☐ Tidak"],["3","Laporan pelanggaran dilengkapi bukti dan hak jawab terlapor.","☐ Ya ☐ Tidak"],["4","Identitas pelapor dan data pribadi pihak terkait dijaga.","☐ Ya ☐ Tidak"],["5","Sanksi yang dijatuhkan sesuai jenis sanksi pada ART Pasal 12.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-003","g":"Komunikasi dan Informasi","t":"Penyampaian Instruksi dan Penugasan","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[553,556],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara menyampaikan, menerima, mengonfirmasi, memantau, dan menutup instruksi serta penugasan, sehingga pemberi, penerima, hasil yang diharapkan, dan batas waktunya jelas."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk instruksi dan penugasan dari pimpinan, Menteri, Kabiro, dan ketua panitia kepada pengurus atau panitia, baik lisan, tertulis, maupun melalui kanal digital. SOP ini tidak mengatur surat tugas atau mandat (SOP-ADM-006), pendelegasian wewenang (SOP-GOV-008), serta pemantauan kinerja (SOP-SDM-008 dan SOP-MONEV)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 5 ayat (4) (media pembelajaran tanggung jawab, disiplin, dan amanah).","ART Bab III (Tugas BEM) huruf f dan ART Pasal 4 (Wewenang BEM) huruf a dan c.","ART Pasal 10 ayat (4) (agenda Rapat Koordinasi: koordinasi kegiatan dan monitoring).","ART Pasal 11 huruf l (larangan meninggalkan tanggung jawab tanpa alasan sah dan tanpa pemberitahuan resmi).","Matriks kewenangan (SOP-GOV-001) dan pendelegasian wewenang (SOP-GOV-008)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Instruksi","Arahan dari pihak berwenang untuk melakukan atau tidak melakukan sesuatu."],["Penugasan","Instruksi yang memuat pekerjaan, hasil, penerima, dan batas waktu tertentu."],["Pesan Penugasan","Format baku penugasan yang memuat pekerjaan, tujuan, hasil, tenggat, sumber daya, dan cara pelaporan."],["Konfirmasi penerimaan","Jawaban tertulis penerima yang menyatakan menerima, perlu klarifikasi, atau tidak sanggup disertai alasan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Instruksi hanya diberikan oleh pihak yang berwenang menurut matriks kewenangan. Instruksi di luar garis kewenangan dikonfirmasi kepada atasan penerima.","Setiap penugasan memuat: pekerjaan, tujuan, hasil yang diharapkan, tenggat, pemberi dan penerima, sumber daya atau anggaran, serta cara pelaporan.","Penugasan disampaikan secara tertulis pada kanal tercatat (SOP-KOM-001). Instruksi lisan dikonfirmasi tertulis paling lambat 1 hari kerja.","Penerima mengonfirmasi dalam 1 x 24 jam (usulan): menerima, perlu klarifikasi, atau tidak sanggup disertai alasan dan usulan waktu.","Instruksi yang bertentangan dengan AD/ART, peraturan kampus, atau syariat tidak dilaksanakan dan dilaporkan kepada atasan atau Irjen.","Setiap penugasan memiliki satu penanggung jawab utama. Penugasan mendesak mengikuti SOP- GOV-012."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pemberi tugas (pimpinan, Menteri, Kabiro, ketua panitia)","A","Memastikan penugasan sesuai kewenangan, jelas, wajar, dan dipantau sampai selesai."],["Penerima tugas","R","Mengonfirmasi, melaksanakan, melaporkan kemajuan, dan menyerahkan hasil tepat waktu."],["Sekretaris Jenderal","R","Menyediakan format, mencatat penugasan lintas unit pada Daftar Penugasan, dan mengingatkan tenggat."],["Atasan langsung penerima","C","Menyelesaikan benturan beban kerja atau jadwal penerima."],["Wakil Presiden","C","Memutuskan bila terjadi tumpang tindih atau perbedaan pendapat antarunit."],["Inspektur Jenderal","I","Menerima laporan penugasan yang terlambat atau bermasalah untuk pemantauan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Matriks kewenangan (SOP-GOV-001).","Notulen rapat dan daftar tindak lanjut (SOP-ADM-009 dan SOP-ADM-010).","Program kerja dan target bulanan.","Format Pesan Penugasan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pemeriksaan kewenangan: Memastikan penugasan berada dalam kewenangan pemberi dan sumber daya tersedia; menentukan penerima.","Pemberi tugas","Matriks, program kerja","Penugasan layak diberikan","Sebelum disampaikan"],["2","Penyusunan pesan: Menulis Pesan Penugasan: pekerjaan, tujuan, hasil, tenggat, sumber daya, cara lapor.","Pemberi tugas","Format Pesan Penugasan","Pesan Penugasan","Sebelum disampaikan"],["3","Penyampaian: Mengirim melalui kanal tercatat dengan menyebut nama penerima; penugasan lintas unit melalui Sekjen.","Pemberi tugas","Pesan Penugasan","Penugasan terkirim dan tercatat","Pada jam kerja (SOP-KOM-002)"],["4","Konfirmasi: Membalas dengan menerima, meminta klarifikasi, atau menyatakan tidak sanggup disertai alasan dan usulan.","Penerima tugas","Pesan Penugasan","Konfirmasi tertulis","1 x 24 jam"],["5","Klarifikasi atau penyesuaian: Menjawab pertanyaan atau menyesuaikan tenggat dan sumber daya; bila tidak sepakat, atasan langsung atau Wapres memutuskan.","Pemberi tugas, Wapres","Konfirmasi penerima","Penugasan jelas atau diubah","2 hari kerja"],["6","Pencatatan dan pemantauan: Mencatat penugasan lintas unit pada Daftar Penugasan dan memantau kemajuan sesuai SOP-KOM-004.","Sekjen, pemberi tugas","Penugasan terkonfirmasi","Daftar Penugasan diperbarui","Ditinjau mingguan"],["7","Pengingat tenggat: Mengingatkan pada H-2 dan H-1 (usulan); keterlambatan dilaporkan sesuai SOP-MONEV-008.","Pemberi tugas, Sekjen","Daftar Penugasan","Pengingat terkirim","H-2 dan H-1"],["8","Penutupan: Memeriksa hasil, menyatakan selesai atau perlu perbaikan, lalu menutup status penugasan.","Pemberi tugas","Hasil kerja","Penugasan ditutup","2 hari kerja setelah hasil diserahkan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penugasan umum disampaikan paling lambat 3 hari kerja sebelum tenggat (usulan); konfirmasi 1 x 24 jam; pemeriksaan hasil 2 hari kerja. Hasil akhir: penugasan tercatat, terkonfirmasi, dan ditutup."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Penerima tidak merespons dalam 1 x 24 jam: pengingat, lalu atasan langsung pada hari kerja kedua, lalu SOP-SDM-011.","Beban atau jadwal berbenturan: diputuskan atasan langsung penerima atau Wakil Presiden.","Instruksi bertentangan dengan aturan: tidak dilaksanakan dan dilaporkan kepada atasan atau Irjen.","Sengketa kewenangan antarpengurus: SOP-GOV-010.","Penugasan mendesak yang tidak sempat melalui prosedur penuh: SOP-GOV-012."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Sedikitnya 90% penugasan mendapat konfirmasi dalam 1 x 24 jam.","100% penugasan lintas unit tercatat pada Daftar Penugasan.","Persentase penugasan selesai tepat waktu meningkat dari bulan ke bulan.","Tidak ada penugasan tanpa penanggung jawab yang jelas."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Pesan Penugasan dan konfirmasi penerima.","Daftar Penugasan lintas unit.","Catatan penutupan penugasan.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal meninjau Daftar Penugasan setiap minggu pada Rapat Koordinasi; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Periksa kewenangan → Susun Pesan Penugasan → Kirim melalui kanal tercatat → Konfirmasi penerima → Pencatatan dan pemantauan → Penutupan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Format Pesan Penugasan","Pekerjaan; tujuan; hasil yang diharapkan; tenggat; pemberi; penerima; sumber daya atau anggaran; cara pelaporan."],["Daftar Penugasan","Nomor; tanggal; pemberi; penerima; pekerjaan; tenggat; status; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pemberi berwenang menurut matriks kewenangan.","☐ Ya ☐ Tidak"],["2","Pesan memuat pekerjaan, hasil, tenggat, dan cara pelaporan.","☐ Ya ☐ Tidak"],["3","Penugasan dikirim melalui kanal tercatat dan dikonfirmasi penerima.","☐ Ya ☐ Tidak"],["4","Penugasan lintas unit tercatat pada Daftar Penugasan.","☐ Ya ☐ Tidak"],["5","Penugasan yang selesai ditutup dengan catatan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-004","g":"Komunikasi dan Informasi","t":"Format Laporan Progres melalui Kanal Digital","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[557,560],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan format, jadwal, dan jalur pelaporan progres pekerjaan, program, dan unit melalui kanal digital agar kemajuan dapat dipantau, hambatan cepat diketahui, dan bahan evaluasi tersedia."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk laporan progres rutin (mingguan dan bulanan) dari pengurus, kementerian, biro, dan panitia kepada atasan, Sekretaris Jenderal, dan pimpinan. SOP ini tidak mengatur laporan pertanggungjawaban kegiatan (SOP-PRO-020), laporan keuangan (SOP-KEU-015), dan laporan akhir kabinet (SOP-MONEV-012)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) dan (2) (laporan pertanggungjawaban berkala; pengelolaan transparan dan akuntabel).","ART Pasal 3 (Kewajiban BEM) huruf g (laporan berkala kepada pihak berwenang).","ART Pasal 10 ayat (1), (4), dan (5) (Rapat Koordinasi: evaluasi pelaksanaan program, monitoring, notulensi resmi).","ART Pasal 9 ayat (5) (hasil Rapat Kerja menjadi pedoman pelaksanaan program kerja).","SOP-MONEV-003 (laporan progres setiap unit) dan SOP-SDM-009 (pelaporan progres pekerjaan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Laporan mingguan","Laporan singkat progres unit kepada Sekretaris Jenderal menjelang Rapat Koordinasi."],["Laporan bulanan","Laporan lengkap unit yang menjadi bahan laporan bulanan kabinet (SOP-ADM-019)."],["Status pekerjaan","Salah satu dari: belum mulai, berjalan, terhambat, selesai, atau ditunda."],["Bukti progres","Tautan, foto, dokumen, atau catatan yang membuktikan capaian yang dilaporkan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Dua jenis laporan: laporan mingguan singkat dan laporan bulanan unit dengan format lengkap.","Jadwal (usulan): laporan mingguan dikirim pada hari tetap yang ditetapkan Sekjen, sehari sebelum Rapat Koordinasi; laporan bulanan dikirim paling lambat tanggal 5 bulan berikutnya.","Isi laporan: identitas unit dan periode, capaian terhadap target, status tiap pekerjaan atau program, hambatan dan bantuan yang dibutuhkan, rencana periode berikutnya, dan bukti.","Laporan dikirim melalui kanal terdaftar (email resmi atau folder repositori); ringkasan boleh disampaikan di grup koordinasi, tetapi bukan pengganti laporan tertulis.","Laporan memuat data yang benar dan dapat dibuktikan; kesalahan data dikoreksi dan versi revisinya dicatat.","Penamaan berkas mengikuti SOP-ADM-014, misalnya LAP-[UNIT]-[PERIODE].","Hambatan yang berisiko (anggaran, keselamatan, reputasi) dilaporkan segera dan tidak menunggu jadwal laporan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Menetapkan jadwal dan format, merekap laporan, dan menyampaikan rekap kepada pimpinan."],["Menteri / Kabiro","R","Menyusun, memverifikasi, dan mengirim laporan unit tepat waktu."],["Anggota dan ketua panitia","R","Menyampaikan progres dan bukti kepada Menteri atau Kabiro."],["Admin kesekretariatan","R","Memeriksa kelengkapan format, mengingatkan, dan mengarsipkan laporan."],["Wakil Presiden","C","Menelaah hambatan lintas unit dan menentukan tindak lanjut."],["Inspektur Jenderal","C","Memverifikasi laporan secara sampel dan mencatat temuan."],["Presiden","I","Menerima rekap progres kabinet."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Program kerja dan target bulanan hasil Rapat Kerja.","Daftar Penugasan (SOP-KOM-003).","Templat laporan progres.","Bukti progres dari anggota dan panitia."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengumpulan data unit: Menyampaikan progres, status, dan bukti kepada Menteri atau Kabiro.","Anggota, ketua panitia","Penugasan, target","Bahan laporan","H-2 sebelum batas kirim"],["2","Penyusunan laporan: Mengisi templat laporan, memeriksa data dan bukti, lalu memberi status tiap pekerjaan.","Menteri / Kabiro","Bahan laporan","Laporan unit siap kirim","Sebelum batas kirim"],["3","Pengiriman: Mengirim melalui email resmi atau folder repositori dengan penamaan baku; ringkasan ke grup koordinasi.","Menteri / Kabiro","Laporan unit","Laporan terkirim","Sesuai jadwal mingguan atau bulanan"],["4","Pemeriksaan kelengkapan: Memeriksa format dan kelengkapan; mengembalikan laporan yang kurang.","Admin kesekretariatan","Laporan unit","Lengkap atau perlu revisi","1 hari kerja"],["5","Rekapitulasi: Menyusun Rekap Progres Kabinet: capaian, hambatan, dan keterlambatan.","Sekjen","Laporan unit lengkap","Rekap Progres Kabinet","2 hari kerja setelah batas kirim"],["6","Pembahasan dan tindak lanjut: Membahas rekap pada Rapat Koordinasi; mencatat keputusan dan tindak lanjut (SOP-ADM-009 dan SOP-ADM-010).","Pimpinan dan Eksekutif","Rekap","Daftar tindak lanjut","Sesuai jadwal rapat"],["7","Penanganan keterlambatan: Mengingatkan unit yang belum mengirim pada H+1, melaporkan kepada Wapres pada H+3, dan menindaklanjuti sesuai SOP-MONEV- 008.","Sekjen, Wapres","Daftar pengiriman","Laporan diterima atau pembinaan","H+1 dan H+3"],["8","Pengarsipan: Menyimpan laporan dan rekap pada repositori resmi.","Admin kesekretariatan","Laporan final","Arsip lengkap","3 hari kerja setelah rapat"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Rekap progres disusun 2 hari kerja setelah batas kirim laporan. Hasil akhir: laporan unit, Rekap Progres Kabinet, dan daftar tindak lanjut yang terarsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Laporan terlambat atau tidak dikirim: ikuti langkah penanganan keterlambatan dan SOP-MONEV-008.","Data tidak konsisten atau diduga tidak benar: Irjen melakukan verifikasi; dugaan manipulasi laporan diproses melalui SOP-SDM-013.","Hambatan yang membutuhkan keputusan: dibawa ke Rapat Pimpinan (SOP-GOV-005).","Laporan memuat data sensitif atau pribadi: batasi akses sesuai SOP-ADM-020."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Sedikitnya 90% unit mengirim laporan tepat waktu.","100% laporan memuat bukti progres.","Hambatan yang dilaporkan ditindaklanjuti dalam 7 hari kerja (usulan).","Rekap Progres Kabinet tersedia sebelum Rapat Koordinasi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan progres mingguan dan bulanan unit.","Rekap Progres Kabinet.","Daftar tindak lanjut rapat.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa ketepatan waktu dan kelengkapan laporan setiap bulan; Irjen memverifikasi sampel laporan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kumpulkan progres unit → Susun laporan → Kirim melalui kanal terdaftar → Periksa kelengkapan → Rekap kabinet → Rapat Koordinasi → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Laporan Progres Mingguan","Unit; periode; capaian; status pekerjaan; hambatan; kebutuhan bantuan; rencana berikutnya; bukti."],["Templat Laporan Bulanan Unit","Unit; periode; capaian terhadap target; rincian program; hambatan dan penyebab; tindakan perbaikan; lampiran bukti."],["Rekap Progres Kabinet","Unit; capaian; status; hambatan; keterlambatan; tindak lanjut; penanggung jawab."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Laporan memuat identitas unit, periode, capaian, status, hambatan, dan rencana.","☐ Ya ☐ Tidak"],["2","Setiap capaian disertai bukti yang dapat dibuka.","☐ Ya ☐ Tidak"],["3","Laporan dikirim melalui kanal terdaftar dengan penamaan baku.","☐ Ya ☐ Tidak"],["4","Keterlambatan telah ditindaklanjuti sesuai jadwal.","☐ Ya ☐ Tidak"],["5","Laporan dan rekap tercatat pada Register Dokumen.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-005","g":"Komunikasi dan Informasi","t":"Pengelolaan Grup WhatsApp atau Platform Koordinasi","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[561,564],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara membuat, menamai, mengisi, mengelola, memoderasi, mengarsipkan, dan menutup grup atau platform koordinasi, sehingga komunikasi tertib, aman, dan informasi penting tidak tercecer."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh grup atau kanal koordinasi atas nama BEM, kementerian, biro, dan panitia kegiatan, baik di WhatsApp maupun platform lain yang ditetapkan. SOP ini tidak mengatur grup pribadi yang tidak mengatasnamakan BEM, adab berkomunikasi (SOP-KOM-002), dan pengamanan akun (SOP-KOM-013)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (2) (pengelolaan organisasi secara transparan, akuntabel, efektif, dan efisien).","ART Pasal 4 (Wewenang BEM) huruf c (mengusulkan pembentukan panitia kegiatan dan tim kerja internal).","ART Pasal 3 (Kewajiban BEM) huruf d (menjaga nama baik) dan ART Pasal 11 huruf g dan h.","SOP-KOM-001 (kanal resmi), SOP-KOM-002 (etika komunikasi), dan SOP-KOM-013 (akses akun).","SOP-SDM-018 (kerahasiaan data dan informasi pribadi anggota)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Grup resmi","Grup atau kanal koordinasi yang tercatat pada Daftar Kanal Resmi."],["Admin grup","Pengurus yang ditunjuk untuk membuat, mengatur, dan memoderasi grup."],["Grup panitia","Grup sementara yang dibentuk untuk satu kegiatan dan ditutup setelah kegiatan selesai."],["Moderasi","Pengaturan isi dan keanggotaan grup agar sesuai tujuan dan aturan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Jenis grup: grup Pimpinan, grup Kabinet (seluruh pengurus), grup unit (kementerian atau biro), dan grup panitia. Grup pengumuman satu arah dapat dibuat bila diperlukan.","Penamaan baku: BEM-[Jenis]-[Nama]-[Periode], misalnya BEM-Unit-DKV-2026/2027. Deskripsi grup memuat tujuan, aturan singkat, dan nama admin.","Setiap grup memiliki sedikitnya dua admin (admin utama dan admin cadangan) agar tidak bergantung pada satu orang (usulan).","Anggota hanya pengurus atau panitia yang berkepentingan. Pihak luar tidak dimasukkan ke grup internal; dibuat kanal khusus dengan akses terbatas.","Tautan undangan grup tidak disebarkan di ruang publik.","Isi grup mengikuti SOP-KOM-002 dan tujuan grup. Pesan di luar topik, iklan, dan isu pribadi tidak diizinkan.","Keputusan dan persetujuan yang muncul di grup dikonfirmasi pada kanal tercatat (SOP-KOM-001).","Anggota yang berhenti atau diberhentikan dikeluarkan dari grup paling lambat 1 hari kerja; akses berkas dicabut (SOP-KOM-013).","Grup panitia ditutup dan diarsipkan paling lambat 14 hari setelah tujuannya selesai."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Menyetujui pembuatan grup, mencatatnya pada Daftar Kanal Resmi, dan meninjau grup secara berkala."],["Admin grup","R","Membuat, menamai, mengisi anggota, memoderasi, memperbarui keanggotaan, dan mengarsipkan."],["Menteri / Kabiro","R","Mengajukan grup unit, menunjuk admin, dan memastikan anggota tepat."],["Ketua panitia","R","Mengajukan grup panitia dan memastikan penutupan setelah kegiatan."],["Wakil Presiden","C","Memutuskan bila terjadi sengketa moderasi atau pelanggaran aturan grup."],["Inspektur Jenderal","C","Memeriksa kepatuhan pengelolaan grup pada evaluasi berkala."],["Seluruh anggota grup","I","Menaati aturan grup dan tidak meneruskan isi grup tertutup keluar."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Struktur kabinet dan susunan panitia.","Daftar Kanal Resmi.","Formulir Permintaan Grup."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Permintaan: Mengisi Formulir Permintaan Grup: tujuan, anggota, dan calon admin.","Menteri / Kabiro, ketua panitia","Formulir","Permintaan tercatat","Sesuai kebutuhan"],["2","Persetujuan: Memeriksa kebutuhan, keamanan, dan kemungkinan tumpang tindih; menyetujui dan mencatat pada Daftar Kanal Resmi.","Sekjen","Formulir","Grup disetujui","1 hari kerja"],["3","Pembuatan: Membuat grup sesuai penamaan baku, mengisi deskripsi, mengatur izin kirim dan ubah info, serta menunjuk admin cadangan.","Admin grup","Persetujuan","Grup aktif","1 hari kerja setelah disetujui"],["4","Pengisian anggota: Memasukkan anggota sesuai daftar dan mengirim pesan aturan grup.","Admin grup","Daftar anggota","Anggota terdaftar","Pada hari pembuatan"],["5","Penggunaan dan moderasi: Memoderasi isi, mengingatkan pelanggaran, mengalihkan topik, dan meringkas keputusan.","Admin grup","Aturan grup","Grup tertib","Setiap hari"],["6","Pembaruan keanggotaan: Menambah atau mengeluarkan anggota sesuai pengangkatan atau pemberhentian; mencabut akses berkas.","Admin grup, Sekjen","Informasi pengurus","Keanggotaan mutakhir","1 hari kerja"],["7","Peninjauan berkala: Memeriksa seluruh grup resmi (aktif, admin, anggota) dan menutup grup yang tidak lagi diperlukan.","Sekjen","Daftar Kanal Resmi","Catatan peninjauan","Setiap bulan"],["8","Penutupan dan pengarsipan: Menyimpan berkas dan ringkasan keputusan pada repositori, mengumumkan penutupan, lalu menonaktifkan grup.","Admin grup","Berkas grup","Grup ditutup, arsip lengkap","14 hari setelah tujuan selesai"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Persetujuan grup diberikan 1 hari kerja setelah permintaan lengkap; grup panitia ditutup paling lambat 14 hari setelah tujuannya selesai. Hasil akhir: grup resmi yang tercatat, tertib, dan terarsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Grup atas nama BEM dibuat tanpa persetujuan: Sekjen mendaftarkan atau menutupnya setelah berkoordinasi dengan Presiden.","Pelanggaran aturan di dalam grup: SOP-KOM-002; pelanggaran berat melalui SOP-SDM-013.","Isi grup bocor ke luar: SOP-RSK-009 dan SOP-RSK-010.","Admin berhalangan atau kehilangan akses: admin cadangan mengambil alih; ikuti SOP-KOM-013.","Anggota yang berhenti menolak keluar dari grup: Sekjen menyampaikan kepada pimpinan."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% grup resmi tercatat dan memiliki sedikitnya dua admin.","Anggota yang berhenti dikeluarkan dari grup dalam 1 hari kerja pada 100% kasus.","Grup panitia diarsipkan dalam 14 hari setelah tujuan selesai.","Tidak ada grup atas nama BEM yang tidak terdaftar."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar grup resmi (bagian dari Daftar Kanal Resmi).","Aturan grup dan ringkasan keputusan yang diarsipkan.","Catatan peninjauan dan penutupan grup.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal meninjau seluruh grup resmi setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Permintaan grup → Persetujuan Sekjen → Pembuatan dan pengisian anggota → Moderasi dan pembaruan → Peninjauan bulanan → Penutupan dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Grup","Nama grup; jenis; tujuan; calon anggota; admin utama dan cadangan; masa aktif; tanggal."],["Templat Pesan Aturan Grup","Tujuan grup; aturan isi; jam tenang; batas respons; larangan; nama admin."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Grup tercatat pada Daftar Kanal Resmi dan memiliki sedikitnya dua admin.","☐ Ya ☐ Tidak"],["2","Nama dan deskripsi grup sesuai ketentuan baku.","☐ Ya ☐ Tidak"],["3","Anggota sesuai daftar dan tidak ada pihak luar pada grup internal.","☐ Ya ☐ Tidak"],["4","Anggota yang berhenti sudah dikeluarkan dan akses berkas dicabut.","☐ Ya ☐ Tidak"],["5","Grup yang selesai sudah diarsipkan dan ditutup.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-006","g":"Komunikasi dan Informasi","t":"Pengelolaan Email Resmi Organisasi","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[565,568],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan penggunaan, pemantauan, pengiriman, pengarsipan, dan pengamanan email resmi BEM agar komunikasi tertulis dengan kampus dan pihak luar tertib, tercatat, dan terlindungi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh email resmi BEM (sekretariat, pimpinan, dan unit) yang dipakai untuk komunikasi internal, dengan kampus, dan dengan pihak luar. SOP ini tidak mengatur format dan penomoran surat (SOP- ADM-002 dan SOP-ADM-003) serta pengamanan akun secara rinci (SOP-KOM-013)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (2) (pengelolaan organisasi secara transparan dan akuntabel).","ART Pasal 4 (Wewenang BEM) huruf f (menandatangani surat-surat resmi dan dokumen organisasi).","ART Pasal 3 (Kewajiban BEM) huruf g dan h (laporan berkala; mematuhi peraturan kampus).","SOP-ADM-001, SOP-ADM-002, SOP-ADM-013, dan SOP-ADM-014.","SOP-KOM-013 (pengelolaan akses akun digital) dan SOP-RSK-008 (pengamanan data dan akses digital)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Email resmi","Alamat email atas nama organisasi atau jabatan yang tercatat pada Daftar Kanal Resmi."],["Kotak masuk sekretariat","Kotak masuk bersama yang dipantau Sekretariat untuk menerima surat dan permintaan resmi."],["Tanda tangan email","Blok identitas baku di akhir email: nama, jabatan, unit, dan kontak resmi."],["Phishing","Upaya penipuan melalui email atau tautan untuk mencuri data atau akses akun."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Email resmi dibuat atas nama organisasi atau jabatan, bukan nama pribadi. Penyedia layanan dan alamat ditetapkan Presiden melalui Daftar Kanal Resmi.","Kotak masuk sekretariat dipantau setiap hari kerja; surat penting diteruskan kepada pejabat atau unit berwenang.","Email resmi hanya dipakai untuk urusan organisasi, bukan untuk pendaftaran layanan pribadi.","Email yang mengikat atas nama BEM (kerja sama, permintaan resmi, pernyataan) memerlukan persetujuan pejabat berwenang sesuai SOP-ADM-004.","Format: subjek jelas (Jenis - Perihal - Unit), salam pembuka dan penutup, isi ringkas, lampiran PDF dengan nama sesuai SOP-ADM-014, dan tanda tangan baku.","Alamat pihak luar dalam jumlah banyak dimasukkan pada bcc; atasan atau pihak terkait pada cc.","Email masuk resmi diakui atau dibalas paling lambat 2 hari kerja (usulan).","Lampiran sensitif memakai tautan dengan akses terbatas. Kata sandi tidak dikirim melalui email.","Email dan lampiran penting disimpan di repositori (SOP-ADM-013), bukan hanya di kotak masuk.","Tautan atau lampiran yang mencurigakan tidak dibuka dan dilaporkan kepada Sekjen (SOP-RSK-008)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Menetapkan alamat email resmi, aturan pemakaian, dan memeriksa keamanannya."],["Admin kesekretariatan","R","Memantau kotak masuk, mencatat, meneruskan, memeriksa email keluar, dan mengarsipkan."],["Pejabat pengirim atau penandatangan","R","Menyetujui dan mengirim atau menandatangani email yang mengikat."],["Unit pemohon","R","Menyusun draf email sesuai templat dan memberi data yang benar."],["Inspektur Jenderal","C","Memeriksa kepatuhan dan keamanan pengelolaan email pada evaluasi berkala."],["Seluruh pengurus","I","Memakai email resmi hanya melalui prosedur dan tidak mengirim atas nama BEM dari akun pribadi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Kanal Resmi.","Templat email resmi dan tanda tangan baku.","Register surat masuk dan keluar (SOP-ADM-001 dan SOP-ADM-002)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan akun: Menetapkan alamat email resmi organisasi dan unit; menyetujui dan mendaftarkannya sesuai SOP-KOM- 013.","Sekjen, Presiden","Kebutuhan unit","Akun resmi terdaftar","3 hari kerja setelah struktur ditetapkan"],["2","Pemantauan kotak masuk: Memeriksa kotak masuk, memilah surat penting, dan mencatat pada register surat masuk.","Admin kesekretariatan","Email masuk","Email tercatat","Setiap hari kerja"],["3","Penerusan: Meneruskan email kepada pejabat atau unit berwenang dengan catatan batas waktu.","Admin kesekretariatan","Email masuk","Email diteruskan","1 hari kerja"],["4","Penyusunan email keluar: Menyusun draf dengan templat; email yang mengikat diajukan kepada pejabat berwenang (SOP-ADM-004).","Unit pemohon","Kebutuhan, templat","Draf email","Sesuai tenggat"],["5","Pemeriksaan: Memeriksa subjek, penerima, lampiran, tanda tangan, dan memastikan tidak ada data sensitif.","Admin kesekretariatan","Draf email","Email siap kirim","1 hari kerja"],["6","Pengiriman: Mengirim dari akun resmi dengan cc atau bcc yang tepat dan menyimpan bukti terkirim.","Pejabat pengirim, admin","Email siap kirim","Email terkirim","Sesuai tenggat"],["7","Pengarsipan: Menyimpan email dan lampiran penting pada repositori dan menandainya pada register.","Admin kesekretariatan","Email terkirim atau masuk","Arsip lengkap","3 hari kerja"],["8","Pemeriksaan keamanan: Memeriksa daftar akses, penerusan otomatis, kata sandi, dan autentikasi dua langkah.","Sekjen","Daftar Akun","Catatan pemeriksaan","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Email masuk resmi diakui atau dibalas 2 hari kerja dan diarsipkan 3 hari kerja (usulan). Hasil akhir: email resmi terkirim atau diterima, tercatat pada register, dan terarsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Email dari pihak luar yang meminta transfer dana atau data pribadi: verifikasi melalui kanal lain sebelum ditanggapi.","Dugaan phishing atau akun disusupi: SOP-RSK-008; dugaan kebocoran data: SOP-RSK-009.","Email berisi pengaduan atau aspirasi: teruskan ke SOP-RSK-004 atau SOP-ADV-001.","Email mendesak dari kampus: langsung diteruskan kepada Presiden dan Sekjen.","Email salah kirim: tarik bila memungkinkan, minta penghapusan kepada penerima, dan catat pada SOP-RSK-012."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% email masuk resmi diakui atau dibalas dalam 2 hari kerja.","Tidak ada email atas nama BEM yang dikirim dari akun pribadi.","100% akun email resmi memakai autentikasi dua langkah dan memiliki pengelola tercatat.","Email penting terarsip dalam 3 hari kerja."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Email resmi terkirim beserta bukti.","Register surat masuk dan keluar yang mutakhir.","Arsip email dan lampiran.","Catatan pemeriksaan keamanan bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa register dan keamanan email setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Penetapan akun → Pantau kotak masuk → Teruskan atau susun balasan → Periksa → Kirim → Arsip → Pemeriksaan keamanan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Email Resmi","Subjek; salam pembuka; isi; penutup; tanda tangan baku; lampiran."],["Formulir Pengajuan Pengiriman Email Resmi","Pemohon; unit; tujuan; penerima; ringkasan isi; lampiran; pejabat penyetuju; tenggat."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Email dikirim dari akun resmi, bukan akun pribadi.","☐ Ya ☐ Tidak"],["2","Email yang mengikat telah disetujui pejabat berwenang.","☐ Ya ☐ Tidak"],["3","Subjek, penerima, dan lampiran telah diperiksa.","☐ Ya ☐ Tidak"],["4","Tidak ada data sensitif atau kata sandi dalam isi email.","☐ Ya ☐ Tidak"],["5","Email dan lampiran penting telah diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-007","g":"Komunikasi dan Informasi","t":"Pembuatan dan Persetujuan Konten Publikasi","o":"Kepala Biro Desain Komunikasi Visual","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro DKV","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[569,572],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan alur permintaan, pembuatan, pemeriksaan, persetujuan, dan penayangan konten publikasi BEM, sehingga isi akurat, sesuai syariat dan aturan kampus, serta mencerminkan organisasi dengan tepat."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh konten publikasi atas nama BEM, kementerian, biro, dan panitia, baik daring maupun luring (poster, spanduk, infografis, naskah, video, dan ucapan). SOP ini tidak mengatur pengelolaan akun (SOP-KOM-008), koreksi publikasi (SOP-KOM-009), pernyataan resmi (SOP-KOM-010), dokumentasi (SOP-KOM-011), dan logo serta templat (SOP-KOM-014)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 3 ayat (1) dan Pasal 5 ayat (3) (landasan Al-Qur'an dan As-Sunnah; kegiatan ilmiah dan dakwah sesuai manhaj Ahlusunah wal Jamaah).","AD Pasal 18 ayat (1) dan (2) (lambang yang disahkan STDIIS Jember).","ART Pasal 2 (Hak BEM) huruf b dan h; ART Pasal 3 (Kewajiban BEM) huruf a, d, dan h.","ART Pasal 11 huruf a, b, d, e, g, dan h (larangan SARA, penistaan agama, paham yang bertentangan, politik praktis, pencemaran nama baik, pelecehan).","SOP-PRO-013 (publikasi dan pendaftaran peserta) dan SOP-KOM-014 (logo dan templat)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Brief","Ringkasan kebutuhan konten: tujuan, sasaran, isi pokok, data, tenggat, dan tingkat konten."],["Konten Tingkat 1","Konten rutin: informasi layanan, pengumuman kegiatan yang sudah disetujui, ucapan umum, dan edukasi umum."],["Konten Tingkat 2","Konten yang menyangkut sikap atau kebijakan BEM, kampus, advokasi, kerja sama atau sponsor, serta isu sensitif."],["Pemeriksa keagamaan","Pihak kompeten yang ditunjuk Presiden atau Pembina untuk memeriksa muatan dalil, hukum, atau pandangan keagamaan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Konten memuat sumber atau dasar informasi, tanggal berlaku, dan kontak resmi, serta memakai logo dan templat yang disahkan (SOP-KOM-014).","Konten tidak memuat: SARA, penistaan agama, kabar yang belum terverifikasi, data pribadi tanpa izin, afiliasi politik praktis atas nama BEM tanpa izin kampus, serta iklan atau sponsor yang bertentangan dengan syariat atau belum disetujui.","Konten yang memuat dalil, pembahasan hukum agama, atau pandangan keagamaan harus bersumber jelas dan diperiksa pemeriksa keagamaan sebelum tayang. BEM tidak mengeluarkan fatwa.","Tingkat 1 disetujui Kepala Biro DKV. Tingkat 2 disetujui Presiden atau Wakil Presiden yang ditunjuk (SOP-GOV-008) setelah diperiksa Kepala Biro DKV.","Konten yang mengatasnamakan kampus atau menyangkut kerja sama eksternal dikonfirmasi kepada KAUR ORMAWA bila kampus mensyaratkan.","Konten tidak boleh tayang sebelum persetujuan tercatat. Jadwal tayang dicatat pada Kalender Konten.","Brief diserahkan paling lambat H-3 untuk desain biasa dan H-7 untuk video atau konten besar (usulan). Revisi dibatasi dua putaran (usulan).","Gambar, huruf, musik, dan video milik pihak lain dipakai hanya dengan izin atau lisensi terbuka dan sumbernya dicantumkan; konten audio mengikuti ketentuan kampus dan syariat."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro DKV","A","Mengelola antrean, memeriksa isi, dan menyetujui konten Tingkat 1."],["Pemohon (unit atau panitia)","R","Menyerahkan brief dan data yang benar serta tepat waktu."],["Staf Biro DKV","R","Menyusun desain atau naskah, memeriksa fakta bersama pemohon, dan merevisi."],["Presiden","C","Menyetujui konten Tingkat 2 dan menunjuk pemeriksa keagamaan."],["Sekretaris Jenderal","C","Memeriksa kesesuaian administrasi (nomor surat, jadwal resmi) dan kewenangan."],["Admin media sosial","R","Menayangkan konten yang disetujui sesuai SOP-KOM-008."],["Inspektur Jenderal","I","Menerima laporan pelanggaran konten dan memeriksa kepatuhan secara sampel."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Permintaan Konten (brief).","Data dan sumber informasi dari pemohon.","Templat, logo, dan aset visual resmi.","Kalender organisasi (SOP-ADM-018)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Permintaan konten: Mengisi Formulir Permintaan Konten: tujuan, sasaran, isi pokok, data, tenggat, dan tingkat konten.","Pemohon","Data dan sumber","Permintaan tercatat","H-3 (desain) atau H-7 (video)"],["2","Penerimaan dan penentuan tingkat: Memeriksa kelengkapan brief, menentukan Tingkat 1 atau 2, dan memasukkan ke antrean dan Kalender Konten.","Kabiro DKV","Brief","Antrean dan tingkat ditetapkan","1 hari kerja"],["3","Pembuatan draf: Menyusun draf dengan templat dan aset resmi serta memeriksa fakta bersama pemohon.","Staf Biro DKV","Brief, templat","Draf konten","2 sampai 3 hari kerja"],["4","Pemeriksaan isi: Memeriksa dengan Checklist Konten (fakta, bahasa, aturan, hak cipta, logo); administrasi diperiksa Sekjen; muatan agama diperiksa pemeriksa keagamaan.","Kabiro DKV, Sekjen","Draf, checklist","Catatan pemeriksaan","1 hari kerja"],["5","Revisi: Memperbaiki draf sesuai catatan; maksimal dua putaran.","Staf Biro DKV, pemohon","Catatan pemeriksaan","Draf final","2 hari kerja"],["6","Persetujuan: Tingkat 1 disetujui Kabiro DKV; Tingkat 2 disetujui Presiden atau Wapres yang ditunjuk (dan dikonfirmasi ke kampus bila perlu).","Kabiro DKV, Presiden","Draf final","Persetujuan tertulis pada kanal tercatat","1 hari kerja (Tingkat 1); 2 hari kerja (Tingkat 2)"],["7","Penayangan: Menayangkan sesuai jadwal dan menyimpan bukti tayang (tautan atau tangkapan layar).","Admin media sosial","Konten disetujui","Konten tayang","Sesuai Kalender Konten"],["8","Pengarsipan dan evaluasi: Menyimpan berkas final dan persetujuan; mencatat jangkauan dan tanggapan; membawa masukan ke evaluasi.","Kabiro DKV","Bukti tayang","Arsip dan catatan evaluasi","3 hari kerja setelah tayang"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Konten Tingkat 1 diselesaikan paling lambat 3 hari kerja sejak brief lengkap; Tingkat 2 paling lambat 5 hari kerja; video atau konten besar paling lambat 10 hari kerja (usulan). Hasil akhir: konten tayang dengan catatan persetujuan dan arsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Konten mendesak: persetujuan lisan Presiden atau Wapres dicatat tertulis dalam 1 hari kerja (SOP- GOV-012).","Perbedaan pendapat tentang isi: diputuskan Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan.","Pemohon menekan konten tayang tanpa persetujuan: Sekjen atau Wapres menegur sesuai SOP-KOM- 002.","Kesalahan ditemukan setelah tayang: SOP-KOM-009; isu yang membesar: SOP-KOM-012.","Konten menyangkut sponsor atau kerja sama: SOP-HKE-007 dan SOP-HKE-008."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% konten yang tayang memiliki catatan persetujuan.","Sedikitnya 90% permintaan konten selesai sesuai standar waktu.","Tidak ada konten tayang yang ditarik karena melanggar aturan.","Seluruh konten memakai logo dan templat yang disahkan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Konten final yang tayang atau terpasang.","Catatan persetujuan dan catatan pemeriksaan.","Antrean dan Kalender Konten.","Bukti tayang dan entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro DKV meninjau antrean dan kepatuhan persetujuan setiap bulan; Irjen memeriksa sampel konten pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Permintaan konten → Penentuan tingkat → Pembuatan draf → Pemeriksaan isi → Persetujuan → Penayangan → Arsip dan evaluasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Konten","Pemohon; unit; tujuan; sasaran; isi pokok; data dan sumber; tenggat; tingkat konten; tanggal."],["Checklist Konten","Fakta dan sumber; bahasa; kesesuaian aturan; hak cipta; logo dan templat; data pribadi; izin tayang."],["Kalender Konten","Tanggal tayang; platform; konten; penanggung jawab; status persetujuan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Brief lengkap dan tingkat konten telah ditentukan.","☐ Ya ☐ Tidak"],["2","Fakta, sumber, dan tanggal telah diperiksa.","☐ Ya ☐ Tidak"],["3","Tidak ada muatan yang dilarang pada ART Pasal 11.","☐ Ya ☐ Tidak"],["4","Muatan keagamaan telah diperiksa pemeriksa keagamaan.","☐ Ya ☐ Tidak"],["5","Persetujuan tercatat sebelum tayang dan bukti tayang disimpan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-008","g":"Komunikasi dan Informasi","t":"Pengelolaan Media Sosial","o":"Kepala Biro Desain Komunikasi Visual","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro DKV","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[573,576],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan tata kelola akun media sosial resmi BEM, meliputi peran admin, perencanaan konten, interaksi, moderasi, eskalasi isu, dan pelaporan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh akun media sosial resmi BEM, kementerian, dan biro. SOP ini tidak mengatur pembuatan konten (SOP-KOM-007), koreksi publikasi (SOP-KOM-009), pernyataan resmi (SOP-KOM-010), komunikasi krisis (SOP-KOM-012), dan pengamanan akses akun (SOP-KOM-013)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 5 ayat (3) (kegiatan ilmiah, dakwah, sosial, dan pengabdian sesuai manhaj Ahlusunah wal Jamaah) dan AD Pasal 17 ayat (2).","AD Pasal 18 ayat (1) dan (2) (lambang yang disahkan STDIIS Jember).","ART Pasal 2 (Hak BEM) huruf g dan h (menyampaikan aspirasi dan kritik konstruktif).","ART Pasal 3 (Kewajiban BEM) huruf c dan d (memberi manfaat bagi civitas kampus dan masyarakat; menjaga nama baik).","ART Pasal 11 huruf a, b, e, g, dan h (larangan SARA, penistaan agama, politik praktis, pencemaran nama baik, pelecehan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Akun resmi","Akun media sosial yang tercatat pada Daftar Kanal Resmi dan dikelola atas nama organisasi."],["Admin akun","Pengurus yang ditunjuk untuk menayangkan konten, membalas pesan, dan memoderasi."],["Moderasi","Menyembunyikan, menghapus, atau menindaklanjuti komentar dan pesan yang melanggar aturan."],["Kalender Konten","Jadwal tayang konten bulanan yang disusun dari kalender organisasi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Hanya akun yang terdaftar pada Daftar Kanal Resmi yang boleh memakai nama dan lambang BEM. Akun lain yang mencatut dilaporkan dan diminta ditutup.","Peran: admin utama (Kepala Biro DKV), admin pelaksana (staf), dan admin cadangan. Akses diberikan sesuai kebutuhan (SOP-KOM-013).","Isi akun: informasi kegiatan, edukasi, dakwah, ilmiah, layanan mahasiswa, dan apresiasi. Isi rapat tertutup, data pribadi, dan dokumen rahasia tidak diunggah.","Kalender Konten bulanan disusun Biro DKV dari kalender organisasi (SOP-ADM-018) dan dibagikan kepada unit.","Komentar dan pesan dibalas santun dan faktual paling lambat 1 x 24 jam hari kerja (usulan). Pertanyaan yang membutuhkan keputusan dialihkan ke unit terkait; aspirasi diteruskan ke SOP-ADV- 001.","Komentar berisi SARA, caci maki, pornografi, hoaks, atau serangan pribadi disembunyikan atau dihapus dan didokumentasikan; pelaku berulang dapat diblokir atas izin Kepala Biro DKV.","Admin tidak berdebat di kolom komentar dan tidak menyuarakan opini pribadi lewat akun resmi. Polemik dialihkan ke jalur resmi.","Interaksi akun resmi (mengikuti, membagikan ulang, menyukai) hanya dengan akun yang selaras dengan tujuan organisasi dan tidak menunjukkan afiliasi politik praktis (ART Pasal 11 huruf e).","Gejala isu yang memanas dilaporkan segera kepada Kepala Biro DKV untuk ditangani melalui SOP- KOM-012."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro DKV","A","Mengelola akun, mengesahkan Kalender Konten, dan memutuskan moderasi serta pemblokiran."],["Admin media sosial","R","Menayangkan, memantau, membalas, memoderasi, dan melaporkan."],["Staf Biro DKV","R","Menyiapkan konten sesuai Kalender Konten (SOP-KOM-007)."],["Presiden","C","Menyetujui daftar akun dan menentukan sikap pada isu sensitif."],["Sekretaris Jenderal","C","Mencatat akun pada Daftar Kanal Resmi dan memastikan keamanan akses (SOP-KOM-013)."],["Inspektur Jenderal","C","Memeriksa kepatuhan pengelolaan akun pada evaluasi berkala."],["Seluruh pengurus","I","Membagikan konten resmi dan tidak menayangkan konten atas nama BEM di luar Biro DKV."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Kanal Resmi.","Kalender organisasi dan program kerja.","Konten yang telah disetujui (SOP-KOM-007).","Templat jawaban standar."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pendaftaran akun: Mengajukan akun baru atau perubahan akun; menyetujui; mendaftarkan pada Daftar Kanal Resmi dan SOP-KOM- 013.","Kabiro DKV, Sekjen, Presiden","Kebutuhan unit","Akun terdaftar","3 hari kerja"],["2","Perencanaan: Menyusun Kalender Konten bulanan dari kalender organisasi dan program; mengesahkan dan membagikan.","Biro DKV","Kalender organisasi","Kalender Konten","Paling lambat tanggal 25 bulan sebelumnya"],["3","Penayangan: Menayangkan konten yang telah disetujui sesuai kalender dan menyimpan bukti tayang.","Admin media sosial","Konten disetujui","Konten tayang","Sesuai kalender"],["4","Pemantauan harian: Memeriksa komentar, pesan, dan sebutan; memilah menjadi layak dibalas, aspirasi, dan bermasalah.","Admin media sosial","Interaksi masuk","Daftar tindak lanjut","Setiap hari kerja"],["5","Balasan dan penerusan: Membalas dengan templat jawaban; meneruskan aspirasi ke SOP-ADV- 001 dan pertanyaan teknis ke unit terkait.","Admin media sosial","Pesan dan komentar","Balasan terkirim","1 x 24 jam"],["6","Moderasi: Menyembunyikan atau menghapus komentar yang melanggar, menyimpan bukti, dan mencatat pelaku berulang.","Admin media sosial, Kabiro DKV","Komentar bermasalah","Catatan moderasi","Pada hari yang sama"],["7","Eskalasi isu: Melaporkan gejala isu yang memanas kepada Kabiro DKV dan Presiden untuk SOP-KOM-012.","Admin media sosial","Tangkapan layar, tautan","Laporan isu","Pada hari yang sama"],["8","Pelaporan dan evaluasi: Menyusun laporan bulanan (unggahan, jangkauan, aspirasi, moderasi) dan menyesuaikan kalender.","Admin media sosial, Kabiro DKV","Data akun","Laporan bulanan","Paling lambat tanggal 5 bulan berikutnya"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Balasan interaksi dalam 1 x 24 jam hari kerja; laporan bulanan paling lambat tanggal 5 bulan berikutnya (usulan). Hasil akhir: akun resmi yang aktif, tertib, dan terlaporkan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Akun diretas atau kehilangan akses: SOP-KOM-013, SOP-RSK-008, dan SOP-RSK-009.","Isu atau polemik membesar: SOP-KOM-012; pernyataan resmi: SOP-KOM-010.","Kesalahan konten setelah tayang: SOP-KOM-009.","Aspirasi atau pengaduan lewat kolom komentar atau pesan: SOP-ADV-001 dan SOP-RSK-004.","Akun lain mencatut nama atau lambang BEM: Kabiro DKV melapor ke Presiden untuk ditindaklanjuti ke kampus bila perlu."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% akun resmi tercatat dan memiliki sedikitnya dua pengelola.","Sedikitnya 90% komentar dan pesan dibalas dalam 1 x 24 jam hari kerja.","Komentar melanggar aturan dimoderasi pada hari yang sama pada 100% kasus.","Laporan bulanan media sosial diterima tepat waktu."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Kalender Konten bulanan.","Bukti tayang dan catatan moderasi.","Laporan bulanan media sosial.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro DKV memeriksa kepatuhan pengelolaan akun setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pendaftaran akun → Kalender Konten → Penayangan → Pemantauan harian → Balasan dan moderasi → Eskalasi isu bila perlu → Laporan bulanan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pendaftaran Akun","Nama akun; platform; fungsi; pengelola utama dan cadangan; email atau nomor pemulihan; tanggal; persetujuan."],["Templat Laporan Bulanan Media Sosial","Periode; jumlah unggahan; jangkauan; interaksi; aspirasi masuk; kejadian moderasi; masalah; rencana perbaikan."],["Templat Jawaban Standar","Pertanyaan umum; jawaban baku; unit rujukan; kontak resmi."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Akun tercatat pada Daftar Kanal Resmi dan memiliki sedikitnya dua pengelola.","☐ Ya ☐ Tidak"],["2","Kalender Konten bulanan telah disahkan dan dibagikan.","☐ Ya ☐ Tidak"],["3","Setiap konten yang tayang memiliki persetujuan (SOP-KOM-007).","☐ Ya ☐ Tidak"],["4","Komentar dan pesan telah dipantau dan dibalas sesuai standar waktu.","☐ Ya ☐ Tidak"],["5","Laporan bulanan telah dikirim dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-009","g":"Komunikasi dan Informasi","t":"Penanganan Koreksi, Kesalahan, dan Penghapusan Publikasi","o":"Kepala Biro Desain Komunikasi Visual","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro DKV","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[577,580],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara menerima laporan, menilai, mengoreksi, menarik, menghapus, dan mengomunikasikan perbaikan atas publikasi yang keliru atau bermasalah secara cepat, jujur, dan terdokumentasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh publikasi atas nama BEM (daring dan luring) yang mengandung kesalahan fakta, tulisan, tanggal, nama, atau desain, melanggar aturan, atau menimbulkan keberatan. SOP ini tidak mengatur isu reputasi yang meluas (SOP-KOM-012) dan pelanggaran etik berat oleh individu (SOP-SDM-013)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (2) (pengelolaan organisasi secara transparan dan akuntabel).","ART Pasal 3 (Kewajiban BEM) huruf d dan h (menjaga nama baik; mematuhi peraturan kampus).","ART Pasal 11 huruf g (larangan tindakan yang mencemarkan nama baik organisasi atau lembaga).","ART Pasal 13 ayat (7) dan (9) (prinsip keadilan, objektivitas, dan hak klarifikasi).","SOP-KOM-007, SOP-KOM-010, dan SOP-KOM-012."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kesalahan minor","Kesalahan ketik atau desain kecil yang tidak mengubah makna."],["Kesalahan substantif","Kesalahan data, tanggal, nama, atau klaim yang mengubah makna atau berpotensi merugikan pihak lain."],["Pelanggaran konten","Muatan SARA, data pribadi, pelanggaran hak cipta, atau yang bertentangan dengan syariat dan aturan kampus."],["Log Koreksi","Catatan seluruh laporan kesalahan beserta penyebab, tindakan, dan pelaksananya."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Prinsip: mengakui kesalahan dengan cepat, mengoreksi dengan jelas, dan tidak menyembunyikan jejak kesalahan substantif.","Kesalahan minor diperbaiki langsung atau berkas diganti dan dicatat pada Log Koreksi.","Kesalahan substantif dikoreksi secara terbuka (catatan koreksi pada unggahan atau unggahan koreksi) disertai perbaikan.","Pelanggaran konten dengan risiko tinggi (data pribadi, SARA) segera disembunyikan atau ditarik oleh admin dan dilaporkan pada hari yang sama.","Penghapusan unggahan publik diketahui Kepala Biro DKV; untuk konten Tingkat 2 diketahui Presiden.","Konten yang dikoreksi atau dihapus diarsipkan (tangkapan layar atau berkas asli) sebagai bukti dan bahan evaluasi.","Permintaan penghapusan dari pihak yang datanya atau fotonya tampil ditanggapi paling lambat 1 hari kerja dan dikabulkan bila beralasan.","Permintaan maaf atau klarifikasi publik disampaikan melalui SOP-KOM-010."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro DKV","A","Menilai kategori kesalahan, memutuskan tindakan, dan menutup kasus."],["Admin media sosial","R","Menerima laporan, melakukan tindakan penahan, dan melakukan koreksi teknis."],["Penyusun konten","R","Menyiapkan versi benar dan menganalisis penyebab kesalahan."],["Presiden","C","Menyetujui koreksi atau klarifikasi publik untuk konten Tingkat 2."],["Sekretaris Jenderal","C","Memastikan koreksi dokumen resmi atau data administrasi."],["Inspektur Jenderal","C","Menilai penyebab kesalahan yang berulang."],["Pelapor atau pihak terdampak","I","Menerima kabar tindak lanjut."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan kesalahan dari internal atau publik.","Konten asli yang dipermasalahkan dan catatan persetujuannya (SOP-KOM-007).","Log Koreksi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan laporan: Menerima laporan dari internal atau publik dan mencatatnya pada Log Koreksi.","Admin media sosial","Laporan","Laporan tercatat","Segera"],["2","Penilaian awal: Menentukan kategori (minor, substantif, pelanggaran konten) dan tingkat risiko.","Kabiro DKV","Laporan, konten asli","Kategori dan tindakan ditetapkan","Pada hari yang sama"],["3","Tindakan penahan: Menyembunyikan atau menarik sementara unggahan berisiko tinggi dan menyimpan salinannya.","Admin media sosial","Penilaian awal","Unggahan tertahan, salinan arsip","Segera setelah penilaian"],["4","Penyusunan koreksi: Menyiapkan versi benar dan catatan koreksi; Tingkat 2 dimintakan persetujuan Presiden.","Penyusun konten, Kabiro DKV","Fakta yang benar","Versi koreksi","1 hari kerja (minor); 2 hari kerja (substantif)"],["5","Pemberitahuan: Menayangkan koreksi atau catatan koreksi dan menghubungi pelapor atau pihak terdampak; bila perlu, pernyataan melalui SOP-KOM-010.","Admin media sosial","Versi koreksi","Koreksi tayang","Setelah persetujuan"],["6","Penghapusan atau penarikan final: Menghapus unggahan yang tidak dapat diperbaiki dengan sepengetahuan pejabat dan mengarsipkan salinannya.","Kabiro DKV","Keputusan tindakan","Unggahan ditarik, arsip","2 hari kerja"],["7","Analisis penyebab: Menelusuri penyebab (data keliru, pemeriksaan terlewat) dan menetapkan perbaikan proses.","Penyusun konten, Kabiro DKV","Log Koreksi","Catatan penyebab dan perbaikan","5 hari kerja"],["8","Penutupan dan tinjauan: Menutup kasus; merekap Log Koreksi pada evaluasi bulanan; kesalahan berulang dibawa ke SOP-MONEV- 009.","Kabiro DKV, Irjen","Log Koreksi","Kasus ditutup, rekap","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penilaian awal dilakukan pada hari yang sama; koreksi substantif ditayangkan paling lambat 2 hari kerja. Hasil akhir: koreksi tayang atau unggahan ditarik, tercatat pada Log Koreksi, dan terarsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kesalahan memicu polemik atau menyebar luas: SOP-KOM-012.","Keberatan dari kampus atau pihak luar yang bersifat serius: Presiden berkonsultasi dengan KAUR ORMAWA atau Pembina.","Kesalahan dilakukan dengan sengaja atau lalai berat: SOP-SDM-013.","Data pribadi tersebar melalui publikasi: SOP-RSK-009 dan SOP-SDM-018."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% laporan kesalahan tercatat pada Log Koreksi.","Unggahan berisiko tinggi ditahan pada hari yang sama pada 100% kasus.","Koreksi substantif tayang dalam 2 hari kerja.","Kesalahan berulang dengan penyebab yang sama menurun dari bulan ke bulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Log Koreksi.","Salinan arsip konten yang dikoreksi atau dihapus.","Catatan koreksi atau pernyataan klarifikasi.","Catatan penyebab dan entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro DKV merekap dan meninjau Log Koreksi setiap bulan; Irjen menilai kepatuhan dan kesalahan berulang pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima laporan → Nilai kategori → Tahan unggahan bila berisiko → Susun koreksi → Tayangkan koreksi → Analisis penyebab → Tutup kasus → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan Kesalahan Publikasi","Pelapor; tanggal; konten atau tautan; jenis kesalahan; bukti; usulan perbaikan."],["Log Koreksi","Tanggal; konten atau tautan; kategori; penyebab; tindakan; pelaksana; status."],["Templat Catatan Koreksi","Konten yang dikoreksi; bagian yang keliru; informasi yang benar; tanggal koreksi."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Laporan tercatat dan kategori kesalahan telah ditentukan.","☐ Ya ☐ Tidak"],["2","Unggahan berisiko tinggi telah ditahan dan diarsipkan.","☐ Ya ☐ Tidak"],["3","Koreksi disetujui pejabat yang berwenang sebelum tayang.","☐ Ya ☐ Tidak"],["4","Pelapor atau pihak terdampak telah diberi kabar.","☐ Ya ☐ Tidak"],["5","Penyebab dianalisis dan Log Koreksi diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-010","g":"Komunikasi dan Informasi","t":"Pernyataan Resmi Organisasi kepada Publik","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[581,584],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan pihak yang berwenang serta tahapan menyusun, memeriksa, menyetujui, dan menyampaikan pernyataan resmi BEM kepada publik, sehingga BEM berbicara dengan satu suara, akurat, dan sesuai AD/ART serta peraturan kampus."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk setiap pernyataan tertulis atau lisan atas nama BEM yang ditujukan kepada mahasiswa, kampus, publik, atau media: pernyataan sikap, klarifikasi, siaran pers, ucapan resmi, dan wawancara. SOP ini tidak mengatur publikasi kegiatan rutin (SOP-KOM-007). Pernyataan pada keadaan krisis tetap mengikuti SOP ini dan SOP-KOM-012."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 (Wewenang BEM) huruf e dan f (mewakili mahasiswa sebagai pimpinan tertinggi eksekutif mahasiswa; menandatangani surat dan dokumen resmi).","ART Pasal 2 (Hak BEM) huruf e, g, dan h (kerja sama eksternal dengan persetujuan Ketua STDIIS; aspirasi; kritik konstruktif).","ART Pasal 3 (Kewajiban BEM) huruf d dan h (menjaga nama baik; mematuhi peraturan kampus).","ART Pasal 11 huruf a, b, e, dan g (larangan SARA, penistaan agama, politik praktis tanpa izin kampus, pencemaran nama baik).","SOP-GOV-008 (pendelegasian wewenang) dan SOP-GOV-012 (keputusan mendesak)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pernyataan resmi","Pernyataan atas nama BEM yang disetujui Presiden."],["Juru bicara","Pengurus yang ditunjuk tertulis oleh Presiden untuk menyampaikan pernyataan pada topik dan waktu tertentu."],["Siaran pers","Pernyataan tertulis resmi yang dibagikan kepada media dan publik."],["Pendapat pribadi","Pandangan perseorangan yang tidak memakai identitas jabatan dan tidak mengatasnamakan BEM."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Presiden adalah pihak yang berwenang menyampaikan pernyataan resmi. Presiden dapat mendelegasikannya kepada Wakil Presiden atau juru bicara secara tertulis untuk topik dan waktu tertentu (SOP-GOV-008).","Pengurus lain tidak berbicara atas nama BEM kepada media atau publik tanpa penunjukan, dan tidak memakai identitas jabatan untuk menyampaikan pendapat pribadi.","Kritik terbuka terhadap kebijakan adalah hak BEM selama disampaikan dengan etika (ART Pasal 2 huruf h). Pernyataan sikap terhadap kampus diputuskan Presiden pada Rapat Pimpinan, berbasis fakta, memakai bahasa santun, dan didahului jalur aspirasi atau audiensi (SOP-HKE-003).","Pernyataan tidak memuat: politik praktis atau afiliasi partai tanpa izin kampus, SARA, tuduhan tanpa bukti, identitas pelapor atau data pribadi, serta hal di luar kewenangan BEM seperti fatwa atau kebijakan kampus.","Isi pernyataan berupa fakta terverifikasi dengan sumber jelas, ringkas, santun, dan tidak berspekulasi; bila belum jelas, disampaikan bahwa informasi masih dikumpulkan.","Pernyataan tertulis memakai kop resmi, bernomor (SOP-ADM-003 dan SOP-ADM-005), dan ditandatangani Presiden.","Pernyataan yang menyangkut kampus dikoordinasikan dengan KAUR ORMAWA bila kampus mensyaratkan.","Permintaan media atau wawancara dicatat dan dikonfirmasi paling lambat 1 hari kerja. Jawaban spontan tidak diberikan sebelum ada persetujuan; yang disampaikan adalah waktu tanggapan resmi.","Salinan final disimpan pada repositori dan seluruh kanal memakai teks yang sama."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Memutuskan perlu tidaknya pernyataan, menyetujui, menandatangani, dan menunjuk juru bicara."],["Wakil Presiden atau juru bicara","R","Menyampaikan pernyataan bila didelegasikan dan memeriksa kesesuaian isi."],["Sekretaris Jenderal","R","Mencatat permintaan, menyusun draf, memeriksa administrasi, dan mengarsipkan."],["Kepala Biro DKV","R","Menyiapkan format publikasi dan menyebarkan pernyataan melalui kanal resmi."],["Inspektur Jenderal","C","Memverifikasi fakta dan kesesuaian dengan AD/ART bila pernyataan menyangkut sikap atau tudingan."],["KAUR ORMAWA atau Pembina","C","Dikonfirmasi bila pernyataan menyangkut kampus."],["Seluruh pengurus","I","Menyampaikan hanya teks resmi dan merujuk pertanyaan kepada juru bicara."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Permintaan media atau pemicu isu.","Fakta, bukti, dan kronologi dari unit terkait.","Hasil Rapat Pimpinan (SOP-GOV-005).","Templat pernyataan resmi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pencatatan pemicu: Mencatat permintaan atau isu pada Daftar Permintaan Pernyataan beserta pihak dan tenggat.","Sekjen","Permintaan media, isu","Permintaan tercatat","1 hari kerja"],["2","Keputusan: Menentukan perlu tidaknya pernyataan, bentuk, topik, dan juru bicara pada Rapat Pimpinan atau melalui SOP-GOV-012.","Presiden","Daftar permintaan","Keputusan pernyataan","1 hari kerja"],["3","Pengumpulan fakta: Menghimpun fakta, bukti, dan kronologi; Irjen membantu verifikasi bila menyangkut tuduhan.","Sekjen, unit terkait, Irjen","Data unit","Fakta terverifikasi","1 sampai 2 hari kerja"],["4","Penyusunan draf: Menyusun draf pernyataan (pesan kunci, fakta, tanggapan) dan menyiapkan format publikasi.","Sekjen, Kabiro DKV","Fakta terverifikasi","Draf pernyataan","1 hari kerja"],["5","Pemeriksaan: Memeriksa fakta, bahasa, dan kepatuhan; konfirmasi ke KAUR ORMAWA bila menyangkut kampus.","Wapres, Irjen, Sekjen","Draf pernyataan","Catatan pemeriksaan","1 hari kerja"],["6","Persetujuan: Menyetujui dan menandatangani pernyataan tertulis atau menyetujui naskah lisan.","Presiden","Draf diperiksa","Pernyataan final","1 hari kerja"],["7","Penyampaian: Menyampaikan melalui kanal yang sama untuk seluruh audiens dan memberi tahu pengurus agar merujuk pada teks resmi.","Presiden atau juru bicara, Kabiro DKV","Pernyataan final","Pernyataan tersampaikan","Sesuai waktu yang ditetapkan"],["8","Pemantauan dan tindak lanjut: Memantau tanggapan; koreksi bila ada kesalahan (SOP-KOM-009); eskalasi bila isu membesar (SOP-KOM-012); mengarsipkan.","Kabiro DKV, Sekjen","Tanggapan publik","Laporan tindak lanjut, arsip","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Permintaan media dikonfirmasi paling lambat 1 hari kerja; pernyataan biasa diselesaikan paling lambat 3 hari kerja sejak keputusan; keadaan mendesak mengikuti SOP-GOV-012. Hasil akhir: pernyataan resmi yang disetujui, tersampaikan, dan terarsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pernyataan harus disampaikan sangat cepat: SOP-GOV-012 dan SOP-KOM-012.","Presiden berhalangan: SOP-GOV-009 (pelaksana harian).","Perbedaan pendapat pimpinan tentang isi: diputuskan pada Rapat Pimpinan (SOP-GOV-005).","Pengurus berbicara tanpa kewenangan: SOP-KOM-002 dan SOP-SDM-013.","Pernyataan menyangkut aspek hukum atau pidana: Presiden berkonsultasi dengan KAUR ORMAWA atau Pembina."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pernyataan resmi memiliki persetujuan Presiden dan terarsip.","Permintaan media dikonfirmasi dalam 1 hari kerja.","Tidak ada pernyataan atas nama BEM dari pihak tidak berwenang yang dibiarkan tanpa tindak lanjut.","Tidak ada koreksi substantif atas pernyataan karena kesalahan fakta."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Pernyataan resmi final yang ditandatangani atau naskah lisan yang disetujui.","Daftar Permintaan Pernyataan.","Catatan pemeriksaan dan bukti penyampaian.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal merekap dan memeriksa kelengkapan arsip pernyataan setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Catat pemicu → Keputusan Presiden → Kumpulkan fakta → Susun draf → Periksa → Persetujuan Presiden → Sampaikan → Pantau dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Permintaan Pernyataan","Nomor; tanggal; pemicu; pihak yang meminta; tenggat; keputusan; juru bicara; status."],["Templat Pernyataan Resmi","Nomor; perihal; latar belakang; pernyataan atau sikap; kontak resmi; penandatangan; tanggal."],["Surat Penunjukan Juru Bicara","Nama; jabatan; topik; masa berlaku; batas wewenang; penandatangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Presiden telah memutuskan perlu tidaknya pernyataan dan menunjuk juru bicara.","☐ Ya ☐ Tidak"],["2","Fakta telah diverifikasi dan bersumber jelas.","☐ Ya ☐ Tidak"],["3","Pernyataan tidak memuat hal yang dilarang pada ART Pasal 11.","☐ Ya ☐ Tidak"],["4","Pernyataan telah disetujui dan, bila perlu, dikonfirmasi ke kampus.","☐ Ya ☐ Tidak"],["5","Salinan final diarsipkan dan pengurus telah diberi tahu.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-011","g":"Komunikasi dan Informasi","t":"Pengelolaan Dokumentasi Foto dan Video","o":"Kepala Biro Desain Komunikasi Visual","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro DKV","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[585,588],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan perencanaan, pengambilan, penyimpanan, penyuntingan, penggunaan, dan pelindungan dokumentasi foto dan video kegiatan BEM agar bukti kegiatan tersedia, mudah ditemukan, serta hak dan privasi subjek terlindungi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk dokumentasi seluruh kegiatan dan aktivitas resmi BEM yang diambil oleh tim dokumentasi atau pengurus. SOP ini menjadi acuan teknis bukti dokumentasi pada SOP-PRO-018 dan tidak mengatur pengarsipan umum (SOP-ADM-013)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) dan (2) (laporan pertanggungjawaban berkala; pengelolaan transparan dan akuntabel).","ART Pasal 3 (Kewajiban BEM) huruf d dan g (menjaga nama baik; laporan berkala).","ART Pasal 11 huruf g dan h (larangan pencemaran nama baik, pelecehan, dan perundungan).","SOP-PRO-018, SOP-ADM-013, SOP-ADM-014, dan SOP-AST-003 (peminjaman aset).","SOP-SDM-018 dan SOP-RSK-010 (kerahasiaan data pribadi dan informasi sensitif)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Berkas mentah","Hasil dokumentasi asli sebelum dipilih dan disunting."],["Berkas final","Hasil dokumentasi yang telah dipilih, disunting, dan siap digunakan."],["Subjek dokumentasi","Orang yang tampil atau terekam pada foto atau video."],["Izin tayang","Persetujuan subjek atau pihak berwenang agar dokumentasi dipublikasikan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap kegiatan resmi menunjuk koordinator dokumentasi dan menetapkan kebutuhannya (jenis foto dan video, momen wajib) pada TOR atau rundown (SOP-PRO-007).","Dokumentasi mematuhi ketentuan kampus dan adab syar'i dalam pengambilan serta penayangan gambar; tidak mengambil gambar pada area atau momen privat dan tidak merekam percakapan tertutup tanpa izin.","Peserta diberi tahu bahwa kegiatan didokumentasikan (pada publikasi atau pendaftaran). Narasumber dan pihak luar dimintai izin tayang bila perlu. Foto close-up atau cerita personal memerlukan persetujuan subjek.","Tidak dipublikasikan: dokumentasi rapat tertutup, tampilan layar yang memuat data sensitif, dan gambar yang merendahkan atau merugikan subjek.","Berkas mentah dan final disalin ke repositori resmi paling lambat 3 hari setelah kegiatan, dengan penamaan sesuai SOP-ADM-014 (tanggal, kegiatan, jenis, nomor). Penyimpanan pada perangkat pribadi dibersihkan setelah salinan terverifikasi.","Penyuntingan tidak boleh mengubah fakta atau menyesatkan.","Karya dokumentasi menjadi milik BEM. Pihak luar yang mendokumentasikan menandatangani izin penggunaan; aset pihak lain dipakai dengan izin.","Permintaan penghapusan oleh subjek dihormati dan ditangani melalui SOP-KOM-009."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro DKV","A","Menetapkan standar dokumentasi, memeriksa berkas final, dan menyetujui penggunaan."],["Koordinator dokumentasi","R","Merencanakan kebutuhan, menugaskan petugas, menyalin, dan mengarsipkan berkas."],["Tim dokumentasi","R","Mengambil, memilih, dan menyunting dokumentasi sesuai ketentuan."],["Ketua panitia","C","Menyampaikan kebutuhan dokumentasi dan memberi tahu peserta serta narasumber."],["Admin arsip digital","R","Menerima dan menata berkas pada repositori sesuai penamaan baku."],["Inspektur Jenderal","C","Memverifikasi dokumentasi sebagai bukti kegiatan secara sampel."],["Peserta dan subjek","I","Mengetahui kegiatan didokumentasikan dan dapat mengajukan keberatan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["TOR, rundown, dan daftar kebutuhan dokumentasi kegiatan.","Jadwal kegiatan dan daftar petugas.","Formulir Izin Tayang.","Alat dokumentasi yang telah dipinjam (SOP-AST-003)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Perencanaan: Menetapkan kebutuhan dan jadwal dokumentasi, menunjuk petugas, dan meminjam alat.","Ketua panitia, koordinator dokumentasi","TOR, rundown","Rencana dokumentasi","H-3 sebelum kegiatan"],["2","Pemberitahuan dan izin: Mencantumkan pemberitahuan dokumentasi pada publikasi atau pendaftaran dan mengurus izin tayang narasumber atau pihak luar.","Ketua panitia","Rencana dokumentasi","Pemberitahuan dan izin","H-3 sebelum kegiatan"],["3","Pengambilan: Mengambil dokumentasi sesuai daftar kebutuhan dengan menjaga batas dan adab.","Tim dokumentasi","Daftar kebutuhan","Berkas mentah","Saat kegiatan"],["4","Penyalinan dan pencadangan: Menyalin seluruh berkas mentah ke penyimpanan bersama dan repositori.","Koordinator dokumentasi","Berkas mentah","Berkas mentah tersimpan","24 jam (cadangan awal); 3 hari (repositori)"],["5","Seleksi dan penyuntingan: Memilih dan menyunting tanpa mengubah fakta; memeriksa data sensitif dan izin tayang.","Tim dokumentasi, Kabiro DKV","Berkas mentah","Berkas final","5 hari kerja (foto); 7 hari kerja (video)"],["6","Persetujuan penggunaan: Menyetujui penggunaan untuk publikasi (SOP-KOM-007) atau bukti LPJ (SOP-PRO-018).","Kabiro DKV","Berkas final, izin tayang","Persetujuan penggunaan","1 hari kerja"],["7","Penyerahan dan penayangan: Menyerahkan berkas ke panitia atau Admin media sosial dan mencatat yang telah tayang.","Koordinator dokumentasi","Berkas final","Berkas diserahkan, tayang tercatat","Sesuai kebutuhan"],["8","Penyimpanan akhir: Menyusun indeks dokumentasi, mengatur akses, mengembalikan alat, dan membersihkan perangkat pribadi.","Admin arsip digital","Berkas final","Arsip lengkap dan indeks","Setelah seluruh berkas diserahkan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Berkas mentah masuk repositori paling lambat 3 hari setelah kegiatan; berkas final foto 5 hari kerja dan video 7 hari kerja (usulan). Hasil akhir: dokumentasi final, indeks, dan catatan izin yang terarsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Keberatan subjek atas dokumentasi yang tayang: SOP-KOM-009.","Dokumentasi memuat data sensitif yang bocor: SOP-RSK-009 dan SOP-RSK-010.","Alat rusak atau hilang: SOP-AST-007.","Berkas hilang atau rusak: pemulihan sesuai SOP-ADM-015.","Perbedaan ketentuan izin dengan kampus: Presiden berkoordinasi dengan KAUR ORMAWA."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kegiatan resmi memiliki dokumentasi di repositori dalam 3 hari setelah kegiatan.","100% berkas final yang dipublikasikan memiliki catatan izin tayang bila diperlukan.","Keberatan subjek ditindaklanjuti dalam 1 hari kerja pada 100% kasus.","Dokumentasi bukti LPJ lengkap pada setiap kegiatan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Berkas dokumentasi mentah dan final.","Indeks dokumentasi dan catatan izin tayang.","Catatan pengembalian alat.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro DKV memeriksa ketepatan waktu penyimpanan dan kelengkapan indeks setiap bulan; Irjen memeriksa sampel dokumentasi pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Rencana dokumentasi → Pemberitahuan dan izin → Pengambilan → Salin dan cadangkan → Seleksi dan sunting → Persetujuan penggunaan → Serahkan dan arsipkan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Dokumentasi Kegiatan","Kegiatan; tanggal; lokasi; kebutuhan foto dan video; momen wajib; koordinator; tenggat."],["Formulir Izin Tayang","Nama subjek; bentuk dokumentasi; tujuan penggunaan; persetujuan; tanggal; tanda tangan."],["Indeks Dokumentasi","Kegiatan; tanggal; jenis; lokasi berkas; petugas; status izin; akses."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Koordinator dokumentasi dan kebutuhan telah ditetapkan sebelum kegiatan.","☐ Ya ☐ Tidak"],["2","Peserta telah diberi tahu dan izin tayang diperoleh bila diperlukan.","☐ Ya ☐ Tidak"],["3","Berkas mentah dan final tersimpan di repositori dalam batas waktu.","☐ Ya ☐ Tidak"],["4","Berkas yang dipublikasikan bebas dari data sensitif dan gambar yang merugikan subjek.","☐ Ya ☐ Tidak"],["5","Alat telah dikembalikan dan perangkat pribadi telah dibersihkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-012","g":"Komunikasi dan Informasi","t":"Penanganan Isu Reputasi dan Komunikasi Krisis","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[589,592],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara mendeteksi, menilai, memutuskan, dan menangani isu yang mengancam nama baik BEM atau kampus serta mengelola komunikasi selama krisis agar cepat, terkoordinasi, jujur, dan tidak memperburuk keadaan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk isu reputasi yang muncul di media sosial, pesan berantai, pemberitaan, atau pembicaraan mahasiswa; insiden kegiatan yang menarik perhatian publik; dan kesalahan publikasi yang membesar. SOP ini mengatur aspek komunikasi dan keputusan bersama; penanganan masalah pokok mengikuti SOP-RSK-011 dan SOP-RSK lainnya yang relevan."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 9 ayat (2) huruf c (tindakan yang merugikan dan merusak nama baik kampus dan organisasi).","ART Pasal 3 (Kewajiban BEM) huruf d (menjaga nama baik) dan ART Pasal 11 huruf g.","ART Pasal 4 (Wewenang BEM) huruf e (mewakili mahasiswa).","ART Pasal 12 dan Pasal 13 (jenis sanksi; mekanisme sanksi; hak klarifikasi dan pembelaan).","SOP-GOV-005, SOP-GOV-009, SOP-GOV-012, SOP-KOM-009, SOP-KOM-010, dan SOP-RSK- 011."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Isu","Informasi, keluhan, atau pembicaraan yang berpotensi memengaruhi nama baik BEM atau kampus."],["Krisis","Isu yang telah atau berpotensi cepat merusak nama baik atau mengganggu kegiatan, misalnya menyangkut keselamatan, SARA, dana, atau aspek hukum."],["Tim Krisis","Kelompok kerja sementara yang dibentuk Presiden untuk menangani isu Level 2 dan Level 3."],["Pernyataan sementara","Pernyataan singkat awal yang menyatakan BEM mengetahui isu dan sedang menelusuri fakta."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Level isu: Level 1 (pantau): keluhan atau kritik terbatas yang belum menyebar, ditangani Kabiro DKV dan unit. Level 2 (waspada): isu menyebar atau melibatkan kampus atau pihak luar, Presiden dan Wapres dilibatkan. Level 3 (krisis): menyangkut keselamatan, SARA, dana, hukum, atau pemberitaan luas.","Tim Krisis (Level 2 dan 3): Presiden (pengambil keputusan), Wapres, Sekjen (pencatat dan koordinator), Kabiro DKV (pemantauan dan publikasi), Irjen (verifikasi fakta), serta unit terkait. Kampus atau Pembina dilibatkan bila perlu.","Prinsip: keselamatan dan kebenaran lebih dahulu; satu juru bicara; tidak berspekulasi, menyalahkan, atau berdebat di kolom komentar; mengakui kesalahan bila terbukti; tidak menghapus bukti; menyampaikan yang diketahui dan langkah berikutnya.","Pernyataan sementara diterbitkan paling lambat 4 jam sejak Level 3 ditetapkan (usulan).","Pada Level 2 dan 3 yang menyangkut kampus, Presiden menghubungi KAUR ORMAWA atau Pembina.","Biro DKV memantau sebutan dan tanggapan serta mencatat linimasa dengan tangkapan layar.","Dugaan pelanggaran oleh individu diproses melalui SOP-SDM-013 dan tidak diumumkan sebelum klarifikasi; terlapor berhak memberi klarifikasi dan pembelaan.","Setelah krisis, pembelajaran dicatat dan SOP diperbaiki bila perlu."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan level, membentuk Tim Krisis, menunjuk juru bicara, dan memutuskan pernyataan."],["Wakil Presiden","R","Mengoordinasikan Tim Krisis dan menggantikan Presiden bila berhalangan (SOP-GOV-009)."],["Sekretaris Jenderal","R","Mencatat linimasa, mengoordinasikan data, dan mengarsipkan laporan."],["Kepala Biro DKV","R","Memantau isu dan menyebarkan pernyataan melalui kanal resmi."],["Menteri / Kabiro unit terkait","R","Menyediakan fakta dan tindakan yang telah diambil unitnya."],["Inspektur Jenderal","C","Memverifikasi fakta dan menilai kepatuhan penanganan."],["KAUR ORMAWA atau Pembina","C","Dihubungi pada isu yang menyangkut kampus."],["Seluruh pengurus","I","Tidak berkomentar atas nama BEM dan merujuk kepada juru bicara."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan isu beserta tangkapan layar atau tautan.","Fakta dan kronologi dari unit terkait.","Lembar Penilaian Isu.","Daftar kontak darurat."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Deteksi dan pelaporan: Melaporkan isu kepada Sekjen atau Kabiro DKV beserta tangkapan layar atau tautan.","Seluruh pengurus, Biro DKV","Isu yang ditemukan","Laporan isu","Pada hari yang sama"],["2","Penilaian awal: Memverifikasi dan menentukan level isu dengan Lembar Penilaian Isu; melapor kepada Presiden.","Kabiro DKV, Sekjen","Laporan isu","Level diusulkan","4 jam sejak diterima"],["3","Aktivasi: Menetapkan level, membentuk Tim Krisis (Level 2 dan 3), menunjuk juru bicara dan koordinator fakta.","Presiden","Hasil penilaian","Tim dan penugasan","2 jam sejak penilaian"],["4","Pengumpulan fakta: Menghimpun fakta, bukti, dan kronologi; mencatat linimasa.","Unit terkait, Irjen, Sekjen","Data unit","Kronologi dan fakta","Pada hari yang sama"],["5","Penyusunan respons: Menyusun pernyataan sementara dan, bila perlu, pernyataan lengkap melalui SOP-KOM-010 dengan pemeriksaan dipercepat.","Tim Krisis","Fakta, kronologi","Pernyataan siap","4 jam (pernyataan sementara)"],["6","Penyampaian dan koordinasi: Menyampaikan melalui kanal resmi, memberi tahu kampus atau Pembina, dan menginstruksikan pengurus merujuk pada pernyataan.","Juru bicara, Kabiro DKV","Pernyataan siap","Pernyataan tersampaikan","Sesuai keputusan Presiden"],["7","Pemantauan dan pembaruan: Memantau perkembangan; Tim Krisis bertemu singkat harian hingga isu reda; menyampaikan pembaruan seperlunya.","Tim Krisis, Kabiro DKV","Hasil pemantauan","Pembaruan dan keputusan lanjutan","Harian hingga reda"],["8","Penutupan dan evaluasi: Menyatakan penutupan, menyusun Laporan Penanganan, dan membawa pembelajaran ke Rapat Kabinet.","Presiden, Sekjen","Linimasa, tindakan","Laporan Penanganan","7 hari kerja setelah penutupan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Level isu diusulkan paling lambat 4 jam sejak laporan diterima, Tim Krisis dibentuk 2 jam kemudian, dan pernyataan sementara paling lambat 4 jam untuk Level 3 (usulan). Hasil akhir: isu tertangani, pernyataan tercatat, dan Laporan Penanganan terarsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Menyangkut keselamatan atau kecelakaan: SOP-RSK-003 didahulukan.","Dugaan penyalahgunaan dana atau aset: SOP-RSK-007.","Dugaan pelanggaran etik oleh individu: SOP-SDM-013; perundungan atau pelecehan: SOP-RSK-005.","Pimpinan terlibat dalam isu: Irjen menangani dan berkonsultasi dengan KAUR ORMAWA atau Pembina.","Presiden berhalangan: SOP-GOV-009; keputusan mendesak: SOP-GOV-012."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Level isu ditetapkan dalam 4 jam sejak laporan pada sedikitnya 90% kasus.","Pernyataan sementara terbit dalam 4 jam pada seluruh kasus Level 3.","100% kasus Level 3 memiliki Laporan Penanganan dalam 7 hari kerja.","Tidak ada pernyataan yang saling bertentangan dari pengurus selama krisis.","Simulasi (tabletop) dilakukan sedikitnya satu kali per periode."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Penilaian Isu dan linimasa.","Pernyataan sementara dan pernyataan lengkap.","Laporan Penanganan.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal mengarsipkan seluruh dokumen penanganan; Irjen menilai kepatuhan pada evaluasi berkala dan hasil simulasi dibahas pada evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Deteksi dan lapor → Penilaian level → Aktivasi Tim Krisis → Kumpulkan fakta → Pernyataan sementara → Penyampaian → Pantau dan perbarui → Laporan Penanganan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Penilaian Isu","Tanggal dan jam; sumber; uraian isu; jangkauan; dampak; level; tindakan awal; penilai."],["Templat Pernyataan Sementara","Pengakuan bahwa isu diketahui; langkah penelusuran; waktu pembaruan berikutnya; kontak resmi."],["Daftar Kontak Darurat","Nama; jabatan; peran dalam Tim Krisis; kontak resmi; pengganti."],["Templat Laporan Penanganan","Ringkasan isu; linimasa; keputusan; hasil; pembelajaran; rencana perbaikan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Isu telah diverifikasi dan levelnya ditetapkan.","☐ Ya ☐ Tidak"],["2","Tim Krisis, juru bicara, dan koordinator fakta telah ditunjuk (Level 2 dan 3).","☐ Ya ☐ Tidak"],["3","Pernyataan sementara terbit dalam batas waktu bila Level 3.","☐ Ya ☐ Tidak"],["4","Kampus atau Pembina telah dihubungi pada isu yang menyangkut kampus.","☐ Ya ☐ Tidak"],["5","Laporan Penanganan telah disusun dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-013","g":"Komunikasi dan Informasi","t":"Pengelolaan Akses Akun Digital","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[593,596],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara mendaftarkan, memberi, mengamankan, mengubah, mencabut, dan menyerahterimakan akses akun digital organisasi (email, media sosial, penyimpanan, dan platform koordinasi), sehingga akun aman, tidak bergantung pada satu orang, dan akses sesuai kewenangan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh akun digital atas nama BEM, kementerian, biro, dan panitia, beserta pengurus yang mengelolanya. SOP ini tidak mengatur penanganan insiden keamanan dan kebocoran data (SOP-RSK-008 dan SOP-RSK-009) dan serah terima akun akhir periode (SOP-TRN-006), tetapi menjadi dasar keduanya."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (2) (pengelolaan organisasi secara transparan, akuntabel, efektif, dan efisien).","ART Pasal 3 (Kewajiban BEM) huruf e dan h (mengelola secara amanah; mematuhi peraturan kampus).","ART Pasal 11 huruf i dan k (larangan penyelewengan dan penggunaan fasilitas atau nama organisasi untuk kepentingan pribadi).","SOP-KOM-001 (kanal resmi), SOP-SDM-018 (kerahasiaan data anggota), dan SOP-ADM-015 (hak akses dan pencadangan).","Pedoman Penyusunan SOP BEM Kabinet Baru (dokumen dan akses tidak boleh hanya di perangkat atau akun pribadi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Akun resmi","Akun atas nama organisasi atau jabatan yang tercatat pada Daftar Akun Resmi."],["Pemilik akun","Jabatan yang bertanggung jawab atas akun; bukan perseorangan."],["Pengelola akun","Pengurus yang diberi akses harian."],["Autentikasi dua langkah","Pengamanan tambahan berupa kode verifikasi selain kata sandi."],["Daftar Akun Resmi","Dokumen berakses terbatas yang memuat akun, pemilik, pengelola, email atau nomor pemulihan, dan tanggal tinjauan; tidak memuat kata sandi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap akun resmi dibuat atas nama organisasi atau jabatan, memiliki pemilik (jabatan), sedikitnya dua pengelola, dan email atau nomor pemulihan milik organisasi.","Akses diberikan seminimal yang dibutuhkan (peran terendah yang cukup). Akses penuh (pemilik atau admin utama) dipegang Sekjen dan pejabat yang ditunjuk Presiden.","Kata sandi unik, kuat, dan tidak dibagikan lewat grup atau email. Penyimpanan bersama kredensial memakai pengelola kata sandi atau cara yang disetujui Sekjen.","Autentikasi dua langkah diaktifkan pada seluruh akun yang mendukungnya, dengan nomor atau perangkat pemulihan yang tidak hanya milik satu orang.","Akun resmi tidak dipakai untuk kepentingan pribadi dan tidak dibuka pada perangkat umum tanpa kewaspadaan; keluar dari akun setelah dipakai.","Pengurus yang berhenti, diberhentikan, berganti jabatan, atau selesai kepanitiaan dicabut aksesnya paling lambat 1 hari kerja (SOP-SDM-014).","Peninjauan hak akses dilakukan setiap bulan untuk akun kritis dan setiap triwulan untuk akun lain (usulan); hasil dicatat.","Kata sandi diganti saat pengelola berganti, saat dugaan akun disusupi, dan paling lambat saat serah terima kabinet (SOP-TRN-006).","Akun yang tidak lagi diperlukan ditutup setelah datanya diarsipkan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan pemilik akun, menyetujui pembuatan atau penutupan akun, dan menunjuk pemegang akses penuh."],["Sekretaris Jenderal","R","Menyusun dan memelihara Daftar Akun Resmi, memberi dan mencabut akses, serta meninjau hak akses."],["Kepala Biro DKV","R","Mengelola akun media sosial dan aset visual sesuai SOP-KOM-008."],["Pengelola akun","R","Menjaga kredensial, memakai akun sesuai fungsi, dan melaporkan kejadian mencurigakan."],["Menteri / Kabiro","R","Mengusulkan pengelola unit dan memberi tahu bila pengelola berhenti atau berganti."],["Inspektur Jenderal","C","Memeriksa kepatuhan pengelolaan akses pada evaluasi berkala."],["Seluruh pengurus","I","Tidak meminta atau membagikan kredensial di luar prosedur."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Kanal Resmi (SOP-KOM-001).","Struktur kabinet dan daftar pengurus.","Formulir Permintaan Akses.","Informasi pengangkatan, pemberhentian, atau pergantian pengurus."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Inventarisasi akun: Mendata seluruh akun yang ada dan dibutuhkan, termasuk dari kabinet sebelumnya; menetapkan pemilik dan pengelola.","Sekjen","Daftar kanal, struktur kabinet","Draf Daftar Akun Resmi","5 hari kerja setelah struktur ditetapkan"],["2","Pengesahan: Menyetujui daftar akun, pemilik, dan pemegang akses penuh.","Presiden","Draf daftar","Daftar Akun Resmi disahkan","2 hari kerja"],["3","Pengamanan awal: Mengganti kata sandi bawaan atau warisan, mengaktifkan autentikasi dua langkah, dan mengatur pemulihan organisasi.","Pengelola akun, Sekjen","Daftar disahkan","Akun aman","3 hari kerja setelah pengesahan"],["4","Permintaan akses: Mengisi Formulir Permintaan Akses: akun, peran, alasan, dan masa berlaku.","Menteri / Kabiro","Kebutuhan kerja","Permintaan tercatat","Sesuai kebutuhan"],["5","Pemberian akses: Memeriksa kewenangan dan memberi akses seminimal mungkin; mencatat pada daftar.","Sekjen","Formulir","Akses diberikan dan tercatat","1 hari kerja"],["6","Pencabutan atau perubahan: Mencabut atau mengubah akses saat pengurus berhenti, berganti jabatan, atau panitia dibubarkan; mengganti kata sandi bila perlu.","Sekjen","Informasi pergantian pengurus","Akses dicabut atau diubah","1 hari kerja"],["7","Peninjauan berkala: Memeriksa seluruh akun: pengelola, hak akses, autentikasi dua langkah, dan akun yang tidak terdaftar; mencatat temuan.","Sekjen dan Irjen","Daftar Akun Resmi","Catatan peninjauan","Bulanan (kritis); triwulan (lainnya)"],["8","Penutupan akun: Mengarsipkan data, mencabut seluruh akses, dan menutup akun yang tidak diperlukan dengan persetujuan Presiden.","Sekjen, Presiden","Keputusan penutupan","Akun ditutup, arsip","5 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Daftar Akun Resmi disahkan paling lambat 7 hari kerja sejak struktur kabinet ditetapkan; akses pengurus yang berhenti dicabut dalam 1 hari kerja (usulan). Hasil akhir: akun terdaftar, aman, dan aksesnya sesuai kewenangan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Akun diretas, kehilangan akses, atau pengelola tidak dapat dihubungi: segera lapor Sekjen; ikuti SOP- RSK-008 dan SOP-RSK-009.","Pengurus menolak menyerahkan akses atau kredensial: Sekjen melapor kepada Presiden; dapat ditindaklanjuti melalui SOP-SDM-013.","Dugaan penyalahgunaan akun untuk kepentingan pribadi: SOP-RSK-007 dan SOP-SDM-013.","Akun atas nama BEM yang dikelola pihak lain atau tidak diketahui: didaftarkan atau diminta ditutup setelah koordinasi dengan Presiden.","Perbedaan pendapat tentang pemberian akses: diputuskan Wakil Presiden."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% akun resmi tercatat pada Daftar Akun Resmi dengan pemilik dan sedikitnya dua pengelola.","100% akun yang mendukung memakai autentikasi dua langkah.","Akses pengurus yang berhenti dicabut dalam 1 hari kerja pada 100% kasus.","Tidak ada kata sandi yang tersimpan pada dokumen atau grup terbuka."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Akun Resmi (akses terbatas, tanpa kata sandi).","Formulir Permintaan Akses dan catatan pencabutan.","Catatan peninjauan hak akses.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal meninjau hak akses sesuai jadwal dan melaporkan hasilnya pada Rapat Pimpinan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Inventarisasi akun → Pengesahan Presiden → Pengamanan awal → Permintaan dan pemberian akses → Pencabutan saat pergantian → Peninjauan berkala → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Akun Resmi","Nama akun; platform; pemilik (jabatan); pengelola; email atau nomor pemulihan; autentikasi dua langkah; tanggal tinjauan; status."],["Formulir Permintaan Akses","Pemohon; unit; akun; peran akses; alasan; masa berlaku; persetujuan; tanggal."],["Catatan Pencabutan Akses","Nama pengurus; akun; alasan; tanggal dicabut; kata sandi diganti (ya atau tidak); pelaksana."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap akun memiliki pemilik jabatan dan sedikitnya dua pengelola.","☐ Ya ☐ Tidak"],["2","Autentikasi dua langkah dan pemulihan milik organisasi telah aktif.","☐ Ya ☐ Tidak"],["3","Akses pengurus yang berhenti atau berganti jabatan sudah dicabut atau disesuaikan.","☐ Ya ☐ Tidak"],["4","Tidak ada kata sandi yang disimpan di dokumen, grup, atau email terbuka.","☐ Ya ☐ Tidak"],["5","Peninjauan berkala telah dilakukan dan dicatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-KOM-014","g":"Komunikasi dan Informasi","t":"Penggunaan Logo, Identitas Visual, dan Templat Desain","o":"Kepala Biro Desain Komunikasi Visual","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro DKV","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[597,600],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan aturan pemakaian logo, warna, huruf, dan templat desain resmi BEM serta pengelolaan aset visual, sehingga identitas organisasi konsisten, sah, dan tidak disalahgunakan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pemakaian nama, logo, dan identitas visual BEM pada surat, publikasi, kegiatan, atribut, dan materi kerja sama, oleh pengurus, panitia, maupun pihak luar. SOP ini tidak mengatur isi publikasi (SOP- KOM-007) dan pengesahan lambang oleh kampus, yang tetap menjadi kewenangan STDIIS Jember."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 18 ayat (1) dan (2) (lambang BEM adalah lambang yang disahkan STDIIS Jember; lambang yang tidak disahkan dilarang di dalam kampus).","AD Pasal 18 ayat (3) (seragam resmi adalah Pakaian Dinas Harian BEM).","ART Pasal 2 (Hak BEM) huruf b (hak atas penggunaan nama, lambang, dan identitas resmi yang disetujui STDIIS Jember).","ART Pasal 11 huruf g dan k (larangan pencemaran nama baik; penggunaan nama organisasi untuk kepentingan pribadi yang merugikan).","SOP-KOM-007, SOP-KOM-008, SOP-ADM-005 (kop surat, stempel, tanda tangan), dan SOP-HKE- 006 (dokumen kerja sama)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Logo resmi","Lambang BEM yang disahkan STDIIS Jember beserta variasi yang diizinkan."],["Identitas visual","Warna, huruf, tata letak, dan gaya desain baku organisasi."],["Templat desain","Berkas desain baku untuk surat, poster, sertifikat, slide, dan unggahan."],["Pustaka Aset Visual","Folder pada repositori resmi yang menyimpan logo, templat, huruf, dan aset yang boleh dipakai."],["Buku Panduan Identitas","Dokumen ringkas aturan pemakaian logo dan identitas visual."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Hanya logo yang disahkan STDIIS Jember yang dipakai atas nama BEM. Logo atau lambang yang tidak disahkan tidak dipakai di dalam kampus (AD Pasal 18 ayat 2).","Perubahan logo atau pembuatan lambang baru, termasuk logo kabinet atau kegiatan, hanya dengan persetujuan Presiden dan, bila diperlukan, disahkan kampus sebelum dipakai.","Buku Panduan Identitas memuat versi logo, ukuran minimum, ruang aman, warna, huruf, dan larangan: tidak diubah, diregangkan, diberi efek, atau dipasang pada latar yang mengganggu keterbacaan.","Logo kampus, mitra, dan sponsor dipakai sesuai pedoman pemilik dan izin tertulis; penempatan sponsor tidak lebih menonjol daripada logo resmi tanpa persetujuan Presiden.","Seluruh publikasi memakai templat dari Pustaka Aset Visual; deviasi desain untuk kegiatan khusus disetujui Kepala Biro DKV.","Kop surat, stempel, dan tanda tangan mengikuti SOP-ADM-005; logo tidak dipakai untuk surat atau dokumen yang tidak melalui prosedur.","Pihak luar memakai logo BEM hanya dengan izin tertulis Presiden yang menyebut tujuan dan masa berlaku, serta harus menghentikan pemakaian bila izin berakhir.","Aset visual pihak lain (gambar, huruf, musik) dipakai hanya dengan izin atau lisensi yang jelas dan sumbernya dicatat; pemakaian konten tanpa izin tidak dibenarkan.","Pemakaian logo untuk kegiatan politik praktis, bisnis pribadi, atau muatan yang bertentangan dengan syariat dan aturan kampus dilarang (ART Pasal 11).","Berkas sumber desain disimpan pada repositori dalam format terbuka (sumber dan ekspor); desain tidak hanya disimpan di perangkat perancang."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro DKV","A","Menyusun dan memelihara Buku Panduan Identitas, Pustaka Aset Visual, dan templat; memutuskan permintaan penyimpangan desain."],["Presiden","R","Menyetujui perubahan logo, izin pemakaian oleh pihak luar, dan hubungan dengan kampus soal pengesahan lambang."],["Staf Biro DKV","R","Membuat dan memperbarui templat, menjaga pustaka, dan mendampingi unit."],["Sekretaris Jenderal","C","Memastikan kop surat, stempel, dan tanda tangan dipakai sesuai SOP-ADM- 005."],["Menteri / Kabiro dan ketua panitia","R","Memakai templat dan logo sesuai aturan dan mengajukan permintaan penyimpangan secara tertulis."],["KAUR ORMAWA","C","Memberi pengesahan atau tanggapan kampus atas lambang dan identitas resmi."],["Inspektur Jenderal","I","Memeriksa kepatuhan pemakaian logo secara sampel."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Logo dan lambang yang disahkan STDIIS Jember.","Pedoman identitas kampus dan ketentuan sponsor atau mitra.","Permintaan templat atau izin pemakaian dari unit atau pihak luar.","Kalender organisasi dan kebutuhan publikasi kabinet."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Inventarisasi identitas: Mengumpulkan logo yang disahkan, panduan kampus, dan templat lama; memeriksa keabsahan.","Kabiro DKV","Berkas dari kampus dan arsip","Daftar aset sah","5 hari kerja setelah struktur ditetapkan"],["2","Penyusunan panduan dan templat: Menyusun Buku Panduan Identitas dan templat inti (surat, poster, slide, sertifikat, unggahan).","Biro DKV","Aset sah","Draf panduan dan templat","10 hari kerja"],["3","Pemeriksaan dan pengesahan: Memeriksa kesesuaian dengan aturan kampus dan syariat; menyetujui panduan dan templat.","Sekjen, Presiden","Draf panduan","Panduan dan templat disahkan","3 hari kerja"],["4","Penyimpanan dan sosialisasi: Mengunggah ke Pustaka Aset Visual, mengatur akses, dan mensosialisasikan kepada pengurus.","Biro DKV, Sekjen","Panduan disahkan","Pustaka dan sosialisasi","3 hari kerja setelah pengesahan"],["5","Permintaan penyimpangan: Mengajukan Formulir Permintaan Penyimpangan Desain bila perlu (logo kegiatan, gaya khusus).","Pemohon","Kebutuhan kegiatan","Permintaan tercatat","Sebelum desain dibuat"],["6","Pemeriksaan permintaan: Menilai penyimpangan terhadap Buku Panduan; logo baru dibawa ke Presiden dan, bila perlu, kampus.","Kabiro DKV, Presiden","Permintaan","Disetujui atau ditolak beralasan","2 hari kerja"],["7","Izin pemakaian pihak luar: Menerima permintaan, memeriksa tujuan, dan menerbitkan Surat Izin Pemakaian Logo yang ditandatangani Presiden.","Sekjen, Presiden","Permintaan pihak luar","Surat Izin Pemakaian atau penolakan","3 hari kerja"],["8","Pemantauan dan pembaruan: Memeriksa pemakaian logo pada publikasi secara sampel, menegur penyimpangan, dan memperbarui panduan saat perlu.","Kabiro DKV","Publikasi yang tayang","Catatan temuan, pembaruan panduan","Setiap bulan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Buku Panduan Identitas dan templat inti ditargetkan disahkan paling lambat 20 hari kerja sejak struktur kabinet ditetapkan; permintaan penyimpangan dijawab 2 hari kerja; izin pihak luar 3 hari kerja (usulan). Hasil akhir: panduan, templat, dan pustaka yang berlaku dan terarsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Logo atau lambang tidak sah dipakai atas nama BEM: ditarik; Kabiro DKV melapor kepada Presiden untuk ditindaklanjuti ke kampus bila perlu.","Pihak luar memakai logo tanpa izin: Presiden menegur secara tertulis dan, bila berlanjut, melapor kepada KAUR ORMAWA.","Pelanggaran pemakaian oleh pengurus: SOP-KOM-002; pelanggaran berat melalui SOP-SDM-013.","Pelanggaran hak cipta atau keberatan pemilik aset: SOP-KOM-009 dan, bila perlu, Presiden berkonsultasi dengan kampus.","Perbedaan tafsir tentang identitas resmi: diputuskan Presiden setelah berkonsultasi dengan KAUR ORMAWA."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% publikasi resmi memakai logo dan templat yang disahkan pada pemeriksaan sampel.","Tidak ada logo atau lambang tidak sah yang dipakai atas nama BEM.","100% pemakaian logo oleh pihak luar memiliki izin tertulis.","Buku Panduan Identitas dan Pustaka Aset Visual tersedia bagi seluruh pengurus dalam 20 hari kerja."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Buku Panduan Identitas.","Templat desain dan Pustaka Aset Visual.","Surat Izin Pemakaian Logo dan catatan penyimpangan yang disetujui.","Entri pada Register Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Komunikasi dan Informasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro DKV memeriksa kepatuhan dan kemutakhiran pustaka setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Inventarisasi aset sah → Susun panduan dan templat → Pengesahan → Simpan di pustaka dan sosialisasi → Permintaan penyimpangan atau izin → Pemantauan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Buku Panduan Identitas","Versi logo; ukuran minimum; ruang aman; warna; huruf; contoh benar dan salah; larangan."],["Formulir Permintaan Penyimpangan Desain","Pemohon; kegiatan; kebutuhan; contoh usulan; alasan; keputusan; tanggal."],["Surat Izin Pemakaian Logo","Pihak peminta; tujuan; media; masa berlaku; syarat; penandatangan; nomor surat."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Logo yang dipakai adalah logo yang disahkan STDIIS Jember.","☐ Ya ☐ Tidak"],["2","Publikasi memakai templat dan aturan pada Buku Panduan Identitas.","☐ Ya ☐ Tidak"],["3","Logo mitra dan sponsor dipakai dengan izin dan penempatan sesuai ketentuan.","☐ Ya ☐ Tidak"],["4","Pemakaian logo oleh pihak luar memiliki izin tertulis dengan masa berlaku.","☐ Ya ☐ Tidak"],["5","Berkas sumber desain tersimpan di Pustaka Aset Visual.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kepala Biro DKV; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-001","g":"Keanggotaan dan SDM","t":"Rekrutmen dan Seleksi Pengurus","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[605,608],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur rekrutmen dan seleksi pengurus BEM yang terbuka, adil, dan terukur, baik untuk jalur penunjukan Menteri/Kabiro maupun jalur seleksi staf kementerian/biro, sehingga setiap pengurus memenuhi syarat AD/ART dan terpilih berdasarkan kompetensi, integritas, dan komitmen."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pengangkatan Menteri dan Kabiro (jalur penunjukan prerogatif Presiden) dan penerimaan staf kementerian dan biro (jalur seleksi terbuka). SOP ini tidak mengatur pemilihan Presiden dan Wakil Presiden (AD Pasal 11 ayat 2 huruf a) dan tidak mengatur pengisian jabatan kosong di tengah periode (lihat SOP-SDM- 015)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 8 ayat (1) sampai (3) (keanggotaan terbuka bagi mahasiswa aktif; rekrutmen terbuka, seleksi yang adil, dan musyawarah).","AD Pasal 8 ayat (5) sampai (7) (batas rangkap jabatan dan syarat Menteri/Kabiro merangkap Ketua Divisi).","AD Pasal 10 (masa jabatan satu periode).","AD Pasal 11 ayat (2) huruf b dan c (pengangkatan Menteri/Kabiro secara prerogatif; seleksi terbuka staf dengan penilaian akumulatif).","ART Pasal 4 huruf b (wewenang mengangkat pengurus internal) dan Pasal 5 ayat (1), (2), (4).","ART Pasal 6 ayat (1) (syarat umum kepengurusan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Jalur penunjukan","Pengangkatan Menteri dan Kabiro oleh Presiden secara prerogatif melalui forum musyawarah internal."],["Jalur seleksi staf","Penerimaan staf kementerian dan biro melalui seleksi terbuka."],["Penilaian akumulatif","Penjumlahan nilai kompetensi, integritas, dan wawancara untuk menentukan kelulusan."],["Surat komitmen","Pernyataan tertulis kesediaan menjalankan tugas dengan amanah selama satu periode."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan Menteri/Kabiro dan mengesahkan hasil seleksi staf."],["Menteri PSDM","R","Ketua panitia seleksi; menyusun instrumen, menjalankan tes, dan menghitung nilai."],["Sekretaris Jenderal","R","Verifikasi administrasi, penerbitan SK, dan pengarsipan."],["Menteri / Kabiro unit","C","Menyampaikan kebutuhan formasi dan menjadi pewawancara."],["Inspektur Jenderal","C","Pengawas independen proses seleksi dan penerima keberatan."],["KAUR ORMAWA","C","Menerbitkan surat rekomendasi bagi pelamar yang merangkap jabatan (AD Pasal 8 ayat 7 huruf c)."],["Pelamar","I","Mengajukan berkas dan mengikuti seluruh tahap seleksi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formasi dan kebutuhan kompetensi tiap unit.","Syarat pelamar: mahasiswa aktif; berakhlak baik dan tidak sedang menjalani sanksi akademik atau kemahasiswaan; IPK minimal 2,7; tidak menjabat pengurus ormawa lain, kecuali Menteri/Kabiro yang memenuhi syarat AD Pasal 8 ayat (7); surat komitmen satu periode.","Syarat tambahan bagi Menteri/Kabiro yang merangkap Ketua Divisi: IPK minimal 3,5, maksimal 2 jabatan, surat komitmen, dan surat rekomendasi KAUR ORMAWA.","Transkrip IPK terbaru dan bukti status mahasiswa aktif."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan formasi: Menetapkan jumlah dan kompetensi yang dibutuhkan tiap unit pada rapat pimpinan.","Presiden, Wapres, Menteri PSDM, Sekjen","Kebutuhan unit","Formasi tertulis","Awal periode"],["2","Pembentukan panitia: Mengusulkan dan mengesahkan panitia seleksi (PSDM, wakil unit, Irjen sebagai pengawas).","Menteri PSDM; Presiden","Formasi","SK panitia","2 hari kerja"],["3","Pengumuman terbuka: Mengumumkan syarat, formasi, jadwal, dan bobot nilai melalui kanal resmi.","PSDM","SK panitia","Pengumuman","Pendaftaran minimal 7 hari"],["4","Verifikasi administrasi: Memeriksa status aktif, IPK, sanksi, rangkap jabatan, dan surat komitmen.","Sekjen dan PSDM","Berkas pelamar","Daftar lolos administrasi","3 hari kerja"],["5","Tes kompetensi dan integritas: Studi kasus atau tes tertulis, serta penilaian integritas (rekam jejak dan rekomendasi).","PSDM","Daftar lolos","Skor kompetensi dan integritas","3 hari kerja"],["6","Wawancara: Minimal dua pewawancara (PSDM dan Menteri/Kabiro unit) memakai lembar penilaian seragam.","PSDM dan Menteri/Kabiro","Lembar penilaian","Skor wawancara","3 hari kerja"],["7","Penilaian akumulatif: Menjumlah nilai (kompetensi 40, integritas 30, wawancara 30; ambang lulus 70, usulan); Irjen memeriksa konsistensi.","PSDM; Irjen","Seluruh skor","Peringkat","2 hari kerja"],["8","Musyawarah penetapan: Menetapkan yang lulus; bila nilai sama, dipertimbangkan kebutuhan unit dan komitmen.","Panitia dan pimpinan","Peringkat","Berita acara","1 hari kerja"],["9","Pengesahan dan pengumuman: Mengesahkan hasil, menerbitkan SK, dan mengumumkan hasil.","Presiden; Sekjen","Berita acara","SK dan pengumuman","2 hari kerja"],["10","Jalur penunjukan Menteri/Kabiro: Presiden mengajukan calon; Sekjen memverifikasi syarat ART Pasal 6 dan AD Pasal 8 ayat (7); forum musyawarah internal memutus; Presiden menetapkan; dilanjutkan pelantikan (SOP-SDM-003).","Presiden; Sekjen; forum internal","Calon, berkas syarat","SK Menteri/Kabiro","5 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Seleksi staf dari penetapan formasi hingga SK ditargetkan paling lambat 25 hari kerja, sudah termasuk masa pendaftaran minimal 7 hari. Hasil akhir: SK pengangkatan, pengumuman hasil, dan register pengurus."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pelamar yang tidak memenuhi syarat ditolak dengan alasan tertulis.","Kuota tidak terpenuhi: pendaftaran diperpanjang satu kali (5 hari kerja); bila tetap kurang, Presiden memutuskan penugasan sementara melalui SOP-GOV-012.","Keberatan hasil diajukan ke Irjen paling lambat 2 hari kerja setelah pengumuman; Irjen memeriksa dan melapor ke Presiden.","Dugaan kecurangan dalam seleksi (ART Pasal 11 huruf j) diproses melalui SOP-SDM-013.","Pertentangan AD Pasal 8 ayat (5) sampai (7) dengan ART Pasal 6 ayat (1) huruf d: berlaku ART sebagai aturan dasar dan AD Pasal 8 ayat (7) sebagai satu-satunya pengecualian, sampai ada penegasan dari forum yang berwenang."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% pelamar dinilai dengan formulir seragam.","Hasil diumumkan sesuai jadwal pengumuman.","Tidak ada pengurus diangkat tanpa verifikasi syarat.","Seluruh keberatan ditanggapi tertulis paling lambat 5 hari kerja."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Pengumuman seleksi dan daftar pendaftar.","Lembar nilai dan berita acara seleksi.","SK pengangkatan.","Register pengurus yang diperbarui. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal. Data pelamar yang tidak lolos mengikuti SOP-SDM-018."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri PSDM mengevaluasi proses seleksi setelah setiap gelombang; Irjen menilai kepatuhan prosedur dan kewajaran penilaian pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Formasi → Panitia → Pengumuman → Verifikasi administrasi → Tes dan wawancara → Nilai akumulatif → Penetapan → SK Presiden → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pendaftaran","Identitas; program studi; IPK; organisasi lain yang diikuti; motivasi; pilihan unit; surat komitmen."],["Lembar Penilaian Wawancara","Nama pelamar; aspek penilaian; skor; catatan; pewawancara; tanggal."],["Berita Acara Seleksi","Peserta; hasil nilai; peringkat; keputusan; tanda tangan panitia."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pengumuman memuat syarat, jadwal, dan bobot nilai.","☐ Ya ☐ Tidak"],["2","Seluruh pelamar telah diverifikasi IPK, status aktif, dan rangkap jabatan.","☐ Ya ☐ Tidak"],["3","Setiap pelamar diwawancarai oleh minimal dua pewawancara.","☐ Ya ☐ Tidak"],["4","Irjen telah memeriksa konsistensi nilai.","☐ Ya ☐ Tidak"],["5","SK dan pengumuman hasil telah diterbitkan dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-002","g":"Keanggotaan dan SDM","t":"Penempatan Anggota Sesuai Kompetensi","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[609,611],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Memastikan pengurus yang telah lulus seleksi ditempatkan pada unit dan tugas yang sesuai dengan kompetensi, minat, dan kebutuhan organisasi, serta mengatur mutasi atau rotasi di tengah periode secara tertib."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk penempatan awal pengurus hasil SOP-SDM-001 dan mutasi atau rotasi antarunit di tengah periode. Penetapan Menteri dan Kabiro tetap prerogatif Presiden (AD Pasal 11 ayat 2 huruf b) dan tidak diatur dalam SOP ini."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 11 ayat (2) huruf b dan c.","ART Pasal 4 huruf b (wewenang mengangkat dan memberhentikan pengurus internal).","ART Pasal 5 ayat (1), (2), dan (4) (susunan pengurus dan pengangkatan melalui mekanisme internal).","SOP-SDM-001 (hasil seleksi) dan SOP-SDM-004 (uraian tugas)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pemetaan kompetensi","Pencatatan keterampilan, minat, pengalaman, dan ketersediaan waktu tiap pengurus."],["Matriks kebutuhan","Daftar jumlah dan kompetensi yang dibutuhkan tiap unit."],["Mutasi","Pemindahan pengurus dari satu unit atau jabatan ke yang lain di dalam periode yang sama."],["Masa penyesuaian","Periode 30 hari setelah penempatan untuk menilai kecocokan (usulan)."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan penempatan dan mutasi."],["Menteri PSDM","R","Pemetaan kompetensi, penyusunan usulan, mediasi keberatan."],["Sekretaris Jenderal","R","Menerbitkan SK penempatan dan memperbarui register."],["Menteri / Kabiro","C","Menyampaikan kebutuhan unit dan menanggapi usulan."],["Pengurus bersangkutan","C","Menyampaikan minat dan keberatan."],["Wakil Presiden","C","Memeriksa keseimbangan beban dan program studi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Hasil seleksi dan data minat serta keterampilan pengurus.","Uraian tugas dan program kerja unit.","Hasil evaluasi kinerja (khusus mutasi tengah periode)."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pemetaan kompetensi: Merekap hasil seleksi, minat, keterampilan, pengalaman, dan ketersediaan waktu.","PSDM","Hasil SOP- SDM-001","Profil kompetensi","3 hari kerja"],["2","Analisis kebutuhan: Menyampaikan jumlah dan kompetensi yang dibutuhkan unit.","Menteri/Kabiro","Program kerja unit","Matriks kebutuhan","2 hari kerja"],["3","Penyusunan usulan: Mencocokkan profil dengan kebutuhan, memperhatikan keterwakilan program studi (ART Pasal 5 ayat 1) dan beban kerja.","PSDM","Profil, matriks","Draf penempatan","3 hari kerja"],["4","Konfirmasi: Memberi kesempatan menanggapi kepada Menteri/Kabiro dan pengurus bersangkutan.","Menteri/Kabiro ; pengurus","Draf penempatan","Persetujuan atau keberatan","2 hari kerja"],["5","Penetapan: Pimpinan bermusyawarah; Presiden menetapkan; Sekjen menerbitkan SK.","Pimpinan; Presiden; Sekjen","Draf final","Berita acara dan SK","2 hari kerja"],["6","Masa penyesuaian: Atasan memantau; PSDM mengevaluasi singkat pada hari ke-30.","Atasan; PSDM","SK, catatan atasan","Hasil: tetap atau mutasi","30 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Penempatan awal ditargetkan paling lambat 14 hari kerja setelah pengurus dinyatakan lulus. Mutasi tengah periode memakai tahap 3 sampai 6 dengan pemberitahuan kepada Menteri/Kabiro asal dan tujuan. Hasil akhir: SK penempatan."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Keberatan dimediasi PSDM paling lama 3 hari kerja; bila belum selesai, Presiden memutus dan keputusannya final.","Kebutuhan mendesak ditangani melalui SOP-GOV-012 (keputusan mendesak) dengan pencatatan.","Pengurus yang menunjukkan ketidakcocokan berat pada masa penyesuaian dapat dimutasi atas usulan PSDM dengan persetujuan Presiden.."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% pengurus memiliki SK penempatan paling lambat 14 hari kerja setelah dinyatakan lulus.","Minimal 80% pengurus menilai penempatan sesuai pada survei hari ke-30.","Seluruh mutasi tercatat dengan alasan tertulis."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Profil kompetensi dan matriks kebutuhan.","Berita acara penetapan.","SK penempatan.","Hasil evaluasi masa penyesuaian. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal. Profil pengurus tergolong data terbatas (SOP-SDM-018)."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri PSDM memeriksa kesesuaian penempatan pada evaluasi tengah periode; Irjen menilai kepatuhan prosedur mutasi."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pemetaan kompetensi → Kebutuhan unit → Usulan → Konfirmasi → Penetapan Presiden → SK → Masa penyesuaian → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Profil Kompetensi","Nama; program studi; keterampilan; pengalaman; minat; pilihan unit; ketersediaan waktu."],["Matriks Kebutuhan Unit","Unit; jumlah; kompetensi; prioritas; keterangan."],["Templat SK Penempatan","Nama; jabatan; unit; tanggal efektif; dasar; pengesah."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Profil kompetensi seluruh pengurus tersedia.","☐ Ya ☐ Tidak"],["2","Kebutuhan seluruh unit telah dicatat.","☐ Ya ☐ Tidak"],["3","Pengurus dan Menteri/Kabiro telah diberi kesempatan menanggapi.","☐ Ya ☐ Tidak"],["4","SK penempatan diterbitkan dan register diperbarui.","☐ Ya ☐ Tidak"],["5","Evaluasi masa penyesuaian dilakukan pada hari ke-30.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-003","g":"Keanggotaan dan SDM","t":"Pelantikan dan Orientasi Pengurus Baru","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[612,614],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Memastikan pelantikan pengurus sah, tertib, dan bermartabat, serta seluruh pengurus baru memahami organisasi, kewenangan, dan etika sebelum mulai bekerja."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pelantikan Presiden dan Wakil Presiden, Sekretaris Jenderal, Inspektur Jenderal, Menteri, Kabiro, dan staf, serta orientasi seluruh pengurus baru termasuk pengganti hasil SOP-SDM-015."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 8 ayat (4) (Presiden disahkan dan dilantik oleh Ketua STDIIS).","ART Pasal 5 ayat (3) dan (4) (Presiden dilantik Ketua STDIIS; pengurus dilantik Presiden).","SOP-SDM-007 (kode etik) dan SOP-SDM-018 (kerahasiaan data).","Catatan penyusun B.5 (pelantikan Wakil Presiden)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pelantikan","Prosesi resmi pengambilan ikrar dan penetapan pengurus oleh pejabat berwenang."],["Ikrar amanah","Pernyataan kesanggupan menunaikan tugas dengan jujur dan bertanggung jawab."],["Pakta","Dokumen kepatuhan etika dan kerahasiaan yang ditandatangani pengurus."],["Orientasi","Pembekalan dasar tentang AD/ART, struktur, uraian tugas, SOP inti, dan etika."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Ketua STDIIS","A","Melantik Presiden dan Wakil Presiden (asumsi untuk Wakil Presiden)."],["Presiden","A","Melantik Sekjen, Irjen, Menteri, Kabiro, dan staf."],["Sekretaris Jenderal","R","Rencana, administrasi, berita acara, dan pemberian akses."],["Menteri PSDM","R","Pemeriksaan kelengkapan dan penyelenggaraan orientasi."],["KAUR ORMAWA","C","Koordinasi dengan kampus untuk pelantikan Presiden dan Wapres."],["Pengurus baru","I","Hadir, menandatangani pakta, dan mengikuti orientasi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["SK penempatan atau pengangkatan.","Surat komitmen dan pakta kepatuhan etika serta kerahasiaan yang telah ditandatangani.","Naskah ikrar dan susunan acara."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Persiapan: Menyusun rencana pelantikan (waktu, tempat, susunan acara, naskah SK, daftar yang dilantik).","Sekjen","SK pengurus","Rencana pelantikan","7 hari kerja sebelum acara"],["2","Permohonan: Untuk Presiden dan Wapres, mengirim surat permohonan pelantikan kepada Ketua STDIIS melalui KAUR ORMAWA.","Sekjen","Rencana","Surat terkirim","7 hari kerja sebelum acara"],["3","Pemeriksaan kelengkapan: Memeriksa SK, surat komitmen, dan pakta yang telah ditandatangani.","PSDM","Berkas pengurus","Checklist lengkap","2 hari kerja sebelum acara"],["4","Pelantikan: Pelantik membacakan SK dan memimpin ikrar amanah; pengurus menandatangani berita acara.","Ketua STDIIS atau Presiden","SK, naskah ikrar","Pengurus resmi","Hari pelaksanaan"],["5","Dokumentasi: Menyusun berita acara dan memperbarui register pengurus.","Sekjen","Berita acara","Berita acara, register","2 hari kerja"],["6","Pemberian akses: Menyerahkan uraian tugas dan mengaktifkan akses dokumen serta grup resmi sesuai jabatan.","Sekjen","SK, uraian tugas","Akses aktif","2 hari kerja"],["7","Orientasi: Pembekalan 1 sampai 2 hari: AD/ART, struktur, uraian tugas, SOP inti, kode etik, persuratan, keuangan dasar, komunikasi, kerahasiaan.","PSDM","Materi orientasi","Daftar hadir","Maksimal 14 hari kerja setelah pelantikan"],["8","Evaluasi orientasi: Tes pemahaman dan survei umpan balik.","PSDM","Hasil tes","Laporan orientasi","3 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Dari persiapan hingga orientasi selesai ditargetkan paling lambat 25 hari kerja sejak SK pengurus terbit. Hasil akhir: pengurus resmi dilantik, berkas lengkap, dan orientasi tuntas."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengurus berhalangan hadir dilantik susulan paling lambat 7 hari kerja dan wajib mengikuti orientasi susulan.","Pengurus yang belum dilantik tidak boleh menandatangani dokumen atau mewakili BEM.","Pengunduran diri sebelum pelantikan dilanjutkan ke SOP-SDM-015.","Perbedaan pendapat tentang pelantik Wakil Presiden dikonsultasikan kepada KAUR ORMAWA."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% pengurus dilantik dengan berkas lengkap.","Minimal 90% pengurus mengikuti orientasi tepat waktu.","Nilai pemahaman rata-rata minimal 70.","Seluruh akses aktif paling lambat 2 hari kerja setelah pelantikan."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Berita acara pelantikan dan dokumentasi.","Daftar hadir orientasi dan laporan orientasi.","Pakta bertanda tangan.","Register pengurus yang diperbarui. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan berkas pelantikan; Menteri PSDM mengevaluasi efektivitas orientasi pada setiap gelombang."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Rencana → Permohonan pelantikan → Cek kelengkapan → Pelantikan → Berita acara dan akses → Orientasi → Evaluasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Naskah Ikrar Amanah","Teks ikrar; pelantik; tanggal; tanda tangan."],["Checklist Kelengkapan Pelantikan","Nama; SK; surat komitmen; pakta etika; pakta kerahasiaan; status."],["Materi dan Jadwal Orientasi","Sesi; pemateri; durasi; peserta."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","SK pengurus dan naskah ikrar tersedia.","☐ Ya ☐ Tidak"],["2","Surat permohonan pelantikan Presiden/Wapres telah dikirim.","☐ Ya ☐ Tidak"],["3","Seluruh pengurus telah menandatangani pakta.","☐ Ya ☐ Tidak"],["4","Berita acara dan register telah diperbarui.","☐ Ya ☐ Tidak"],["5","Orientasi dan tesnya telah dilaksanakan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-004","g":"Keanggotaan dan SDM","t":"Penyusunan dan Pengesahan Uraian Tugas","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[615,617],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menjamin setiap jabatan memiliki uraian tugas tertulis yang jelas, tidak tumpang tindih, dan selaras dengan AD/ART, sebagai dasar pembagian pekerjaan, penugasan, dan penilaian kinerja."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh jabatan: Presiden, Wakil Presiden, Sekretaris Jenderal, Inspektur Jenderal, Menteri, Kabiro, dan staf. SOP ini melengkapi SOP-GOV-001 (pembagian tugas dan wewenang)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 7 dan Pasal 13 (susunan dan pimpinan BEM).","ART Bab III (Tugas dan Wewenang BEM) dan Pasal 5 ayat (2) dan (6).","ART Pasal 12 ayat (3) (Irjen menilai kinerja pengurus).","Pedoman SOP Bagian IV (matriks RACI) dan SOP-GOV-001."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Uraian tugas","Rincian tugas, hasil kerja, wewenang, dan tanggung jawab suatu jabatan."],["Atasan langsung","Pejabat yang memberi penugasan dan menilai pengurus pada uraian tugas."],["Matriks tugas","Rekap seluruh uraian tugas untuk memeriksa tumpang tindih dan celah."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Mengesahkan uraian tugas seluruh jabatan."],["Menteri PSDM","R","Menyusun templat, mengonsolidasi, dan mensosialisasikan."],["Menteri / Kabiro","R","Menyusun draf uraian tugas jabatan di unitnya."],["Sekretaris Jenderal","R","Memeriksa kewenangan, memberi nomor, dan mengarsipkan."],["Wakil Presiden","C","Pemeriksa dan pemutus tumpang tindih antarunit."],["Inspektur Jenderal","C","Menelaah keselarasan dengan AD/ART."],["Seluruh pengurus","I","Memahami dan menjalankan uraian tugasnya."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Struktur kabinet dan program kerja hasil RAKER.","Matriks kewenangan SOP-GOV-001.","Uraian tugas kabinet sebelumnya, bila ada."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan templat: Menetapkan isi: identitas jabatan, atasan, tujuan, tugas pokok, wewenang, tanggung jawab, hubungan kerja, indikator, syarat, larangan.","PSDM","Pedoman SOP","Templat","2 hari kerja"],["2","Penyusunan draf: Menyusun uraian tiap jabatan dari program kerja unit.","Menteri/Kabiro","Templat, proker","Draf uraian tugas","7 hari kerja"],["3","Konsolidasi: Memeriksa tumpang tindih dan celah antarunit.","PSDM","Seluruh draf","Matriks tugas","3 hari kerja"],["4","Pemeriksaan kewenangan: Memastikan tidak bertentangan dengan AD/ART dan SOP keuangan; Irjen menelaah.","Sekjen; Irjen","Matriks tugas","Catatan pemeriksaan","3 hari kerja"],["5","Pembahasan: Membahas dan menetapkan draf final pada rapat pimpinan.","Pimpinan","Draf, catatan","Draf final","2 hari kerja"],["6","Pengesahan: Mengesahkan, memberi nomor, dan mengarsipkan.","Presiden; Sekjen","Draf final","Uraian tugas sah","2 hari kerja"],["7","Sosialisasi: Menyerahkan kepada tiap pengurus dengan tanda terima.","PSDM","Uraian tugas sah","Tanda terima","5 hari kerja"],["8","Revisi berkala: Merevisi saat struktur atau proker berubah atau berdasarkan evaluasi kinerja.","PSDM; Sekjen","Hasil evaluasi","Revisi tercatat","Setiap ada pemicu"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Seluruh jabatan memiliki uraian tugas sah paling lambat 21 hari kerja setelah pelantikan. Hasil akhir: uraian tugas sah, matriks tugas, dan tanda terima."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Tumpang tindih tugas antarunit diputus Wakil Presiden; bila menyangkut kewenangan Presiden, diputus Presiden.","Tugas di luar uraian ditangani melalui penugasan tertulis (SOP-SDM-008).","Perselisihan kewenangan antarpengurus: SOP-GOV-010.","Uraian tugas yang bertentangan dengan AD/ART wajib diubah."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% jabatan memiliki uraian tugas sah paling lambat 21 hari kerja setelah pelantikan.","Tidak ada tugas tanpa penanggung jawab pada matriks.","Seluruh pengurus memiliki tanda terima uraian tugas."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Uraian tugas sah setiap jabatan.","Matriks tugas dan catatan pemeriksaan.","Tanda terima dan riwayat revisi. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri PSDM meninjau kesesuaian uraian tugas pada evaluasi tengah periode; Irjen menilai keselarasan dengan AD/ART."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Templat → Draf unit → Konsolidasi → Periksa Sekjen dan Irjen → Pembahasan → Pengesahan Presiden → Sosialisasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Uraian Tugas","Jabatan; atasan; tujuan; tugas pokok; wewenang; tanggung jawab; hubungan kerja; indikator; syarat; larangan."],["Matriks Tugas","Jabatan; tugas; unit; tumpang tindih; keterangan."],["Tanda Terima Uraian Tugas","Nama; jabatan; tanggal; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh jabatan memiliki uraian tugas.","☐ Ya ☐ Tidak"],["2","Tidak ada tumpang tindih atau celah pada matriks.","☐ Ya ☐ Tidak"],["3","Wewenang tidak bertentangan dengan AD/ART.","☐ Ya ☐ Tidak"],["4","Uraian tugas telah disahkan Presiden.","☐ Ya ☐ Tidak"],["5","Seluruh pengurus telah menandatangani tanda terima.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-005","g":"Keanggotaan dan SDM","t":"Penyusunan Target Kerja Individu","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[618,620],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Memastikan setiap pengurus memiliki target kerja yang terukur dan selaras dengan program kerja kabinet hasil RAKER, sebagai dasar pemantauan dan evaluasi kinerja."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus. Target disusun untuk satu periode dan ditinjau pada tengah periode."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 9 ayat (3) huruf a, b, dan e, serta ayat (5) (agenda RAKER dan hasilnya sebagai pedoman satu periode).","AD Pasal 5 (fungsi dan tujuan BEM).","SOP-SDM-004 (uraian tugas), SOP-SDM-009 (pelaporan), dan SOP-SDM-010 (evaluasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Target SMART","Target yang spesifik, terukur, dapat dicapai, relevan, dan memiliki tenggat."],["Lembar target","Dokumen kesepakatan target antara pengurus dan atasan langsung."],["Peninjauan tengah periode","Pemeriksaan ulang target saat proker berubah atau pada evaluasi tengah periode."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Atasan langsung","A","Menyepakati dan mengesahkan target pengurus."],["Pengurus","R","Merumuskan target dan menandatangani lembar target."],["Menteri PSDM","R","Menyediakan templat dan merekap seluruh target."],["Sekretaris Jenderal","C","Memeriksa keselarasan dengan timeline kabinet."],["Presiden","I","Mengesahkan target Menteri/Kabiro dan menerima rekap."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Program kerja dan timeline hasil RAKER.","Uraian tugas jabatan.","Anggaran unit."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penurunan proker: Memilah proker, tugas, dan timeline unit menjadi tugas per pengurus.","Atasan langsung","Proker, uraian tugas","Daftar tugas","3 hari kerja"],["2","Perumusan target: Menulis target SMART: kegiatan, hasil, ukuran, tenggat, dukungan yang dibutuhkan.","Pengurus","Daftar tugas","Draf target","4 hari kerja"],["3","Kesepakatan: Berdiskusi, menyepakati, dan menandatangani lembar target.","Atasan; pengurus","Draf target","Lembar target","3 hari kerja"],["4","Konsolidasi: Merekap seluruh target dan memeriksa keselarasan jadwal serta beban kerja.","PSDM; Sekjen","Lembar target","Rekap target","3 hari kerja"],["5","Pengesahan: Menteri/Kabiro mengesahkan target staf; Presiden mengesahkan target Menteri/Kabiro.","Menteri/Kabiro ; Presiden","Rekap target","Target sah","2 hari kerja"],["6","Peninjauan tengah periode: Merevisi target bila proker berubah, dengan kesepakatan ulang tertulis.","Atasan; pengurus","Hasil evaluasi","Revisi target","Sesuai pemicu"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Seluruh tahap diselesaikan paling lambat 14 hari kerja setelah RAKER. Hasil akhir: target kerja sah seluruh pengurus dan rekap target unit."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengurus yang menilai beban berlebihan mengajukan keberatan tertulis kepada atasan; bila belum sepakat, Wakil Presiden memutus.","Target yang tidak tercapai karena faktor di luar kendali dicatat sebagai kendala dan tidak otomatis dinilai kurang.","Perubahan proker besar memerlukan penyesuaian target melalui persetujuan atasan dan pencatatan."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% pengurus memiliki target sah paling lambat 14 hari kerja setelah RAKER.","Minimal 90% target memenuhi kriteria SMART pada pemeriksaan PSDM.","Seluruh revisi target tercatat."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar target bertanda tangan.","Rekap target unit.","Catatan revisi target. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal. Target individu tergolong data terbatas (SOP-SDM-018)."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri PSDM memeriksa mutu target pada setiap siklus; Irjen menilai konsistensi target dengan program kerja pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Penurunan proker → Perumusan target → Kesepakatan → Konsolidasi → Pengesahan → Pemantauan → Peninjauan tengah periode → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Target Individu","Nama; jabatan; kegiatan; hasil; ukuran; tenggat; dukungan; tanda tangan."],["Rekap Target Unit","Unit; pengurus; target; tenggat; status."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Target berasal dari proker hasil RAKER.","☐ Ya ☐ Tidak"],["2","Setiap target memenuhi kriteria SMART.","☐ Ya ☐ Tidak"],["3","Lembar target ditandatangani pengurus dan atasan.","☐ Ya ☐ Tidak"],["4","Target Menteri/Kabiro disahkan Presiden.","☐ Ya ☐ Tidak"],["5","Rekap target diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-006","g":"Keanggotaan dan SDM","t":"Presensi, Izin, Sakit, dan Ketidakhadiran","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[621,624],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Mengatur pencatatan kehadiran, izin, dan sakit serta penanganan ketidakhadiran secara adil dan konsisten, termasuk pelaksanaan ketentuan pemberhentian karena tidak mengikuti kegiatan tiga kali berturut-turut tanpa uzur."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus pada kegiatan wajib: rapat kabinet, rapat pimpinan (bagi yang terkait), rapat koordinasi, rapat unit, RAKER, Mubes dan Musyawarah Istimewa, pelantikan dan orientasi, serta kegiatan resmi yang dinyatakan wajib dalam undangan. Berlaku untuk kegiatan luring maupun daring (ART Pasal 10 ayat 6)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 9 ayat (2) huruf e (diberhentikan karena tidak mengikuti kegiatan organisasi 3 kali berturut- turut tanpa uzur).","ART Pasal 10 (Rapat Koordinasi) dan Pasal 11 huruf l (larangan meninggalkan tanggung jawab tanpa alasan sah).","ART Pasal 12 ayat (2) (jenis sanksi) dan Pasal 13 ayat (9) (hak klarifikasi dan pembelaan).","Catatan penyusun B.7 (definisi kegiatan wajib dan cara menghitung)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kegiatan wajib","Kegiatan yang dinyatakan wajib dalam undangan oleh penyelenggara."],["Uzur","Alasan yang dibenarkan: sakit, musibah atau kedukaan keluarga, kewajiban akademik yang tidak dapat dipindah, tugas resmi kampus, atau alasan darurat lain yang diterima atasan."],["Alpa","Tidak hadir tanpa uzur atau tanpa pemberitahuan."],["Berturut-turut","Alpa pada kegiatan wajib yang berurutan; kehadiran atau izin sah memutus rangkaian."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Menetapkan tata cara presensi dan menyampaikan rekap serta eskalasi."],["Biro Kesekretariatan","R","Mencatat presensi dan menyusun rekap."],["Menteri / Kabiro","R","Menilai izin staf unitnya."],["Pengurus","R","Hadir atau memberi kabar tepat waktu."],["Menteri PSDM","C","Pembinaan pengurus yang sering tidak hadir."],["Inspektur Jenderal","I","Menerima laporan eskalasi alpa tiga kali."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Undangan kegiatan yang mencantumkan status wajib.","Formulir izin atau sakit dan bukti uzur.","Daftar hadir (digital atau manual)."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan kegiatan wajib: Mencantumkan status wajib pada undangan.","Penyelenggara; Sekjen","Rencana kegiatan","Undangan","Sebelum kegiatan"],["2","Pengajuan izin: Memberi tahu lewat kanal resmi disertai alasan: paling lambat 3 jam sebelum rapat rutin atau H-1 untuk kegiatan besar; sakit mendadak boleh dikabarkan segera.","Pengurus","Formulir izin","Permohonan izin","Sesuai ketentuan"],["3","Penilaian izin: Menilai uzur dan menjawab; penolakan wajib disertai alasan.","Atasan langsung","Permohonan izin","Status izin","3 jam"],["4","Presensi: Mengisi presensi; terlambat lebih dari 15 menit dicatat terlambat.","Pengurus; Kesekretariatan","Daftar hadir","Daftar hadir","Saat kegiatan"],["5","Bukti uzur: Menyerahkan bukti (surat dokter atau keterangan) untuk sakit dua hari atau lebih dan kegiatan besar.","Pengurus","Bukti","Bukti uzur","Maksimal 3 hari kerja setelah kegiatan"],["6","Rekap: Merekap per kegiatan dan bulanan; menyampaikan kepada Menteri/Kabiro dan PSDM.","Kesekretariatan ; Sekjen","Daftar hadir, izin","Rekap kehadiran","2 hari kerja"],["7","Penanganan alpa: Alpa 1 kali: atasan menanyakan alasan (tabayyun) dan mengingatkan lisan. Alpa 2 kali berturut-turut: teguran tertulis dan pembinaan (SOP-SDM-011). Alpa 3 kali berturut-turut tanpa uzur: Sekjen melapor ke Irjen untuk SOP-SDM-013 dan 014.","Atasan; Sekjen; Irjen","Rekap kehadiran","Tindak lanjut tercatat","3 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Rekap kehadiran disampaikan paling lambat 2 hari kerja setelah kegiatan; tindak lanjut alpa dimulai paling lambat 3 hari kerja. Hasil akhir: rekap kehadiran bulanan dan catatan tindak lanjut."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Gangguan sistem presensi: gunakan daftar hadir manual.","Izin terlambat karena keadaan darurat dapat diterima bila dijelaskan paling lambat 24 jam.","Perbedaan penilaian uzur diputus Sekjen bersama PSDM.","Pengurus berhak memberi klarifikasi sebelum dinyatakan alpa tiga kali (ART Pasal 13 ayat 9).","Ketidakhadiran pada kegiatan yang tidak berstatus wajib tidak dihitung."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["Kehadiran rapat wajib minimal 85%.","100% ketidakhadiran tercatat dengan status (hadir, izin, sakit, alpa).","Tidak ada pemberhentian karena absen tanpa klarifikasi tertulis.","Rekap bulanan disampaikan tepat waktu."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar hadir dan register izin.","Rekap kehadiran bulanan.","Surat teguran tertulis, bila ada. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal. Alasan sakit tergolong data rahasia (SOP-SDM-018)."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan rekap tiap bulan; Irjen menilai konsistensi penerapan aturan alpa pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Undangan wajib → Izin atau hadir → Presensi → Bukti uzur → Rekap → Alpa: ingatkan, tegur, eskalasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Izin atau Sakit","Nama; kegiatan; alasan; bukti; tanggal; persetujuan atasan."],["Daftar Hadir Kegiatan","Kegiatan; tanggal; nama; status; paraf."],["Rekap Kehadiran Bulanan","Nama; hadir; izin; sakit; alpa; terlambat; catatan."],["Templat Teguran Tertulis","Nama; dasar; kejadian; tindak lanjut; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Undangan mencantumkan status wajib.","☐ Ya ☐ Tidak"],["2","Izin dan sakit tercatat dengan status.","☐ Ya ☐ Tidak"],["3","Rekap bulanan disampaikan kepada atasan dan PSDM.","☐ Ya ☐ Tidak"],["4","Alpa 1 dan 2 kali ditindaklanjuti dalam batas waktu.","☐ Ya ☐ Tidak"],["5","Alpa 3 kali berturut-turut telah diklarifikasi sebelum dieskalasi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-007","g":"Keanggotaan dan SDM","t":"Standar Kedisiplinan dan Etika Organisasi","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[625,627],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan standar perilaku pengurus yang islami, profesional, dan berintegritas serta cara menegakkannya, sehingga pembinaan lebih didahulukan daripada sanksi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus, baik di dalam kegiatan BEM maupun di luar kegiatan saat membawa nama BEM, termasuk di ruang digital."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 3 (landasan Al-Qur'an dan As-Sunnah) dan Pasal 5 (fungsi, termasuk pembelajaran tanggung jawab, disiplin, dan amanah).","AD Pasal 9 ayat (2) (alasan pemberhentian) dan Pasal 18 ayat (3) (seragam resmi PDH BEM).","ART Pasal 2 dan 3 (hak dan kewajiban BEM).","ART Pasal 11 (larangan) dan Pasal 12 (sanksi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kode etik","Standar perilaku yang disahkan Presiden dan wajib dipatuhi pengurus."],["Pakta kepatuhan","Pernyataan tertulis pengurus untuk mematuhi kode etik."],["Pembinaan","Nasihat dan arahan kepada pengurus sebelum penerapan sanksi."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Mengesahkan kode etik dan menjadi teladan."],["Menteri PSDM","R","Menyusun kode etik, sosialisasi, dan pembinaan."],["Inspektur Jenderal","R","Memantau kepatuhan dan melapor melalui forum resmi BEM."],["Menteri / Kabiro","R","Keteladanan dan pembinaan unit."],["Sekretaris Jenderal","C","Menelaah draf dan mengarsipkan pakta."],["Seluruh pengurus","R","Mematuhi kode etik dan menandatangani pakta."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["AD/ART, terutama larangan pada ART Pasal 11.","Standar inti perilaku: akhlak dan amanah; disiplin; PDH pada kegiatan resmi dan berpakaian sopan sesuai aturan kampus; komunikasi santun tanpa fitnah; menjaga batasan pergaulan sesuai syariat; integritas keuangan dan fasilitas; netralitas politik praktis; kerahasiaan dan pelaporan konflik kepentingan.","Aturan kampus tentang tata tertib mahasiswa."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan kode etik: Menyusun dari standar inti dan larangan ART Pasal 11; ditelaah Irjen dan Sekjen.","PSDM","AD/ART, aturan kampus","Draf kode etik","7 hari kerja"],["2","Pengesahan: Membahas pada rapat kabinet dan menetapkan.","Presiden","Draf","Kode etik sah","3 hari kerja"],["3","Pakta kepatuhan: Menandatangani pakta saat pelantikan (SOP-SDM-003).","Pengurus","Kode etik","Pakta","Saat pelantikan"],["4","Sosialisasi: Menjelaskan dengan contoh kasus saat orientasi dan menyegarkan setiap bulan.","PSDM","Kode etik","Daftar hadir","Berkala"],["5","Pembinaan harian: Menasihati secara pribadi pelanggaran ringan yang pertama kali dan mencatatnya.","Atasan langsung","Temuan","Catatan pembinaan","Maksimal 3 hari kerja"],["6","Pemantauan: Memantau kepatuhan tiap triwulan dan melaporkan melalui forum resmi BEM (ART Pasal 13 ayat 6).","Irjen","Catatan pembinaan","Laporan pemantauan","Triwulan"],["7","Penegakan: Pelanggaran yang tidak selesai melalui pembinaan dilaporkan dan diproses melalui SOP-SDM-013.","Atasan; Irjen","Laporan","Tindak lanjut","Sesuai SOP- SDM-013"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Kode etik disahkan paling lambat 10 hari kerja setelah pelantikan, sebelum atau bersamaan dengan orientasi. Hasil akhir: kode etik sah dan pakta bertanda tangan seluruh pengurus."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Ketentuan yang multitafsir ditafsirkan bersama PSDM dan Irjen, lalu ditetapkan Presiden dan diumumkan.","Perubahan kode etik mengikuti tahap 1 sampai 4.","Pelanggaran yang tergolong berat tidak melalui pembinaan, langsung ke SOP-SDM-013.","Dugaan perundungan atau pelecehan mengikuti SOP-SDM-017."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% pengurus menandatangani pakta.","Kasus berulang menurun pada evaluasi tengah periode.","100% laporan pelanggaran ditindaklanjuti sesuai SOP-SDM-013."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Kode etik sah.","Pakta bertanda tangan dan daftar hadir sosialisasi.","Catatan pembinaan dan laporan pemantauan. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal. Catatan pembinaan bersifat rahasia (SOP-SDM-018)."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri PSDM mengevaluasi efektivitas sosialisasi tiap semester; Irjen melaporkan kepatuhan pada forum resmi BEM."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Susun kode etik → Pengesahan Presiden → Pakta → Sosialisasi → Pembinaan → Pemantauan Irjen → Penegakan (SOP-SDM-013) → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Kode Etik Pengurus","Standar inti; larangan; hak pembelaan; sanksi; pengesahan."],["Pakta Kepatuhan Etika","Nama; jabatan; pernyataan; tanggal; tanda tangan."],["Catatan Pembinaan","Pengurus; kejadian; nasihat; tindak lanjut; pembina; tanggal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kode etik memuat larangan ART Pasal 11.","☐ Ya ☐ Tidak"],["2","Kode etik telah disahkan Presiden.","☐ Ya ☐ Tidak"],["3","Seluruh pengurus telah menandatangani pakta.","☐ Ya ☐ Tidak"],["4","Sosialisasi dilakukan saat orientasi dan berkala.","☐ Ya ☐ Tidak"],["5","Laporan pemantauan Irjen disampaikan tiap triwulan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-008","g":"Keanggotaan dan SDM","t":"Pemberian dan Pemantauan Penugasan","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[628,630],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Memastikan setiap penugasan jelas, tertulis, terpantau, dan dapat dipertanggungjawabkan, sehingga tidak ada pekerjaan penting tanpa penanggung jawab dan hasil yang dapat diperiksa."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk tugas rutin, tugas khusus, penunjukan panitia atau delegasi, baik antarpengurus maupun antarunit, di dalam maupun di luar program kerja."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf c (mengusulkan pembentukan panitia dan tim kerja internal).","ART Pasal 9 (RAKER: pembagian tugas dan tanggung jawab).","Pedoman SOP Bagian IV (matriks RACI).","SOP-SDM-004 (uraian tugas) dan SOP-GOV-008 (pendelegasian wewenang)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Lembar penugasan","Dokumen berisi tujuan, keluaran, tenggat, prioritas, sumber daya, dan kewenangan penugasan."],["Pemberi tugas","Pejabat yang berwenang menugaskan sesuai uraian tugas."],["Tracker penugasan","Daftar penugasan beserta penerima, tenggat, dan status."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Pemberi tugas","A","Menyusun lembar penugasan, memantau, dan memverifikasi hasil."],["Penerima tugas","R","Mengonfirmasi, melaksanakan, dan melapor."],["Sekretaris Jenderal","R","Mencatat dan memelihara tracker penugasan."],["Menteri / Kabiro terkait","C","Memberi masukan untuk penugasan lintas unit."],["Inspektur Jenderal","I","Menerima rekap keterlambatan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Uraian tugas dan program kerja.","Kebutuhan pekerjaan dari pimpinan atau unit.","Kapasitas dan beban kerja penerima tugas."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Perumusan: Menulis lembar penugasan: tujuan, keluaran, tenggat, prioritas, sumber daya, kewenangan, dan cara pelaporan.","Pemberi tugas","Kebutuhan pekerjaan","Lembar penugasan","Sebelum disampaikan"],["2","Penyampaian: Menyampaikan melalui kanal resmi (SOP-KOM-03); penugasan lisan yang mendesak wajib ditegaskan tertulis.","Pemberi tugas","Lembar penugasan","Penugasan diterima","Maksimal 24 jam"],["3","Konfirmasi: Menyatakan sanggup atau berkeberatan beserta alasan (beban, jadwal, kompetensi).","Penerima","Penugasan","Konfirmasi","1 x 24 jam"],["4","Pencatatan: Mencatat nomor, penerima, tenggat, dan status pada tracker.","Sekjen","Konfirmasi","Entri tracker","1 hari kerja"],["5","Pemantauan: Check-in pada pertengahan waktu; penerima melapor lewat SOP-SDM-009.","Pemberi; penerima","Tracker","Catatan progres","Berkala"],["6","Penanganan hambatan: Melapor hambatan segera; pemberi memberi dukungan, memperpanjang tenggat satu kali, atau menugaskan ulang.","Penerima; pemberi","Laporan hambatan","Keputusan tertulis","2 hari kerja"],["7","Penyelesaian dan verifikasi: Menyerahkan hasil; pemberi memeriksa kesesuaian dengan keluaran.","Penerima; pemberi","Hasil kerja","Hasil terverifikasi","2 hari kerja"],["8","Penutupan: Menutup status dan mencatat umpan balik untuk evaluasi kinerja.","Pemberi; Sekjen","Hasil terverifikasi","Tracker selesai","1 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Penugasan disampaikan, dikonfirmasi, dan dicatat paling lambat 3 hari kerja sejak dirumuskan; tenggat pelaksanaan ditetapkan pada lembar penugasan. Hasil akhir: hasil kerja terverifikasi dan tracker tertutup."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Keterlambatan melewati tenggat ditangani melalui SOP-MONEV-08.","Penugasan yang bertentangan dengan AD/ART, syariat, atau kode etik wajib ditolak dan dilaporkan kepada atasan atau Irjen.","Pendelegasian lanjutan memerlukan persetujuan pemberi tugas (SOP-GOV-008).","Perselisihan beban kerja diputus atasan bersama PSDM."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% penugasan selesai sesuai tenggat.","100% penugasan tercatat pada tracker.","Seluruh penugasan lisan terkonfirmasi tertulis paling lambat 24 jam."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar penugasan.","Tracker penugasan.","Catatan hambatan dan hasil verifikasi. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa tracker tiap pekan; Irjen menilai kepatuhan pencatatan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Rumuskan penugasan → Sampaikan → Konfirmasi → Catat → Pantau → Atasi hambatan → Verifikasi hasil → Tutup → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Penugasan","Nomor; pemberi; penerima; tujuan; keluaran; tenggat; prioritas; sumber daya; cara lapor."],["Tracker Penugasan","Nomor; penerima; tenggat; status; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Penugasan tertulis dan memuat keluaran serta tenggat.","☐ Ya ☐ Tidak"],["2","Penerima telah mengonfirmasi dalam 1 x 24 jam.","☐ Ya ☐ Tidak"],["3","Penugasan tercatat pada tracker.","☐ Ya ☐ Tidak"],["4","Hambatan dilaporkan dan diputus tertulis.","☐ Ya ☐ Tidak"],["5","Hasil diverifikasi sebelum penugasan ditutup.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-009","g":"Keanggotaan dan SDM","t":"Pelaporan Progres Pekerjaan","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[631,633],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menjamin atasan dan pimpinan menerima informasi progres yang tepat waktu, seragam, dan dapat ditindaklanjuti, sehingga hambatan diketahui sebelum menjadi keterlambatan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk laporan mingguan pengurus kepada atasan, laporan bulanan unit kepada Sekretaris Jenderal, dan laporan bulanan kabinet kepada Presiden."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) (kewajiban laporan pertanggungjawaban secara berkala).","ART Pasal 3 huruf e dan g (kewajiban membuat laporan) dan Pasal 10 (Rapat Koordinasi).","SOP-ADM-19 (laporan bulanan dan laporan kabinet), SOP-KOM-04, dan SOP-MONEV-03."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Laporan progres","Laporan singkat tentang pekerjaan selesai, sedang berjalan, rencana, dan kendala."],["Kanal resmi","Platform komunikasi yang ditetapkan BEM untuk pelaporan."],["Kendala","Hambatan yang menghalangi pencapaian target atau tenggat."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden dan Wakil Presiden","A","Menerima laporan kabinet dan menindaklanjuti."],["Sekretaris Jenderal","R","Menyusun laporan bulanan kabinet dan menyimpan arsip."],["Menteri / Kabiro","R","Memverifikasi laporan staf dan menyusun laporan bulanan unit."],["Pengurus","R","Menyusun dan mengirim laporan mingguan."],["Inspektur Jenderal","I","Menerima rekap temuan dan keterlambatan laporan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Target kerja individu (SOP-SDM-005) dan penugasan (SOP-SDM-008).","Format laporan: selesai; sedang dikerjakan (persentase); rencana pekan depan; kendala; bantuan yang dibutuhkan; bukti atau tautan.","Data kehadiran dan tracker penugasan."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Laporan mingguan: Mengirim laporan lewat kanal resmi sesuai format.","Pengurus","Target, penugasan","Laporan mingguan","Kamis pukul 20.00 (usulan)"],["2","Verifikasi: Mencocokkan dengan target dan penugasan.","Menteri/Kabiro","Laporan mingguan","Laporan terverifikasi","1 hari kerja"],["3","Tindak lanjut: Memberi umpan balik dan bantuan atas kendala.","Atasan","Laporan terverifikasi","Catatan tindak lanjut","2 hari kerja"],["4","Laporan bulanan unit: Menyerahkan rangkuman unit.","Menteri/Kabiro","Laporan mingguan","Laporan unit","Tanggal 5 (usulan)"],["5","Konsolidasi: Menyusun laporan bulanan kabinet.","Sekjen","Laporan unit","Laporan kabinet","3 hari kerja"],["6","Pembahasan: Membahas pada rapat pimpinan atau kabinet; keputusan dicatat dalam notulen.","Pimpinan","Laporan kabinet","Keputusan tindak lanjut","Rapat berikutnya"],["7","Penyimpanan: Mengarsipkan laporan di folder resmi.","Sekjen","Laporan final","Arsip","1 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Laporan mingguan masuk setiap pekan, laporan unit setiap bulan, dan laporan kabinet dikonsolidasi paling lambat 3 hari kerja setelah laporan unit lengkap. Hasil akhir: laporan bulanan kabinet dan keputusan tindak lanjut."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Laporan terlambat diingatkan satu kali; selanjutnya ditangani melalui SOP-MONEV-08.","Pekerjaan yang macet wajib dilaporkan sebagai kendala, bukan didiamkan.","Data sensitif hanya dikirim melalui kanal terbatas (SOP-SDM-018).","Laporan yang dimanipulasi diproses melalui SOP-SDM-013."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% laporan mingguan tepat waktu.","100% laporan bulanan unit masuk sesuai jadwal.","Kendala ditindaklanjuti paling lambat 2 hari kerja."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan mingguan dan bulanan unit.","Laporan bulanan kabinet.","Catatan tindak lanjut. Seluruh dokumen disimpan pada repositori resmi BEM (folder Laporan) oleh Sekretaris Jenderal."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa ketepatan waktu dan kelengkapan laporan tiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Laporan mingguan → Verifikasi atasan → Tindak lanjut → Laporan unit → Konsolidasi Sekjen → Pembahasan → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Format Laporan Mingguan","Nama; periode; selesai; sedang dikerjakan; rencana; kendala; bantuan; bukti."],["Format Laporan Bulanan Unit","Unit; periode; capaian; kendala; rencana; serapan anggaran; lampiran."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Laporan memakai format baku.","☐ Ya ☐ Tidak"],["2","Laporan telah diverifikasi atasan.","☐ Ya ☐ Tidak"],["3","Kendala memiliki tindak lanjut.","☐ Ya ☐ Tidak"],["4","Laporan bulanan unit diserahkan sesuai jadwal.","☐ Ya ☐ Tidak"],["5","Laporan kabinet dibahas dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-010","g":"Keanggotaan dan SDM","t":"Evaluasi Kinerja Individu dan Unit","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[634,636],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menilai kinerja pengurus dan unit secara objektif, terukur, dan adil sebagai dasar pembinaan, apresiasi, mutasi, dan pengembangan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus dan unit (kementerian, biro, Inspektorat Jenderal, sekretariat) pada tiga siklus: ringan bulanan, tengah periode (selaras SOP-MONEV-11), dan akhir periode (selaras SOP-MONEV-12 dan SOP-TRN-01)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 12 ayat (3) dan (4) (Irjen mengawasi, mengevaluasi, dan menilai kinerja pengurus).","ART Pasal 13 ayat (6) (hasil pengawasan disampaikan melalui forum resmi BEM).","AD Pasal 17 (pengelolaan transparan dan akuntabel).","SOP-SDM-005 (target) dan SOP-SDM-009 (laporan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Penilaian diri","Penilaian pengurus atas kinerjanya sendiri disertai bukti."],["Kalibrasi","Penyamaan standar penilaian antarunit agar adil."],["Kategori kinerja","Sangat Baik (85 atau lebih), Baik (70 sampai 84), Cukup (55 sampai 69), Kurang (di bawah 55); usulan."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Mengesahkan hasil dan tindak lanjut."],["Menteri PSDM","R","Menyusun instrumen, mengompilasi, dan mengalirkan rekomendasi."],["Atasan langsung","R","Menilai dan memberi umpan balik."],["Inspektur Jenderal","R","Memverifikasi objektivitas dan menerima keberatan."],["Sekretaris Jenderal","C","Menyediakan data kehadiran, laporan, dan tracker."],["Pengurus","C","Menyusun penilaian diri."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Bobot individu (usulan): capaian target 50; kehadiran dan kedisiplinan 15; kualitas kerja dan kolaborasi 20; etika dan amanah 15.","Bobot unit (usulan): ketercapaian proker 40; ketepatan waktu dan laporan 20; tertib administrasi dan keuangan 20; kolaborasi dan kontribusi 20.","Data kehadiran, laporan, tracker penugasan, dan ketertiban pertanggungjawaban."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Instrumen dan jadwal: Menetapkan jadwal, instrumen, dan bobot; Presiden mengesahkan.","PSDM; Presiden","Pedoman SOP","Instrumen sah","Awal periode"],["2","Pengumpulan data: Menyerahkan data kehadiran, laporan, tracker, dan ketertiban pertanggungjawaban.","Sekjen; Biro Keuangan","Arsip","Paket data","3 hari kerja"],["3","Penilaian diri: Mengisi penilaian diri disertai bukti.","Pengurus","Instrumen","Formulir diri","3 hari kerja"],["4","Penilaian atasan: Menilai berdasarkan data dan bukti.","Atasan langsung","Paket data","Skor atasan","4 hari kerja"],["5","Verifikasi: Memeriksa konsistensi dan bukti; selisih penilaian diri dan atasan lebih dari 15 poin diklarifikasi.","Irjen","Skor","Skor terverifikasi","3 hari kerja"],["6","Kalibrasi: Menyamakan standar antarunit.","PSDM; Wapres; Sekjen","Skor terverifikasi","Hasil akhir","2 hari kerja"],["7","Umpan balik: Menyampaikan hasil secara pribadi: kekuatan, perbaikan, rencana.","Atasan","Hasil akhir","Berita umpan balik","3 hari kerja"],["8","Pengesahan dan tindak lanjut: Mengesahkan; menyampaikan hasil agregat di forum resmi BEM; rekomendasi dialirkan ke SOP-SDM- 002, 011, 012, 016.","Presiden; PSDM","Hasil akhir","Laporan evaluasi","3 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Satu siklus evaluasi diselesaikan paling lambat 22 hari kerja sejak jadwal dibuka. Hasil akhir: laporan evaluasi yang disahkan Presiden beserta rekomendasi tindak lanjut."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Keberatan diajukan tertulis ke Irjen paling lambat 3 hari kerja setelah umpan balik dan dijawab paling lambat 5 hari kerja.","Hasil individu bersifat rahasia (SOP-SDM-018); hanya hasil agregat yang dibuka.","Menteri/Kabiro dinilai Presiden dan Wapres dengan masukan staf unitnya; Presiden dan Wapres dievaluasi melalui forum evaluasi kabinet.","Pengurus bernilai di bawah 55 diproses melalui SOP-SDM-011."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% pengurus dan unit dievaluasi pada tiap siklus.","Keberatan terjawab paling lambat 5 hari kerja.","Seluruh rekomendasi memiliki tindak lanjut tercatat."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Instrumen dan lembar penilaian.","Berita umpan balik.","Laporan evaluasi dan rekomendasi. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM, akses terbatas) oleh Sekretaris Jenderal."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri PSDM meninjau instrumen setelah tiap siklus; Irjen menilai objektivitas dan kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Instrumen → Data → Penilaian diri → Penilaian atasan → Verifikasi Irjen → Kalibrasi → Umpan balik → Pengesahan Presiden → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Penilaian Individu","Nama; komponen; skor diri; skor atasan; bukti; catatan."],["Formulir Penilaian Unit","Unit; komponen; skor; bukti; catatan."],["Berita Umpan Balik","Pengurus; hasil; kekuatan; perbaikan; rencana; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Instrumen dan bobot disahkan di awal periode.","☐ Ya ☐ Tidak"],["2","Penilaian diri dan atasan memakai bukti.","☐ Ya ☐ Tidak"],["3","Irjen telah memverifikasi konsistensi nilai.","☐ Ya ☐ Tidak"],["4","Umpan balik disampaikan secara pribadi.","☐ Ya ☐ Tidak"],["5","Rekomendasi telah dialirkan ke SOP terkait.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-011","g":"Keanggotaan dan SDM","t":"Pembinaan Anggota Tidak Aktif atau Tidak Memenuhi Tugas","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[637,639],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Memulihkan pengurus yang tidak aktif atau tidak memenuhi tugas melalui pembinaan terstruktur sebelum menempuh sanksi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku bila terjadi salah satu pemicu: (a) alpa 2 kali berturut-turut tanpa uzur; (b) nilai evaluasi di bawah 55; (c) tugas terlambat tanpa kabar 3 kali; (d) tidak merespons kanal resmi lebih dari 7 hari tanpa kabar. Pembinaan bukan sanksi, bersifat rahasia, dan tidak dilakukan dengan mempermalukan di grup."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 9 ayat (2) huruf e.","ART Pasal 11 huruf l dan Pasal 12 ayat (1) dan (2) (pembinaan dan penegakan disiplin oleh pimpinan; jenis sanksi).","SOP-SDM-006 (presensi) dan SOP-SDM-010 (evaluasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pembinaan","Pendampingan terstruktur untuk memulihkan kinerja dan keaktifan pengurus."],["Rencana pembinaan","Kesepakatan tertulis tentang penyebab, perbaikan, dukungan, dan target selama 14 hari."],["Cuti sementara","Penonaktifan sementara paling lama 30 hari atas persetujuan Presiden bagi pengurus dengan kondisi berat."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Wakil Presiden","A","Meninjau hasil pembinaan dan memutuskan kelanjutan."],["Atasan langsung","R","Melakukan pendekatan pribadi dan pendampingan."],["Menteri PSDM","R","Menyusun rencana pembinaan dan menilai hasilnya."],["Sekretaris Jenderal","C","Menyediakan data kehadiran dan laporan."],["Inspektur Jenderal","I","Menerima eskalasi bila pembinaan tidak berhasil."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Rekap kehadiran, laporan, dan tracker penugasan.","Hasil evaluasi kinerja.","Catatan pembinaan sebelumnya."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Identifikasi: Mengidentifikasi pengurus yang memenuhi pemicu dari rekap kehadiran, laporan, dan evaluasi.","Sekjen; PSDM","Rekap SOP- SDM-006, 009, 010","Daftar pembinaan","2 hari kerja"],["2","Pendekatan pribadi: Menemui pengurus secara pribadi untuk tabayyun dan memahami penyebab (akademik, kesehatan, pribadi, beban, motivasi).","Atasan langsung","Daftar pembinaan","Catatan pertemuan","3 hari kerja"],["3","Rencana pembinaan: Menyepakati penyebab, perbaikan, dukungan (pengurangan beban sementara, pendampingan), dan target terukur 14 hari.","Atasan; PSDM; pengurus","Catatan pertemuan","Rencana tertulis","2 hari kerja"],["4","Pendampingan: Mendampingi dengan check-in setiap 3 sampai 4 hari.","Atasan; PSDM","Rencana","Catatan pendampingan","14 hari kerja"],["5","Evaluasi: Menilai pencapaian target pembinaan.","PSDM","Catatan pendampingan","Hasil evaluasi","2 hari kerja"],["6","Keputusan: Pulih: ditutup. Belum pulih: diperpanjang 14 hari satu kali. Tetap belum pulih atau ada pelanggaran: eskalasi ke SOP-SDM-013, atau SOP- SDM-014 bila pengurus memilih mengundurkan diri.","Wapres; PSDM","Hasil evaluasi","Keputusan tertulis","2 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Satu siklus pembinaan paling lama 25 hari kerja, termasuk satu kali perpanjangan 14 hari bila diperlukan. Hasil akhir: keputusan tertulis (pulih, perpanjangan, atau eskalasi)."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengurus dengan kondisi berat (sakit berat, musibah) dapat diberi cuti sementara paling lama 30 hari atas persetujuan Presiden dan tidak dihitung alpa.","Indikasi tekanan, perundungan, atau pelecehan dialihkan ke SOP-SDM-017 dan, bila perlu, layanan konseling kampus.","Pelanggaran berat tidak melalui pembinaan, langsung ke SOP-SDM-013."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 70% pengurus yang dibina pulih.","100% eskalasi sanksi didahului catatan pembinaan.","Tidak ada pembinaan yang dipublikasikan di grup."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Catatan pertemuan dan pendampingan.","Rencana dan hasil evaluasi pembinaan.","Keputusan tertulis. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal. Seluruh catatan pembinaan bersifat rahasia (SOP-SDM-018)."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri PSDM melaporkan tingkat keberhasilan pembinaan pada evaluasi tengah periode; Irjen menilai kepatuhan prosedur."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Identifikasi → Pendekatan pribadi → Rencana 14 hari → Pendampingan → Evaluasi → Pulih atau eskalasi (SOP-SDM-013/014) → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Catatan Pembinaan","Pengurus; pemicu; penyebab; nasihat; tindak lanjut; pembina; tanggal."],["Rencana Pembinaan","Penyebab; perbaikan; dukungan; target; jadwal check-in; tanda tangan."],["Hasil Evaluasi Pembinaan","Target; capaian; keputusan; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pemicu terverifikasi dari data.","☐ Ya ☐ Tidak"],["2","Pendekatan pribadi dilakukan sebelum rencana disusun.","☐ Ya ☐ Tidak"],["3","Rencana pembinaan disepakati tertulis.","☐ Ya ☐ Tidak"],["4","Pembinaan terdokumentasi dan rahasia.","☐ Ya ☐ Tidak"],["5","Eskalasi hanya setelah pembinaan dilakukan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-012","g":"Keanggotaan dan SDM","t":"Penghargaan dan Apresiasi Anggota","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[640,642],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menumbuhkan semangat dan keteladanan melalui apresiasi yang adil dan transparan, tanpa menggeser keikhlasan dalam berorganisasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk apresiasi segera (lisan atau tertulis), Pengurus Teladan (triwulan), Unit Terbaik (tengah dan akhir periode), dan penghargaan akhir kabinet."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 5 ayat (4) (media pembelajaran tanggung jawab, disiplin, dan amanah).","SOP-SDM-010 (evaluasi kinerja).","SOP keuangan (SOP-KEU) bila penghargaan memerlukan anggaran."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Apresiasi segera","Ucapan atau pengakuan langsung atas kontribusi nyata."],["Pengurus Teladan","Penghargaan periodik bagi pengurus dengan kinerja dan akhlak terbaik."],["Daftar layak","Daftar nominasi yang lolos verifikasi."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Mengesahkan penerima penghargaan."],["Menteri PSDM","R","Mengelola proses nominasi dan verifikasi."],["Menteri / Kabiro","R","Mengusulkan nominasi dengan alasan dan bukti."],["Inspektur Jenderal","R","Memastikan nominasi bebas sanksi dan pelanggaran."],["Biro Keuangan","C","Memeriksa anggaran bila ada."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Kriteria: skor SOP-SDM-010 minimal 85; tidak sedang menjalani sanksi; kehadiran minimal 90%; kontribusi nyata berupa inisiatif, kolaborasi, dan akhlak.","Usulan nominasi beserta bukti.","Anggaran dalam RAB, bila ada."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Apresiasi segera: Menyampaikan apresiasi atas kontribusi nyata dan mencatatnya.","Pimpinan; atasan","Kontribusi nyata","Catatan apresiasi","Segera"],["2","Pembukaan nominasi: Membuka nominasi tiap siklus; atasan mengusulkan dengan alasan dan bukti.","PSDM; Menteri/Kabiro","Kriteria","Daftar nominasi","3 hari kerja"],["3","Verifikasi: Mencocokkan skor dan kehadiran; memastikan tidak ada sanksi atau pelanggaran.","PSDM; Irjen","Daftar nominasi","Daftar layak","3 hari kerja"],["4","Penetapan: Rapat pimpinan memilih dan Presiden mengesahkan.","Pimpinan; Presiden","Daftar layak","SK penghargaan","2 hari kerja"],["5","Penyerahan: Menyerahkan di forum resmi dalam bentuk sertifikat, ucapan, atau bentuk non-materi; anggaran bila ada harus masuk RAB.","PSDM; Presiden","SK","Penghargaan diserahkan","Sesuai jadwal"],["6","Dokumentasi: Mencatat dalam portofolio pengurus dan laporan kabinet.","PSDM; Sekjen","Dokumentasi","Arsip","2 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Satu siklus penghargaan diselesaikan paling lambat 11 hari kerja sejak nominasi dibuka. Hasil akhir: SK penghargaan dan penyerahan di forum resmi."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Nominasi tidak boleh untuk diri sendiri.","Penilai yang memiliki konflik kepentingan mengundurkan diri dari penilaian.","Keberatan diajukan kepada Irjen.","Penghargaan dapat dicabut bila kemudian terbukti ada pelanggaran berat pada periode penilaian."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% penerima memenuhi kriteria terverifikasi.","Setiap unit menerima minimal satu apresiasi tercatat per triwulan.","Seluruh penghargaan tercatat pada portofolio."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar nominasi dan daftar layak.","SK penghargaan.","Dokumentasi penyerahan. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri PSDM meninjau keadilan dan keterbukaan proses tiap siklus; Irjen menilai kepatuhan verifikasi."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Nominasi → Verifikasi PSDM dan Irjen → Penetapan Presiden → Penyerahan → Dokumentasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Nominasi","Nama; jabatan; alasan; bukti; pengusul; tanggal."],["Templat Sertifikat atau Ucapan","Nama; kategori; periode; pengesah."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Nominasi disertai alasan dan bukti.","☐ Ya ☐ Tidak"],["2","Skor dan kehadiran memenuhi kriteria.","☐ Ya ☐ Tidak"],["3","Tidak ada sanksi aktif pada nominee.","☐ Ya ☐ Tidak"],["4","Penghargaan disahkan Presiden.","☐ Ya ☐ Tidak"],["5","Anggaran, bila ada, sesuai RAB.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-013","g":"Keanggotaan dan SDM","t":"Penanganan Dugaan Pelanggaran Kode Etik","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[643,646],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menangani dugaan pelanggaran secara adil, objektif, berbasis bukti, dan proporsional, dengan tetap menjamin hak klarifikasi dan pembelaan pihak yang dilaporkan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk dugaan pelanggaran larangan ART Pasal 11 dan alasan pemberhentian AD Pasal 9 ayat (2) oleh anggota atau pengurus. Dikecualikan: perundungan, intimidasi, dan pelecehan (jalur perlindungan SOP-SDM- 017, dengan SOP ini untuk bagian sanksi) dan dugaan penyalahgunaan dana atau aset (SOP-RSK-07)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 9 ayat (2) (alasan pemberhentian).","ART Pasal 4 huruf b (wewenang memberhentikan pengurus internal) dan Pasal 5 ayat (7) (pemberhentian Presiden dan Wapres melalui MBLB).","ART Pasal 8 ayat (3) huruf c (Musyawarah Istimewa untuk pelanggaran berat).","ART Pasal 11 (larangan), Pasal 12 (jenis sanksi dan kewenangan), dan Pasal 13 (mekanisme pemberian sanksi).","Catatan penyusun B.2 dan B.3."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Ringan","Pelanggaran disiplin kecil, berdampak internal terbatas, pertama kali. Sanksi: teguran lisan atau tertulis."],["Sedang","Pelanggaran berulang atau berdampak terbatas pada kegiatan atau nama baik. Sanksi: teguran tertulis, peringatan keras, atau skorsing."],["Berat","Korupsi atau penyalahgunaan dana, asusila, narkoba atau miras, SARA, kekerasan, merusak nama baik kampus, tindak pidana, atau alpa 3 kali berturut-turut tanpa uzur. Sanksi: skorsing atau pemberhentian tetap."],["BAP klarifikasi","Berita acara pemeriksaan yang memuat keterangan terlapor, saksi, dan bukti."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Mengesahkan putusan sanksi."],["Inspektur Jenderal","R","Menerima laporan, memeriksa, dan menyusun rekomendasi."],["Menteri / Kabiro dan atasan","R","Menangani pelanggaran ringan."],["Forum pimpinan","R","Memutus jenis sanksi (ART Pasal 12 ayat 2)."],["Sekretaris Jenderal","R","Menerbitkan surat sanksi dan mengarsipkan."],["KAUR ORMAWA","I","Menerima laporan pelanggaran berat berdampak institusi (ART Pasal 12 ayat 7)."],["Terlapor","C","Memberi klarifikasi dan pembelaan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan tertulis disertai bukti yang dapat dipertanggungjawabkan (ART Pasal 13 ayat 4).","Kode etik dan larangan ART Pasal 11.","Rekap kehadiran, laporan, dan catatan pembinaan yang relevan."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan laporan: Menerima laporan melalui kanal tertutup disertai bukti; identitas pelapor dilindungi.","Irjen","Laporan, bukti","Laporan","Kapan saja"],["2","Registrasi: Mencatat dan memeriksa kelengkapan; laporan tanpa bukti dikembalikan untuk dilengkapi.","Irjen","Laporan","Nomor perkara","1 hari kerja"],["3","Klasifikasi: Menetapkan ringan, sedang, atau berat berdasarkan dampak (ART Pasal 12 ayat 9) dan memastikan pemeriksa bebas konflik kepentingan.","Irjen","Laporan","Klasifikasi","2 hari kerja"],["4","Penanganan ringan: Menasihati dan memberi teguran lisan atau tertulis (ART Pasal 13 ayat 1), lalu melapor ke Irjen.","Atasan; Menteri/Kabiro","Klasifikasi","Teguran","3 hari kerja"],["5","Pemeriksaan sedang atau berat: Tabayyun: memanggil terlapor, mendengar klarifikasi dan pembelaan (ART Pasal 13 ayat 9), memeriksa saksi dan bukti.","Irjen","Laporan, bukti","BAP klarifikasi","Maksimal 7 hari kerja"],["6","Rekomendasi: Menyusun rekomendasi sanksi yang proporsional.","Irjen","BAP","Rekomendasi tertulis","2 hari kerja"],["7","Putusan: Memutus jenis sanksi (ART Pasal 12 ayat 2) setelah terlapor memberi tanggapan akhir.","Forum pimpinan","Rekomendasi","Putusan","3 hari kerja"],["8","Pengesahan dan pemberitahuan: Mengesahkan dan menerbitkan surat sanksi; pemberhentian tetap dilanjutkan ke SOP-SDM-014.","Presiden; Sekjen","Putusan","Surat sanksi","2 hari kerja"],["9","Pelaporan: Pelanggaran berat berdampak institusi dilaporkan ke KAUR ORMAWA; dugaan pidana diserahkan ke kampus atau pihak berwenang.","Irjen","Putusan","Laporan","2 hari kerja"],["10","Keberatan: Terlapor mengajukan keberatan tertulis; ditinjau Wapres bersama dua pimpinan yang tidak terlibat pemeriksaan.","Terlapor; Wapres","Keberatan","Putusan keberatan","3 hari kerja pengajuan; 5 hari kerja peninjauan"],["11","Pemantauan dan penutupan: Memantau pelaksanaan sanksi dan melaporkan hasil pengawasan melalui forum resmi BEM (ART Pasal 13 ayat 6).","Irjen","Surat sanksi","Kasus ditutup","Sesuai sanksi"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Sejak registrasi sampai putusan ditargetkan paling lambat 14 hari kerja (ART Pasal 13 ayat 8: wajar dan proporsional). Hasil akhir: putusan, surat sanksi, dan arsip tertutup."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Terlapor Presiden atau Wapres: Irjen menyusun laporan dan pemberhentian ditempuh melalui MBLB (ART Pasal 5 ayat 7) dengan pemberitahuan kepada KAUR ORMAWA.","Terlapor Irjen: diperiksa Wapres bersama Sekjen.","Pemeriksa yang berkonflik kepentingan wajib mundur.","Bukti tidak cukup: kasus ditutup dengan catatan dan pembinaan (SOP-SDM-011).","Laporan yang terbukti sengaja palsu dapat diproses sebagai pelanggaran oleh pelapor."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% laporan teregistrasi paling lambat 1 hari kerja.","Minimal 90% kasus diputus paling lambat 14 hari kerja.","100% terlapor mendapat kesempatan klarifikasi.","Tidak ada kebocoran identitas pelapor."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register perkara.","BAP klarifikasi dan rekomendasi.","Putusan dan surat sanksi. Seluruh dokumen disimpan sebagai arsip tertutup pada repositori resmi BEM oleh Inspektur Jenderal dan Sekretaris Jenderal (SOP-SDM-018)."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen melaporkan jumlah, jenis, dan ketepatan waktu penanganan kasus pada forum resmi BEM tiap triwulan tanpa membuka identitas."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Laporan dan bukti → Registrasi → Klasifikasi → Tabayyun dan pemeriksaan → Rekomendasi → Putusan forum → Pengesahan Presiden → Keberatan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan","Pelapor; terlapor; kejadian; bukti; tanggal."],["BAP Klarifikasi","Pihak diperiksa; keterangan; bukti; pemeriksa; tanda tangan."],["Rekomendasi Sanksi","Klasifikasi; pasal; pertimbangan; rekomendasi."],["Templat Surat Sanksi","Jenis sanksi; dasar; kewajiban; masa berlaku; pengesah."],["Formulir Keberatan","Pengurus; putusan; alasan; permintaan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Laporan disertai bukti.","☐ Ya ☐ Tidak"],["2","Pemeriksa bebas konflik kepentingan.","☐ Ya ☐ Tidak"],["3","Terlapor telah diberi kesempatan klarifikasi dan pembelaan.","☐ Ya ☐ Tidak"],["4","Sanksi sesuai klasifikasi dan disahkan Presiden.","☐ Ya ☐ Tidak"],["5","Arsip kasus disimpan tertutup.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-014","g":"Keanggotaan dan SDM","t":"Pengunduran Diri dan Pemberhentian Pengurus","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[647,650],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Memastikan pengunduran diri dan pemberhentian pengurus berjalan tertib, sah, dan tidak mengganggu keberlangsungan tugas, dokumen, aset, dan akses organisasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk berhentinya pengurus karena tidak lagi menjadi mahasiswa aktif, masa jabatan berakhir, meninggal dunia, atau mengundurkan diri (AD Pasal 9 ayat 1), serta pemberhentian karena sanksi (AD Pasal 9 ayat 2) melalui SOP-SDM-013, termasuk alpa 3 kali berturut-turut tanpa uzur."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 9 dan Pasal 10.","ART Pasal 4 huruf b dan Pasal 5 ayat (7) dan (8).","ART Pasal 8 ayat (7) (hasil Musyawarah Istimewa disahkan Ketua STDIIS) dan Pasal 12 ayat (2).","SOP-SDM-013 (sanksi) dan SOP-SDM-015 (pengisian jabatan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Clearance","Pemeriksaan bahwa pengurus telah menyerahkan dokumen, tugas, aset, dana, dan akses."],["Berhenti dengan hormat","Berhenti karena sebab AD Pasal 9 ayat (1) dengan clearance lengkap."],["Surat keterangan pengabdian","Surat dari Sekjen yang menerangkan masa dan jabatan pengabdian."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menyetujui dan menetapkan pemberhentian pengurus."],["Sekretaris Jenderal","R","Administrasi, clearance, SK, dan pencabutan akses."],["Menteri PSDM dan atasan langsung","R","Pembicaraan awal dan serah terima tugas."],["Biro Keuangan dan penanggung jawab aset","R","Clearance dana dan inventaris."],["Inspektur Jenderal","C","Memastikan prosedur sanksi terpenuhi."],["KAUR ORMAWA dan Ketua STDIIS","I","Diberi tahu bila menyangkut Presiden atau Wapres."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Surat pengunduran diri, data akademik, atau putusan SOP-SDM-013.","Daftar tugas berjalan, dokumen, aset, dana, dan akses pengurus.","Uraian tugas jabatan."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan: Menyerahkan surat pengunduran diri bertanda tangan beserta alasan dan tanggal efektif yang diusulkan.","Pengurus","Surat","Surat pengunduran diri","Kapan saja"],["2","Pembicaraan awal: Menemui pengurus untuk memahami alasan dan menawarkan solusi (misalnya cuti sementara, SOP-SDM-011); keputusan akhir tetap pada pengurus.","Atasan; PSDM","Surat","Catatan pertemuan","3 hari kerja"],["3","Persetujuan: Menyetujui pengunduran diri; untuk Wapres disampaikan ke forum internal; untuk Presiden, Wapres menggantikan (ART Pasal 5 ayat 8) dan kampus diberi tahu.","Presiden","Catatan pertemuan","Persetujuan","3 hari kerja"],["4","Serah terima dan clearance: Menyerahkan dokumen, tugas berjalan, aset, pertanggungjawaban dana, dan akses digital; penerima dan atasan menandatangani, Sekjen memverifikasi.","Pengurus; atasan; Sekjen","Daftar serah terima","Berita acara serah terima","7 hari kerja"],["5","Penerbitan SK: Menerbitkan SK pemberhentian dengan hormat dan surat keterangan pengabdian bila clearance lengkap.","Sekjen","Berita acara","SK; surat keterangan","2 hari kerja"],["6","Pencabutan akses: Mencabut akses grup, folder, dan akun resmi.","Sekjen","SK","Akses dicabut","1 hari kerja setelah SK"],["7","Pengisian jabatan: Dilanjutkan ke SOP- SDM-015.","Presiden; Sekjen","SK","Jabatan terisi","Sesuai SOP- SDM-015"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Dari persetujuan hingga akses dicabut ditargetkan paling lambat 13 hari kerja. Sebab lain: tidak lagi mahasiswa aktif, SK terbit paling lambat 3 hari kerja setelah verifikasi akademik; meninggal dunia, serah terima dilakukan atasan dan Sekjen bersama keluarga bila diperlukan. Pemberhentian karena sanksi mengikuti putusan SOP- SDM-013; pemberhentian Presiden dan Wapres hanya melalui MBLB dan hasilnya disahkan Ketua STDIIS (asumsi, selaras ART Pasal 8 ayat 7)."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengurus menolak serah terima: Sekjen dan Irjen melapor ke Presiden dan surat keterangan pengabdian ditahan.","Dugaan penyalahgunaan dana atau aset diproses melalui SOP-RSK-07 sebelum clearance dinyatakan selesai.","Pengunduran diri tidak menghentikan pemeriksaan SOP-SDM-013 yang sudah berjalan.","Hak keberatan pada SOP-SDM-013 tetap berlaku sebelum SK pemberhentian karena sanksi dilaksanakan."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["SK terbit paling lambat 3 hari kerja setelah persetujuan.","Clearance selesai paling lambat 7 hari kerja.","100% akses dicabut paling lambat 1 hari kerja setelah SK.","Tidak ada aset atau dokumen hilang tanpa catatan."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Surat pengunduran diri dan catatan pertemuan.","Berita acara serah terima dan clearance.","SK pemberhentian dan surat keterangan pengabdian.","Log pencabutan akses. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan clearance setiap kasus; Irjen menilai kepatuhan prosedur pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Surat atau putusan → Pembicaraan awal → Persetujuan Presiden → Serah terima dan clearance → SK → Pencabutan akses → Pengisian jabatan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Surat Pengunduran Diri","Nama; jabatan; alasan; tanggal efektif; tanda tangan."],["Berita Acara Serah Terima dan Clearance","Dokumen; tugas; aset; dana; akses; penerima; tanda tangan."],["Templat SK Pemberhentian","Nama; jabatan; dasar; tanggal efektif; pengesah."],["Surat Keterangan Pengabdian","Nama; jabatan; masa jabatan; pengesah."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Alasan dan dasar pemberhentian jelas.","☐ Ya ☐ Tidak"],["2","Serah terima dokumen, aset, dana, dan akses lengkap.","☐ Ya ☐ Tidak"],["3","SK diterbitkan dan register diperbarui.","☐ Ya ☐ Tidak"],["4","Akses dicabut sesuai batas waktu.","☐ Ya ☐ Tidak"],["5","Pengisian jabatan telah diproses.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-015","g":"Keanggotaan dan SDM","t":"Pergantian atau Pengisian Jabatan Kosong","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[651,653],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Memastikan jabatan yang kosong terisi dengan cepat, sah, dan memenuhi syarat tanpa menghentikan pekerjaan organisasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk kekosongan jabatan akibat SOP-SDM-014 atau halangan tetap (ART Pasal 8 ayat 3 huruf a). Pengganti menjabat sampai akhir periode dan masa itu dihitung satu periode. Susunan minimal (Presiden, Wapres, Sekjen; AD Pasal 7) tidak boleh kosong lebih dari 14 hari kerja."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 7, Pasal 10, dan Pasal 11 ayat (2) huruf b dan c.","ART Pasal 4 huruf b dan Pasal 5 ayat (3) sampai (8).","ART Pasal 6 (syarat umum kepengurusan) dan Pasal 8 (Musyawarah Istimewa).","Catatan penyusun B.1."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pelaksana tugas (Plt)","Pengurus yang ditunjuk sementara agar pekerjaan tidak terhenti; tidak mengambil keputusan strategis atau komitmen dana baru tanpa persetujuan Presiden."],["Daftar cadangan","Daftar pelamar lulus seleksi yang belum ditempatkan, berlaku paling lama satu semester."],["Aturan pengganti","Presiden: digantikan Wapres melalui musyawarah internal (ART Pasal 5 ayat 8). Wapres: calon dari Presiden, ditetapkan musyawarah internal pimpinan dan jajaran Menteri/Kabiro, lalu diberitahukan ke Ketua STDIIS (usulan). Sekjen, Irjen, Menteri, Kabiro: prerogatif Presiden melalui forum musyawarah internal. Staf: seleksi terbuka atau daftar cadangan."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menunjuk Plt dan menetapkan pengganti."],["Sekretaris Jenderal","R","Pencatatan kekosongan, SK, dan berita acara."],["Menteri PSDM","R","Verifikasi syarat dan seleksi staf."],["Inspektur Jenderal","C","Memeriksa rekam jejak calon."],["Menteri / Kabiro","C","Menyampaikan kebutuhan unit."],["KAUR ORMAWA dan Ketua STDIIS","I","Diberi tahu bila jabatan Presiden atau Wapres terisi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Lembar kekosongan dari SOP-SDM-014.","Syarat ART Pasal 6 dan AD Pasal 8 ayat (5) sampai (7).","Daftar cadangan dan uraian tugas jabatan."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pencatatan kekosongan: Mencatat jabatan, tanggal, tugas berjalan, dan risiko.","Sekjen","SOP-SDM-014","Lembar kekosongan","1 hari kerja"],["2","Penunjukan Plt: Menunjuk pelaksana tugas agar pekerjaan tidak terhenti.","Presiden","Lembar kekosongan","SK Plt","Maksimal 2 hari kerja"],["3","Penyusunan calon: Menyiapkan sedikitnya satu calon sesuai aturan pengganti.","Pimpinan","Aturan pengganti","Daftar calon","5 hari kerja"],["4","Verifikasi syarat: Memeriksa ART Pasal 6, AD Pasal 8 ayat (5) sampai (7), dan surat komitmen; Irjen memeriksa bebas sanksi aktif.","PSDM; Sekjen; Irjen","Berkas calon","Hasil verifikasi","2 hari kerja"],["5","Musyawarah penetapan: Forum musyawarah internal memutus dan mencatat dalam berita acara.","Forum internal","Hasil verifikasi","Berita acara","2 hari kerja"],["6","Pengesahan: Menetapkan SK; kampus diberi tahu bila jabatan Presiden atau Wapres.","Presiden; Sekjen","Berita acara","SK pengganti","2 hari kerja"],["7","Pelantikan dan serah terima: Melantik sesuai SOP-SDM-003 dan menerima serah terima dari Plt atau pendahulu.","Sekjen; Presiden","SK","Pejabat definitif","3 hari kerja"],["8","Penyesuaian dokumen: Menyesuaikan uraian tugas dan target kerja.","PSDM","Pelantikan","Dokumen diperbarui","5 hari kerja"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Pengisian definitif ditargetkan paling lambat 14 hari kerja; naiknya Wapres menjadi Presiden paling lambat 3 hari kerja setelah kesepakatan musyawarah. Hasil akhir: SK pengganti, pelantikan, dan serah terima."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Tidak ada calon memenuhi syarat: Plt diperpanjang satu kali (14 hari kerja) sambil membuka seleksi terbuka (SOP-SDM-001).","Presiden dan Wapres sama-sama kosong atau halangan tetap: Musyawarah Istimewa diselenggarakan (ART Pasal 8) dan kampus diberi tahu segera.","Perbedaan tafsir aturan pengganti dikonsultasikan kepada KAUR ORMAWA atau Pembina."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["Plt ditunjuk paling lambat 2 hari kerja.","Jabatan definitif terisi paling lambat 14 hari kerja.","Tidak ada jabatan inti kosong lebih dari 14 hari kerja."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar kekosongan dan SK Plt.","Berita acara penetapan.","SK pengganti dan berita acara pelantikan. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal melaporkan durasi kekosongan jabatan pada evaluasi tengah periode; Irjen menilai kepatuhan syarat dan prosedur."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Catat kekosongan → Plt → Calon → Verifikasi syarat → Musyawarah → SK Presiden → Pelantikan dan serah terima → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Kekosongan Jabatan","Jabatan; tanggal; sebab; tugas berjalan; risiko; Plt."],["Templat SK Plt","Nama; jabatan; masa; batas wewenang; pengesah."],["Berita Acara Penetapan","Calon; hasil verifikasi; keputusan; peserta; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Plt ditunjuk tepat waktu.","☐ Ya ☐ Tidak"],["2","Calon memenuhi ART Pasal 6 dan AD Pasal 8.","☐ Ya ☐ Tidak"],["3","Keputusan lewat musyawarah dan tercatat.","☐ Ya ☐ Tidak"],["4","Pelantikan dan serah terima dilakukan.","☐ Ya ☐ Tidak"],["5","Uraian tugas dan target diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-016","g":"Keanggotaan dan SDM","t":"Pengembangan Kapasitas dan Pelatihan","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[654,656],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Meningkatkan kompetensi pengurus secara terencana sesuai kebutuhan unit dan nilai Al-Qur'an dan As- Sunnah."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pelatihan internal (kepemimpinan, keorganisasian, teknis administrasi, keuangan, desain), pembinaan keilmuan dan akhlak, mentoring, dan pelatihan eksternal."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 3 dan Pasal 5 ayat (1) dan (4).","ART Pasal 2 huruf d dan j (kegiatan ilmiah dan izin kegiatan di luar kampus).","SOP-SDM-002 (penempatan) dan SOP-SDM-010 (evaluasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Analisis kebutuhan","Pemetaan kesenjangan kompetensi pengurus terhadap kebutuhan tugas."],["Mentoring","Pendampingan oleh pengurus senior atau pembina kepada pengurus lain."],["Portofolio pengurus","Catatan pelatihan dan capaian pengembangan setiap pengurus."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menyetujui rencana dan anggaran."],["Menteri PSDM","R","Perencanaan, pelaksanaan, dan evaluasi."],["Menteri / Kabiro","C","Menyampaikan kebutuhan unit."],["Sekretaris Jenderal","C","Memasukkan ke kalender kegiatan."],["Biro Keuangan","C","Memeriksa anggaran."],["KAUR ORMAWA","C","Memberi izin kegiatan eksternal (ART Pasal 2 huruf j)."],["Peserta","R","Mengikuti dan menerapkan hasil."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Hasil evaluasi kinerja dan pemetaan kompetensi.","Usulan Menteri/Kabiro.","Anggaran kegiatan dalam RAB."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Analisis kebutuhan: Memetakan kesenjangan kompetensi dari penempatan, evaluasi, dan usulan unit.","PSDM","SOP-SDM-002, 010","Daftar kebutuhan","5 hari kerja"],["2","Rencana pengembangan: Menyusun rencana tahunan: topik, sasaran, pemateri, waktu, anggaran; dimasukkan ke kalender (SOP-PRO-02).","PSDM","Daftar kebutuhan","Rencana tahunan","5 hari kerja"],["3","Persetujuan: Menyetujui rencana; anggaran mengikuti SOP keuangan.","Presiden","Rencana","Rencana sah","3 hari kerja"],["4","Pelaksanaan: Menyelenggarakan sebagai kegiatan terencana; kehadiran dicatat (SOP-SDM-006); pemateri eksternal diajukan lewat SOP-PRO-10.","PSDM","Rencana sah","Pelatihan terlaksana","Sesuai jadwal"],["5","Evaluasi: Tes sebelum dan sesudah, survei kepuasan, dan penilaian atasan atas penerapan.","PSDM; atasan","Hasil pelatihan","Laporan evaluasi","7 hari kerja"],["6","Tindak lanjut: Menyusun rencana penerapan dan mentoring; mencatat di portofolio.","PSDM","Laporan evaluasi","Portofolio","7 hari kerja"],["7","Pelaporan: Memasukkan ke laporan bulanan dan evaluasi.","PSDM; Sekjen","Laporan evaluasi","Laporan","Bulanan"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Rencana tahunan disahkan paling lambat 15 hari kerja setelah analisis kebutuhan dimulai. Hasil akhir: pelatihan terlaksana, laporan evaluasi, dan portofolio pengurus diperbarui."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Peserta berhalangan mendapat sesi atau materi susulan.","Materi dan pemateri harus sejalan dengan nilai Al-Qur'an dan As-Sunnah serta aturan kampus.","Pelatihan eksternal memerlukan izin kampus sebelum diikuti."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 80% pengurus mengikuti minimal dua pelatihan per periode.","Kenaikan nilai tes minimal 20% (usulan).","Minimal 70% peserta menerapkan hasil pada penilaian atasan."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar kebutuhan dan rencana tahunan.","Daftar hadir dan laporan evaluasi.","Portofolio pengurus. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri PSDM melaporkan efektivitas pelatihan pada evaluasi tengah dan akhir periode; Irjen menilai penggunaan anggaran pelatihan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Analisis kebutuhan → Rencana tahunan → Persetujuan Presiden → Pelaksanaan → Evaluasi → Tindak lanjut → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Analisis Kebutuhan","Unit; kompetensi; kesenjangan; prioritas."],["Rencana Tahunan Pengembangan","Topik; sasaran; pemateri; waktu; anggaran."],["Formulir Evaluasi Pelatihan","Nilai sebelum; nilai sesudah; kepuasan; masukan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Rencana berbasis analisis kebutuhan.","☐ Ya ☐ Tidak"],["2","Rencana dan anggaran disetujui Presiden.","☐ Ya ☐ Tidak"],["3","Kehadiran peserta dicatat.","☐ Ya ☐ Tidak"],["4","Evaluasi pra dan pasca dilakukan.","☐ Ya ☐ Tidak"],["5","Hasil dicatat pada portofolio.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-017","g":"Keanggotaan dan SDM","t":"Perlindungan dari Perundungan, Intimidasi, dan Pelecehan","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[657,660],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Melindungi pengurus dan anggota dari perundungan, intimidasi, dan pelecehan, menyediakan jalur lapor yang aman, serta menjamin penanganan sesuai ketentuan ART dan kebijakan kampus."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk dugaan perundungan (fisik, verbal, sosial, daring), intimidasi, dan pelecehan (termasuk seksual) antarpengurus atau oleh pengurus terhadap mahasiswa lain dalam konteks kegiatan BEM, luring maupun daring. BEM tidak menyelesaikan sendiri kasus kekerasan seksual atau dugaan pidana; kasus tersebut wajib diteruskan ke pihak kampus atau yang berwenang."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 3 dan Pasal 5.","ART Pasal 11 huruf c dan h (larangan kekerasan, asusila, pelecehan, dan perundungan).","ART Pasal 12 dan 13 (sanksi dan mekanisme).","Kebijakan kampus dan peraturan nasional tentang pencegahan dan penanganan kekerasan di perguruan tinggi.","SOP-SDM-013 dan SOP-SDM-018."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Perlindungan sementara","Tindakan segera untuk menjaga keselamatan pelapor atau korban selama kasus diproses."],["Petugas penerima laporan","Dua pengurus ditunjuk Presiden, sebaiknya laki-laki dan perempuan, agar pelapor dapat memilih."],["Pembalasan","Tindakan merugikan pelapor atau saksi karena laporannya; termasuk pelanggaran berat tersendiri."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menunjuk petugas dan mengesahkan tindakan serta sanksi."],["Inspektur Jenderal","R","Pemilik proses, asesmen, rujukan, dan pemantauan."],["Petugas penerima laporan","R","Menerima laporan dengan menjaga kerahasiaan."],["Wakil Presiden","R","Menetapkan perlindungan sementara."],["Menteri PSDM","C","Pencegahan dan sosialisasi."],["KAUR ORMAWA dan layanan kampus","C","Rujukan, pendampingan, dan penanganan kasus berat."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Laporan dari korban, saksi, atau pihak lain.","Bukti (pesan, tangkapan layar, saksi) yang dijaga utuh.","Kontak layanan kampus dan pihak berwenang."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pencegahan: Mensosialisasikan larangan, adab interaksi, dan saluran lapor saat orientasi dan berkala; mengatur kehadiran dan pendampingan pada kegiatan malam dan daring.","PSDM; Irjen","Kode etik","Daftar hadir sosialisasi","Berkala"],["2","Penerimaan laporan: Mendengarkan tanpa menghakimi atau menekan, melindungi identitas, dan mencatat.","Petugas penerima laporan","Laporan","Catatan laporan","Segera"],["3","Asesmen risiko: Menilai keselamatan segera, tingkat bahaya, dan kebutuhan pendampingan.","Petugas; Irjen","Catatan laporan","Lembar asesmen","24 jam"],["4","Perlindungan sementara: Memisahkan interaksi (jadwal, tempat, unit), menghentikan tugas bersama, dan mengamankan komunikasi; korban tidak dipersalahkan.","Wapres; Presiden","Asesmen","Tindakan sementara","48 jam"],["5","Rujukan: Meneruskan pelecehan seksual, kekerasan fisik, ancaman, atau dugaan pidana ke KAUR ORMAWA, layanan kampus, atau pihak berwenang; BEM mendampingi korban.","Irjen","Asesmen","Surat rujukan","2 hari kerja"],["6","Pemeriksaan: Untuk kasus yang ditangani BEM, memakai SOP-SDM- 013 dengan penguatan: korban boleh didampingi, tidak dihadapkan langsung dengan terlapor, pertanyaan tidak mengorek berlebihan, bukti digital diamankan.","Irjen","Laporan, bukti","BAP","Sesuai SOP- SDM-013"],["7","Keputusan dan sanksi: Mengikuti SOP- SDM-013 tahap rekomendasi sampai pengesahan; perundungan dan pelecehan diklasifikasikan sedang sampai berat.","Forum pimpinan; Presiden","Rekomendasi","Putusan","Sesuai SOP- SDM-013"],["8","Pemulihan dan pemantauan: Memantau keselamatan, memastikan tidak ada pembalasan, dan menilai kebutuhan pendampingan lanjutan.","Irjen; PSDM","Putusan","Laporan pemantauan","30 hari"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Respons laporan paling lambat 24 jam, perlindungan sementara paling lambat 48 jam, dan pemantauan 30 hari setelah putusan. Hasil akhir: perlindungan terlaksana, rujukan atau putusan, dan laporan pemantauan."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pelapor mencabut laporan: Irjen menilai kemungkinan adanya tekanan; kasus berisiko berat tetap diteruskan.","Terlapor adalah pimpinan: laporan langsung ke Irjen atau KAUR ORMAWA tanpa melalui terlapor.","Pembalasan terhadap pelapor adalah pelanggaran berat tersendiri.","Laporan yang sengaja palsu diproses melalui SOP-SDM-013."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% laporan direspons paling lambat 24 jam.","100% tindakan perlindungan sementara paling lambat 48 jam.","Tidak ada kebocoran identitas pelapor.","Pemantauan 30 hari terdokumentasi pada semua kasus."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Catatan laporan dan lembar asesmen.","Surat rujukan.","Laporan pemantauan. Seluruh dokumen disimpan sebagai arsip tertutup oleh Inspektur Jenderal (SOP-SDM-018)."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Irjen melaporkan statistik agregat dan efektivitas perlindungan pada forum resmi BEM tiap triwulan tanpa membuka identitas."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Laporan → Asesmen risiko 24 jam → Perlindungan sementara → Rujukan atau pemeriksaan → Putusan → Pemulihan dan pemantauan 30 hari → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan Tertutup","Pelapor (opsional); kejadian; waktu; bukti; kebutuhan."],["Lembar Asesmen Risiko","Tingkat bahaya; keselamatan; tindakan sementara; rujukan."],["Daftar Kontak Rujukan Kampus","Unit layanan; kontak; jam layanan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Laporan diterima petugas yang dipilih pelapor.","☐ Ya ☐ Tidak"],["2","Asesmen dilakukan dalam 24 jam.","☐ Ya ☐ Tidak"],["3","Perlindungan sementara diterapkan.","☐ Ya ☐ Tidak"],["4","Kasus berat atau pidana telah dirujuk.","☐ Ya ☐ Tidak"],["5","Pemantauan 30 hari dilakukan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SDM-018","g":"Keanggotaan dan SDM","t":"Kerahasiaan Data dan Informasi Pribadi Anggota","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[661,664],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Melindungi data pribadi dan informasi sensitif pengurus serta pelamar sebagai bentuk amanah, dan mencegah penyalahgunaan serta kebocoran."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk data pelamar dan pengurus, hasil seleksi, transkrip dan IPK, data kesehatan atau alasan sakit, hasil evaluasi, catatan pembinaan, serta laporan pelanggaran dan perundungan, baik dokumen fisik maupun digital, bagi seluruh pengurus."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 5 ayat (4) (amanah dalam berorganisasi).","ART Pasal 3 huruf e dan h (pengelolaan amanah dan kepatuhan pada kebijakan kampus).","Undang-Undang Nomor 27 Tahun 2022 tentang Pelindungan Data Pribadi.","SOP-ADM-15, SOP-ADM-20, dan SOP-RSK-08 sampai 10."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Data umum","Nama, jabatan, program studi, dan kontak kerja; dapat diakses seluruh pengurus."],["Data terbatas","Nomor HP pribadi, alamat, IPK, dan hasil evaluasi; hanya atasan langsung, PSDM, dan Sekjen."],["Data rahasia","Data kesehatan, catatan pembinaan, laporan pelanggaran, identitas pelapor, dan rincian hasil seleksi; hanya Irjen, Sekjen, Presiden, dan pihak berwenang sesuai keperluan."],["Register data","Daftar jenis data, tujuan, pemilik, tingkat, lokasi, dan masa simpan."]]}}]},{"p":"B","n":5,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Mengelola register data dan kebijakan akses."],["Biro Kesekretariatan","R","Penyimpanan dan pengendalian akses."],["Menteri PSDM","R","Pengelolaan data SDM."],["Inspektur Jenderal","R","Pengelolaan data kasus dan audit kepatuhan."],["Presiden","C","Memutuskan pengecualian akses."],["Seluruh pengurus","R","Menjaga data yang dipegang."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":6,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar data yang dikumpulkan dari seluruh SOP-SDM.","Formulir persetujuan dan pakta kerahasiaan.","Daftar akun dan folder resmi."]}]},{"p":"B","n":7,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pendataan dan klasifikasi: Menyusun register data dan menetapkan tingkatnya.","Sekjen","Daftar data","Register data","7 hari kerja"],["2","Persetujuan: Mengisi persetujuan pengumpulan dan penggunaan data; hanya data yang diperlukan yang dikumpulkan.","Pelamar; pengurus","Formulir","Persetujuan","Saat pendaftaran"],["3","Pakta kerahasiaan: Menandatangani pakta bagi pemegang data saat pelantikan (SOP-SDM-003).","Pengurus","Pakta","Pakta","Saat pelantikan"],["4","Penyimpanan dan akses: Menyimpan di folder resmi dengan hak akses sesuai tingkat, akun resmi, verifikasi dua langkah bila tersedia; dokumen fisik di lemari terkunci.","Kesekretariatan","Register","Akses terkendali","Berkelanjutan"],["5","Penggunaan dan pembagian: Menggunakan sesuai tujuan; dilarang membagikan di grup umum atau media sosial; pembagian data terbatas atau rahasia memerlukan izin Sekjen dan dicatat.","Seluruh pengurus; Sekjen","Register","Log akses","Setiap penggunaan"],["6","Permintaan akses atau koreksi: Pengurus dapat meminta salinan atau perbaikan datanya sendiri.","Pengurus; Sekjen","Permintaan","Jawaban tertulis","5 hari kerja"],["7","Retensi dan pemusnahan: Menghapus data pelamar tidak lolos paling lama 1 semester; mengarsipkan data pengurus sesuai SOP-ADM-13 dengan akses dibatasi; mencatat pemusnahan.","Sekjen; Kesekretariatan","Register","Berita acara pemusnahan","Sesuai register"],["8","Insiden kebocoran: Melaporkan dugaan kebocoran ke Sekjen dan Irjen, menanganinya lewat SOP-RSK-09, dan memberi tahu pihak terdampak.","Pengurus; Sekjen; Irjen","Temuan","Laporan insiden","24 jam"],["9","Audit: Memeriksa kepatuhan akses dan penyimpanan.","Irjen","Log akses","Laporan audit","Tiap semester"]]}}]},{"p":"B","n":8,"t":"Standar waktu dan hasil","c":[{"p":"Register data disusun paling lambat 7 hari kerja setelah pelantikan; permintaan akses dijawab paling lambat 5 hari kerja; insiden dilaporkan paling lambat 24 jam. Hasil akhir: register, log akses, dan laporan audit semester."},{"note":"Catatan: angka waktu, bobot, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":9,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Permintaan data oleh kampus atau pihak berwenang memerlukan izin Presiden dan Sekjen, dicatat, dan dibatasi seperlunya.","Dalam keadaan darurat keselamatan, data dibuka seminimal mungkin dan dilaporkan kemudian.","Pelanggaran kerahasiaan diproses melalui SOP-SDM-013 dan tergolong berat bila disengaja.","Laporan yang dipublikasikan untuk transparansi tetap menyamarkan data pribadi."]}]},{"p":"B","n":10,"t":"Indikator keberhasilan","c":[{"ul":["100% pemegang data menandatangani pakta.","Tidak ada insiden kebocoran.","100% permintaan akses dijawab paling lambat 5 hari kerja.","Audit semester terlaksana."]}]},{"p":"B","n":11,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register data dan formulir persetujuan.","Pakta kerahasiaan dan log akses.","Berita acara pemusnahan dan laporan audit. Seluruh dokumen disimpan pada repositori resmi BEM (folder SDM) oleh Sekretaris Jenderal. Folder data terbatas dan rahasia hanya dapat diakses sesuai tingkat pada register."]}]},{"p":"B","n":12,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal meninjau register tiap semester; Irjen mengaudit kepatuhan akses dan penyimpanan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Klasifikasi data → Persetujuan → Pakta → Penyimpanan dan akses → Penggunaan terbatas → Retensi dan pemusnahan → Audit → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Register Data","Jenis data; tujuan; pemilik; tingkat; lokasi; masa simpan."],["Formulir Persetujuan Data","Data; tujuan; penggunaan; hak; tanda tangan."],["Pakta Kerahasiaan","Nama; jabatan; kewajiban; sanksi; tanda tangan."],["Log Akses","Tanggal; pengakses; data; tujuan; izin."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh data telah diklasifikasi pada register.","☐ Ya ☐ Tidak"],["2","Pemegang data telah menandatangani pakta.","☐ Ya ☐ Tidak"],["3","Akses sesuai tingkat data.","☐ Ya ☐ Tidak"],["4","Pembagian data tercatat pada log akses.","☐ Ya ☐ Tidak"],["5","Audit semester dilaksanakan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-001","g":"Hubungan Eksternal dan Kemitraan","t":"Penerimaan Undangan dari Pihak Eksternal","o":"Menteri Hubungan Eksternal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Hubungan Eksternal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[669,673],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penerimaan, pencatatan, penilaian, pengambilan keputusan, dan penjawaban undangan dari pihak eksternal, sehingga setiap undangan ditanggapi tepat waktu, dinilai kesesuaiannya dengan AD/ART dan peraturan kampus, serta tidak ada undangan yang diterima atau ditolak tanpa keputusan yang sah."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh undangan (surat, email, pesan digital, atau lisan yang dikonfirmasi tertulis) yang ditujukan kepada BEM atau pengurus dalam kapasitas organisasi, seperti rapat, seminar, pelatihan, kunjungan, dan forum antar-BEM. SOP ini tidak mengatur penunjukan delegasi (lihat SOP-HKE-002), pemberian mandat (SOP-HKE-011), pengelolaan surat masuk secara umum (SOP-ADM-001), maupun undangan pribadi yang tidak membawa nama BEM."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 3 ayat (1) sampai (3) (landasan, asas, dan sifat independen BEM).","ART Pasal 2 huruf d, e, dan j (hak menyelenggarakan kegiatan, bekerja sama dengan pihak eksternal dengan persetujuan Ketua STDIIS, dan mengikuti kegiatan organisasi kemahasiswaan tingkat regional, nasional, atau internasional dengan seizin kampus).","ART Pasal 4 huruf e (mewakili mahasiswa dalam forum resmi internal dan eksternal sebagai pimpinan tertinggi eksekutif mahasiswa).","ART Bab III (Tugas BEM) huruf d (membangun koordinasi dan kerja sama dengan ORMAWA dan pihak eksternal perguruan tinggi).","ART Pasal 11 huruf a, d, e, dan g (larangan SARA, paham yang bertentangan dengan Al-Qur'an dan As-Sunnah, mengatasnamakan BEM dalam politik praktis tanpa izin kampus, dan mencemarkan nama baik organisasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pihak eksternal","Pihak di luar kepengurusan BEM, yaitu pihak kampus, ORMAWA lain (BPM, HIMA, UKM, dan ORMAWA atau BEM perguruan tinggi lain), instansi pemerintah, lembaga swasta, komunitas, dan perorangan."],["Undangan eksternal","Permintaan resmi dari pihak eksternal agar BEM atau pengurusnya hadir atau terlibat dalam suatu kegiatan."],["Register Undangan","Buku atau lembar kerja digital pencatatan seluruh undangan beserta kategori, keputusan, dan tindak lanjutnya."],["Penilaian kelayakan","Pemeriksaan manfaat, kesesuaian program, jadwal, biaya, dan risiko suatu undangan sebelum diputuskan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Seluruh undangan dicatat pada Register Undangan oleh Biro Kesekretariatan paling lambat 1 hari kerja setelah diterima, termasuk undangan yang masuk melalui pesan pribadi pengurus.","Pengurus yang menerima undangan langsung wajib meneruskannya kepada Biro Kesekretariatan dan tidak memberi jawaban kehadiran sebelum ada keputusan.","Kategori 1 (rutin): undangan dari pihak kampus atau ORMAWA STDIIS tanpa komitmen biaya; diputuskan Wakil Presiden.","Kategori 2 (kegiatan luar kampus): undangan dari instansi, lembaga, atau ORMAWA/BEM perguruan tinggi lain; diputuskan Presiden dan wajib mendapat izin kampus bila berupa kegiatan organisasi kemahasiswaan tingkat regional, nasional, atau internasional (ART Pasal 2 huruf j).","Kategori 3 (sensitif): undangan bernuansa politik praktis atau partai politik, berbayar atau berkomitmen dana, memuat permintaan kerja sama, atau meminta pernyataan atas nama BEM; diputuskan Presiden dengan izin atau persetujuan kampus, dan unsur kerja samanya diteruskan ke SOP-HKE-005.","Undangan yang mengandung unsur yang dilarang ART Pasal 11 (SARA, paham yang bertentangan dengan Al-Qur'an dan As-Sunnah, atau kegiatan yang dilarang syariat) ditolak dan dicatat alasannya.","Jawaban atas undangan wajib berupa surat balasan resmi yang disetujui pejabat yang berwenang, bukan jawaban lisan atau pesan pribadi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Hubungan Eksternal","A","Bertanggung jawab atas penilaian kelayakan, usulan keputusan, dan ketepatan balasan setiap undangan."],["Kepala Biro Kesekretariatan","R","Mencatat undangan, memeriksa keaslian pengirim, menyusun dan mengirim surat balasan, serta mengarsipkan."],["Wakil Presiden","R","Memutuskan undangan Kategori 1."],["Presiden","R","Memutuskan undangan Kategori 2 dan 3 melalui musyawarah pimpinan (SOP- GOV-002)."],["Inspektur Jenderal","C","Menelaah kesesuaian dengan AD/ART bila undangan Kategori 3 atau ada indikasi pertentangan."],["KAUR ORMAWA / Pembina","C","Memberi izin atau pertimbangan bila diperlukan."],["Pengundang","I","Menerima jawaban resmi BEM."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Surat atau pesan undangan yang memuat pengundang, nama acara, waktu, tempat, tujuan, dan pembiayaan.","Kalender organisasi dan jadwal kegiatan BEM.","Daftar larangan pada ART Pasal 11..","Hasil Rapat Kerja untuk menilai kesesuaian dengan program kerja."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan dan pencatatan: Menerima undangan melalui kanal resmi, memberi nomor register, dan mencatat pada Register Undangan.","Kepala Biro Kesekretariatan","Undangan","Entri Register Undangan","1 hari kerja"],["2","Verifikasi pengirim: Memeriksa keaslian pengundang, tujuan acara, pembiayaan, dan ada tidaknya muatan yang dilarang ART Pasal 11.","Menteri Hubungan Eksternal","Undangan, daftar larangan","Catatan verifikasi","1 hari kerja"],["3","Penilaian dan kategori: Mengisi Formulir Penilaian Undangan: manfaat, kesesuaian program kerja, bentrokan jadwal, biaya, risiko, dan kategori undangan.","Menteri Hubungan Eksternal","Catatan verifikasi, kalender","Formulir penilaian dan rekomendasi","2 hari kerja"],["4","Pemeriksaan keselarasan: Memeriksa undangan Kategori 3 terhadap AD/ART dan peraturan kampus; memberi catatan tertulis bila ada pertentangan.","Irjen","Formulir penilaian","Catatan pemeriksaan","1 hari kerja"],["5","Keputusan: Memutuskan menerima, menolak, atau menunda. Kategori 1 oleh Wakil Presiden; Kategori 2 dan 3 oleh Presiden melalui musyawarah pimpinan (SOP-GOV-002), atau SOP- GOV-012 bila mendesak.","Wapres / Presiden","Formulir penilaian, catatan Irjen","Keputusan tercatat","2 hari kerja"],["6","Izin kampus: Mengajukan permohonan izin atau persetujuan kepada KAUR ORMAWA/Ketua STDIIS bila undangan memerlukannya.","Kepala Biro Kesekretariatan","Keputusan, surat permohonan","Surat izin kampus","3 hari kerja; diajukan paling lambat 5 hari kerja sebelum acara"],["7","Balasan resmi: Menyusun dan mengirim surat balasan (menerima, menolak dengan santun, atau meminta penyesuaian) sesuai SOP-ADM-002.","Kepala Biro Kesekretariatan","Keputusan, izin kampus","Surat balasan terkirim","2 hari kerja setelah keputusan"],["8","Tindak lanjut dan arsip: Bila diterima, meneruskan ke SOP- HKE-002 dan memasukkan ke kalender organisasi; melengkapi Register Undangan dan mengarsipkan seluruh dokumen.","Menteri Hubungan Eksternal dan Sekjen","Surat balasan, Register","Register lengkap, arsip","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari penerimaan hingga balasan resmi paling lambat 7 hari kerja, atau paling lambat 3 hari kerja sebelum acara bila undangan diterima kurang dari 7 hari sebelum acara. Hasil akhir: keputusan tercatat dan surat balasan resmi."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Waktu tidak mencukupi untuk alur biasa: gunakan SOP-GOV-012 (keputusan mendesak) dan catat sebagai keputusan mendesak.","Perbedaan penilaian kategori: diputuskan Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Undangan yang memuat permintaan kerja sama atau dana: dialihkan ke SOP-HKE-005 atau SOP- HKE-007.","Undangan bernuansa politik praktis tanpa izin kampus: tidak boleh diterima atas nama BEM."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% undangan tercatat pada Register Undangan dalam 1 hari kerja.","100% undangan dibalas resmi sebelum batas waktu.","Tidak ada kehadiran atas nama BEM tanpa keputusan yang sah.","Tidak ada temuan Irjen terkait undangan Kategori 3."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Undangan Eksternal.","Formulir Penilaian Undangan dan catatan pemeriksaan Irjen.","Keputusan tercatat dan surat izin kampus (bila ada).","Surat balasan resmi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan Register Undangan setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima dan catat → Verifikasi pengirim → Penilaian dan kategori → Keputusan → Izin kampus (bila perlu) → Balasan resmi → Tindak lanjut dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Register Undangan Eksternal","Nomor register; tanggal terima; pengundang; nama acara; waktu dan tempat; kategori; keputusan; delegasi; tanggal balasan; keterangan."],["Formulir Penilaian Undangan","Pengundang; tujuan acara; manfaat; kesesuaian program kerja; jadwal; biaya; risiko; kategori; rekomendasi; penilai; tanggal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Undangan tercatat pada Register dalam 1 hari kerja.","☐ Ya ☐ Tidak"],["2","Pengirim dan tujuan acara telah diverifikasi.","☐ Ya ☐ Tidak"],["3","Tidak ada muatan yang dilarang ART Pasal 11.","☐ Ya ☐ Tidak"],["4","Izin kampus diperoleh bila kegiatan regional, nasional, internasional, atau bernuansa politik.","☐ Ya ☐ Tidak"],["5","Keputusan tercatat sebelum surat balasan dikirim.","☐ Ya ☐ Tidak"],["6","Surat balasan terkirim dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Hubungan Eksternal; Menteri Harmonisasi Kampus; Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-002","g":"Hubungan Eksternal dan Kemitraan","t":"Pengiriman Delegasi Organisasi","o":"Menteri Hubungan Eksternal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Hubungan Eksternal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[674,677],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penunjukan, pembekalan, pengiriman, dan pertanggungjawaban delegasi yang mewakili BEM pada kegiatan eksternal, sehingga delegasi kompeten, membawa penugasan yang sah, menjaga adab dan nama baik organisasi, serta hasilnya kembali menjadi manfaat bagi BEM."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk penunjukan satu atau lebih pengurus untuk mewakili BEM pada kegiatan eksternal yang telah diputuskan diterima (SOP-HKE-001) atau diinisiasi BEM. SOP ini tidak mengatur isi dan batas mandat (lihat SOP-HKE-011) maupun pelaporan hasil (SOP-HKE-012)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf e dan f (mewakili mahasiswa pada forum resmi dan menandatangani surat resmi).","ART Pasal 2 huruf j (mengikuti kegiatan organisasi kemahasiswaan regional, nasional, dan internasional dengan seizin kampus).","ART Pasal 6 ayat (1) huruf a dan b (syarat pengurus: mahasiswa aktif, berakhlak baik, dan tidak sedang menjalani sanksi akademik atau kemahasiswaan).","ART Pasal 3 huruf b dan d (Kewajiban: menjaga ukhuwah dan nama baik STDIIS Jember).","ART Pasal 11 huruf e, g, dan k (larangan politik praktis tanpa izin, mencemarkan nama baik, dan memakai nama organisasi untuk kepentingan pribadi).","AD Pasal 18 ayat (3) (seragam resmi BEM adalah PDH BEM)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Delegasi","Satu atau lebih pengurus aktif BEM yang ditugaskan mewakili BEM pada suatu kegiatan eksternal."],["Ketua delegasi","Anggota delegasi yang ditunjuk memimpin, menjadi penghubung dengan pimpinan BEM, dan bertanggung jawab atas laporan."],["Surat Tugas","Surat resmi yang menyatakan nama, kegiatan, waktu, dan tempat penugasan delegasi."],["Pembekalan","Pengarahan sebelum berangkat mengenai tujuan, batas mandat, isu sensitif, adab, dan bahan yang dibawa."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Delegasi adalah pengurus aktif yang memenuhi syarat ART Pasal 6 ayat (1) huruf a dan b; mahasiswa non-pengurus hanya dapat disertakan atas keputusan Presiden.","Penunjukan memperhatikan kesesuaian bidang, kesiapan, dan jadwal perkuliahan; tugas delegasi tidak boleh mengorbankan kewajiban akademik.","Setiap delegasi membawa Surat Tugas; bila mewakili sikap BEM atau menandatangani sesuatu, delegasi juga membawa Surat Mandat (SOP-HKE-011).","Kegiatan regional, nasional, dan internasional wajib mendapat izin kampus sebelum keberangkatan; tanpa izin, pengurus tidak berangkat atas nama BEM (ART Pasal 2 huruf j).","Biaya delegasi diajukan melalui mekanisme keuangan (SOP-KEU-002 dan SOP-KEU-004); pengurus tidak menalangi dana organisasi tanpa persetujuan tertulis.","Pada acara resmi delegasi mengenakan PDH BEM, kecuali ditentukan lain oleh penyelenggara atau kampus, serta menaati adab Islami dan tata tertib acara.","Delegasi tidak menyampaikan sikap, membuat komitmen, atau menandatangani dokumen di luar mandat; hal di luar mandat dibawa kepada pimpinan.","Pemberian dari pihak eksternal yang berkaitan dengan jabatan dilaporkan kepada Menteri Hubungan Eksternal dan diperlakukan sesuai SOP-RSK-006 (usulan)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Hubungan Eksternal","A","Mengusulkan delegasi, menyelenggarakan pembekalan, dan memantau pelaksanaan penugasan."],["Presiden","R","Menetapkan delegasi dan ketua delegasi serta menandatangani Surat Tugas."],["Kepala Biro Kesekretariatan","R","Menerbitkan Surat Tugas dan mengajukan izin kampus."],["Kepala Biro Keuangan","R","Memproses kebutuhan biaya sesuai anggaran."],["Delegasi / Ketua delegasi","R","Melaksanakan penugasan, menjaga adab, dan menyampaikan laporan."],["Inspektur Jenderal","C","Memeriksa kepatuhan terhadap syarat delegasi dan batas mandat bila diminta."],["Wakil Presiden","C","Memberi pertimbangan penunjukan dan penggantian delegasi."],["Seluruh pengurus","I","Mengetahui jadwal dan penugasan delegasi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Keputusan menerima undangan atau menginisiasi kegiatan (SOP-HKE-001).","Undangan atau kerangka acuan kegiatan.","Jadwal perkuliahan dan beban tugas calon delegasi.","Anggaran yang tersedia dan izin kampus bila diperlukan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Identifikasi kebutuhan: Menentukan jumlah, bidang, dan kompetensi delegasi berdasarkan sifat kegiatan, agenda, dan anggaran.","Menteri Hubungan Eksternal","Keputusan undangan, kerangka acuan","Kebutuhan delegasi","1 hari kerja"],["2","Usulan delegasi: Mengusulkan nama delegasi dan ketua delegasi dengan memeriksa syarat ART Pasal 6 ayat (1) dan jadwal kuliah.","Menteri Hubungan Eksternal","Kebutuhan delegasi, data pengurus","Formulir Usulan Delegasi","2 hari kerja"],["3","Penetapan: Menetapkan delegasi dan ketua delegasi, serta menyatakan perlu tidaknya Surat Mandat.","Presiden","Formulir usulan","Keputusan penetapan","1 hari kerja"],["4","Surat Tugas dan izin: Menerbitkan Surat Tugas dan mengajukan izin kampus untuk kegiatan yang mewajibkannya.","Kepala Biro Kesekretariatan","Keputusan penetapan","Surat Tugas, surat izin","3 hari kerja"],["5","Dukungan biaya: Memproses kebutuhan biaya perjalanan dan akomodasi sesuai anggaran yang telah disetujui.","Kepala Biro Keuangan","Surat Tugas, anggaran","Dana tersedia atau dicatat","Sebelum keberangkatan"],["6","Pembekalan: Memberi pengarahan tujuan, batas mandat, isu sensitif, adab, dan bahan yang dibawa; delegasi menandatangani lembar pembekalan.","Menteri Hubungan Eksternal","Surat Tugas, bahan","Lembar Pembekalan","Paling lambat 1 hari sebelum berangkat"],["7","Pelaksanaan: Menghadiri kegiatan, mengisi daftar hadir, mendokumentasikan, dan melapor kendala kepada pimpinan melalui kanal resmi.","Ketua delegasi","Surat Tugas, bahan","Dokumentasi dan catatan lapangan","Sesuai jadwal kegiatan"],["8","Pelaporan dan evaluasi: Menyampaikan laporan sesuai SOP- HKE-012 dan mengevaluasi manfaat serta kepatuhan delegasi.","Ketua delegasi dan Menteri Hubungan Eksternal","Catatan lapangan","Laporan hasil, catatan evaluasi","3 hari kerja setelah kegiatan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penetapan delegasi paling lambat 3 hari kerja sebelum keberangkatan dan pembekalan paling lambat 1 hari sebelum berangkat. Hasil akhir: Surat Tugas, izin kampus (bila perlu), dan laporan delegasi."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Delegasi berhalangan mendadak: Menteri Hubungan Eksternal mengusulkan pengganti dengan persetujuan Wakil Presiden dan Surat Tugas diperbarui.","Izin kampus belum terbit: delegasi tidak berangkat atas nama BEM; kegiatan ditunda atau dibatalkan.","Dugaan pelanggaran etika atau pelampauan mandat oleh delegasi: ditangani melalui SOP-SDM-013 dan ART Pasal 12 sampai 13.","Insiden keselamatan selama penugasan: SOP-RSK-003."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% delegasi memiliki Surat Tugas sebelum berangkat.","100% kegiatan yang wajib izin kampus memperoleh izin sebelum berangkat.","Laporan delegasi diterima paling lambat 3 hari kerja setelah kegiatan.","Tidak ada pelampauan mandat yang dicatat pada evaluasi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Usulan Delegasi dan keputusan penetapan.","Surat Tugas dan surat izin kampus.","Lembar Pembekalan Delegasi.","Laporan hasil kegiatan (SOP-HKE-012). Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri Hubungan Eksternal meninjau daftar penugasan delegasi setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Identifikasi kebutuhan → Usulan delegasi → Penetapan Presiden → Surat Tugas dan izin → Dukungan biaya → Pembekalan → Pelaksanaan → Laporan dan evaluasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Usulan Delegasi","Nama kegiatan; penyelenggara; waktu dan tempat; nama dan jabatan calon delegasi; ketua delegasi; alasan pemilihan; kebutuhan biaya; pengusul; tanggal."],["Surat Tugas Delegasi","Nomor surat; dasar penugasan; nama dan jabatan; kegiatan; waktu dan tempat; ketentuan khusus; penandatangan."],["Lembar Pembekalan Delegasi","Tujuan kehadiran; batas mandat; isu sensitif; adab dan busana; bahan yang dibawa; nomor kontak pimpinan; tanda tangan delegasi."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh delegasi memenuhi syarat ART Pasal 6 ayat (1).","☐ Ya ☐ Tidak"],["2","Surat Tugas telah terbit dan ditandatangani.","☐ Ya ☐ Tidak"],["3","Izin kampus diperoleh untuk kegiatan yang mewajibkannya.","☐ Ya ☐ Tidak"],["4","Surat Mandat tersedia bila delegasi mewakili sikap atau menandatangani dokumen.","☐ Ya ☐ Tidak"],["5","Pembekalan telah dilaksanakan dan dicatat.","☐ Ya ☐ Tidak"],["6","Laporan diterima dalam 3 hari kerja.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Hubungan Eksternal; Kepala Biro Kesekretariatan; Kepala Biro Keuangan; delegasi yang bersangkutan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-003","g":"Hubungan Eksternal dan Kemitraan","t":"Pengajuan Audiensi dengan Pihak Kampus","o":"Menteri Harmonisasi Kampus","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Harmonisasi Kampus","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[678,681],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengajuan, persiapan, pelaksanaan, dan tindak lanjut audiensi BEM dengan pihak kampus agar penyampaian koordinasi, permohonan, laporan, dan masukan dilakukan dengan tertib, santun, berdasar data, serta terdokumentasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk audiensi BEM dengan Ketua STDIIS, KAUR ORMAWA, Pembina, atau pejabat dan pengajar yang berwenang untuk keperluan koordinasi, permohonan izin atau fasilitas, penyampaian laporan, konsultasi, dan penyampaian masukan umum. Audiensi advokasi atas kasus mahasiswa mengikuti SOP-ADV-007; rapat rutin dengan Pembina tidak diatur dalam SOP ini."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf g, h, dan i (hak menyampaikan aspirasi, kritik, dan saran; mengkritisi kebijakan kampus secara konstruktif dengan etika yang baik; serta mendapat fasilitas dan dukungan kampus).","ART Pasal 3 huruf h (Kewajiban: mematuhi seluruh peraturan dan kebijakan STDIIS Jember).","ART Pasal 4 huruf e dan f (mewakili mahasiswa dan menandatangani surat resmi).","AD Pasal 17 ayat (3) (hasil pembahasan laporan pertanggungjawaban dilaporkan kepada Kepala Urusan Organisasi Kemahasiswaan).","ART Pasal 9 ayat (6) (program kerja yang disahkan dalam Rapat Kerja memerlukan persetujuan Pembina sebelum dilaksanakan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Audiensi","Pertemuan resmi terjadwal antara BEM dan pihak kampus untuk membahas suatu agenda."],["Pihak kampus","Ketua STDIIS, KAUR ORMAWA, Pembina, serta pejabat atau pengajar yang berwenang atas agenda yang dibahas."],["Bahan audiensi","Ringkasan latar belakang, data pendukung, permintaan, dan sikap BEM yang telah disepakati pimpinan."],["Notulen audiensi","Catatan resmi hasil audiensi yang memuat kesepakatan dan tindak lanjut."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pintu koordinasi BEM dengan kampus adalah KAUR ORMAWA, kecuali kampus menetapkan jalur lain; permohonan kepada pimpinan yang lebih tinggi disampaikan melalui jalur tersebut (asumsi pada Catatan Penyusun).","Audiensi diajukan secara tertulis atas nama BEM dengan agenda yang jelas dan ditandatangani Presiden atau pejabat yang diberi wewenang (SOP-GOV-008).","Sikap, permintaan, dan kritik yang akan disampaikan wajib dibahas dan disepakati pimpinan lebih dahulu (SOP-GOV-002); kritik disampaikan konstruktif, berdasar data, dan dengan adab (ART Pasal 2 huruf h).","Kritik atau keberatan terhadap kebijakan kampus tidak disampaikan melalui publikasi terbuka sebelum jalur audiensi ditempuh (SOP-KOM-010).","Peserta audiensi dari BEM dibatasi pada pimpinan, menteri atau kepala biro terkait, dan satu pencatat; peserta mengenakan PDH BEM.","Hasil audiensi yang memuat kesepakatan atau tugas dicatat dalam notulen dan dimasukkan ke daftar tindak lanjut (SOP-ADM-010).","Usulan yang menyentuh perubahan AD/ART tidak diputuskan dalam audiensi; ikuti AD Bab XI dan ART Bab VII."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Harmonisasi Kampus","A","Bertanggung jawab atas kesiapan agenda, bahan, dan tindak lanjut audiensi dengan pihak kampus."],["Presiden","R","Menandatangani surat permohonan, memimpin audiensi, dan menyampaikan sikap BEM."],["Sekretaris Jenderal","R","Memastikan surat, notulen, dan arsip melalui Biro Kesekretariatan."],["Wakil Presiden","C","Memberi pertimbangan sikap dan hadir bila diperlukan."],["Menteri / Kabiro terkait","C","Menyediakan data dan bahan sesuai bidangnya."],["Inspektur Jenderal","C","Memeriksa kesesuaian bahan dengan AD/ART bila menyangkut dugaan pelanggaran."],["Pihak kampus","C","Menjadwalkan, menerima, dan memberi tanggapan atas audiensi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Agenda audiensi dan alasan kebutuhannya.","Data dan dokumen pendukung yang dapat dipertanggungjawabkan.","Keputusan pimpinan mengenai sikap BEM.","Informasi jalur dan jadwal dari KAUR ORMAWA atau pihak kampus."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Identifikasi agenda: Merumuskan tujuan audiensi, pihak kampus yang dituju, dan hasil yang diharapkan.","Menteri Harmonisasi Kampus","Kebutuhan koordinasi","Rumusan agenda","2 hari kerja"],["2","Penyusunan bahan: Menyusun Lembar Bahan Audiensi: latar belakang, data, permintaan, opsi, dan usulan sikap.","Menteri Harmonisasi Kampus bersama menteri terkait","Rumusan agenda, data","Draf bahan","3 hari kerja"],["3","Persetujuan sikap: Membahas bahan dalam Rapat Pimpinan dan menetapkan sikap BEM secara musyawarah (SOP-GOV-002).","Pimpinan","Draf bahan","Bahan final dan sikap BEM","1 kali rapat"],["4","Surat permohonan: Menyusun dan mengirim surat permohonan audiensi melalui KAUR ORMAWA atau jalur yang ditetapkan kampus.","Kepala Biro Kesekretariatan","Bahan final","Surat terkirim, nomor register","2 hari kerja; dikirim paling lambat 5 hari kerja sebelum jadwal diusulkan"],["5","Konfirmasi jadwal: Menindaklanjuti jawaban kampus, memastikan waktu, tempat, dan peserta, serta menyampaikan jadwal kepada peserta BEM.","Menteri Harmonisasi Kampus","Jawaban kampus","Jadwal terkonfirmasi","2 hari kerja"],["6","Pelaksanaan: Melaksanakan audiensi dengan adab dan sikap yang telah disepakati; mencatat kesepakatan dan permintaan kampus.","Presiden dan peserta BEM","Bahan final, jadwal","Notulen audiensi","Sesuai jadwal"],["7","Pelaporan internal: Menyusun notulen dan melaporkannya pada Rapat Pimpinan; menetapkan tindak lanjut dan penanggung jawab.","Sekjen","Notulen","Notulen sah, daftar tindak lanjut","2 hari kerja; dibahas paling lambat 5 hari kerja"],["8","Tindak lanjut: Memantau pelaksanaan tindak lanjut dan menyampaikan perkembangan kepada pihak kampus bila diminta.","Menteri Harmonisasi Kampus","Daftar tindak lanjut","Laporan tindak lanjut","Sesuai tenggat tindak lanjut"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari identifikasi agenda hingga surat permohonan terkirim paling lambat 7 hari kerja; notulen diselesaikan 2 hari kerja setelah audiensi. Hasil akhir: notulen audiensi dan daftar tindak lanjut."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Permohonan belum dijawab dalam 5 hari kerja: mengingatkan melalui KAUR ORMAWA; bila mendesak gunakan SOP-GOV-012.","Pimpinan berbeda pendapat mengenai sikap: SOP-GOV-002 dan SOP-GOV-010.","Audiensi tidak menghasilkan titik temu: dikonsultasikan kepada Pembina; BEM tidak mengambil langkah sepihak.","Agenda berupa kasus atau pengaduan mahasiswa: dialihkan ke SOP-ADV-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% audiensi memiliki surat permohonan dan bahan yang disetujui pimpinan.","Notulen selesai paling lambat 2 hari kerja setelah audiensi.","Tindak lanjut tercatat dan dipantau hingga selesai.","Tidak ada kritik terhadap kampus yang dipublikasikan sebelum jalur audiensi ditempuh."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Surat permohonan audiensi dan jawaban kampus.","Lembar Bahan Audiensi.","Notulen audiensi.","Daftar tindak lanjut. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan dokumen audiensi setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Identifikasi agenda → Penyusunan bahan → Persetujuan sikap pimpinan → Surat permohonan → Konfirmasi jadwal → Pelaksanaan → Notulen dan laporan → Tindak lanjut → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Surat Permohonan Audiensi","Nomor surat; tujuan kepada; perihal; agenda; usulan waktu dan tempat; daftar peserta BEM; kontak; penandatangan."],["Lembar Bahan Audiensi","Agenda; latar belakang; data pendukung; permintaan; opsi; sikap BEM; peserta dan peran; tanggal persetujuan pimpinan."],["Notulen Audiensi","Hari dan tanggal; tempat; peserta; pokok pembahasan; kesepakatan; tindak lanjut dan penanggung jawab; tenggat; pencatat."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Agenda dan tujuan audiensi jelas.","☐ Ya ☐ Tidak"],["2","Sikap BEM telah disepakati pimpinan.","☐ Ya ☐ Tidak"],["3","Surat permohonan dikirim melalui jalur yang benar.","☐ Ya ☐ Tidak"],["4","Peserta mengenakan PDH BEM dan mengetahui batas bahan.","☐ Ya ☐ Tidak"],["5","Notulen selesai dalam 2 hari kerja.","☐ Ya ☐ Tidak"],["6","Tindak lanjut masuk daftar pemantauan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Harmonisasi Kampus; menteri dan kepala biro terkait; Biro Kesekretariatan. Salinan notulen diberikan kepada KAUR ORMAWA atau Pembina bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-004","g":"Hubungan Eksternal dan Kemitraan","t":"Audiensi dengan Organisasi Mahasiswa Lain","o":"Menteri Harmonisasi Kampus","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Harmonisasi Kampus","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[682,685],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur persiapan, pelaksanaan, dan tindak lanjut audiensi BEM dengan organisasi mahasiswa lain untuk koordinasi, silaturahim, konsultasi, dan penjajakan kolaborasi secara tertib dan sesuai ukhuwah Islamiyah, tanpa menimbulkan ikatan yang belum disetujui."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk audiensi dengan ORMAWA internal STDIIS (BPM, HIMA, dan UKM) dan dengan ORMAWA atau BEM perguruan tinggi lain. Audiensi dengan pihak kampus mengikuti SOP-HKE-003; kerja sama yang mengikat mengikuti SOP-HKE-005."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Bab III (Tugas BEM) huruf d dan f (membangun koordinasi antar ORMAWA dan mengoordinasikan seluruh kegiatan kemahasiswaan).","ART Pasal 4 huruf g (memberikan rekomendasi kepada HIMA dan UKM dalam pelaksanaan kegiatan).","ART Pasal 2 huruf e (kerja sama dengan ORMAWA lain dengan persetujuan Ketua STDIIS).","AD Pasal 3 ayat (3) dan AD Pasal 5 ayat (2) (sifat independen dan penguatan ukhuwah Islamiyah).","AD Pasal 17 ayat (3) (laporan pertanggungjawaban BEM dibahas bersama BPM dalam Musyawarah Besar).","ART Pasal 11 huruf a, d, dan e (larangan SARA, paham yang bertentangan, dan politik praktis tanpa izin kampus)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["ORMAWA internal","Organisasi kemahasiswaan di lingkungan STDIIS Jember, yaitu BPM, HIMA, dan UKM."],["ORMAWA eksternal","Organisasi mahasiswa atau BEM perguruan tinggi lain di luar STDIIS Jember."],["Telaah mitra","Pemeriksaan profil, visi, afiliasi, dan reputasi ORMAWA eksternal sebelum audiensi."],["Catatan kesepahaman","Catatan hasil audiensi yang bersifat awal dan tidak mengikat."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Audiensi dengan ORMAWA internal dipimpin Menteri Harmonisasi Kampus; audiensi dengan ORMAWA eksternal dilakukan bersama Menteri Hubungan Eksternal dan dengan izin Presiden.","Audiensi bersifat koordinasi dan penjajakan; setiap hasil yang menimbulkan komitmen, biaya, atau kerja sama diteruskan ke SOP-HKE-005 dan tidak berlaku sebelum disetujui.","Kolaborasi dengan HIMA, UKM, dan BPM cukup dikoordinasikan sesuai ART Bab III huruf d dan f, kecuali menimbulkan komitmen kepada pihak di luar STDIIS (asumsi pada Catatan Penyusun).","Audiensi dengan BPM dilakukan dengan menjaga fungsi pengawasan BPM dan independensi BEM; BEM tidak meminta BPM mengubah penilaian atas laporan pertanggungjawaban.","ORMAWA eksternal yang berafiliasi dengan partai politik, bermuatan politik praktis, atau menyebarkan paham yang bertentangan dengan Al-Qur'an dan As-Sunnah tidak diterima audiensinya tanpa izin kampus (ART Pasal 11 huruf d dan e).","Pernyataan bersama, komunike, atau publikasi hasil audiensi memerlukan persetujuan Presiden (SOP- KOM-010).","Adab ukhuwah dijaga: undangan santun, tepat waktu, tidak merendahkan, dan tidak memprovokasi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Harmonisasi Kampus","A","Bertanggung jawab atas persiapan, pelaksanaan, dan tindak lanjut audiensi dengan ORMAWA."],["Menteri Hubungan Eksternal","R","Memimpin telaah mitra dan hubungan dengan ORMAWA eksternal."],["Presiden","R","Menyetujui audiensi ORMAWA eksternal dan sikap BEM."],["Sekretaris Jenderal","R","Memastikan surat, notulen, dan arsip melalui Biro Kesekretariatan."],["Inspektur Jenderal","C","Memeriksa kesesuaian telaah mitra dengan AD/ART bila diminta."],["Wakil Presiden","C","Memberi pertimbangan koordinasi antar-unit."],["ORMAWA mitra","C","Menerima undangan dan memberi tanggapan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Tujuan dan agenda audiensi.","Profil singkat ORMAWA mitra.","Persetujuan Presiden untuk ORMAWA eksternal.","Jadwal kegiatan BEM dan ORMAWA mitra."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penentuan tujuan: Menetapkan tujuan audiensi, ORMAWA yang dituju, dan jenis hubungan yang diharapkan.","Menteri Harmonisasi Kampus","Kebutuhan koordinasi","Rumusan tujuan","1 hari kerja"],["2","Telaah mitra: Untuk ORMAWA eksternal: memeriksa profil, visi, afiliasi, dan reputasi menggunakan Lembar Telaah Mitra.","Menteri Hubungan Eksternal","Profil mitra, basis data mitra","Lembar Telaah Mitra","3 hari kerja"],["3","Persetujuan: Meminta persetujuan Presiden untuk audiensi ORMAWA eksternal dan menetapkan batas pembicaraan.","Presiden","Rumusan tujuan, telaah","Persetujuan tercatat","2 hari kerja"],["4","Undangan atau permohonan: Mengirim surat undangan atau permohonan audiensi dan mengonfirmasi jadwal.","Kepala Biro Kesekretariatan","Persetujuan, jadwal","Surat terkirim, jadwal terkonfirmasi","2 hari kerja"],["5","Persiapan bahan: Menyusun poin pembicaraan, data pendukung, dan batas komitmen yang boleh dibahas.","Menteri Harmonisasi Kampus","Rumusan tujuan, telaah","Bahan audiensi","2 hari kerja"],["6","Pelaksanaan: Melaksanakan audiensi dengan adab ukhuwah, mencatat hasil, mengisi daftar hadir, dan mendokumentasikan.","Menteri Harmonisasi Kampus dan peserta BEM","Bahan audiensi","Notulen, daftar hadir, dokumentasi","Sesuai jadwal"],["7","Catatan kesepahaman: Menyusun catatan hasil yang tidak mengikat dan memisahkan butir yang perlu diproses sebagai kerja sama.","Sekjen","Notulen","Catatan kesepahaman","2 hari kerja"],["8","Pelaporan dan tindak lanjut: Melaporkan hasil sesuai SOP-HKE- 012, memperbarui basis data mitra (SOP-HKE-013), dan meneruskan butir kerja sama ke SOP-HKE-005.","Menteri Harmonisasi Kampus","Catatan kesepahaman","Laporan, pembaruan data, usulan kerja sama","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari penentuan tujuan hingga audiensi terlaksana ditargetkan paling lambat 10 hari kerja, dan laporan paling lambat 3 hari kerja setelah audiensi. Hasil akhir: notulen, catatan kesepahaman, dan laporan hasil."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Hasil audiensi mengarah pada komitmen atau biaya: dihentikan pada tahap catatan dan diproses melalui SOP-HKE-005.","ORMAWA eksternal bermuatan politik praktis atau paham yang dilarang: audiensi ditunda sampai ada izin kampus atau ditolak.","Perselisihan dengan ORMAWA lain: SOP-GOV-010 dan, bila menyangkut institusi, dikonsultasikan kepada KAUR ORMAWA.","Pernyataan bersama tanpa persetujuan: ditarik dan ditangani sesuai SOP-KOM-009."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% audiensi ORMAWA eksternal memiliki telaah mitra dan persetujuan Presiden.","Tidak ada komitmen yang dibuat dalam audiensi tanpa melalui SOP-HKE-005.","Laporan audiensi diterima paling lambat 3 hari kerja.","Basis data mitra diperbarui setelah setiap audiensi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Telaah Mitra (ORMAWA eksternal).","Surat undangan atau permohonan audiensi.","Notulen audiensi dan catatan kesepahaman.","Laporan hasil pertemuan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri Harmonisasi Kampus meninjau daftar audiensi dan tindak lanjut setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Penentuan tujuan → Telaah mitra → Persetujuan Presiden → Undangan atau permohonan → Persiapan bahan → Pelaksanaan → Catatan kesepahaman → Laporan dan tindak lanjut → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Telaah Mitra","Nama ORMAWA; asal perguruan tinggi; visi dan kegiatan; afiliasi; reputasi; kesesuaian dengan AD/ART; manfaat; risiko; rekomendasi; penelaah."],["Catatan Kesepahaman","Pihak yang bertemu; tanggal; pokok pembahasan; hal yang disepakati sebagai catatan awal; hal yang perlu diproses sebagai kerja sama; pernyataan tidak mengikat."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Tujuan audiensi jelas dan sesuai tugas BEM.","☐ Ya ☐ Tidak"],["2","Telaah mitra selesai untuk ORMAWA eksternal.","☐ Ya ☐ Tidak"],["3","Persetujuan Presiden tercatat untuk ORMAWA eksternal.","☐ Ya ☐ Tidak"],["4","Tidak ada komitmen yang mengikat dibuat dalam audiensi.","☐ Ya ☐ Tidak"],["5","Butir kerja sama diteruskan ke SOP-HKE-005.","☐ Ya ☐ Tidak"],["6","Basis data mitra diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Harmonisasi Kampus; Menteri Hubungan Eksternal; Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-005","g":"Hubungan Eksternal dan Kemitraan","t":"Pengajuan dan Pengelolaan Kerja Sama","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[686,690],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan tahapan pengajuan, penilaian, persetujuan, pelaksanaan, pemantauan, perpanjangan, dan pengakhiran kerja sama BEM dengan pihak eksternal, sehingga setiap kerja sama halal, tidak mengikat melampaui periode kepengurusan, mendapat persetujuan Ketua STDIIS, dan bermanfaat bagi organisasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh bentuk kerja sama BEM dengan pihak eksternal (instansi pemerintah, swasta, ORMAWA lain, lembaga dakwah, sosial, dan pendidikan, serta komunitas), termasuk nota kesepahaman, perjanjian kerja sama, kolaborasi kegiatan, dan kemitraan media. Penyusunan naskah diatur SOP-HKE-006, sponsor diatur SOP-HKE-007 dan SOP-HKE-008, dan pengelolaan keuangan kerja sama mengikuti SOP- KEU."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf e (kerja sama yang halal dan tidak mengikat dengan pihak eksternal dengan persetujuan Ketua STDIIS).","AD Pasal 15 ayat (1) huruf b dan ayat (2) (dukungan eksternal yang tidak mengikat, tidak menimbulkan kewajiban melampaui satu periode, dan terhindar dari riba, gharar, dan maysir).","ART Pasal 4 huruf e dan f (mewakili mahasiswa dan menandatangani dokumen organisasi).","ART Pasal 3 huruf a, b, d, dan h (Kewajiban: prinsip Ahlus Sunnah wal Jama'ah, ukhuwah, nama baik, dan kepatuhan pada peraturan kampus).","ART Bab III (Tugas BEM) huruf d (kerja sama dengan pihak eksternal perguruan tinggi).","ART Pasal 11 huruf a, d, e, dan k (larangan SARA, paham yang bertentangan, politik praktis tanpa izin, dan penggunaan nama organisasi untuk kepentingan pribadi).","AD Pasal 18 ayat (1) dan (2) (hanya lambang yang disahkan STDIIS Jember yang boleh digunakan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kerja sama","Hubungan tertulis atau terdokumentasi antara BEM dan pihak eksternal untuk melaksanakan kegiatan, program, atau pertukaran manfaat."],["Kerja sama tidak mengikat","Kerja sama yang tidak menimbulkan kewajiban hukum atau keuangan melampaui periode kepengurusan, tidak memberi mitra hak menentukan kebijakan BEM, dan dapat diakhiri dengan pemberitahuan tertulis (usulan operasional)."],["Naskah kerja sama","Dokumen tertulis kerja sama, seperti nota kesepahaman atau perjanjian kerja sama (SOP- HKE-006)."],["Penanggung jawab kerja sama (PIC)","Pengurus yang ditunjuk memantau pelaksanaan satu kerja sama sampai selesai."],["Register Kerja Sama","Daftar seluruh kerja sama beserta status, masa berlaku, dan PIC."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kerja sama harus halal, tidak mengikat, dan mendapat persetujuan Ketua STDIIS sebelum ditandatangani (ART Pasal 2 huruf e); tanpa persetujuan, kerja sama belum berlaku.","Kerja sama tidak boleh menimbulkan kewajiban BEM yang melampaui masa kepengurusan Kabinet Samasta; masa berlaku paling lama sampai berakhirnya masa jabatan kabinet.","Kerja sama tidak boleh memuat denda, ganti rugi, eksklusivitas, atau hak mitra menentukan kebijakan, program, atau pengurus BEM.","Penyaringan mitra: bidang kegiatan halal; sejalan dengan landasan Al-Qur'an dan As-Sunnah serta manhaj Ahlusunah wal Jamaah; tidak berafiliasi politik praktis tanpa izin kampus; reputasi baik; dan tidak ada konflik kepentingan pengurus (SOP-RSK-006).","Tahapan persetujuan: pembahasan Rapat Pimpinan, keputusan Presiden, persetujuan tertulis Ketua STDIIS melalui KAUR ORMAWA, lalu penandatanganan oleh Presiden.","Setiap kerja sama memiliki PIC dan tercatat pada Register Kerja Sama dan basis data mitra (SOP- HKE-013).","Kerja sama yang melibatkan dana mengikuti SOP-KEU-012 dan SOP-KEU-013, dan yang melibatkan pengadaan mengikuti SOP-KEU-010; tidak ada transaksi melalui rekening pribadi.","Nama, lambang, dan identitas BEM pada materi kerja sama hanya memakai lambang yang disahkan STDIIS Jember."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Bertanggung jawab akhir atas keputusan kerja sama, menandatangani naskah, dan memutuskan perpanjangan atau pengakhiran."],["Menteri Hubungan Eksternal","R","Menelaah mitra, menyusun usulan, menjadi PIC, dan memantau pelaksanaan."],["Sekretaris Jenderal","R","Mengoordinasikan penyusunan naskah (SOP-HKE-006), pencatatan Register, dan pengarsipan."],["Kepala Biro Keuangan","C","Menelaah dampak keuangan dan memastikan pengelolaan dana sesuai SOP- KEU."],["Inspektur Jenderal","C","Memeriksa kesesuaian dengan AD/ART, aturan kampus, dan syariat serta risiko konflik kepentingan."],["Wakil Presiden","C","Memberi pertimbangan dan mengoordinasikan unit pelaksana."],["Ketua STDIIS / KAUR ORMAWA","C","Memberi persetujuan atas kerja sama sesuai ART Pasal 2 huruf e."],["Mitra","C","Mengajukan atau menanggapi usulan dan menyepakati naskah."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Usulan Kerja Sama beserta tujuan dan manfaat.","Profil dan legalitas mitra.","Draf naskah kerja sama (SOP-HKE-006).","Rancangan anggaran bila kerja sama memerlukan dana.","Daftar penyaringan mitra (halal, afiliasi, reputasi, konflik kepentingan)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Usulan kerja sama: Mengisi Formulir Usulan Kerja Sama: mitra, bentuk, tujuan, manfaat, kebutuhan dana, dan jangka waktu.","Menteri / Kabiro pengusul","Kebutuhan program, penawaran mitra","Formulir usulan","2 hari kerja"],["2","Telaah mitra dan manfaat: Memeriksa profil mitra, kehalalan bidang, kesesuaian visi dan manhaj, afiliasi, serta manfaat dan beban bagi BEM.","Menteri Hubungan Eksternal","Formulir usulan","Lembar Telaah Mitra","5 hari kerja"],["3","Pemeriksaan keselarasan: Memeriksa risiko, konflik kepentingan, dan kesesuaian dengan AD/ART, aturan kampus, dan syariat.","Irjen","Lembar Telaah Mitra","Catatan pemeriksaan","2 hari kerja"],["4","Keputusan awal: Membahas usulan dalam Rapat Pimpinan (SOP-GOV-005) dan memutuskan lanjut, ubah, atau tolak secara musyawarah (SOP-GOV-002).","Presiden dan pimpinan","Telaah, catatan Irjen","Keputusan awal","1 kali rapat"],["5","Penyusunan naskah: Menyusun dan menegosiasikan naskah sesuai SOP-HKE-006 dengan batas tidak mengikat.","Sekjen bersama PIC","Keputusan awal","Naskah final","7 hari kerja"],["6","Persetujuan Ketua STDIIS: Mengajukan naskah kepada Ketua STDIIS melalui KAUR ORMAWA dan menunggu persetujuan tertulis.","Presiden melalui Sekjen","Naskah final, telaah","Persetujuan tertulis kampus","Menurut ketentuan kampus; usulan 10 hari kerja"],["7","Penandatanganan dan pencatatan: Menandatangani naskah, mencatat pada Register Kerja Sama, menunjuk PIC, dan mendistribusikan salinan.","Presiden dan Sekjen","Naskah final, persetujuan kampus","Naskah bertanda tangan, entri Register","2 hari kerja"],["8","Pelaksanaan dan pemantauan: Melaksanakan kewajiban kedua pihak, memantau kepatuhan, dan melaporkan perkembangan pada Rapat Koordinasi.","PIC","Naskah, rencana kegiatan","Laporan perkembangan","Setiap bulan atau setiap kegiatan"],["9","Evaluasi dan pengakhiran: Mengevaluasi manfaat, memutuskan perpanjangan (melalui proses yang sama) atau pengakhiran, dan mencatat status akhir.","Presiden dan Menteri Hubungan Eksternal","Laporan perkembangan","Keputusan perpanjangan atau pengakhiran","30 hari sebelum masa berlaku berakhir"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari usulan hingga penandatanganan ditargetkan paling lambat 25 hari kerja sejak usulan lengkap, tidak termasuk waktu persetujuan kampus yang mengikuti ketentuan kampus. Hasil akhir: naskah bertanda tangan, persetujuan Ketua STDIIS, dan entri Register Kerja Sama."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Mitra menuntut klausul mengikat atau melampaui periode: ditolak atau dinegosiasi ulang; bila perlu penafsiran, dikonsultasikan kepada KAUR ORMAWA atau Pembina.","Kampus belum atau tidak memberi persetujuan: naskah tidak ditandatangani dan kegiatan kerja sama tidak dimulai.","Mitra tidak memenuhi kesepakatan atau merugikan nama baik: Presiden menghentikan kerja sama secara tertulis dan melaporkannya kepada Pembina.","Dugaan penyalahgunaan nama atau dana dalam kerja sama: SOP-RSK-007 dan ART Pasal 12 sampai 13.","Usulan kerja sama yang menyentuh perubahan AD/ART tidak diputuskan melalui SOP ini; ikuti AD Bab XI dan ART Bab VII."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kerja sama ditandatangani setelah persetujuan Ketua STDIIS.","100% kerja sama tercatat pada Register Kerja Sama dan memiliki PIC.","Tidak ada klausul yang mengikat melampaui periode kepengurusan.","Setiap kerja sama dievaluasi sebelum masa berlaku berakhir."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Usulan Kerja Sama dan Lembar Telaah Mitra.","Catatan pemeriksaan Irjen dan keputusan Rapat Pimpinan.","Persetujuan tertulis Ketua STDIIS.","Naskah kerja sama bertanda tangan.","Register Kerja Sama dan laporan perkembangan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan Register Kerja Sama setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala dan evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Usulan kerja sama → Telaah mitra → Periksa Irjen → Keputusan awal → Penyusunan naskah → Persetujuan Ketua STDIIS → Penandatanganan dan pencatatan → Pelaksanaan dan pemantauan → Evaluasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Usulan Kerja Sama","Nama mitra; bentuk kerja sama; tujuan; manfaat; kebutuhan dana; jangka waktu; pengusul; PIC yang diusulkan; tanggal."],["Lembar Telaah Mitra","Profil dan legalitas mitra; kehalalan bidang; kesesuaian visi dan manhaj; afiliasi; reputasi; konflik kepentingan; manfaat; beban; rekomendasi."],["Register Kerja Sama","Nomor; mitra; bentuk; PIC; tanggal persetujuan kampus; tanggal tanda tangan; masa berlaku; status; keterangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Mitra lulus penyaringan halal, afiliasi, reputasi, dan konflik kepentingan.","☐ Ya ☐ Tidak"],["2","Tidak ada klausul mengikat melampaui periode kepengurusan.","☐ Ya ☐ Tidak"],["3","Persetujuan tertulis Ketua STDIIS telah diperoleh sebelum penandatanganan.","☐ Ya ☐ Tidak"],["4","Lambang yang digunakan adalah lambang yang disahkan.","☐ Ya ☐ Tidak"],["5","Kerja sama tercatat pada Register dan memiliki PIC.","☐ Ya ☐ Tidak"],["6","Rencana evaluasi dan masa berakhir tercatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Hubungan Eksternal; Kepala Biro Keuangan; Kepala Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-006","g":"Hubungan Eksternal dan Kemitraan","t":"Penyusunan dan Peninjauan Dokumen Kerja Sama","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[691,695],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan, peninjauan, penyuntingan, pengesahan, dan pengendalian versi dokumen kerja sama, sehingga isinya jelas, seimbang, sesuai AD/ART dan syariat, tidak mengikat melampaui periode, dan mudah ditelusuri."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk nota kesepahaman, perjanjian kerja sama, kesepakatan sponsor tertulis, addendum, dan berita acara serah terima yang berkaitan dengan kerja sama. SOP ini tidak mengatur keputusan untuk bekerja sama (SOP-HKE-005), penomoran surat (SOP-ADM-003), maupun penggunaan kop surat, stempel, dan tanda tangan secara umum (SOP-ADM-005)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf b dan e (penggunaan nama dan lambang yang sah serta kerja sama yang halal dan tidak mengikat dengan persetujuan Ketua STDIIS).","ART Pasal 4 huruf f (menandatangani surat resmi dan dokumen organisasi).","AD Pasal 15 ayat (1) huruf b, ayat (2), dan ayat (3) (dukungan tidak mengikat, bebas riba, gharar, dan maysir, serta terdokumentasi dengan bukti resmi).","AD Pasal 18 ayat (1) dan (2) (lambang yang disahkan STDIIS Jember).","ART Pasal 3 huruf e (Kewajiban: mengelola keuangan secara amanah, transparan, dan akuntabel).","ART Pasal 11 huruf i dan k (larangan korupsi, manipulasi, dan penggunaan nama organisasi untuk kepentingan pribadi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Nota kesepahaman (MoU)","Dokumen yang memuat maksud dan arah kerja sama secara garis besar."],["Perjanjian kerja sama (PKS)","Dokumen yang memuat hak, kewajiban, dan ketentuan pelaksanaan kerja sama secara rinci."],["Addendum","Perubahan atau tambahan atas naskah kerja sama yang telah ditandatangani."],["Klausul wajib","Ketentuan minimal yang harus ada pada setiap naskah kerja sama BEM."],["Versi","Nomor revisi draf naskah yang dikendalikan agar tidak ada naskah ganda."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Naskah kerja sama memakai templat baku BEM; naskah dari mitra ditelaah dengan Daftar Periksa Klausul yang sama sebelum diterima.","Klausul wajib: identitas para pihak dan kapasitas penandatangan; maksud dan tujuan; ruang lingkup; hak dan kewajiban; jangka waktu yang tidak melampaui periode kepengurusan; pembiayaan dan pelaporan; penggunaan nama dan lambang; kerahasiaan; larangan; pengakhiran; dan penyelesaian perselisihan.","Naskah tidak memuat riba, gharar, maysir, denda atau ganti rugi yang membebani BEM, eksklusivitas, atau kewajiban yang mengikat pengurus periode berikutnya.","Perselisihan diselesaikan lebih dahulu secara musyawarah dan tabayyun; bila belum selesai melibatkan Pembina atau KAUR ORMAWA.","Perubahan isi naskah yang sudah ditandatangani hanya melalui addendum yang disetujui dengan alur yang sama dengan naskah awal.","Penandatangan atas nama BEM adalah Presiden; penandatangan lain hanya berdasarkan Surat Mandat (SOP-HKE-011).","Setiap naskah diberi nomor dokumen (SOP-ADM-003), memakai lambang yang disahkan, dan disimpan sebagai dokumen penting (SOP-ADM-011)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Bertanggung jawab atas kualitas, kelengkapan, dan pengendalian versi naskah kerja sama."],["Kepala Biro Kesekretariatan","R","Menyusun draf, mengelola versi, penomoran, penggandaan, dan pengarsipan."],["Menteri Hubungan Eksternal / PIC","R","Memberi masukan substansi dan menegosiasikan naskah dengan mitra."],["Kepala Biro Keuangan","C","Menelaah ketentuan pembiayaan dan pelaporan keuangan."],["Inspektur Jenderal","C","Memeriksa kesesuaian dengan AD/ART, aturan kampus, dan syariat."],["Presiden","R","Menyetujui naskah final dan menandatangani."],["Ketua STDIIS / KAUR ORMAWA","C","Menyetujui kerja sama sebelum penandatanganan."],["Mitra","C","Menelaah dan menyepakati naskah."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Keputusan awal kerja sama dari Rapat Pimpinan (SOP-HKE-005).","Templat naskah kerja sama dan Daftar Periksa Klausul.","Profil dan legalitas mitra.","Rencana anggaran dan kewajiban kedua pihak."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Persiapan bahan: Mengumpulkan keputusan awal, profil mitra, rencana kegiatan, dan menentukan templat yang dipakai.","Kepala Biro Kesekretariatan","Keputusan awal, templat","Bahan penyusunan","1 hari kerja"],["2","Penyusunan draf: Menyusun draf naskah dengan klausul wajib dan memberi nomor versi.","Kepala Biro Kesekretariatan bersama PIC","Bahan penyusunan","Draf versi 1","3 hari kerja"],["3","Telaah substansi: Menelaah ruang lingkup, kewajiban, dan ketentuan pembiayaan; menyampaikan masukan tertulis.","PIC dan Kepala Biro Keuangan","Draf versi 1","Catatan substansi","2 hari kerja"],["4","Pemeriksaan AD/ART dan syariat: Memeriksa dengan Daftar Periksa Klausul: tidak mengikat, bebas riba, gharar, dan maysir, serta sesuai AD/ART; bila ragu dikonsultasikan kepada KAUR ORMAWA atau Pembina.","Irjen","Draf, daftar periksa","Catatan pemeriksaan","2 hari kerja"],["5","Negosiasi dan revisi: Membahas draf dengan mitra, mencatat perubahan, dan menerbitkan versi berikutnya.","PIC bersama Sekjen","Catatan substansi, catatan Irjen","Draf final","5 hari kerja"],["6","Persetujuan: Menyampaikan draf final kepada Presiden dan, melalui alur SOP-HKE- 005, kepada Ketua STDIIS.","Presiden dan Sekjen","Draf final","Persetujuan tertulis","Menurut SOP- HKE-005"],["7","Finalisasi dan penandatanganan: Memberi nomor dokumen, mencetak, menandatangani, memberi stempel sesuai SOP-ADM-005, dan menukar naskah asli.","Sekjen dan Presiden","Naskah disetujui","Naskah bertanda tangan","2 hari kerja"],["8","Distribusi dan arsip: Memindai naskah, menyimpan di repositori, mendistribusikan salinan kepada PIC dan Biro Keuangan, serta mencatat pada Register.","Kepala Biro Kesekretariatan","Naskah bertanda tangan","Arsip dan Register diperbarui","2 hari kerja"],["9","Peninjauan dan addendum: Meninjau naskah 30 hari sebelum berakhir atau saat ada perubahan; menyusun addendum bila perlu.","Sekjen dan PIC","Naskah, laporan pelaksanaan","Addendum atau pengakhiran","30 hari sebelum berakhir"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penyusunan hingga draf final ditargetkan paling lambat 13 hari kerja sejak keputusan awal, tidak termasuk waktu negosiasi yang bergantung pada mitra. Hasil akhir: naskah bertanda tangan yang tercatat dan terarsip."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Mitra bersikeras pada klausul mengikat: dihentikan pada tahap negosiasi dan dilaporkan kepada Presiden untuk diputuskan atau ditolak.","Perbedaan tafsir klausul dengan AD/ART atau syariat: dikonsultasikan kepada KAUR ORMAWA atau Pembina sebelum disepakati.","Ditemukan dua versi naskah beredar: versi yang berlaku adalah yang tercatat pada Register; versi lain ditarik oleh Sekjen.","Dugaan pemalsuan atau perubahan naskah tanpa persetujuan: SOP-RSK-007 dan ART Pasal 12 sampai 13."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% naskah kerja sama memuat klausul wajib dan lolos Daftar Periksa Klausul.","Tidak ada naskah yang ditandatangani sebelum persetujuan yang diwajibkan.","100% naskah bertanda tangan terarsip dalam 2 hari kerja.","Tidak ada temuan dua versi naskah yang beredar."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Templat dan Daftar Periksa Klausul yang digunakan.","Draf bernomor versi dan catatan pemeriksaan Irjen.","Naskah kerja sama bertanda tangan dan addendum (bila ada).","Entri Register Kerja Sama. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa ketersediaan naskah terkini dan Register Kerja Sama setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Persiapan bahan → Penyusunan draf → Telaah substansi → Periksa AD/ART dan syariat → Negosiasi dan revisi → Persetujuan → Penandatanganan → Distribusi dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Naskah Kerja Sama","Judul; identitas para pihak; maksud dan tujuan; ruang lingkup; hak dan kewajiban; jangka waktu; pembiayaan; nama dan lambang; kerahasiaan; larangan; pengakhiran; penyelesaian perselisihan; penandatangan."],["Daftar Periksa Klausul","Tidak mengikat; masa berlaku; bebas riba, gharar, dan maysir; tanpa denda dan eksklusivitas; penggunaan lambang; kerahasiaan; pengakhiran; penyelesaian perselisihan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh klausul wajib ada dalam naskah.","☐ Ya ☐ Tidak"],["2","Masa berlaku tidak melampaui periode kepengurusan.","☐ Ya ☐ Tidak"],["3","Tidak ada unsur riba, gharar, maysir, denda, atau eksklusivitas.","☐ Ya ☐ Tidak"],["4","Persetujuan Ketua STDIIS diperoleh sebelum penandatanganan.","☐ Ya ☐ Tidak"],["5","Naskah bernomor, bertanda tangan, dan memakai lambang yang disahkan.","☐ Ya ☐ Tidak"],["6","Naskah terarsip dan tercatat pada Register Kerja Sama.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Hubungan Eksternal; Kepala Biro Keuangan; Kepala Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-007","g":"Hubungan Eksternal dan Kemitraan","t":"Pengajuan Sponsorship","o":"Menteri Hubungan Eksternal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Hubungan Eksternal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[696,700],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan, penyaringan, persetujuan, pengajuan, dan pemantauan permohonan sponsorship kepada pihak eksternal, sehingga permintaan terarah, sesuai syariat dan peraturan kampus, tidak mengikat, serta tidak merugikan nama baik organisasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk permohonan dukungan dana, barang, jasa, atau media dari pihak eksternal untuk kegiatan BEM, baik oleh BEM maupun panitia kegiatan. SOP ini tidak mengatur penerimaan dan pemenuhan kewajiban sponsor (SOP-HKE-008), pengelolaan keuangan sponsor (SOP-KEU-012), maupun pengajuan dana kemahasiswaan kepada kampus (SOP-KEU-004)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf b, ayat (2), ayat (3), dan ayat (4) (sumber dana, bebas riba, gharar, dan maysir, bukti penerimaan resmi, serta penyusunan anggaran dengan persetujuan KAUR ORMAWA).","ART Pasal 2 huruf e dan f (kerja sama yang halal dan tidak mengikat serta pengelolaan pendanaan sesuai prinsip syariah).","ART Pasal 3 huruf e dan g (Kewajiban: pengelolaan keuangan amanah dan laporan berkala).","ART Pasal 9 (Rapat Kerja: program kerja yang disahkan memerlukan persetujuan Pembina sebelum dilaksanakan).","ART Pasal 11 huruf f, g, i, dan k (larangan zat haram, mencemarkan nama baik, korupsi, dan penyalahgunaan nama organisasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Sponsorship","Dukungan dana, barang, jasa, atau media dari pihak eksternal untuk suatu kegiatan, dengan kompensasi yang disepakati dan wajar."],["Proposal sponsor","Dokumen permohonan yang memuat gambaran kegiatan, kebutuhan dukungan, dan paket kompensasi."],["Sponsor tidak mengikat","Sponsor yang tidak memberi hak menentukan konten, narasumber, atau kebijakan BEM dan tidak menimbulkan kewajiban melampaui periode kepengurusan."],["Daftar tolak","Daftar bidang usaha atau pihak yang tidak boleh dimintai atau diterima sponsornya."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Sponsorship hanya diajukan untuk kegiatan yang termasuk program kerja sah hasil Rapat Kerja dan telah memiliki rancangan anggaran biaya.","Kriteria sponsor: bidang usaha halal; tidak terkait riba, gharar, atau maysir; tidak bergerak pada produk atau jasa yang dilarang syariat dan peraturan kampus; tidak berafiliasi politik praktis tanpa izin kampus; dan tidak ada konflik kepentingan pengurus.","Hal yang meragukan (syubhat) tidak diputuskan sendiri oleh BEM, tetapi dikonsultasikan kepada Pembina atau KAUR ORMAWA sebelum proposal dikirim.","Sponsor tidak boleh menentukan isi acara, narasumber, atau kebijakan BEM, dan kompensasi dibatasi pada publikasi atau penyebutan yang wajar serta tidak memuat unsur yang dilarang syariat.","Proposal sponsor memakai surat resmi atas nama BEM dan disetujui Presiden; dilarang meminta sponsor atas nama pribadi atau menerima dana tunai langsung oleh pengurus perseorangan.","Tidak ada janji kompensasi di luar paket yang telah disetujui.","Permohonan dana kepada pihak kampus adalah dana kemahasiswaan (ART Pasal 4 huruf d) dan bukan sponsorship."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Hubungan Eksternal","A","Bertanggung jawab atas penyaringan calon sponsor, pengajuan, dan komunikasi dengan calon sponsor."],["Penanggung jawab kegiatan","R","Menyusun kebutuhan dukungan dan konten proposal sponsor."],["Kepala Biro Keuangan","R","Menyiapkan rancangan anggaran dan rekening penerimaan."],["Kepala Biro Desain Komunikasi Visual","R","Menyiapkan tampilan proposal dan materi kompensasi."],["Kepala Biro Kesekretariatan","R","Menerbitkan dan mengirim surat pengajuan serta mencatat Register Sponsor."],["Presiden","R","Menyetujui proposal dan daftar target sponsor."],["Inspektur Jenderal","C","Memeriksa kesesuaian calon sponsor dengan syariat, AD/ART, dan peraturan kampus."],["Pembina / KAUR ORMAWA","C","Memberi pertimbangan atas hal yang meragukan."],["Calon sponsor","I","Menerima proposal dan memberi tanggapan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Keputusan program kerja dan rancangan anggaran biaya yang disahkan.","Rincian kebutuhan dukungan dan paket kompensasi.","Daftar target sponsor dan daftar tolak.","Rekening atau kas organisasi yang ditetapkan Biro Keuangan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penentuan kebutuhan: Menentukan bentuk dan jumlah dukungan yang dibutuhkan berdasarkan rancangan anggaran biaya.","Penanggung jawab kegiatan","Program kerja, anggaran","Rincian kebutuhan","2 hari kerja"],["2","Penyusunan proposal: Menyusun Proposal Sponsor dan paket kompensasi yang wajar, serta merancang tampilannya.","Penanggung jawab kegiatan dan Biro DKV","Rincian kebutuhan","Proposal sponsor","5 hari kerja"],["3","Penyaringan calon sponsor: Menyusun daftar target dan menyaring dengan Daftar Periksa Sponsor: bidang halal, afiliasi, reputasi, dan konflik kepentingan.","Menteri Hubungan Eksternal","Daftar target, daftar tolak","Daftar sponsor lolos saring","3 hari kerja"],["4","Pemeriksaan: Memeriksa kesesuaian calon sponsor dan paket kompensasi dengan syariat, AD/ART, dan peraturan kampus; Biro Keuangan memeriksa kesesuaian dengan anggaran.","Irjen dan Kepala Biro Keuangan","Proposal, daftar sponsor","Catatan pemeriksaan","2 hari kerja"],["5","Persetujuan: Menyetujui proposal dan daftar target; hal yang meragukan dikonsultasikan kepada Pembina atau KAUR ORMAWA.","Presiden","Proposal, catatan pemeriksaan","Persetujuan tercatat","2 hari kerja"],["6","Pengiriman: Mengirim proposal melalui surat resmi, mencatat pada Register Sponsor, dan memastikan kontak resmi BEM.","Kepala Biro Kesekretariatan","Proposal disetujui","Surat terkirim, entri Register","2 hari kerja"],["7","Tindak lanjut: Menindaklanjuti tanggapan, menjelaskan paket, dan mencatat setiap pertemuan atau percakapan penting (SOP-HKE-012).","Menteri Hubungan Eksternal","Tanggapan sponsor","Catatan tindak lanjut","Setiap ada tanggapan"],["8","Pencatatan keputusan: Mencatat sponsor yang setuju, menolak, atau menunda; sponsor yang setuju diproses menurut SOP-HKE- 008.","Menteri Hubungan Eksternal dan Sekjen","Tanggapan akhir","Register Sponsor diperbarui","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Proposal sponsor diajukan paling lambat 30 hari sebelum kegiatan (usulan). Dari penentuan kebutuhan hingga pengiriman proposal ditargetkan paling lambat 14 hari kerja. Hasil akhir: proposal terkirim dan Register Sponsor diperbarui."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Calon sponsor bidangnya meragukan: dikonsultasikan kepada Pembina atau KAUR ORMAWA; selama belum jelas, proposal tidak dikirim.","Sponsor mengajukan syarat yang mengikat atau mengintervensi acara: ditolak atau dinegosiasi ulang; dilaporkan kepada Presiden.","Pengurus atau panitia meminta sponsor atas nama pribadi atau menerima dana tunai: dihentikan dan dilaporkan kepada Irjen; SOP-RSK-007.","Dukungan sponsor kurang dari kebutuhan: SOP-KEU-014 (penanganan selisih anggaran)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% proposal sponsor disetujui Presiden sebelum dikirim.","100% calon sponsor lolos Daftar Periksa Sponsor.","Tidak ada penerimaan dana sponsor melalui pengurus perseorangan.","Register Sponsor diperbarui paling lambat 1 hari kerja setelah ada tanggapan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Rincian kebutuhan dan Proposal Sponsor.","Daftar Periksa Sponsor dan daftar tolak.","Persetujuan Presiden dan surat pengajuan.","Register Sponsor. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri Hubungan Eksternal dan Kepala Biro Keuangan meninjau Register Sponsor setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Penentuan kebutuhan → Penyusunan proposal → Penyaringan calon sponsor → Pemeriksaan → Persetujuan Presiden → Pengiriman → Tindak lanjut → Pencatatan keputusan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Proposal Sponsor","Latar belakang dan tujuan kegiatan; waktu dan tempat; sasaran peserta; kebutuhan dukungan; paket kompensasi; kontak resmi; rekening organisasi; lampiran."],["Daftar Periksa Sponsor","Bidang usaha halal; bebas riba, gharar, dan maysir; tidak termasuk daftar tolak; afiliasi politik; reputasi; konflik kepentingan; paket tidak mengikat."],["Register Sponsor","Nomor; calon sponsor; kegiatan; bentuk dukungan; tanggal kirim; tanggapan; status; keterangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kegiatan termasuk program kerja sah dan memiliki anggaran.","☐ Ya ☐ Tidak"],["2","Calon sponsor lolos Daftar Periksa Sponsor.","☐ Ya ☐ Tidak"],["3","Hal meragukan telah dikonsultasikan kepada Pembina atau KAUR ORMAWA.","☐ Ya ☐ Tidak"],["4","Proposal disetujui Presiden sebelum dikirim.","☐ Ya ☐ Tidak"],["5","Proposal memakai surat resmi dan rekening organisasi.","☐ Ya ☐ Tidak"],["6","Register Sponsor diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Hubungan Eksternal; Kepala Biro Keuangan; Kepala Biro Kesekretariatan; Kepala Biro DKV. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-008","g":"Hubungan Eksternal dan Kemitraan","t":"Penerimaan Sponsor dan Pemenuhan Kewajibannya","o":"Menteri Hubungan Eksternal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Hubungan Eksternal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[701,705],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penerimaan dukungan sponsor yang sah, tercatat, dan transparan, serta pemenuhan kompensasi yang telah disepakati dan pelaporannya kepada sponsor dan organisasi, sehingga hubungan dengan sponsor terjaga dan tidak ada kewajiban yang melampaui kesepakatan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku sejak sponsor menyatakan bersedia sampai laporan akhir kepada sponsor, mencakup penerimaan dana, barang, atau jasa, pembuatan kesepakatan, pemenuhan kompensasi, dan penutupan. Pengajuan sponsor mengikuti SOP-HKE-007; pembukuan dan pelaporan keuangan mengikuti SOP-KEU-005, SOP-KEU-012, SOP-KEU-013, dan SOP-KEU-015."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) huruf b, ayat (2), dan ayat (3) (dukungan tidak mengikat, bebas riba, gharar, dan maysir, serta bukti penerimaan resmi).","AD Pasal 17 ayat (1) sampai (3) (laporan pertanggungjawaban yang transparan dan akuntabel).","ART Pasal 2 huruf e dan f (kerja sama yang halal dan tidak mengikat serta pengelolaan pendanaan sesuai syariah).","ART Pasal 3 huruf e dan g (Kewajiban: pengelolaan keuangan amanah dan laporan berkala).","ART Pasal 11 huruf i dan k (larangan korupsi, manipulasi, dan penyalahgunaan nama atau fasilitas organisasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kesepakatan sponsor","Dokumen tertulis yang memuat bentuk dukungan, nilai, kompensasi, dan jangka waktu (SOP-HKE-006)."],["Bukti penerimaan resmi","Kuitansi, tanda terima, atau bukti transfer yang tercatat atas nama organisasi."],["Kompensasi","Hak publikasi atau penyebutan wajar yang disepakati untuk sponsor."],["Sponsor in-kind","Dukungan berupa barang atau jasa yang diterima dengan berita acara dan nilai taksiran."],["Laporan sponsor","Laporan pemenuhan kompensasi dan ringkasan hasil kegiatan kepada sponsor."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Dana sponsor hanya masuk ke rekening atau kas organisasi atau rekening kegiatan yang ditetapkan Biro Keuangan, tidak ke rekening pribadi pengurus (SOP-KEU-009).","Setiap penerimaan dibuktikan dengan bukti penerimaan resmi dan dicatat paling lambat 1 hari kerja (AD Pasal 15 ayat 3; SOP-KEU-005).","Kesepakatan sponsor dibuat tertulis dan tidak mengikat; kompensasi dibatasi pada hal yang disepakati dan tidak memuat unsur yang dilarang syariat.","Barang atau jasa diterima dengan Berita Acara Serah Terima, dicatat nilai taksirannya, dan barang yang menjadi aset BEM dicatat pada inventaris (SOP-AST-001).","Penggunaan logo sponsor pada materi BEM mengikuti SOP-KOM-014; materi kompensasi diperiksa sebelum dipublikasikan.","Dukungan yang disertai syarat mengikat, intervensi, atau bertentangan dengan syariat ditolak atau dikembalikan.","Kelebihan atau kekurangan dana mengikuti SOP-KEU-018 dan SOP-KEU-014.","Laporan kepada sponsor disampaikan paling lambat 14 hari kerja setelah kegiatan, sebatas yang disepakati."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Hubungan Eksternal","A","Bertanggung jawab atas hubungan dengan sponsor, pemenuhan kompensasi, dan pelaporan kepada sponsor."],["Presiden","R","Menyetujui penerimaan dan menandatangani kesepakatan sponsor."],["Kepala Biro Keuangan","R","Menerima, mencatat, dan membukukan dana serta menyusun pelaporan keuangan sponsor."],["Penanggung jawab kegiatan","R","Memenuhi kompensasi, mendokumentasikan, dan melapor."],["Kepala Biro DKV","R","Menyiapkan materi publikasi sponsor sesuai kesepakatan."],["Sekretaris Jenderal","R","Menyusun kesepakatan dan berita acara serta mengarsipkan."],["Inspektur Jenderal","C","Memeriksa penerimaan dan kesesuaian pemenuhan kompensasi."],["Sponsor","I","Menerima kompensasi dan laporan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Konfirmasi tertulis kesediaan sponsor.","Kesepakatan sponsor (SOP-HKE-006).","Rekening organisasi dan Rancangan Anggaran Biaya kegiatan.","Daftar kompensasi yang disepakati dan jadwal pemenuhannya."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Konfirmasi komitmen: Menerima konfirmasi tertulis sponsor tentang bentuk, nilai, dan syarat dukungan, serta memeriksa kesesuaiannya dengan proposal.","Menteri Hubungan Eksternal","Tanggapan sponsor","Konfirmasi komitmen","2 hari kerja"],["2","Kesepakatan sponsor: Menyusun dan menandatangani kesepakatan tertulis sesuai SOP-HKE- 006 setelah memeriksa tidak adanya syarat mengikat.","Sekjen dan Presiden","Konfirmasi komitmen","Kesepakatan bertanda tangan","3 hari kerja"],["3","Penerimaan dukungan: Menerima dana melalui rekening atau kas organisasi; menerima barang atau jasa dengan Berita Acara Serah Terima.","Kepala Biro Keuangan","Kesepakatan, bukti transfer atau barang","Bukti penerimaan resmi","Sesuai jadwal kesepakatan"],["4","Pencatatan: Mencatat penerimaan pada pembukuan kegiatan dan Register Sponsor serta menandai peruntukannya.","Kepala Biro Keuangan","Bukti penerimaan","Catatan keuangan dan Register","1 hari kerja"],["5","Pemenuhan kompensasi: Melaksanakan kompensasi sesuai daftar, memeriksa materi sebelum publikasi, dan mendokumentasikannya.","Penanggung jawab kegiatan dan Biro DKV","Daftar kompensasi","Bukti pemenuhan kompensasi","Sesuai jadwal kegiatan"],["6","Pemantauan kewajiban: Memantau pemenuhan kompensasi dengan Daftar Pemenuhan Kewajiban dan melaporkan kekurangan kepada Presiden.","Menteri Hubungan Eksternal","Daftar pemenuhan","Daftar terisi","Mingguan selama kegiatan"],["7","Laporan dan terima kasih: Mengirim ucapan terima kasih resmi dan laporan sponsor yang memuat bukti kompensasi dan ringkasan hasil kegiatan.","Menteri Hubungan Eksternal","Bukti kompensasi, laporan kegiatan","Laporan sponsor terkirim","14 hari kerja setelah kegiatan"],["8","Pemeriksaan dan penutupan: Merekonsiliasi dana, memastikan seluruh kewajiban terpenuhi, memperbarui basis data mitra, dan menutup berkas.","Kepala Biro Keuangan dan Irjen","Catatan keuangan, daftar pemenuhan","Berkas ditutup","7 hari kerja setelah laporan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pencatatan penerimaan paling lambat 1 hari kerja, laporan kepada sponsor paling lambat 14 hari kerja setelah kegiatan, dan penutupan berkas paling lambat 7 hari kerja setelah laporan. Hasil akhir: kesepakatan sponsor, bukti penerimaan, bukti kompensasi, dan laporan sponsor."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Dana sponsor masuk ke rekening pribadi: segera dipindahkan ke kas organisasi paling lambat 1 hari kerja dan dilaporkan kepada Irjen (SOP-RSK-007).","Sponsor meminta tambahan kompensasi di luar kesepakatan: ditolak atau dibuat addendum yang disetujui Presiden.","Sponsor batal atau mengurangi dukungan: Biro Keuangan menyesuaikan anggaran (SOP-KEU-014) tanpa membuat utang di luar persetujuan (SOP-KEU-019).","Kompensasi tidak terpenuhi: Menteri Hubungan Eksternal menyampaikan klarifikasi dan perbaikan kepada sponsor serta melaporkannya kepada Presiden.","Dana masuk tanpa kesepakatan atau tidak dikenal: ditahan dan dikonfirmasi kepada pengirim sebelum digunakan."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% dukungan sponsor memiliki bukti penerimaan resmi dan tercatat dalam 1 hari kerja.","100% kompensasi yang disepakati terpenuhi dan terdokumentasi.","Laporan sponsor terkirim paling lambat 14 hari kerja setelah kegiatan.","Tidak ada temuan Irjen berupa dana sponsor melalui rekening pribadi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Kesepakatan sponsor bertanda tangan dan Berita Acara Serah Terima.","Bukti penerimaan resmi dan catatan keuangan.","Daftar Pemenuhan Kewajiban dan bukti kompensasi.","Laporan sponsor dan surat ucapan terima kasih. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro Keuangan merekonsiliasi penerimaan sponsor setiap bulan bersama Menteri Hubungan Eksternal; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Konfirmasi komitmen → Kesepakatan sponsor → Penerimaan dukungan → Pencatatan → Pemenuhan kompensasi → Pemantauan kewajiban → Laporan dan terima kasih → Pemeriksaan dan penutupan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Kesepakatan Sponsor","Para pihak; kegiatan; bentuk dan nilai dukungan; kompensasi; jangka waktu; pernyataan tidak mengikat; rekening organisasi; penandatangan."],["Berita Acara Serah Terima Dukungan","Tanggal; pemberi dan penerima; jenis dan jumlah barang atau jasa; nilai taksiran; kondisi; saksi; tanda tangan."],["Daftar Pemenuhan Kewajiban","Kompensasi yang disepakati; tenggat; penanggung jawab; bukti; status; paraf pemeriksa."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kesepakatan sponsor tertulis dan tidak mengikat.","☐ Ya ☐ Tidak"],["2","Dana masuk ke rekening atau kas organisasi dengan bukti penerimaan resmi.","☐ Ya ☐ Tidak"],["3","Penerimaan dicatat dalam 1 hari kerja.","☐ Ya ☐ Tidak"],["4","Seluruh kompensasi terpenuhi dan terdokumentasi.","☐ Ya ☐ Tidak"],["5","Laporan sponsor terkirim dalam 14 hari kerja.","☐ Ya ☐ Tidak"],["6","Rekonsiliasi dan penutupan berkas selesai.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Hubungan Eksternal; Kepala Biro Keuangan; Kepala Biro Kesekretariatan; Kepala Biro DKV. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-009","g":"Hubungan Eksternal dan Kemitraan","t":"Penerimaan Kunjungan Tamu dan Mitra","o":"Menteri Hubungan Eksternal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Hubungan Eksternal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[706,709],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penjadwalan, persiapan, penerimaan, pendampingan, dan tindak lanjut kunjungan tamu dan mitra kepada BEM, sehingga penerimaan berlangsung ramah, tertib, aman, sesuai adab Islami dan tata tertib kampus, serta menjaga nama baik STDIIS Jember."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk kunjungan mahasiswa, ORMAWA atau BEM lain, instansi, mitra, sponsor, dan tokoh ke sekretariat atau kegiatan BEM, atau ke kampus dengan sepengetahuan BEM. Acara resmi berskala besar mengikuti SOP-HKE-010; penggunaan ruang sekretariat mengikuti SOP-AST-005; pembahasan kerja sama mengikuti SOP-HKE-005."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 huruf b dan d (Kewajiban: menjaga ukhuwah Islamiyah serta nama baik, ketertiban, dan kedamaian lingkungan kampus).","ART Pasal 2 huruf b dan i (penggunaan identitas resmi dan fasilitas kampus).","ART Bab III (Tugas BEM) huruf d (koordinasi dan kerja sama dengan ORMAWA dan pihak eksternal perguruan tinggi).","ART Pasal 4 huruf e (mewakili mahasiswa dalam forum resmi).","ART Pasal 11 huruf a, e, g, dan h (larangan SARA, politik praktis tanpa izin, mencemarkan nama baik, dan tindakan asusila atau pelecehan).","AD Pasal 18 ayat (3) (seragam resmi BEM adalah PDH BEM)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Tamu","Pihak eksternal yang berkunjung kepada BEM, termasuk mitra, sponsor, perwakilan ORMAWA lain, dan tokoh."],["Pendamping tamu","Pengurus yang ditunjuk menemani tamu sejak kedatangan sampai kepulangan."],["Agenda kunjungan","Rangkaian acara kunjungan yang disepakati kedua pihak."],["Buku tamu","Catatan kehadiran tamu beserta tujuan kunjungan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Kunjungan dijadwalkan melalui Menteri Hubungan Eksternal dan dikonfirmasi tertulis; kunjungan tanpa pemberitahuan diterima seperlunya setelah menghubungi pimpinan.","Tamu dari luar kampus yang memasuki lingkungan kampus diberitahukan kepada KAUR ORMAWA atau petugas kampus sesuai aturan kampus.","Penerimaan menjaga adab Islami dan tata tertib kampus, termasuk pengaturan interaksi tamu putra dan putri, waktu salat, dan jamuan yang halal.","Setiap kunjungan didampingi sekurang-kurangnya dua pengurus berpakaian PDH BEM, satu di antaranya pencatat.","Pembahasan sikap atau komitmen BEM hanya oleh pimpinan atau penerima mandat; pengurus lain tidak membuat komitmen (SOP-HKE-011).","Tamu tidak diberi akses terhadap dokumen rahasia atau data pribadi pengurus (SOP-ADM-020 dan SOP-RSK-010).","Dokumentasi dan publikasi kunjungan dilakukan dengan sepengetahuan tamu dan persetujuan Presiden (SOP-KOM-010).","Kunjungan bernuansa kampanye atau politik praktis tidak diterima tanpa izin kampus; jamuan dan cendera mata mengikuti anggaran dan dicatat."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Hubungan Eksternal","A","Bertanggung jawab atas penjadwalan, pendampingan, dan tindak lanjut kunjungan."],["Kepala Biro Kesekretariatan","R","Menerima permohonan, menyusun surat, dan mengelola buku tamu."],["Pendamping tamu","R","Menyambut, mendampingi, dan mencatat jalannya kunjungan."],["Presiden / Wakil Presiden","R","Menerima tamu penting dan memutuskan kunjungan yang sensitif."],["Tim Acara","R","Menyiapkan ruang, perlengkapan, dan jamuan."],["Inspektur Jenderal","C","Menelaah kunjungan yang berpotensi bertentangan dengan AD/ART bila diminta."],["KAUR ORMAWA","C","Menerima pemberitahuan dan memberi arahan sesuai aturan kampus."],["Tamu","I","Menerima agenda dan tata tertib kunjungan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Permohonan atau pemberitahuan kunjungan beserta tujuan dan jumlah tamu.","Kalender organisasi dan ketersediaan ruang.","Anggaran jamuan dan perlengkapan.","Daftar pengurus pendamping."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan permohonan: Mencatat permohonan atau pemberitahuan kunjungan, tujuan, jumlah, dan susunan tamu.","Kepala Biro Kesekretariatan","Permohonan kunjungan","Entri permohonan","1 hari kerja"],["2","Penilaian dan keputusan: Menilai tujuan, kategori, dan risiko kunjungan; kunjungan penting atau sensitif diputuskan Presiden.","Menteri Hubungan Eksternal dan Presiden","Entri permohonan","Keputusan menerima, menunda, atau menolak","2 hari kerja"],["3","Koordinasi kampus: Memberitahukan kunjungan kepada KAUR ORMAWA atau petugas kampus dan memesan ruang bila diperlukan.","Kepala Biro Kesekretariatan","Keputusan","Pemberitahuan terkirim, ruang tersedia","2 hari kerja"],["4","Persiapan: Menyusun agenda kunjungan, menunjuk pendamping, menyiapkan ruang, jamuan halal, bahan, dan lembar tata tertib.","Menteri Hubungan Eksternal dan Tim Acara","Keputusan, jadwal","Agenda dan persiapan siap","2 hari kerja sebelum kunjungan"],["5","Penyambutan dan pelaksanaan: Menyambut tamu, mengisi buku tamu, melaksanakan agenda, dan mencatat pembahasan serta permintaan tamu.","Pendamping tamu","Agenda kunjungan","Buku tamu, catatan kunjungan","Sesuai agenda"],["6","Dokumentasi dan cendera mata: Mendokumentasikan kunjungan dengan sepengetahuan tamu dan memberi atau menerima cendera mata sesuai anggaran serta mencatatnya.","Pendamping tamu","Anggaran, daftar cendera mata","Dokumentasi, catatan cendera mata","Saat kunjungan"],["7","Pelepasan dan terima kasih: Mengantar tamu, mengirim ucapan terima kasih resmi, dan menyampaikan tindak lanjut yang dijanjikan.","Menteri Hubungan Eksternal","Catatan kunjungan","Ucapan terima kasih terkirim","2 hari kerja"],["8","Laporan dan pembaruan data: Menyusun laporan sesuai SOP-HKE- 012 dan memperbarui basis data mitra sesuai SOP-HKE-013.","Pendamping tamu dan Menteri Hubungan Eksternal","Catatan kunjungan","Laporan, data mitra diperbarui","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Keputusan kunjungan paling lambat 2 hari kerja setelah permohonan, jadwal terkonfirmasi paling lambat 2 hari kerja sebelum kunjungan, dan laporan paling lambat 3 hari kerja setelah kunjungan. Hasil akhir: catatan kunjungan, laporan, dan data mitra yang diperbarui."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Tamu datang tanpa pemberitahuan: pendamping menghubungi pimpinan; tamu dipersilakan menunggu di ruang yang ditentukan sampai ada keputusan.","Tamu meminta komitmen, dukungan dana, atau pernyataan atas nama BEM: dibawa ke pimpinan; tidak dijawab di tempat (SOP-HKE-005 atau SOP-HKE-007).","Tamu atau pengurus melanggar tata tertib atau adab: pendamping menegur dengan santun dan melaporkannya kepada Presiden; SOP-SDM-013 bila pelanggar adalah pengurus.","Keadaan darurat saat kunjungan: SOP-RSK-003."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% kunjungan tercatat pada buku tamu dan memiliki pendamping.","Tidak ada komitmen yang dibuat tanpa keputusan pimpinan.","Laporan kunjungan diterima paling lambat 3 hari kerja.","Tidak ada keluhan tamu atau kampus yang berkaitan dengan adab dan ketertiban."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Buku tamu dan catatan kunjungan.","Agenda kunjungan dan pemberitahuan kepada kampus.","Dokumentasi dan catatan cendera mata.","Laporan kunjungan dan ucapan terima kasih. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri Hubungan Eksternal meninjau buku tamu dan laporan kunjungan setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima permohonan → Penilaian dan keputusan → Koordinasi kampus → Persiapan → Penyambutan dan pelaksanaan → Pelepasan dan terima kasih → Laporan dan pembaruan data → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permohonan Kunjungan","Nama tamu atau lembaga; tujuan; tanggal dan waktu usulan; jumlah tamu; kebutuhan khusus; kontak; tanggal permohonan."],["Buku Tamu","Tanggal; nama dan asal; tujuan; pengurus yang menemui; waktu masuk dan keluar; tanda tangan."],["Catatan Kunjungan","Tanggal; tamu; pendamping; pembahasan; permintaan tamu; janji atau tindak lanjut; cendera mata; pencatat."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Permohonan kunjungan tercatat dan diputuskan.","☐ Ya ☐ Tidak"],["2","Kampus diberi tahu sesuai aturan kampus.","☐ Ya ☐ Tidak"],["3","Pendamping minimal dua pengurus berpakaian PDH BEM.","☐ Ya ☐ Tidak"],["4","Jamuan halal dan adab pergaulan terjaga.","☐ Ya ☐ Tidak"],["5","Tidak ada komitmen yang dibuat tanpa mandat.","☐ Ya ☐ Tidak"],["6","Laporan dan pembaruan data mitra selesai dalam 3 hari kerja.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Hubungan Eksternal; Kepala Biro Kesekretariatan; Tim Acara. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-010","g":"Hubungan Eksternal dan Kemitraan","t":"Protokoler Acara Resmi dan Penerimaan Tamu","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[710,713],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan tata urutan, tata tempat, tata penyambutan, tata busana, dan adab pelaksanaan acara resmi BEM, sehingga penghormatan kepada tamu proporsional, acara berlangsung tertib dan islami, serta sesuai ketentuan kampus."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk acara resmi yang diselenggarakan BEM atau yang menempatkan BEM sebagai tuan rumah atau peserta kehormatan, seperti pelantikan, seminar, penerimaan tamu pimpinan, audiensi resmi, dan penandatanganan kerja sama. Teknis panitia dan rundown kegiatan mengikuti SOP-PRO; kunjungan kecil mengikuti SOP-HKE-009."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 8 ayat (4) (Presiden BEM disahkan dan dilantik oleh Ketua STDI Imam Syafi'i Jember).","AD Pasal 18 ayat (1) sampai (3) (lambang yang disahkan dan seragam resmi PDH BEM).","ART Pasal 2 huruf b (penggunaan nama, lambang, dan identitas resmi yang disetujui STDIIS Jember).","ART Pasal 3 huruf a sampai d (Kewajiban: prinsip Ahlus Sunnah wal Jama'ah, ukhuwah, nilai-nilai Islam, dan nama baik kampus).","ART Pasal 4 huruf e (mewakili mahasiswa dalam forum resmi).","ART Pasal 11 huruf a dan g (larangan SARA dan mencemarkan nama baik)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Protokoler","Aturan tata urutan, tata tempat, dan tata penghormatan dalam acara resmi."],["Urutan kehormatan","Urutan penghormatan tamu dan pejabat dalam penempatan, sambutan, dan penyambutan."],["Penghubung tamu (liaison)","Pengurus yang menjadi penghubung tunggal antara panitia dan satu tamu penting."],["Gladi bersih","Latihan akhir seluruh rangkaian acara sebelum hari pelaksanaan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Aturan kampus mengenai protokoler didahulukan; bila kampus tidak menetapkan, BEM memakai urutan kehormatan berikut (usulan): Ketua STDIIS atau pimpinan kampus, Pembina atau KAUR ORMAWA, tamu eksternal, pimpinan BEM, perwakilan ORMAWA, lalu pengurus dan peserta.","Acara dibuka dengan ucapan basmalah, tilawah, dan doa, serta memperhatikan waktu salat; susunan acara tidak memuat unsur yang dilarang syariat dan peraturan kampus.","Tata busana pengurus adalah PDH BEM kecuali ditentukan lain; tata pergaulan putra dan putri mengikuti syariat dan tata tertib kampus.","Hanya lambang dan atribut yang disahkan STDIIS Jember yang dipasang pada acara (AD Pasal 18).","Naskah sambutan Presiden dan pembawa acara disiapkan dan diperiksa sebelum acara; hanya satu juru bicara yang menanggapi media atau tamu.","Setiap tamu penting memiliki penghubung tamu; tamu dijemput, dikawal, dan diantar sesuai tata tempat.","Acara besar wajib melalui gladi bersih; keselamatan dan keadaan darurat mengikuti SOP-PRO-017.","Dokumentasi dan publikasi acara mengikuti SOP-KOM-011 dan SOP-KOM-010."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Bertanggung jawab atas penetapan tata acara, tata tempat, dan pengawasan pelaksanaan protokoler."],["Tim Acara","R","Menyusun susunan acara, tata tempat, pembagian peran, dan memimpin gladi bersih."],["Presiden","R","Menerima tamu utama, menyampaikan sambutan, dan menyetujui susunan acara."],["Menteri Hubungan Eksternal","R","Mengundang dan menghubungi tamu eksternal serta menunjuk penghubung tamu."],["Kepala Biro DKV","R","Menyiapkan spanduk, tata visual, dan dokumentasi sesuai ketentuan."],["Wakil Presiden","C","Memberi pertimbangan dan mendampingi tamu."],["Inspektur Jenderal","C","Memeriksa kesesuaian tata acara dengan AD/ART bila diminta."],["Pembina / KAUR ORMAWA","C","Memberi arahan protokoler kampus."],["Seluruh pengurus dan panitia","I","Menjalankan peran sesuai pembagian."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Keputusan penyelenggaraan acara dan program kerja yang sah.","Daftar tamu dan pejabat yang diundang.","Aturan protokoler kampus.","Ketersediaan tempat, perlengkapan, dan anggaran."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan jenis acara dan tamu: Menetapkan jenis, tingkat formalitas, dan daftar tamu acara.","Sekjen dan Presiden","Program kerja, aturan kampus","Daftar tamu awal","2 hari kerja"],["2","Susunan acara: Menyusun susunan acara, durasi, tata busana, dan pembagian peran (pembawa acara, doa, penerima tamu, penghubung tamu).","Tim Acara","Daftar tamu awal","Susunan acara","3 hari kerja"],["3","Tata tempat dan urutan kehormatan: Menetapkan tata tempat duduk, jalur masuk, dan urutan kehormatan sesuai aturan kampus.","Tim Acara","Susunan acara, aturan kampus","Denah dan urutan kehormatan","2 hari kerja"],["4","Undangan dan konfirmasi: Mengirim undangan resmi, mengonfirmasi kehadiran, dan menyusun daftar tamu final.","Menteri Hubungan Eksternal dan Biro Kesekretariatan","Daftar tamu, susunan acara","Daftar tamu final","Final paling lambat 3 hari sebelum acara"],["5","Persiapan visual dan naskah: Menyiapkan spanduk, atribut, naskah sambutan, naskah pembawa acara, dan kelengkapan dokumentasi.","Biro DKV dan Tim Acara","Susunan acara","Perlengkapan dan naskah siap","3 hari kerja"],["6","Gladi bersih: Melatih seluruh rangkaian acara, jalur tamu, dan penanganan keadaan darurat.","Tim Acara","Susunan acara, denah","Catatan perbaikan gladi","1 hari sebelum acara"],["7","Pelaksanaan: Melaksanakan acara sesuai susunan, menyambut dan mengantar tamu, serta mengendalikan waktu dan adab.","Tim Acara dan penghubung tamu","Susunan acara","Acara terlaksana","Sesuai jadwal"],["8","Penutupan dan evaluasi: Melepas tamu, mengirim ucapan terima kasih, mengumpulkan dokumentasi, dan mengevaluasi protokoler.","Sekjen","Dokumentasi, catatan gladi","Evaluasi singkat, laporan","2 hari kerja setelah acara"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Susunan acara selesai paling lambat 7 hari sebelum acara, daftar tamu final paling lambat 3 hari sebelum acara, dan gladi bersih 1 hari sebelum acara. Hasil akhir: acara terlaksana sesuai protokoler dan evaluasi singkat."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Perbedaan tafsir urutan kehormatan: mengikuti arahan Pembina atau KAUR ORMAWA; selama belum jelas, memakai urutan yang paling menghormati pimpinan kampus.","Tamu tiba lebih cepat atau terlambat: penghubung tamu menyesuaikan agenda dengan persetujuan Sekjen atau Presiden.","Perubahan mendadak pada susunan acara: diputuskan Sekjen dan dilaporkan kepada Presiden (SOP- GOV-012 bila menyangkut keputusan penting).","Pelanggaran adab atau tata tertib oleh pengurus atau panitia: SOP-SDM-013.","Insiden keselamatan: SOP-PRO-017 dan SOP-RSK-003."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Acara resmi berlangsung sesuai susunan dan tanpa keluhan protokoler dari kampus atau tamu.","100% tamu penting memiliki penghubung tamu.","Acara besar melalui gladi bersih.","Evaluasi protokoler diselesaikan paling lambat 2 hari kerja setelah acara."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Susunan acara, denah tempat, dan urutan kehormatan.","Daftar tamu final.","Naskah sambutan dan pembawa acara.","Catatan gladi bersih dan evaluasi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan dokumen protokoler setiap acara resmi; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Penetapan acara dan tamu → Susunan acara → Tata tempat dan urutan kehormatan → Undangan dan konfirmasi → Persiapan visual dan naskah → Gladi bersih → Pelaksanaan → Penutupan dan evaluasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Susunan Acara dan Pembagian Peran","Nama acara; hari, tanggal, dan tempat; urutan acara beserta durasi; penanggung jawab tiap mata acara; tata busana."],["Daftar Tamu dan Urutan Kehormatan","Nama dan jabatan; asal lembaga; status konfirmasi; tempat duduk; penghubung tamu; keterangan khusus."],["Catatan Gladi Bersih","Tanggal; hal yang diuji; temuan; perbaikan; penanggung jawab; status."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Aturan protokoler kampus telah dipenuhi.","☐ Ya ☐ Tidak"],["2","Susunan acara tidak memuat unsur yang dilarang syariat dan aturan kampus.","☐ Ya ☐ Tidak"],["3","Hanya lambang dan atribut yang disahkan yang dipasang.","☐ Ya ☐ Tidak"],["4","Setiap tamu penting memiliki penghubung tamu.","☐ Ya ☐ Tidak"],["5","Gladi bersih telah dilaksanakan untuk acara besar.","☐ Ya ☐ Tidak"],["6","Evaluasi protokoler selesai dalam 2 hari kerja.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Hubungan Eksternal; Biro Kesekretariatan; Biro DKV; Tim Acara. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-011","g":"Hubungan Eksternal dan Kemitraan","t":"Pemberian Mandat kepada Delegasi","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[714,717],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pemberian, pembatasan, pencatatan, perubahan, dan pencabutan mandat kepada delegasi yang mewakili sikap BEM, bernegosiasi, atau menandatangani dokumen pada forum eksternal, sehingga setiap tindakan atas nama BEM sah, terbatas, dan dapat dipertanggungjawabkan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk mandat kepada pengurus yang mewakili BEM di luar BEM: menyampaikan sikap, bernegosiasi, atau menandatangani dokumen. SOP ini berbeda dari pendelegasian wewenang internal (SOP-GOV-008) dan Surat Tugas kehadiran biasa (SOP-HKE-002). Penerbitan surat mandat secara administratif mengikuti SOP- ADM-006."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf e dan f (mewakili mahasiswa sebagai pimpinan tertinggi eksekutif dan menandatangani surat resmi serta dokumen organisasi).","AD Pasal 13 (pimpinan BEM terdiri atas Presiden, Wakil Presiden, dan Sekretariat Jenderal).","ART Pasal 2 huruf e (kerja sama dengan pihak eksternal dengan persetujuan Ketua STDIIS).","ART Pasal 11 huruf e, g, dan k (larangan politik praktis tanpa izin, mencemarkan nama baik, dan memakai nama organisasi untuk kepentingan pribadi).","ART Pasal 12 dan 13 (jenis sanksi serta mekanisme pemberian sanksi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Mandat","Kewenangan tertulis dari Presiden kepada seorang pengurus untuk bertindak atas nama BEM dalam batas tertentu."],["Mandat kehadiran","Mandat untuk mewakili BEM secara kehadiran tanpa menyatakan sikap atau mengambil keputusan."],["Mandat sikap","Mandat untuk menyampaikan sikap BEM yang telah diputuskan pimpinan."],["Mandat penandatanganan","Mandat untuk menandatangani dokumen tertentu atas nama BEM."],["Batas mandat","Rincian hal yang boleh dan tidak boleh dilakukan penerima mandat."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pemberi mandat atas nama BEM adalah Presiden; Wakil Presiden atau Sekretaris Jenderal hanya dalam hal Presiden berhalangan sesuai SOP-GOV-008 dan SOP-GOV-009.","Mandat selalu tertulis, memuat forum, tanggal, jenis mandat, batas mandat, dan masa berlaku; mandat lisan hanya pada keadaan mendesak dan dicatat tertulis paling lambat 1 hari kerja (SOP-GOV-012).","Mandat sikap hanya diberikan atas sikap yang telah diputuskan pimpinan secara musyawarah (SOP- GOV-002).","Mandat penandatanganan atas kerja sama baru hanya diberikan setelah persetujuan kampus (SOP- HKE-005).","Penerima mandat tidak mengalihkan mandat kepada pihak lain tanpa persetujuan tertulis Presiden; hal di luar mandat dijawab dengan akan dibawa kepada pimpinan.","Tindakan di luar batas mandat tidak mengikat BEM dan dapat dikenai sanksi sesuai ART Pasal 12 dan 13.","Mandat berakhir otomatis pada akhir masa berlaku atau dapat dicabut Presiden sewaktu-waktu dengan pemberitahuan tertulis."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Bertanggung jawab akhir atas pemberian, perubahan, dan pencabutan mandat serta menandatangani Surat Mandat."],["Sekretaris Jenderal","R","Menyusun Surat Mandat, mencatatnya pada Register Mandat, dan mengarsipkan."],["Menteri Hubungan Eksternal","R","Menyiapkan bahan mandat, poin sikap, dan pembekalan penerima mandat."],["Penerima mandat","R","Menjalankan mandat dalam batasnya dan melapor."],["Wakil Presiden","C","Memberi pertimbangan sikap dan batas mandat."],["Inspektur Jenderal","C","Memeriksa kesesuaian mandat dengan AD/ART dan memantau pelampauan mandat."],["Pihak eksternal","I","Menerima salinan Surat Mandat bila diminta."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Keputusan pimpinan tentang sikap atau kebutuhan penandatanganan.","Informasi forum eksternal: agenda, waktu, dan peserta.","Surat Tugas delegasi (SOP-HKE-002).","Persetujuan kampus untuk kerja sama baru (bila ada)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Permintaan mandat: Mengajukan Formulir Permintaan Mandat: forum, agenda, hal yang akan dibahas atau ditandatangani, dan jenis mandat.","Menteri Hubungan Eksternal atau penerima calon","Undangan, agenda forum","Formulir permintaan mandat","2 hari kerja sebelum forum"],["2","Perumusan batas mandat: Menyusun poin sikap dan batas mandat: hal yang boleh disampaikan, tidak boleh disampaikan, dan harus dikonsultasikan.","Menteri Hubungan Eksternal bersama Sekjen","Formulir, keputusan pimpinan","Draf batas mandat","1 hari kerja"],["3","Pembahasan pimpinan: Membahas mandat sikap atau penandatanganan yang baru atau sensitif secara musyawarah (SOP- GOV-002).","Pimpinan","Draf batas mandat","Keputusan pimpinan","1 kali rapat"],["4","Pemeriksaan: Memeriksa kesesuaian mandat dengan AD/ART, aturan kampus, dan persetujuan yang diwajibkan.","Irjen","Draf batas mandat","Catatan pemeriksaan","1 hari kerja"],["5","Penetapan: Menetapkan dan menandatangani Surat Mandat beserta masa berlaku.","Presiden","Draf, catatan Irjen","Surat Mandat bertanda tangan","1 hari kerja"],["6","Pencatatan dan pembekalan: Mencatat pada Register Mandat, menyerahkan Surat Mandat, dan membekali penerima tentang batas mandat.","Sekjen dan Menteri Hubungan Eksternal","Surat Mandat","Register Mandat, lembar pembekalan","Sebelum forum"],["7","Pelaksanaan dan pelaporan darurat: Menjalankan mandat; hal di luar mandat dikonsultasikan melalui kanal resmi kepada pimpinan.","Penerima mandat","Surat Mandat","Catatan pelaksanaan","Selama forum"],["8","Penutupan atau pencabutan: Menutup mandat setelah laporan SOP- HKE-012 diterima atau mencabutnya bila syarat berubah atau terjadi pelampauan.","Presiden dan Sekjen","Laporan, temuan","Mandat ditutup atau dicabut, Register diperbarui","3 hari kerja setelah forum"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Surat Mandat diterbitkan paling lambat 1 hari kerja sebelum forum dan laporan penerima mandat paling lambat 3 hari kerja setelah forum. Hasil akhir: Surat Mandat, Register Mandat, dan laporan pelaksanaan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Penerima mandat melampaui batas mandat: tindakan tidak mengikat BEM; Presiden menegur dan menugaskan Irjen menelaah (SOP-SDM-013).","Forum menuntut keputusan di luar mandat: penerima mandat meminta waktu untuk membawa ke pimpinan dan tidak memutuskan di tempat.","Mandat darurat tanpa waktu tertulis: SOP-GOV-012 dan dicatat tertulis paling lambat 1 hari kerja.","Penerima mandat berhalangan: mandat gugur; Presiden menetapkan penerima baru melalui alur SOP ini."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% tindakan atas nama BEM di forum eksternal memiliki Surat Tugas atau Surat Mandat.","100% mandat tercatat pada Register Mandat.","Tidak ada kasus pelampauan mandat.","Seluruh mandat ditutup atau dicabut dalam 3 hari kerja setelah forum."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Permintaan Mandat dan draf batas mandat.","Surat Mandat bertanda tangan.","Register Mandat.","Catatan pelaksanaan dan laporan (SOP-HKE-012). Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa Register Mandat setiap bulan; Irjen menilai kepatuhan dan menelaah dugaan pelampauan mandat."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Permintaan mandat → Perumusan batas mandat → Pembahasan pimpinan → Periksa Irjen → Penetapan Presiden → Pencatatan dan pembekalan → Pelaksanaan → Penutupan atau pencabutan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Mandat","Nama penerima; forum dan tanggal; agenda; jenis mandat; hal yang akan dibahas atau ditandatangani; pengusul."],["Surat Mandat","Nomor surat; pemberi dan penerima mandat; jenis mandat; forum; batas mandat; masa berlaku; ketentuan pelaporan; penandatangan."],["Register Mandat","Nomor; penerima; forum; jenis mandat; tanggal terbit; masa berlaku; status; keterangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Jenis dan batas mandat tertulis jelas.","☐ Ya ☐ Tidak"],["2","Sikap yang dimandatkan telah diputuskan pimpinan.","☐ Ya ☐ Tidak"],["3","Persetujuan kampus tersedia untuk mandat penandatanganan kerja sama baru.","☐ Ya ☐ Tidak"],["4","Surat Mandat ditandatangani Presiden dan dicatat pada Register.","☐ Ya ☐ Tidak"],["5","Penerima telah dibekali dan memahami batas mandat.","☐ Ya ☐ Tidak"],["6","Mandat ditutup atau dicabut setelah forum.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Hubungan Eksternal; penerima mandat. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-012","g":"Hubungan Eksternal dan Kemitraan","t":"Pelaporan Hasil Pertemuan Eksternal","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[718,721],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan format, batas waktu, verifikasi, pembahasan, dan pengarsipan laporan hasil pertemuan eksternal, sehingga kesepakatan, permintaan, dan pembelajaran dari setiap pertemuan terdokumentasi, disampaikan kepada pimpinan, dan ditindaklanjuti."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pertemuan atau kegiatan eksternal yang dihadiri pengurus atas nama BEM: undangan, audiensi, kunjungan, pertemuan dengan mitra atau sponsor, dan forum antar-BEM. Notulen rapat internal mengikuti SOP-ADM-009; laporan bulanan dan laporan kabinet mengikuti SOP-ADM-019."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) dan (2) (kewajiban menyusun laporan secara berkala dan pengelolaan yang transparan serta akuntabel).","ART Pasal 3 huruf g (Kewajiban: membuat laporan pertanggungjawaban kegiatan secara berkala kepada pihak yang berwenang).","ART Pasal 10 ayat (4) dan (5) (Rapat Koordinasi: agenda koordinasi kegiatan dan hasil rapat dituangkan dalam notulensi resmi yang disosialisasikan).","ART Pasal 4 huruf e (mewakili mahasiswa dalam forum resmi internal dan eksternal).","ART Pasal 11 huruf g dan k (larangan mencemarkan nama baik dan penyalahgunaan nama organisasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Laporan hasil pertemuan (LHP)","Laporan tertulis tentang jalannya pertemuan eksternal, kesepakatan, permintaan, dan tindak lanjut."],["Kesepakatan awal","Hasil pembicaraan yang belum mengikat BEM sebelum diproses sesuai SOP terkait."],["Informasi sensitif","Informasi yang jika tersebar dapat merugikan organisasi, kampus, mitra, atau pihak tertentu."],["Daftar tindak lanjut","Daftar tugas yang timbul dari pertemuan beserta penanggung jawab dan tenggat (SOP- ADM-010)."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap pengurus yang mewakili BEM dalam pertemuan eksternal wajib menyampaikan LHP tertulis paling lambat 3 hari kerja setelah pertemuan.","LHP memuat tanggal dan tempat, pihak yang hadir, pokok pembahasan, kesepakatan awal, permintaan pihak lain, tindak lanjut dan penanggung jawab, bukti, dan catatan risiko.","Laporan disusun faktual dan objektif; pendapat pribadi dipisahkan dari fakta dan sikap pihak lain tidak ditambah atau dikurangi.","Informasi sensitif diberi tanda dan aksesnya dibatasi (SOP-ADM-020 dan SOP-RSK-010).","Kesepakatan awal tidak otomatis mengikat BEM; kesepakatan yang berimplikasi kerja sama, dana, atau sikap diproses melalui SOP-HKE-005, SOP-HKE-007, atau SOP-GOV-002.","LHP dibahas pada Rapat Pimpinan atau Rapat Koordinasi terdekat dan tindak lanjutnya dicatat pada daftar tindak lanjut.","Isi laporan tidak disebarkan melalui media sosial atau kanal publik tanpa persetujuan Presiden (SOP- KOM-010).","Pengurus yang berulang tidak melapor dibina sesuai SOP-SDM-011."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Bertanggung jawab atas kelengkapan, klasifikasi, pembahasan, dan pengarsipan LHP."],["Delegasi / pengurus yang hadir","R","Menyusun dan menyampaikan LHP beserta bukti tepat waktu."],["Menteri Hubungan Eksternal","R","Memverifikasi isi LHP dan memimpin tindak lanjut hubungan eksternal."],["Kepala Biro Kesekretariatan","R","Mengirim pengingat, mencatat, dan mengarsipkan LHP serta daftar tindak lanjut."],["Presiden","C","Menerima laporan dan memberi arahan tindak lanjut."],["Wakil Presiden","C","Memberi pertimbangan koordinasi tindak lanjut antar-unit."],["Inspektur Jenderal","C","Memantau kepatuhan pelaporan dan kesesuaian isi dengan AD/ART."],["Seluruh pengurus","I","Menerima informasi hasil yang relevan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Surat Tugas atau Surat Mandat delegasi.","Catatan lapangan, daftar hadir, dan dokumentasi pertemuan.","Format baku LHP.","Jadwal Rapat Pimpinan dan Rapat Koordinasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengingat dan format: Mengirim pengingat dan format LHP kepada delegasi satu hari setelah pertemuan.","Kepala Biro Kesekretariatan","Kalender, Surat Tugas","Pengingat terkirim","1 hari kerja setelah pertemuan"],["2","Penyusunan LHP: Menyusun LHP sesuai format: pembahasan, kesepakatan awal, permintaan, tindak lanjut, dan catatan risiko.","Delegasi / pengurus yang hadir","Catatan lapangan, format","Draf LHP","3 hari kerja setelah pertemuan"],["3","Pengumpulan bukti: Melampirkan daftar hadir, dokumentasi, materi, dan surat atau dokumen yang diterima.","Delegasi / pengurus yang hadir","Dokumen pertemuan","LHP lengkap dengan lampiran","Bersama LHP"],["4","Verifikasi isi: Memeriksa kebenaran dan kelengkapan isi serta memastikan tidak ada pelampauan mandat.","Menteri Hubungan Eksternal","LHP","LHP terverifikasi","2 hari kerja"],["5","Klasifikasi dan pemeriksaan: Memeriksa format, menandai informasi sensitif, dan memutuskan tingkat keterbukaan laporan.","Sekjen","LHP terverifikasi","LHP terklasifikasi","1 hari kerja"],["6","Pembahasan: Membahas LHP pada Rapat Pimpinan atau Rapat Koordinasi terdekat dan memutuskan tindak lanjut.","Presiden dan pimpinan","LHP terklasifikasi","Keputusan tindak lanjut","Paling lambat 7 hari kerja"],["7","Pencatatan tindak lanjut: Mencatat tindak lanjut beserta penanggung jawab dan tenggat pada daftar tindak lanjut serta memantaunya.","Kepala Biro Kesekretariatan","Keputusan tindak lanjut","Daftar tindak lanjut","1 hari kerja setelah rapat"],["8","Arsip dan pembaruan data: Mengarsipkan LHP, memperbarui basis data mitra (SOP-HKE-013), dan memasukkan ringkasan pada laporan bulanan.","Kepala Biro Kesekretariatan dan Menteri Hubungan Eksternal","LHP final","Arsip, data mitra, bahan laporan bulanan","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"LHP diserahkan paling lambat 3 hari kerja setelah pertemuan, diverifikasi dalam 2 hari kerja, dan dibahas paling lambat 7 hari kerja. Hasil akhir: LHP terarsip dan daftar tindak lanjut yang berjalan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["LHP terlambat lebih dari 3 hari kerja: Sekjen menegur; berulang diteruskan ke SOP-SDM-011.","Isi laporan diragukan atau berbeda dengan keterangan pihak lain: Menteri Hubungan Eksternal meminta klarifikasi dan Irjen dapat melakukan penelaahan.","Laporan memuat dugaan pelanggaran atau penyalahgunaan: diteruskan kepada Irjen dan ditangani menurut SOP-RSK-004 atau SOP-RSK-007.","Laporan memuat informasi yang berisiko bagi reputasi: SOP-KOM-012."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pertemuan eksternal memiliki LHP dalam 3 hari kerja.","100% LHP terverifikasi dan terklasifikasi sebelum dibahas.","100% tindak lanjut tercatat dengan penanggung jawab dan tenggat.","Tidak ada kebocoran informasi sensitif dari laporan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan hasil pertemuan beserta lampiran.","Catatan verifikasi dan klasifikasi.","Keputusan dan daftar tindak lanjut.","Ringkasan untuk laporan bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa ketepatan waktu dan kelengkapan LHP setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengingat dan format → Penyusunan LHP → Pengumpulan bukti → Verifikasi isi → Klasifikasi dan pemeriksaan → Pembahasan pimpinan → Pencatatan tindak lanjut → Arsip dan pembaruan data → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan Hasil Pertemuan Eksternal","Nama pertemuan; tanggal dan tempat; pihak yang hadir; pokok pembahasan; kesepakatan awal; permintaan pihak lain; tindak lanjut dan penanggung jawab; bukti; catatan risiko; pelapor."],["Daftar Tindak Lanjut","Nomor; asal pertemuan; tindakan; penanggung jawab; tenggat; status; keterangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","LHP diserahkan dalam 3 hari kerja.","☐ Ya ☐ Tidak"],["2","Seluruh bagian format terisi dan bukti terlampir.","☐ Ya ☐ Tidak"],["3","Isi diverifikasi Menteri Hubungan Eksternal.","☐ Ya ☐ Tidak"],["4","Informasi sensitif ditandai dan aksesnya dibatasi.","☐ Ya ☐ Tidak"],["5","Tindak lanjut tercatat dengan penanggung jawab dan tenggat.","☐ Ya ☐ Tidak"],["6","LHP terarsip dan basis data mitra diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Hubungan Eksternal; Menteri Harmonisasi Kampus; Kepala Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HKE-013","g":"Hubungan Eksternal dan Kemitraan","t":"Pengelolaan Hubungan dan Basis Data Mitra","o":"Menteri Hubungan Eksternal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Hubungan Eksternal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[722,726],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengelolaan hubungan berkelanjutan dan basis data mitra BEM yang akurat, mutakhir, aman, dan dapat diwariskan antar-kabinet, sehingga hubungan dengan mitra terjaga, tidak bergantung pada ingatan perorangan, dan digunakan hanya untuk kepentingan organisasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk pendataan, klasifikasi, pemeliharaan hubungan, pemutakhiran, evaluasi, pengamanan, dan serah terima data mitra BEM, yaitu pihak kampus, ORMAWA, instansi, lembaga, sponsor, dan tokoh. SOP ini tidak mengatur data pribadi pengurus (SOP-SDM-018), keamanan akun dan data digital secara umum (SOP-RSK- 008), maupun serah terima kerja sama antar-kabinet (SOP-TRN-007)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Bab III (Tugas BEM) huruf d (koordinasi dan kerja sama dengan ORMAWA dan pihak eksternal perguruan tinggi).","ART Pasal 2 huruf e (kerja sama yang halal dan tidak mengikat dengan pihak eksternal dengan persetujuan Ketua STDIIS).","ART Pasal 3 huruf b, d, dan g (Kewajiban: menjaga ukhuwah, nama baik, dan membuat laporan berkala).","AD Pasal 17 ayat (2) (pengelolaan organisasi yang transparan, akuntabel, efektif, dan efisien).","ART Pasal 11 huruf g dan k (larangan mencemarkan nama baik dan memakai fasilitas atau nama organisasi untuk kepentingan pribadi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Mitra","Pihak eksternal yang menjalin hubungan berkelanjutan dengan BEM, baik dalam bentuk kerja sama, sponsor, koordinasi, maupun silaturahim."],["Basis Data Mitra (BDM)","Kumpulan data terstruktur tentang mitra beserta riwayat hubungan dan dokumennya."],["Status hubungan","Klasifikasi mitra: aktif, pasif, ditangguhkan, atau daftar tolak."],["Pemilik hubungan (PIC)","Pengurus yang bertanggung jawab menjaga hubungan dengan satu mitra."],["Daftar tolak","Daftar pihak yang tidak boleh diajak kerja sama atau diterima dukungannya karena alasan syariat, AD/ART, atau pelanggaran kesepakatan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["BDM disimpan pada repositori resmi, dikelola Menteri Hubungan Eksternal; hak baca untuk pimpinan dan hak ubah hanya untuk Menteri Hubungan Eksternal dan staf yang ditunjuk.","Data minimal: nama dan jenis mitra, kontak resmi, bidang kegiatan, status, PIC, riwayat interaksi, dokumen terkait (naskah kerja sama, LHP), dan tanggal pemutakhiran.","Data pribadi kontak dikumpulkan seperlunya dan hanya untuk keperluan organisasi; data tidak diberikan kepada pihak lain atau dipakai untuk kepentingan pribadi.","Setiap mitra memiliki PIC; hubungan dilakukan melalui kanal resmi organisasi.","Setiap interaksi baru dilaporkan unit terkait kepada staf Kementerian Hubungan Eksternal paling lambat 3 hari kerja agar BDM tetap mutakhir.","BDM diverifikasi dan dimutakhirkan sekurang-kurangnya setiap tiga bulan serta setiap ada perubahan signifikan.","Penetapan status daftar tolak diputuskan Presiden berdasarkan telaah Irjen dan, bila meragukan, pertimbangan Pembina atau KAUR ORMAWA.","Pemeliharaan hubungan dilakukan dengan ucapan pada momen penting, ucapan terima kasih, silaturahim, dan undangan kegiatan sesuai anggaran dan adab Islami.","BDM wajib diserahterimakan kepada kabinet berikutnya (SOP-TRN-006 dan SOP-TRN-007)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Hubungan Eksternal","A","Bertanggung jawab atas keakuratan, pemutakhiran, keamanan, dan pemanfaatan BDM."],["Staf Kementerian Hubungan Eksternal","R","Menginput, memverifikasi, dan memutakhirkan data."],["Penanggung jawab mitra (PIC)","R","Menjaga hubungan dan melaporkan perkembangan mitra."],["Kepala Biro Kesekretariatan","R","Menyimpan dokumen terkait dan mengatur pencadangan serta hak akses (SOP- ADM-015)."],["Sekretaris Jenderal","R","Menyusun struktur BDM, hak akses, dan serah terima."],["Presiden","C","Menetapkan status daftar tolak dan hubungan strategis."],["Inspektur Jenderal","C","Memeriksa kepatuhan terhadap AD/ART dan penelaahan mitra."],["Seluruh unit","I","Melaporkan interaksi baru dengan pihak eksternal."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Arsip mitra kabinet sebelumnya, bila ada.","Register Kerja Sama, Register Sponsor, dan LHP.","Struktur dan hak akses BDM yang disetujui.","Kebijakan kerahasiaan data (SOP-ADM-020 dan SOP-RSK-010)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan struktur dan akses: Menetapkan kolom BDM, status hubungan, dan hak akses pengurus.","Menteri Hubungan Eksternal bersama Sekjen","Kebutuhan organisasi","Struktur BDM dan daftar hak akses","3 hari kerja"],["2","Pendataan awal: Menghimpun mitra dari arsip kabinet sebelumnya, kampus, ORMAWA, kerja sama, dan sponsor ke dalam BDM.","Staf Kementerian Hubungan Eksternal","Arsip, register","BDM awal","10 hari kerja"],["3","Klasifikasi dan PIC: Menetapkan status hubungan tiap mitra dan menunjuk PIC.","Menteri Hubungan Eksternal","BDM awal","BDM terklasifikasi","3 hari kerja"],["4","Pencatatan interaksi: Menerima laporan interaksi dari unit dan LHP, lalu memperbarui riwayat hubungan.","Staf Kementerian Hubungan Eksternal","Laporan interaksi, LHP","BDM diperbarui","3 hari kerja"],["5","Pemeliharaan hubungan: Menjaga komunikasi berkala, mengirim ucapan dan ucapan terima kasih, serta mengundang mitra pada kegiatan yang relevan.","PIC","BDM, kalender","Catatan pemeliharaan hubungan","Berkala; sekurang- kurangnya triwulan"],["6","Verifikasi triwulan: Memverifikasi kebenaran kontak, status, dan dokumen setiap mitra dan menandai data yang usang.","Menteri Hubungan Eksternal","BDM","BDM terverifikasi","Setiap 3 bulan"],["7","Evaluasi mitra: Menilai manfaat dan kepatuhan mitra; mengusulkan status ditangguhkan atau daftar tolak kepada Presiden.","Menteri Hubungan Eksternal dan Presiden","BDM, laporan kerja sama","Penetapan status","Setiap 3 bulan atau saat ada temuan"],["8","Pengamanan dan serah terima: Mencadangkan BDM, membatasi akses, dan menyerahkan BDM kepada kabinet berikutnya.","Sekjen dan Menteri Hubungan Eksternal","BDM final","Cadangan dan berita acara serah terima","Sesuai jadwal transisi"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Struktur BDM ditetapkan paling lambat 3 hari kerja dan pendataan awal paling lambat 10 hari kerja setelah SOP disahkan. Pemutakhiran paling lambat 3 hari kerja setelah interaksi dan verifikasi setiap 3 bulan. Hasil akhir: BDM mutakhir yang aman dan siap diserahterimakan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Data mitra bocor atau disalahgunakan: SOP-RSK-009 dan SOP-RSK-007; akses yang bersangkutan dicabut segera.","Dua unit memiliki hubungan berbeda dengan mitra yang sama: diputuskan Wakil Presiden; PIC tunggal ditetapkan.","Mitra terindikasi bertentangan dengan syariat atau AD/ART: hubungan ditangguhkan dan diajukan kepada Presiden untuk status daftar tolak.","Mitra meminta penghapusan datanya: dipertimbangkan Menteri Hubungan Eksternal dan Presiden dengan memperhatikan kewajiban pengarsipan organisasi."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% mitra aktif memiliki PIC dan data terverifikasi dalam 3 bulan terakhir.","Interaksi baru tercatat paling lambat 3 hari kerja.","Tidak ada kejadian data mitra bocor atau disalahgunakan.","BDM dan berita acara serah terima tersedia pada akhir masa jabatan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Basis Data Mitra beserta cadangan.","Daftar hak akses dan daftar tolak.","Catatan verifikasi triwulan dan evaluasi mitra.","Berita acara serah terima BDM. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Biro Kesekretariatan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa ketersediaan dan hak akses BDM setiap triwulan; Irjen menilai kepatuhan pada evaluasi berkala dan evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Penetapan struktur dan akses → Pendataan awal → Klasifikasi dan PIC → Pencatatan interaksi → Pemeliharaan hubungan → Verifikasi triwulan → Evaluasi mitra → Pengamanan dan serah terima → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Basis Data Mitra","Nomor; nama mitra; jenis; kontak resmi; bidang kegiatan; status hubungan; PIC; riwayat interaksi; dokumen terkait; tanggal pemutakhiran."],["Lembar Evaluasi Mitra","Mitra; periode; manfaat; kepatuhan pada kesepakatan; kendala; rekomendasi status; penilai; tanggal."],["Berita Acara Serah Terima Basis Data Mitra","Tanggal; pihak penyerah dan penerima; jumlah mitra; lokasi penyimpanan; hak akses; catatan; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap mitra aktif memiliki PIC dan status hubungan.","☐ Ya ☐ Tidak"],["2","Interaksi baru tercatat dalam 3 hari kerja.","☐ Ya ☐ Tidak"],["3","Verifikasi triwulan terlaksana.","☐ Ya ☐ Tidak"],["4","Hak akses dibatasi dan cadangan tersedia.","☐ Ya ☐ Tidak"],["5","Data pribadi dikumpulkan seperlunya dan hanya untuk keperluan organisasi.","☐ Ya ☐ Tidak"],["6","Berita acara serah terima disiapkan pada masa transisi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri Hubungan Eksternal; Menteri Harmonisasi Kampus; Kepala Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-MONEV-001","g":"Monitoring, Evaluasi, dan Pengawasan","t":"Penetapan Indikator Kinerja Kabinet","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[731,734],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan, pemeriksaan, pengesahan, dan peninjauan indikator kinerja kabinet beserta target, ambang status, sumber data, dan penanggung jawabnya, sehingga capaian BEM, unit, dan pengurus dapat diukur secara objektif, konsisten, dan dapat diverifikasi selama satu periode kepengurusan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk Presiden, Wakil Presiden, Sekretaris Jenderal, Menteri, Kepala Biro, Inspektur Jenderal, dan seluruh unit BEM Kabinet Samasta. Mencakup indikator tingkat kabinet dan tingkat unit. SOP ini tidak mengatur pemantauan target bulanan (lihat SOP-MONEV-002), format laporan progres (SOP-MONEV-003), maupun penilaian individu (SOP-MONEV-005)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 9 ayat (3) huruf a, c, dan e (Rapat Kerja menyusun program kerja, timeline, dan target capaian organisasi) serta ayat (5) dan (6) (hasil Raker menjadi pedoman dan program memerlukan persetujuan Pembina).","ART Pasal 7 ayat (5) huruf c (Mubes mengevaluasi kinerja organisasi).","ART Pasal 12 ayat (3) dan (4) (pengawasan, evaluasi, dan penilaian kinerja oleh Irjen dalam rangka pembinaan dan pencegahan pelanggaran).","AD Pasal 17 ayat (2) (pengelolaan transparan, akuntabel, efektif, dan efisien).","SOP-GOV-001 (matriks kewenangan), SOP-GOV-002 (pengambilan keputusan), dan SOP-GOV-006 (Rapat Kabinet)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Indikator kinerja","Ukuran yang menunjukkan sejauh mana suatu tujuan, program, atau tugas telah tercapai."],["Target","Nilai yang ingin dicapai pada suatu indikator dalam jangka waktu tertentu."],["Kamus indikator","Dokumen yang menjelaskan nama, definisi, cara ukur, target, ambang status, sumber data, dan pemilik setiap indikator."],["Ambang status","Batas persentase capaian yang menentukan status hijau, kuning, atau merah."],["Bukti capaian","Dokumen, catatan, atau data yang dapat diperiksa untuk membuktikan capaian suatu indikator."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Indikator ditetapkan setelah Rapat Kerja awal periode dan diturunkan dari target capaian organisasi serta program kerja yang telah disahkan.","Dimensi minimal (usulan): ketepatan waktu program, capaian hasil program, tertib administrasi, tertib keuangan, kehadiran dan partisipasi, serta tindak lanjut keputusan dan temuan.","Setiap indikator wajib memiliki definisi, cara ukur, target, sumber data, bukti, frekuensi pengukuran, dan satu pemilik.","Jumlah indikator dibatasi agar dapat dipantau: maksimal 5 indikator utama per unit (usulan).","Ambang status (usulan): hijau jika capaian 90% atau lebih, kuning 70% sampai 89%, dan merah kurang dari 70%.","Indikator hanya mengukur hal yang dapat dibuktikan dan tidak boleh mendorong pelaporan yang tidak benar.","Indikator Inspektorat Jenderal ditetapkan melalui Rapat Pimpinan dan tidak dinilai oleh Inspektur Jenderal sendiri.","Indikator dikunci setelah disahkan. Perubahan hanya melalui evaluasi tengah periode (SOP-MONEV- 011) atau perubahan kondisi besar melalui SOP-GOV-011."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan Kamus Indikator melalui Keputusan Presiden."],["Wakil Presiden","R","Menelaah usulan unit Eksekutif dan memastikan indikator tidak tumpang tindih."],["Sekretaris Jenderal","R","Menyusun draf Kamus Indikator, mensosialisasikan, dan mengaktifkan dashboard monitoring."],["Menteri / Kabiro","R","Mengusulkan indikator, target, dan sumber data unit."],["Inspektur Jenderal","C","Memeriksa keterukuran, kemampuan verifikasi, dan keselarasan dengan AD/ART."],["Kementerian PSDM","C","Memberi masukan agar indikator selaras dengan penilaian pengurus."],["Seluruh pengurus","I","Memahami dan menjalankan indikator yang berlaku."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Hasil Rapat Kerja: program kerja, timeline, dan target capaian organisasi.","AD/ART, peraturan kampus, matriks kewenangan (SOP-GOV-001), dan uraian tugas.","Data dasar atau laporan akhir kabinet sebelumnya, bila ada.","Usulan indikator dari setiap unit."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyiapan bahan: Mengumpulkan target capaian hasil Raker, program kerja, matriks kewenangan, dan data dasar kabinet sebelumnya.","Sekjen","Hasil Raker, matriks, arsip","Bahan penyusunan indikator","2 hari kerja setelah Raker"],["2","Usulan indikator unit: Mengisi Formulir Usulan Indikator Unit: indikator, definisi, target, sumber data, dan frekuensi pengukuran.","Menteri / Kabiro","Program kerja unit","Usulan tertulis tiap unit","3 hari kerja"],["3","Penyusunan draf kamus: Menggabungkan usulan, menghapus tumpang tindih, menetapkan satu pemilik tiap indikator, dan menentukan ambang status.","Sekjen bersama Wapres","Usulan unit","Draf Kamus Indikator","3 hari kerja"],["4","Pemeriksaan keterukuran: Memeriksa bahwa setiap indikator terukur, memiliki sumber data dan bukti, serta tidak bertentangan dengan AD/ART; memberi catatan tertulis.","Irjen","Draf, checklist","Catatan pemeriksaan","2 hari kerja"],["5","Pembahasan: Membahas draf pada Rapat Kabinet secara musyawarah (SOP-GOV-002), lalu merevisi sesuai catatan.","Pimpinan dan Eksekutif","Draf, catatan Irjen","Draf final","1 kali rapat; revisi 2 hari kerja"],["6","Pengesahan: Menetapkan Kamus Indikator melalui Keputusan Presiden. Bagian yang menyangkut program kerja mengikuti persetujuan Pembina.","Presiden","Draf final","Keputusan Presiden","2 hari kerja"],["7","Sosialisasi dan aktivasi: Membagikan Kamus melalui kanal resmi, memasukkan indikator ke dashboard monitoring, dan mencatat pada Register Dokumen.","Sekjen","Keputusan Presiden","Distribusi tercatat, dashboard aktif","3 hari kerja setelah pengesahan"],["8","Peninjauan berkala: Meninjau indikator pada evaluasi tengah periode, saat terjadi perubahan struktur atau program besar, atau saat indikator terbukti tidak dapat diukur.","Sekjen dan Irjen","Hasil evaluasi, temuan","Revisi atau penegasan kamus","Setiap ada pemicu"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penetapan indikator ditargetkan selesai paling lambat 15 hari kerja sejak Rapat Kerja selesai. Hasil akhir: Keputusan Presiden beserta Kamus Indikator Kabinet."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba.."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Unit tidak menyerahkan usulan sampai batas waktu: Wakil Presiden menetapkan usulan sementara berdasarkan program kerja unit, dan unit mengonfirmasi pada Rapat Kabinet.","Perbedaan pendapat tentang target atau ambang: diputuskan melalui SOP-GOV-002.","Indikator diduga bertentangan dengan AD/ART atau aturan kampus: ditunda dan ditelaah Irjen; bila perlu penafsiran, dikonsultasikan kepada KAUR ORMAWA atau Pembina.","Kebutuhan mengubah AD/ART tidak diputuskan melalui SOP ini; ikuti AD Bab XI dan ART Bab VII."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% unit memiliki indikator yang telah disahkan paling lambat 15 hari kerja setelah Raker.","100% indikator memiliki pemilik, target, sumber data, dan bukti.","Kamus Indikator tersosialisasi paling lambat 3 hari kerja setelah pengesahan.","Tidak ada indikator yang dibatalkan karena tidak dapat diverifikasi pada evaluasi tengah periode."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Keputusan Presiden tentang Indikator Kinerja Kabinet.","Kamus Indikator Kabinet (target, ambang status, sumber data, pemilik).","Catatan pemeriksaan Irjen.","Entri pada Register Dokumen dan dashboard monitoring. Seluruh dokumen disimpan pada repositori resmi BEM (folder Monitoring dan Evaluasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kesesuaian dashboard dengan Kamus Indikator setiap bulan; Irjen menilai keterukuran indikator pada evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Penyiapan bahan → Usulan indikator unit → Draf kamus indikator → Periksa Irjen → Pembahasan → Pengesahan Presiden → Sosialisasi dan aktivasi dashboard → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Usulan Indikator Unit","Nama unit; pengusul; indikator; definisi; target; sumber data; frekuensi pengukuran; bukti; tanggal."],["Templat Kamus Indikator Kabinet","Kode indikator; dimensi; indikator; cara ukur; target; ambang hijau, kuning, merah; sumber data; pemilik; frekuensi."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap indikator memiliki definisi, cara ukur, target, sumber data, dan satu pemilik.","☐ Ya ☐ Tidak"],["2","Jumlah indikator utama tiap unit tidak melebihi batas yang ditetapkan.","☐ Ya ☐ Tidak"],["3","Tidak ada indikator yang bertentangan dengan AD/ART dan aturan kampus.","☐ Ya ☐ Tidak"],["4","Keputusan Presiden telah ditandatangani dan Kamus Indikator tersosialisasi.","☐ Ya ☐ Tidak"],["5","Dokumen tercatat pada Register Dokumen dan dashboard telah diaktifkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-MONEV-002","g":"Monitoring, Evaluasi, dan Pengawasan","t":"Pemantauan Target Bulanan","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[735,738],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penjabaran target tahunan menjadi target bulanan, pemantauan capaian, penetapan status, dan pembahasan hasilnya, sehingga penyimpangan terdeteksi lebih awal sebelum berubah menjadi keterlambatan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh kementerian, biro, dan unit BEM Kabinet Samasta. Mencakup target kegiatan, hasil, dan serapan anggaran yang ditetapkan tiap bulan. SOP ini tidak mengatur penanganan pekerjaan terlambat (SOP-MONEV-008) dan format laporan unit (SOP-MONEV-003)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 9 ayat (3) huruf c dan e (timeline kegiatan dan target capaian organisasi).","ART Pasal 10 ayat (1), (2), dan (4) (Rapat Koordinasi untuk mengevaluasi pelaksanaan program kerja dan memonitor penggunaan anggaran).","AD Pasal 14 huruf c (Rapat Koordinasi) dan AD Pasal 17 ayat (2) (pengelolaan transparan dan akuntabel).","SOP-MONEV-001 (indikator), SOP-GOV-006 (Rapat Kabinet), dan SOP-ADM-015 (hak akses dokumen)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Target bulanan","Hasil yang harus dicapai suatu unit pada bulan tertentu, lengkap dengan ukuran, tenggat, penanggung jawab, dan bukti."],["Dashboard monitoring","Tampilan terpusat status target, tenggat, anggaran, dan masalah seluruh unit."],["Status capaian","Penandaan hijau, kuning, atau merah berdasarkan ambang pada SOP-MONEV-001."],["Titik periksa","Waktu tetap pemantauan: penetapan target, pengecekan tengah bulan, dan penutupan bulan."],["Bukti capaian","Dokumen, foto, notulen, atau bukti transaksi yang menunjukkan target telah dicapai."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Target bulanan diturunkan dari timeline Raker dan Kamus Indikator, serta mencakup kegiatan, hasil, dan serapan anggaran bila ada.","Setiap target memiliki satu penanggung jawab, satu ukuran, satu tenggat, dan satu bukti capaian.","Pemantauan dilakukan pada tiga titik periksa: penetapan target sebelum bulan berjalan, pengecekan tengah bulan, dan penutupan bulan.","Capaian hanya diakui bila disertai bukti yang dapat diperiksa.","Status mengikuti ambang pada SOP-MONEV-001. Status merah diproses melalui SOP-MONEV-008; status merah dua bulan berturut-turut menjadi agenda Rapat Evaluasi.","Perubahan target karena alasan sah (jadwal kampus, belum ada izin Pembina, kebijakan pihak luar) dicatat sebagai perubahan target yang disetujui Wakil Presiden, bukan dihapus.","Pemantauan tidak menggantikan pengawasan Irjen; Irjen dapat mengambil sampel bukti capaian."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Menjalankan siklus pemantauan, menyusun rekap, dan melaporkan hasil kepada pimpinan."],["Wakil Presiden","R","Menyetujui target unit, menindaklanjuti unit berstatus merah."],["Menteri / Kabiro","R","Menetapkan target, melaporkan realisasi, dan melampirkan bukti."],["Biro Kesekretariatan","R","Mengelola dashboard, menghitung status, dan mengarsipkan bukti."],["Inspektur Jenderal","C","Mengambil sampel bukti capaian dan memberi catatan."],["Presiden","I","Menerima ringkasan capaian kabinet."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Timeline kegiatan hasil Raker dan Kamus Indikator.","Kalender organisasi dan kalender kampus.","Rekap capaian bulan sebelumnya dan daftar tindak lanjut.","Data serapan anggaran dari Biro Keuangan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan target bulan berjalan: Mengisi Lembar Target Bulanan: kegiatan, ukuran, tenggat, penanggung jawab, dan bukti capaian.","Menteri / Kabiro","Timeline Raker, Kamus Indikator","Lembar target unit","Hari kerja terakhir bulan sebelumnya"],["2","Verifikasi dan persetujuan: Memeriksa kesesuaian dengan program yang telah disetujui Pembina, tumpang tindih, kapasitas unit, dan bentrok kalender; menyetujui target.","Wapres bersama Sekjen","Lembar target, kalender","Target bulanan disetujui","2 hari kerja"],["3","Konsolidasi dashboard: Memasukkan target seluruh unit ke dashboard monitoring.","Biro Kesekretariatan","Target disetujui","Dashboard bulan berjalan","1 hari kerja"],["4","Pengecekan tengah bulan: Meminta pembaruan status singkat untuk target yang berisiko terlambat dan mencatat hasilnya.","Sekjen","Dashboard","Status tengah bulan","Sekitar hari kerja ke-10 (usulan)"],["5","Penutupan bulan: Mengisi realisasi dan melampirkan bukti capaian.","Menteri / Kabiro","Target, bukti","Realisasi dan bukti","Hari kerja ke-3 bulan berikutnya"],["6","Penghitungan status: Menghitung persentase capaian dan status per target, per unit, dan kabinet; memeriksa kecukupan bukti.","Biro Kesekretariatan dan Sekjen","Realisasi, bukti","Rekap capaian bulanan","Hari kerja ke-5"],["7","Pembahasan: Menyajikan rekap pada Rapat Kabinet bulanan, menetapkan tindak lanjut, dan meneruskan target berstatus merah ke SOP-MONEV-008.","Sekjen dan pimpinan rapat","Rekap","Keputusan tindak lanjut","Rapat Kabinet bulanan"],["8","Pencatatan dan arsip: Menyimpan rekap, bukti, dan daftar tindak lanjut; memperbarui dashboard.","Biro Kesekretariatan","Rekap, notulen","Arsip dan dashboard terbarui","3 hari kerja setelah rapat"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Rekap capaian bulanan tersedia paling lambat hari kerja ke-5 setiap bulan. Hasil akhir: rekap capaian bulanan, dashboard terbarui, dan daftar tindak lanjut."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Unit tidak menyerahkan target atau realisasi: Sekjen mengingatkan secara tertulis satu kali; bila tetap tidak ada, diteruskan kepada Wakil Presiden dan unit ditandai merah (tidak dilaporkan).","Bukti tidak memadai: capaian dicatat belum terverifikasi dan Irjen dapat diminta mengklarifikasi.","Perbedaan penilaian capaian: diputuskan Wakil Presiden; bila belum selesai dibawa ke Rapat Pimpinan (SOP-GOV-005).","Target berubah akibat keputusan pihak luar: dicatat sebagai perubahan target dan tidak dihitung sebagai kegagalan unit."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% unit menyerahkan target dan realisasi tepat waktu setiap bulan.","Rekap capaian tersedia paling lambat hari kerja ke-5.","100% penetapan status hijau, kuning, atau merah didukung bukti.","Minimal 80% tindak lanjut hasil pemantauan selesai sesuai tenggat."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Target Bulanan setiap unit yang telah disetujui.","Rekap capaian bulanan dan dashboard monitoring terbaru.","Daftar tindak lanjut.","Arsip bukti capaian. Seluruh dokumen disimpan pada repositori resmi BEM (folder Monitoring dan Evaluasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa konsistensi dashboard dengan rekap setiap bulan; Irjen mengambil sampel bukti capaian pada pengawasan berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Target bulanan unit → Verifikasi dan persetujuan → Input dashboard → Pengecekan tengah bulan → Realisasi dan bukti → Hitung status → Bahas di Rapat Kabinet → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Target Bulanan Unit","Nama unit; bulan; kegiatan; ukuran; tenggat; penanggung jawab; bukti capaian; persetujuan Wapres."],["Templat Rekap Capaian Bulanan","Unit; target; realisasi; persentase; status; kendala; tindak lanjut; lokasi bukti."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap target memiliki ukuran, tenggat, penanggung jawab, dan bukti.","☐ Ya ☐ Tidak"],["2","Target selaras dengan program yang telah disetujui Pembina.","☐ Ya ☐ Tidak"],["3","Realisasi dilengkapi bukti yang dapat diperiksa.","☐ Ya ☐ Tidak"],["4","Status dihitung sesuai ambang dan target merah telah diteruskan ke SOP-MONEV-008.","☐ Ya ☐ Tidak"],["5","Rekap, notulen, dan bukti tersimpan pada repositori resmi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-MONEV-003","g":"Monitoring, Evaluasi, dan Pengawasan","t":"Laporan Progres Setiap Unit","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[739,742],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan format, isi, jalur, tenggat, dan verifikasi laporan progres setiap kementerian, biro, dan unit, agar pimpinan memperoleh informasi capaian, kendala, anggaran, dan kebutuhan keputusan yang seragam, tepat waktu, dan dapat diverifikasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk Menteri, Kepala Biro, Inspektur Jenderal, tim acara, dan panitia kegiatan yang berada di bawah koordinasi BEM. Mencakup laporan bulanan dan laporan insidental. SOP ini tidak mengatur LPJ kegiatan (SOP-PRO-020) dan laporan keuangan kegiatan (SOP-KEU-015)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) dan (2) (laporan pertanggungjawaban berkala; pengelolaan transparan dan akuntabel).","ART Bab II Pasal 3 (Kewajiban BEM) huruf g (laporan kegiatan dan keuangan secara berkala).","ART Pasal 10 ayat (1), (4), dan (5) (Rapat Koordinasi, agenda, dan notulensi resmi).","SOP-MONEV-002 (target bulanan), SOP-GOV-006 (Rapat Kabinet), SOP-KOM-004 (format laporan progres melalui kanal digital), SOP-SDM-009, dan SOP-ADM-019."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Laporan progres","Laporan tertulis unit yang memuat capaian, kendala, anggaran, rencana, dan kebutuhan keputusan."],["Laporan bulanan","Laporan rutin yang disampaikan satu kali setiap bulan."],["Laporan insidental","Laporan di luar jadwal untuk kejadian yang berpengaruh pada target, keselamatan, keuangan, atau reputasi."],["Kanal resmi","Sarana komunikasi dan penyimpanan yang ditetapkan BEM untuk laporan (SOP-KOM- 001)."],["Verifikasi sampel","Pencocokan sebagian butir laporan dengan bukti dan data sumber."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap unit wajib menyampaikan laporan bulanan dan laporan insidental sesuai ketentuan SOP ini.","Isi minimal: capaian dibanding target bulanan, kegiatan berjalan, kendala, penggunaan anggaran, rencana bulan berikutnya, kebutuhan keputusan atau dukungan, dan bukti pendukung.","Laporan disampaikan melalui kanal resmi dengan format baku; laporan lewat pesan pribadi tidak diakui sebagai laporan resmi.","Laporan berisi fakta yang dapat dibuktikan. Laporan yang sengaja memuat data tidak benar diproses sebagai dugaan pelanggaran etik (SOP-SDM-013).","Laporan insidental disampaikan paling lambat 1 hari kerja sejak kejadian; kejadian darurat dilaporkan segera melalui jalur yang diatur SOP-RSK-003.","Data pribadi dalam laporan dibatasi seperlunya dan dilindungi sesuai SOP-SDM-018.","Laporan Inspektorat Jenderal memuat status pelaksanaan pengawasan dan tidak membuka temuan yang belum final.","Laporan bulanan seluruh unit menjadi bahan Laporan Bulanan Kabinet (SOP-ADM-019)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Menetapkan format, menerima, merekap, dan menyajikan laporan unit."],["Menteri / Kabiro","R","Menyusun dan menyampaikan laporan unit tepat waktu beserta bukti."],["Biro Kesekretariatan","R","Memeriksa kelengkapan, mencatat penerimaan, dan mengarsipkan laporan."],["Wakil Presiden","R","Menelaah laporan dan menindaklanjuti kendala unit Eksekutif."],["Inspektur Jenderal","C","Memverifikasi sampel laporan terhadap bukti."],["Presiden","I","Menerima rekap laporan kabinet."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Target bulanan unit (SOP-MONEV-002).","Format Laporan Progres Unit.","Bukti capaian dan data realisasi anggaran dari Biro Keuangan.","Daftar tindak lanjut bulan sebelumnya."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan laporan: Mengisi Formulir Laporan Progres Unit dan melampirkan bukti pendukung.","Menteri / Kabiro","Target bulanan, bukti","Laporan unit","Hari kerja ke-3 setiap bulan"],["2","Penyerahan: Mengirim laporan melalui kanal resmi dengan penamaan file sesuai SOP- ADM-014.","Menteri / Kabiro","Laporan unit","Laporan tercatat","Sama dengan batas penyusunan"],["3","Pemeriksaan kelengkapan: Memeriksa kolom wajib, bukti, nama file, dan tenggat; mengembalikan laporan yang belum lengkap.","Biro Kesekretariatan","Laporan, checklist","Lengkap atau perlu revisi","1 hari kerja"],["4","Perbaikan: Melengkapi laporan sesuai catatan pemeriksaan.","Menteri / Kabiro","Catatan pemeriksaan","Laporan diperbaiki","1 hari kerja"],["5","Verifikasi sampel: Mencocokkan sebagian butir laporan dengan bukti dan data keuangan; mencatat hasilnya.","Irjen","Laporan lengkap, bukti","Catatan verifikasi","2 hari kerja"],["6","Konsolidasi: Menyusun rekap laporan kabinet: status tiap unit, masalah utama, dan kebutuhan keputusan.","Sekjen","Laporan lengkap, catatan Irjen","Rekap laporan kabinet","Hari kerja ke-5"],["7","Telaah dan tindak lanjut: Menelaah rekap, menghubungi unit yang bermasalah, dan menetapkan isu untuk Rapat Kabinet.","Wapres","Rekap","Instruksi tindak lanjut","2 hari kerja"],["8","Penyajian dan pengarsipan: Menyajikan rekap pada Rapat Kabinet, memasukkan keputusan ke daftar tindak lanjut, dan menyimpan laporan di repositori resmi.","Sekjen dan Biro Kesekretariatan","Rekap, notulen","Keputusan tercatat, arsip lengkap","3 hari kerja setelah rapat"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Laporan bulanan unit diterima paling lambat hari kerja ke-3 setiap bulan dan rekap kabinet tersedia paling lambat hari kerja ke-5. Hasil akhir: rekap laporan kabinet dan arsip laporan unit."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Laporan terlambat: Sekjen mengirim pengingat satu kali; keterlambatan lanjutan ditangani melalui SOP-MONEV-008.","Isi laporan tidak sesuai bukti: laporan dikembalikan; bila diduga disengaja, diteruskan melalui SOP- SDM-013.","Laporan memuat kejadian darurat, insiden, atau dugaan penyalahgunaan dana: segera dilaporkan kepada Presiden dan ditangani melalui SOP-GOV-007 atau SOP-RSK terkait.","Unit tidak dapat melapor karena kendala teknis: laporan disampaikan melalui jalur cadangan yang ditunjuk Sekjen dan dicatat."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% laporan unit diterima tepat waktu.","Minimal 90% laporan lengkap pada penyerahan pertama.","Rekap laporan kabinet tersedia paling lambat hari kerja ke-5.","Tidak ditemukan ketidaksesuaian material antara laporan dan bukti pada verifikasi sampel."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan Progres Unit setiap bulan dan laporan insidental bila ada.","Rekap laporan kabinet.","Catatan verifikasi sampel Irjen.","Daftar tindak lanjut dan arsip laporan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Monitoring dan Evaluasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Biro Kesekretariatan memeriksa kelengkapan arsip laporan setiap bulan; Irjen menilai kepatuhan unit dan akurasi laporan pada pengawasan berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Susun laporan unit → Serahkan lewat kanal resmi → Periksa kelengkapan → Verifikasi sampel Irjen → Rekap kabinet → Telaah Wapres → Sajikan di Rapat Kabinet → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan Progres Unit","Unit; periode; capaian dibanding target; kegiatan berjalan; kendala; penggunaan anggaran; rencana bulan depan; kebutuhan keputusan; bukti; pelapor; tanggal."],["Formulir Laporan Insidental","Unit; waktu kejadian; uraian; dampak; tindakan awal; bantuan atau keputusan yang dibutuhkan; pelapor."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh kolom wajib terisi dan sesuai target bulanan.","☐ Ya ☐ Tidak"],["2","Bukti pendukung dilampirkan dan dapat dibuka.","☐ Ya ☐ Tidak"],["3","Laporan diserahkan melalui kanal resmi sebelum tenggat.","☐ Ya ☐ Tidak"],["4","Verifikasi sampel telah dilakukan dan dicatat.","☐ Ya ☐ Tidak"],["5","Rekap kabinet disajikan dan tindak lanjut tercatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-MONEV-004","g":"Monitoring, Evaluasi, dan Pengawasan","t":"Evaluasi Pelaksanaan Program Kerja","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[743,746],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur evaluasi pelaksanaan program kerja kabinet secara berkala dan setelah program selesai, mencakup ketepatan waktu, capaian, anggaran, kepatuhan prosedur, dan manfaat, sehingga menghasilkan penilaian tertulis dan rekomendasi perbaikan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh program kerja kabinet dan unit pelaksananya. Evaluasi pada tingkat kegiatan oleh panitia mengikuti SOP-PRO-021 dan menjadi masukan SOP ini. SOP ini tidak mengatur LPJ kegiatan (SOP- PRO-020), pembatalan program (SOP-PRO-022), dan penilaian kinerja individu (SOP-MONEV-005)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 14 huruf d (Rapat Evaluasi).","ART Pasal 10 ayat (1) (mengevaluasi pelaksanaan program kerja) dan ART Pasal 7 ayat (5) huruf c (evaluasi kinerja organisasi pada Mubes).","ART Pasal 9 ayat (5) dan (6) (hasil Raker sebagai pedoman; persetujuan Pembina).","AD Pasal 17 ayat (2) (pengelolaan efektif dan efisien).","SOP-GOV-006 (Rapat Kabinet dan Rapat Evaluasi), SOP-MONEV-001, SOP-MONEV-002, dan SOP-MONEV-003."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Evaluasi program","Penilaian sistematis atas pelaksanaan dan hasil suatu program kerja dibanding rencana."],["Rapat Evaluasi","Rapat untuk menilai capaian dan masalah berulang (SOP-GOV-006)."],["Evaluasi mandiri","Penilaian yang dilakukan sendiri oleh unit atau penanggung jawab program sebelum dibahas."],["Rekomendasi","Saran tindakan hasil evaluasi: lanjutkan, perbaiki, ganti, tunda, atau hentikan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Evaluasi dilakukan setiap triwulan untuk seluruh program berjalan dan setelah program selesai serta LPJ diterima (usulan).","Kriteria: kesesuaian dengan program yang disetujui Pembina, ketepatan waktu, capaian hasil dibanding target, penggunaan anggaran dibanding RAB, kepatuhan prosedur dan administrasi, serta manfaat bagi sasaran program.","Penilaian berbasis data dan bukti dari SOP-MONEV-002, SOP-MONEV-003, LPJ, dan hasil verifikasi Irjen, bukan kesan pribadi.","Evaluasi bersifat pembinaan: fokus pada perbaikan sistem. Dugaan pelanggaran individu ditangani melalui SOP-SDM-013, bukan dalam forum evaluasi program.","Status program (usulan): Tercapai, Tercapai sebagian, atau Belum tercapai, disertai rekomendasi.","Rekomendasi diteruskan ke SOP-MONEV-010. Pembatalan atau penundaan program mengikuti SOP- PRO-022.","Pihak yang dievaluasi diberi kesempatan menjelaskan sebelum penilaian ditetapkan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Wakil Presiden","A","Memimpin evaluasi program Eksekutif dan menetapkan hasil evaluasi."],["Sekretaris Jenderal","R","Menjadwalkan, mengumpulkan bahan, mencatat, dan menyusun laporan evaluasi."],["Menteri / Kabiro / Ketua pelaksana","R","Menyusun evaluasi mandiri dan memaparkan hasil program."],["Inspektur Jenderal","R","Menyampaikan hasil verifikasi dan catatan pengawasan."],["Presiden","C","Memberi arahan strategis dan memutuskan rekomendasi yang melampaui kewenangan unit."],["Seluruh pengurus","I","Menerima hasil evaluasi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Rekap capaian bulanan dan laporan progres unit.","LPJ kegiatan dan hasil evaluasi kegiatan (SOP-PRO-020 dan SOP-PRO-021).","Hasil verifikasi dan temuan Irjen.","Program kerja yang telah disahkan Raker dan persetujuan Pembina."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penjadwalan: Menetapkan jadwal evaluasi triwulan dan evaluasi per program pada kalender organisasi.","Sekjen","Kalender, timeline","Jadwal evaluasi","Awal periode; diperbarui sesuai kebutuhan"],["2","Evaluasi mandiri: Mengisi Lembar Evaluasi Mandiri Program berdasarkan kriteria, termasuk kendala dan pembelajaran.","Menteri / Kabiro / Ketua pelaksana","Rekap capaian, LPJ","Evaluasi mandiri","H-7 Rapat Evaluasi"],["3","Penyusunan bahan: Menggabungkan evaluasi mandiri, data capaian, anggaran, dan hasil verifikasi Irjen menjadi satu bahan evaluasi.","Sekjen","Evaluasi mandiri, data","Paket bahan evaluasi","H-5"],["4","Telaah awal: Menelaah kesenjangan antara evaluasi mandiri dan data; Irjen menyampaikan catatan verifikasi.","Wapres dan Irjen","Paket bahan","Catatan telaah","H-2"],["5","Rapat Evaluasi: Membahas tiap program: capaian, penyebab, dan pembelajaran; memberi kesempatan klarifikasi kepada unit.","Pimpinan rapat","Bahan, catatan telaah","Penilaian dan opsi rekomendasi","Dalam rapat"],["6","Penetapan hasil: Menetapkan status dan rekomendasi tiap program sesuai SOP-GOV-002.","Wapres dan Presiden","Opsi rekomendasi","Keputusan evaluasi","Dalam rapat"],["7","Pencatatan: Menyusun Laporan Evaluasi Program dan notulen rapat.","Sekjen","Hasil rapat","Laporan evaluasi, notulen","3 hari kerja"],["8","Tindak lanjut: Menyerahkan rekomendasi ke penyusunan rencana tindakan korektif (SOP-MONEV-010).","Sekjen dan Wapres","Laporan evaluasi","Daftar rekomendasi diproses","3 hari kerja"],["9","Umpan balik dan arsip: Menyampaikan hasil kepada unit terkait dan menyimpan dokumen di repositori resmi.","Sekjen","Laporan evaluasi","Hasil diterima, arsip lengkap","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Laporan Evaluasi Program diterbitkan paling lambat 3 hari kerja setelah Rapat Evaluasi. Hasil akhir: Laporan Evaluasi Program dan daftar rekomendasi."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Unit tidak menyerahkan bahan: evaluasi disusun dari data yang tersedia, ditandai data tidak lengkap, dan dicatat sebagai temuan administrasi (SOP-MONEV-009).","Perbedaan penilaian antara unit dan pimpinan: diputuskan melalui SOP-GOV-002; bila menyangkut hubungan antarpengurus, gunakan SOP-GOV-010.","Ditemukan penyimpangan berat atau dugaan penyalahgunaan dana: evaluasi biasa dihentikan dan dirujuk ke SOP-RSK-007 serta SOP-GOV-007; Irjen melaporkan kepada KAUR ORMAWA bila berdampak pada institusi (ART Pasal 12 ayat 7).","Program perlu perubahan jadwal, konsep, atau anggaran: ikuti SOP-PRO-015 dan SOP-KEU-014."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% program dievaluasi sesuai jadwal.","Laporan Evaluasi Program terbit paling lambat 3 hari kerja setelah rapat.","Minimal 80% rekomendasi menjadi tindakan korektif yang tercatat.","Persentase program berstatus Tercapai meningkat dari triwulan ke triwulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Lembar Evaluasi Mandiri Program.","Laporan Evaluasi Program dan notulen Rapat Evaluasi.","Daftar rekomendasi dan status program.","Entri pada daftar tindak lanjut."]},{"p":"Seluruh dokumen disimpan pada repositori resmi BEM (folder Monitoring dan Evaluasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal merekap status evaluasi setiap triwulan; Irjen menilai ketepatan evaluasi dan tindak lanjut pada evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Jadwal evaluasi → Evaluasi mandiri → Bahan evaluasi → Telaah Wapres dan Irjen → Rapat Evaluasi → Penetapan hasil → Laporan dan rekomendasi → Tindakan korektif (MONEV-010) → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Evaluasi Mandiri Program","Nama program; penanggung jawab; penilaian enam kriteria; kendala; pembelajaran; usulan rekomendasi; tanggal."],["Templat Laporan Evaluasi Program","Program; periode; capaian; anggaran; temuan; status; rekomendasi; penanggung jawab tindak lanjut; tenggat."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh program berjalan masuk jadwal evaluasi.","☐ Ya ☐ Tidak"],["2","Evaluasi mandiri dan data pendukung tersedia sebelum rapat.","☐ Ya ☐ Tidak"],["3","Unit diberi kesempatan menjelaskan sebelum penilaian ditetapkan.","☐ Ya ☐ Tidak"],["4","Status dan rekomendasi tiap program tercatat pada laporan.","☐ Ya ☐ Tidak"],["5","Rekomendasi telah diteruskan ke SOP-MONEV-010 dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-MONEV-005","g":"Monitoring, Evaluasi, dan Pengawasan","t":"Evaluasi Kinerja Pengurus","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Kepala Biro Kesekretariatan","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[747,751],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penilaian kinerja pengurus berdasarkan kriteria terukur, bukti, dan kesempatan klarifikasi, sebagai dasar pembinaan, apresiasi, dan tindak lanjut yang adil sesuai AD/ART."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh pengurus BEM Kabinet Samasta, yaitu Presiden, Wakil Presiden, Sekretaris Jenderal, Menteri, Kepala Biro, Inspektur Jenderal, serta anggota dan staf. Penilaian dilakukan pada tengah periode dan akhir periode, dan dapat dilakukan insidental atas permintaan pimpinan. SOP ini tidak mengatur penjatuhan sanksi (ART Pasal 12 dan SOP-SDM-013), pembinaan (SOP-SDM-011), apresiasi (SOP-SDM-012), maupun target kerja individu (SOP-SDM-005)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 12 ayat (1), (3), (4), (5), dan (6) (kewenangan pimpinan BEM dan Irjen dalam pembinaan, pengawasan, evaluasi, dan penilaian kinerja pengurus).","ART Pasal 6 ayat (1) dan (2) (syarat umum kepengurusan dan pemberhentian pengurus yang melanggar).","ART Pasal 13 ayat (7) sampai (9) (keadilan, objektivitas, bukti, jangka waktu wajar, dan hak klarifikasi serta pembelaan).","ART Pasal 4 (Wewenang BEM) huruf b (mengangkat dan memberhentikan pengurus internal) dan ART Pasal 11 huruf l (larangan meninggalkan tanggung jawab).","AD Pasal 9 ayat (2) huruf e (tidak mengikuti kegiatan organisasi tiga kali berturut-turut tanpa uzur).","SOP-MONEV-001, SOP-SDM-005, SOP-SDM-006, SOP-SDM-009, SOP-SDM-010, dan SOP-SDM- 018."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kinerja pengurus","Hasil kerja, kualitas, kehadiran, kepatuhan, dan sikap kerja pengurus dibanding tugas dan target yang ditetapkan."],["Rubrik penilaian","Tabel kriteria, bobot, dan skala nilai yang dipakai penilai."],["Penilaian diri","Penilaian yang diisi pengurus tentang kinerjanya sendiri."],["Klarifikasi","Penjelasan atau sanggahan pengurus atas draf hasil penilaian."],["Predikat kinerja","Kategori hasil: Sangat baik, Baik, Cukup, atau Perlu pembinaan (usulan)."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Penilaian dilakukan oleh Irjen (ART Pasal 12 ayat 3). Kementerian PSDM menyediakan instrumen, pemetaan kompetensi, dan pembinaan lanjutan. Keputusan sanksi tetap berada pada pimpinan BEM (ART Pasal 12 ayat 1 dan 5).","Dimensi dan bobot (usulan): capaian target kerja 40%, kualitas dan ketepatan waktu 20%, kehadiran dan partisipasi 15%, kepatuhan prosedur dan etika 15%, kerja sama dan inisiatif 10%.","Sumber data: rekap SOP-MONEV-002 dan SOP-MONEV-003, presensi (SOP-SDM-006), daftar tindak lanjut, hasil verifikasi, serta penilaian atasan langsung. Desas-desus dan data tanpa bukti tidak dipakai.","Sebelum nilai ditetapkan, pengurus menerima draf hasil dan berhak memberi klarifikasi (ART Pasal 13 ayat 9).","Penilaian Presiden dan Wakil Presiden disusun Irjen, dibahas melalui forum resmi BEM, dan diteruskan kepada KAUR ORMAWA atau Pembina (lihat Catatan Penyusun). Penilaian Irjen dibahas Rapat Pimpinan tanpa kehadiran Irjen pada saat penetapan.","Hasil penilaian individu bersifat terbatas: hanya diketahui pengurus yang dinilai, pimpinan, Irjen, dan Kementerian PSDM (SOP-SDM-018). Ringkasan agregat tanpa nama dapat disampaikan kepada seluruh pengurus.","Hasil penilaian dipakai untuk pembinaan, apresiasi, dan pertimbangan penempatan. Hasil penilaian bukan satu-satunya dasar pemberhentian; pemberhentian mengikuti ART Pasal 12 dan SOP-SDM-014."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Inspektur Jenderal","A","Menetapkan jadwal, menghitung dan menetapkan hasil, serta melaporkan hasil penilaian."],["Kementerian PSDM","R","Menyediakan instrumen dan pemetaan kompetensi serta menyusun pembinaan lanjutan."],["Atasan langsung (Menteri / Kabiro / Wapres)","R","Mengisi penilaian atasan berbasis fakta dan bukti."],["Sekretaris Jenderal","R","Menyediakan data presensi, capaian, dan tindak lanjut; mengarsipkan."],["Pengurus yang dinilai","R","Mengisi penilaian diri, memberi bukti, dan menanggapi draf hasil."],["Presiden","C","Menerima hasil dan menetapkan tindak lanjut sesuai kewenangan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Kamus Indikator, uraian tugas, dan target kerja individu.","Rekap capaian bulanan, laporan progres, dan presensi.","Rubrik dan Formulir Penilaian Kinerja Pengurus.","Catatan verifikasi dan temuan Irjen yang relevan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan jadwal dan instrumen: Menetapkan jadwal, rubrik, dan bobot penilaian yang selaras dengan SOP- MONEV-001.","Irjen bersama PSDM","Kamus indikator, uraian tugas","Jadwal dan rubrik","5 hari kerja sebelum periode penilaian"],["2","Pengumuman: Mengumumkan jadwal, kriteria, dan sumber data kepada seluruh pengurus.","Sekjen","Jadwal dan rubrik","Pengumuman resmi","3 hari kerja sebelum penilaian"],["3","Pengumpulan data: Menghimpun rekap capaian, presensi, laporan, dan tindak lanjut tiap pengurus.","Sekjen dan Biro Kesekretariatan","Rekap MONEV, presensi","Paket data per pengurus","3 hari kerja"],["4","Penilaian diri dan atasan: Pengurus mengisi penilaian diri dan atasan langsung mengisi penilaian atasan.","Pengurus dan atasan langsung","Formulir, paket data","Formulir terisi","3 hari kerja"],["5","Penilaian dan verifikasi: Menghitung skor, memeriksa konsistensi penilaian diri, penilaian atasan, dan data; meminta penjelasan atasan bila selisih besar; menyusun draf predikat.","Irjen","Formulir, paket data","Draf hasil penilaian","5 hari kerja"],["6","Draf dan klarifikasi: Menyampaikan draf kepada pengurus yang dinilai dan memberi kesempatan klarifikasi.","Irjen","Draf hasil","Klarifikasi atau persetujuan","3 hari kerja"],["7","Penetapan hasil: Menetapkan hasil akhir dengan mempertimbangkan klarifikasi. Keberatan yang tidak selesai diputuskan Rapat Pimpinan.","Irjen; Rapat Pimpinan untuk keberatan","Draf, klarifikasi","Hasil penilaian","2 hari kerja"],["8","Pelaporan: Menyampaikan ringkasan agregat melalui forum resmi BEM (ART Pasal 13 ayat 6) dan hasil rinci hanya kepada pihak berwenang.","Irjen","Hasil penilaian","Laporan hasil penilaian","3 hari kerja setelah penetapan"],["9","Tindak lanjut dan arsip: Merekomendasikan pembinaan, apresiasi, atau penempatan (SOP- SDM-011 dan SOP-SDM-012) dan menyimpan dokumen dengan akses terbatas.","PSDM, pimpinan, Sekjen","Laporan hasil","Rencana pembinaan atau apresiasi, arsip","5 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Proses penilaian dari penetapan jadwal hingga hasil akhir ditargetkan selesai dalam 20 hari kerja per periode penilaian. Hasil akhir: Hasil Penilaian Kinerja Pengurus dan laporan agregat."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengurus tidak mengisi atau tidak hadir: dinilai berdasarkan data yang tersedia, dicatat, dan dipanggil Wakil Presiden.","Keberatan atas hasil: diajukan tertulis dalam 3 hari kerja dan diputuskan Rapat Pimpinan paling lambat 5 hari kerja.","Ditemukan dugaan pelanggaran etik atau larangan ART Pasal 11: ditangani melalui SOP-SDM-013 dan ART Pasal 12 sampai 13, tidak diputuskan dalam penilaian kinerja.","Konflik kepentingan penilai: penilai diganti sesuai SOP-RSK-006."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pengurus dinilai sesuai jadwal.","100% hasil penilaian didukung bukti dan diberi kesempatan klarifikasi sebelum ditetapkan.","Keberatan diselesaikan paling lambat 5 hari kerja.","Minimal 80% rekomendasi pembinaan dan apresiasi terlaksana."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Rubrik dan Formulir Penilaian Kinerja Pengurus.","Hasil Penilaian Kinerja Pengurus (akses terbatas).","Laporan ringkasan agregat.","Rekomendasi pembinaan, apresiasi, atau penempatan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Monitoring dan Evaluasi, akses terbatas) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan arsip dan pembatasan akses; proses penilaian ditinjau pada evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Jadwal dan rubrik → Pengumpulan data → Penilaian diri dan atasan → Verifikasi Irjen → Draf dan klarifikasi → Penetapan hasil → Laporan dan tindak lanjut → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Rubrik dan Formulir Penilaian Kinerja Pengurus","Nama dan jabatan; periode; lima dimensi dan bobot; skor penilaian diri; skor atasan; bukti; skor akhir; predikat."],["Lembar Klarifikasi dan Keberatan","Nama pengurus; butir yang dipersoalkan; alasan; bukti tambahan; tanggal; tanggapan penilai; keputusan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Rubrik dan bobot telah diumumkan sebelum penilaian.","☐ Ya ☐ Tidak"],["2","Seluruh nilai didukung data atau bukti.","☐ Ya ☐ Tidak"],["3","Pengurus menerima draf dan diberi kesempatan klarifikasi.","☐ Ya ☐ Tidak"],["4","Hasil individu disimpan dengan akses terbatas.","☐ Ya ☐ Tidak"],["5","Tindak lanjut pembinaan atau apresiasi telah ditetapkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Kementerian PSDM; seluruh Menteri dan Kepala Biro (khusus dokumen SOP, rubrik, dan formulir); arsip Biro Kesekretariatan. Hasil penilaian individu tidak didistribusikan secara umum."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-MONEV-006","g":"Monitoring, Evaluasi, dan Pengawasan","t":"Pemeriksaan Kelengkapan Administrasi","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Kepala Biro Kesekretariatan","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[752,755],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pemeriksaan kelengkapan, keabsahan, dan ketepatan waktu dokumen administrasi BEM, sehingga dokumen tertib, dapat ditelusuri, dan siap diperiksa kapan pun diperlukan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk dokumen seluruh unit BEM: surat, proposal dan izin, notulen dan daftar tindak lanjut, presensi, LPJ dan bukti kegiatan, keputusan, serta arsip fisik dan digital. Pemeriksaan dilakukan berkala berbasis sampel dan menyeluruh pada saat tertentu. SOP ini tidak mengatur pembuatan dokumen (SOP-ADM), pemeriksaan kelengkapan proposal sebelum diajukan (SOP-ADM-008), dan pemeriksaan keuangan (SOP-MONEV-007)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 12 ayat (3) dan (4) (pengawasan dan evaluasi dalam rangka pembinaan dan pencegahan pelanggaran).","ART Pasal 13 ayat (4), (5), (6), (7), dan (9) (bukti, pemantauan dan klarifikasi Irjen, hasil melalui forum resmi, keadilan, hak klarifikasi).","ART Pasal 9 ayat (6) (program kerja memerlukan persetujuan Pembina sebelum dilaksanakan).","AD Pasal 17 ayat (2) (pengelolaan transparan dan akuntabel).","SOP-ADM-011 sampai SOP-ADM-014, SOP-ADM-020, dan SOP-RSK-010."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pemeriksaan administrasi","Pencocokan dokumen dengan standar kelengkapan, keabsahan, ketepatan waktu, dan penyimpanan."],["Dokumen wajib","Dokumen yang harus ada pada setiap proses, misalnya izin, notulen, dan bukti kegiatan."],["Sampel","Bagian dokumen yang dipilih untuk diperiksa mewakili seluruh dokumen unit."],["Temuan administrasi","Kekurangan atau penyimpangan dokumen yang dicatat pada Register Temuan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Objek pemeriksaan: persuratan, proposal dan izin Pembina, notulen dan daftar tindak lanjut, presensi, LPJ dan bukti kegiatan, keputusan dan registernya, serta arsip.","Pemeriksaan berkala dilakukan setiap bulan atas minimal 20% dokumen baru tiap unit (usulan). Pemeriksaan menyeluruh 100% dilakukan pada LPJ kegiatan, dokumen serah terima, dan unit yang memiliki temuan berat.","Standar pemeriksaan: kelengkapan, keabsahan (nomor, tanda tangan, kewenangan), ketepatan waktu, konsistensi data, serta penamaan dan lokasi penyimpanan.","Irjen tidak mengubah dokumen yang diperiksa; perbaikan dilakukan unit pemilik dokumen.","Pemeriksaan dilakukan dengan prinsip keadilan, objektivitas, dan bukti (ART Pasal 13 ayat 7). Unit diberi kesempatan klarifikasi dan perbaikan sebelum temuan ditetapkan (ART Pasal 13 ayat 9).","Dokumen rahasia diperiksa hanya oleh Irjen sesuai pembatasan akses (SOP-ADM-020 dan SOP-RSK- 010) dan isinya tidak disebarkan.","Hasil pemeriksaan: Lengkap, Lengkap dengan catatan, atau Tidak lengkap. Temuan dicatat pada Register Temuan (SOP-MONEV-009)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Inspektur Jenderal","A","Merencanakan, melaksanakan, dan menetapkan hasil pemeriksaan."],["Biro Kesekretariatan","R","Menyediakan Register Dokumen, akses arsip, dan daftar dokumen yang diperiksa."],["Menteri / Kabiro","R","Menyiapkan dokumen unit, memberi klarifikasi, dan memperbaiki kekurangan."],["Sekretaris Jenderal","C","Memberi masukan standar dokumen dan memantau perbaikan."],["Wakil Presiden","I","Menerima hasil dan menindaklanjuti unit Eksekutif."],["Presiden","I","Menerima ringkasan hasil pemeriksaan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Rencana pemeriksaan dan Register Dokumen.","Checklist Pemeriksaan Administrasi.","Dokumen unit yang diperiksa.","Hasil pemeriksaan sebelumnya dan status tindak lanjut."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Rencana pemeriksaan: Menyusun jadwal dan cakupan pemeriksaan (sampel atau menyeluruh) serta unit yang diperiksa.","Irjen","Kalender, Register Dokumen","Rencana pemeriksaan","Awal bulan"],["2","Pemberitahuan: Memberi tahu unit tentang jadwal dan dokumen yang perlu disiapkan. Pemeriksaan tanpa pemberitahuan hanya atas dugaan pelanggaran dan diketahui Presiden.","Irjen","Rencana pemeriksaan","Unit mengetahui jadwal","2 hari kerja sebelum pemeriksaan"],["3","Penyiapan dokumen dan akses: Menyiapkan dokumen dan membuka akses arsip sesuai batas hak akses.","Menteri / Kabiro dan Biro Kesekretariatan","Pemberitahuan","Dokumen tersedia","Sebelum jadwal"],["4","Pemeriksaan: Mencocokkan dokumen dengan Checklist Pemeriksaan Administrasi dan mencatat butir lengkap atau tidak lengkap.","Irjen","Dokumen, checklist","Catatan hasil sementara","5 hari kerja"],["5","Konfirmasi dan klarifikasi: Menyampaikan hasil sementara kepada unit dan menerima klarifikasi atau kelengkapan dokumen.","Irjen dan Menteri / Kabiro","Hasil sementara","Klarifikasi atau dokumen tambahan","3 hari kerja"],["6","Penetapan hasil: Menetapkan status akhir, mencatat temuan pada Register Temuan, dan menyusun rekomendasi.","Irjen","Hasil sementara, klarifikasi","Laporan Hasil Pemeriksaan Administrasi","2 hari kerja"],["7","Penyampaian: Menyampaikan hasil melalui Rapat Kabinet atau forum resmi BEM dan kepada unit terkait.","Irjen","Laporan hasil","Hasil diterima","Rapat Kabinet terdekat"],["8","Perbaikan: Melengkapi atau memperbaiki dokumen sesuai rekomendasi dan tenggat.","Menteri / Kabiro","Rekomendasi","Dokumen diperbaiki","10 hari kerja (usulan)"],["9","Verifikasi penutupan: Memeriksa perbaikan, menutup temuan, dan mengarsipkan laporan.","Irjen dan Biro Kesekretariatan","Dokumen perbaikan","Temuan ditutup, arsip","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pemeriksaan dari pelaksanaan hingga laporan hasil ditargetkan selesai paling lambat 10 hari kerja. Hasil akhir: Laporan Hasil Pemeriksaan Administrasi dan Register Temuan yang diperbarui."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Dokumen hilang atau diduga dipalsukan: dilaporkan segera kepada Presiden, dipulihkan sesuai SOP- ADM-015, dan diproses melalui SOP-RSK terkait.","Unit tidak menyediakan dokumen atau menghambat pemeriksaan: diteruskan kepada Wakil Presiden; bila berlanjut, ditangani melalui SOP-GOV-010.","Temuan berat yang berdampak pada institusi: dibahas melalui SOP-GOV-007 dan dilaporkan Irjen kepada KAUR ORMAWA (ART Pasal 12 ayat 7).","Temuan yang sama muncul berulang: dicatat sebagai masalah berulang pada SOP-MONEV-009."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% unit diperiksa sesuai rencana.","Minimal 90% dokumen sampel dinyatakan lengkap pada triwulan kedua dan seterusnya (usulan).","Temuan administrasi ditutup paling lambat 10 hari kerja.","Jumlah temuan administrasi berulang menurun dari bulan ke bulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Rencana Pemeriksaan Administrasi.","Checklist Pemeriksaan Administrasi yang telah terisi.","Laporan Hasil Pemeriksaan Administrasi.","Entri pada Register Temuan."]},{"p":"Seluruh dokumen disimpan pada repositori resmi BEM (folder Monitoring dan Evaluasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memantau penutupan temuan administrasi setiap bulan; Rapat Evaluasi meninjau tren temuan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Rencana pemeriksaan → Pemberitahuan unit → Pemeriksaan dokumen → Klarifikasi unit → Penetapan hasil → Perbaikan dokumen → Verifikasi penutupan → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Checklist Pemeriksaan Administrasi","Unit; jenis dokumen; kelengkapan; keabsahan; ketepatan waktu; konsistensi; lokasi simpan; hasil; catatan pemeriksa."],["Templat Laporan Hasil Pemeriksaan Administrasi","Unit; periode; cakupan; hasil; temuan; rekomendasi; penanggung jawab perbaikan; tenggat."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Rencana pemeriksaan dan cakupan telah ditetapkan.","☐ Ya ☐ Tidak"],["2","Unit diberi kesempatan klarifikasi sebelum temuan ditetapkan.","☐ Ya ☐ Tidak"],["3","Hasil dan temuan tercatat pada Register Temuan.","☐ Ya ☐ Tidak"],["4","Perbaikan diverifikasi sebelum temuan ditutup.","☐ Ya ☐ Tidak"],["5","Laporan hasil tersimpan pada repositori resmi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-MONEV-007","g":"Monitoring, Evaluasi, dan Pengawasan","t":"Pemeriksaan Pertanggungjawaban Keuangan","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Kepala Biro Kesekretariatan","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[756,760],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pemeriksaan LPJ keuangan kegiatan dan laporan keuangan BEM terhadap bukti, anggaran yang disetujui, dan prinsip pengelolaan keuangan yang amanah, transparan, serta sesuai syariah, sehingga penyimpangan dapat dicegah atau ditemukan dan pertanggungjawaban dapat diterima."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk LPJ keuangan kegiatan, laporan keuangan bulanan Biro Keuangan, uang muka, serta penerimaan dari sponsor, donasi, dan kontribusi. SOP ini tidak mengatur penyusunan laporan keuangan (SOP- KEU-015), pemeriksaan bukti oleh Biro Keuangan (SOP-KEU-016), rekonsiliasi kas berkala (SOP-KEU- 017), dan penanganan dugaan penyalahgunaan dana (SOP-RSK-007)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) sampai (4) (sumber keuangan, larangan riba, gharar, dan maysir, bukti penerimaan resmi, serta anggaran yang disetujui KAUR ORMAWA).","AD Pasal 17 ayat (1) sampai (3) (laporan pertanggungjawaban berkala, transparan, dan dibahas dalam Mubes).","ART Bab II Pasal 3 (Kewajiban BEM) huruf e dan g; ART Bab III Pasal 3 (Tugas BEM) huruf e (anggaran dengan persetujuan BPM dan laporan pertanggungjawaban).","ART Pasal 10 ayat (4) huruf b (monitoring penggunaan anggaran) dan ART Pasal 11 huruf i (larangan korupsi, manipulasi, dan penyelewengan dana).","ART Pasal 12 ayat (3) dan (7); ART Pasal 13 ayat (4), (7), dan (9).","SOP-KEU-015, SOP-KEU-016, SOP-KEU-017, SOP-PRO-020, dan SOP-RSK-007."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["LPJ keuangan","Laporan pertanggungjawaban penggunaan dana suatu kegiatan atau periode, disertai bukti."],["Bukti transaksi sah","Kuitansi, nota, atau bukti transfer yang memuat tanggal, nominal, pihak, dan uraian transaksi."],["RAB","Rencana anggaran biaya yang telah disetujui."],["Selisih anggaran","Perbedaan antara anggaran yang disetujui dan realisasi."],["Pemisahan fungsi","Pemisahan pihak yang mengajukan, menyetujui, memegang dana, dan memeriksa."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Irjen tidak boleh merangkap fungsi pengaju, pemberi persetujuan, atau pemegang dana atas transaksi yang diperiksa.","Cakupan: kesesuaian realisasi dengan RAB; kelengkapan dan keabsahan bukti; kewajaran nominal; kepatuhan syariah (sumber dan penggunaan dana bebas riba, gharar, maysir); pencatatan pemasukan dengan bukti penerimaan resmi; kecocokan saldo kas dan rekening; serta persetujuan anggaran oleh KAUR ORMAWA dan BPM.","Seluruh LPJ keuangan kegiatan diperiksa 100% sebelum disahkan. Laporan bulanan Biro Keuangan diperiksa minimal 30% transaksi, ditambah seluruh transaksi di atas batas nilai yang ditetapkan Presiden setelah uji coba (usulan).","Hasil pemeriksaan: Diterima, Diterima dengan catatan, Dikembalikan untuk perbaikan, atau Diteruskan sebagai dugaan penyimpangan.","Irjen tidak menyimpulkan adanya pelanggaran. Dugaan penyimpangan diteruskan kepada Presiden dan Wakil Presiden dan diproses melalui SOP-RSK-007. Pelanggaran berat yang berdampak pada institusi dilaporkan Irjen kepada KAUR ORMAWA (ART Pasal 12 ayat 7).","Pihak yang diperiksa berhak memberi klarifikasi dan bukti tambahan sebelum hasil ditetapkan (ART Pasal 13 ayat 9).","Data rekening dan keuangan bersifat terbatas (SOP-RSK-010) dan tidak disebarkan di luar pihak berwenang."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Inspektur Jenderal","A","Memeriksa, menetapkan hasil, dan melaporkan hasil pemeriksaan keuangan."],["Biro Keuangan","R","Menyerahkan LPJ dan bukti, memberi klarifikasi, dan menindaklanjuti catatan."],["Ketua pelaksana dan bendahara kegiatan","R","Menyusun LPJ, melampirkan bukti, dan memperbaiki catatan."],["Biro Kesekretariatan","R","Mengarsipkan LPJ final dan laporan hasil pemeriksaan dengan akses terbatas."],["Presiden","C","Menerima hasil, menetapkan penerimaan LPJ, dan memutuskan penanganan dugaan penyimpangan."],["Sekretaris Jenderal","I","Memantau kelengkapan arsip dan tindak lanjut."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["LPJ keuangan beserta RAB final dan bukti transaksi.","Persetujuan anggaran dan bukti penerimaan dana.","Rekening koran atau catatan kas.","Checklist Pemeriksaan LPJ Keuangan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan LPJ: Menerima LPJ keuangan beserta RAB, persetujuan anggaran, dan bukti transaksi; mencatat tanda terima.","Biro Keuangan dan Irjen","LPJ, bukti","Tanda terima","Sesuai tenggat SOP-PRO-020"],["2","Pemeriksaan kelengkapan awal: Memeriksa kelengkapan dokumen; mengembalikan LPJ yang belum lengkap.","Irjen","LPJ","Lengkap atau dikembalikan","1 hari kerja"],["3","Pemeriksaan substantif: Mencocokkan realisasi dengan RAB, memeriksa bukti satu per satu, menghitung ulang total, memeriksa kepatuhan syariah, bukti pemasukan, dan saldo; mencatat pada checklist.","Irjen","LPJ, RAB, bukti","Catatan pemeriksaan","5 hari kerja"],["4","Klarifikasi: Menyampaikan catatan dan meminta penjelasan atau bukti tambahan.","Irjen, Biro Keuangan, Ketua pelaksana","Catatan pemeriksaan","Jawaban dan bukti tambahan","3 hari kerja"],["5","Penetapan hasil: Menetapkan hasil pemeriksaan dan menyusun Laporan Hasil Pemeriksaan Keuangan.","Irjen","Catatan, jawaban","Laporan hasil pemeriksaan","2 hari kerja"],["6","Penyampaian: Menyampaikan laporan kepada Presiden dan Wakil Presiden; ringkasan disampaikan melalui forum resmi BEM; dugaan penyimpangan diteruskan sesuai ketentuan.","Irjen","Laporan hasil","Laporan diterima","1 hari kerja"],["7","Perbaikan dan penyelesaian selisih: Memperbaiki LPJ, melengkapi bukti, dan menyelesaikan selisih atau kelebihan dana (SOP-KEU-018).","Ketua pelaksana dan Biro Keuangan","Catatan hasil","LPJ perbaikan, selisih diselesaikan","5 hari kerja"],["8","Verifikasi penutupan: Memeriksa perbaikan; LPJ final disahkan sesuai SOP-PRO-020; temuan ditutup.","Irjen","LPJ perbaikan","Status final, temuan ditutup","2 hari kerja"],["9","Pengarsipan: Menyimpan LPJ final, laporan hasil, dan bukti pada repositori dengan akses terbatas.","Biro Kesekretariatan","Dokumen final","Arsip lengkap","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pemeriksaan satu LPJ keuangan ditargetkan selesai paling lambat 12 hari kerja sejak LPJ diterima lengkap, belum termasuk waktu perbaikan oleh pelaksana. Hasil akhir: Laporan Hasil Pemeriksaan Keuangan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Bukti transaksi tidak ada atau tidak sah: dicatat sebagai tidak dapat dipertanggungjawabkan; pelaksana diminta bukti pengganti yang sah dan surat pernyataan; temuan tetap dicatat.","Selisih besar yang tidak dapat dijelaskan atau dugaan manipulasi: diproses melalui SOP-RSK-007 dan SOP-GOV-007; bila berat dan berdampak pada institusi, dilaporkan kepada KAUR ORMAWA.","Transaksi atau sumber dana tidak sesuai prinsip syariah: tidak diterima, dicatat sebagai temuan, dan dibahas pimpinan.","Irjen memiliki konflik kepentingan atas transaksi yang diperiksa: penilai diganti sesuai SOP-RSK-006."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% LPJ keuangan diperiksa sebelum disahkan.","Laporan hasil pemeriksaan terbit paling lambat 12 hari kerja sejak LPJ lengkap.","Temuan keuangan ditutup paling lambat 10 hari kerja setelah perbaikan.","Tidak ada transaksi tanpa bukti sah pada LPJ final."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Checklist Pemeriksaan LPJ Keuangan.","Laporan Hasil Pemeriksaan Keuangan.","LPJ final yang telah disahkan.","Entri pada Register Temuan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Monitoring dan Evaluasi, akses terbatas) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan arsip keuangan setiap bulan; Rapat Evaluasi meninjau tren temuan keuangan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima LPJ → Periksa kelengkapan → Pemeriksaan substantif → Klarifikasi → Penetapan hasil → Perbaikan dan selisih → Verifikasi penutupan → Arsip terbatas → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Checklist Pemeriksaan LPJ Keuangan","Kegiatan; kesesuaian RAB; keabsahan bukti; kewajaran nominal; kepatuhan syariah; bukti pemasukan; saldo; hasil; catatan."],["Templat Laporan Hasil Pemeriksaan Keuangan","Kegiatan atau periode; cakupan; hasil; temuan; selisih; rekomendasi; penanggung jawab; tenggat."],["Surat Pernyataan Bukti Pengganti","Nama; kegiatan; rincian transaksi; alasan bukti hilang; pernyataan; tanda tangan; persetujuan Biro Keuangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pemeriksa tidak merangkap fungsi atas transaksi yang diperiksa.","☐ Ya ☐ Tidak"],["2","Realisasi dicocokkan dengan RAB dan seluruh bukti diperiksa.","☐ Ya ☐ Tidak"],["3","Kepatuhan syariah dan bukti pemasukan telah diperiksa.","☐ Ya ☐ Tidak"],["4","Pihak yang diperiksa diberi kesempatan klarifikasi.","☐ Ya ☐ Tidak"],["5","Laporan hasil dan LPJ final tersimpan dengan akses terbatas.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Biro Keuangan; arsip Biro Kesekretariatan (akses terbatas). Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-MONEV-008","g":"Monitoring, Evaluasi, dan Pengawasan","t":"Penanganan Pekerjaan yang Terlambat","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[761,764],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur mengidentifikasi, mengklasifikasi, menangani, dan mencegah keterlambatan pekerjaan, penugasan, dan target kabinet, agar penyebab segera diatasi secara adil dan proporsional dengan pembinaan sebagai langkah pertama."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk keterlambatan target bulanan, laporan, tindak lanjut rapat, penugasan, dan dokumen oleh pengurus maupun unit. SOP ini tidak mengatur sanksi (ART Pasal 12 dan SOP-SDM-013), perubahan jadwal atau konsep kegiatan (SOP-PRO-015), dan kendala lapangan saat kegiatan berlangsung (SOP-PRO-016)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 10 ayat (1) dan (4) (Rapat Koordinasi mengevaluasi program dan menyelesaikan permasalahan internal).","ART Pasal 12 ayat (1) dan (2) (pembinaan dan jenis sanksi oleh pimpinan BEM); ART Pasal 11 huruf l (larangan meninggalkan tanggung jawab).","AD Pasal 9 ayat (2) huruf e (uzur sebagai alasan yang dibenarkan).","ART Pasal 13 ayat (7) sampai (9) (keadilan, jangka waktu wajar, dan hak klarifikasi).","SOP-MONEV-002, SOP-MONEV-003, SOP-GOV-008, SOP-GOV-010, SOP-SDM-008, dan SOP- SDM-011."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Keterlambatan","Kondisi pekerjaan melewati tenggat tanpa selesai dan tanpa perubahan target yang sah."],["Tingkat keterlambatan","Ringan (1 sampai 3 hari kerja), Sedang (4 sampai 7 hari kerja), Berat (lebih dari 7 hari kerja atau menghambat keputusan atau kegiatan penting) (usulan)."],["Rencana pemulihan","Rencana tindakan, tenggat baru, dan dukungan yang dibutuhkan untuk menyelesaikan pekerjaan terlambat."],["Uzur","Alasan yang dibenarkan dan diberitahukan, misalnya sakit atau kebutuhan akademik."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Prinsip: deteksi dini, pembinaan lebih dahulu, sanksi sebagai langkah terakhir.","Keterlambatan karena uzur yang diberitahukan sebelum tenggat tidak dianggap pelanggaran dan ditangani sebagai perubahan target.","Pemicu deteksi: dashboard (SOP-MONEV-002), laporan unit (SOP-MONEV-003), daftar tindak lanjut, dan kalender.","Tindakan bertingkat: Ringan, pengingat tertulis dan tenggat baru paling lama 3 hari kerja; Sedang, pemanggilan oleh Wakil Presiden dan Rencana Pemulihan; Berat, dibahas Rapat Pimpinan atau Rapat Evaluasi dan dapat disertai pengalihan tugas sementara.","Pengalihan tugas sementara dilakukan oleh Wakil Presiden atau Presiden melalui surat tugas atau mandat (SOP-GOV-008).","Keterlambatan berulang (3 kali dalam satu periode atau 2 bulan berturut-turut oleh pelaksana yang sama, usulan) menjadi dasar pembinaan formal (SOP-SDM-011) dan masukan penilaian (SOP- MONEV-005). Sanksi hanya melalui ART Pasal 12 dan SOP-SDM-013.","Keterlambatan yang berdampak pada keuangan, keselamatan, atau kewajiban kepada pihak luar segera dieskalasi kepada Presiden.","Pelaksana berhak menjelaskan sebelum klasifikasi ditetapkan (ART Pasal 13 ayat 9)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Wakil Presiden","A","Mengklasifikasi keterlambatan, menyetujui Rencana Pemulihan, dan memutuskan bantuan atau pengalihan tugas."],["Sekretaris Jenderal","R","Mendeteksi, mengirim pengingat, memantau pemulihan, dan mencatat."],["Menteri / Kabiro / pelaksana","R","Menjelaskan penyebab dan menjalankan Rencana Pemulihan."],["Inspektur Jenderal","C","Memverifikasi penyebab dan hasil pemulihan untuk kasus sedang dan berat."],["Kementerian PSDM","C","Memberi masukan pembinaan bagi pelaksana yang berulang terlambat."],["Presiden","I","Menerima laporan kasus berat."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Dashboard monitoring dan rekap capaian bulanan.","Daftar tindak lanjut rapat dan penugasan.","Pemberitahuan uzur atau izin pelaksana.","Formulir Klarifikasi Keterlambatan dan Rencana Pemulihan Pekerjaan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Deteksi: Memeriksa dashboard, laporan, dan daftar tindak lanjut; menandai pekerjaan yang melewati tenggat.","Sekjen","Dashboard, daftar tindak lanjut","Daftar keterlambatan","Setiap pekan (usulan)"],["2","Pengingat tertulis: Mengirim pengingat melalui kanal resmi kepada pelaksana dengan tembusan atasan langsung.","Sekjen","Daftar keterlambatan","Pengingat terkirim","1 hari kerja setelah terdeteksi"],["3","Klarifikasi penyebab: Menjelaskan penyebab, ada atau tidak uzur, bukti, dan perkiraan penyelesaian.","Pelaksana","Pengingat","Klarifikasi tertulis","2 hari kerja"],["4","Klasifikasi: Menetapkan tingkat keterlambatan dan sah atau tidaknya alasan.","Wapres","Klarifikasi, data","Klasifikasi tercatat","1 hari kerja"],["5","Rencana pemulihan: Untuk kasus sedang dan berat, menyusun Rencana Pemulihan: tindakan, tenggat baru, dan dukungan.","Pelaksana dan atasan; disetujui Wapres","Klasifikasi","Rencana pemulihan","2 hari kerja"],["6","Bantuan atau pengalihan tugas: Bila diperlukan, menambah bantuan atau mengalihkan tugas sementara melalui surat tugas atau mandat.","Wapres atau Presiden","Rencana pemulihan","Surat tugas atau mandat","1 hari kerja"],["7","Pemantauan pemulihan: Memantau pelaksanaan dan mencatat status sampai tenggat baru.","Sekjen","Rencana pemulihan","Status pemulihan","Sesuai tenggat baru"],["8","Verifikasi dan penutupan: Memeriksa hasil pekerjaan; menutup kasus atau mengeskalasi. Irjen memverifikasi kasus sedang dan berat.","Wapres dan Irjen","Bukti penyelesaian","Kasus ditutup atau dieskalasi","2 hari kerja"],["9","Pencatatan: Mencatat penyebab pada Register Temuan; kasus berulang atau berat masuk agenda Rapat Evaluasi.","Sekjen","Hasil penanganan","Entri register, agenda rapat","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pengingat dikirim paling lambat 1 hari kerja setelah keterlambatan terdeteksi dan klasifikasi ditetapkan paling lambat 4 hari kerja. Hasil akhir: pekerjaan selesai atau eskalasi tercatat."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pelaksana tidak menjawab setelah dua pengingat: dipanggil Wakil Presiden; bila tetap tidak responsif, ditangani sebagai dugaan meninggalkan tanggung jawab melalui SOP-SDM-013.","Keterlambatan oleh Menteri, Kabiro, atau unit: ditangani Wakil Presiden dan diteruskan kepada Presiden bila tidak selesai.","Keterlambatan oleh unsur pimpinan: dibahas pada Rapat Pimpinan (SOP-GOV-005) dengan masukan Irjen.","Keterlambatan akibat kendala pihak luar: dicatat, dilaporkan kepada Presiden, dan target diubah melalui SOP-MONEV-002.","Perselisihan penyebab atau tanggung jawab: SOP-GOV-010."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pekerjaan terlambat tercatat dan diberi pengingat paling lambat 1 hari kerja.","Minimal 80% keterlambatan ringan dan sedang selesai sesuai tenggat baru.","Jumlah keterlambatan berat menurun dari bulan ke bulan.","Jumlah pelaksana yang berulang terlambat menurun setelah pembinaan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar keterlambatan.","Formulir Klarifikasi Keterlambatan dan Rencana Pemulihan Pekerjaan.","Surat tugas atau mandat bila ada pengalihan.","Entri pada Register Temuan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Monitoring dan Evaluasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal merekap keterlambatan setiap bulan; Irjen mengambil sampel penanganan kasus untuk memeriksa keadilan dan kepatuhan prosedur."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Deteksi → Pengingat tertulis → Klarifikasi penyebab → Klasifikasi → Rencana pemulihan → Pemantauan → Verifikasi → Tutup atau eskalasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Klarifikasi Keterlambatan","Pelaksana; pekerjaan; tenggat awal; penyebab; uzur dan bukti; perkiraan selesai; tanggal."],["Rencana Pemulihan Pekerjaan","Pekerjaan; tingkat keterlambatan; tindakan; tenggat baru; dukungan; penanggung jawab; persetujuan Wapres."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Keterlambatan tercatat dan pengingat dikirim tepat waktu.","☐ Ya ☐ Tidak"],["2","Pelaksana diberi kesempatan menjelaskan sebelum klasifikasi.","☐ Ya ☐ Tidak"],["3","Tingkat keterlambatan dan tindakan sesuai ketentuan.","☐ Ya ☐ Tidak"],["4","Pemulihan dipantau dan diverifikasi sebelum kasus ditutup.","☐ Ya ☐ Tidak"],["5","Kasus berulang atau berat masuk agenda Rapat Evaluasi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-MONEV-009","g":"Monitoring, Evaluasi, dan Pengawasan","t":"Pencatatan Temuan dan Masalah Berulang","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Kepala Biro Kesekretariatan","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[765,768],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pencatatan, verifikasi, klasifikasi, dan analisis temuan serta masalah berulang yang berasal dari pemantauan, pemeriksaan, dan evaluasi, agar penyebab utama dapat diatasi dan kesalahan yang sama tidak terulang."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk temuan dari SOP-MONEV-002 sampai SOP-MONEV-008, laporan Irjen, Rapat Kabinet dan Rapat Evaluasi, serta pemeriksaan pihak kampus. SOP ini tidak mengatur penanganan pengaduan dan dugaan pelanggaran (SOP-RSK-004, SOP-RSK-005, SOP-RSK-007, dan SOP-SDM-013) maupun pencatatan insiden (SOP-RSK-012), yang memiliki register tersendiri dan dirujuk silang pada Register Temuan."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 12 ayat (3), (4), (6), dan (7) (pengawasan, pembinaan, pencegahan pelanggaran, dan pelaporan pelanggaran berat kepada KAUR ORMAWA).","ART Pasal 13 ayat (4) sampai (9) (bukti, pemantauan dan klarifikasi Irjen, hasil melalui forum resmi, keadilan, jangka waktu wajar, dan hak klarifikasi).","AD Pasal 17 ayat (2) (pengelolaan transparan dan akuntabel).","SOP-MONEV-004 sampai SOP-MONEV-008, SOP-RSK-006, SOP-RSK-009, SOP-RSK-010, SOP- RSK-012, dan SOP-ADM-020."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Temuan","Fakta berbasis bukti tentang kekurangan, penyimpangan, atau risiko yang ditemukan melalui pemantauan, pemeriksaan, atau evaluasi."],["Masalah berulang","Temuan sejenis yang muncul 2 kali atau lebih dalam 3 bulan atau pada 2 unit atau lebih (usulan)."],["Akar masalah","Penyebab mendasar suatu masalah, bukan sekadar gejalanya."],["Kategori temuan","Ringan, Sedang, atau Berat berdasarkan dampak."],["Register Temuan","Daftar tunggal seluruh temuan beserta kategori, penanggung jawab, tenggat, dan status."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Seluruh temuan dicatat pada satu Register Temuan yang dikelola Irjen. Setiap entri memuat nomor, tanggal, sumber, unit, uraian fakta, bukti, kategori, dampak, penanggung jawab, tenggat, dan status.","Kategori (usulan): Ringan, kekurangan administratif tanpa dampak berarti; Sedang, berdampak pada mutu atau ketepatan atau bersifat berulang; Berat, berdampak pada keuangan, keselamatan, reputasi, atau institusi, atau terindikasi melanggar larangan ART Pasal 11.","Temuan harus berbasis fakta dan bukti dan tidak memuat kesimpulan pelanggaran sebelum proses SOP-SDM-013 selesai. Nama individu hanya dicantumkan bila diperlukan untuk penanggung jawab tindak lanjut.","Pihak terkait diberi kesempatan klarifikasi sebelum temuan ditetapkan final (ART Pasal 13 ayat 9).","Irjen dan Sekjen menganalisis masalah berulang setiap bulan: pengelompokan menurut jenis, unit, dan penyebab. Analisis akar masalah dilakukan untuk temuan Berat, Sedang, dan berulang.","Temuan Berat yang berdampak pada institusi dilaporkan Irjen kepada KAUR ORMAWA (ART Pasal 12 ayat 7) di samping kepada pimpinan. Hasil pengawasan disampaikan melalui forum resmi BEM (ART Pasal 13 ayat 6).","Akses Register Temuan: Irjen penuh; Presiden, Wakil Presiden, dan Sekjen membaca temuan yang relevan; unit melihat temuan unitnya; ringkasan tanpa nama dibagikan kepada seluruh pengurus.","Temuan ditutup hanya setelah bukti perbaikan diverifikasi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Inspektur Jenderal","A","Mencatat, memverifikasi, mengklasifikasi, menganalisis, dan menutup temuan."],["Sekretaris Jenderal","R","Mengelola repositori Register Temuan dan membantu analisis masalah berulang."],["Menteri / Kabiro","R","Memberi klarifikasi dan menjalankan tindak lanjut atas temuan unit."],["Wakil Presiden","C","Memastikan setiap temuan memiliki penanggung jawab dan tenggat."],["Presiden","I","Menerima temuan Berat dan ringkasan analisis."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Hasil SOP-MONEV-002 sampai SOP-MONEV-008.","Bukti dan catatan pemeriksaan.","Laporan atau masukan dari unit, rapat, dan pihak kampus.","Register Temuan periode sebelumnya."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan temuan: Menerima temuan dari hasil pemeriksaan, pemantauan, evaluasi, atau laporan dan membuat draf temuan.","Irjen","Hasil MONEV, laporan","Draf temuan","Maks. 2 hari kerja sejak diketahui"],["2","Verifikasi fakta: Memeriksa bukti dan membedakan fakta dari dugaan.","Irjen","Draf temuan, bukti","Temuan terverifikasi","3 hari kerja"],["3","Klarifikasi: Memberi pihak terkait kesempatan menjelaskan dan menyerahkan bukti tambahan.","Irjen dan unit","Temuan terverifikasi","Tanggapan unit","3 hari kerja"],["4","Klasifikasi dan pencatatan: Menetapkan kategori, dampak, penanggung jawab, dan tenggat; mencatat pada Register Temuan.","Irjen","Temuan, tanggapan","Entri Register Temuan","1 hari kerja"],["5","Pemberitahuan: Menyampaikan temuan final kepada unit dan atasan; temuan Berat segera kepada pimpinan.","Irjen","Entri register","Pemberitahuan tercatat","1 hari kerja"],["6","Analisis masalah berulang: Mengelompokkan temuan, mengidentifikasi masalah berulang, dan menganalisis akar masalah.","Irjen dan Sekjen","Register Temuan","Laporan analisis temuan","Bulanan, setelah rekap SOP- MONEV-002"],["7","Pelaporan: Menyampaikan ringkasan temuan dan masalah berulang melalui Rapat Kabinet atau Rapat Evaluasi.","Irjen","Laporan analisis","Ringkasan disampaikan","Rapat bulanan"],["8","Penyerahan ke tindakan korektif: Menyerahkan temuan Sedang, Berat, dan masalah berulang ke SOP- MONEV-010.","Irjen kepada Wapres","Register Temuan, analisis","Daftar untuk rencana tindakan korektif","2 hari kerja setelah pelaporan"],["9","Penutupan dan arsip: Menutup temuan setelah bukti perbaikan diverifikasi dan mengarsipkan dengan akses sesuai ketentuan.","Irjen dan Sekjen","Bukti perbaikan","Temuan ditutup, arsip","Sesuai tenggat tindak lanjut"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Temuan dicatat paling lambat 2 hari kerja sejak diketahui dan ditetapkan final paling lambat 8 hari kerja setelah verifikasi dimulai. Hasil akhir: entri Register Temuan dan laporan analisis bulanan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Temuan terindikasi pelanggaran etik, larangan ART Pasal 11, atau penyalahgunaan dana atau aset: diteruskan ke SOP-SDM-013, SOP-RSK-004, atau SOP-RSK-007.","Temuan Berat: dibahas melalui SOP-GOV-007 dan dilaporkan kepada KAUR ORMAWA bila berdampak pada institusi.","Unit membantah temuan: unit menyerahkan bukti tambahan; bila perbedaan tetap ada, diputuskan Rapat Pimpinan (SOP-GOV-005).","Temuan menyangkut Inspektorat Jenderal sendiri: dicatat oleh Sekretaris Jenderal dan diverifikasi Wakil Presiden sesuai SOP-RSK-006.","Register Temuan bocor atau diakses tanpa hak: ditangani melalui SOP-RSK-009."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% temuan memiliki bukti, kategori, penanggung jawab, dan tenggat.","Minimal 90% temuan Ringan dan Sedang ditutup tepat waktu.","Laporan analisis masalah berulang tersedia setiap bulan.","Jumlah masalah berulang menurun dari triwulan ke triwulan; tidak ada pelanggaran kerahasiaan Register Temuan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Temuan yang diperbarui.","Formulir Temuan dan catatan klarifikasi.","Laporan analisis temuan dan masalah berulang.","Daftar temuan yang diserahkan ke SOP-MONEV-010. Seluruh dokumen disimpan pada repositori resmi BEM (folder Monitoring dan Evaluasi, akses terbatas) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan dan pembatasan akses Register Temuan setiap bulan; evaluasi tengah periode menilai efektivitas pencatatan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima temuan → Verifikasi fakta → Klarifikasi → Klasifikasi dan catat → Analisis berulang → Lapor di rapat → Serahkan ke MONEV-010 → Tutup dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Temuan","Nomor; tanggal; sumber; unit; uraian fakta; bukti; kategori; dampak; penanggung jawab; tenggat."],["Register Temuan","Nomor; tanggal; unit; kategori; status; penanggung jawab; tenggat; rujukan RTK; lokasi arsip."],["Lembar Analisis Akar Masalah","Masalah; frekuensi; unit terkait; rangkaian pertanyaan mengapa; akar masalah; usulan pencegahan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Temuan berbasis fakta dan bukti yang dapat diperiksa.","☐ Ya ☐ Tidak"],["2","Pihak terkait diberi kesempatan klarifikasi.","☐ Ya ☐ Tidak"],["3","Kategori, penanggung jawab, dan tenggat tercatat.","☐ Ya ☐ Tidak"],["4","Analisis masalah berulang dilakukan dan dilaporkan.","☐ Ya ☐ Tidak"],["5","Temuan ditutup hanya setelah verifikasi bukti perbaikan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri dan Kepala Biro (khusus temuan unitnya); arsip Biro Kesekretariatan (akses terbatas). Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-MONEV-010","g":"Monitoring, Evaluasi, dan Pengawasan","t":"Penyusunan Rencana Tindakan Korektif","o":"Wakil Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Wakil Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[769,772],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan, persetujuan, pelaksanaan, pemantauan, dan verifikasi rencana tindakan korektif atas temuan, rekomendasi evaluasi, dan masalah berulang, agar perbaikan konkret, bertenggat, dan tidak berhenti pada catatan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk rencana tindakan korektif (RTK) atas temuan SOP-MONEV-004 sampai SOP-MONEV-009, rekomendasi evaluasi tengah periode, dan arahan Rapat Kabinet. SOP ini tidak mengatur tindakan korektif atas insiden (SOP-RSK-012) dan penjatuhan sanksi (ART Pasal 12)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 12 ayat (3) dan (4) (evaluasi dalam rangka pembinaan dan pencegahan pelanggaran).","ART Pasal 10 ayat (1) dan (4) huruf c (evaluasi pelaksanaan program kerja dan penyelesaian permasalahan internal).","ART Pasal 13 ayat (7) dan (8) (keadilan, objektivitas, dan jangka waktu wajar).","AD Pasal 17 ayat (2) (pengelolaan efektif dan efisien).","SOP-GOV-002, SOP-GOV-004, SOP-GOV-006, SOP-GOV-011, SOP-MONEV-009, SOP-ADM- 010, dan SOP-RSK-012."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Tindakan korektif","Tindakan memperbaiki masalah yang telah terjadi."],["Tindakan pencegahan","Tindakan agar masalah yang sama tidak terulang."],["RTK","Dokumen rencana tindakan korektif yang memuat akar masalah, tindakan, penanggung jawab, tenggat, dan bukti selesai."],["Efektivitas tindakan","Keadaan ketika masalah tidak muncul kembali pada pemeriksaan berikutnya."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap temuan Sedang, Berat, dan masalah berulang wajib memiliki RTK. Temuan Ringan dapat digabung dalam satu RTK per unit.","RTK memuat akar masalah, tindakan perbaikan, tindakan pencegahan, penanggung jawab tunggal, tenggat, sumber daya, indikator selesai, dan bukti.","Tenggat standar (usulan): Ringan 10 hari kerja, Sedang 15 hari kerja, Berat ditetapkan Rapat Pimpinan sesuai tingkat risiko.","RTK disusun oleh unit pemilik masalah dan disetujui Wakil Presiden. RTK Berat, lintas unit, atau berdampak anggaran disetujui Rapat Pimpinan atau Rapat Kabinet (SOP-GOV-002).","Tindakan yang memerlukan persetujuan pihak luar (anggaran, kebijakan) belum berlaku sebelum persetujuan diperoleh.","RTK tidak boleh menyalahkan pihak tanpa bukti. Pembinaan didahulukan; penjatuhan sanksi hanya melalui ART Pasal 12 dan SOP-SDM-013.","Efektivitas diverifikasi Irjen. Bila masalah muncul kembali, RTK disusun ulang dengan analisis lebih mendalam dan eskalasi.","RTK dicatat pada daftar tindak lanjut (SOP-ADM-010)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Wakil Presiden","A","Menunjuk penanggung jawab, menyetujui RTK, dan memastikan pelaksanaan."],["Menteri / Kabiro (pemilik masalah)","R","Menyusun dan melaksanakan RTK serta mengumpulkan bukti."],["Sekretaris Jenderal","R","Mencatat RTK, memantau tenggat, dan melaporkan status."],["Inspektur Jenderal","C","Menelaah RTK dan memverifikasi bukti serta efektivitas tindakan."],["Presiden","C","Menyetujui RTK Berat atau lintas unit bersama Rapat Pimpinan."],["Seluruh pengurus","I","Menjalankan perubahan yang berlaku bagi mereka."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Register Temuan dan laporan analisis (SOP-MONEV-009).","Rekomendasi Laporan Evaluasi Program dan evaluasi tengah periode.","Arahan Rapat Kabinet atau Rapat Pimpinan.","Formulir RTK."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan daftar masalah: Menerima temuan Sedang, Berat, masalah berulang, dan rekomendasi evaluasi yang perlu RTK.","Sekjen","Register Temuan, laporan evaluasi","Daftar masalah yang perlu RTK","1 hari kerja"],["2","Penunjukan penanggung jawab: Menetapkan satu penanggung jawab untuk setiap RTK.","Wapres","Daftar masalah","Penanggung jawab ditetapkan","1 hari kerja"],["3","Penyusunan RTK: Mengisi Formulir RTK berdasarkan analisis akar masalah.","Menteri / Kabiro","Temuan, analisis","Draf RTK","3 hari kerja"],["4","Telaah: Menelaah apakah RTK menjawab akar masalah dan dapat diverifikasi; memeriksa dampak pada jadwal dan anggaran.","Irjen dan Sekjen","Draf RTK","Catatan telaah","2 hari kerja"],["5","Persetujuan: Menyetujui RTK sesuai tingkat: Wakil Presiden, Rapat Pimpinan, atau Rapat Kabinet.","Wapres; Presiden bila berat atau lintas unit","Draf RTK, catatan telaah","RTK disetujui","2 hari kerja"],["6","Pelaksanaan: Melaksanakan tindakan dan mengumpulkan bukti pelaksanaan.","Penanggung jawab","RTK","Bukti pelaksanaan","Sesuai tenggat RTK"],["7","Pemantauan: Memantau progres, mengingatkan pada H-3 tenggat, dan meneruskan keterlambatan ke SOP-MONEV-008.","Sekjen","Daftar RTK","Status RTK","Minimal sekali sebulan"],["8","Verifikasi efektivitas: Memeriksa bukti dan efektivitas; menutup temuan atau meminta RTK disusun ulang.","Irjen","Bukti pelaksanaan","Temuan ditutup atau dibuka kembali","3 hari kerja setelah bukti diterima"],["9","Pelaporan dan arsip: Melaporkan status RTK pada Rapat Kabinet bulanan dan menyimpan dokumen di repositori resmi.","Sekjen","Status RTK","Laporan status, arsip","Setiap Rapat Kabinet"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"RTK disusun paling lambat 5 hari kerja sejak penanggung jawab ditunjuk dan disetujui paling lambat 2 hari kerja setelahnya. Hasil akhir: RTK yang disetujui, dilaksanakan, dan diverifikasi."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["RTK tidak disetujui atau buntu: diputuskan Presiden (keputusan internal) melalui SOP-GOV-002.","Unit tidak menyusun RTK sampai batas waktu: Wakil Presiden menetapkan RTK sementara dan keterlambatan diproses melalui SOP-MONEV-008.","RTK lintas unit memicu konflik: SOP-GOV-004 dan SOP-GOV-010.","Tindakan korektif memerlukan perubahan kebijakan atau SOP: SOP-GOV-011; perubahan AD/ART tidak diputuskan melalui SOP ini.","Masalah berulang setelah RTK selesai: dibahas pada Rapat Evaluasi dan RTK disusun ulang dengan analisis lebih dalam."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% temuan Sedang dan Berat memiliki RTK paling lambat 5 hari kerja sejak penanggung jawab ditunjuk.","Minimal 85% RTK selesai tepat waktu.","Minimal 90% temuan yang ditutup tidak muncul kembali pada pemeriksaan berikutnya.","Jumlah masalah berulang menurun dari triwulan ke triwulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["RTK yang telah disetujui.","Register RTK pada daftar tindak lanjut.","Bukti pelaksanaan dan hasil verifikasi Irjen.","Laporan status RTK bulanan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Monitoring dan Evaluasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal merekap status RTK setiap bulan; Irjen menilai efektivitas RTK pada pemeriksaan berikutnya dan evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima daftar masalah → Tunjuk penanggung jawab → Susun RTK → Telaah Irjen → Persetujuan → Pelaksanaan → Pemantauan → Verifikasi efektivitas → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Rencana Tindakan Korektif","Rujukan temuan; akar masalah; tindakan perbaikan; tindakan pencegahan; penanggung jawab; tenggat; sumber daya; indikator selesai; persetujuan."],["Register Tindakan Korektif","Nomor RTK; rujukan temuan; penanggung jawab; tenggat; status; tanggal verifikasi; hasil efektivitas."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap temuan Sedang dan Berat memiliki RTK.","☐ Ya ☐ Tidak"],["2","RTK memuat akar masalah, tindakan perbaikan, dan tindakan pencegahan.","☐ Ya ☐ Tidak"],["3","RTK memiliki satu penanggung jawab, tenggat, dan indikator selesai.","☐ Ya ☐ Tidak"],["4","Persetujuan diperoleh sesuai tingkat sebelum pelaksanaan.","☐ Ya ☐ Tidak"],["5","Bukti dan efektivitas diverifikasi sebelum temuan ditutup.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-MONEV-011","g":"Monitoring, Evaluasi, dan Pengawasan","t":"Evaluasi Tengah Periode Kabinet","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[773,776],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur evaluasi menyeluruh pada pertengahan masa jabatan untuk menilai capaian, kepatuhan, kinerja, kondisi sumber daya, dan keberlanjutan program, serta menetapkan penyesuaian arah kabinet untuk paruh kedua periode."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk seluruh aspek kabinet: program kerja, indikator, keuangan, administrasi, pengurus, SOP, dan hubungan eksternal. Dilaksanakan satu kali pada pertengahan periode. SOP ini tidak mengatur Mubes (ART Pasal 7), laporan akhir kabinet (SOP-MONEV-012), maupun perubahan AD/ART (AD Bab XI dan ART Bab VII)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 5 ayat (5) (masa jabatan Presiden dan Wakil Presiden satu tahun).","ART Pasal 9 ayat (3), (5), dan (6) (Raker: program, target, dan persetujuan Pembina).","ART Pasal 10 (Rapat Koordinasi) dan AD Pasal 14 huruf d (Rapat Evaluasi).","ART Pasal 12 ayat (3) (evaluasi dan penilaian kinerja oleh Irjen) dan AD Pasal 15 ayat (4) (anggaran dengan persetujuan KAUR ORMAWA).","SOP-GOV-001, SOP-GOV-002, SOP-GOV-006, SOP-GOV-011, dan SOP-MONEV-001 sampai SOP-MONEV-010."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Evaluasi tengah periode","Evaluasi menyeluruh atas kabinet pada sekitar bulan keenam masa jabatan (usulan)."],["Penyesuaian","Perubahan target, program, anggaran, atau cara kerja untuk paruh kedua periode."],["Laporan Evaluasi Tengah Periode","Dokumen yang memuat hasil evaluasi, masalah utama, dan keputusan penyesuaian."],["Paruh kedua","Sisa masa jabatan setelah evaluasi tengah periode."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Evaluasi dilaksanakan melalui Rapat Evaluasi khusus (AD Pasal 14 huruf d) yang dihadiri BPH, Eksekutif, dan Irjen, pada sekitar bulan keenam dan disesuaikan dengan kalender akademik (usulan).","Cakupan wajib: capaian program (SOP-MONEV-004); status indikator (SOP-MONEV-001 sampai SOP-MONEV-003); hasil pemeriksaan administrasi dan keuangan (SOP-MONEV-006 dan SOP- MONEV-007); temuan dan RTK (SOP-MONEV-009 dan SOP-MONEV-010); kinerja pengurus dan jabatan kosong (SOP-MONEV-005); kondisi kas dan aset; hubungan eksternal dan aspirasi mahasiswa; serta keterlaksanaan SOP.","Evaluasi memakai data MONEV yang telah diverifikasi dan tidak memakai data baru tanpa bukti.","Penyesuaian program atau anggaran yang melampaui kewenangan kabinet memerlukan persetujuan Pembina atau KAUR ORMAWA (ART Pasal 9 ayat 6 dan AD Pasal 15 ayat 4) atau forum permusyawaratan yang berwenang.","Penyesuaian SOP dan keputusan Presiden mengikuti SOP-GOV-011. Usulan perubahan AD/ART diarahkan pada prosedur masing-masing.","Rapat ini bukan forum pemberhentian. Kasus berat diarahkan ke SOP-GOV-007 atau Musyawarah Istimewa (ART Pasal 8).","Ringkasan hasil dilaporkan kepada KAUR ORMAWA atau Pembina (usulan) dan hasil lengkap kepada seluruh pengurus.","Evaluasi tengah periode menjadi kesempatan meninjau seluruh SOP sesuai saran urutan uji coba pada Catatan Penyusun."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Menetapkan kerangka, memimpin rapat, dan menerbitkan keputusan penyesuaian."],["Wakil Presiden","R","Memimpin evaluasi unit Eksekutif dan menelaah usulan penyesuaian."],["Sekretaris Jenderal","R","Menyusun bahan, notulen, dan Laporan Evaluasi Tengah Periode."],["Inspektur Jenderal","R","Menyampaikan hasil pengawasan, pemeriksaan, dan penilaian kinerja."],["Menteri / Kabiro","R","Menyusun evaluasi mandiri unit dan memaparkan hasilnya."],["Kementerian PSDM","C","Memberi masukan kondisi SDM dan kebutuhan pembinaan."],["Pembina / KAUR ORMAWA","I","Menerima ringkasan hasil dan memberi persetujuan atas penyesuaian yang memerlukannya."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Rekap MONEV bulanan dan Laporan Evaluasi Program triwulan.","Laporan hasil pemeriksaan administrasi dan keuangan.","Register Temuan, Register RTK, dan hasil penilaian kinerja (agregat).","Data kas, aset, dan kerja sama yang berjalan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan jadwal dan kerangka: Menetapkan tanggal, agenda, dan kerangka Laporan Evaluasi Tengah Periode.","Presiden dan Sekjen","Kalender organisasi dan kampus","Jadwal dan kerangka","Paling lambat 15 hari kerja sebelum rapat"],["2","Pengumpulan data: Menghimpun data SOP-MONEV-001 sampai SOP-MONEV-010 dan data tambahan.","Sekjen","Rekap, register, laporan","Paket data evaluasi","10 hari kerja"],["3","Evaluasi mandiri unit: Mengisi Lembar Evaluasi Tengah Periode Unit: capaian, kendala, kebutuhan, dan usulan penyesuaian.","Menteri / Kabiro","Paket data","Evaluasi mandiri unit","7 hari kerja"],["4","Penilaian Irjen: Menyampaikan penilaian pengawasan, kepatuhan, dan kinerja.","Irjen","Paket data, hasil pemeriksaan","Laporan Irjen","7 hari kerja"],["5","Konsolidasi bahan: Menyusun ringkasan capaian, masalah utama, dan opsi penyesuaian.","Sekjen dan Wapres","Evaluasi unit, laporan Irjen","Bahan Rapat Evaluasi","3 hari kerja"],["6","Rapat Evaluasi Tengah Periode: Membahas hasil dan mengambil keputusan penyesuaian sesuai SOP- GOV-002.","Presiden (pimpinan rapat)","Bahan rapat","Keputusan penyesuaian","1 kali rapat"],["7","Pengajuan persetujuan: Mengajukan penyesuaian program atau anggaran yang memerlukan persetujuan Pembina, KAUR ORMAWA, atau forum lain.","Presiden","Keputusan penyesuaian","Pengajuan terkirim","3 hari kerja"],["8","Penerbitan laporan dan keputusan: Menerbitkan Laporan Evaluasi Tengah Periode dan Keputusan Presiden tentang penyesuaian.","Sekjen dan Presiden","Hasil rapat","Laporan dan Keputusan Presiden","5 hari kerja"],["9","Sosialisasi, tindak lanjut, arsip: Mensosialisasikan hasil, memperbarui target dan RTK, serta menyimpan dokumen.","Sekjen","Laporan, keputusan","Target diperbarui, arsip","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari penetapan jadwal sampai penerbitan laporan ditargetkan selesai dalam 30 hari kerja. Hasil akhir: Laporan Evaluasi Tengah Periode dan Keputusan Presiden tentang penyesuaian."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Ditemukan kondisi darurat (dana, kekosongan pimpinan, kebuntuan): dibahas melalui SOP-GOV-007 atau diajukan ke Musyawarah Istimewa sesuai ART Pasal 8.","Pimpinan tidak sepakat: SOP-GOV-002; bila buntu, Presiden memutuskan untuk keputusan internal.","Pembina atau KAUR ORMAWA tidak menyetujui penyesuaian: program mengikuti persetujuan semula dan penyesuaian ditunda.","Usulan menyentuh isi AD/ART: dialihkan ke prosedur perubahan AD/ART.","Data tidak lengkap saat jadwal tiba: evaluasi tetap dilaksanakan dengan catatan data tidak lengkap dan dilengkapi setelahnya."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Evaluasi tengah periode terlaksana sesuai jadwal.","100% unit menyerahkan evaluasi mandiri.","Keputusan penyesuaian terbit paling lambat 10 hari kerja setelah rapat.","Minimal 80% penyesuaian terlaksana pada paruh kedua periode."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan Evaluasi Tengah Periode.","Keputusan Presiden tentang penyesuaian.","Notulen Rapat Evaluasi Tengah Periode.","Target, indikator, dan RTK yang diperbarui. Seluruh dokumen disimpan pada repositori resmi BEM (folder Monitoring dan Evaluasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memantau pelaksanaan penyesuaian setiap bulan; Irjen menilai ketepatan pelaksanaan keputusan evaluasi pada pengawasan berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Jadwal dan kerangka → Pengumpulan data → Evaluasi unit dan Irjen → Konsolidasi → Rapat Evaluasi → Persetujuan pihak luar → Laporan dan Keputusan Presiden → Sosialisasi dan arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Evaluasi Tengah Periode Unit","Unit; capaian; indikator; kendala; kebutuhan; usulan penyesuaian; pembelajaran; tanggal."],["Templat Laporan Evaluasi Tengah Periode","Ringkasan; capaian; keuangan; temuan dan RTK; SDM; hubungan eksternal; kondisi SOP; keputusan penyesuaian; tindak lanjut."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh cakupan wajib telah dievaluasi menggunakan data terverifikasi.","☐ Ya ☐ Tidak"],["2","Seluruh unit dan Irjen menyampaikan bahan evaluasi.","☐ Ya ☐ Tidak"],["3","Keputusan penyesuaian dicatat sesuai SOP-GOV-002.","☐ Ya ☐ Tidak"],["4","Persetujuan pihak luar telah diajukan untuk penyesuaian yang memerlukannya.","☐ Ya ☐ Tidak"],["5","Laporan dan keputusan tersosialisasi serta diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-MONEV-012","g":"Monitoring, Evaluasi, dan Pengawasan","t":"Penyusunan Laporan Akhir Kabinet","o":"Presiden","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Presiden","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[777,781],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyusunan, pemeriksaan, pengesahan, dan penyampaian Laporan Akhir Kabinet yang merangkum capaian, keuangan, evaluasi, temuan, dan pembelajaran satu periode kepengurusan sebagai pertanggungjawaban kepada BPM dan bahan transisi kabinet berikutnya."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk Presiden, Wakil Presiden, Sekretaris Jenderal, Menteri, Kepala Biro, Inspektur Jenderal, dan seluruh unit. SOP ini tidak mengatur pelaksanaan Mubes (ART Pasal 7), serah terima jabatan, dokumen, dana, aset, dan akun (SOP-TRN-002 sampai SOP-TRN-006). Hubungan dengan SOP-TRN-001 dijelaskan pada Catatan Penyusun."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) sampai (3) (laporan berkala, pengelolaan transparan, penyampaian kepada BPM untuk dibahas dalam Mubes, dan laporan hasil kepada KAUR ORMAWA).","ART Bab III Pasal 3 (Tugas BEM) huruf e (laporan pertanggungjawaban anggaran dan program pada akhir masa jabatan) dan ART Bab II Pasal 3 (Kewajiban BEM) huruf g.","ART Pasal 7 ayat (2), (5), dan (8) (Mubes, evaluasi kinerja organisasi, dan berita acara yang disahkan Ketua STDIIS).","ART Pasal 5 ayat (5) (masa jabatan satu tahun).","SOP-MONEV-001 sampai SOP-MONEV-011 dan SOP-TRN-001 sampai SOP-TRN-010."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Laporan Akhir Kabinet","Laporan pertanggungjawaban kinerja seluruh kabinet selama satu periode kepengurusan."],["Catatan Pemeriksaan Akhir","Catatan Irjen atas kelengkapan dan kesesuaian laporan dengan data MONEV dan laporan keuangan."],["Pembelajaran kabinet","Hal yang berhasil, kendala, dan saran perbaikan yang diwariskan kepada kabinet berikutnya."],["Berita Acara","Catatan resmi hasil sidang Mubes yang disahkan Ketua STDIIS atau pejabat yang ditunjuk."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Isi minimal: ringkasan eksekutif; capaian program dan indikator; laporan keuangan akhir dan saldo; hasil evaluasi tengah periode dan tindak lanjutnya; ringkasan temuan, RTK, dan temuan yang belum selesai; kondisi SDM (agregat); hubungan eksternal dan kerja sama berjalan; aset dan dokumen; kendala dan pembelajaran; rekomendasi untuk kabinet berikutnya; serta lampiran.","Laporan disusun dari data MONEV yang telah diverifikasi. Angka harus cocok dengan rekap dan laporan keuangan yang telah diperiksa (SOP-MONEV-007).","Irjen menerbitkan Catatan Pemeriksaan Akhir dan tidak mengubah isi laporan.","Laporan disahkan Presiden dan disampaikan kepada BPM untuk dibahas dalam Mubes. Hasil pembahasan dilaporkan kepada KAUR ORMAWA (AD Pasal 17 ayat 3). Berita Acara Mubes disahkan Ketua STDIIS atau pejabat yang ditunjuk (ART Pasal 7 ayat 8).","Temuan yang belum selesai wajib dicantumkan secara terbuka beserta statusnya dan diteruskan pada serah terima (SOP-TRN-008).","Laporan tidak memuat data pribadi sensitif dan tidak mencantumkan nilai kinerja individu (SOP- SDM-018).","Jadwal penyusunan mengikuti jadwal Mubes yang ditetapkan; Mubes dianggap sah bila dihadiri minimal 50% peserta yang berhak hadir (ART Pasal 7 ayat 6)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Presiden","A","Mengesahkan Laporan Akhir Kabinet dan menyampaikannya pada Mubes."],["Sekretaris Jenderal","R","Menyusun kerangka, menggabungkan laporan unit, dan mengarsipkan."],["Menteri / Kabiro","R","Menyusun laporan akhir unit dan menyerahkan bukti."],["Biro Keuangan","R","Menyusun laporan keuangan akhir dan rekonsiliasi saldo."],["Inspektur Jenderal","R","Menerbitkan Catatan Pemeriksaan Akhir."],["Wakil Presiden","C","Menelaah draf dan memastikan kelengkapan laporan unit Eksekutif."],["BPM dan KAUR ORMAWA","I","Menerima laporan dan hasil pembahasan sesuai AD Pasal 17 ayat (3)."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Rekap MONEV bulanan dan Laporan Evaluasi Tengah Periode.","Laporan hasil pemeriksaan administrasi dan keuangan.","Register Temuan dan Register RTK.","Data saldo, aset, kerja sama berjalan, dan jadwal Mubes."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan kerangka dan jadwal: Menetapkan outline, jadwal pengumpulan bahan, dan tenggat sesuai jadwal Mubes.","Sekjen; disetujui Presiden","Jadwal Mubes, templat","Kerangka dan jadwal","30 hari kerja sebelum Mubes (usulan)"],["2","Laporan akhir unit: Menyusun laporan akhir unit: capaian, kendala, pembelajaran, aset, dokumen, dan kerja sama berjalan.","Menteri / Kabiro","Rekap MONEV, LPJ","Laporan akhir unit","10 hari kerja"],["3","Laporan keuangan akhir: Menyusun laporan keuangan akhir dan rekonsiliasi saldo.","Biro Keuangan","Catatan keuangan, LPJ","Laporan keuangan akhir","10 hari kerja"],["4","Konsolidasi: Menggabungkan laporan unit menjadi draf Laporan Akhir Kabinet dan memeriksa konsistensi angka.","Sekjen dan Biro Kesekretariatan","Laporan unit, laporan keuangan","Draf laporan","7 hari kerja"],["5","Pemeriksaan akhir: Memeriksa kelengkapan dan kesesuaian draf dengan data MONEV dan laporan keuangan; menyusun Catatan Pemeriksaan Akhir.","Irjen","Draf laporan","Catatan pemeriksaan akhir","5 hari kerja"],["6","Telaah dan perbaikan: Menelaah draf bersama pimpinan dan memperbaiki sesuai catatan.","Wapres, Sekjen, unit","Draf, catatan Irjen","Draf final","5 hari kerja"],["7","Pengesahan: Mengesahkan Laporan Akhir Kabinet.","Presiden","Draf final","Laporan disahkan","2 hari kerja"],["8","Penyampaian dan pembahasan di Mubes: Menyampaikan laporan kepada BPM, memaparkan pada Mubes, dan mencatat hasil pembahasan pada Berita Acara.","Presiden dan Sekjen","Laporan, Berita Acara","Laporan dibahas, Berita Acara","Sesuai jadwal Mubes"],["9","Pelaporan hasil, arsip, dan serah ke transisi: Melaporkan hasil pembahasan kepada KAUR ORMAWA, mengarsipkan, dan menyerahkan laporan serta temuan terbuka ke proses transisi.","Presiden dan Sekjen","Berita Acara, laporan","Laporan hasil, arsip, bahan transisi","5 hari kerja setelah Mubes"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penyusunan dari penetapan kerangka sampai laporan disahkan ditargetkan selesai paling lambat 25 hari kerja sebelum Mubes. Hasil akhir: Laporan Akhir Kabinet yang disahkan, Catatan Pemeriksaan Akhir, dan Berita Acara."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Unit tidak menyerahkan laporan: Sekjen menyusun bagian unit dari data yang tersedia, ditandai tidak lengkap, dan dilaporkan kepada Presiden.","Irjen menemukan ketidaksesuaian angka: laporan tidak disahkan sampai diperbaiki; bila diduga manipulasi, diproses melalui SOP-RSK-007.","BPM meminta perbaikan atau menolak laporan: laporan diperbaiki dan dibahas ulang sesuai ketentuan Mubes.","Mubes tidak memenuhi kuorum: mengikuti ART Pasal 7 ayat (6); jadwal ditetapkan ulang melalui SOP-GOV-002.","Pimpinan berhalangan pada saat penyampaian: SOP-GOV-009."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Laporan Akhir Kabinet diserahkan kepada BPM sesuai jadwal Mubes.","100% unit menyerahkan laporan akhir unit.","Tidak ada ketidaksesuaian angka pada laporan final.","100% temuan yang belum selesai tercantum dan diteruskan pada serah terima."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan Akhir Kabinet yang disahkan Presiden.","Catatan Pemeriksaan Akhir Irjen.","Berita Acara Mubes dan laporan hasil kepada KAUR ORMAWA.","Arsip laporan dan bahan transisi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Monitoring dan Evaluasi) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekretaris Jenderal memeriksa kelengkapan arsip laporan akhir; Irjen memeriksa konsistensi laporan dengan data MONEV sebelum pengesahan."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kerangka dan jadwal → Laporan unit dan keuangan → Konsolidasi → Pemeriksaan akhir Irjen → Pengesahan Presiden → Pembahasan di Mubes → Laporan ke KAUR ORMAWA → Arsip dan transisi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Laporan Akhir Kabinet","Ringkasan eksekutif; capaian; keuangan; evaluasi; temuan dan RTK; SDM; hubungan eksternal; aset dan dokumen; pembelajaran; rekomendasi; lampiran."],["Formulir Laporan Akhir Unit","Unit; capaian; kendala; pembelajaran; aset dan dokumen; kerja sama berjalan; rekomendasi; penyusun; tanggal."],["Templat Catatan Pemeriksaan Akhir","Cakupan pemeriksaan; kesesuaian data; ketidaksesuaian; catatan; pemeriksa; tanggal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Seluruh bagian wajib laporan tersedia dan angka konsisten.","☐ Ya ☐ Tidak"],["2","Catatan Pemeriksaan Akhir Irjen telah diterbitkan.","☐ Ya ☐ Tidak"],["3","Temuan yang belum selesai dicantumkan secara terbuka.","☐ Ya ☐ Tidak"],["4","Laporan disahkan Presiden dan disampaikan kepada BPM.","☐ Ya ☐ Tidak"],["5","Hasil pembahasan dilaporkan kepada KAUR ORMAWA dan seluruh dokumen diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HMK-001","g":"SOP Khusus Unit: Harmonisasi Kampus","t":"Koordinasi dan Pendataan UKM/ORMAWA","o":"Menteri Harmonisasi Kampus","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Harmonisasi Kampus","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[787,790],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pendataan, pembaruan, dan koordinasi rutin dengan HIMA, UKM, dan ormawa lain agar BEM memiliki data yang mutakhir tentang pengurus, kegiatan, dan kebutuhan ormawa, serta koordinasi berjalan teratur dan tercatat."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Berlaku untuk Kementerian Harmonisasi Kampus dan seluruh HIMA, UKM, serta ormawa lain di lingkungan STDIIS Jember yang berhubungan dengan BEM. SOP ini tidak mengatur pengawasan atau penjatuhan sanksi terhadap ormawa (kewenangan KAUR ORMAWA dan BPM) dan tidak mengatur kolaborasi kegiatan (lihat SOP-HMK-003)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Bab III (Tugas BEM) huruf d dan f (koordinasi antar-ormawa dan seluruh kegiatan kemahasiswaan).","ART Pasal 4 huruf g (rekomendasi kepada HIMA dan UKM dalam pelaksanaan kegiatan).","ART Pasal 10 (Rapat Koordinasi) dan Pasal 12 ayat (8) (kewenangan KAUR ORMAWA dan BPM atas pelanggaran).","AD Pasal 20 ayat (1) (unsur organisasi kemahasiswaan: BEM, BPM, HIMA, UKM)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Basis Data Ormawa","Catatan terpadu berisi nama ormawa, pengurus inti, penghubung resmi, kontak, program kerja, dan jadwal kegiatan."],["Penghubung ormawa (liaison)","Pengurus yang ditunjuk ormawa sebagai penghubung resmi dengan BEM."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pendataan bersifat koordinatif, bukan pengawasan; BEM tidak mencampuri urusan internal ormawa.","Data pribadi hanya dikumpulkan seperlunya dan dipakai untuk koordinasi resmi (lihat SOP-SDM- 018).","Data diperbarui paling sedikit setiap semester dan setiap ada pergantian pengurus ormawa.","Rapat koordinasi dengan ormawa mengikuti ART Pasal 10 dan hasilnya dituangkan dalam notulensi resmi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Harmonisasi Kampus","A","Bertanggung jawab atas kelengkapan data dan terlaksananya koordinasi; menyetujui basis data dan jadwal rapat."],["Staf Kementerian Harmonisasi","R","Mengirim formulir, memverifikasi data, menyusun notulensi, dan memantau tindak lanjut."],["Penghubung ormawa","R","Mengisi dan memperbarui data ormawa serta menghadiri rapat koordinasi."],["Sekretaris Jenderal","C","Menyimpan basis data dan memasukkan jadwal koordinasi ke kalender organisasi."],["KAUR ORMAWA","I","Menerima daftar ormawa aktif dan rekap koordinasi bila diminta."],["Inspektur Jenderal","I","Menerima rekap untuk bahan pengawasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar ormawa aktif dari KAUR ORMAWA.","Formulir Data Ormawa.","Kalender organisasi dan kalender akademik."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan daftar ormawa: Memverifikasi daftar HIMA, UKM, dan ormawa aktif bersama KAUR ORMAWA.","Menteri","Daftar dari KAUR ORMAWA","Daftar ormawa aktif","3 hari kerja setelah struktur kabinet ditetapkan"],["2","Pengumpulan data: Mengirim Formulir Data Ormawa kepada penghubung dan meminta pengisian.","Staf","Daftar ormawa","Formulir terkirim","5 hari kerja"],["3","Verifikasi dan penyusunan basis data: Memeriksa kelengkapan dan kebenaran data, mengonfirmasi bila ada yang janggal, lalu menyusun Basis Data Ormawa.","Staf; disetujui Menteri","Formulir terisi","Basis Data Ormawa","3 hari kerja"],["4","Penyerahan arsip: Menyerahkan basis data kepada Sekjen untuk disimpan dan dimasukkan ke kalender organisasi.","Menteri","Basis data","Basis data tersimpan","1 hari kerja"],["5","Penjadwalan koordinasi: Menyusun jadwal rapat koordinasi berkala (usulan satu kali sebulan) dan mengirim undangan melalui kanal resmi.","Staf","Kalender","Undangan terkirim","Minimal 3 hari kerja sebelum rapat"],["6","Pelaksanaan koordinasi: Memimpin rapat, mencatat kebutuhan, masalah, dan rencana kegiatan ormawa.","Menteri","Undangan, agenda","Notulensi","Sesuai jadwal"],["7","Tindak lanjut: Menyusun Daftar Tindak Lanjut dan meneruskannya kepada unit BEM yang terkait.","Staf","Notulensi","Daftar Tindak Lanjut","3 hari kerja setelah rapat"],["8","Pembaruan data: Memperbarui basis data saat ada pergantian pengurus atau perubahan data ormawa.","Staf","Pemberitahuan ormawa","Basis data terbarui","5 hari kerja sejak pemberitahuan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari penetapan daftar ormawa hingga basis data tersimpan paling lama 12 hari kerja. Hasil akhir: Basis Data Ormawa, notulensi rapat koordinasi, dan Daftar Tindak Lanjut."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Ormawa tidak merespons permintaan data: diingatkan melalui penghubung, lalu dilaporkan kepada Wakil Presiden dan KAUR ORMAWA.","Perselisihan antar-ormawa: ditangani melalui SOP-HMK-003 dan, bila menyangkut pengurus BEM, SOP-GOV-010.","Dugaan pelanggaran ormawa: tidak diputuskan Kementerian; dilimpahkan kepada KAUR ORMAWA dan BPM sesuai ART Pasal 12 ayat (8).","Kebocoran atau penyalahgunaan data ormawa: SOP-RSK-009."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% ormawa aktif terdata lengkap dalam 1 bulan sejak penetapan daftar.","Basis data diperbarui paling lambat 5 hari kerja setelah ada perubahan.","Minimal 80% rapat koordinasi terlaksana sesuai jadwal dan seluruhnya bernotulensi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Basis Data Ormawa.","Jadwal dan notulensi rapat koordinasi.","Daftar Tindak Lanjut. Seluruh dokumen disimpan pada repositori resmi BEM (folder Harmonisasi Kampus) oleh Menteri Harmonisasi Kampus bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri memeriksa kemutakhiran data setiap bulan; Sekjen memeriksa kelengkapan penyimpanan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Verifikasi daftar ormawa → Pengumpulan data → Basis data → Arsip Sekjen → Rapat koordinasi → Tindak lanjut → Pembaruan berkala → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Data Ormawa","Nama ormawa; jenis; pengurus inti; penghubung dan kontak resmi; program kerja; tanggal pengisian."],["Templat Notulensi Koordinasi Ormawa","Tanggal; peserta; pokok bahasan; keputusan; tindak lanjut; penanggung jawab; tenggat."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Data ormawa telah dikonfirmasi penghubung.","☐ Ya ☐ Tidak"],["2","Basis data telah diserahkan kepada Sekjen.","☐ Ya ☐ Tidak"],["3","Notulensi terkirim paling lambat 3 hari kerja setelah rapat.","☐ Ya ☐ Tidak"],["4","Setiap tindak lanjut memiliki penanggung jawab dan tenggat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HMK-002","g":"SOP Khusus Unit: Harmonisasi Kampus","t":"Komunikasi dengan Pihak Internal Kampus","o":"Menteri Harmonisasi Kampus","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Harmonisasi Kampus","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[791,794],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan tata cara komunikasi BEM dengan ustadz, dosen, Pembina, KAUR ORMAWA, dan pimpinan kampus agar penyampaian informasi, permohonan, dan aspirasi dilakukan dengan adab, melalui jalur resmi, dan tercatat."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Komunikasi resmi Kementerian Harmonisasi Kampus dan unit BEM lain dengan pihak internal kampus. SOP ini tidak mengatur audiensi formal dengan kampus (lihat SOP-HKE-003) maupun hubungan dengan pihak di luar kampus (lihat SOP-HKE)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf g dan h (penyampaian aspirasi, kritik, dan saran kepada kampus secara konstruktif dan beretika).","ART Pasal 3 huruf d dan h (menjaga nama baik STDIIS dan mematuhi peraturan kampus).","ART Pasal 1 huruf d dan g (KAUR ORMAWA dan Pembina).","ART Pasal 11 huruf g (larangan mencemarkan nama baik organisasi atau lembaga)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pihak internal kampus","Ustadz atau pengajar, dosen, Pembina, KAUR ORMAWA, dan pimpinan STDIIS. Cakupan istilah ustadz dikonfirmasi pada Catatan Penyusun."],["Kanal resmi","Surat, email resmi, atau pesan melalui nomor atau akun resmi unit sesuai SOP-KOM-001."],["Log Komunikasi Internal","Catatan tanggal, pihak, kanal, ringkasan, tanggapan, dan tindak lanjut komunikasi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Komunikasi dilakukan dengan adab: salam, bahasa santun, dan waktu yang patut.","Permohonan dan pemberitahuan resmi disampaikan tertulis mengikuti SOP persuratan; pesan singkat hanya untuk pengantar atau konfirmasi.","Arahan atau keputusan kampus yang diterima secara lisan dikonfirmasi secara tertulis.","Kritik dan aspirasi disampaikan melalui forum atau jalur resmi, bukan melalui media sosial.","Komunikasi tingkat pimpinan kampus dilakukan oleh Presiden atau Wakil Presiden (ART Pasal 4 huruf e)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Harmonisasi Kampus","A","Bertanggung jawab atas ketepatan pihak, jalur, dan adab komunikasi serta kelengkapan catatan."],["Staf Kementerian Harmonisasi","R","Menyusun pesan atau surat, menyampaikan, dan mencatat tanggapan."],["Unit pemohon","R","Mengajukan kebutuhan komunikasi dengan tujuan dan materi yang jelas."],["Presiden / Wakil Presiden","C","Menyetujui dan melakukan komunikasi tingkat pimpinan kampus."],["Sekretaris Jenderal","C","Memberi nomor dan mengarsipkan surat resmi."],["Inspektur Jenderal","I","Menerima rekap untuk bahan pengawasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Permintaan Komunikasi.","Daftar kontak resmi pihak internal kampus.","Draf surat atau pesan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Identifikasi kebutuhan: Unit pemohon mengisi Formulir Permintaan Komunikasi: pihak dituju, tujuan, materi, dan tanggal dibutuhkan.","Unit pemohon","Kebutuhan unit","Formulir terkirim","Minimal 3 hari kerja sebelum dibutuhkan"],["2","Penentuan pihak dan jalur: Menentukan pihak yang dituju dan jalur resmi; komunikasi tingkat pimpinan kampus dialihkan kepada Presiden atau Wakil Presiden.","Menteri","Formulir","Pihak dan jalur ditetapkan","1 hari kerja"],["3","Penyusunan pesan: Menyusun surat atau pesan dengan bahasa santun sesuai SOP-ADM-002.","Staf","Formulir, templat","Draf surat atau pesan","1 hari kerja"],["4","Persetujuan: Memeriksa isi dan adab; hal strategis diajukan kepada Wakil Presiden.","Menteri; Wapres bila strategis","Draf","Persetujuan","1 hari kerja"],["5","Penyampaian: Mengirim melalui kanal resmi dan menyimpan bukti pengiriman.","Staf","Draf disetujui","Bukti pengiriman","2 hari kerja setelah disetujui"],["6","Pencatatan tanggapan: Mencatat tanggapan pada Log Komunikasi Internal; tanggapan lisan dikonfirmasi tertulis.","Staf","Tanggapan","Log terbarui","1 hari kerja setelah tanggapan"],["7","Penerusan hasil: Meneruskan hasil dan arahan kepada unit pemohon.","Menteri","Log","Hasil diterima pemohon","3 hari kerja setelah tanggapan"],["8","Rekap bulanan: Merekap Log dan melaporkannya kepada Sekjen dan Irjen.","Staf","Log","Rekap bulanan","Bulanan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penyampaian paling lambat 2 hari kerja setelah disetujui; hasil diteruskan kepada pemohon paling lama 3 hari kerja setelah tanggapan diterima. Hasil akhir: Log Komunikasi Internal dan bukti pengiriman."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Tidak ada tanggapan setelah 5 hari kerja: pengingat sopan, lalu Wakil Presiden menindaklanjuti melalui KAUR ORMAWA.","Perbedaan pendapat dengan kampus tidak diperdebatkan di ruang publik; dibahas melalui audiensi (SOP-HKE-003) dan Rapat Pimpinan (SOP-GOV-005).","Pesan yang berpotensi mencemarkan nama baik ditahan dan diperiksa Wakil Presiden sebelum dikirim.","Kebutuhan mendesak menyangkut keselamatan: langsung menghubungi pihak berwenang dan melapor setelahnya (SOP-RSK-003)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% komunikasi resmi tercatat pada Log Komunikasi Internal.","Minimal 90% pesan disampaikan dalam 2 hari kerja setelah disetujui.","Tidak ada keluhan etika komunikasi dari pihak kampus."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Log Komunikasi Internal.","Surat atau pesan terkirim beserta bukti.","Catatan tanggapan dan tindak lanjut. Seluruh dokumen disimpan pada repositori resmi BEM (folder Harmonisasi Kampus) oleh Menteri Harmonisasi Kampus bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri memeriksa Log setiap bulan; Sekjen memeriksa arsip surat; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kebutuhan komunikasi → Pihak dan jalur → Susun pesan → Persetujuan → Penyampaian → Catat tanggapan → Teruskan ke pemohon → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Komunikasi","Unit pemohon; pihak dituju; tujuan; materi; tanggal dibutuhkan; lampiran."],["Log Komunikasi Internal","Tanggal; pihak; kanal; ringkasan; tanggapan; tindak lanjut; penanggung jawab."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pihak dan jalur resmi sudah tepat.","☐ Ya ☐ Tidak"],["2","Bahasa santun dan sesuai adab.","☐ Ya ☐ Tidak"],["3","Persetujuan diperoleh sebelum pengiriman.","☐ Ya ☐ Tidak"],["4","Tanggapan dicatat dan diteruskan kepada pemohon.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-HMK-003","g":"SOP Khusus Unit: Harmonisasi Kampus","t":"Kolaborasi Antar UKM/ORMAWA","o":"Menteri Harmonisasi Kampus","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Harmonisasi Kampus","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[795,798],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur memfasilitasi kolaborasi kegiatan antar HIMA, UKM, dan ormawa lain, mulai dari penjajakan, kesepakatan peran, pemantauan, hingga evaluasi, agar kegiatan saling mendukung dan tidak tumpang tindih."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Kolaborasi kegiatan antar ormawa di lingkungan STDIIS yang difasilitasi BEM. SOP ini tidak mengatur kegiatan internal satu ormawa, kerja sama dengan pihak luar kampus (lihat SOP-HKE-005), maupun pendanaan (lihat SOP-KEU)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Bab III (Tugas BEM) huruf c, d, dan f (pengembangan diri, koordinasi antar-ormawa, dan seluruh kegiatan kemahasiswaan).","ART Pasal 4 huruf c dan g (usulan panitia atau tim kerja dan rekomendasi kepada HIMA dan UKM).","ART Pasal 2 huruf d (kegiatan ilmiah, dakwah, sosial, dan minat bakat).","AD Pasal 5 ayat (2) (mempererat ukhuwah Islamiah dan kebersamaan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kolaborasi","Kegiatan bersama dua ormawa atau lebih dengan pembagian peran tertulis."],["Piagam Kolaborasi","Catatan tertulis tujuan, peran, hasil kerja, pendanaan, tenggat, dan penanggung jawab setiap ormawa."],["Rekomendasi BEM","Surat dukungan BEM kepada HIMA atau UKM untuk pelaksanaan kegiatan (ART Pasal 4 huruf g)."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap kolaborasi memiliki satu ormawa utama dan pembagian peran serta beban dana tertulis dalam Piagam Kolaborasi.","BEM memfasilitasi dan memberi rekomendasi, tidak mengambil alih kegiatan ormawa.","Kolaborasi sesuai syariat dan peraturan kampus; kegiatan yang memerlukan izin kampus mengikuti SOP-PRO-009.","Jadwal diperiksa terhadap kalender organisasi untuk mencegah kegiatan bentrok."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Harmonisasi Kampus","A","Bertanggung jawab atas fasilitasi, telaah, dan penutupan kolaborasi."],["Staf Kementerian Harmonisasi","R","Menelaah usulan, memfasilitasi pertemuan, dan memantau progres."],["Ormawa inisiator","R","Mengajukan gagasan dan bertindak sebagai ormawa utama."],["Ormawa mitra","R","Menyatakan kesediaan dan melaksanakan peran yang disepakati."],["Sekretaris Jenderal","C","Memeriksa kalender organisasi dan menerbitkan surat rekomendasi."],["KAUR ORMAWA","I","Menerima informasi bila kegiatan memerlukan izin kampus."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Usulan Kolaborasi.","Kalender organisasi.","Basis Data Ormawa (SOP-HMK-001)."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan gagasan: Ormawa inisiator mengisi Formulir Usulan Kolaborasi.","Ormawa inisiator","Gagasan kegiatan","Usulan tercatat","Sesuai kebutuhan"],["2","Telaah: Memeriksa tujuan, kesesuaian syariat dan aturan, serta potensi bentrok jadwal.","Staf; disetujui Menteri","Usulan, kalender","Layak atau perlu revisi","3 hari kerja"],["3","Penjajakan mitra: Memfasilitasi pertemuan dan memperoleh konfirmasi tertulis kesediaan mitra.","Staf","Usulan layak","Konfirmasi mitra","5 hari kerja"],["4","Piagam Kolaborasi: Menyusun dan menandatangani Piagam Kolaborasi oleh ormawa terkait.","Ormawa inisiator dan mitra","Konfirmasi mitra","Piagam bertanda tangan","3 hari kerja"],["5","Rekomendasi BEM: Menerbitkan surat rekomendasi sesuai ART Pasal 4 huruf g melalui Sekjen.","Menteri; Sekjen","Piagam","Surat rekomendasi","3 hari kerja"],["6","Pemantauan: Memantau progres sesuai tahapan kegiatan dan mencatat kendala.","Staf","Piagam, laporan ormawa","Catatan progres","Sesuai tahapan kegiatan"],["7","Penyelesaian perbedaan: Memediasi perbedaan peran, jadwal, atau dana; bila tidak selesai dibawa ke Wakil Presiden.","Menteri","Catatan kendala","Kesepakatan baru","5 hari kerja"],["8","Penutupan dan evaluasi: Mencatat hasil dan pembelajaran kolaborasi.","Staf","Laporan kegiatan","Catatan evaluasi","5 hari kerja setelah kegiatan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari pengajuan hingga Piagam Kolaborasi ditandatangani paling lama 10 hari kerja. Hasil akhir: Piagam Kolaborasi, surat rekomendasi, dan catatan evaluasi."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Jadwal bentrok: Menteri mengusulkan jadwal alternatif; bila tidak sepakat diputuskan Wakil Presiden.","Perselisihan peran atau dana: dimediasi Menteri; bila menyangkut pengurus BEM mengikuti SOP- GOV-010; bila antar-ormawa tidak selesai diteruskan kepada KAUR ORMAWA.","Kolaborasi yang bertentangan dengan AD/ART, syariat, atau aturan kampus ditolak dengan alasan tertulis.","Kegiatan berisiko tinggi: penilaian risiko mengikuti SOP-RSK-002."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% kolaborasi memiliki Piagam sebelum pelaksanaan.","Tidak ada kegiatan bentrok pada kalender organisasi.","Minimal 80% kolaborasi dievaluasi dalam 5 hari kerja setelah selesai."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Usulan Kolaborasi.","Piagam Kolaborasi.","Surat rekomendasi BEM.","Catatan evaluasi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Harmonisasi Kampus) oleh Menteri Harmonisasi Kampus bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri memeriksa Piagam dan catatan evaluasi setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengajuan gagasan → Telaah → Penjajakan mitra → Piagam Kolaborasi → Rekomendasi BEM → Pemantauan → Evaluasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Usulan Kolaborasi","Ormawa inisiator; ormawa mitra; tujuan; bentuk kegiatan; waktu; kebutuhan; tanggal."],["Piagam Kolaborasi","Ormawa utama; peran tiap ormawa; hasil kerja; pendanaan; tenggat; penanggung jawab; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Tujuan sesuai syariat dan aturan kampus.","☐ Ya ☐ Tidak"],["2","Jadwal tidak bentrok pada kalender organisasi.","☐ Ya ☐ Tidak"],["3","Piagam Kolaborasi ditandatangani sebelum pelaksanaan.","☐ Ya ☐ Tidak"],["4","Evaluasi dicatat setelah kegiatan selesai.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-LNG-001","g":"SOP Khusus Unit: Hubungan Eksternal","t":"Diplomasi Mahasiswa","o":"Menteri Hubungan Eksternal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Hubungan Eksternal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[799,802],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur perencanaan, pelaksanaan, dan pelaporan diplomasi mahasiswa, yaitu komunikasi dan representasi BEM kepada pihak di luar kampus untuk membangun hubungan dan menyuarakan kepentingan mahasiswa STDIIS dengan santun dan sesuai syariat."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Pendekatan dan pertemuan diplomatik BEM dengan BEM kampus lain, organisasi mahasiswa, dan lembaga di luar kampus. SOP ini tidak mengatur pengiriman delegasi (SOP-LNG-002), hubungan antar-BEM daerah (SOP-LNG-003), maupun pengelolaan mitra dan perjanjian kerja sama (SOP-LNG-004 dan SOP-HKE-005)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf e dan j (kerja sama halal dengan persetujuan Ketua STDIIS; kegiatan regional, nasional, atau internasional dengan seizin kampus).","ART Pasal 4 huruf e (mewakili mahasiswa dalam forum resmi internal dan eksternal).","ART Pasal 3 huruf b dan d (ukhuwah Islamiyah dan nama baik STDIIS).","ART Pasal 11 huruf a dan e (larangan provokasi SARA dan politik praktis tanpa izin kampus)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Diplomasi mahasiswa","Komunikasi resmi BEM kepada pihak luar kampus untuk membangun hubungan, bertukar gagasan, dan menyampaikan kepentingan mahasiswa."],["Rencana Diplomasi","Dokumen tujuan, sasaran pihak, pesan kunci, jadwal, dan penanggung jawab."],["Pesan kunci","Pokok sikap dan informasi yang boleh disampaikan atas nama BEM."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Representasi atas nama BEM hanya oleh pihak yang diberi mandat (SOP-HKE-011).","Pesan kunci disetujui sebelum pertemuan dan tidak diubah di lapangan tanpa persetujuan.","BEM tidak mengikat diri pada kerja sama atau keputusan forum tanpa persetujuan Ketua STDIIS.","Diplomasi tidak memuat politik praktis, afiliasi partai tanpa izin kampus, atau isu SARA (ART Pasal 11).","Setiap pertemuan wajib dilaporkan (SOP-HKE-012)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Hubungan Eksternal","A","Bertanggung jawab atas rencana, pelaksanaan, dan laporan diplomasi."],["Staf Kementerian Hubungan Eksternal","R","Memetakan pihak, menyiapkan bahan, dan menyusun laporan."],["Presiden","C","Menyetujui pesan kunci strategis dan mewakili BEM pada diplomasi tingkat pimpinan."],["Wakil Presiden","C","Menelaah keselarasan dengan koordinasi Eksekutif."],["Sekretaris Jenderal","R","Menyiapkan surat izin, mandat, dan arsip."],["Ketua STDIIS / KAUR ORMAWA","I","Memberi izin atau menerima pemberitahuan sesuai ketentuan."],["Inspektur Jenderal","I","Menerima laporan untuk bahan pengawasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Rencana kerja Kementerian Hubungan Eksternal.","Profil pihak sasaran.","Formulir Rencana Diplomasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan sasaran: Menetapkan tujuan dan pihak sasaran diplomasi dalam Rencana Diplomasi.","Menteri","Program kerja","Rencana Diplomasi","3 hari kerja"],["2","Pemetaan pihak: Menyusun profil pihak dan memeriksa kesesuaian dengan syariat dan aturan kampus.","Staf","Rencana Diplomasi","Profil pihak","3 hari kerja"],["3","Persetujuan rencana: Mengajukan rencana dan pesan kunci untuk disetujui.","Presiden; Wapres","Rencana, pesan kunci","Persetujuan","3 hari kerja"],["4","Izin kampus: Mengajukan izin atau pemberitahuan kepada kampus bila diperlukan.","Sekjen","Rencana disetujui","Surat izin","Minimal 5 hari kerja sebelum pertemuan"],["5","Pelaksanaan pertemuan: Menyampaikan pesan kunci dan mencatat hasil pertemuan.","Menteri atau pihak bermandat","Pesan kunci, mandat","Catatan pertemuan","Sesuai jadwal"],["6","Pelaporan: Menyusun laporan hasil pertemuan sesuai SOP-HKE-012.","Staf","Catatan pertemuan","Laporan hasil","3 hari kerja"],["7","Tindak lanjut: Mencatat tindak lanjut; hal yang memerlukan keputusan dibawa ke Rapat Pimpinan.","Menteri","Laporan","Daftar tindak lanjut","3 hari kerja"],["8","Evaluasi: Mengevaluasi manfaat diplomasi dan menyempurnakan rencana.","Menteri","Laporan, tindak lanjut","Catatan evaluasi","Triwulanan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Rencana disetujui paling lambat 7 hari kerja sebelum pertemuan; laporan diserahkan paling lama 3 hari kerja setelah pertemuan. Hasil akhir: Rencana Diplomasi, laporan hasil pertemuan, dan daftar tindak lanjut."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pertemuan mendesak kurang dari 5 hari kerja: Presiden memutuskan melalui SOP-GOV-012 dan izin lisan dikonfirmasi tertulis.","Pihak sasaran terindikasi bertentangan dengan syariat atau terlibat politik praktis: pertemuan ditolak (ART Pasal 11).","Pernyataan di luar pesan kunci yang berpotensi merugikan nama baik: dilaporkan kepada Presiden dan ditangani melalui SOP-KOM-012.","Pelanggaran etika oleh pihak bermandat: SOP-SDM-013.."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pertemuan diplomasi memiliki Rencana Diplomasi yang disetujui.","Laporan hasil pertemuan diserahkan dalam 3 hari kerja pada minimal 90% kasus.","Tidak ada keputusan atau pernyataan yang mengikat BEM tanpa persetujuan berwenang."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Rencana Diplomasi dan pesan kunci.","Surat izin dan mandat.","Laporan hasil pertemuan.","Daftar tindak lanjut. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Menteri Hubungan Eksternal bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri memeriksa kelengkapan laporan setiap bulan; Sekjen memeriksa arsip; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Penetapan sasaran → Pemetaan pihak → Persetujuan rencana → Izin kampus → Pertemuan → Laporan → Tindak lanjut → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Rencana Diplomasi","Tujuan; pihak sasaran; pesan kunci; jadwal; pihak bermandat; kebutuhan izin; tanggal."],["Laporan Hasil Pertemuan","Tanggal; pihak; peserta; pokok pembicaraan; kesepakatan; tindak lanjut; lampiran."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pesan kunci telah disetujui.","☐ Ya ☐ Tidak"],["2","Izin atau pemberitahuan kepada kampus telah dikirim.","☐ Ya ☐ Tidak"],["3","Pihak yang hadir memiliki mandat.","☐ Ya ☐ Tidak"],["4","Laporan hasil pertemuan telah diserahkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-LNG-002","g":"SOP Khusus Unit: Hubungan Eksternal","t":"Pengiriman Delegasi","o":"Menteri Hubungan Eksternal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Hubungan Eksternal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[803,806],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penerimaan undangan, penunjukan, pembekalan, pelaksanaan, dan pelaporan delegasi BEM pada acara pihak eksternal agar delegasi bermandat, aman, dan menjaga nama baik organisasi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Delegasi BEM ke seminar, musyawarah, forum antar-BEM, atau acara lain yang diselenggarakan pihak di luar BEM. SOP ini tidak mengatur isi surat mandat (SOP-HKE-011) dan pembiayaan rinci (SOP-KEU)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf j (mengikuti kegiatan di tingkat regional, nasional, atau internasional dengan seizin kampus).","ART Pasal 4 huruf e dan f (mewakili mahasiswa dan menandatangani surat resmi).","ART Pasal 3 huruf d (menjaga nama baik STDIIS).","ART Pasal 6 ayat (1) (syarat umum pengurus, termasuk tidak sedang menjalani sanksi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Delegasi","Pengurus yang ditugaskan secara resmi mewakili BEM pada acara pihak eksternal."],["Surat Mandat","Surat penugasan resmi delegasi (SOP-HKE-011)."],["Pembekalan","Pengarahan singkat tentang tujuan, pesan kunci, adab, dan tata cara pelaporan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Delegasi adalah pengurus aktif yang memenuhi ART Pasal 6 dan tidak sedang menjalani sanksi.","Setiap delegasi memiliki Surat Mandat dan izin kampus sebelum berangkat.","Delegasi menjaga adab, penampilan, dan nama baik, serta tidak menyatakan sikap resmi di luar pesan kunci.","Pembiayaan hanya dari anggaran yang telah disetujui (SOP-KEU-006).","Informasi keberangkatan dan kepulangan disampaikan kepada Menteri untuk keselamatan delegasi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Hubungan Eksternal","A","Bertanggung jawab atas telaah, penunjukan, pembekalan, dan laporan delegasi."],["Staf Kementerian Hubungan Eksternal","R","Mencatat undangan, menyiapkan bahan, dan memantau kehadiran."],["Delegasi","R","Menjalankan mandat dan menyusun laporan."],["Presiden","C","Menyetujui pengiriman delegasi dan menandatangani mandat atas nama BEM."],["Sekretaris Jenderal","R","Menyiapkan surat izin dan mandat."],["Kepala Biro Keuangan","C","Memeriksa ketersediaan anggaran."],["Ketua STDIIS / KAUR ORMAWA","I","Memberi izin sesuai ketentuan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Undangan resmi pihak eksternal.","Anggaran yang disetujui.","Daftar pengurus yang memenuhi syarat."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan undangan: Mencatat undangan sesuai SOP-HKE- 001.","Staf","Undangan","Undangan tercatat","1 hari kerja"],["2","Telaah kelayakan: Menilai relevansi, kesesuaian syariat, jadwal, biaya, dan risiko.","Menteri","Undangan","Rekomendasi hadir atau tidak","2 hari kerja"],["3","Persetujuan: Mengajukan rekomendasi untuk disetujui.","Presiden atau Wapres","Rekomendasi","Keputusan","2 hari kerja"],["4","Penunjukan delegasi: Memilih delegasi berdasarkan kompetensi dan ketersediaan serta memeriksa syarat.","Menteri","Daftar pengurus","Daftar delegasi","2 hari kerja"],["5","Izin dan mandat: Menerbitkan surat izin kampus dan Surat Mandat.","Sekjen","Keputusan, daftar delegasi","Surat izin dan mandat","Minimal 5 hari kerja sebelum acara"],["6","Pembekalan: Menjelaskan tujuan, pesan kunci, adab, dan alur pelaporan.","Menteri","Mandat, pesan kunci","Delegasi siap","1 hari sebelum acara"],["7","Pelaksanaan dan dokumentasi: Mengikuti acara, mencatat hasil, dan mendokumentasikan kegiatan.","Delegasi","Mandat","Catatan dan dokumentasi","Sesuai acara"],["8","Pelaporan: Menyusun laporan delegasi dan mempertanggungjawabkan biaya sesuai SOP-KEU-007.","Delegasi","Catatan acara, bukti biaya","Laporan delegasi","3 hari kerja setelah kembali"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari telaah hingga persetujuan paling lama 4 hari kerja; surat izin dan mandat terbit minimal 5 hari kerja sebelum acara. Hasil akhir: Surat Mandat, izin kampus, dan laporan delegasi."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Undangan mendesak kurang dari 5 hari kerja: Presiden memutuskan melalui SOP-GOV-012 dan izin lisan dikonfirmasi tertulis.","Delegasi berhalangan: Menteri menunjuk pengganti dengan mandat baru.","Insiden atau keadaan darurat saat bertugas: SOP-RSK-003.","Dugaan pelanggaran etika oleh delegasi: SOP-SDM-013.","Undangan bermuatan politik praktis atau bertentangan dengan syariat ditolak (ART Pasal 11)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% delegasi memiliki Surat Mandat dan izin kampus.","Laporan delegasi diserahkan dalam 3 hari kerja pada minimal 90% kasus.","Tidak ada insiden etika yang tidak ditangani."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar delegasi dan Surat Mandat.","Surat izin kampus.","Laporan delegasi.","Bukti pertanggungjawaban biaya. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Menteri Hubungan Eksternal bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri memeriksa kelengkapan mandat dan laporan setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Undangan → Telaah → Persetujuan → Penunjukan delegasi → Izin dan mandat → Pembekalan → Pelaksanaan → Laporan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Telaah Undangan","Pengundang; acara; tanggal; relevansi; biaya; risiko; rekomendasi."],["Laporan Delegasi","Acara; delegasi; hasil; kesepakatan; dokumentasi; tindak lanjut; biaya."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Delegasi memenuhi syarat ART Pasal 6.","☐ Ya ☐ Tidak"],["2","Surat Mandat dan izin kampus telah terbit.","☐ Ya ☐ Tidak"],["3","Anggaran telah disetujui.","☐ Ya ☐ Tidak"],["4","Laporan dan pertanggungjawaban biaya telah diserahkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-LNG-003","g":"SOP Khusus Unit: Hubungan Eksternal","t":"Hubungan Antar-BEM Daerah","o":"Menteri Hubungan Eksternal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Hubungan Eksternal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[807,809],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur membangun dan memelihara hubungan dengan BEM perguruan tinggi lain di daerah secara terencana, bermanfaat, dan tidak mengikat BEM pada kewajiban yang belum disetujui."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Jejaring dan forum antar-BEM tingkat daerah dan regional. SOP ini tidak mengatur keanggotaan forum yang mengikat atau perjanjian kerja sama formal (lihat SOP-HKE-005 dan SOP-LNG-004)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf e dan j (kerja sama halal tidak mengikat dengan persetujuan Ketua STDIIS; kegiatan lintas daerah dengan seizin kampus).","ART Bab III (Tugas BEM) huruf d (koordinasi dan kerja sama dengan pihak eksternal perguruan tinggi).","ART Pasal 3 huruf b (menjaga ukhuwah Islamiyah).","AD Pasal 3 ayat (3) (sifat independen) dan ART Pasal 11 huruf e (politik praktis)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Jejaring BEM","Daftar BEM atau organisasi mahasiswa lain yang menjalin hubungan dengan BEM."],["Forum antar-BEM","Wadah pertemuan beberapa BEM untuk bertukar informasi atau berkegiatan bersama."],["Kartu Kontak Mitra","Catatan nama BEM, kontak resmi, dan riwayat hubungan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Hubungan dibangun atas dasar ukhuwah, saling menghormati, dan kemandirian BEM.","Keanggotaan forum atau aliansi yang mengikat memerlukan persetujuan Ketua STDIIS.","Informasi internal BEM tidak dibagikan tanpa persetujuan Presiden.","Kegiatan bersama mengikuti SOP-PRO dan delegasi mengikuti SOP-LNG-002.","Data kontak mitra dikelola sesuai SOP-HKE-013."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Hubungan Eksternal","A","Bertanggung jawab atas pemetaan dan pemeliharaan jejaring BEM."],["Staf Kementerian Hubungan Eksternal","R","Memetakan jejaring, menjalin komunikasi, dan mencatat hubungan."],["Presiden","C","Menyetujui pengikatan diri pada forum atau kegiatan bersama."],["Sekretaris Jenderal","C","Menerbitkan surat dan mengarsipkan data."],["Ketua STDIIS","C","Menyetujui keanggotaan forum yang mengikat."],["Wakil Presiden","I","Menerima laporan untuk koordinasi Eksekutif."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar BEM dan forum antar-BEM.","Rencana kerja Kementerian Hubungan Eksternal.","Kartu Kontak Mitra."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pemetaan jejaring: Menyusun daftar BEM dan forum yang relevan beserta kontak resminya.","Staf","Referensi forum","Peta jejaring","5 hari kerja; diperbarui per semester"],["2","Penjajakan awal: Memperkenalkan BEM melalui surat atau komunikasi resmi.","Menteri","Peta jejaring","Kontak awal tercatat","5 hari kerja"],["3","Telaah manfaat dan risiko: Menilai manfaat, risiko, dan kesesuaian syariat sebelum hubungan ditingkatkan.","Menteri; Presiden","Hasil penjajakan","Keputusan lanjut atau tidak","3 hari kerja"],["4","Pemeliharaan hubungan: Menjaga komunikasi berkala dan saling mengundang kegiatan.","Staf","Kartu Kontak Mitra","Catatan hubungan","Bulanan"],["5","Kegiatan bersama atau kunjungan: Mengusulkan kegiatan melalui SOP- PRO atau mengirim delegasi melalui SOP-LNG-002.","Menteri","Usulan kegiatan","Usulan atau delegasi","Sesuai kebutuhan"],["6","Keanggotaan forum: Mengajukan keanggotaan forum yang mengikat kepada Ketua STDIIS sebelum menyatakan bergabung.","Presiden; Sekjen","Draf keanggotaan","Persetujuan Ketua STDIIS","Sesuai jadwal kampus"],["7","Laporan dan evaluasi: Menyusun laporan semesteran dan mengevaluasi manfaat jejaring.","Menteri","Catatan hubungan","Laporan semester","Per semester"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penjajakan hingga keputusan lanjut paling lama 8 hari kerja. Hasil akhir: peta jejaring, catatan hubungan, dan laporan semesteran."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Forum meminta komitmen mengikat: ditahan sampai ada persetujuan Presiden dan Ketua STDIIS.","Mitra bermuatan politik praktis atau bertentangan dengan syariat: hubungan tidak dilanjutkan (ART Pasal 11).","Perselisihan dengan BEM lain: dibawa ke Presiden dan dikomunikasikan dengan adab melalui jalur resmi.","Kebocoran data kontak: SOP-RSK-009."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Peta jejaring diperbarui setiap semester.","Setiap hubungan aktif memiliki Kartu Kontak Mitra.","Tidak ada komitmen mengikat tanpa persetujuan berwenang."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Peta jejaring BEM.","Kartu Kontak Mitra.","Catatan hubungan dan laporan semesteran. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Menteri Hubungan Eksternal bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri memeriksa kemutakhiran peta jejaring setiap semester; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pemetaan jejaring → Penjajakan awal → Telaah manfaat dan risiko → Pemeliharaan hubungan → Kegiatan bersama → Laporan dan evaluasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Kartu Kontak Mitra","Nama BEM; perguruan tinggi; kontak resmi; riwayat hubungan; penanggung jawab; tanggal pembaruan."],["Laporan Semester Hubungan Antar-BEM","Daftar hubungan; kegiatan; manfaat; kendala; rencana tindak lanjut."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Hubungan melalui kanal resmi.","☐ Ya ☐ Tidak"],["2","Tidak ada komitmen mengikat tanpa persetujuan.","☐ Ya ☐ Tidak"],["3","Kartu Kontak Mitra terbarui.","☐ Ya ☐ Tidak"],["4","Laporan semester diserahkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-LNG-004","g":"SOP Khusus Unit: Hubungan Eksternal","t":"Pengelolaan Mitra","o":"Menteri Hubungan Eksternal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri Hubungan Eksternal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[810,813],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur identifikasi, penilaian, pencatatan, pemeliharaan, dan evaluasi mitra BEM sehingga kemitraan halal, terdokumentasi, dan tidak membebani kepengurusan berikutnya."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Mitra BEM dari luar kampus seperti lembaga dakwah, komunitas, instansi, dan perusahaan. SOP ini tidak mengatur penyusunan perjanjian (SOP-HKE-005 dan SOP-HKE-006) maupun sponsor dan dana (SOP-HKE- 007, SOP-HKE-008, dan SOP-KEU-012)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf e (kerja sama halal dan tidak mengikat dengan persetujuan Ketua STDIIS).","AD Pasal 15 ayat (1) huruf b dan ayat (2) (dana tidak menimbulkan kewajiban melampaui satu periode dan terhindar dari riba, gharar, dan maysir).","AD Pasal 18 dan ART Pasal 2 huruf b (penggunaan lambang dan identitas resmi).","ART Pasal 11 huruf d dan g (larangan paham yang bertentangan dan pencemaran nama baik)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Mitra","Pihak di luar BEM yang bekerja sama dengan BEM secara tertulis atau tidak tertulis."],["Kartu Penilaian Mitra","Lembar penilaian kehalalan, reputasi, kesesuaian visi, manfaat, dan risiko mitra."],["Basis Data Mitra","Catatan terpadu mitra, penanggung jawab hubungan, dan masa berlaku kerja sama (SOP- HKE-013)."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Mitra dipilih berdasarkan kehalalan usaha atau kegiatan dan kesesuaian dengan nilai Islam, tanpa unsur riba, gharar, dan maysir.","Kerja sama tidak mengikat organisasi melampaui satu periode kepengurusan tanpa persetujuan berwenang.","Setiap mitra memiliki satu penanggung jawab hubungan.","Pencantuman logo mitra pada publikasi mengikuti SOP-KOM-014."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri Hubungan Eksternal","A","Bertanggung jawab atas penilaian, pencatatan, dan evaluasi mitra."],["Staf Kementerian Hubungan Eksternal","R","Mengidentifikasi, mendata, dan memelihara hubungan dengan mitra."],["Penanggung jawab mitra","R","Menjaga komunikasi dan pemenuhan kewajiban timbal balik."],["Presiden","C","Menyetujui kemitraan strategis."],["Ketua STDIIS","C","Menyetujui kerja sama dengan pihak eksternal."],["Sekretaris Jenderal","C","Mengarsipkan dokumen kerja sama."],["Kepala Biro Keuangan","C","Memberi masukan bila kemitraan menyangkut dana."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Profil mitra.","Kartu Penilaian Mitra.","Dokumen kerja sama, bila ada."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Identifikasi mitra: Mencari dan mengusulkan mitra yang relevan dengan program kerja.","Staf","Program kerja","Daftar calon mitra","Sesuai kebutuhan"],["2","Penilaian: Mengisi Kartu Penilaian Mitra: kehalalan, reputasi, kesesuaian visi, manfaat, dan risiko.","Staf; diperiksa Menteri","Profil mitra","Kartu Penilaian","5 hari kerja"],["3","Persetujuan: Mengajukan hasil penilaian; kerja sama formal diajukan kepada Ketua STDIIS.","Presiden; Ketua STDIIS","Kartu Penilaian","Persetujuan atau penolakan","5 hari kerja"],["4","Penetapan penanggung jawab dan pencatatan: Menunjuk penanggung jawab dan memasukkan mitra ke Basis Data Mitra.","Menteri","Persetujuan","Basis Data Mitra terbarui","2 hari kerja"],["5","Pemeliharaan hubungan: Menjaga komunikasi dan memenuhi kewajiban timbal balik.","Penanggung jawab mitra","Basis Data Mitra","Catatan hubungan","Berkala"],["6","Pemantauan masa berlaku: Mengingatkan masa berlaku kerja sama dan kewajiban yang jatuh tempo.","Staf","Basis Data Mitra","Pengingat","30 hari sebelum berakhir"],["7","Evaluasi mitra: Menilai manfaat dan menetapkan lanjut, perbarui, atau hentikan.","Menteri","Catatan hubungan","Keputusan evaluasi","Akhir semester"],["8","Penghentian dan serah terima: Mencatat mitra yang dihentikan dan menyerahkan data mitra aktif kepada kabinet berikutnya (SOP-TRN-007).","Menteri","Basis Data Mitra","Daftar serah terima","Akhir periode"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari penilaian hingga keputusan persetujuan paling lama 10 hari kerja. Hasil akhir: Kartu Penilaian Mitra, Basis Data Mitra, dan keputusan evaluasi."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Mitra tidak lagi memenuhi syarat kehalalan atau nilai Islam: hubungan dihentikan dan dilaporkan kepada Presiden.","Mitra meminta kewajiban yang melampaui satu periode: ditolak atau diajukan untuk persetujuan berwenang.","Sengketa dengan mitra: dibahas Rapat Pimpinan (SOP-GOV-005) dan, bila perlu, KAUR ORMAWA.","Dugaan penyalahgunaan dana atau aset dalam kemitraan: SOP-RSK-007."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% mitra aktif memiliki Kartu Penilaian dan penanggung jawab.","Tidak ada kerja sama berjalan tanpa persetujuan yang berwenang.","Masa berlaku seluruh kerja sama terpantau."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Kartu Penilaian Mitra.","Basis Data Mitra.","Catatan evaluasi mitra.","Daftar serah terima mitra. Seluruh dokumen disimpan pada repositori resmi BEM (folder Hubungan Eksternal) oleh Menteri Hubungan Eksternal bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri memeriksa Basis Data Mitra setiap bulan; Sekjen memeriksa arsip; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Identifikasi mitra → Penilaian → Persetujuan → Pencatatan → Pemeliharaan → Pemantauan masa berlaku → Evaluasi → Serah terima → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Kartu Penilaian Mitra","Nama mitra; bidang; kehalalan; reputasi; kesesuaian visi; manfaat; risiko; rekomendasi; penilai."],["Basis Data Mitra","Nama; kontak; penanggung jawab; jenis kerja sama; masa berlaku; status; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kehalalan dan kesesuaian nilai Islam telah dinilai.","☐ Ya ☐ Tidak"],["2","Persetujuan berwenang diperoleh.","☐ Ya ☐ Tidak"],["3","Mitra tercatat pada Basis Data Mitra.","☐ Ya ☐ Tidak"],["4","Masa berlaku kerja sama terpantau.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PSD-001","g":"SOP Khusus Unit: PSDM","t":"Pelatihan","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[814,817],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur analisis kebutuhan, perencanaan, pelaksanaan, dan evaluasi pelatihan bagi pengurus agar kompetensi meningkat sesuai tugas dan kebutuhan unit."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Pelatihan internal bagi pengurus BEM Kabinet Samasta yang diselenggarakan Kementerian PSDM. SOP ini tidak mengatur kaderisasi (SOP-PSD-002), pemetaan kompetensi (SOP-PSD-003), maupun program umum untuk mahasiswa (SOP-PRO)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 5 ayat (1) dan (4) (pengembangan diri dan pembelajaran tanggung jawab, disiplin, dan amanah).","ART Bab III (Tugas BEM) huruf c (pengembangan diri, dakwah, sosial, keilmuan, dan minat bakat).","ART Pasal 9 (Rapat Kerja: program kerja dan anggaran disahkan sebelum pelaksanaan).","SOP-SDM-016 (pengembangan kapasitas dan pelatihan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Analisis Kebutuhan Pelatihan (AKP)","Hasil pemetaan kesenjangan kompetensi dan kebutuhan unit sebagai dasar menyusun pelatihan."],["Modul pelatihan","Materi tertulis yang digunakan dalam pelatihan."],["Pra dan pascates","Pengukuran pemahaman peserta sebelum dan sesudah pelatihan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pelatihan didasarkan pada AKP dan hasil Pemetaan Kompetensi (SOP-PSD-003).","Materi dan narasumber sesuai nilai Islam, akhlak, dan peraturan kampus; narasumber disetujui sebelum diundang.","Kehadiran peserta dicatat dan menjadi bahan evaluasi pengurus (SOP-PSD-004).","Pelatihan tercantum dalam program kerja dan anggaran; pelaksanaannya mengikuti SOP-PRO (panitia, izin, dan laporan)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri PSDM","A","Bertanggung jawab atas mutu perencanaan, pelaksanaan, dan evaluasi pelatihan."],["Staf Kementerian PSDM","R","Menyusun AKP, modul, dan laporan serta mengelola presensi."],["Narasumber","R","Menyampaikan materi sesuai modul yang disetujui."],["Peserta pelatihan","R","Hadir, mengikuti pelatihan, dan menerapkan hasilnya."],["Wakil Presiden","C","Memastikan pelatihan selaras dengan kebutuhan Eksekutif."],["Sekretaris Jenderal","C","Memasukkan jadwal ke kalender dan menerbitkan surat."],["Kepala Biro Keuangan","C","Memeriksa anggaran pelatihan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Hasil Pemetaan Kompetensi.","Program kerja dan anggaran yang telah disahkan.","Kalender organisasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Analisis kebutuhan: Menyusun AKP dari hasil pemetaan, masukan unit, dan evaluasi sebelumnya.","Menteri; Staf","Pemetaan, masukan unit","AKP","5 hari kerja"],["2","Rencana pelatihan: Menyusun jadwal, materi, narasumber, dan anggaran.","Staf","AKP","Rencana Pelatihan","5 hari kerja"],["3","Persetujuan: Mengajukan rencana untuk disetujui Presiden.","Presiden","Rencana Pelatihan","Persetujuan","3 hari kerja"],["4","Persiapan: Mengundang narasumber, menyiapkan modul, tempat, dan surat sesuai SOP- PRO-009 dan SOP-PRO-011.","Staf; Sekjen","Rencana disetujui","Persiapan siap","Minimal 7 hari kerja sebelum pelatihan"],["5","Pelaksanaan: Menjalankan pelatihan, mencatat presensi, dan melakukan pra dan pascates.","Staf; narasumber","Modul, presensi","Presensi dan hasil tes","Sesuai jadwal"],["6","Evaluasi: Mengumpulkan umpan balik, skor tes, dan rencana penerapan peserta.","Staf","Hasil tes, umpan balik","Evaluasi pelatihan","3 hari kerja setelah pelatihan"],["7","Laporan: Menyusun laporan pelatihan dan mempertanggungjawabkan biaya.","Staf","Evaluasi, bukti biaya","Laporan pelatihan","5 hari kerja"],["8","Tindak lanjut: Memantau penerapan hasil pelatihan pada unit peserta.","Menteri","Rencana penerapan","Catatan tindak lanjut","1 bulan setelah pelatihan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari analisis kebutuhan hingga persetujuan paling lama 13 hari kerja; laporan diserahkan paling lama 5 hari kerja setelah pelatihan. Hasil akhir: Rencana Pelatihan, evaluasi, dan laporan pelatihan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Narasumber berhalangan: Menteri menunjuk pengganti yang disetujui Wakil Presiden.","Peserta tidak hadir tanpa uzur: dicatat dan dilaporkan kepada atasan langsung (SOP-SDM-006).","Anggaran tidak cukup: dibahas dengan Kepala Biro Keuangan; perubahan anggaran mengikuti SOP- KEU-014.","Kendala atau insiden saat pelatihan: SOP-PRO-016 dan SOP-PRO-017."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 80% pengurus yang diundang mengikuti pelatihan.","Rata-rata skor pascates lebih tinggi daripada prates.","Laporan pelatihan diserahkan dalam 5 hari kerja pada minimal 90% kasus."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["AKP dan Rencana Pelatihan.","Modul, presensi, dan hasil tes.","Evaluasi dan laporan pelatihan. Seluruh dokumen disimpan pada repositori resmi BEM (folder PSDM) oleh Menteri PSDM bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri memeriksa kelengkapan laporan dan tindak lanjut setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Analisis kebutuhan → Rencana pelatihan → Persetujuan → Persiapan → Pelaksanaan → Evaluasi → Laporan → Tindak lanjut → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Analisis Kebutuhan Pelatihan","Unit; kompetensi yang dibutuhkan; kesenjangan; prioritas; usulan materi."],["Formulir Evaluasi Pelatihan","Materi; narasumber; penyelenggaraan; skor prates dan pascates; saran; rencana penerapan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pelatihan didasarkan pada AKP.","☐ Ya ☐ Tidak"],["2","Narasumber dan modul disetujui.","☐ Ya ☐ Tidak"],["3","Presensi dan hasil tes tercatat.","☐ Ya ☐ Tidak"],["4","Laporan dan pertanggungjawaban biaya diserahkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PSD-002","g":"SOP Khusus Unit: PSDM","t":"Kaderisasi","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[818,821],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur kaderisasi, yaitu perekrutan calon kader, seleksi, pembinaan berjenjang, penilaian, dan penyiapan penerus agar regenerasi kepemimpinan BEM berjalan terbuka, adil, dan berkelanjutan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Kaderisasi mahasiswa aktif sebagai calon pengurus atau anggota BEM. SOP ini tidak mengatur pemilihan Presiden dan Wakil Presiden (AD Pasal 11 ayat 2 huruf a) dan diselaraskan dengan SOP-SDM-001 (rekrutmen dan seleksi pengurus)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 8 ayat (1) sampai (3) (keanggotaan terbuka; rekrutmen terbuka, seleksi adil, dan musyawarah).","AD Pasal 11 ayat (2) huruf b dan c (pengangkatan Menteri dan Kabiro secara prerogatif Presiden; seleksi terbuka dengan penilaian akumulatif kompetensi, integritas, dan wawancara).","AD Pasal 12 (anggota kehormatan, eksekutif, dan biasa).","ART Pasal 6 ayat (1) (syarat umum pengurus)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Kader","Mahasiswa aktif yang mengikuti pembinaan BEM untuk disiapkan menjadi pengurus."],["Jenjang kaderisasi","Tahapan pembinaan berurutan, dari pengenalan hingga penugasan."],["Penilaian akumulatif","Penilaian gabungan kompetensi, integritas, dan wawancara (AD Pasal 11 ayat 2 huruf c)."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pendaftaran terbuka bagi mahasiswa aktif STDIIS dan seleksi dilakukan secara adil.","Penilaian memakai sistem akumulatif: kompetensi, integritas, dan wawancara.","Syarat ART Pasal 6 ayat (1) diperiksa pada seleksi administrasi; perbedaan ketentuan IPK dan rangkap jabatan pada AD/ART dicatat dalam Catatan Penyusun.","Hasil seleksi ditetapkan melalui musyawarah; penempatan Menteri dan Kabiro tetap prerogatif Presiden.","Data pribadi peserta dilindungi dan hanya digunakan untuk kaderisasi (SOP-SDM-018)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri PSDM","A","Bertanggung jawab atas rencana, seleksi, dan pembinaan kaderisasi."],["Panitia seleksi","R","Menyelenggarakan seleksi administrasi, tes kompetensi, penilaian integritas, dan wawancara."],["Calon kader","R","Mengikuti seleksi dan pembinaan."],["Presiden","C","Menyetujui rencana dan menetapkan penempatan secara prerogatif."],["Wakil Presiden","C","Memberi masukan kebutuhan Eksekutif."],["Sekretaris Jenderal","R","Menerbitkan surat keputusan dan mengarsipkan."],["Inspektur Jenderal","C","Memeriksa kesesuaian proses dengan AD/ART."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Kebutuhan kader dari tiap unit.","Kriteria dan rubrik penilaian.","Kalender organisasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Perencanaan kaderisasi: Menyusun jenjang, kuota, kriteria, dan jadwal.","Menteri","Kebutuhan unit","Rencana Kaderisasi","Awal periode"],["2","Persetujuan: Mengajukan rencana kepada Presiden.","Presiden","Rencana Kaderisasi","Persetujuan","3 hari kerja"],["3","Pengumuman dan pendaftaran: Mengumumkan secara terbuka dan menerima pendaftaran.","Panitia","Rencana disetujui","Daftar pendaftar","7 hari kerja"],["4","Seleksi: Memeriksa syarat, menguji kompetensi, menilai integritas, dan mewawancarai.","Panitia","Pendaftar, rubrik","Skor akumulatif","7 hari kerja"],["5","Musyawarah penetapan: Menetapkan hasil melalui musyawarah bersama Presiden dan BPH.","Menteri; Presiden","Skor akumulatif","Daftar kader terpilih","3 hari kerja"],["6","Pengumuman dan orientasi: Mengumumkan hasil dan melaksanakan orientasi sesuai SOP- SDM-003.","Panitia; Sekjen","Daftar kader terpilih","Kader terorientasi","3 hari kerja"],["7","Pembinaan berjenjang: Menjalankan mentoring, penugasan, dan pelatihan sesuai jenjang.","Menteri; Staf","Rencana Kaderisasi","Catatan perkembangan","Per semester"],["8","Penilaian dan regenerasi: Menilai kesiapan dan menyusun daftar kader siap pimpinan untuk bahan transisi (SOP-TRN-010).","Menteri","Catatan perkembangan","Daftar kader siap","Akhir periode"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari pengumuman hingga penetapan kader paling lama 17 hari kerja. Hasil akhir: Rencana Kaderisasi, skor akumulatif, daftar kader terpilih, dan catatan perkembangan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Sanggahan peserta atas hasil seleksi: diterima tertulis dalam 3 hari kerja dan ditinjau Menteri bersama Irjen.","Dugaan kecurangan seleksi: SOP-RSK-004 dan SOP-SDM-013 (ART Pasal 11 huruf j).","Perbedaan syarat pada AD/ART: Presiden menetapkan acuan sementara dan masalah dibawa ke Mubes atau Musyawarah Istimewa.","Jumlah pendaftar kurang dari kuota: pendaftaran diperpanjang setelah persetujuan Wakil Presiden."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% peserta dinilai dengan rubrik akumulatif yang sama.","Hasil seleksi diumumkan paling lambat 3 hari kerja setelah musyawarah.","Tidak ada sanggahan terbukti tentang ketidakadilan seleksi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Rencana Kaderisasi.","Rubrik dan skor akumulatif.","Daftar kader terpilih dan catatan perkembangan. Seluruh dokumen disimpan pada repositori resmi BEM (folder PSDM) oleh Menteri PSDM bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri memeriksa kelengkapan penilaian; Irjen memeriksa kesesuaian proses dengan AD/ART pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Rencana → Persetujuan → Pendaftaran terbuka → Seleksi akumulatif → Musyawarah penetapan → Orientasi → Pembinaan → Regenerasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pendaftaran Kader","Identitas; program studi; IPK; pengalaman; komitmen; unit yang diminati."],["Rubrik Penilaian Akumulatif","Kompetensi; integritas; wawancara; bobot; skor; penilai; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pendaftaran diumumkan terbuka.","☐ Ya ☐ Tidak"],["2","Syarat ART Pasal 6 diperiksa.","☐ Ya ☐ Tidak"],["3","Seluruh peserta dinilai dengan rubrik yang sama.","☐ Ya ☐ Tidak"],["4","Hasil ditetapkan melalui musyawarah dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PSD-003","g":"SOP Khusus Unit: PSDM","t":"Pemetaan Kompetensi","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[822,825],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur memetakan keahlian, pengalaman, minat, dan kebutuhan pengembangan pengurus agar penempatan, pelatihan, dan evaluasi dilakukan tepat sasaran."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh pengurus BEM Kabinet Samasta. Hasil pemetaan menjadi bahan SOP-SDM-002 (penempatan), SOP- PSD-001 (pelatihan), dan SOP-PSD-004 (evaluasi). SOP ini tidak menetapkan pengangkatan atau pemberhentian pengurus."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 11 ayat (2) huruf b dan c (pengangkatan Menteri dan Kabiro dan seleksi dengan penilaian kompetensi).","ART Pasal 4 huruf b (mengangkat dan memberhentikan pengurus internal).","ART Pasal 6 ayat (1) (syarat umum pengurus).","SOP-SDM-002 dan SOP-SDM-018 (penempatan dan kerahasiaan data pribadi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Peta Kompetensi","Ringkasan keahlian, pengalaman, dan kesenjangan kompetensi setiap pengurus dan unit."],["Kesenjangan kompetensi","Selisih antara kompetensi yang dibutuhkan jabatan dan yang dimiliki pengurus."],["Skala penilaian","Skala 1 sampai 4 untuk menilai tingkat penguasaan (usulan)."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Data diberikan pengurus secara jujur dan dikumpulkan seperlunya.","Akses data terbatas pada Menteri PSDM, Presiden, Wakil Presiden, dan Sekretaris Jenderal.","Penilaian objektif berdasarkan rubrik; hasil dipakai untuk pembinaan, bukan hukuman.","Pemetaan diulang setiap semester dan saat ada pergantian pengurus.","Status rangkap jabatan pengurus dicatat sebagai informasi untuk Presiden."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri PSDM","A","Bertanggung jawab atas instrumen, hasil, dan kerahasiaan pemetaan."],["Staf Kementerian PSDM","R","Menyusun instrumen, mengolah data, dan menyusun peta."],["Pengurus","R","Mengisi profil kompetensi dengan jujur."],["Menteri atau Kabiro unit","C","Memverifikasi data pengurus di unitnya."],["Presiden","I","Menerima peta sebagai bahan penempatan."],["Sekretaris Jenderal","C","Menyimpan data sesuai ketentuan akses."],["Inspektur Jenderal","I","Menerima ringkasan untuk bahan pengawasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Uraian tugas tiap jabatan (SOP-SDM-004).","Formulir Profil Kompetensi.","Rubrik penilaian."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan instrumen: Menyusun formulir dan rubrik penilaian.","Staf","Uraian tugas","Instrumen","5 hari kerja"],["2","Pengisian: Pengurus mengisi Formulir Profil Kompetensi.","Pengurus","Formulir","Formulir terisi","5 hari kerja"],["3","Verifikasi atasan: Menteri atau Kabiro memverifikasi kebenaran data.","Menteri atau Kabiro","Formulir terisi","Data terverifikasi","3 hari kerja"],["4","Penilaian dan pemetaan: Menilai dengan rubrik dan menyusun Peta Kompetensi.","Staf","Data terverifikasi","Peta Kompetensi","5 hari kerja"],["5","Persetujuan dan penyampaian: Menteri PSDM menyetujui peta dan menyampaikannya kepada Presiden dan Wakil Presiden.","Menteri","Peta Kompetensi","Laporan Pemetaan","2 hari kerja"],["6","Umpan balik individu: Menyampaikan hasil kepada pengurus dan menerima tanggapan.","Staf","Peta Kompetensi","Umpan balik tercatat","5 hari kerja"],["7","Pemanfaatan: Menyerahkan hasil kepada penempatan, pelatihan, dan evaluasi.","Menteri","Laporan Pemetaan","Bahan SOP terkait","Sesuai kebutuhan"],["8","Pembaruan: Memperbarui peta setiap semester.","Staf","Peta lama","Peta terbarui","Per semester"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari penyusunan instrumen hingga laporan pemetaan paling lama 20 hari kerja. Hasil akhir: Peta Kompetensi dan Laporan Pemetaan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Data pengurus tidak lengkap atau tidak sesuai: dikembalikan untuk diperbaiki dalam 3 hari kerja.","Keberatan pengurus atas hasil: ditinjau ulang oleh Menteri PSDM dan atasan langsung.","Kebocoran data pemetaan: SOP-RSK-009.","Temuan rangkap jabatan yang tidak sesuai ketentuan: diteruskan kepada Presiden (lihat Catatan Penyusun)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pengurus aktif terpetakan setiap semester.","Hasil disampaikan kepada pengurus dalam 5 hari kerja.","Tidak ada kebocoran data pemetaan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Instrumen dan rubrik pemetaan.","Peta Kompetensi.","Laporan Pemetaan. Seluruh dokumen disimpan pada repositori resmi BEM (folder PSDM) oleh Menteri PSDM bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri memeriksa kemutakhiran peta setiap semester; Sekjen memeriksa hak akses; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Instrumen → Pengisian → Verifikasi atasan → Penilaian → Persetujuan → Umpan balik → Pemanfaatan → Pembaruan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Profil Kompetensi","Nama; unit; keahlian; pengalaman; minat; kebutuhan pengembangan; status rangkap jabatan; tanggal."],["Peta Kompetensi","Pengurus; jabatan; skor tiap kompetensi; kesenjangan; rekomendasi."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Data diisi dan diverifikasi atasan.","☐ Ya ☐ Tidak"],["2","Penilaian memakai rubrik yang sama.","☐ Ya ☐ Tidak"],["3","Akses data dibatasi sesuai ketentuan.","☐ Ya ☐ Tidak"],["4","Umpan balik telah disampaikan kepada pengurus.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-PSD-004","g":"SOP Khusus Unit: PSDM","t":"Evaluasi Pengurus","o":"Menteri PSDM","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Menteri PSDM","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[826,829],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur menilai kinerja, kedisiplinan, dan etika pengurus secara terukur, adil, dan transparan untuk pembinaan, apresiasi, dan tindak lanjut."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Evaluasi individu pengurus BEM oleh Kementerian PSDM sebagai bagian dari monitoring dan evaluasi. Pengawasan dan penilaian kinerja oleh Irjen tetap berlaku (ART Pasal 12 ayat 3 dan 6). Sanksi dijatuhkan oleh pihak berwenang melalui SOP-SDM-013 dan SOP-SDM-014, bukan oleh SOP ini."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 12 ayat (1) sampai (6) (pembinaan pimpinan BEM, jenis sanksi, dan pengawasan Irjen).","ART Pasal 13 ayat (7) sampai (9) (keadilan, objektivitas, bukti, dan hak klarifikasi).","AD Pasal 9 ayat (2) huruf e (tidak mengikuti kegiatan tiga kali berturut-turut tanpa uzur).","ART Pasal 11 huruf l (larangan meninggalkan tanggung jawab tanpa alasan sah dan tanpa pemberitahuan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Evaluasi kinerja","Penilaian capaian target kerja, kehadiran, kualitas hasil, dan etika pengurus."],["Self-assessment","Penilaian diri oleh pengurus sebagai pembanding penilaian atasan."],["Predikat","Kategori hasil: Sangat Baik, Baik, Cukup, atau Perlu Pembinaan (usulan)."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Evaluasi didasarkan pada uraian tugas dan target kerja (SOP-SDM-004 dan SOP-SDM-005) serta bukti yang dapat dipertanggungjawabkan.","Evaluasi dilakukan tengah dan akhir periode (usulan).","Pengurus berhak melihat hasil dan memberi klarifikasi sebelum hasil ditetapkan (ART Pasal 13 ayat 9).","Kementerian PSDM hanya memberi rekomendasi; sanksi ditetapkan pimpinan BEM sesuai ART Pasal 12.","Ketidakhadiran tiga kali berturut-turut tanpa uzur dilaporkan sebagai dasar proses pemberhentian (AD Pasal 9 ayat 2 huruf e).","Hasil evaluasi bersifat rahasia dan hanya dibuka kepada pihak yang berwenang."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Menteri PSDM","A","Bertanggung jawab atas pelaksanaan, kewajaran, dan kerahasiaan evaluasi."],["Staf Kementerian PSDM","R","Mengumpulkan data, merekap skor, dan menyusun laporan."],["Menteri atau Kabiro (atasan langsung)","R","Menilai pengurus di unitnya berdasarkan bukti."],["Pengurus","R","Mengisi self-assessment dan memberi klarifikasi."],["Presiden","C","Menetapkan tindak lanjut bersama BPH sesuai kewenangan."],["Inspektur Jenderal","C","Memberi penilaian kinerja independen dan memeriksa kewajaran proses."],["Sekretaris Jenderal","R","Menyediakan data presensi dan laporan progres."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Uraian tugas dan target kerja pengurus.","Data presensi dan laporan progres.","Formulir Evaluasi Pengurus."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan jadwal dan instrumen: Menetapkan jadwal evaluasi dan instrumen penilaian.","Menteri","Kalender organisasi","Jadwal dan instrumen","5 hari kerja sebelum evaluasi"],["2","Pengumpulan data: Mengumpulkan presensi, laporan progres, dan capaian target.","Staf; Sekjen","Presensi, laporan","Data kinerja","5 hari kerja"],["3","Penilaian: Atasan menilai dan pengurus mengisi self-assessment.","Atasan langsung; pengurus","Data kinerja","Formulir terisi","5 hari kerja"],["4","Rekapitulasi: Merekap skor dan menentukan predikat sementara.","Staf","Formulir terisi","Rekap skor","3 hari kerja"],["5","Kalibrasi dengan Irjen: Membandingkan hasil dengan penilaian kinerja Irjen.","Menteri; Irjen","Rekap skor","Hasil terkalibrasi","3 hari kerja"],["6","Umpan balik dan klarifikasi: Menyampaikan hasil kepada pengurus dan menerima klarifikasi tertulis.","Menteri; pengurus","Hasil terkalibrasi","Hasil final","3 hari kerja"],["7","Rekomendasi: Menyampaikan rekomendasi apresiasi, pembinaan, atau pemrosesan pelanggaran kepada Presiden.","Menteri","Hasil final","Rekomendasi tertulis","2 hari kerja"],["8","Tindak lanjut dan arsip: Memantau tindak lanjut dan mengarsipkan hasil secara rahasia.","Menteri; Sekjen","Keputusan Presiden","Arsip evaluasi","Sesuai keputusan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari penetapan jadwal hingga rekomendasi paling lama 21 hari kerja. Hasil akhir: rekap skor, hasil final, dan rekomendasi tertulis."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengurus keberatan atas hasil: mengajukan klarifikasi tertulis dalam 3 hari kerja dan ditinjau Menteri PSDM bersama Irjen.","Dugaan pelanggaran etik atau pelanggaran berat: SOP-SDM-013.","Pengurus tidak aktif atau tidak memenuhi tugas: pembinaan SOP-SDM-011; bila berlanjut diproses SOP-SDM-014.","Perbedaan hasil dengan penilaian Irjen yang tidak selesai: diputuskan Wakil Presiden."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pengurus aktif dievaluasi pada setiap siklus.","Hasil disampaikan kepada pengurus sebelum ditetapkan pada 100% kasus.","Rekomendasi diserahkan dalam 21 hari kerja sejak evaluasi dimulai."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Evaluasi Pengurus.","Rekap skor dan hasil final.","Rekomendasi tertulis kepada Presiden. Seluruh dokumen disimpan pada repositori resmi BEM (folder PSDM) oleh Menteri PSDM bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Menteri memeriksa kelengkapan evaluasi setiap siklus; Irjen menilai kewajaran proses pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Jadwal dan instrumen → Pengumpulan data → Penilaian → Rekap → Kalibrasi Irjen → Umpan balik → Rekomendasi → Tindak lanjut → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Evaluasi Pengurus","Nama; jabatan; target; capaian; kehadiran; kualitas; etika; skor; predikat; penilai."],["Formulir Klarifikasi Pengurus","Butir yang dipertanyakan; penjelasan; bukti pendukung; tanggal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Penilaian berdasarkan target dan bukti.","☐ Ya ☐ Tidak"],["2","Pengurus telah melihat hasil dan diberi kesempatan klarifikasi.","☐ Ya ☐ Tidak"],["3","Hasil dikalibrasi dengan penilaian Irjen.","☐ Ya ☐ Tidak"],["4","Hasil diarsipkan secara rahasia.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-IRJ-001","g":"SOP Khusus Unit: Inspektorat Jenderal","t":"Perencanaan Pengawasan","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Sekretaris Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[830,833],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur menyusun Rencana Pengawasan yang memuat objek, tujuan, metode, jadwal, dan tim, berbasis risiko dan selaras dengan program kerja serta kalender BEM."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Pengawasan Irjen atas kegiatan, administrasi, pertanggungjawaban keuangan, dan kinerja pengurus BEM. Pengawasan terhadap BPM, HIMA, atau UKM tidak termasuk dan diteruskan kepada KAUR ORMAWA sesuai ART Pasal 12 ayat (7) dan (8)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 1 huruf h (Irjen memiliki fungsi pengawasan terhadap penyelenggaraan organisasi).","ART Pasal 12 ayat (3), (4), dan (6) (pengawasan, evaluasi, dan penilaian kinerja pengurus; pembinaan dan pencegahan pelanggaran).","ART Pasal 13 ayat (5) sampai (8) (pemantauan, klarifikasi, evaluasi, dan penyampaian hasil melalui forum resmi BEM).","SOP-MONEV-001 dan SOP-RSK-001 (indikator kinerja dan identifikasi risiko)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rencana Pengawasan","Dokumen objek, tujuan, metode, jadwal, dan tim pengawasan dalam satu periode."],["Objek pengawasan","Kegiatan, dokumen, proses, atau unit yang diawasi."],["Independensi","Irjen tidak memeriksa pekerjaan yang ia lakukan atau tanggung jawabi sendiri."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pengawasan bertujuan pembinaan dan pencegahan pelanggaran, bukan mencari kesalahan (ART Pasal 12 ayat 4).","Prioritas ditentukan berdasarkan risiko: kegiatan besar, dana, kegiatan baru, dan temuan berulang.","Irjen tidak memeriksa kegiatan yang ia pimpin atau laksanakan; pemeriksaan itu dialihkan kepada Wakil Presiden dan Sekretaris Jenderal.","Rencana diberitahukan kepada unit yang diperiksa kecuali pemeriksaan mendadak yang disetujui Presiden.","Hasil pengawasan disampaikan melalui forum resmi BEM dan dijaga kerahasiaannya."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Inspektur Jenderal","A","Bertanggung jawab atas Rencana Pengawasan dan independensinya."],["Staf Inspektorat Jenderal","R","Mengumpulkan bahan, menilai risiko, dan menyusun draf rencana."],["Presiden","C","Menyetujui rencana dan pemeriksaan mendadak."],["Wakil Presiden","C","Memberi masukan agar rencana selaras dengan koordinasi Eksekutif."],["Sekretaris Jenderal","C","Menyediakan program kerja dan kalender organisasi."],["Menteri atau Kabiro objek pengawasan","I","Menerima pemberitahuan dan menyiapkan dokumen."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Program kerja dan kalender organisasi.","Anggaran yang disahkan.","Temuan dan laporan MONEV sebelumnya."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengumpulan bahan: Mengumpulkan program kerja, kalender, anggaran, laporan, dan temuan sebelumnya.","Staf","Dokumen organisasi","Bahan pengawasan","3 hari kerja setelah RAKER"],["2","Penilaian risiko: Menilai risiko objek dan menyusun daftar prioritas.","Staf","Bahan pengawasan","Daftar prioritas","3 hari kerja"],["3","Penyusunan rencana: Menyusun Rencana Pengawasan: objek, tujuan, metode, jadwal, dan tim.","Irjen","Daftar prioritas","Draf Rencana","5 hari kerja"],["4","Konsultasi: Membahas draf dengan Presiden dan Wakil Presiden.","Irjen","Draf Rencana","Masukan tercatat","3 hari kerja"],["5","Pengesahan: Menetapkan Rencana Pengawasan.","Irjen; Presiden","Draf final","Rencana disahkan","2 hari kerja"],["6","Pemberitahuan: Mengirim surat pemberitahuan kepada unit yang akan diperiksa.","Irjen; Sekjen","Rencana disahkan","Surat pemberitahuan","Minimal 3 hari kerja sebelum pemeriksaan"],["7","Peninjauan rencana: Meninjau dan merevisi rencana saat program berubah atau ada risiko baru.","Irjen","Perubahan program, temuan","Rencana revisi","Setiap triwulan atau saat perubahan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari pengumpulan bahan hingga pengesahan rencana paling lama 13 hari kerja. Hasil akhir: Rencana Pengawasan dan surat pemberitahuan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pemeriksaan mendadak yang diperlukan: persetujuan Presiden dan pencatatan alasan.","Irjen berkonflik kepentingan terhadap objek: pemeriksaan dialihkan kepada tim yang ditunjuk Wakil Presiden (SOP-RSK-006).","Perbedaan pandangan tentang prioritas: dibahas Rapat Pimpinan (SOP-GOV-005).","Objek di luar BEM (BPM, HIMA, UKM): diteruskan kepada KAUR ORMAWA."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Rencana Pengawasan disahkan paling lambat 13 hari kerja setelah RAKER.","Seluruh kegiatan berisiko tinggi masuk dalam rencana.","Rencana diberitahukan kepada unit minimal 3 hari kerja sebelum pemeriksaan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar prioritas risiko.","Rencana Pengawasan.","Surat pemberitahuan pemeriksaan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Inspektorat Jenderal) oleh Inspektur Jenderal (salinan kepada Sekretaris Jenderal) sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden dan Sekretaris Jenderal memeriksa kelengkapan dan independensi rencana pada evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kumpulkan bahan → Nilai risiko → Susun rencana → Konsultasi → Pengesahan → Pemberitahuan → Peninjauan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Rencana Pengawasan","Objek; tujuan; metode; jadwal; tim; tingkat risiko; dasar aturan."],["Surat Pemberitahuan Pemeriksaan","Unit; objek; tanggal; dokumen yang diminta; tim pemeriksa."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Objek ditetapkan berdasarkan risiko.","☐ Ya ☐ Tidak"],["2","Tidak ada konflik kepentingan pada tim.","☐ Ya ☐ Tidak"],["3","Rencana disahkan sebelum pelaksanaan.","☐ Ya ☐ Tidak"],["4","Unit diperiksa telah diberi pemberitahuan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Inspektorat Jenderal dan Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-IRJ-002","g":"SOP Khusus Unit: Inspektorat Jenderal","t":"Pemeriksaan Kegiatan dan Verifikasi Dokumen","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Sekretaris Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[834,837],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur memeriksa pelaksanaan kegiatan dan memverifikasi kelengkapan serta kebenaran dokumen (proposal, surat, laporan pertanggungjawaban, dan bukti transaksi) secara objektif dan berbasis bukti."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Kegiatan dan dokumen yang dikelola kementerian, biro, dan panitia BEM. Irjen memverifikasi bukti, tidak memegang atau membayarkan dana (lihat SOP-MONEV-007 dan SOP-KEU-016)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 12 ayat (3) sampai (6) (pengawasan, evaluasi, dan penilaian kinerja pengurus).","ART Pasal 13 ayat (4), (5), (7), dan (9) (bukti, pemantauan dan klarifikasi, keadilan, serta hak klarifikasi dan pembelaan).","AD Pasal 17 ayat (1) dan (2) (laporan pertanggungjawaban secara berkala; transparan, akuntabel, efektif, dan efisien).","ART Pasal 9 ayat (6) (program kerja memerlukan persetujuan Pembina sebelum dilaksanakan)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Verifikasi dokumen","Pemeriksaan kelengkapan, keabsahan, dan kesesuaian dokumen dengan ketentuan."],["Pemeriksaan lapangan","Pengamatan langsung pelaksanaan kegiatan."],["Bukti","Dokumen, foto, rekaman, atau catatan yang dapat dipertanggungjawabkan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pemeriksaan dilakukan berdasarkan Rencana Pengawasan, permintaan resmi, atau laporan yang disertai bukti (ART Pasal 13 ayat 4).","Tim pemeriksa tidak boleh berkonflik kepentingan terhadap objek (SOP-RSK-006).","Unit yang diperiksa berhak memberi klarifikasi dan pembelaan (ART Pasal 13 ayat 9).","Temuan didasarkan pada bukti, tidak menuduh, dan dijaga kerahasiaannya.","Dokumen asli tidak dibawa pergi kecuali dengan berita acara."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Inspektur Jenderal","A","Bertanggung jawab atas objektivitas dan hasil pemeriksaan."],["Tim pemeriksa (Staf Irjen)","R","Memverifikasi dokumen, memeriksa lapangan, dan menyusun lembar hasil."],["Unit atau panitia yang diperiksa","R","Menyediakan dokumen, hadir klarifikasi, dan menjawab pertanyaan."],["Sekretaris Jenderal","C","Menyediakan arsip dokumen."],["Kepala Biro Keuangan","C","Menyediakan bukti transaksi."],["Presiden dan Wakil Presiden","I","Menerima laporan hasil pemeriksaan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Rencana Pengawasan atau permintaan pemeriksaan.","Dokumen kegiatan yang diperiksa.","Daftar Periksa."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penugasan pemeriksaan: Menerbitkan Surat Tugas Pemeriksaan yang memuat tim, objek, dan tujuan.","Irjen","Rencana Pengawasan","Surat Tugas","1 hari kerja"],["2","Permintaan dokumen: Meminta dokumen kepada unit yang diperiksa.","Tim pemeriksa","Surat Tugas","Daftar dokumen diminta","Dokumen diserahkan 3 hari kerja"],["3","Verifikasi dokumen: Memeriksa kelengkapan, keabsahan, persetujuan, dan kesesuaian dengan AD/ART.","Tim pemeriksa","Dokumen, Daftar Periksa","Daftar Periksa terisi","5 hari kerja"],["4","Pemeriksaan lapangan: Mengamati pelaksanaan kegiatan bila diperlukan dan mencatat kondisi nyata.","Tim pemeriksa","Jadwal kegiatan","Catatan lapangan","Sesuai jadwal kegiatan"],["5","Klarifikasi: Memberi kesempatan unit menjelaskan temuan awal.","Tim pemeriksa; unit diperiksa","Temuan awal","Berita Acara Klarifikasi","3 hari kerja"],["6","Penyusunan hasil: Menyusun Lembar Hasil Pemeriksaan berdasarkan bukti dan klarifikasi.","Tim pemeriksa","Daftar Periksa, klarifikasi","Lembar Hasil","5 hari kerja"],["7","Penyampaian hasil: Menyampaikan hasil kepada unit dan menyerahkannya untuk dicatat sebagai temuan (SOP-IRJ-003).","Irjen","Lembar Hasil","Hasil final","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari penugasan hingga penyampaian hasil paling lama 19 hari kerja. Hasil akhir: Daftar Periksa, Berita Acara Klarifikasi, dan Lembar Hasil Pemeriksaan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Unit tidak menyerahkan dokumen dalam tenggat: diingatkan, lalu dilaporkan kepada Wakil Presiden.","Indikasi penyalahgunaan dana atau aset: dihentikan sementara dan dialihkan ke SOP-RSK-007.","Bukti tidak cukup: temuan tidak dicatat sampai bukti dilengkapi.","Perbedaan pandangan hasil pemeriksaan: dibahas Rapat Pimpinan (SOP-GOV-005)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pemeriksaan memiliki Surat Tugas dan Daftar Periksa.","Hasil disampaikan dalam 19 hari kerja pada minimal 90% kasus.","Seluruh unit yang diperiksa diberi kesempatan klarifikasi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Surat Tugas Pemeriksaan.","Daftar Periksa dan catatan lapangan.","Berita Acara Klarifikasi.","Lembar Hasil Pemeriksaan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Inspektorat Jenderal) oleh Inspektur Jenderal (salinan kepada Sekretaris Jenderal) sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden dan Sekretaris Jenderal memeriksa kelengkapan dokumen pemeriksaan pada evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Surat Tugas → Permintaan dokumen → Verifikasi → Pemeriksaan lapangan → Klarifikasi → Lembar Hasil → Penyampaian → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Surat Tugas Pemeriksaan","Tim; objek; tujuan; periode; dasar; tanda tangan Irjen."],["Daftar Periksa Verifikasi Dokumen","Dokumen; kelengkapan; keabsahan; persetujuan; kesesuaian AD/ART; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Surat Tugas diterbitkan sebelum pemeriksaan.","☐ Ya ☐ Tidak"],["2","Tim bebas dari konflik kepentingan.","☐ Ya ☐ Tidak"],["3","Klarifikasi unit dicatat dalam berita acara.","☐ Ya ☐ Tidak"],["4","Hasil didasarkan pada bukti.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; Menteri atau Kabiro yang diperiksa; arsip Inspektorat Jenderal. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-IRJ-003","g":"SOP Khusus Unit: Inspektorat Jenderal","t":"Pencatatan Temuan dan Rekomendasi Perbaikan","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Sekretaris Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[838,841],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara mencatat, mengklasifikasikan, dan menyampaikan temuan pengawasan serta menyusun rekomendasi perbaikan yang jelas, proporsional, dan dapat ditindaklanjuti."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Temuan dari pemeriksaan (SOP-IRJ-002), MONEV, atau laporan beralasan. Penjatuhan sanksi bukan kewenangan Irjen; sanksi atas pelanggaran individu menjadi kewenangan pimpinan BEM dan pelanggaran berat yang berdampak pada institusi dilaporkan kepada KAUR ORMAWA."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 12 ayat (3), (5), (6), dan (7) (pengawasan Irjen; kewenangan pimpinan BEM; laporan kepada KAUR ORMAWA).","ART Pasal 12 ayat (9) (klasifikasi pelanggaran berdasarkan tingkat dampak terhadap ormawa dan institusi).","ART Pasal 13 ayat (5) sampai (9) (pemantauan, klarifikasi, keadilan, dan hak pembelaan).","SOP-MONEV-009 dan SOP-MONEV-010 (pencatatan temuan berulang dan tindakan korektif)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Temuan","Fakta yang menyimpang dari ketentuan atau standar, disertai bukti."],["Register Temuan","Daftar seluruh temuan, klasifikasi, rekomendasi, penanggung jawab, dan statusnya."],["Klasifikasi temuan","Ringan (administratif), Sedang (berdampak internal), atau Berat (berdampak pada institusi, dana, atau etika), sesuai tingkat dampak (usulan)."],["Rekomendasi","Saran perbaikan konkret yang menyebut penanggung jawab dan tenggat."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap temuan memuat kondisi, kriteria (aturan), bukti, penyebab, dampak, dan rekomendasi (usulan).","Klasifikasi ditentukan berdasarkan tingkat dampak (ART Pasal 12 ayat 9).","Temuan berat disampaikan segera kepada Presiden dan, bila berdampak pada institusi, kepada KAUR ORMAWA (ART Pasal 12 ayat 7).","Dugaan pelanggaran individu mengikuti ART Pasal 13 ayat (1) dan (2).","Identitas sumber laporan dilindungi; temuan berulang dicatat sebagai masalah sistemik (SOP- MONEV-009)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Inspektur Jenderal","A","Bertanggung jawab atas ketepatan, kewajaran, dan kerahasiaan pencatatan temuan."],["Staf Inspektorat Jenderal","R","Merumuskan temuan dan memelihara Register Temuan."],["Unit yang diperiksa","C","Mengonfirmasi fakta dan menanggapi rekomendasi."],["Presiden","C","Menentukan tindak lanjut temuan berat sesuai kewenangan pimpinan BEM."],["Wakil Presiden","I","Menerima laporan untuk koordinasi Eksekutif."],["KAUR ORMAWA","I","Menerima laporan pelanggaran berat yang berdampak pada institusi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Lembar Hasil Pemeriksaan.","Bukti pendukung.","Daftar aturan yang menjadi kriteria."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Perumusan temuan: Merumuskan temuan dari lembar hasil: kondisi, kriteria, bukti, penyebab, dan dampak.","Staf","Lembar Hasil","Draf Temuan","3 hari kerja"],["2","Klasifikasi: Menentukan klasifikasi berdasarkan tingkat dampak.","Irjen","Draf Temuan","Temuan terklasifikasi","2 hari kerja"],["3","Pembahasan dengan unit: Mengonfirmasi fakta dengan unit yang diperiksa.","Irjen; unit diperiksa","Temuan terklasifikasi","Temuan terkonfirmasi","3 hari kerja"],["4","Penyusunan rekomendasi: Menyusun rekomendasi dengan penanggung jawab dan tenggat.","Irjen","Temuan terkonfirmasi","Rekomendasi","3 hari kerja"],["5","Pencatatan: Memasukkan temuan dan rekomendasi ke Register Temuan.","Staf","Rekomendasi","Register Temuan terbarui","1 hari kerja"],["6","Penyampaian: Menyampaikan temuan ringan dan sedang kepada unit melalui forum resmi BEM; temuan berat segera kepada Presiden dan, bila perlu, KAUR ORMAWA.","Irjen","Register Temuan","Laporan Temuan","Ringan dan sedang: forum bulanan; berat: 2 hari kerja"],["7","Tanggapan unit: Unit menyatakan menerima rekomendasi atau menolak dengan alasan tertulis.","Unit diperiksa","Laporan Temuan","Tanggapan tertulis","3 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari perumusan hingga tanggapan unit paling lama 17 hari kerja; temuan berat dilaporkan paling lambat 2 hari kerja setelah dikonfirmasi. Hasil akhir: Register Temuan, Laporan Temuan, dan tanggapan unit."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Unit menolak temuan dengan bukti baru: ditinjau ulang; bila belum sepakat diputuskan Wakil Presiden.","Temuan menyangkut individu: diteruskan kepada Eksekutif terkait sesuai ART Pasal 13 ayat (2); proses sanksi mengikuti SOP-SDM-013.","Temuan menyangkut dugaan penyalahgunaan dana atau aset: SOP-RSK-007.","Temuan berdampak pada institusi: dilaporkan kepada KAUR ORMAWA melalui Presiden."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% temuan memiliki bukti, klasifikasi, dan rekomendasi.","Temuan berat dilaporkan dalam 2 hari kerja pada 100% kasus.","Tidak ada temuan tanpa penanggung jawab dan tenggat."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Temuan.","Laporan Temuan.","Tanggapan tertulis unit. Seluruh dokumen disimpan pada repositori resmi BEM (folder Inspektorat Jenderal) oleh Inspektur Jenderal (salinan kepada Sekretaris Jenderal) sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden dan Sekretaris Jenderal memeriksa kelengkapan Register Temuan pada evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Rumuskan temuan → Klasifikasi → Pembahasan unit → Rekomendasi → Pencatatan → Penyampaian → Tanggapan unit → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Temuan","Nomor; unit; kondisi; kriteria; bukti; penyebab; dampak; klasifikasi."],["Lembar Rekomendasi","Temuan; rekomendasi; penanggung jawab; tenggat; tanggapan unit."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Temuan didukung bukti yang sah.","☐ Ya ☐ Tidak"],["2","Unit telah memberi klarifikasi.","☐ Ya ☐ Tidak"],["3","Klasifikasi sesuai tingkat dampak.","☐ Ya ☐ Tidak"],["4","Rekomendasi memiliki penanggung jawab dan tenggat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; unit terkait; arsip Inspektorat Jenderal. Laporan temuan berat diberikan kepada KAUR ORMAWA melalui Presiden."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-IRJ-004","g":"SOP Khusus Unit: Inspektorat Jenderal","t":"Pemantauan Tindak Lanjut","o":"Inspektur Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Inspektur Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Sekretaris Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[842,845],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur memantau pelaksanaan rekomendasi pengawasan hingga selesai, memastikan perbaikan terwujud, mencegah temuan berulang, dan melaporkan statusnya secara berkala."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh rekomendasi pada Register Temuan dan tindakan korektif sistemik (SOP-MONEV-010). Penjatuhan sanksi bukan kewenangan Irjen."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 12 ayat (3), (4), dan (6) (pengawasan, evaluasi, dan pencegahan pelanggaran).","ART Pasal 13 ayat (5), (6), dan (8) (pemantauan, penyampaian hasil melalui forum resmi BEM, penanganan dalam waktu wajar).","AD Pasal 17 ayat (1) dan (2) (pertanggungjawaban berkala yang transparan dan akuntabel)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Status tindak lanjut","Selesai, Dalam proses, Terlambat, atau Tidak dapat dilaksanakan (usulan)."],["Bukti penyelesaian","Dokumen atau catatan yang menunjukkan rekomendasi telah dilaksanakan."],["Penutupan temuan","Penetapan Irjen bahwa rekomendasi telah dilaksanakan dan diverifikasi."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap rekomendasi memiliki penanggung jawab dan tenggat.","Temuan ditutup hanya setelah bukti penyelesaian diverifikasi Irjen.","Keterlambatan dicatat dan diingatkan lebih dahulu; tidak langsung menjadi sanksi.","Status disampaikan setiap bulan melalui forum resmi BEM (ART Pasal 13 ayat 6).","Rekomendasi yang tidak dapat dilaksanakan memerlukan alasan tertulis dan persetujuan Presiden."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Inspektur Jenderal","A","Bertanggung jawab atas pemantauan dan penutupan temuan."],["Staf Inspektorat Jenderal","R","Mengingatkan, memverifikasi bukti, dan memperbarui Register Temuan."],["Penanggung jawab tindak lanjut (unit)","R","Melaksanakan rekomendasi dan menyerahkan bukti penyelesaian."],["Presiden","C","Memutuskan bila rekomendasi tidak dapat dilaksanakan atau terlambat berat."],["Wakil Presiden","I","Menerima laporan keterlambatan."],["Sekretaris Jenderal","I","Menerima laporan status untuk bahan evaluasi bulanan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Register Temuan.","Tanggapan unit.","Bukti penyelesaian."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan penanggung jawab dan tenggat: Mengonfirmasi penanggung jawab dan tenggat setiap rekomendasi.","Irjen; unit","Register Temuan","Daftar tindak lanjut","2 hari kerja"],["2","Pengingat: Mengirim pengingat sebelum tenggat.","Staf","Daftar tindak lanjut","Pengingat terkirim","3 hari kerja sebelum tenggat"],["3","Pelaporan bukti: Penanggung jawab menyerahkan bukti penyelesaian.","Penanggung jawab","Pelaksanaan rekomendasi","Bukti penyelesaian","Sesuai tenggat"],["4","Verifikasi: Memeriksa kecukupan bukti penyelesaian.","Staf; Irjen","Bukti penyelesaian","Hasil verifikasi","3 hari kerja"],["5","Penutupan atau perpanjangan: Menutup temuan atau memberi perpanjangan satu kali dengan alasan tertulis.","Irjen","Hasil verifikasi","Status terbarui","2 hari kerja"],["6","Penanganan keterlambatan: Melaporkan keterlambatan lebih dari 7 hari kerja kepada Wakil Presiden; yang berat kepada Presiden.","Irjen","Daftar tindak lanjut","Laporan keterlambatan","2 hari kerja"],["7","Pelaporan berkala: Menyampaikan status tindak lanjut melalui forum resmi BEM.","Irjen","Register Temuan","Laporan Status Tindak Lanjut","Bulanan"],["8","Evaluasi efektivitas: Memeriksa apakah masalah yang sama berulang setelah temuan ditutup.","Irjen","Register Temuan","Catatan efektivitas","1 bulan setelah penutupan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Verifikasi bukti paling lama 3 hari kerja setelah diterima; laporan status disampaikan setiap bulan. Hasil akhir: Register Temuan terbarui dan Laporan Status Tindak Lanjut."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Tenggat terlewat lebih dari 7 hari kerja: dilaporkan kepada Wakil Presiden; keterlambatan berat kepada Presiden.","Rekomendasi tidak dapat dilaksanakan: alasan tertulis disampaikan kepada Presiden untuk diputuskan.","Temuan yang sama berulang: dicatat sebagai masalah sistemik dan diprioritaskan pada Rencana Pengawasan (SOP-IRJ-001 dan SOP-MONEV-009).","Pelanggaran terus berlanjut meski telah diingatkan: diproses melalui SOP-SDM-013."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% rekomendasi selesai dalam tenggat.","100% penutupan temuan didukung bukti yang diverifikasi.","Jumlah temuan berulang menurun dari periode ke periode."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar tindak lanjut.","Register Temuan terbarui.","Laporan Status Tindak Lanjut. Seluruh dokumen disimpan pada repositori resmi BEM (folder Inspektorat Jenderal) oleh Inspektur Jenderal (salinan kepada Sekretaris Jenderal) sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Wakil Presiden dan Sekretaris Jenderal memeriksa Register Temuan dan laporan status pada evaluasi tengah periode."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Penetapan PJ dan tenggat → Pengingat → Bukti penyelesaian → Verifikasi → Penutupan atau perpanjangan → Laporan bulanan → Evaluasi efektivitas → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Lembar Tindak Lanjut","Temuan; rekomendasi; penanggung jawab; tenggat; status; bukti; catatan verifikasi."],["Laporan Status Tindak Lanjut","Periode; jumlah temuan; selesai; dalam proses; terlambat; kendala; rencana."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap rekomendasi memiliki penanggung jawab dan tenggat.","☐ Ya ☐ Tidak"],["2","Bukti penyelesaian telah diverifikasi sebelum penutupan.","☐ Ya ☐ Tidak"],["3","Keterlambatan dilaporkan sesuai ketentuan.","☐ Ya ☐ Tidak"],["4","Laporan status disampaikan melalui forum resmi BEM.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; penanggung jawab tindak lanjut; arsip Inspektorat Jenderal. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-DKV-001","g":"SOP Khusus Unit: Biro Desain Komunikasi Visual","t":"Permintaan Desain dan Brief","o":"Kepala Biro Desain Komunikasi Visual","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Desain Komunikasi Visual","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[846,848],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengajuan permintaan desain dan penyusunan brief agar kebutuhan visual unit dipahami jelas, dicatat, dan dapat dikerjakan tepat waktu."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh permintaan desain (poster, infografis, spanduk, templat, dan media visual lain) dari kementerian, biro, panitia, dan tim acara BEM. SOP ini tidak mengatur antrean (SOP-DKV-002), revisi dan persetujuan (SOP- DKV-003), maupun aset visual (SOP-DKV-004)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 18 ayat (1) dan (2) (lambang yang disahkan STDIIS Jember).","ART Pasal 2 huruf b (penggunaan nama, lambang, dan identitas resmi yang disetujui STDIIS Jember).","ART Pasal 3 huruf d (menjaga nama baik STDIIS Jember).","SOP-KOM-007 dan SOP-KOM-014 (persetujuan konten dan penggunaan identitas visual)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Brief desain","Formulir kebutuhan desain: tujuan, pesan, sasaran, ukuran, format, isi, dan tenggat."],["Pemohon","Unit atau panitia yang meminta desain."],["Tiket desain","Nomor pencatatan satu permintaan desain pada Daftar Antrean."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Permintaan hanya diterima melalui Formulir Brief Desain pada kanal resmi (SOP-KOM-001).","Isi teks, data, dan logo mitra disiapkan pemohon; konten yang melanggar syariat, SARA, atau aturan kampus ditolak.","Permintaan yang lengkap diberi tiket dalam 1 hari kerja.","Penggunaan makhluk bernyawa dan unsur visual lain mengikuti pedoman identitas visual BEM yang disahkan Presiden."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro DKV","A","Bertanggung jawab atas kelengkapan brief, kualitas, dan ketepatan waktu desain."],["Desainer","R","Menelaah brief, mengerjakan desain, dan memperbarui status tiket."],["Pemohon","R","Mengisi brief lengkap dan menyiapkan materi isi."],["Menteri atau Kabiro pemohon","C","Memastikan isi permintaan sesuai program kerja."],["Sekretaris Jenderal","I","Menerima rekap permintaan untuk kalender organisasi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Brief Desain.","Materi isi (teks, data, foto, logo).","Program kerja atau kalender kegiatan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan: Pemohon mengisi Formulir Brief Desain dan mengirimnya melalui kanal resmi.","Pemohon","Materi isi","Brief terkirim","Minimal 5 hari kerja sebelum dibutuhkan"],["2","Pemeriksaan kelengkapan: Memeriksa tujuan, ukuran, format, isi, dan tenggat; brief tidak lengkap dikembalikan.","Desainer","Brief","Lengkap atau perlu revisi","1 hari kerja"],["3","Penelaahan isi: Memeriksa kesesuaian isi dengan syariat, aturan kampus, dan pedoman identitas visual.","Kepala Biro","Brief lengkap","Isi layak atau ditolak dengan alasan","1 hari kerja"],["4","Penerbitan tiket: Memberi nomor tiket dan memasukkannya ke Daftar Antrean (SOP-DKV-002).","Desainer","Brief layak","Tiket tercatat","1 hari kerja"],["5","Konfirmasi kepada pemohon: Mengirim konfirmasi tiket dan perkiraan selesai.","Desainer","Tiket","Konfirmasi terkirim","1 hari kerja"],["6","Klarifikasi bila perlu: Meminta penjelasan tambahan kepada pemohon.","Desainer","Brief","Brief diperjelas","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari pengajuan hingga tiket dan konfirmasi diterima pemohon paling lama 3 hari kerja. Hasil akhir: Formulir Brief Desain dan tiket tercatat."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Permintaan mendesak kurang dari 5 hari kerja: Kepala Biro memutuskan prioritas bersama Wakil Presiden (SOP-DKV-002).","Isi permintaan berpotensi melanggar syariat atau aturan kampus: ditolak dan dilaporkan kepada Wakil Presiden.","Perselisihan prioritas antar-unit: SOP-GOV-004.","Penggunaan logo atau identitas tanpa izin: SOP-KOM-014."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% permintaan memiliki tiket dalam 1 hari kerja setelah brief lengkap.","100% desain memiliki brief tertulis.","Jumlah brief yang dikembalikan karena tidak lengkap menurun tiap bulan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Brief Desain.","Tiket pada Daftar Antrean.","Catatan penolakan, bila ada. Seluruh dokumen disimpan pada repositori resmi BEM (folder Desain Komunikasi Visual) oleh Kepala Biro Desain Komunikasi Visual bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memeriksa kelengkapan brief dan ketepatan penerbitan tiket setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengajuan brief → Pemeriksaan kelengkapan → Penelaahan isi → Penerbitan tiket → Konfirmasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Brief Desain","Pemohon; kegiatan; tujuan; pesan utama; sasaran; ukuran dan format; materi isi; tenggat; tanggal."],["Daftar Antrean Desain","Nomor tiket; pemohon; jenis; prioritas; desainer; tenggat; status."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Brief memuat tujuan, ukuran, format, dan tenggat.","☐ Ya ☐ Tidak"],["2","Isi telah ditelaah terhadap syariat dan aturan kampus.","☐ Ya ☐ Tidak"],["3","Tiket dicatat pada Daftar Antrean.","☐ Ya ☐ Tidak"],["4","Pemohon telah menerima konfirmasi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-DKV-002","g":"SOP Khusus Unit: Biro Desain Komunikasi Visual","t":"Antrean Pekerjaan Desain","o":"Kepala Biro Desain Komunikasi Visual","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Desain Komunikasi Visual","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[849,851],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara mengatur urutan, prioritas, dan pemantauan pekerjaan desain agar beban kerja merata dan tenggat unit terpenuhi."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh tiket desain yang telah diterbitkan melalui SOP-DKV-001. SOP ini tidak mengatur isi brief maupun persetujuan hasil."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 huruf h (mematuhi peraturan dan kebijakan STDIIS Jember).","ART Pasal 9 ayat (3) huruf c (timeline kegiatan pada Rapat Kerja).","ART Pasal 10 ayat (4) (monitoring penggunaan anggaran dan koordinasi kegiatan).","SOP-SDM-008 dan SOP-SDM-009 (penugasan dan pelaporan progres)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Daftar Antrean","Catatan seluruh tiket aktif beserta prioritas, pelaksana, tenggat, dan status."],["Prioritas","Tingkat urgensi: Mendesak, Tinggi, atau Biasa (usulan)."],["Kapasitas desainer","Jumlah tiket yang wajar ditangani satu desainer pada waktu bersamaan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Urutan pekerjaan berdasarkan prioritas, tenggat, dan tanggal masuk (yang masuk lebih dahulu dikerjakan lebih dahulu bila setara).","Kegiatan unggulan pada kalender organisasi diprioritaskan.","Satu desainer tidak diberi lebih dari 3 tiket aktif (usulan).","Status tiket diperbarui setiap hari kerja pada Daftar Antrean.","Perubahan prioritas diputuskan Kepala Biro dan diberitahukan kepada pemohon."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro DKV","A","Menetapkan prioritas, pembagian tiket, dan keseimbangan beban kerja."],["Desainer","R","Mengerjakan tiket dan memperbarui status."],["Pemohon","I","Menerima informasi status dan perkiraan selesai."],["Wakil Presiden","C","Memutuskan prioritas bila terjadi perselisihan antar-unit."],["Sekretaris Jenderal","I","Menerima rekap bulanan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Antrean Desain.","Kalender organisasi.","Informasi kapasitas desainer."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penilaian prioritas: Menilai tenggat dan urgensi setiap tiket baru.","Kepala Biro","Tiket baru, kalender","Prioritas tiket","1 hari kerja"],["2","Penugasan: Menugaskan tiket kepada desainer sesuai kapasitas dan keahlian.","Kepala Biro","Prioritas","Tiket ditugaskan","1 hari kerja"],["3","Penetapan perkiraan selesai: Desainer menetapkan perkiraan selesai draf pertama.","Desainer","Tiket","Perkiraan selesai","1 hari kerja"],["4","Pemantauan harian: Memperbarui status (Antre, Dikerjakan, Menunggu revisi, Selesai).","Desainer","Tiket","Status terbarui","Setiap hari kerja"],["5","Penanganan tenggat kritis: Tiket yang berisiko terlambat dilaporkan dan prioritas disesuaikan.","Kepala Biro","Status, kalender","Keputusan prioritas","1 hari kerja"],["6","Pemberitahuan: Memberi tahu pemohon bila perkiraan selesai berubah.","Desainer","Perubahan","Pemberitahuan","Segera"],["7","Rekap bulanan: Merekap jumlah tiket, ketepatan waktu, dan kendala.","Kepala Biro","Daftar Antrean","Rekap bulanan","Bulanan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penugasan paling lama 1 hari kerja setelah tiket terbit; draf pertama sesuai perkiraan yang dikonfirmasi. Hasil akhir: Daftar Antrean terbarui dan rekap bulanan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kapasitas tidak cukup: Kepala Biro meminta bantuan desainer unit lain melalui SOP-GOV-004 atau meminta penjadwalan ulang.","Dua unit meminta prioritas sama: diputuskan Wakil Presiden.","Desainer berhalangan: tiket dialihkan ke desainer lain dan pemohon diberi tahu.","Tiket dibatalkan pemohon: dicatat alasan dan status ditutup."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 85% tiket selesai sebelum tenggat.","Status tiket diperbarui setiap hari kerja pada 100% tiket aktif.","Tidak ada desainer dengan lebih dari 3 tiket aktif."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Antrean terbarui.","Rekap bulanan pekerjaan desain.","Catatan perubahan prioritas. Seluruh dokumen disimpan pada repositori resmi BEM (folder Desain Komunikasi Visual) oleh Kepala Biro Desain Komunikasi Visual bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memeriksa Daftar Antrean setiap minggu; Sekjen menggunakan rekap bulanan untuk evaluasi."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Nilai prioritas → Penugasan → Perkiraan selesai → Pemantauan harian → Tenggat kritis → Rekap bulanan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Antrean Desain","Nomor tiket; pemohon; prioritas; desainer; tenggat; status; catatan."],["Rekap Bulanan Desain","Jumlah tiket; selesai tepat waktu; terlambat; kendala; rencana perbaikan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap tiket memiliki prioritas dan desainer.","☐ Ya ☐ Tidak"],["2","Status diperbarui setiap hari kerja.","☐ Ya ☐ Tidak"],["3","Pemohon diberi tahu bila jadwal berubah.","☐ Ya ☐ Tidak"],["4","Rekap bulanan diserahkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-DKV-003","g":"SOP Khusus Unit: Biro Desain Komunikasi Visual","t":"Revisi dan Persetujuan Desain","o":"Kepala Biro Desain Komunikasi Visual","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Desain Komunikasi Visual","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[852,854],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penyerahan draf, permintaan revisi, dan persetujuan desain agar hasil akhir sesuai kebutuhan, aman secara isi, dan batas revisi jelas."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Draf dan hasil akhir desain yang dikerjakan Biro DKV. Persetujuan konten publikasi untuk media sosial mengikuti SOP-KOM-007."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 huruf d (nama baik STDIIS Jember).","ART Pasal 11 huruf a, b, dan g (larangan SARA, penistaan agama, dan pencemaran nama baik).","AD Pasal 18 ayat (1) dan (2) (lambang resmi).","SOP-KOM-007 dan SOP-KOM-009 (persetujuan konten dan koreksi publikasi)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Draf","Hasil awal desain untuk ditinjau pemohon."],["Putaran revisi","Satu kali permintaan perbaikan yang dikirim lengkap oleh pemohon."],["Desain final","Desain yang disetujui dan siap digunakan atau dipublikasikan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Revisi maksimal 2 putaran per tiket (usulan); putaran tambahan memerlukan persetujuan Kepala Biro.","Permintaan revisi disampaikan tertulis dan lengkap dalam satu pesan.","Perubahan isi pokok setelah persetujuan diperlakukan sebagai tiket baru.","Persetujuan akhir dari pemohon dan, untuk publikasi resmi, dari pihak berwenang (SOP-KOM-007).","Desain final tidak dimodifikasi pihak lain tanpa izin Biro DKV."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro DKV","A","Menyetujui mutu dan kepatuhan desain sebelum diserahkan."],["Desainer","R","Menyerahkan draf, melakukan revisi, dan menyerahkan file final."],["Pemohon","R","Meninjau, memberi revisi tertulis, dan menyetujui."],["Pejabat berwenang konten","C","Menyetujui konten publikasi resmi sesuai SOP-KOM-007."],["Sekretaris Jenderal","I","Menerima arsip desain final."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Tiket desain dan brief.","Draf desain.","Catatan revisi pemohon."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyerahan draf: Mengirim draf kepada pemohon melalui kanal resmi.","Desainer","Tiket, brief","Draf terkirim","Sesuai perkiraan selesai"],["2","Tinjauan pemohon: Pemohon memeriksa isi, ejaan, data, dan logo, lalu menyetujui atau meminta revisi.","Pemohon","Draf","Persetujuan atau catatan revisi","2 hari kerja"],["3","Pengerjaan revisi: Mengerjakan revisi sesuai catatan tertulis.","Desainer","Catatan revisi","Draf revisi","2 hari kerja"],["4","Pemeriksaan mutu: Memeriksa kesesuaian dengan pedoman identitas visual, syariat, dan aturan kampus.","Kepala Biro","Draf akhir","Layak diserahkan","1 hari kerja"],["5","Persetujuan akhir: Pemohon dan pejabat berwenang menyetujui desain final.","Pemohon; pejabat berwenang","Desain layak","Persetujuan tertulis","2 hari kerja"],["6","Penyerahan file final: Menyerahkan file final (format cetak dan digital) dan menyimpannya pada repositori.","Desainer","Persetujuan","File final","1 hari kerja"],["7","Penutupan tiket: Menutup tiket dan mencatat jumlah putaran revisi.","Desainer","File final","Tiket ditutup","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Setiap putaran revisi paling lama 2 hari kerja; penyerahan file final paling lama 1 hari kerja setelah persetujuan. Hasil akhir: desain final disetujui dan tiket ditutup."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pemohon tidak menanggapi dalam 3 hari kerja: pengingat; bila tenggat terancam, Kepala Biro menghubungi Menteri atau Kabiro pemohon.","Revisi melebihi 2 putaran: Kepala Biro memutuskan melanjutkan atau menetapkan tiket baru.","Kesalahan pada desain yang telah terpublikasi: SOP-KOM-009.","Perselisihan tentang hasil desain: diputuskan Wakil Presiden (SOP-GOV-004)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Rata-rata revisi tidak lebih dari 2 putaran per tiket.","Minimal 90% desain final disetujui tertulis sebelum digunakan.","Tidak ada desain berisi kesalahan data yang lolos ke publikasi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Draf dan catatan revisi.","Persetujuan tertulis.","File desain final.","Tiket yang ditutup. Seluruh dokumen disimpan pada repositori resmi BEM (folder Desain Komunikasi Visual) oleh Kepala Biro Desain Komunikasi Visual bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memeriksa mutu dan jumlah revisi setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Draf → Tinjauan pemohon → Revisi → Pemeriksaan mutu → Persetujuan akhir → File final → Penutupan tiket → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Catatan Revisi","Nomor tiket; putaran; bagian yang direvisi; keterangan; tanggal; pengirim."],["Lembar Persetujuan Desain","Nomor tiket; judul; versi; disetujui oleh; tanggal; catatan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Isi, ejaan, data, dan logo telah diperiksa.","☐ Ya ☐ Tidak"],["2","Desain sesuai syariat dan aturan kampus.","☐ Ya ☐ Tidak"],["3","Persetujuan tertulis diperoleh.","☐ Ya ☐ Tidak"],["4","File final tersimpan di repositori.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-DKV-004","g":"SOP Khusus Unit: Biro Desain Komunikasi Visual","t":"Pengelolaan Aset Visual","o":"Kepala Biro Desain Komunikasi Visual","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Desain Komunikasi Visual","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[855,857],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan cara menyimpan, menamai, mengamankan, dan memakai aset visual (logo, templat, font, foto, dan file sumber) agar identitas BEM konsisten, mudah ditemukan, dan terlindung dari penyalahgunaan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh aset visual milik BEM yang dikelola Biro DKV. Hak akses dan pencadangan dokumen umum mengikuti SOP-ADM-015."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 18 ayat (1) dan (2) (lambang BEM yang disahkan STDIIS Jember).","ART Pasal 2 huruf b (penggunaan nama, lambang, dan identitas resmi).","ART Pasal 11 huruf k (larangan menggunakan fasilitas atau nama organisasi untuk kepentingan pribadi).","SOP-ADM-014, SOP-ADM-015, dan SOP-KOM-014."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Aset visual","Logo, templat, ilustrasi, foto, font, dan file sumber desain milik BEM."],["Pustaka Aset","Folder terstruktur penyimpanan aset pada repositori resmi."],["File sumber","File asli desain yang dapat disunting."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Seluruh aset disimpan pada Pustaka Aset di repositori resmi, bukan hanya pada perangkat pribadi desainer.","Penamaan file memakai pola: JENIS-KEGIATAN-TANGGAL-VERSI.","Hak akses disunting hanya oleh Biro DKV; pengguna lain mendapat hak lihat dan unduh versi final.","Font, foto, dan ilustrasi bersumber dari yang sah dan tidak melanggar hak cipta.","Logo hanya digunakan sesuai pedoman identitas visual yang disahkan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro DKV","A","Bertanggung jawab atas kelengkapan, keamanan, dan ketertiban Pustaka Aset."],["Desainer","R","Mengunggah, menamai, dan memperbarui aset."],["Pengguna aset (unit lain)","R","Memakai aset sesuai pedoman dan tidak mengubahnya."],["Sekretaris Jenderal","C","Memberi masukan struktur folder dan hak akses."],["Inspektur Jenderal","I","Menerima laporan penyalahgunaan aset visual."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["File final dan file sumber desain.","Pedoman identitas visual.","Struktur folder repositori."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan aset: Mengumpulkan file final dan sumber setelah tiket ditutup.","Desainer","Tiket ditutup","Aset diterima","1 hari kerja"],["2","Penamaan dan klasifikasi: Menamai file sesuai pola dan memasukkannya ke folder yang tepat.","Desainer","Aset","Aset terklasifikasi","1 hari kerja"],["3","Pemeriksaan sumber dan lisensi: Memastikan font, foto, dan ilustrasi sah dan boleh dipakai.","Desainer; Kepala Biro","Aset","Aset terverifikasi","2 hari kerja"],["4","Pengaturan hak akses: Menetapkan hak akses sesuai peran.","Kepala Biro","Struktur folder","Hak akses tercatat","2 hari kerja"],["5","Layanan unduh: Menyediakan versi final bagi unit yang berhak.","Desainer","Permintaan unit","Aset diterima unit","2 hari kerja"],["6","Pencadangan: Mencadangkan Pustaka Aset secara berkala.","Desainer","Pustaka Aset","Cadangan tersimpan","Bulanan"],["7","Pemeriksaan berkala: Memeriksa kelengkapan, versi, dan penyalahgunaan aset.","Kepala Biro","Pustaka Aset","Catatan pemeriksaan","Per semester"],["8","Serah terima: Menyerahkan akses dan Pustaka Aset kepada kabinet berikutnya (SOP-TRN- 003 dan SOP-TRN-006).","Kepala Biro","Pustaka Aset","Berita acara serah terima","Akhir periode"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Aset diklasifikasikan dan disimpan paling lama 2 hari kerja setelah tiket ditutup. Hasil akhir: Pustaka Aset terstruktur, tercadangkan, dan terkendali aksesnya."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Aset dipakai tanpa izin atau dimodifikasi: Kepala Biro menegur dan melaporkan kepada Wakil Presiden; bila berulang diproses SOP-SDM-013.","Aset hilang atau terhapus: dipulihkan dari cadangan (SOP-ADM-015) dan dicatat sebagai insiden (SOP-RSK-012).","Dugaan pelanggaran hak cipta: aset ditarik dan diganti.","Akun penyimpanan diretas atau bocor: SOP-RSK-008 dan SOP-RSK-009."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% aset final tersimpan di Pustaka Aset dalam 2 hari kerja.","Cadangan dilakukan setiap bulan.","Tidak ada penggunaan logo di luar pedoman yang tidak tertangani."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Pustaka Aset terstruktur.","Daftar hak akses.","Catatan pemeriksaan dan pencadangan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Desain Komunikasi Visual) oleh Kepala Biro Desain Komunikasi Visual bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memeriksa Pustaka Aset setiap semester; Sekjen memeriksa hak akses; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima aset → Penamaan dan klasifikasi → Pemeriksaan lisensi → Hak akses → Layanan unduh → Pencadangan → Serah terima → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Aset Visual","Nama aset; jenis; versi; lokasi; sumber dan lisensi; pemilik; tanggal pembaruan."],["Daftar Hak Akses Aset","Pengguna; peran; hak (lihat, unduh, sunting); tanggal; penyetuju."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Aset memakai pola nama baku.","☐ Ya ☐ Tidak"],["2","Lisensi font dan foto telah diperiksa.","☐ Ya ☐ Tidak"],["3","Hak akses sesuai peran.","☐ Ya ☐ Tidak"],["4","Cadangan bulan berjalan tersedia.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SEK-001","g":"SOP Khusus Unit: Biro Kesekretariatan","t":"Persuratan Masuk dan Keluar","o":"Kepala Biro Kesekretariatan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Kesekretariatan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[858,861],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur penerimaan, pencatatan, penomoran, pembuatan, pengesahan, pengiriman, dan pengendalian surat masuk dan keluar BEM agar tertib dan dapat ditelusuri."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh surat resmi atas nama BEM, baik masuk maupun keluar, termasuk undangan, tugas, mandat, dan rekomendasi. SOP ini merinci SOP-ADM-001 sampai SOP-ADM-006 pada tingkat Biro Kesekretariatan."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf f (menandatangani surat resmi dan dokumen organisasi).","AD Pasal 18 ayat (1) dan (2) (lambang resmi).","ART Pasal 2 huruf b (nama, lambang, dan identitas resmi).","SOP-ADM-001 sampai SOP-ADM-006."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Surat masuk","Surat dari pihak luar BEM yang ditujukan kepada BEM atau unitnya."],["Surat keluar","Surat atas nama BEM yang dikirim kepada pihak lain."],["Buku Agenda Surat","Catatan nomor, tanggal, pengirim atau penerima, perihal, dan status surat."],["Lembar Disposisi","Lembar arahan penerusan dan tindak lanjut surat masuk."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Surat resmi hanya diterbitkan oleh Biro Kesekretariatan dengan kop surat, nomor, dan tanda tangan sesuai kewenangan.","Penomoran memakai sistem baku dan tidak boleh diberikan mundur (backdate).","Surat masuk dicatat pada hari diterima dan dikendalikan hingga ada tindak lanjut.","Surat bersifat rahasia dikelola sesuai SOP-ADM-020.","Surat ke pimpinan kampus ditandatangani Presiden atau pejabat yang diberi mandat (ART Pasal 4 huruf e dan f)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Kesekretariatan","A","Bertanggung jawab atas ketertiban, penomoran, dan arsip persuratan."],["Admin persuratan","R","Mencatat, membuat draf, memberi nomor, mengirim, dan mengarsipkan surat."],["Sekretaris Jenderal","C","Memeriksa kesesuaian administrasi dan kewenangan penandatangan."],["Pejabat penandatangan","R","Menyetujui dan menandatangani sesuai kewenangan."],["Unit pemohon","R","Menyediakan bahan surat dan menindaklanjuti disposisi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Permintaan Surat.","Templat surat dan kop surat.","Surat masuk dan Lembar Disposisi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penerimaan surat masuk: Mencatat surat pada Buku Agenda dan memindai bila perlu.","Admin","Surat masuk","Surat tercatat","Pada hari diterima"],["2","Disposisi: Meneruskan surat kepada pimpinan untuk arahan dan kepada unit tujuan.","Sekjen; Admin","Surat tercatat","Lembar Disposisi","1 hari kerja"],["3","Permintaan surat keluar: Unit pemohon mengajukan Formulir Permintaan Surat beserta bahan.","Unit pemohon","Bahan surat","Permintaan tercatat","Minimal 3 hari kerja sebelum dibutuhkan"],["4","Penyusunan dan pemeriksaan: Menyusun draf, memeriksa isi, format, dan kewenangan.","Admin; Sekjen","Permintaan, templat","Draf diperiksa","1 hari kerja"],["5","Persetujuan dan tanda tangan: Menyerahkan draf kepada pejabat penandatangan.","Pejabat penandatangan","Draf diperiksa","Surat bertanda tangan","2 hari kerja"],["6","Penomoran: Memberi nomor sesuai sistem pada surat final dan mencatat pada Buku Agenda.","Admin","Surat bertanda tangan","Surat bernomor","1 hari kerja"],["7","Pengiriman: Mengirim melalui kanal resmi dan menyimpan bukti.","Admin","Surat bernomor","Bukti pengiriman","1 hari kerja"],["8","Pengarsipan dan pengendalian: Mengarsipkan surat dan memantau tindak lanjut surat masuk.","Admin","Surat, bukti","Arsip; status tindak lanjut","Setelah dikirim; mingguan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Surat keluar rutin selesai paling lama 7 hari kerja sejak permintaan lengkap; surat masuk didisposisikan paling lama 1 hari kerja. Hasil akhir: surat resmi bernomor, bukti pengiriman, dan arsip lengkap."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Surat mendesak: Sekjen dan pejabat penandatangan memproses di luar antrean dan alasan dicatat (SOP-GOV-012).","Surat dari pihak kampus yang memerlukan keputusan pimpinan: langsung diteruskan kepada Presiden.","Kesalahan nomor atau isi surat yang telah terkirim: dibuat surat koreksi dan dicatat pada Buku Agenda.","Surat bermuatan aduan atau data pribadi: SOP-ADV-010 dan SOP-RSK-010."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% surat memiliki nomor dan tercatat pada Buku Agenda.","Minimal 90% surat masuk didisposisikan dalam 1 hari kerja.","Tidak ada surat keluar tanpa tanda tangan berwenang."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Buku Agenda Surat.","Lembar Disposisi.","Surat keluar bernomor dan bukti pengiriman.","Arsip digital dan fisik. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan) oleh Kepala Biro Kesekretariatan bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memeriksa Buku Agenda dan kelengkapan arsip setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Terima surat → Disposisi → Permintaan surat keluar → Susun dan periksa → Tanda tangan → Penomoran → Kirim → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Surat","Unit; jenis surat; tujuan; perihal; lampiran; tanggal dibutuhkan; pemohon."],["Buku Agenda Surat","Nomor; tanggal; pengirim atau penerima; perihal; penandatangan; status."],["Lembar Disposisi","Nomor surat; perihal; arahan; unit tujuan; tenggat; paraf."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Kop surat, nomor, dan tanda tangan sesuai kewenangan.","☐ Ya ☐ Tidak"],["2","Surat tercatat pada Buku Agenda.","☐ Ya ☐ Tidak"],["3","Bukti pengiriman tersimpan.","☐ Ya ☐ Tidak"],["4","Tindak lanjut surat masuk dipantau.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SEK-002","g":"SOP Khusus Unit: Biro Kesekretariatan","t":"Pengarsipan","o":"Kepala Biro Kesekretariatan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Kesekretariatan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[862,865],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengarsipan dokumen fisik dan digital agar seluruh dokumen BEM tersimpan lengkap, terstruktur, aman, mudah ditemukan, dan siap diserahterimakan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh dokumen kabinet pada repositori resmi dan arsip fisik sekretariat. SOP ini merinci SOP-ADM-012 sampai SOP-ADM-016 dan SOP-ADM-020."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (3) (dokumentasi bukti penerimaan dana).","AD Pasal 17 ayat (1) sampai (3) (pertanggungjawaban yang transparan dan akuntabel).","ART Pasal 7 ayat (8) dan Pasal 8 ayat (7) (berita acara).","SOP-ADM-012 sampai SOP-ADM-016."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Repositori resmi","Penyimpanan digital milik organisasi, bukan perangkat atau akun pribadi."],["Daftar Arsip","Catatan jenis, lokasi, tanggal, dan status setiap arsip."],["Retensi","Lama dokumen disimpan sebelum dievaluasi untuk diarsipkan permanen atau dimusnahkan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Dokumen final disimpan pada repositori resmi dalam 3 hari kerja setelah ditetapkan.","Struktur folder dan penamaan mengikuti pola baku (SOP-ADM-014).","Dokumen penting disimpan fisik dan digital; dokumen rahasia dibatasi aksesnya.","Pemusnahan dokumen hanya atas persetujuan Presiden dan dicatat dalam berita acara.","Hak akses disunting hanya oleh Biro Kesekretariatan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Kesekretariatan","A","Bertanggung jawab atas struktur, kelengkapan, dan keamanan arsip."],["Admin dokumen","R","Mengunggah, menamai, mencatat, dan mencadangkan arsip."],["Unit penghasil dokumen","R","Menyerahkan dokumen final tepat waktu."],["Sekretaris Jenderal","C","Menetapkan kebijakan akses dan retensi."],["Presiden","C","Menyetujui pemusnahan dokumen."],["Inspektur Jenderal","I","Menerima akses lihat untuk pengawasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Dokumen final dari unit.","Struktur folder dan pola penamaan.","Daftar Arsip."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyerahan dokumen: Unit menyerahkan dokumen final beserta lampiran.","Unit penghasil","Dokumen final","Dokumen diterima","3 hari kerja setelah final"],["2","Pemeriksaan: Memeriksa kelengkapan, tanda tangan, dan format.","Admin dokumen","Dokumen","Lengkap atau dikembalikan","1 hari kerja"],["3","Penamaan dan klasifikasi: Menamai dan memasukkan ke folder yang tepat.","Admin dokumen","Dokumen lengkap","Dokumen terklasifikasi","1 hari kerja"],["4","Pencatatan: Mencatat pada Daftar Arsip dan menentukan retensi.","Admin dokumen","Dokumen terklasifikasi","Entri Daftar Arsip","1 hari kerja"],["5","Penyimpanan fisik: Menyimpan dokumen fisik di lemari sekretariat secara teratur.","Admin dokumen","Dokumen fisik","Arsip fisik","1 hari kerja"],["6","Pencadangan: Mencadangkan repositori secara berkala.","Admin dokumen","Repositori","Cadangan","Bulanan"],["7","Pemeriksaan berkala: Memeriksa kelengkapan arsip dan hak akses.","Kepala Biro","Daftar Arsip","Catatan pemeriksaan","Per semester"],["8","Evaluasi retensi dan pemusnahan: Mengusulkan pemusnahan arsip yang telah melewati retensi kepada Presiden.","Kepala Biro; Presiden","Daftar Arsip","Berita acara pemusnahan","Akhir periode"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dokumen diarsipkan paling lama 5 hari kerja setelah diserahkan. Hasil akhir: arsip fisik dan digital lengkap serta Daftar Arsip terbarui."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Unit terlambat menyerahkan dokumen: diingatkan, lalu dilaporkan kepada Sekjen dan Wakil Presiden.","Dokumen hilang atau rusak: dipulihkan dari cadangan dan dicatat sebagai insiden (SOP-RSK-012).","Akun repositori diretas: SOP-RSK-008 dan SOP-RSK-009.","Permintaan akses dokumen rahasia: diputuskan Sekjen dan Presiden."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% dokumen final diarsipkan dalam 5 hari kerja.","Cadangan dilakukan setiap bulan.","Tidak ada dokumen penting yang hanya tersimpan di perangkat pribadi."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Arsip.","Arsip digital dan fisik.","Catatan pencadangan dan pemeriksaan.","Berita acara pemusnahan, bila ada. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan) oleh Kepala Biro Kesekretariatan bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memeriksa Daftar Arsip setiap bulan; Irjen memeriksa kelengkapan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Serah dokumen → Pemeriksaan → Klasifikasi → Pencatatan → Simpan fisik dan digital → Pencadangan → Evaluasi retensi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Arsip","Nomor; jenis dokumen; tanggal; unit; lokasi; retensi; status."],["Berita Acara Pemusnahan Arsip","Daftar arsip; alasan; tanggal; saksi; persetujuan Presiden."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Dokumen final telah lengkap dan bertanda tangan.","☐ Ya ☐ Tidak"],["2","Dokumen tercatat pada Daftar Arsip.","☐ Ya ☐ Tidak"],["3","Cadangan bulan berjalan tersedia.","☐ Ya ☐ Tidak"],["4","Akses dokumen rahasia dibatasi.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SEK-003","g":"SOP Khusus Unit: Biro Kesekretariatan","t":"Notulensi Rapat","o":"Kepala Biro Kesekretariatan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Kesekretariatan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[866,868],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pencatatan, pengesahan, dan penyebaran notulensi rapat agar setiap keputusan, tindak lanjut, dan penanggung jawab terdokumentasi dengan benar."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh rapat resmi BEM: rapat pimpinan, rapat kabinet, rapat koordinasi, RAKER, dan rapat evaluasi. Berita acara Mubes dan Musyawarah Istimewa mengikuti ART Pasal 7 ayat (8) dan Pasal 8 ayat (7). SOP ini merinci SOP-ADM-009 dan SOP-ADM-010."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 10 ayat (5) (hasil rapat dituangkan dalam notulensi resmi dan disosialisasikan).","ART Pasal 7 ayat (8) dan Pasal 8 ayat (7) (berita acara Mubes dan Musyawarah Istimewa).","ART Pasal 9 ayat (4) dan (5) (keputusan RAKER).","SOP-GOV-005 sampai SOP-GOV-007."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Notulensi","Catatan resmi jalannya rapat: peserta, pokok bahasan, keputusan, tindak lanjut, dan penanggung jawab."],["Notulis","Pengurus yang ditugaskan mencatat rapat."],["Daftar Tindak Lanjut","Daftar butir tindakan hasil rapat beserta penanggung jawab dan tenggat."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap rapat resmi memiliki notulis dan daftar hadir.","Notulensi memuat keputusan dan pendapat berbeda yang dicatat dengan netral.","Notulensi disahkan pimpinan rapat sebelum disebarkan.","Notulensi dan daftar hadir disimpan sesuai SOP-SEK-002.","Rapat yang membahas hal sensitif dikelola sesuai SOP-ADM-020."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Kesekretariatan","A","Bertanggung jawab atas ketersediaan dan mutu notulensi."],["Notulis","R","Mencatat rapat, menyusun, dan menyebarkan notulensi."],["Pimpinan rapat","R","Mengoreksi dan mengesahkan notulensi."],["Peserta rapat","C","Memberi koreksi atas catatan yang menyangkut dirinya."],["Sekretaris Jenderal","I","Menerima notulensi untuk pemantauan tindak lanjut."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Undangan dan agenda rapat.","Daftar hadir.","Templat notulensi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penugasan notulis: Menunjuk notulis untuk setiap rapat.","Kepala Biro","Jadwal rapat","Notulis ditunjuk","Sebelum rapat"],["2","Pencatatan: Mencatat peserta, pokok bahasan, keputusan, dan tindak lanjut.","Notulis","Rapat, agenda","Catatan rapat","Selama rapat"],["3","Penyusunan notulensi: Menyusun notulensi dengan templat baku.","Notulis","Catatan rapat","Draf notulensi","1 hari kerja"],["4","Koreksi dan pengesahan: Pimpinan rapat memeriksa dan mengesahkan.","Pimpinan rapat","Draf","Notulensi sah","1 hari kerja"],["5","Penyebaran: Mengirim notulensi kepada seluruh peserta dan unit terkait.","Notulis","Notulensi sah","Notulensi terkirim","1 hari kerja setelah pengesahan"],["6","Penyusunan Daftar Tindak Lanjut: Memasukkan butir tindakan ke daftar tindak lanjut.","Notulis","Notulensi sah","Daftar Tindak Lanjut","Bersamaan penyebaran"],["7","Pemantauan tindak lanjut: Memantau penyelesaian dan melaporkan pada rapat berikutnya.","Sekjen; Notulis","Daftar Tindak Lanjut","Laporan tindak lanjut","Mingguan"],["8","Pengarsipan: Menyimpan notulensi dan daftar hadir.","Notulis","Notulensi","Arsip","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Notulensi sah dan terkirim paling lama 3 hari kerja setelah rapat. Hasil akhir: notulensi sah, daftar hadir, dan Daftar Tindak Lanjut."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Perbedaan catatan keputusan: pimpinan rapat memutuskan; bila perlu, rekaman rapat dijadikan rujukan.","Notulis berhalangan: Kepala Biro menunjuk pengganti sebelum rapat.","Notulensi rapat sensitif: dibatasi aksesnya (SOP-ADM-020).","Butir tindak lanjut tidak dikerjakan: SOP-MONEV-008."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% rapat resmi memiliki notulensi dan daftar hadir.","Minimal 90% notulensi terkirim dalam 3 hari kerja.","Minimal 85% butir tindak lanjut selesai sesuai tenggat."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Notulensi sah.","Daftar hadir.","Daftar Tindak Lanjut. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan) oleh Kepala Biro Kesekretariatan bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memeriksa kelengkapan notulensi setiap bulan; Sekjen memantau Daftar Tindak Lanjut."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tunjuk notulis → Catat rapat → Susun notulensi → Pengesahan pimpinan rapat → Sebar → Tindak lanjut → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Notulensi","Rapat; tanggal; tempat; peserta; agenda; pokok bahasan; keputusan; pendapat berbeda; tindak lanjut."],["Daftar Hadir Rapat","Nama; jabatan; tanda tangan; keterangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Notulis telah ditunjuk dan daftar hadir tersedia.","☐ Ya ☐ Tidak"],["2","Keputusan dan tindak lanjut tercatat jelas.","☐ Ya ☐ Tidak"],["3","Notulensi disahkan pimpinan rapat.","☐ Ya ☐ Tidak"],["4","Notulensi disebarkan dan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-SEK-004","g":"SOP Khusus Unit: Biro Kesekretariatan","t":"Pengendalian Dokumen Masuk dan Keluar","o":"Kepala Biro Kesekretariatan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Kesekretariatan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[869,872],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur mengendalikan dokumen yang masuk dan keluar BEM selain surat, yaitu keputusan, SOP, formulir, laporan, dan peminjaman dokumen asli, agar versi tepat, terdistribusi benar, dan dapat dilacak."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Dokumen keputusan, kebijakan, SOP, formulir, dan laporan BEM. SOP ini merinci SOP-ADM-011, SOP- ADM-016, dan Standar Pengendalian Dokumen pada Pedoman Bagian V."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf f (menandatangani dokumen organisasi).","Pedoman Penyusunan SOP BEM Bagian V (sistem kode dan data pengendalian dokumen).","AD Pasal 17 ayat (3) (pelaporan kepada BPM dan KAUR ORMAWA).","SOP-ADM-011, SOP-ADM-016, dan SOP-ADM-020."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Register Dokumen","Catatan kode, versi, pemilik, status, dan lokasi dokumen resmi."],["Dokumen terkendali","Dokumen yang versinya dicatat dan distribusinya dikelola."],["Dokumen kedaluwarsa","Dokumen yang telah diganti, dicabut, atau diarsipkan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Hanya versi terbaru yang berlaku dan tersedia untuk dipakai.","Setiap dokumen terkendali memiliki kode, nomor revisi, pemilik proses, dan tanggal berlaku.","Dokumen kedaluwarsa ditandai dan dipindahkan ke arsip.","Peminjaman dokumen asli dicatat dan dikembalikan sesuai tenggat.","Dokumen rahasia hanya diberikan kepada pihak berhak."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Kesekretariatan","A","Bertanggung jawab atas kebenaran Register Dokumen dan distribusi dokumen terkendali."],["Admin dokumen","R","Mencatat, mendistribusikan, dan mengendalikan versi."],["Pemilik proses","R","Mengajukan dokumen baru atau revisi dan menjaga isinya."],["Presiden","C","Mengesahkan dokumen kebijakan dan SOP."],["Sekretaris Jenderal","C","Memeriksa kesesuaian administrasi."],["Unit pengguna","I","Menggunakan versi terbaru dan mengembalikan dokumen pinjaman."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Dokumen baru atau revisi yang telah disahkan.","Register Dokumen.","Daftar distribusi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan dokumen: Pemilik proses menyerahkan dokumen yang telah disahkan beserta data pengendalian.","Pemilik proses","Dokumen sah","Dokumen diterima","Sesuai kebutuhan"],["2","Pemeriksaan data pengendalian: Memeriksa kode, revisi, pemilik, pengesah, tanggal berlaku, dan lokasi.","Admin dokumen","Dokumen","Data lengkap atau dikembalikan","1 hari kerja"],["3","Pencatatan: Memasukkan ke Register Dokumen dan menandai versi lama sebagai kedaluwarsa.","Admin dokumen","Dokumen lengkap","Register terbarui","1 hari kerja"],["4","Distribusi: Menyebarkan versi terbaru kepada unit sesuai daftar distribusi.","Admin dokumen","Daftar distribusi","Dokumen tersebar","1 hari kerja"],["5","Peminjaman: Mencatat peminjaman dokumen asli pada Buku Peminjaman.","Admin dokumen","Permintaan unit","Catatan peminjaman","1 hari kerja"],["6","Pengembalian: Memeriksa dan mencatat pengembalian dokumen.","Admin dokumen","Dokumen pinjaman","Pengembalian tercatat","Sesuai tenggat pinjam"],["7","Penarikan versi lama: Menarik versi lama dari penggunaan dan memindahkannya ke arsip.","Admin dokumen","Register","Versi lama diarsipkan","2 hari kerja"],["8","Pemeriksaan berkala: Memeriksa kesesuaian Register dengan dokumen di repositori.","Kepala Biro","Register, repositori","Catatan pemeriksaan","Bulanan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dokumen baru dicatat dan didistribusikan paling lama 3 hari kerja setelah diterima. Hasil akhir: Register Dokumen terbarui dan distribusi tercatat."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Dua versi beredar bersamaan: versi lama ditarik dan Kepala Biro melaporkan kepada Sekjen.","Dokumen pinjaman tidak dikembalikan: pengingat, lalu dilaporkan kepada Wakil Presiden.","Dokumen hilang: SOP-RSK-012.","Permintaan dokumen rahasia oleh pihak tidak berhak: ditolak dan dilaporkan kepada Sekjen (SOP- ADM-020)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% dokumen terkendali tercatat pada Register Dokumen.","Tidak ada versi kedaluwarsa beredar pada unit.","Dokumen pinjaman dikembalikan sesuai tenggat pada minimal 90% kasus."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Register Dokumen.","Daftar distribusi.","Buku Peminjaman Dokumen. Seluruh dokumen disimpan pada repositori resmi BEM (folder Kesekretariatan) oleh Kepala Biro Kesekretariatan bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memeriksa kesesuaian Register dengan repositori setiap bulan; Irjen menilai pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengajuan dokumen → Periksa data pengendalian → Pencatatan Register → Distribusi → Peminjaman dan pengembalian → Tarik versi lama → Pemeriksaan berkala → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Register Dokumen","Kode; judul; revisi; pemilik; pengesah; tanggal berlaku; lokasi; status."],["Buku Peminjaman Dokumen","Dokumen; peminjam; tujuan; tanggal pinjam; tenggat; tanggal kembali; paraf."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Dokumen memiliki kode, revisi, dan pemilik proses.","☐ Ya ☐ Tidak"],["2","Register Dokumen telah diperbarui.","☐ Ya ☐ Tidak"],["3","Versi lama telah ditarik.","☐ Ya ☐ Tidak"],["4","Peminjaman dan pengembalian tercatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-BKU-001","g":"SOP Khusus Unit: Biro Keuangan","t":"Penganggaran","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[873,876],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur menyusun, memverifikasi, menyetujui, dan menetapkan anggaran tahunan kabinet dan anggaran program kerja agar perencanaan keuangan sesuai program, realistis, dan sesuai syariat."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Rencana anggaran tahunan kabinet dan RAB seluruh program kerja. SOP ini merinci SOP-KEU-001 sampai SOP-KEU-003 pada tingkat Biro Keuangan."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Bab III (Tugas BEM) huruf e (menyusun anggaran dengan persetujuan BPM dan laporan pertanggungjawaban pada akhir masa jabatan).","ART Pasal 4 huruf d (mengajukan dana kemahasiswaan kepada pihak perguruan tinggi).","AD Pasal 15 ayat (1) sampai (4) (sumber dana, syariat, bukti, dan persetujuan KAUR ORMAWA atas penyusunan anggaran).","ART Pasal 9 ayat (3) huruf d (penyusunan anggaran biaya program kerja pada RAKER)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rencana Anggaran Tahunan","Rencana pendapatan dan belanja kabinet selama satu periode."],["RAB","Rincian anggaran biaya satu program kerja."],["Pagu","Batas maksimal dana yang tersedia untuk satu unit atau program."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Anggaran disusun berdasarkan program kerja yang disahkan RAKER dan waktu pengumpulan anggaran kampus.","Sumber dana dan penggunaannya sesuai syariat dan terhindar dari riba, gharar, dan maysir (AD Pasal 15 ayat 2).","Persetujuan anggaran mengikuti AD Pasal 15 ayat (4) dan ART Bab III huruf e; urutan persetujuan dikonfirmasi (lihat Catatan Penyusun).","Fungsi pengaju, pemeriksa, penyetuju, dan pemegang dana dipisahkan.","Anggaran yang telah disahkan tidak dilampaui tanpa persetujuan perubahan (SOP-KEU-014)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Bertanggung jawab atas rencana anggaran tahunan dan verifikasi RAB."],["Staf Biro Keuangan","R","Menyusun rekap anggaran dan memeriksa RAB."],["Menteri atau Kabiro pengusul","R","Menyusun RAB programnya dengan dasar harga yang wajar."],["Presiden","C","Menyetujui rencana anggaran sebelum diajukan."],["BPM","C","Menyetujui anggaran sesuai ART Bab III huruf e."],["KAUR ORMAWA","C","Menyetujui penyusunan anggaran sesuai AD Pasal 15 ayat (4)."],["Inspektur Jenderal","I","Menerima salinan untuk bahan pengawasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Program kerja yang disahkan RAKER.","Formulir RAB.","Jadwal pengumpulan anggaran kampus."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan kerangka: Menetapkan pagu dan jadwal berdasarkan jadwal kampus.","Kepala Biro; Presiden","Jadwal kampus, program kerja","Pagu dan jadwal","3 hari kerja"],["2","Penyusunan RAB: Menyusun RAB program dengan rincian volume, harga, dan dasar harga.","Pengusul","Program, pagu","RAB","5 hari kerja"],["3","Verifikasi RAB: Memeriksa kewajaran harga, kelengkapan, dan kesesuaian syariat.","Staf; Kepala Biro","RAB","RAB terverifikasi","3 hari kerja"],["4","Penyusunan rencana tahunan: Menggabungkan seluruh RAB menjadi Rencana Anggaran Tahunan.","Staf","RAB terverifikasi","Rencana Anggaran Tahunan","3 hari kerja"],["5","Persetujuan Presiden: Presiden memeriksa dan menyetujui rencana.","Presiden","Rencana Anggaran","Persetujuan internal","2 hari kerja"],["6","Persetujuan pihak eksternal: Mengajukan kepada BPM dan KAUR ORMAWA sesuai ketentuan.","Presiden; Kepala Biro","Rencana disetujui","Persetujuan BPM dan KAUR ORMAWA","Sesuai jadwal kampus"],["7","Penetapan dan sosialisasi: Menetapkan anggaran dan menyampaikan pagu kepada seluruh unit.","Kepala Biro","Persetujuan","Anggaran ditetapkan","3 hari kerja"],["8","Pengarsipan: Menyimpan dokumen anggaran sesuai SOP-SEK-002.","Staf","Anggaran","Arsip","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penyusunan hingga persetujuan internal paling lama 19 hari kerja, kecuali ditentukan jadwal kampus. Hasil akhir: Rencana Anggaran Tahunan dan RAB terverifikasi."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pagu tidak mencukupi: Menteri atau Kabiro menyesuaikan program; keputusan prioritas diambil Presiden.","Perbedaan pandangan BPM dan KAUR ORMAWA: Presiden mengonsultasikan kepada Pembina.","Dugaan penggelembungan harga: SOP-RSK-007.","Unsur riba, gharar, atau maysir pada rencana: ditolak dan dikembalikan."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% program berbiaya memiliki RAB terverifikasi.","Rencana anggaran diajukan sebelum jadwal kampus berakhir.","Tidak ada belanja di luar anggaran yang tidak disetujui."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["RAB terverifikasi.","Rencana Anggaran Tahunan.","Bukti persetujuan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Kepala Biro Keuangan bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memeriksa kesesuaian anggaran dengan program setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kerangka dan pagu → Susun RAB → Verifikasi → Rencana tahunan → Persetujuan Presiden → Persetujuan BPM dan KAUR ORMAWA → Penetapan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir RAB","Program; uraian biaya; volume; harga satuan; dasar harga; total; sumber dana."],["Rencana Anggaran Tahunan","Pendapatan; belanja tiap unit; pagu; total; tanda tangan persetujuan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","RAB mengikuti program kerja yang disahkan.","☐ Ya ☐ Tidak"],["2","Harga wajar dan memiliki dasar.","☐ Ya ☐ Tidak"],["3","Sumber dan penggunaan dana sesuai syariat.","☐ Ya ☐ Tidak"],["4","Persetujuan berwenang diperoleh.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-BKU-002","g":"SOP Khusus Unit: Biro Keuangan","t":"Pencairan Dana","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[877,879],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengajuan dan pencairan dana program kerja agar dana keluar hanya untuk kebutuhan yang telah disetujui dan dengan bukti yang lengkap."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Pencairan dana dari dana kemahasiswaan atau sumber lain untuk program kerja BEM. SOP ini merinci SOP- KEU-004 dan SOP-KEU-007."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf d (mengajukan dana kemahasiswaan).","AD Pasal 15 ayat (3) (dokumentasi bukti penerimaan resmi).","ART Pasal 11 huruf i dan k (larangan korupsi, manipulasi, dan penyalahgunaan dana).","SOP-KEU-004, SOP-KEU-007, dan SOP-KEU-009."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pengajuan Pencairan","Permintaan resmi dana sesuai RAB yang telah disetujui."],["Uang muka","Dana yang diberikan sebelum kegiatan dan wajib dipertanggungjawabkan."],["Bendahara","Pemegang dana yang melaksanakan penerimaan dan pembayaran."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Pencairan hanya untuk program dan RAB yang telah disetujui.","Pengaju, pemeriksa, penyetuju, dan pemegang dana dilakukan oleh pihak berbeda.","Pencairan disertai surat pengajuan, RAB, dan persetujuan; tanpa kelengkapan tidak diproses.","Uang muka wajib dipertanggungjawabkan dalam 7 hari kerja setelah kegiatan (usulan).","Dana disimpan pada rekening atau kas resmi organisasi (SOP-KEU-009)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Bertanggung jawab atas pemeriksaan dan keabsahan pencairan."],["Bendahara","R","Mencairkan dana, mencatat, dan menerima bukti."],["Ketua pelaksana kegiatan","R","Mengajukan pencairan dan menggunakan dana sesuai RAB."],["Presiden","C","Menyetujui pencairan sesuai kewenangan."],["Sekretaris Jenderal","C","Memeriksa kelengkapan surat dan proposal."],["Inspektur Jenderal","I","Menerima rekap untuk bahan pengawasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Proposal dan RAB yang disetujui.","Surat Pengajuan Pencairan.","Persetujuan berwenang."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan: Ketua pelaksana mengajukan pencairan dengan Formulir Pengajuan.","Ketua pelaksana","Proposal, RAB","Pengajuan terkirim","Minimal 5 hari kerja sebelum dana dibutuhkan"],["2","Pemeriksaan kelengkapan: Memeriksa kesesuaian dengan RAB dan persetujuan.","Staf Keuangan","Pengajuan","Lengkap atau dikembalikan","2 hari kerja"],["3","Verifikasi: Memeriksa ketersediaan dana dan kewajaran jumlah.","Kepala Biro","Hasil pemeriksaan","Verifikasi","1 hari kerja"],["4","Persetujuan: Menyetujui jumlah dan tujuan pencairan.","Presiden","Verifikasi","Persetujuan","1 hari kerja"],["5","Pencairan: Menyerahkan dana kepada penerima dengan tanda terima.","Bendahara","Persetujuan","Tanda terima","1 hari kerja"],["6","Pencatatan: Mencatat pengeluaran pada buku kas.","Bendahara","Tanda terima","Buku kas terbarui","Pada hari pencairan"],["7","Pengingat pertanggungjawaban: Mengingatkan batas pertanggungjawaban uang muka.","Staf Keuangan","Tanda terima","Pengingat","3 hari kerja sebelum tenggat"],["8","Penutupan: Mengonfirmasi pertanggungjawaban selesai (SOP-BKU-003 dan SOP- BKU-004).","Kepala Biro","Bukti, laporan","Pencairan ditutup","Sesuai tenggat"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Dari pengajuan lengkap hingga pencairan paling lama 5 hari kerja. Hasil akhir: tanda terima, buku kas terbarui, dan pertanggungjawaban uang muka."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kebutuhan mendesak: Presiden dan Kepala Biro memutuskan pencairan cepat melalui SOP-GOV-012 dengan bukti dilengkapi kemudian.","Dana tidak mencukupi: SOP-KEU-014.","Uang muka tidak dipertanggungjawabkan: ditagih dan dilaporkan kepada Wakil Presiden; bila berlanjut SOP-RSK-007.","Perbedaan antara RAB dan pengajuan: dikembalikan untuk diperbaiki."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pencairan memiliki persetujuan dan tanda terima.","Minimal 90% uang muka dipertanggungjawabkan tepat waktu.","Tidak ada pencairan di luar RAB."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Pengajuan Pencairan.","Tanda terima dana.","Buku kas terbarui. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Kepala Biro Keuangan bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memeriksa kepatuhan pencairan setiap bulan; Irjen memeriksa bukti pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengajuan → Pemeriksaan → Verifikasi → Persetujuan → Pencairan → Pencatatan → Pertanggungjawaban → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Pengajuan Pencairan","Kegiatan; jumlah; tujuan; rujukan RAB; tanggal dibutuhkan; pengaju."],["Tanda Terima Dana","Penerima; jumlah; tanggal; keperluan; tanda tangan penerima dan bendahara."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Pengajuan sesuai RAB yang disetujui.","☐ Ya ☐ Tidak"],["2","Persetujuan dan verifikasi lengkap.","☐ Ya ☐ Tidak"],["3","Tanda terima ditandatangani.","☐ Ya ☐ Tidak"],["4","Batas pertanggungjawaban dicatat.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-BKU-003","g":"SOP Khusus Unit: Biro Keuangan","t":"Pembayaran dan Pencatatan","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[880,882],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pembayaran, pencatatan, dan pengelolaan bukti transaksi agar setiap penerimaan dan pengeluaran tercatat benar, tepat waktu, dan dapat diperiksa."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh penerimaan dan pengeluaran dana BEM. SOP ini merinci SOP-KEU-005, SOP-KEU-006, SOP-KEU- 008, SOP-KEU-010, dan SOP-KEU-016."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 15 ayat (1) sampai (3) (sumber dana, syariat, dan bukti penerimaan resmi).","AD Pasal 17 ayat (1) dan (2) (laporan berkala; transparan dan akuntabel).","ART Pasal 3 huruf e (pengelolaan keuangan secara amanah, transparan, dan akuntabel).","ART Pasal 11 huruf i (larangan korupsi, manipulasi, dan penyelewengan dana)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Buku kas","Catatan kronologis penerimaan dan pengeluaran."],["Bukti transaksi","Kuitansi, nota, faktur, atau bukti transfer."],["Reimbursement","Penggantian biaya yang telah dikeluarkan pengurus untuk keperluan yang disetujui."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap transaksi memiliki bukti sah dan dicatat pada hari yang sama atau paling lambat hari kerja berikutnya.","Pembayaran hanya untuk item dalam RAB; di luar RAB memerlukan persetujuan (SOP-KEU-014).","Transaksi dalam jumlah besar dilakukan nontunai bila memungkinkan (usulan).","Nota dan kuitansi memuat tanggal, penjual, uraian, jumlah, dan tanda tangan.","Pengeluaran dan penerimaan tidak mengandung unsur riba, gharar, dan maysir."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Bertanggung jawab atas ketepatan pencatatan dan keabsahan bukti."],["Bendahara","R","Melakukan pembayaran, mencatat pada buku kas, dan menyimpan bukti."],["Pengusul pembayaran","R","Mengajukan pembayaran dengan nota dan bukti yang sah."],["Sekretaris Jenderal","C","Mengarsipkan bukti sesuai SOP-SEK-002."],["Inspektur Jenderal","I","Memeriksa bukti pada pengawasan berkala."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Permintaan pembayaran dan bukti.","RAB yang disetujui.","Buku kas."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan pembayaran: Pengusul mengirim permintaan beserta nota atau tagihan.","Pengusul","Nota atau tagihan","Permintaan tercatat","Sebelum jatuh tempo"],["2","Pemeriksaan bukti: Memeriksa keabsahan bukti dan kesesuaian dengan RAB.","Staf Keuangan","Permintaan, RAB","Bukti sah atau dikembalikan","2 hari kerja"],["3","Persetujuan: Menyetujui pembayaran sesuai batas kewenangan.","Kepala Biro","Hasil pemeriksaan","Persetujuan","1 hari kerja"],["4","Pembayaran: Melakukan pembayaran dan memperoleh bukti pembayaran.","Bendahara","Persetujuan","Bukti pembayaran","1 hari kerja"],["5","Pencatatan: Mencatat pada buku kas dan mengelompokkan bukti per kegiatan.","Bendahara","Bukti pembayaran","Buku kas terbarui","1 hari kerja"],["6","Pencatatan penerimaan: Mencatat setiap penerimaan dengan bukti penerimaan resmi.","Bendahara","Dana masuk","Bukti penerimaan","Pada hari diterima"],["7","Reimbursement: Memproses penggantian biaya yang sah setelah bukti diverifikasi.","Kepala Biro; Bendahara","Bukti, persetujuan","Penggantian dana","5 hari kerja"],["8","Pengarsipan bukti: Menyerahkan bukti kepada arsip.","Bendahara","Bukti","Arsip bukti","Bulanan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pembayaran dilakukan paling lama 4 hari kerja setelah permintaan lengkap; pencatatan paling lambat 1 hari kerja setelah transaksi. Hasil akhir: buku kas terbarui dan bukti tersimpan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Bukti tidak sah atau tidak lengkap: dikembalikan; bila telanjur dibayar, dicatat sebagai temuan (SOP- IRJ-003).","Selisih saldo: SOP-BKU-005 dan SOP-KEU-018.","Dugaan penyalahgunaan dana: SOP-RSK-007.","Pembayaran mendesak di luar prosedur: SOP-GOV-012 dengan bukti dilengkapi kemudian."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% transaksi memiliki bukti sah.","Minimal 95% transaksi dicatat dalam 1 hari kerja.","Tidak ada transaksi tanpa persetujuan berwenang."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Buku kas.","Bukti pembayaran dan penerimaan.","Daftar transaksi per kegiatan. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Kepala Biro Keuangan bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memeriksa buku kas dan bukti setiap bulan; Irjen memeriksa pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengajuan pembayaran → Pemeriksaan bukti → Persetujuan → Pembayaran → Pencatatan → Pengarsipan bukti → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Permintaan Pembayaran","Kegiatan; penerima; uraian; jumlah; rujukan RAB; bukti terlampir."],["Buku Kas","Tanggal; uraian; penerimaan; pengeluaran; saldo; rujukan bukti."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Bukti memuat tanggal, penjual, uraian, dan jumlah.","☐ Ya ☐ Tidak"],["2","Pembayaran sesuai RAB dan persetujuan.","☐ Ya ☐ Tidak"],["3","Transaksi dicatat pada buku kas.","☐ Ya ☐ Tidak"],["4","Bukti diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-BKU-004","g":"SOP Khusus Unit: Biro Keuangan","t":"Laporan Keuangan Kegiatan","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[883,886],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur menyusun laporan keuangan kegiatan dan memeriksa pertanggungjawaban agar setiap dana yang digunakan dapat dipertanggungjawabkan secara transparan dan tepat waktu."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Laporan keuangan setiap kegiatan sebagai bagian LPJ (SOP-PRO-020) dan laporan keuangan periodik. SOP ini merinci SOP-KEU-015 dan SOP-KEU-016."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["AD Pasal 17 ayat (1) sampai (3) (laporan berkala; disampaikan kepada BPM untuk dibahas pada Mubes dan dilaporkan kepada KAUR ORMAWA).","ART Bab III (Tugas BEM) huruf e (laporan pertanggungjawaban anggaran).","ART Pasal 3 huruf g (membuat laporan pertanggungjawaban kegiatan dan keuangan).","ART Pasal 11 huruf i."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Laporan keuangan kegiatan","Ringkasan penerimaan, pengeluaran, dan saldo satu kegiatan beserta bukti."],["Sisa dana","Selisih dana yang diterima dan yang dibelanjakan."],["Pemeriksaan bukti","Pengecekan kelengkapan dan kesesuaian bukti dengan laporan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Laporan keuangan diserahkan dalam 7 hari kerja setelah kegiatan (usulan).","Setiap angka pada laporan dapat dilacak pada bukti.","Sisa dana disetor kembali kepada Bendahara dalam 3 hari kerja setelah kegiatan.","Kekurangan dana yang ditutup dari pihak lain dicatat dan diumumkan pada laporan.","Laporan menjadi bagian LPJ kegiatan dan bahan laporan kabinet."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Bertanggung jawab atas pemeriksaan dan penerimaan laporan keuangan."],["Bendahara kegiatan","R","Menyusun laporan keuangan dan menyerahkan bukti."],["Ketua pelaksana kegiatan","R","Menyetujui laporan dan bertanggung jawab atas penggunaan dana."],["Staf Biro Keuangan","R","Memeriksa laporan dan bukti."],["Inspektur Jenderal","C","Memverifikasi pertanggungjawaban pada pengawasan (SOP-MONEV-007)."],["Sekretaris Jenderal","I","Menerima laporan untuk LPJ dan arsip."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Buku kas kegiatan.","Bukti transaksi.","RAB dan realisasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Rekapitulasi: Merekap penerimaan, pengeluaran, dan sisa dana.","Bendahara kegiatan","Buku kas, bukti","Rekap realisasi","3 hari kerja"],["2","Penyusunan laporan: Menyusun laporan dengan perbandingan RAB dan realisasi.","Bendahara kegiatan","Rekap","Draf laporan","2 hari kerja"],["3","Persetujuan ketua pelaksana: Ketua pelaksana memeriksa dan menandatangani.","Ketua pelaksana","Draf laporan","Laporan bertanda tangan","1 hari kerja"],["4","Penyerahan: Menyerahkan laporan dan bukti kepada Biro Keuangan.","Bendahara kegiatan","Laporan, bukti","Laporan diterima","7 hari kerja setelah kegiatan"],["5","Pemeriksaan bukti: Memeriksa kelengkapan dan kesesuaian bukti.","Staf Keuangan","Laporan, bukti","Hasil pemeriksaan","3 hari kerja"],["6","Perbaikan: Meminta perbaikan bila ada ketidaksesuaian.","Bendahara kegiatan","Catatan pemeriksaan","Laporan diperbaiki","3 hari kerja"],["7","Penerimaan dan penutupan: Menerima laporan, menyetor sisa dana, dan menutup kegiatan.","Kepala Biro","Laporan benar","Berita Acara Penutupan Keuangan","2 hari kerja"],["8","Penyerahan untuk LPJ: Meneruskan laporan kepada penyusun LPJ dan arsip.","Kepala Biro; Sekjen","Laporan diterima","LPJ lengkap (SOP-PRO-020)","2 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Penyerahan laporan paling lama 7 hari kerja setelah kegiatan; pemeriksaan dan penutupan paling lama 8 hari kerja setelah laporan diterima. Hasil akhir: laporan keuangan kegiatan dan Berita Acara Penutupan Keuangan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Laporan terlambat: pengingat, lalu dilaporkan kepada Wakil Presiden dan dapat menunda pencairan kegiatan berikutnya.","Selisih antara laporan dan bukti: dikembalikan; indikasi penyelewengan SOP-RSK-007.","Sisa dana tidak disetor: ditagih dan dilaporkan kepada Presiden.","Bukti hilang: pernyataan tertulis dan persetujuan Kepala Biro; dicatat sebagai insiden (SOP-RSK-012)."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% laporan diserahkan dalam 7 hari kerja.","100% kegiatan berbiaya ditutup dengan Berita Acara Penutupan Keuangan.","Tidak ada selisih tak terjelaskan pada pemeriksaan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Laporan keuangan kegiatan.","Berita Acara Penutupan Keuangan.","Bukti transaksi terarsip. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Kepala Biro Keuangan bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memeriksa ketepatan waktu dan kelengkapan laporan setiap bulan; Irjen memverifikasi pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Rekap realisasi → Susun laporan → Persetujuan ketua pelaksana → Penyerahan → Pemeriksaan bukti → Perbaikan → Penutupan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Laporan Keuangan Kegiatan","Kegiatan; sumber dana; RAB; realisasi; selisih; sisa dana; lampiran bukti."],["Berita Acara Penutupan Keuangan","Kegiatan; saldo akhir; sisa dana disetor; pemeriksa; tanggal; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap angka dapat dilacak pada bukti.","☐ Ya ☐ Tidak"],["2","Sisa dana telah disetor.","☐ Ya ☐ Tidak"],["3","Laporan ditandatangani ketua pelaksana.","☐ Ya ☐ Tidak"],["4","Berita Acara Penutupan diterbitkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-BKU-005","g":"SOP Khusus Unit: Biro Keuangan","t":"Rekonsiliasi Kas","o":"Kepala Biro Keuangan","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Kepala Biro Keuangan","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[887,889],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur mencocokkan catatan kas dengan saldo nyata dan bukti agar selisih terdeteksi dini, dijelaskan, dan diperbaiki."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Kas tunai, rekening, dan seluruh dana organisasi. SOP ini merinci SOP-KEU-017 dan SOP-KEU-018."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 huruf e (keuangan yang amanah, transparan, dan akuntabel).","AD Pasal 17 ayat (2) (transparan, akuntabel, efektif, dan efisien).","ART Pasal 10 ayat (4) huruf b (monitoring penggunaan anggaran).","ART Pasal 11 huruf i (larangan manipulasi dan penyelewengan dana)."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rekonsiliasi","Pencocokan buku kas dengan saldo tunai, mutasi rekening, dan bukti."],["Selisih","Perbedaan antara saldo buku dan saldo nyata."],["Berita Acara Rekonsiliasi","Catatan hasil rekonsiliasi dan penjelasan selisih."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Rekonsiliasi dilakukan setiap bulan dan sebelum serah terima keuangan.","Dilakukan oleh pihak selain pemegang kas (pemisahan fungsi).","Selisih apa pun dicatat dan dijelaskan, tidak ditutup diam-diam.","Hasil dilaporkan kepada Presiden dan dapat diperiksa Irjen.","Rekening hanya atas nama organisasi sesuai SOP-KEU-009."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Kepala Biro Keuangan","A","Bertanggung jawab atas ketepatan dan kelengkapan rekonsiliasi."],["Staf Biro Keuangan (pemeriksa)","R","Mencocokkan catatan, saldo, dan bukti."],["Bendahara","R","Menyediakan buku kas, uang tunai, dan mutasi rekening."],["Presiden","I","Menerima hasil rekonsiliasi."],["Inspektur Jenderal","C","Menyaksikan atau memeriksa rekonsiliasi dan menindaklanjuti selisih."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Buku kas.","Mutasi rekening dan uang tunai.","Bukti transaksi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan jadwal: Menetapkan tanggal rekonsiliasi dan pemeriksa.","Kepala Biro","Kalender","Jadwal","Akhir bulan"],["2","Pengumpulan data: Mengumpulkan buku kas, mutasi rekening, dan hitungan kas tunai.","Bendahara","Buku kas, mutasi","Data rekonsiliasi","2 hari kerja"],["3","Pencocokan: Mencocokkan saldo dan transaksi dengan bukti.","Pemeriksa","Data rekonsiliasi","Daftar selisih","2 hari kerja"],["4","Penjelasan selisih: Menelusuri dan menjelaskan setiap selisih.","Bendahara; pemeriksa","Daftar selisih","Penjelasan selisih","3 hari kerja"],["5","Penyesuaian: Memperbaiki pencatatan yang keliru dengan persetujuan Kepala Biro.","Bendahara","Penjelasan","Buku kas dikoreksi","1 hari kerja"],["6","Pelaporan: Menyusun Berita Acara Rekonsiliasi dan melaporkannya.","Kepala Biro","Hasil","Berita Acara Rekonsiliasi","2 hari kerja"],["7","Pengarsipan: Menyimpan berita acara.","Staf","Berita Acara","Arsip","2 hari kerja"],["8","Pemeriksaan mendadak: Menyelenggarakan hitung kas mendadak bila diminta Presiden atau Irjen.","Kepala Biro; Irjen","Perintah","Catatan hitung kas","Sesuai permintaan"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Rekonsiliasi bulanan selesai paling lama 10 hari kerja setelah akhir bulan. Hasil akhir: Berita Acara Rekonsiliasi."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Selisih tidak dapat dijelaskan: dilaporkan kepada Presiden dan Irjen dalam 2 hari kerja dan diproses SOP-RSK-007.","Mutasi rekening tidak tersedia: Kepala Biro meminta kepada bank dan mencatat kendala.","Kas tunai melebihi batas simpan: disetor ke rekening resmi.","Kewajiban dan utang yang ditemukan: dicatat sesuai SOP-KEU-019."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% bulan memiliki Berita Acara Rekonsiliasi.","Seluruh selisih dijelaskan dalam 5 hari kerja.","Tidak ada selisih tak terjelaskan pada akhir periode."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Berita Acara Rekonsiliasi.","Daftar selisih dan penjelasan.","Catatan hitung kas mendadak, bila ada. Seluruh dokumen disimpan pada repositori resmi BEM (folder Keuangan) oleh Kepala Biro Keuangan bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Kepala Biro memastikan rekonsiliasi bulanan; Irjen memeriksa pada evaluasi berkala dan menjadikannya bahan serah terima keuangan (SOP-TRN-004)."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Jadwal → Kumpul data → Pencocokan → Penjelasan selisih → Penyesuaian → Berita Acara → Arsip → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Berita Acara Rekonsiliasi","Periode; saldo buku; saldo nyata; selisih; penjelasan; pemeriksa; tanda tangan."],["Lembar Hitung Kas","Nominal; jumlah lembar; total; tanggal; saksi."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Rekonsiliasi dilakukan oleh pihak selain pemegang kas.","☐ Ya ☐ Tidak"],["2","Setiap selisih dijelaskan.","☐ Ya ☐ Tidak"],["3","Buku kas dikoreksi dengan persetujuan.","☐ Ya ☐ Tidak"],["4","Berita acara diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-LOG-001","g":"SOP Khusus Unit: Logistik dan Aset (BPH)","t":"Inventaris","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[890,893],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur mendata, memberi kode, dan memeriksa inventaris BEM agar seluruh aset tercatat lengkap, mudah dilacak, dan dapat diserahterimakan."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh aset milik BEM atau yang dipinjamkan kepada BEM, di bawah pengelolaan BPH dan Eksekutif. SOP ini merinci SOP-AST-001, SOP-AST-002, SOP-AST-010, dan SOP-AST-011."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf i (fasilitas dan dukungan kampus untuk program kerja).","AD Pasal 15 ayat (1) huruf d (hasil pengembangan aset organisasi yang dikelola produktif).","ART Pasal 11 huruf k (larangan menggunakan fasilitas atau nama organisasi untuk kepentingan pribadi).","SOP-AST-001 sampai SOP-AST-012."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["BPH","Badan Pengurus Harian BEM; dalam SOP ini diasumsikan Presiden, Wakil Presiden, dan Sekretaris Jenderal."],["Kode inventaris","Nomor unik yang menempel pada setiap aset."],["Daftar Inventaris","Catatan nama aset, kode, kondisi, lokasi, dan penanggung jawab."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap aset memiliki kode, kondisi, lokasi, dan satu penanggung jawab.","Aset pinjaman kampus dibedakan dari aset milik BEM.","Inventaris diperiksa setidaknya satu kali per semester.","Penghapusan atau pemindahtanganan aset mengikuti aturan kampus dan persetujuan berwenang (SOP- AST-012).","Aset tidak digunakan untuk kepentingan pribadi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Bertanggung jawab atas kelengkapan dan kebenaran Daftar Inventaris."],["Petugas inventaris (BPH atau Eksekutif)","R","Mendata, memberi kode, dan memperbarui daftar."],["Penanggung jawab aset","R","Menjaga aset dan melapor bila rusak atau hilang."],["Presiden","C","Menyetujui penghapusan aset."],["Kepala Biro Keuangan","C","Mencatat nilai aset yang dibeli dari dana organisasi."],["Inspektur Jenderal","I","Memeriksa inventaris pada pengawasan berkala."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Aset yang diterima atau dibeli.","Daftar Inventaris sebelumnya.","Bukti pembelian atau serah terima."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pendataan awal: Menghitung dan mencatat seluruh aset yang ada.","Petugas inventaris","Aset, daftar sebelumnya","Daftar Inventaris awal","10 hari kerja setelah kabinet dilantik"],["2","Pemberian kode: Memberi kode dan menempelkan label.","Petugas inventaris","Daftar awal","Aset berkode","3 hari kerja"],["3","Penetapan penanggung jawab: Menetapkan penanggung jawab dan lokasi tiap aset.","Sekjen","Aset berkode","Daftar penanggung jawab","2 hari kerja"],["4","Pencatatan aset baru: Mencatat aset baru dengan bukti perolehan.","Petugas inventaris","Aset baru, bukti","Daftar terbarui","2 hari kerja"],["5","Pemeriksaan berkala: Mencocokkan daftar dengan kondisi nyata.","Petugas; Sekjen","Daftar Inventaris","Berita Acara Pemeriksaan Inventaris","Per semester"],["6","Penanganan selisih: Menelusuri aset tidak ditemukan atau berlebih (SOP-LOG-004).","Sekjen","Berita Acara","Penjelasan selisih","5 hari kerja"],["7","Penghapusan aset: Mengajukan penghapusan aset rusak berat atau tidak dipakai kepada pihak berwenang.","Sekjen; Presiden","Daftar, alasan","Persetujuan penghapusan","Sesuai kebutuhan"],["8","Serah terima: Menyerahkan inventaris kepada kabinet berikutnya (SOP-TRN-005).","Sekjen","Daftar Inventaris","Berita acara serah terima","Akhir periode"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Pendataan awal selesai paling lama 15 hari kerja setelah kabinet dilantik; pemeriksaan berkala setiap semester. Hasil akhir: Daftar Inventaris terbarui dan berita acara pemeriksaan."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Aset tidak ditemukan: SOP-LOG-004 dan SOP-AST-007.","Dugaan penyalahgunaan aset: SOP-RSK-007.","Aset pinjaman kampus rusak: dilaporkan kepada KAUR ORMAWA melalui Sekjen.","Kekurangan data bukti perolehan: dicatat dan dilengkapi sesuai catatan serah terima."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% aset berkode dan memiliki penanggung jawab.","Pemeriksaan dilakukan setiap semester.","Selisih inventaris terjelaskan dalam 5 hari kerja."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Inventaris.","Berita Acara Pemeriksaan Inventaris.","Berita acara serah terima. Seluruh dokumen disimpan pada repositori resmi BEM (folder Logistik dan Aset) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen memeriksa kemutakhiran daftar setiap semester; Irjen memeriksa pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pendataan → Pemberian kode → Penanggung jawab → Pencatatan aset baru → Pemeriksaan berkala → Penanganan selisih → Serah terima → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Inventaris","Kode; nama aset; jumlah; kondisi; lokasi; penanggung jawab; sumber; tanggal."],["Berita Acara Pemeriksaan Inventaris","Tanggal; pemeriksa; hasil; selisih; tindak lanjut; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Aset berkode dan berpenanggung jawab.","☐ Ya ☐ Tidak"],["2","Daftar sesuai kondisi nyata.","☐ Ya ☐ Tidak"],["3","Selisih telah ditindaklanjuti.","☐ Ya ☐ Tidak"],["4","Berita acara pemeriksaan diarsipkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-LOG-002","g":"SOP Khusus Unit: Logistik dan Aset (BPH)","t":"Penggunaan Ruang Sekretariat","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[894,896],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan tata cara penggunaan, pengamanan, dan perawatan ruang sekretariat agar ruang tertib, bersih, aman, dan adil bagi seluruh pengurus."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Ruang sekretariat dan perabot di dalamnya. Peminjaman ruang oleh pihak luar mengikuti SOP-AST-008. SOP ini merinci SOP-AST-005 dan SOP-AST-009."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf i (fasilitas kampus).","ART Pasal 3 huruf d (menjaga nama baik dan ketertiban kampus).","ART Pasal 11 huruf f, h, dan k (larangan zat haram, asusila, dan penggunaan fasilitas untuk kepentingan pribadi).","SOP-AST-005 dan SOP-AST-009."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Jadwal ruang","Daftar penggunaan ruang oleh unit dan kegiatan."],["Penjaga ruang","Pengurus yang bertanggung jawab membuka dan menutup ruang pada waktu tertentu."],["Buku Penggunaan Ruang","Catatan pemakai, waktu, dan kondisi ruang."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Ruang dipakai untuk kegiatan organisasi sesuai syariat dan aturan kampus.","Jadwal ruang disusun adil dan ditempel pada tempat yang mudah dilihat.","Ketentuan adab: menjaga kebersihan, memisahkan tempat bagi lawan jenis sesuai aturan kampus, dan menutup ruang pada waktu salat.","Kunci dipegang penjaga ruang yang ditetapkan; duplikat kunci tercatat.","Dilarang tidur, membawa zat haram, atau menggunakan ruang untuk kepentingan pribadi."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Bertanggung jawab atas jadwal, ketertiban, dan keamanan ruang."],["Penjaga ruang","R","Membuka dan menutup ruang, memeriksa kondisi, dan mengisi buku penggunaan."],["Pengurus pengguna ruang","R","Mematuhi tata tertib dan merapikan ruang setelah dipakai."],["Wakil Presiden","C","Memutuskan perselisihan jadwal antar-unit."],["KAUR ORMAWA","I","Menerima laporan bila ada pelanggaran yang berdampak pada kampus."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Jadwal ruang.","Daftar penjaga ruang.","Buku Penggunaan Ruang."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penetapan tata tertib: Menyusun dan menempelkan tata tertib penggunaan ruang.","Sekjen","Aturan kampus","Tata tertib","5 hari kerja setelah kabinet dilantik"],["2","Penyusunan jadwal: Menyusun jadwal berdasarkan kebutuhan unit dan kalender organisasi.","Sekjen","Kalender","Jadwal ruang","3 hari kerja"],["3","Pemesanan ruang: Unit memesan ruang untuk rapat atau kegiatan di luar jadwal.","Unit pemohon","Jadwal","Konfirmasi pemesanan","2 hari kerja sebelum pemakaian"],["4","Pembukaan ruang: Membuka ruang, memeriksa kondisi, dan mencatat pada buku.","Penjaga ruang","Kunci, buku","Kondisi awal tercatat","Awal pemakaian"],["5","Penggunaan: Menggunakan ruang sesuai tata tertib.","Pengurus pengguna","Tata tertib","Kegiatan tertib","Sesuai jadwal"],["6","Penutupan ruang: Memeriksa kebersihan, perabot, listrik, dan mengunci ruang.","Penjaga ruang","Kondisi ruang","Kondisi akhir tercatat","Akhir pemakaian"],["7","Penanganan kerusakan atau kehilangan: Melaporkan kerusakan atau kehilangan melalui SOP-LOG-004.","Penjaga ruang","Temuan","Laporan","1 hari kerja"],["8","Evaluasi: Meninjau penggunaan dan tata tertib setiap semester.","Sekjen","Buku Penggunaan Ruang","Catatan evaluasi","Per semester"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Konfirmasi pemesanan ruang paling lama 2 hari kerja sebelum pemakaian; laporan kerusakan paling lama 1 hari kerja. Hasil akhir: jadwal ruang dan Buku Penggunaan Ruang terisi."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Bentrok jadwal: dimusyawarahkan; bila tidak sepakat diputuskan Wakil Presiden.","Pelanggaran tata tertib: ditegur penjaga ruang; yang berulang diproses SOP-SDM-013.","Insiden keamanan atau kebakaran: SOP-RSK-003.","Perbedaan kebijakan ruang dengan kampus: dikonsultasikan kepada KAUR ORMAWA."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% pemakaian tercatat pada Buku Penggunaan Ruang.","Tidak ada bentrok jadwal yang tidak terselesaikan.","Ruang tertutup rapi setelah pemakaian pada minimal 95% hari."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Tata tertib ruang.","Jadwal ruang.","Buku Penggunaan Ruang. Seluruh dokumen disimpan pada repositori resmi BEM (folder Logistik dan Aset) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen memeriksa Buku Penggunaan Ruang setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Tata tertib → Jadwal → Pemesanan → Buka ruang → Penggunaan → Tutup ruang → Evaluasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Jadwal Ruang Sekretariat","Hari; waktu; unit atau kegiatan; penanggung jawab; keterangan."],["Buku Penggunaan Ruang","Tanggal; pemakai; waktu; kondisi awal dan akhir; paraf."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Tata tertib terpasang.","☐ Ya ☐ Tidak"],["2","Kondisi awal dan akhir ruang dicatat.","☐ Ya ☐ Tidak"],["3","Ruang dikunci setelah pemakaian.","☐ Ya ☐ Tidak"],["4","Kerusakan dilaporkan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-LOG-003","g":"SOP Khusus Unit: Logistik dan Aset (BPH)","t":"Logistik dan Peminjaman Aset","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[897,899],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengelolaan logistik kegiatan dan peminjaman aset agar kebutuhan unit terpenuhi, aset tidak hilang, dan pengembalian tepat waktu."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Perlengkapan dan barang milik BEM yang dipinjam unit internal dan, dengan persetujuan, pihak eksternal. SOP ini merinci SOP-AST-003, SOP-AST-004, dan SOP-AST-008, serta berkaitan dengan SOP-PRO-011 dan SOP-PRO-012."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf i (fasilitas kampus).","ART Pasal 11 huruf k (larangan memakai fasilitas untuk kepentingan pribadi).","ART Pasal 2 huruf e (kerja sama dengan pihak eksternal dengan persetujuan Ketua STDIIS).","SOP-AST-003, SOP-AST-004, dan SOP-AST-008."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Peminjaman","Penggunaan aset BEM sementara oleh pengurus atau pihak lain."],["Formulir Peminjaman","Dokumen resmi peminjaman: peminjam, aset, tujuan, dan jangka waktu."],["Berita Acara Serah Terima","Catatan kondisi aset saat dipinjam dan dikembalikan."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Aset hanya dipinjamkan untuk kegiatan yang sah.","Peminjam bertanggung jawab atas kerusakan atau kehilangan aset selama peminjaman.","Peminjaman kepada pihak eksternal memerlukan persetujuan Presiden dan, bila perlu, KAUR ORMAWA.","Kondisi aset diperiksa saat dipinjam dan saat dikembalikan.","Pemakaian pribadi tanpa kaitan organisasi tidak diperbolehkan."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Bertanggung jawab atas persetujuan dan pengendalian peminjaman."],["Petugas logistik","R","Memeriksa, menyerahkan, dan menerima kembali aset."],["Peminjam","R","Menggunakan aset dengan hati-hati dan mengembalikan tepat waktu."],["Presiden","C","Menyetujui peminjaman eksternal."],["KAUR ORMAWA","I","Menerima informasi bila aset kampus terlibat."],["Inspektur Jenderal","I","Memeriksa catatan pada pengawasan."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Formulir Peminjaman.","Daftar Inventaris.","Jadwal kegiatan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengajuan: Peminjam mengisi Formulir Peminjaman.","Peminjam","Kebutuhan","Formulir terkirim","2 hari kerja sebelum dipakai"],["2","Pemeriksaan ketersediaan: Memeriksa ketersediaan dan bentrok jadwal.","Petugas logistik","Formulir, inventaris","Tersedia atau tidak","1 hari kerja"],["3","Persetujuan: Menyetujui peminjaman; eksternal diteruskan kepada Presiden.","Sekjen; Presiden","Hasil pemeriksaan","Persetujuan","1 hari kerja"],["4","Serah terima: Menyerahkan aset dan mencatat kondisi pada berita acara.","Petugas logistik","Persetujuan","Berita Acara Serah Terima","Hari pemakaian"],["5","Penggunaan: Menggunakan aset sesuai tujuan.","Peminjam","Aset","Kegiatan berjalan","Sesuai jangka waktu"],["6","Pengembalian: Mengembalikan aset dan memeriksa kondisinya.","Peminjam; petugas","Aset","Aset kembali","Sesuai tenggat"],["7","Penanganan kerusakan atau kehilangan: Mencatat dan menindaklanjuti sesuai SOP-LOG-004.","Sekjen","Temuan pengembalian","Keputusan penggantian","3 hari kerja"],["8","Penutupan dan pencatatan: Menutup formulir dan memperbarui Daftar Inventaris.","Petugas logistik","Aset kembali","Peminjaman ditutup","1 hari kerja"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Persetujuan paling lama 2 hari kerja setelah pengajuan; pengembalian sesuai tenggat pada formulir. Hasil akhir: Formulir dan Berita Acara Serah Terima lengkap."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Pengembalian terlambat: diingatkan; keterlambatan lebih dari 3 hari kerja dilaporkan kepada Wakil Presiden.","Kerusakan atau kehilangan: SOP-LOG-004.","Peminjam eksternal tidak mengembalikan aset: dilaporkan kepada Presiden dan KAUR ORMAWA.","Dua peminjam berebut aset: diputuskan Sekjen berdasarkan prioritas kegiatan."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% peminjaman memiliki formulir dan berita acara.","Minimal 95% aset dikembalikan tepat waktu.","Tidak ada aset hilang tanpa penanganan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Formulir Peminjaman.","Berita Acara Serah Terima.","Catatan peminjaman terbarui. Seluruh dokumen disimpan pada repositori resmi BEM (folder Logistik dan Aset) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen memeriksa catatan peminjaman setiap bulan; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Pengajuan → Cek ketersediaan → Persetujuan → Serah terima → Penggunaan → Pengembalian → Penutupan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Formulir Peminjaman Aset","Peminjam; unit; aset; jumlah; tujuan; tanggal pinjam dan kembali; persetujuan."],["Berita Acara Serah Terima Aset","Aset; kode; kondisi saat dipinjam; kondisi saat dikembalikan; tanda tangan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Formulir disetujui sebelum aset diserahkan.","☐ Ya ☐ Tidak"],["2","Kondisi aset dicatat saat serah dan kembali.","☐ Ya ☐ Tidak"],["3","Pengembalian tepat waktu.","☐ Ya ☐ Tidak"],["4","Daftar Inventaris diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-LOG-004","g":"SOP Khusus Unit: Logistik dan Aset (BPH)","t":"Pemeliharaan Aset","o":"Sekretaris Jenderal","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Sekretaris Jenderal","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[900,902],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur perawatan, pemeriksaan, dan penanganan aset rusak atau hilang agar aset tetap layak pakai dan kerugian organisasi minimal."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Seluruh aset yang tercatat pada Daftar Inventaris. SOP ini merinci SOP-AST-006 dan SOP-AST-007."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 huruf e (pengelolaan yang amanah dan akuntabel).","ART Pasal 11 huruf i dan k (larangan penyelewengan dan penggunaan fasilitas untuk kepentingan pribadi).","AD Pasal 15 ayat (1) huruf d (pengembangan aset yang dikelola produktif).","SOP-AST-006 dan SOP-AST-007."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Pemeliharaan","Perawatan rutin dan perbaikan agar aset layak pakai."],["Laporan Kerusakan atau Kehilangan","Laporan tertulis peristiwa kerusakan atau kehilangan aset."],["Jadwal perawatan","Rencana pemeriksaan dan perawatan aset secara berkala."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap aset memiliki jadwal perawatan sesuai jenisnya.","Kerusakan atau kehilangan dilaporkan dalam 1 hari kerja sejak diketahui.","Biaya perbaikan atau penggantian mengikuti prosedur keuangan (SOP-BKU-002 dan SOP-BKU-003).","Penggantian oleh peminjam atau penanggung jawab ditetapkan setelah klarifikasi.","Aset rusak berat dicatat untuk penghapusan (SOP-LOG-001)."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Sekretaris Jenderal","A","Bertanggung jawab atas pemeliharaan dan keputusan penanganan kerusakan atau kehilangan."],["Petugas logistik","R","Melaksanakan pemeriksaan dan perawatan serta menyusun laporan."],["Penanggung jawab aset","R","Merawat aset dan melapor kerusakan atau kehilangan."],["Presiden","C","Menyetujui penggantian biaya yang signifikan."],["Kepala Biro Keuangan","C","Menyediakan dana perbaikan sesuai prosedur."],["Inspektur Jenderal","I","Menerima laporan kerusakan atau kehilangan berat."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["Daftar Inventaris.","Jadwal perawatan.","Laporan kerusakan atau kehilangan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan jadwal perawatan: Menyusun jadwal pemeriksaan dan perawatan.","Petugas logistik","Daftar Inventaris","Jadwal perawatan","5 hari kerja setelah inventaris"],["2","Pemeriksaan rutin: Memeriksa kondisi aset dan membersihkannya.","Petugas; penanggung jawab","Jadwal","Catatan kondisi","Sesuai jadwal"],["3","Pelaporan kerusakan atau kehilangan: Membuat Laporan Kerusakan atau Kehilangan.","Penanggung jawab","Kejadian","Laporan","1 hari kerja"],["4","Klarifikasi: Meminta keterangan penanggung jawab atau peminjam.","Sekjen","Laporan","Catatan klarifikasi","3 hari kerja"],["5","Penentuan tindakan: Menentukan perbaikan, penggantian, atau penghapusan.","Sekjen; Presiden","Klarifikasi","Keputusan tindakan","3 hari kerja"],["6","Pelaksanaan tindakan: Melakukan perbaikan atau penggantian dengan dana yang disetujui.","Petugas logistik","Keputusan, dana","Aset dipulihkan atau diganti","Sesuai keputusan"],["7","Pencatatan: Memperbarui Daftar Inventaris dan arsip laporan.","Petugas logistik","Hasil tindakan","Daftar terbarui","2 hari kerja"],["8","Pelaporan: Melaporkan ringkasan kerusakan dan kehilangan pada rapat evaluasi.","Sekjen","Laporan","Ringkasan","Per semester"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Laporan kerusakan atau kehilangan dibuat paling lama 1 hari kerja; keputusan tindakan paling lama 6 hari kerja setelah laporan. Hasil akhir: aset dipulihkan atau diganti dan Daftar Inventaris terbarui."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Kehilangan aset bernilai tinggi atau dugaan pencurian: dilaporkan kepada Presiden dan KAUR ORMAWA dan diproses SOP-RSK-012.","Dugaan kelalaian atau penyalahgunaan: SOP-RSK-007 dan SOP-SDM-013.","Biaya perbaikan melebihi anggaran: SOP-KEU-014.","Aset pinjaman kampus rusak: dilaporkan kepada KAUR ORMAWA."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% aset memiliki jadwal perawatan.","Laporan kerusakan atau kehilangan dibuat dalam 1 hari kerja pada minimal 95% kasus.","Aset layak pakai pada minimal 90% pemeriksaan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Jadwal perawatan.","Laporan Kerusakan atau Kehilangan.","Keputusan tindakan dan Daftar Inventaris terbarui. Seluruh dokumen disimpan pada repositori resmi BEM (folder Logistik dan Aset) oleh Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Sekjen memeriksa catatan perawatan setiap semester; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Jadwal perawatan → Pemeriksaan rutin → Laporan kerusakan → Klarifikasi → Keputusan tindakan → Perbaikan atau ganti → Pencatatan → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Jadwal Perawatan Aset","Aset; kode; kegiatan perawatan; frekuensi; penanggung jawab; tanggal."],["Laporan Kerusakan atau Kehilangan","Aset; kode; kejadian; tanggal; penyebab; saksi; usulan tindakan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Jadwal perawatan tersedia.","☐ Ya ☐ Tidak"],["2","Kerusakan dilaporkan dalam 1 hari kerja.","☐ Ya ☐ Tidak"],["3","Keputusan tindakan tercatat.","☐ Ya ☐ Tidak"],["4","Daftar Inventaris diperbarui.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ACR-001","g":"SOP Khusus Unit: Tim Acara","t":"Rundown Acara","o":"Koordinator Tim Acara","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Koordinator Tim Acara","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[903,906],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur menyusun, menyetujui, mengendalikan, dan mengevaluasi rundown acara agar alur acara jelas, tepat waktu, memperhatikan waktu salat, dan dipahami seluruh panitia."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Rundown seluruh acara resmi BEM. SOP ini merinci SOP-PRO-014 dan SOP-PRO-015 pada sisi alur acara dan tidak mengatur pembentukan panitia (SOP-PRO-006) maupun pembiayaan (SOP-BKU)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf c (usulan panitia kegiatan dan tim kerja internal).","ART Pasal 9 ayat (3) huruf c (penetapan timeline kegiatan).","AD Pasal 5 ayat (3) (kegiatan ilmiah, dakwah, sosial, dan pengabdian sesuai manhaj Ahlusunah wal Jamaah).","SOP-PRO-007, SOP-PRO-014, dan SOP-PRO-015."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rundown","Susunan acara berurutan lengkap dengan waktu, penanggung jawab, dan kebutuhan teknis."],["Run-through","Gladi atau simulasi alur acara sebelum hari pelaksanaan."],["Master of Ceremony (MC)","Pemandu acara yang membacakan rundown di hadapan peserta."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Rundown disusun berdasarkan TOR kegiatan yang telah disetujui.","Waktu salat dan adab acara menjadi pertimbangan utama pembagian waktu.","Setiap mata acara memiliki durasi dan penanggung jawab.","Perubahan rundown pada hari pelaksanaan diputuskan ketua pelaksana dan diberitahukan kepada Tim Acara.","Rundown final dibagikan kepada seluruh panitia dan pengisi acara."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Koordinator Tim Acara","A","Bertanggung jawab atas kualitas, ketepatan waktu, dan keselarasan rundown."],["Tim Acara","R","Menyusun rundown dan melakukan run-through."],["Ketua pelaksana","C","Menyetujui rundown dan perubahan pada hari pelaksanaan."],["Penanggung jawab seksi","C","Memberi masukan kebutuhan seksinya."],["MC dan pengisi acara","I","Menerima rundown dan menjalankannya."],["Sekretaris Jenderal","I","Memasukkan jadwal ke kalender organisasi."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["TOR kegiatan.","Jadwal tempat dan waktu salat.","Daftar pengisi acara."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Pengumpulan kebutuhan: Mengumpulkan tujuan, durasi, pengisi acara, dan kebutuhan teknis.","Tim Acara","TOR","Daftar kebutuhan","2 hari kerja"],["2","Penyusunan draf rundown: Menyusun urutan acara, durasi, dan penanggung jawab dengan memperhatikan waktu salat.","Tim Acara","Daftar kebutuhan","Draf rundown","3 hari kerja"],["3","Telaah: Memeriksa draf bersama seksi terkait.","Koordinator; seksi","Draf rundown","Masukan","2 hari kerja"],["4","Persetujuan: Ketua pelaksana menyetujui rundown.","Ketua pelaksana","Draf telaah","Rundown disetujui","1 hari kerja"],["5","Pembagian rundown: Membagikan rundown final kepada panitia, MC, dan pengisi acara.","Tim Acara","Rundown disetujui","Rundown tersebar","Minimal 3 hari kerja sebelum acara"],["6","Run-through: Melakukan gladi alur acara.","Tim Acara; panitia","Rundown final","Catatan gladi","1 hari sebelum acara"],["7","Pengendalian saat acara: Memantau waktu per mata acara dan menyesuaikan dengan persetujuan ketua pelaksana.","Koordinator","Rundown final","Acara berjalan sesuai waktu","Saat acara"],["8","Evaluasi: Mencatat ketepatan waktu dan perbaikan.","Tim Acara","Catatan acara","Evaluasi rundown","3 hari kerja setelah acara"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Rundown final dibagikan paling lambat 3 hari kerja sebelum acara. Hasil akhir: rundown final, catatan gladi, dan evaluasi rundown."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Acara melebihi waktu: Koordinator dan ketua pelaksana memutuskan pemangkasan mata acara tanpa mengorbankan waktu salat.","Pengisi acara berhalangan: Tim Acara menyiapkan pengganti atau penyesuaian rundown.","Perubahan jadwal besar: SOP-PRO-015.","Insiden saat acara: SOP-PRO-017 dan SOP-RSK-003."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% acara memiliki rundown yang disetujui.","Minimal 90% mata acara berjalan sesuai durasi.","Rundown dibagikan minimal 3 hari kerja sebelum acara pada minimal 90% kegiatan."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Rundown final.","Catatan gladi.","Evaluasi rundown. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tim Acara) oleh Koordinator Tim Acara bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Koordinator memeriksa kesesuaian rundown dan realisasi setelah setiap acara; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Kumpul kebutuhan → Draf rundown → Telaah → Persetujuan → Pembagian → Run- through → Pengendalian saat acara → Evaluasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Templat Rundown Acara","Waktu; mata acara; durasi; penanggung jawab; kebutuhan teknis; keterangan."],["Catatan Gladi dan Evaluasi Rundown","Mata acara; waktu rencana dan realisasi; kendala; perbaikan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Rundown mengikuti TOR dan waktu salat.","☐ Ya ☐ Tidak"],["2","Setiap mata acara memiliki penanggung jawab.","☐ Ya ☐ Tidak"],["3","Rundown disetujui ketua pelaksana.","☐ Ya ☐ Tidak"],["4","Gladi telah dilakukan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ACR-002","g":"SOP Khusus Unit: Tim Acara","t":"Koordinasi Panitia","o":"Koordinator Tim Acara","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Koordinator Tim Acara","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[907,909],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur koordinasi antara Tim Acara, ketua pelaksana, dan seksi panitia agar peran jelas, informasi mengalir tertib, dan masalah cepat teratasi sebelum dan selama acara."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Koordinasi seluruh panitia kegiatan BEM. SOP ini tidak mengatur pembentukan panitia (SOP-PRO-006) dan koordinasi lintas kementerian di luar kepanitiaan (SOP-GOV-004)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 4 huruf c (usulan panitia dan tim kerja internal).","ART Pasal 10 (Rapat Koordinasi).","ART Pasal 9 ayat (3) huruf b (pembagian tugas dan tanggung jawab).","SOP-GOV-004 dan SOP-PRO-006."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Rapat panitia","Pertemuan koordinasi rutin panitia kegiatan."],["Papan Koordinasi","Daftar tugas, penanggung jawab, tenggat, dan status seluruh seksi."],["Briefing akhir","Pengarahan terakhir kepada panitia sebelum acara dimulai."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Setiap seksi memiliki koordinator dan satu garis pelaporan.","Rapat panitia dicatat dengan notulensi (SOP-SEK-003).","Instruksi disampaikan melalui kanal resmi (SOP-KOM-001 dan SOP-KOM-003).","Kehadiran panitia pada gladi dan briefing akhir wajib.","Masalah yang tidak terselesaikan seksi dieskalasikan kepada ketua pelaksana."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Koordinator Tim Acara","A","Bertanggung jawab atas kelancaran koordinasi teknis acara."],["Ketua pelaksana","R","Memimpin panitia dan memutuskan hal strategis kegiatan."],["Koordinator seksi","R","Melaksanakan tugas seksi dan melaporkan progres."],["Tim Acara","R","Mengelola Papan Koordinasi dan jadwal rapat."],["Sekretaris Jenderal","I","Menerima notulensi untuk tindak lanjut."],["Wakil Presiden","C","Menengahi bila terjadi perselisihan lintas unit."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["TOR dan struktur panitia.","Rundown acara.","Papan Koordinasi."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan Papan Koordinasi: Menyusun tugas, penanggung jawab, dan tenggat tiap seksi.","Tim Acara","Struktur panitia, TOR","Papan Koordinasi","2 hari kerja setelah panitia dibentuk"],["2","Penjadwalan rapat: Menjadwalkan rapat panitia rutin dan briefing.","Tim Acara","Kalender","Jadwal rapat","1 hari kerja"],["3","Rapat panitia: Membahas progres, kendala, dan keputusan.","Ketua pelaksana; seksi","Papan Koordinasi","Notulensi","Mingguan"],["4","Pelaporan progres: Setiap seksi melaporkan progres melalui format resmi.","Koordinator seksi","Pekerjaan seksi","Laporan progres","Mingguan"],["5","Penanganan hambatan: Meneruskan hambatan yang tidak selesai kepada ketua pelaksana.","Koordinator","Laporan progres","Keputusan penanganan","2 hari kerja"],["6","Gladi dan briefing akhir: Menyelenggarakan gladi dan briefing sebelum acara.","Koordinator; ketua pelaksana","Rundown final","Panitia siap","1 hari sebelum acara"],["7","Koordinasi hari pelaksanaan: Mengoordinasikan seluruh seksi melalui saluran komunikasi acara.","Koordinator","Rundown","Acara terkendali","Saat acara"],["8","Evaluasi panitia: Mengevaluasi koordinasi dan peran.","Tim Acara","Catatan acara","Evaluasi koordinasi","3 hari kerja setelah acara"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Papan Koordinasi tersedia paling lama 2 hari kerja setelah panitia dibentuk; hambatan ditindaklanjuti paling lama 2 hari kerja. Hasil akhir: Papan Koordinasi, notulensi rapat, dan evaluasi koordinasi."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Seksi tidak melapor: diingatkan, lalu dilaporkan kepada ketua pelaksana.","Perselisihan antar-seksi: diputuskan ketua pelaksana; antar-unit BEM melalui SOP-GOV-004.","Panitia tidak hadir tanpa uzur: dicatat dan ditangani SOP-SDM-006 dan SOP-SDM-011.","Keadaan darurat: SOP-PRO-017."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["Minimal 90% rapat panitia bernotulensi.","Minimal 90% laporan progres diterima tepat waktu.","Hambatan ditindaklanjuti dalam 2 hari kerja pada minimal 90% kasus."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Papan Koordinasi.","Notulensi rapat panitia.","Laporan progres dan evaluasi koordinasi. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tim Acara) oleh Koordinator Tim Acara bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Koordinator memeriksa Papan Koordinasi setiap minggu; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Papan Koordinasi → Jadwal rapat → Rapat panitia → Laporan progres → Penanganan hambatan → Gladi dan briefing → Koordinasi hari H → Evaluasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Papan Koordinasi Panitia","Seksi; tugas; penanggung jawab; tenggat; status; kendala."],["Laporan Progres Seksi","Seksi; periode; capaian; kendala; rencana; kebutuhan bantuan."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Setiap seksi memiliki koordinator dan tenggat.","☐ Ya ☐ Tidak"],["2","Rapat panitia bernotulensi.","☐ Ya ☐ Tidak"],["3","Gladi dan briefing akhir dilakukan.","☐ Ya ☐ Tidak"],["4","Hambatan tercatat dan ditindaklanjuti.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ACR-003","g":"SOP Khusus Unit: Tim Acara","t":"Protokoler Acara","o":"Koordinator Tim Acara","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Koordinator Tim Acara","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[910,913],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan tata cara protokoler acara BEM, mulai dari penerimaan tamu, tata urutan, tempat duduk, hingga etika penyambutan, agar acara berlangsung santun, sesuai adab Islam, dan menghormati tamu."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Acara resmi BEM di dalam maupun luar kampus. SOP ini merinci SOP-HKE-009 dan SOP-HKE-010 pada sisi penyelenggaraan acara."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 3 huruf c dan d (menjunjung nilai Islam dan menjaga nama baik STDIIS).","ART Pasal 3 huruf a dan b (prinsip Ahlus Sunnah wal Jama'ah dan ukhuwah Islamiyah).","ART Pasal 11 huruf a, b, dan h (larangan SARA, penistaan agama, dan asusila atau pelecehan).","SOP-HKE-009 dan SOP-HKE-010."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Protokoler","Aturan tata urutan dan penghormatan pada acara resmi."],["Daftar Tamu","Daftar tamu undangan beserta kedudukan dan penerimaannya."],["Petugas penerima tamu","Panitia yang menyambut dan mengarahkan tamu."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Penerimaan tamu dilakukan dengan adab: salam, sikap santun, dan penghormatan sesuai kedudukan.","Tata tempat dan interaksi memperhatikan aturan syariat dan kampus, termasuk pemisahan lawan jenis bila ditetapkan.","Tata urutan sambutan ditetapkan sebelum acara dan dikonfirmasi kepada tamu kehormatan.","Waktu salat dan fasilitas ibadah disediakan bagi tamu.","Pengambilan dokumentasi tamu mengikuti SOP-KOM-011."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Koordinator Tim Acara","A","Bertanggung jawab atas tata protokoler dan penerimaan tamu."],["Petugas protokoler","R","Menerima, mengarahkan, dan mendampingi tamu."],["Ketua pelaksana","C","Menyetujui Daftar Tamu dan tata urutan."],["Presiden atau Wakil Presiden","C","Menjadi perwakilan BEM bagi tamu pimpinan (ART Pasal 4 huruf e)."],["Sekretaris Jenderal","R","Menyiapkan surat undangan dan balasan."],["KAUR ORMAWA atau pihak kampus","I","Diberi tahu bila acara menghadirkan tamu dari luar."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["TOR dan rundown acara.","Daftar Tamu.","Surat undangan."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan Daftar Tamu: Menyusun daftar tamu, kedudukan, dan kebutuhan khusus.","Tim Acara","TOR","Daftar Tamu","3 hari kerja"],["2","Pengiriman undangan: Mengirim undangan melalui kanal resmi (SOP-HKE-001).","Sekjen","Daftar Tamu","Undangan terkirim","Minimal 7 hari kerja sebelum acara"],["3","Konfirmasi kehadiran: Mengonfirmasi kehadiran dan kebutuhan tamu.","Petugas protokoler","Undangan","Daftar hadir sementara","3 hari kerja sebelum acara"],["4","Penyusunan tata urutan dan tempat: Menetapkan tata urutan sambutan, tempat duduk, dan jalur masuk.","Tim Acara","Daftar hadir sementara","Tata urutan dan denah","2 hari kerja"],["5","Briefing petugas: Memberi arahan adab dan alur penyambutan kepada petugas.","Koordinator","Tata urutan","Petugas siap","1 hari sebelum acara"],["6","Penyambutan: Menyambut dan mengarahkan tamu sesuai tata urutan.","Petugas protokoler","Daftar Tamu, denah","Tamu terlayani","Saat acara"],["7","Pendampingan dan pelepasan: Mendampingi tamu hingga selesai dan melepas dengan santun.","Petugas protokoler","Rundown","Tamu terlayani","Saat acara"],["8","Ucapan terima kasih dan evaluasi: Mengirim ucapan terima kasih dan mencatat masukan tamu.","Sekjen; Tim Acara","Daftar hadir","Surat terima kasih; evaluasi protokoler","5 hari kerja setelah acara"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Undangan dikirim paling lambat 7 hari kerja sebelum acara; ucapan terima kasih dikirim paling lama 5 hari kerja setelah acara. Hasil akhir: Daftar Tamu, tata urutan, denah, dan evaluasi protokoler."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Tamu hadir tanpa konfirmasi atau di luar daftar: diterima dan ditempatkan oleh ketua pelaksana.","Tamu pimpinan kampus: didampingi Presiden atau Wakil Presiden.","Perilaku tamu atau peserta yang melanggar adab atau aturan: ditegur santun oleh ketua pelaksana; yang serius SOP-RSK-004.","Insiden saat penyambutan: SOP-PRO-017."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% acara resmi memiliki Daftar Tamu dan tata urutan.","Undangan terkirim minimal 7 hari kerja sebelum acara pada minimal 90% acara.","Tidak ada keluhan adab dari tamu yang tidak ditindaklanjuti."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Tamu.","Tata urutan dan denah.","Surat terima kasih.","Evaluasi protokoler. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tim Acara) oleh Koordinator Tim Acara bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Koordinator memeriksa kelengkapan protokoler setelah setiap acara; Irjen menilai pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Daftar Tamu → Undangan → Konfirmasi → Tata urutan dan denah → Briefing petugas → Penyambutan → Pendampingan → Evaluasi → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Tamu Undangan","Nama; jabatan; instansi; kontak; kehadiran; kebutuhan khusus; petugas pendamping."],["Tata Urutan Acara dan Denah","Urutan sambutan; tempat duduk; jalur masuk; petugas."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Daftar Tamu dan tata urutan disetujui.","☐ Ya ☐ Tidak"],["2","Undangan dan konfirmasi dilakukan.","☐ Ya ☐ Tidak"],["3","Petugas telah dibriefing.","☐ Ya ☐ Tidak"],["4","Fasilitas ibadah disediakan.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]},{"c":"SOP-ACR-004","g":"SOP Khusus Unit: Tim Acara","t":"Pengendalian Teknis Acara","o":"Koordinator Tim Acara","r":"00","st":"Draf (siap diuji coba)","m":{"Pemilik proses":"Koordinator Tim Acara","Penyusun":"Sekretaris Jenderal 1","Pemeriksa":"Wakil Presiden dan Inspektur Jenderal","Pengesah":"Presiden BEM, sesuai AD/ART dan peraturan kampus","Tanggal berlaku":"Diisi setelah disahkan"},"pg":[914,916],"s":[{"p":"B","n":1,"t":"Tujuan","c":[{"p":"Menetapkan prosedur pengendalian teknis acara, yaitu tempat, perangkat suara, tampilan, listrik, dan peralatan pendukung, agar acara berjalan lancar dan masalah teknis cepat tertangani."}]},{"p":"B","n":2,"t":"Ruang lingkup","c":[{"p":"Aspek teknis acara BEM. SOP ini merinci SOP-PRO-011, SOP-PRO-015, dan SOP-PRO-016 pada sisi teknis dan tidak mengatur pengadaan barang (SOP-KEU-010 dan SOP-PRO-012)."}]},{"p":"B","n":3,"t":"Dasar hukum dan dokumen acuan","c":[{"ul":["ART Pasal 2 huruf i (fasilitas kampus untuk program kerja).","ART Pasal 3 huruf d (menjaga ketertiban dan nama baik).","ART Pasal 4 huruf c (tim kerja internal).","SOP-PRO-011, SOP-PRO-016, dan SOP-PRO-017."]}]},{"p":"B","n":4,"t":"Definisi istilah","c":[{"tb":{"h":["Istilah","Pengertian"],"r":[["Daftar Periksa Teknis","Daftar kebutuhan dan kesiapan peralatan serta tempat."],["Site check","Pemeriksaan tempat acara sebelum hari pelaksanaan."],["Rencana cadangan","Langkah alternatif bila peralatan atau tempat bermasalah."]]}}]},{"p":"B","n":5,"t":"Ketentuan pokok","c":[{"ul":["Site check dilakukan sebelum acara, termasuk akses, listrik, perangkat suara, dan tempat ibadah.","Peralatan diuji pada gladi (SOP-ACR-001).","Rencana cadangan disiapkan untuk perangkat kritis.","Peralatan yang dipinjam atau milik BEM dicatat dan dikembalikan (SOP-LOG-003).","Keselamatan peserta didahulukan; kelistrikan diperiksa sebelum acara."]}]},{"p":"B","n":6,"t":"Pihak yang terlibat dan tanggung jawab","c":[{"tb":{"h":["Pelaksana","RACI","Tanggung jawab"],"r":[["Koordinator Tim Acara","A","Bertanggung jawab atas kesiapan dan kelancaran teknis acara."],["Petugas teknis","R","Menyiapkan, menguji, mengoperasikan, dan membongkar peralatan."],["Ketua pelaksana","C","Memutuskan perubahan teknis yang berdampak pada acara."],["Petugas logistik BPH","C","Menyediakan dan menerima kembali peralatan."],["Pengelola tempat","I","Memberi akses dan fasilitas tempat."],["Sekretaris Jenderal","I","Menerima laporan teknis."]]}},{"p":"R = Responsible, A = Accountable, C = Consulted, I = Informed."}]},{"p":"B","n":7,"t":"Persyaratan dan dokumen masukan","c":[{"ul":["TOR dan rundown acara.","Daftar Periksa Teknis.","Denah tempat."]}]},{"p":"B","n":8,"t":"Prosedur pelaksanaan","c":[{"tb":{"h":["No.","Tahapan dan tindakan","Pelaksana","Masukan","Hasil","Batas waktu"],"r":[["1","Penyusunan Daftar Periksa Teknis: Menyusun daftar kebutuhan dan penanggung jawab.","Petugas teknis","TOR, rundown","Daftar Periksa Teknis","3 hari kerja"],["2","Site check: Memeriksa tempat dan fasilitas pada lokasi.","Petugas teknis; koordinator","Daftar Periksa","Catatan site check","Minimal 3 hari kerja sebelum acara"],["3","Penyiapan peralatan: Menyiapkan dan menguji peralatan serta rencana cadangan.","Petugas teknis","Catatan site check","Peralatan siap","1 hari sebelum acara"],["4","Gladi teknis: Menguji alur acara bersama panitia.","Koordinator; panitia","Rundown, peralatan","Catatan gladi teknis","1 hari sebelum acara"],["5","Pengoperasian: Mengoperasikan dan memantau peralatan selama acara.","Petugas teknis","Peralatan siap","Acara lancar","Saat acara"],["6","Penanganan gangguan: Menangani gangguan dengan rencana cadangan dan melapor kepada koordinator.","Petugas teknis; koordinator","Gangguan","Gangguan teratasi","Segera"],["7","Pembongkaran dan pengembalian: Membongkar, memeriksa, dan mengembalikan peralatan.","Petugas teknis","Peralatan","Peralatan kembali","Segera setelah acara"],["8","Laporan teknis: Menyusun laporan teknis dan evaluasi.","Koordinator","Catatan acara","Laporan teknis","3 hari kerja setelah acara"]]}}]},{"p":"B","n":9,"t":"Standar waktu dan hasil","c":[{"p":"Site check minimal 3 hari kerja sebelum acara; laporan teknis paling lama 3 hari kerja setelah acara. Hasil akhir: Daftar Periksa Teknis terisi, catatan site check, dan laporan teknis."},{"note":"Catatan: angka waktu, kuorum, dan frekuensi bersifat usulan dan ditetapkan final setelah uji coba."}]},{"p":"B","n":10,"t":"Pengecualian dan eskalasi masalah","c":[{"ul":["Peralatan kritis rusak: rencana cadangan diaktifkan dan dilaporkan kepada ketua pelaksana.","Tempat tidak dapat dipakai: SOP-PRO-015 untuk perubahan tempat atau jadwal.","Gangguan keselamatan (listrik, kebakaran, kerumunan): SOP-PRO-017 dan SOP-RSK-003.","Kehilangan atau kerusakan peralatan pinjaman: SOP-LOG-004."]}]},{"p":"B","n":11,"t":"Indikator keberhasilan","c":[{"ul":["100% acara memiliki site check dan Daftar Periksa Teknis.","Gangguan teknis diatasi dalam waktu yang tidak mengganggu mata acara pokok pada minimal 90% kasus.","Seluruh peralatan kembali lengkap setelah acara."]}]},{"p":"B","n":12,"t":"Dokumen keluaran dan arsip","c":[{"ul":["Daftar Periksa Teknis.","Catatan site check dan gladi teknis.","Laporan teknis. Seluruh dokumen disimpan pada repositori resmi BEM (folder Tim Acara) oleh Koordinator Tim Acara bersama Sekretaris Jenderal sesuai SOP pengarsipan, bukan hanya pada perangkat atau akun pribadi."]}]},{"p":"B","n":13,"t":"Pengendalian dan evaluasi","c":[{"p":"Koordinator memeriksa kelengkapan laporan teknis setelah setiap acara; Irjen menilai kepatuhan pada evaluasi berkala."}]},{"p":"C","n":1,"t":"Diagram alir ringkas","c":[{"flow":"Mulai → Daftar Periksa Teknis → Site check → Penyiapan peralatan → Gladi teknis → Pengoperasian → Penanganan gangguan → Pembongkaran → Laporan teknis → Selesai"}]},{"p":"C","n":2,"t":"Formulir dan templat","c":[{"tb":{"h":["Nama","Isi minimal"],"r":[["Daftar Periksa Teknis Acara","Kebutuhan; jumlah; penanggung jawab; kondisi; rencana cadangan; paraf."],["Laporan Teknis Acara","Acara; tempat; peralatan; gangguan; penanganan; saran; tanggal."]]}}]},{"p":"C","n":3,"t":"Checklist pemeriksaan","c":[{"tb":{"h":["No.","Butir pemeriksaan","Ya / Tidak"],"r":[["1","Site check telah dilakukan.","☐ Ya ☐ Tidak"],["2","Peralatan telah diuji dan rencana cadangan siap.","☐ Ya ☐ Tidak"],["3","Gangguan tercatat dan ditangani.","☐ Ya ☐ Tidak"],["4","Peralatan dikembalikan lengkap.","☐ Ya ☐ Tidak"]]}}]},{"p":"C","n":4,"t":"Daftar distribusi","c":[{"p":"Presiden; Wakil Presiden; Sekretaris Jenderal; Inspektur Jenderal; seluruh Menteri dan Kepala Biro; arsip Biro Kesekretariatan. Salinan diberikan kepada Pembina atau KAUR ORMAWA bila diminta."}]},{"p":"C","n":5,"t":"Riwayat perubahan","c":[{"tb":{"h":["Revisi","Tanggal","Ringkasan perubahan dan alasan","Pengesah"],"r":[["00","Diisi setelah disahkan","Penerbitan awal kabinet Samasta","Presiden BEM"]]}}]}]}];
